const normalizeYesNoValue = (value) => {
  if (value === null || typeof value === 'undefined') return null;
  const normalized = String(value).trim().toLowerCase();
  if (['1', 'true', 'yes', 'y', 'on'].includes(normalized)) return 'yes';
  if (['0', 'false', 'no', 'n', 'off'].includes(normalized)) return 'no';
  return null;
};

const normalizeRecommendationValue = (value) => {
  const normalized = (value || '').toString().trim().toLowerCase();
  if (['recommend', 'fund', 'approve'].includes(normalized)) return 'fund';
  if (['no_recommend', 'do_not_fund', 'reject', 'decline'].includes(normalized)) return 'do_not_fund';
  if (normalized === 'alternative') return 'alternative';
  return null;
};

const normalizeEsdcEligibilityValue = (value) => {
  const normalized = (value || '').toString().trim().toLowerCase().replace(/\s+/g, '_');
  if (normalized === 'crf') return 'crf';
  if (['ei_active_claim', 'ei_active', 'ei_claim'].includes(normalized)) return 'ei_active_claim';
  if (['ei_reach_back', 'ei_reachback'].includes(normalized)) return 'ei_reach_back';
  return null;
};

const parseCurrencyValue = (value) => {
  if (value === null || typeof value === 'undefined' || value === '') return null;
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  const cleaned = String(value).replace(/[^0-9.-]/g, '');
  if (!cleaned) return null;
  const num = Number(cleaned);
  return Number.isFinite(num) ? num : null;
};

const normalizeCurrencyAmountInput = value => {
  if (value === null || typeof value === 'undefined' || value === '') {
    return { empty: true, valid: true, normalized: '', fractionDigits: 0 };
  }
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      return { empty: false, valid: false, normalized: '', fractionDigits: 0 };
    }
    const normalized = String(value);
    const fractionDigits = normalized.includes('.') ? normalized.split('.')[1].length : 0;
    return { empty: false, valid: true, normalized, fractionDigits };
  }
  const compact = String(value)
    .trim()
    .replace(/[$]/g, '')
    .replace(/\s+/g, '');
  if (!compact) {
    return { empty: true, valid: true, normalized: '', fractionDigits: 0 };
  }
  const currencyPattern = /^[+-]?(?:(?:(?:\d{1,3}(?:,\d{3})+)|\d+)(?:\.\d*)?|\.\d+)$/;
  if (!currencyPattern.test(compact)) {
    return { empty: false, valid: false, normalized: '', fractionDigits: 0 };
  }
  const normalized = compact.replace(/,/g, '');
  const fractionDigits = normalized.includes('.') ? normalized.split('.')[1].length : 0;
  return { empty: false, valid: true, normalized, fractionDigits };
};

const parseCurrencyAmountInput = value => {
  const normalized = normalizeCurrencyAmountInput(value);
  if (normalized.empty) return { value: null, error: null };
  if (!normalized.valid) return { value: NaN, error: 'invalid' };
  const numeric = Number(normalized.normalized);
  if (!Number.isFinite(numeric)) return { value: NaN, error: 'invalid' };
  if (normalized.fractionDigits > 2) return { value: numeric, error: 'precision' };
  return { value: Number(numeric.toFixed(2)), error: null };
};

const validateCurrencyAmountInput = (value, { min = 0, max = 999999 } = {}) => {
  const parsed = parseCurrencyAmountInput(value);
  if (parsed.error) return parsed;
  if (parsed.value === null) return parsed;
  if ((min !== null && parsed.value < min) || (max !== null && parsed.value > max)) {
    return { value: parsed.value, error: 'range' };
  }
  return parsed;
};

const formatCurrencyValue = (value) => {
  const num = parseCurrencyValue(value);
  if (num === null) return '';
  return num.toLocaleString('en-CA', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
};

const formatCurrencyField = (value) => {
  if (value === null || typeof value === 'undefined' || value === '') return '';
  const num = parseCurrencyValue(value);
  if (num === null) return normaliseString(value) || '';
  return num.toLocaleString('en-CA', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
};

const sumCurrencyValues = (...values) => {
  let total = 0;
  let hasValue = false;
  for (const value of values) {
    const num = parseCurrencyValue(value);
    if (num === null) continue;
    total += num;
    hasValue = true;
  }
  return hasValue ? total : null;
};

const setTemplateField = ($, field, value) => {
  const selection = $(`[data-field="${field}"]`);
  if (!selection.length) return;
  const hasHtml = value && typeof value === 'object' && Object.prototype.hasOwnProperty.call(value, 'html');
  selection.each((_idx, node) => {
    const el = $(node);
    const tag = (node.tagName || '').toLowerCase();
    if (hasHtml) {
      if (tag === 'input' || tag === 'textarea') {
        el.replaceWith(`<span class="pdf-html-field">${value.html || ''}</span>`);
        return;
      }
      el.html(value.html || '');
      return;
    }
    if (tag === 'input') {
      const inputType = (el.attr('type') || '').toLowerCase();
      if (inputType === 'checkbox') {
        if (value) {
          el.attr('checked', 'checked');
        } else {
          el.removeAttr('checked');
        }
        return;
      }
      if (inputType === 'radio') {
        const optionValue = el.attr('value');
        if (value !== null && typeof value !== 'undefined' && String(optionValue) === String(value)) {
          el.attr('checked', 'checked');
        } else {
          el.removeAttr('checked');
        }
        return;
      }
      el.attr('value', value === null || typeof value === 'undefined' ? '' : String(value));
      return;
    }
    if (tag === 'textarea') {
      el.text(value === null || typeof value === 'undefined' ? '' : String(value));
      return;
    }
    if (tag === 'img') {
      const src = value === null || typeof value === 'undefined' ? '' : String(value);
      if (src) {
        el.attr('src', src);
      } else {
        el.removeAttr('src');
      }
      return;
    }
    el.text(value === null || typeof value === 'undefined' ? '' : String(value));
  });
};

const buildAssessmentPdfHtml = ({ templateHtml, fields }) => {
  const $ = cheerio.load(templateHtml);
  Object.entries(fields).forEach(([field, value]) => {
    setTemplateField($, field, value);
  });
  return $.html();
};

function buildAssessmentVersionLabel({
  versionNumber = null,
  variant = 'submitted',
  previousVersionNumber = null
} = {}) {
  const normalizedVersion = normalisePositiveInteger(versionNumber);
  if (!normalizedVersion) return '';
  if (variant === 'approved') {
    return `v${normalizedVersion} approved`;
  }
  if (variant === 'redline') {
    const priorVersion = normalisePositiveInteger(previousVersionNumber);
    return priorVersion ? `v${normalizedVersion} redline vs v${priorVersion}` : `v${normalizedVersion} redline`;
  }
  return `v${normalizedVersion}`;
}

function buildAssessmentDocumentMetadata({
  label,
  documentType,
  versionNumber = null,
  variant = 'submitted',
  previousVersionNumber = null,
  snapshot = null
} = {}) {
  const metadata = {
    label,
    document_type: documentType,
    assessment_version_number: normalisePositiveInteger(versionNumber) || null,
    assessment_variant: normaliseString(variant) || null,
    assessment_previous_version_number: normalisePositiveInteger(previousVersionNumber) || null,
    assessment_snapshot: snapshot && typeof snapshot === 'object' ? snapshot : null
  };
  return JSON.stringify(metadata);
}

function parseAssessmentDocumentInfo(row) {
  if (!row || typeof row !== 'object') return null;
  const metadata = parseMetadata(row.metadata) || {};
  const documentType =
    normaliseString(row.document_category || metadata.document_type || null) ||
    null;
  const versionNumber = normalisePositiveInteger(metadata.assessment_version_number) || 1;
  const previousVersionNumber = normalisePositiveInteger(metadata.assessment_previous_version_number) || null;
  const variant = normaliseString(metadata.assessment_variant || null) || null;
  const snapshot = metadata.assessment_snapshot && typeof metadata.assessment_snapshot === 'object'
    ? metadata.assessment_snapshot
    : null;
  return {
    id: normalisePositiveInteger(row.id) || null,
    documentType,
    versionNumber,
    previousVersionNumber,
    variant,
    snapshot,
    createdAt: toIsoDateTime(row.created_at) || null,
    label: normaliseString(row.label || metadata.label || null) || null,
    status: normaliseString(row.status || null) || null
  };
}

async function fetchLatestAssessmentDocumentInfo({
  applicationId,
  caseId = null,
  documentTypes = ['case_assessment'],
  connection = pool
} = {}) {
  const categories = Array.isArray(documentTypes)
    ? Array.from(new Set(documentTypes.map(item => normaliseString(item)).filter(Boolean)))
    : [];
  const normalizedApplicationId = normalisePositiveInteger(applicationId);
  const normalizedCaseId = normalisePositiveInteger(caseId);
  if (!categories.length || (!normalizedApplicationId && !normalizedCaseId)) {
    return null;
  }
  const placeholders = categories.map(() => '?').join(',');
  const whereClauses = [`document_category IN (${placeholders})`];
  const params = [...categories];
  if (normalizedApplicationId) {
    whereClauses.push('application_id = ?');
    params.push(normalizedApplicationId);
  } else {
    whereClauses.push('case_id = ?');
    params.push(normalizedCaseId);
  }
  const [rows] = await connection.query(
    `SELECT id, document_category, label, metadata, status, created_at
       FROM iset_document
      WHERE ${whereClauses.join(' AND ')}
      ORDER BY created_at DESC, id DESC`,
    params
  );
  const items = Array.isArray(rows)
    ? rows.map(parseAssessmentDocumentInfo).filter(Boolean)
    : [];
  return items[0] || null;
}

async function storeAssessmentPdfDocument({
  applicationId,
  caseId,
  clientId,
  applicantUserId,
  actorUserId,
  trackingId,
  pdfBuffer,
  documentType = 'case_assessment',
  label = 'Case manager assessment',
  fileNamePrefix = 'case-manager-assessment',
  versionNumber = null,
  variant = 'submitted',
  previousVersionNumber = null,
  snapshot = null,
  archivePreviousActive = true,
  replaceExistingVersion = false,
  connection = pool
}) {
  const runner = connection || pool;
  const normalizedApplicationId = normalisePositiveInteger(applicationId);
  const normalizedCaseId = normalisePositiveInteger(caseId);
  if ((!normalizedApplicationId && !normalizedCaseId) || !pdfBuffer) return null;
  const normalizedVersionNumber = normalisePositiveInteger(versionNumber);
  const versionSuffix = normalizedVersionNumber ? `-v${normalizedVersionNumber}` : '';
  const documentReference = normaliseString(trackingId) || normalizedApplicationId || normalizedCaseId;
  const displayName = `${fileNamePrefix}${versionSuffix}-${documentReference}.pdf`;
  const sizeBytes = Number.isFinite(Number(pdfBuffer?.length)) ? Number(pdfBuffer.length) : null;
  const checksum = pdfBuffer ? crypto.createHash('sha256').update(pdfBuffer).digest('hex') : null;
  const normalizedApplicantUserId = normalisePositiveInteger(applicantUserId);
  const normalizedActorUserId = normalisePositiveInteger(actorUserId);
  const normalizedClientId = normalisePositiveInteger(clientId);
  let relativePath = null;
  const { generateKey, presignPut, DRIVER } = require('../ISET-intake/s3Provider');
  if (DRIVER !== 's3') {
    throw new Error('s3_upload_unavailable');
  }
  const key = generateKey(applicantUserId || actorUserId || 'admin', displayName);
  const presigned = await presignPut({ key, contentType: 'application/pdf' });
  await axios.put(presigned.url, pdfBuffer, {
    headers: {
      ...(presigned.headers || {}),
      'Content-Type': 'application/pdf',
      ...(sizeBytes ? { 'Content-Length': sizeBytes } : {})
    }
  });
  relativePath = key;
  if (!relativePath) {
    throw new Error('path_resolution_failed');
  }

  if (archivePreviousActive) {
    const scopeColumn = normalizedApplicationId ? 'application_id' : 'case_id';
    const scopeValue = normalizedApplicationId || normalizedCaseId;
    await runner.query(
      `UPDATE iset_document
          SET status = 'archived', updated_at = NOW()
        WHERE ${scopeColumn} = ?
          ${normalizedApplicationId ? '' : 'AND application_id IS NULL'}
          AND document_category = ?
          AND status = 'active'`,
      [scopeValue, documentType]
    );
  } else if (replaceExistingVersion && normalizedVersionNumber) {
    const scopeColumn = normalizedApplicationId ? 'application_id' : 'case_id';
    const scopeValue = normalizedApplicationId || normalizedCaseId;
    const [existingRows] = await runner.query(
      `SELECT id, metadata
         FROM iset_document
        WHERE ${scopeColumn} = ?
          ${normalizedApplicationId ? '' : 'AND application_id IS NULL'}
          AND document_category = ?
          AND status = 'active'`,
      [scopeValue, documentType]
    );
    const idsToArchive = (Array.isArray(existingRows) ? existingRows : [])
      .map(row => ({ id: normalisePositiveInteger(row?.id), info: parseAssessmentDocumentInfo(row) }))
      .filter(item => item.id && item.info?.versionNumber === normalizedVersionNumber)
      .map(item => item.id);
    if (idsToArchive.length) {
      const idPlaceholders = idsToArchive.map(() => '?').join(',');
      await runner.query(
        `UPDATE iset_document
            SET status = 'archived', updated_at = NOW()
          WHERE id IN (${idPlaceholders})`,
        idsToArchive
      );
    }
  }

  const metadata = buildAssessmentDocumentMetadata({
    label,
    documentType,
    versionNumber: normalizedVersionNumber,
    variant,
    previousVersionNumber,
    snapshot
  });
  const insertPayload = [
    normalizedCaseId || null,
    normalizedApplicationId || null,
    normalizedClientId,
    normalizedApplicantUserId,
    normalizedActorUserId,
    displayName,
    relativePath,
    'application/pdf',
    label,
    metadata,
    sizeBytes,
    checksum,
    documentType
  ];
  const [result] = await runner.query(
    `INSERT INTO iset_document
       (case_id, application_id, client_id, applicant_user_id, user_id, source, file_name, file_path, mime_type, label, metadata, size_bytes, checksum_sha256, status, document_category)
     VALUES (?,?,?,?,?, 'system_generated', ?, ?, ?, ?, ?, ?, ?, 'active', ?)`,
    insertPayload
  );
  return result?.insertId || null;
}

