const NWAC_LOGO_PATH = path.join(__dirname, 'public', 'nwac-logo.png');
let nwacLogoDataUriCache = null;

function getNwacLogoDataUri() {
  if (nwacLogoDataUriCache !== null) return nwacLogoDataUriCache;
  try {
    const logoBuffer = fs.readFileSync(NWAC_LOGO_PATH);
    nwacLogoDataUriCache = `data:image/png;base64,${logoBuffer.toString('base64')}`;
  } catch (err) {
    console.warn('[assessment-pdf] Unable to load NWAC logo:', err.message);
    nwacLogoDataUriCache = '';
  }
  return nwacLogoDataUriCache;
}

const CONSENT_LOGO_PATH = path.join(__dirname, 'public', 'nwac-consent-logo.png');
let consentLogoDataUriCache = null;

function getConsentLogoDataUri() {
  if (consentLogoDataUriCache !== null) return consentLogoDataUriCache;
  try {
    const logoBuffer = fs.readFileSync(CONSENT_LOGO_PATH);
    consentLogoDataUriCache = `data:image/png;base64,${logoBuffer.toString('base64')}`;
  } catch (err) {
    console.warn('[consent-pdf] Unable to load NWAC logo:', err.message);
    consentLogoDataUriCache = '';
  }
  return consentLogoDataUriCache;
}

function formatSignatureDate(value) {
  if (!value) return 'Not signed';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleString('en-CA', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
}

function formatMultilineHtml(value) {
  return escapeHtml(value || '').replace(/\r?\n/g, '<br />');
}

function buildPdfSignaturePanelHtml({
  signerName,
  signedAt,
  emptyMessage = 'Not signed'
} = {}) {
  const normalizedSignerName = normaliseString(signerName);
  const signatureBoxClass = normalizedSignerName ? 'signature-box' : 'signature-box empty';
  const signatureValue = normalizedSignerName || emptyMessage;
  const signedAtText = signedAt ? `Signed on ${escapeHtml(formatSignatureDate(signedAt))}` : 'No signature timestamp recorded';
  return `
    <div class="signature-panel">
      <div class="${signatureBoxClass}">${escapeHtml(signatureValue)}</div>
      <div class="signature-meta">${signedAtText}</div>
    </div>
  `;
}

function buildAssessmentAgreementSectionHtml({
  agreeWithCoordinator,
  denialReason,
  approvalSignatureHtml
} = {}) {
  const normalizedDecision = normaliseString(agreeWithCoordinator);
  const agreeChecked = normalizedDecision === 'agree' ? ' checked="checked"' : '';
  const disagreeChecked = normalizedDecision === 'disagree' ? ' checked="checked"' : '';
  return `
    <div class="section-title">AGREEMENT WITH COORDINATOR RECOMMENDATION</div>
    <table class="form-table">
      <tr>
        <td class="label">Coordinator recommendation</td>
        <td>
          <div class="check-grid">
            <label class="check"><input type="radio" name="agreeCoordinatorApproved"${agreeChecked} />Agree</label>
            <label class="check"><input type="radio" name="agreeCoordinatorApproved"${disagreeChecked} />Disagree</label>
          </div>
        </td>
        <td class="label">Reason for denial by NWAC (if applicable)</td>
        <td><div class="text-field large">${escapeHtml(denialReason || '')}</div></td>
      </tr>
      <tr>
        <td class="label">Approver eSignature</td>
        <td colspan="3">${approvalSignatureHtml || buildPdfSignaturePanelHtml({})}</td>
      </tr>
    </table>
  `;
}

const resolvePaymentTypeLabel = (value) => {
  const normalized = normalizePaymentTypeCode(value) || normaliseString(value);
  if (!normalized) return '';
  return PAYMENT_TYPE_LABELS[normalized] || normalized;
};

const resolveCostLineOccurrences = (line, intervention = null, { allowInterventionFallback = false } = {}) => {
  if (!line || typeof line !== 'object') return null;
  const recurrence = line.recurrence && typeof line.recurrence === 'object' ? line.recurrence : {};
  const occurrencesRaw = recurrence.occurrences;
  const directOccurrences = Number.isFinite(Number(occurrencesRaw)) && Number(occurrencesRaw) > 0
    ? Number(occurrencesRaw)
    : null;
  if (directOccurrences) return directOccurrences;
  const recurrenceStart = toDateOnlyString(recurrence.startDate);
  const recurrenceEnd = toDateOnlyString(recurrence.endDate);
  if (recurrenceStart && recurrenceEnd) {
    return calculateInclusiveMonthCount(recurrenceStart, recurrenceEnd);
  }
  if (allowInterventionFallback) {
    const interventionStart = toDateOnlyString(intervention?.startDate ?? intervention?.interventionStartDate ?? null);
    const interventionEnd = toDateOnlyString(intervention?.endDate ?? intervention?.interventionEndDate ?? null);
    if (interventionStart && interventionEnd) {
      return calculateInclusiveMonthCount(interventionStart, interventionEnd);
    }
  }
  return null;
};

const resolveCostLineSubmissionTiming = (line, submissionTimingByType = null) => {
  const code = normalizePaymentTypeCode(line?.type);
  if (!code) return 'manual_trigger';
  let timingValue = null;
  if (submissionTimingByType instanceof Map) {
    timingValue = submissionTimingByType.get(code) || null;
  } else if (submissionTimingByType && typeof submissionTimingByType === 'object') {
    timingValue = submissionTimingByType[code] || null;
  }
  return (
    normalizePaymentSubmissionTiming(timingValue) ||
    PAYMENT_SUBMISSION_TIMING_DEFAULTS[code] ||
    'manual_trigger'
  );
};

const resolveCostLinePayableText = ({
  line,
  intervention = null,
  submissionTimingByType = null,
  recurrenceEnabled = false,
  occurrences = null
}) => {
  const recurrence = line?.recurrence && typeof line.recurrence === 'object' ? line.recurrence : {};
  const submissionTiming = resolveCostLineSubmissionTiming(line, submissionTimingByType);
  const interventionStart = toDateOnlyString(intervention?.startDate ?? intervention?.interventionStartDate ?? null);
  const interventionEnd = toDateOnlyString(intervention?.endDate ?? intervention?.interventionEndDate ?? null);
  const recurrenceStart = toDateOnlyString(recurrence.startDate);
  const recurrenceEnd = toDateOnlyString(recurrence.endDate);
  const explicitPayableDate = resolveCostLinePayableDate(line);
  const firstInstallmentDate = recurrenceStart ||
    explicitPayableDate ||
    (submissionTiming === 'intervention_end'
      ? (interventionEnd || recurrenceEnd)
      : (interventionStart || recurrenceEnd));
  const firstInstallmentDateLabel = formatFundingDate(firstInstallmentDate);

  if (recurrenceEnabled) {
    const occurrenceCount = Number.isFinite(Number(occurrences)) && Number(occurrences) > 0
      ? Number(occurrences)
      : null;
    let text = occurrenceCount
      ? `payable in ${occurrenceCount} monthly installment${occurrenceCount === 1 ? '' : 's'}`
      : 'payable in monthly installments';
    if (firstInstallmentDateLabel) {
      text += ` starting ${firstInstallmentDateLabel}`;
    }
    return text;
  }
  let payableDate = '';
  if (submissionTiming === 'intervention_start') {
    payableDate = formatFundingDate(interventionStart || recurrenceStart || explicitPayableDate);
  } else if (submissionTiming === 'intervention_end') {
    payableDate = formatFundingDate(interventionEnd || recurrenceEnd || explicitPayableDate);
  } else if (submissionTiming === 'recurrence_schedule') {
    payableDate = formatFundingDate(recurrenceStart || explicitPayableDate || interventionStart || interventionEnd);
  } else if (submissionTiming === 'manual_trigger') {
    payableDate = formatFundingDate(explicitPayableDate);
  }
  if (payableDate) {
    return `payable on ${payableDate}`;
  }
  return 'payable';
};

const resolveCostLinePayeeLabel = (line) => {
  if (!line || typeof line !== 'object') return '';
  const payee = line.payee && typeof line.payee === 'object' ? line.payee : {};
  const payeeName = normaliseString(
    payee.name ||
    line.payeeName ||
    line.payee_name ||
    null
  );
  if (payeeName) return payeeName;
  const rawType = normaliseString(
    payee.type ||
    line.payeeType ||
    line.payee_type ||
    null
  );
  if (!rawType) return '';
  const key = rawType.toLowerCase().replace(/[^a-z0-9]+/g, '');
  const typeLabelMap = {
    participantclient: 'client',
    client: 'client',
    accreditededucationaltraininginstitution: 'institution',
    traininginstitution: 'institution',
    institution: 'institution',
    employerwagesubsidypartner: 'employer',
    employer: 'employer',
    childcareprovider: 'childcare provider',
    communitynonprofitorganization: 'community organization',
    trainingrelatedsupplier: 'supplier',
    professionalbusinessservicesprovider: 'service provider',
    vendor: 'vendor',
    other: 'payee'
  };
  return typeLabelMap[key] || '';
};

const resolveCostLinePayableDate = (line) => {
  if (!line || typeof line !== 'object') return '';
  const recurrence = line.recurrence && typeof line.recurrence === 'object' ? line.recurrence : {};
  const candidates = [
    line.payableDate,
    line.payable_date,
    line.paymentDate,
    line.payment_date,
    line.dateDue,
    line.date_due,
    recurrence.startDate,
    recurrence.start_date
  ];
  for (const candidate of candidates) {
    const normalized = toDateOnlyString(candidate);
    if (normalized) return normalized;
  }
  return '';
};

const formatCostLineDetails = (
  line,
  intervention = null,
  submissionTimingByType = null,
  recurrencePolicyByType = null,
  paymentSummary = null
) => {
  if (!line || typeof line !== 'object') return '';
  const recurrence = line.recurrence && typeof line.recurrence === 'object' ? line.recurrence : {};
  const recurrenceEnabledExplicit = recurrence.enabled === true || String(recurrence.enabled || '').toLowerCase() === 'true';
  const recurrenceMode = resolveRecurrenceModeForPaymentType(line?.type, recurrencePolicyByType);
  const recurrenceRequired = recurrenceMode === 'required';
  const recurrenceEnabled = recurrenceEnabledExplicit || recurrenceRequired;
  const occurrences = recurrenceEnabled
    ? resolveCostLineOccurrences(line, intervention, { allowInterventionFallback: true })
    : null;
  const amountPerPeriod = recurrenceEnabled ? parseCurrencyValue(recurrence.amountPerPeriod) : null;
  const payeeLabel = resolveCostLinePayeeLabel(line);
  const payableText = resolveCostLinePayableText({
    line,
    intervention,
    submissionTimingByType,
    recurrenceEnabled,
    occurrences
  });
  let scheduleText = payableText || '';
  if (amountPerPeriod !== null) {
    const amountText = formatFundingCurrency(amountPerPeriod);
    if (amountText) {
      scheduleText = scheduleText
        ? `${scheduleText} (${amountText} per month)`
        : `${amountText} per month`;
    }
  }
  if (paymentSummary && Number.isFinite(paymentSummary.paidTotal) && paymentSummary.paidTotal > 0) {
    const currentAmount = resolveFundingAgreementCostLineAmount(line, intervention);
    const paidTotal = Math.round(paymentSummary.paidTotal * 100) / 100;
    const paidDate = formatFundingDate(paymentSummary.lastPaidAt || null);
    const paidAmountText = formatFundingCurrency(paidTotal);
    const payeeSuffix = payeeLabel ? ` to ${payeeLabel}` : '';
    const paidTiming = paidDate
      ? paymentSummary.paidCount > 1
        ? ` through ${paidDate}`
        : ` on ${paidDate}`
      : '';
    const fullyPaid =
      Number.isFinite(currentAmount) &&
      currentAmount > 0 &&
      paidTotal + 0.009 >= currentAmount;
    if (fullyPaid) {
      return `paid${paidTiming}${payeeSuffix}`;
    }

    let remainingScheduleText = scheduleText
      ? scheduleText.replace(/^payable\b/i, 'remaining payable')
      : 'remaining payable';
    const remainingAmount =
      Number.isFinite(currentAmount) && currentAmount > 0
        ? Math.max(0, Math.round((currentAmount - paidTotal) * 100) / 100)
        : null;
    if (recurrenceEnabled && remainingAmount !== null && remainingAmount > 0) {
      let remainingOccurrences = null;
      if (amountPerPeriod !== null && amountPerPeriod > 0) {
        const quotient = remainingAmount / amountPerPeriod;
        if (Math.abs(Math.round(quotient) - quotient) <= 0.01) {
          remainingOccurrences = Math.max(0, Math.round(quotient));
        }
      }
      const nextScheduledDate = formatFundingDate(paymentSummary.nextScheduledDate || null);
      remainingScheduleText = Number.isFinite(remainingOccurrences) && remainingOccurrences > 0
        ? `remaining payable in ${remainingOccurrences} monthly installment${remainingOccurrences === 1 ? '' : 's'}`
        : 'remaining payable in monthly installments';
      if (nextScheduledDate) {
        remainingScheduleText += ` starting ${nextScheduledDate}`;
      }
      if (amountPerPeriod !== null) {
        const remainingAmountText = formatFundingCurrency(amountPerPeriod);
        if (remainingAmountText) {
          remainingScheduleText += ` (${remainingAmountText} per month)`;
        }
      }
    } else if (!recurrenceEnabled && paymentSummary.nextScheduledDate) {
      remainingScheduleText = `remaining payable on ${formatFundingDate(paymentSummary.nextScheduledDate)}`;
    }

    if (paidAmountText) {
      return `${paidAmountText} already paid${paidTiming}; ${remainingScheduleText}${payeeSuffix}`;
    }
    return `paid in part${paidTiming}; ${remainingScheduleText}${payeeSuffix}`;
  }
  let detailText = scheduleText;
  if (payeeLabel) {
    detailText = detailText
      ? `${detailText} to ${payeeLabel}`
      : `to ${payeeLabel}`;
  }
  return detailText;
};

const resolveDeliveryModeLabel = (value) => {
  const normalized = normaliseString(value);
  if (!normalized) return '';
  if (normalized === 'in_house') return 'In-house (no external partner)';
  if (normalized === 'partner') return 'External delivery partner';
  return formatCaseStatusLabel(normalized) || normalized;
};

const buildAssessmentInlineDiffHtml = ({
  currentValue = '',
  previousValue,
  diffStatus = null,
  emptyValue = '&mdash;'
} = {}) => {
  const normalizedStatus = normaliseString(diffStatus ?? null);
  const resolvedStatus = normalizedStatus ? normalizedStatus.toLowerCase() : null;
  const hasPreviousValue = typeof previousValue !== 'undefined';
  const current = normaliseString(currentValue ?? null) || '';
  const previous = hasPreviousValue ? (normaliseString(previousValue ?? null) || '') : '';

  if (!resolvedStatus && !hasPreviousValue) {
    return current ? escapeHtml(current) : emptyValue;
  }
  if (resolvedStatus === 'removed') {
    const removedValue = previous || current;
    return removedValue ? `<div class="redline-inline-old">${escapeHtml(removedValue)}</div>` : emptyValue;
  }
  if (resolvedStatus === 'added') {
    const addedValue = current || previous;
    return addedValue ? `<div class="redline-inline-new">${escapeHtml(addedValue)}</div>` : emptyValue;
  }
  if (current === previous) {
    return current ? escapeHtml(current) : emptyValue;
  }
  if (!previous) {
    return current ? `<div class="redline-inline-new">${escapeHtml(current)}</div>` : emptyValue;
  }
  if (!current) {
    return `<div class="redline-inline-old">${escapeHtml(previous)}</div>`;
  }
  return [
    '<div class="redline-change-block">',
    `<div class="redline-inline-old">${escapeHtml(previous)}</div>`,
    `<div class="redline-inline-new">${escapeHtml(current)}</div>`,
    '</div>'
  ].join('');
};

const buildAssessmentTotalDiffHtml = ({
  currentValue = '',
  previousValue,
  diffStatus = null,
  emptyValue = ''
} = {}) => {
  const contentHtml = buildAssessmentInlineDiffHtml({
    currentValue,
    previousValue,
    diffStatus,
    emptyValue
  });
  return contentHtml || '';
};

const buildAssessmentMultilineDiffHtml = ({
  currentValue = '',
  previousValue,
  diffStatus = null,
  emptyValue = '&mdash;'
} = {}) => {
  const normalizedStatus = normaliseString(diffStatus ?? null);
  const resolvedStatus = normalizedStatus ? normalizedStatus.toLowerCase() : null;
  const hasPreviousValue = typeof previousValue !== 'undefined';
  const current = normaliseString(currentValue ?? null) || '';
  const previous = hasPreviousValue ? (normaliseString(previousValue ?? null) || '') : '';
  const currentHtml = current ? formatMultilineHtml(current) : emptyValue;
  const previousHtml = previous ? formatMultilineHtml(previous) : emptyValue;
  if (!resolvedStatus && !hasPreviousValue) {
    return currentHtml;
  }
  if (resolvedStatus === 'removed') {
    const removedHtml = previous ? formatMultilineHtml(previous) : currentHtml;
    return removedHtml ? `<div class="redline-inline-old">${removedHtml}</div>` : emptyValue;
  }
  if (resolvedStatus === 'added') {
    const addedHtml = current ? formatMultilineHtml(current) : previousHtml;
    return addedHtml ? `<div class="redline-inline-new">${addedHtml}</div>` : emptyValue;
  }
  if (current === previous) {
    return currentHtml;
  }
  if (!previous) {
    return currentHtml ? `<div class="redline-inline-new">${currentHtml}</div>` : emptyValue;
  }
  if (!current) {
    return `<div class="redline-inline-old">${previousHtml}</div>`;
  }
  return [
    '<div class="redline-change-block">',
    `<div class="redline-inline-old">${previousHtml}</div>`,
    `<div class="redline-inline-new">${currentHtml}</div>`,
    '</div>'
  ].join('');
};

const hasAssessmentSnapshotContent = snapshot =>
  Boolean(snapshot && typeof snapshot === 'object' && !Array.isArray(snapshot) && Object.keys(snapshot).length);

function sortAssessmentInterventions(list) {
  const items = Array.isArray(list) ? list.slice() : [];
  return items.sort((a, b) => {
    const aDate = a?.startDate || '';
    const bDate = b?.startDate || '';
    if (aDate && bDate && aDate !== bDate) return String(aDate).localeCompare(String(bDate));
    if (aDate && !bDate) return -1;
    if (!aDate && bDate) return 1;
    const aCode = a?.code || '';
    const bCode = b?.code || '';
    if (aCode !== bCode) return String(aCode).localeCompare(String(bCode));
    const aId = a?.id || 0;
    const bId = b?.id || 0;
    return Number(aId) - Number(bId);
  });
}

function buildAssessmentInterventionKey(intervention) {
  if (!intervention) return '';
  if (intervention.id) return `id:${intervention.id}`;
  const code = intervention.code || '';
  const start = intervention.startDate || '';
  const end = intervention.endDate || '';
  const program = intervention.programName || '';
  const institution = intervention.institution || '';
  return `key:${code}|${start}|${end}|${program}|${institution}`;
}

function buildAssessmentInterventionSignature(intervention) {
  const canonical = canonicalisePreviewValue({
    code: intervention?.code || null,
    label: intervention?.label || null,
    startDate: intervention?.startDate || null,
    endDate: intervention?.endDate || null,
    deliveryMode: intervention?.deliveryMode || null,
    programName: intervention?.programName || null,
    institution: intervention?.institution || null,
    noc: intervention?.noc || null,
    nocVersion: intervention?.nocVersion || null,
    itpDetails: intervention?.itpDetails || null,
    wageSubsidyDetails: intervention?.wageSubsidyDetails || null,
    costLines: Array.isArray(intervention?.costLines) ? intervention.costLines : [],
    costTotal: intervention?.costTotal ?? null,
  });
  return JSON.stringify(canonical);
}

function buildAssessmentCostLineKey(line, index = 0) {
  const id = normaliseString(line?.id ?? line?.lineId ?? line?.line_id ?? null);
  if (id) return `id:${id}`;
  const type = normaliseString(line?.type ?? line?.paymentType ?? line?.payment_type ?? null) || '';
  const payeeType = normaliseString(line?.payee?.type ?? line?.payeeType ?? line?.payee_type ?? null) || '';
  const payeeName = normaliseString(line?.payee?.name ?? line?.payeeName ?? line?.payee_name ?? null) || '';
  return `key:${type}|${payeeType}|${payeeName}|${Number(index) + 1}`;
}

function buildAssessmentCostLineSignature(line) {
  return JSON.stringify(
    canonicalisePreviewValue({
      type: line?.type || null,
      amount: line?.amount ?? null,
      notes: line?.notes || null,
      recurrence: line?.recurrence || null,
      payee: line?.payee || null,
    })
  );
}

function buildAssessmentCostLineDiffList({ previousCostLines, currentCostLines }) {
  const previousList = Array.isArray(previousCostLines) ? previousCostLines : [];
  const currentList = Array.isArray(currentCostLines) ? currentCostLines : [];
  const previousByKey = new Map();
  const previousSignature = new Map();
  previousList.forEach((line, index) => {
    const key = buildAssessmentCostLineKey(line, index);
    if (!key) return;
    previousByKey.set(key, { ...line, sourceLineIndex: index + 1 });
    previousSignature.set(key, buildAssessmentCostLineSignature(line));
  });

  const seen = new Set();
  const diff = [];
  currentList.forEach((line, index) => {
    const key = buildAssessmentCostLineKey(line, index);
    const previousLine = key ? previousByKey.get(key) : null;
    if (!previousLine) {
      diff.push({ ...line, diffStatus: 'added', sourceLineIndex: index + 1 });
      return;
    }
    seen.add(key);
    const currentSignature = buildAssessmentCostLineSignature(line);
    const previousLineSignature = previousSignature.get(key);
    if (currentSignature !== previousLineSignature) {
      diff.push({ ...previousLine, diffStatus: 'removed' });
      diff.push({ ...line, diffStatus: 'added', sourceLineIndex: index + 1 });
    } else {
      diff.push({ ...line, sourceLineIndex: index + 1 });
    }
  });

  previousList.forEach((line, index) => {
    const key = buildAssessmentCostLineKey(line, index);
    if (!key || seen.has(key)) return;
    diff.push({ ...line, diffStatus: 'removed', sourceLineIndex: index + 1 });
  });
  return diff;
}

function buildAssessmentInterventionMetaDiffs({ previousIntervention, currentIntervention }) {
  const previousStartDate = toDateOnlyString(previousIntervention?.startDate ?? null);
  const currentStartDate = toDateOnlyString(currentIntervention?.startDate ?? null);
  const previousEndDate = toDateOnlyString(previousIntervention?.endDate ?? null);
  const currentEndDate = toDateOnlyString(currentIntervention?.endDate ?? null);
  const previousDuration = calculateDurationDaysFromDates(previousStartDate, previousEndDate);
  const currentDuration = calculateDurationDaysFromDates(currentStartDate, currentEndDate);
  return {
    label: buildFundingAgreementValueDiff(
      previousIntervention?.label ?? null,
      currentIntervention?.label ?? null
    ),
    deliveryMode: buildFundingAgreementValueDiff(
      resolveDeliveryModeLabel(previousIntervention?.deliveryMode ?? null),
      resolveDeliveryModeLabel(currentIntervention?.deliveryMode ?? null)
    ),
    programName: buildFundingAgreementValueDiff(
      previousIntervention?.programName ?? null,
      currentIntervention?.programName ?? null
    ),
    institution: buildFundingAgreementValueDiff(
      previousIntervention?.institution ?? null,
      currentIntervention?.institution ?? null
    ),
    startDate: buildFundingAgreementValueDiff(
      previousStartDate,
      currentStartDate
    ),
    endDate: buildFundingAgreementValueDiff(
      previousEndDate,
      currentEndDate
    ),
    durationDays: buildFundingAgreementValueDiff(
      previousDuration === null ? '' : String(previousDuration),
      currentDuration === null ? '' : String(currentDuration)
    ),
    noc: buildFundingAgreementValueDiff(
      previousIntervention?.noc ?? null,
      currentIntervention?.noc ?? null
    ),
    nocVersion: buildFundingAgreementValueDiff(
      previousIntervention?.nocVersion ?? null,
      currentIntervention?.nocVersion ?? null
    ),
    itpDetails: buildFundingAgreementValueDiff(
      previousIntervention?.itpDetails ?? null,
      currentIntervention?.itpDetails ?? null
    ),
    wageSubsidyDetails: buildFundingAgreementValueDiff(
      previousIntervention?.wageSubsidyDetails ?? null,
      currentIntervention?.wageSubsidyDetails ?? null
    )
  };
}

function buildAssessmentInterventionDiffList({ previousInterventions, currentInterventions }) {
  const previousList = sortAssessmentInterventions(previousInterventions);
  const currentList = sortAssessmentInterventions(currentInterventions);
  const previousByKey = new Map();
  const previousSignature = new Map();
  previousList.forEach(item => {
    const key = buildAssessmentInterventionKey(item);
    if (!key) return;
    previousByKey.set(key, item);
    previousSignature.set(key, buildAssessmentInterventionSignature(item));
  });

  const seen = new Set();
  const diff = [];

  currentList.forEach(item => {
    const key = buildAssessmentInterventionKey(item);
    const previous = key ? previousByKey.get(key) : null;
    if (!previous) {
      diff.push({ ...item, diffStatus: 'added' });
      return;
    }
    seen.add(key);
    const currentSignature = buildAssessmentInterventionSignature(item);
    const previousItemSignature = previousSignature.get(key);
    if (currentSignature !== previousItemSignature) {
      diff.push({
        ...item,
        diffStatus: 'modified',
        metaDiffs: buildAssessmentInterventionMetaDiffs({
          previousIntervention: previous,
          currentIntervention: item
        }),
        costLineDiffs: buildAssessmentCostLineDiffList({
          previousCostLines: previous?.costLines,
          currentCostLines: item?.costLines
        }),
        previousCostTotal:
          computeCostLinesTotal(Array.isArray(previous?.costLines) ? previous.costLines : []) ??
          parseCurrencyValue(previous?.costTotal) ??
          null
      });
    } else {
      diff.push({ ...item });
    }
  });

  previousList.forEach(item => {
    const key = buildAssessmentInterventionKey(item);
    if (!key || seen.has(key)) return;
    diff.push({ ...item, diffStatus: 'removed' });
  });
  return diff;
}

const buildAssessmentProposedInterventionsHtml = ({
  interventions,
  interventionLabelLookup,
  fallbackDeliveryModeLabel
}) => {
  const list = Array.isArray(interventions) ? interventions : [];
  if (!list.length) {
    return '<div class="empty-state">No proposed interventions recorded.</div>';
  }

  return list.map((intervention, index) => {
    const code = normaliseString(intervention?.code);
    const explicitLabel = normaliseString(
      intervention?.label ?? intervention?.interventionLabel ?? intervention?.intervention_label
    );
    const label = explicitLabel || (code && interventionLabelLookup ? interventionLabelLookup.get(code) : null);
    const displayLabel = label ? (code ? `${label} (${code})` : label) : (code || '');
    const diffStatusRaw = normaliseString(intervention?.diffStatus ?? intervention?.diff_status ?? null);
    const diffStatus = diffStatusRaw ? diffStatusRaw.toLowerCase() : null;
    const diffLabel =
      diffStatus === 'added'
        ? 'Added'
        : diffStatus === 'removed'
        ? 'Removed'
        : diffStatus === 'modified'
        ? 'Updated'
        : '';
    const diffBadge = diffLabel
      ? `<span class="redline-badge redline-${escapeHtml(diffStatus)}-badge">${escapeHtml(diffLabel)}</span>`
      : '';
    const title = `Intervention ${index + 1}${displayLabel ? `: ${displayLabel}` : ''}`;
    const deliveryLabel =
      resolveDeliveryModeLabel(intervention?.deliveryMode) ||
      fallbackDeliveryModeLabel ||
      '';
    const startDate = toDateOnlyString(intervention?.startDate);
    const endDate = toDateOnlyString(intervention?.endDate);
    const durationDays = calculateDurationDaysFromDates(startDate, endDate);
    const durationText = durationDays === null ? '' : String(durationDays);
    const nocCode = normaliseString(intervention?.noc);
    const nocVersion = normaliseString(intervention?.nocVersion);
    const programName = normaliseString(intervention?.programName);
    const institution = normaliseString(intervention?.institution);
    const itpDetails = normaliseString(intervention?.itpDetails);
    const wageDetails = normaliseString(intervention?.wageSubsidyDetails);
    const metaDiffs = intervention?.metaDiffs && typeof intervention.metaDiffs === 'object'
      ? intervention.metaDiffs
      : {};
    const currentCostLines = Array.isArray(intervention?.costLines) ? intervention.costLines : [];
    const renderedCostLines =
      diffStatus === 'modified' && Array.isArray(intervention?.costLineDiffs)
        ? intervention.costLineDiffs
        : currentCostLines;

    const costRows = renderedCostLines.map(line => {
      const typeLabel = resolvePaymentTypeLabel(line?.type);
      const amountValue = formatCurrencyValue(line?.amount);
      const amountText = amountValue ? `$${amountValue}` : '';
      const details = formatCostLineDetails(line, intervention);
      const notes = normaliseString(line?.notes);
      const detailsHtml = notes
        ? `${escapeHtml(details || '')}<br /><em>${formatMultilineHtml(notes)}</em>`
        : escapeHtml(details || '');
      const rowDiffStatusRaw = normaliseString(line?.diffStatus ?? line?.diff_status ?? null);
      const rowDiffStatus = rowDiffStatusRaw ? rowDiffStatusRaw.toLowerCase() : null;
      const rowBadgeLabel =
        rowDiffStatus === 'removed'
          ? 'Removed'
          : rowDiffStatus === 'added'
          ? 'Added'
          : '';
      const rowBadgeHtml = rowBadgeLabel
        ? `<span class="redline-badge redline-${escapeHtml(rowDiffStatus)}-badge">${escapeHtml(rowBadgeLabel)}</span> `
        : '';
      const rowClassName = rowDiffStatus ? ` class="redline-row-${escapeHtml(rowDiffStatus)}"` : '';
      return `
        <tr${rowClassName}>
          <td>${rowBadgeHtml}${buildAssessmentInlineDiffHtml({ currentValue: typeLabel || '', diffStatus: rowDiffStatus, emptyValue: '' })}</td>
          <td class="amount">${buildAssessmentInlineDiffHtml({ currentValue: amountText, diffStatus: rowDiffStatus, emptyValue: '' })}</td>
          <td>${rowDiffStatus ? renderFundingAgreementDiffHtml({ html: detailsHtml, diffStatus: rowDiffStatus, emptyValue: '&mdash;' }) : detailsHtml}</td>
        </tr>`;
    }).join('');

    const costRowsHtml = costRows || '<tr><td colspan="3">No cost items recorded.</td></tr>';
    const costTotal = computeCostLinesTotal(currentCostLines);
    const fallbackTotal = Number.isFinite(Number(intervention?.costTotal))
      ? Number(intervention.costTotal)
      : null;
    const totalValue = costTotal !== null ? costTotal : fallbackTotal;
    const totalText = totalValue === null ? '' : `$${formatCurrencyValue(totalValue)}`;
    const previousTotalValue = parseCurrencyValue(intervention?.previousCostTotal);
    const previousTotalText = previousTotalValue === null ? '' : `$${formatCurrencyValue(previousTotalValue)}`;
    const totalHtml = diffStatus === 'modified'
      ? buildAssessmentTotalDiffHtml({
          currentValue: totalText,
          previousValue: previousTotalText,
          emptyValue: ''
        })
      : buildAssessmentTotalDiffHtml({ currentValue: totalText, diffStatus, emptyValue: '' });
    const titleHtml = diffBadge ? `${diffBadge} ${escapeHtml(title)}` : escapeHtml(title);
    const displayLabelHtml = diffStatus === 'modified'
      ? buildAssessmentInlineDiffHtml({
          currentValue: displayLabel || '',
          previousValue: metaDiffs?.label?.from,
          emptyValue: ''
        })
      : buildAssessmentInlineDiffHtml({ currentValue: displayLabel || '', diffStatus, emptyValue: '' });
    const deliveryModeHtml = diffStatus === 'modified'
      ? buildAssessmentInlineDiffHtml({
          currentValue: deliveryLabel,
          previousValue: metaDiffs?.deliveryMode?.from,
          emptyValue: ''
        })
      : buildAssessmentInlineDiffHtml({ currentValue: deliveryLabel, diffStatus, emptyValue: '' });
    const programNameHtml = diffStatus === 'modified'
      ? buildAssessmentInlineDiffHtml({
          currentValue: programName,
          previousValue: metaDiffs?.programName?.from,
          emptyValue: ''
        })
      : buildAssessmentInlineDiffHtml({ currentValue: programName, diffStatus, emptyValue: '' });
    const startDateHtml = diffStatus === 'modified'
      ? buildAssessmentInlineDiffHtml({
          currentValue: startDate,
          previousValue: metaDiffs?.startDate?.from,
          emptyValue: ''
        })
      : buildAssessmentInlineDiffHtml({ currentValue: startDate, diffStatus, emptyValue: '' });
    const endDateHtml = diffStatus === 'modified'
      ? buildAssessmentInlineDiffHtml({
          currentValue: endDate,
          previousValue: metaDiffs?.endDate?.from,
          emptyValue: ''
        })
      : buildAssessmentInlineDiffHtml({ currentValue: endDate, diffStatus, emptyValue: '' });
    const durationHtml = diffStatus === 'modified'
      ? buildAssessmentInlineDiffHtml({
          currentValue: durationText,
          previousValue: metaDiffs?.durationDays?.from,
          emptyValue: ''
        })
      : buildAssessmentInlineDiffHtml({ currentValue: durationText, diffStatus, emptyValue: '' });
    const nocCodeHtml = diffStatus === 'modified'
      ? buildAssessmentInlineDiffHtml({
          currentValue: nocCode,
          previousValue: metaDiffs?.noc?.from,
          emptyValue: ''
        })
      : buildAssessmentInlineDiffHtml({ currentValue: nocCode, diffStatus, emptyValue: '' });
    const nocVersionHtml = diffStatus === 'modified'
      ? buildAssessmentInlineDiffHtml({
          currentValue: nocVersion,
          previousValue: metaDiffs?.nocVersion?.from,
          emptyValue: ''
        })
      : buildAssessmentInlineDiffHtml({ currentValue: nocVersion, diffStatus, emptyValue: '' });
    const institutionHtml = diffStatus === 'modified'
      ? buildAssessmentInlineDiffHtml({
          currentValue: institution,
          previousValue: metaDiffs?.institution?.from,
          emptyValue: ''
        })
      : buildAssessmentInlineDiffHtml({ currentValue: institution, diffStatus, emptyValue: '' });
    const itpDetailsHtml = diffStatus === 'modified'
      ? buildAssessmentMultilineDiffHtml({
          currentValue: itpDetails,
          previousValue: metaDiffs?.itpDetails?.from
        })
      : buildAssessmentMultilineDiffHtml({ currentValue: itpDetails, diffStatus });
    const wageDetailsHtml = diffStatus === 'modified'
      ? buildAssessmentMultilineDiffHtml({
          currentValue: wageDetails,
          previousValue: metaDiffs?.wageSubsidyDetails?.from
        })
      : buildAssessmentMultilineDiffHtml({ currentValue: wageDetails, diffStatus });
    const blockClassName = diffStatus ? `intervention-block redline-${escapeHtml(diffStatus)}` : 'intervention-block';

    return `
      <div class="${blockClassName}">
        <div class="intervention-title">${titleHtml}</div>
        <table class="form-table intervention-table">
          <tr>
            <td class="label">Intervention</td>
            <td colspan="3">${displayLabelHtml}</td>
          </tr>
          <tr>
            <td class="label">Delivery mode</td>
            <td>${deliveryModeHtml}</td>
            <td class="label">Program name</td>
            <td>${programNameHtml}</td>
          </tr>
          <tr>
            <td class="label">Start date</td>
            <td>${startDateHtml}</td>
            <td class="label">End date</td>
            <td>${endDateHtml}</td>
          </tr>
          <tr>
            <td class="label">Duration (days)</td>
            <td>${durationHtml}</td>
            <td class="label">NOC version</td>
            <td>${nocVersionHtml}</td>
          </tr>
          <tr>
            <td class="label">NOC code</td>
            <td>${nocCodeHtml}</td>
            <td class="label">Training Institution / Employer</td>
            <td>${institutionHtml}</td>
          </tr>
          <tr>
            <td class="label">ITP details</td>
            <td colspan="3">${itpDetailsHtml}</td>
          </tr>
          <tr>
            <td class="label">Wage subsidy details</td>
            <td colspan="3">${wageDetailsHtml}</td>
          </tr>
        </table>
        <table class="cost-table">
          <thead>
            <tr>
              <th>Cost item</th>
              <th>Amount</th>
              <th>Details</th>
            </tr>
          </thead>
          <tbody>
            ${costRowsHtml}
          </tbody>
        </table>
        <div class="cost-total">Intervention total: ${totalHtml || escapeHtml(totalText)}</div>
      </div>`;
  }).join('');
};

async function fetchAssessmentApplicantContext({ applicationId, applicantUserId }) {
  let applicantName = null;
  let trackingId = null;
  let resolvedApplicantUserId = normalisePositiveInteger(applicantUserId);
  if (applicationId) {
    try {
      const [[row]] = await pool.query(
        `SELECT
           COALESCE(
             NULLIF(JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.personal.full_name')), ''),
             NULLIF(JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.submission_snapshot.full_name')), ''),
             NULLIF(TRIM(CONCAT_WS(' ',
               COALESCE(
                 NULLIF(JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$."first-name"')), ''),
                 NULLIF(JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.first_name')), '')
               ),
               COALESCE(
                 NULLIF(JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$."last-name"')), ''),
                 NULLIF(JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.last_name')), '')
               )
             )), ''),
             u.name
           ) AS applicant_name,
           COALESCE(
             NULLIF(JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.submission_snapshot.reference_number')), ''),
             s.reference_number
           ) AS tracking_id,
           COALESCE(
             NULLIF(JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.submission_snapshot.user_id')), ''),
             s.user_id
           ) AS applicant_user_id
         FROM iset_application a
         LEFT JOIN iset_application_submission s ON s.id = a.submission_id
         LEFT JOIN user u ON u.id = s.user_id
         WHERE a.id = ?
         LIMIT 1`,
        [applicationId]
      );
      applicantName = normaliseString(row?.applicant_name);
      trackingId = normaliseString(row?.tracking_id);
      if (!resolvedApplicantUserId) {
        resolvedApplicantUserId = normalisePositiveInteger(row?.applicant_user_id);
      }
    } catch (err) {
      console.warn('[assessment-pdf] failed to resolve applicant context:', err?.message || err);
    }
  }
  if (!applicantName && resolvedApplicantUserId) {
    try {
      const [[userRow]] = await pool.query('SELECT name FROM user WHERE id = ? LIMIT 1', [resolvedApplicantUserId]);
      applicantName = normaliseString(userRow?.name);
    } catch (_) {}
  }
  return { applicantName, trackingId, applicantUserId: resolvedApplicantUserId };
}

function formatAssessmentOtherFundingDetailsForPdf(structuredDetails, fallbackText = '') {
  const parseLegacyOtherFundingSummary = value => {
    const text = normaliseString(value);
    if (!text) return {};
    const involvedMatch = text.match(/Other funding involved:\s*(Yes|No|Unknown)\.?/i);
    const involved = involvedMatch ? involvedMatch[1].toLowerCase() : '';
    const notesMatch = text.match(/(?:^|\s)Notes:\s*([\s\S]*)$/i);
    const notes = notesMatch
      ? notesMatch[1].trim()
      : text.replace(/Other funding involved:\s*(Yes|No|Unknown)\.?\s*/i, '').trim();
    return {
      involved,
      sources: [],
      notes: notes || text,
    };
  };
  const source = structuredDetails && typeof structuredDetails === 'object'
    ? structuredDetails
    : (typeof structuredDetails === 'string' ? parseLegacyOtherFundingSummary(structuredDetails) : null);
  if (!source) return normaliseString(fallbackText) || '';

  const normalizeInvolved = value => {
    const normalized = String(value || '').trim().toLowerCase();
    if (normalized === 'yes' || normalized === 'no' || normalized === 'unknown') return normalized;
    return '';
  };
  const normalizeType = value => {
    const normalized = String(value || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
    if (!normalized) return 'other';
    return normalized;
  };
  const normalizeStatus = (value, entry = {}) => {
    const normalized = String(value || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
    if (normalized === 'not_confirmed' || normalized === 'notconfirmed') return 'unknown';
    if (['confirmed', 'pending', 'denied', 'unknown'].includes(normalized)) return normalized;
    return String(entry?.coverage || '').trim() ? 'confirmed' : 'unknown';
  };
  const typeLabelLookup = {
    iset_holder: 'ISET Holder',
    federal_program: 'Federal Program',
    provincial_territorial_program: 'Prov/Terr Program',
    indigenous_government_org: 'Indigenous Government',
    employer: 'Employer',
    education_bursary_scholarship: 'Bursary/Scholarship',
    nonprofit_charity: 'Nonprofit/Charity',
    insurance_compensation: 'Insurance/Compensation',
    personal_family: 'Personal/Family',
    other_public: 'Other Public',
    other: 'Other',
  };
  const statusLabelLookup = {
    confirmed: 'Confirmed',
    pending: 'Pending',
    denied: 'Denied',
    unknown: 'Unknown / not confirmed',
  };
  const formatAmount = value => {
    const parsed = parseCurrencyValue(value);
    return parsed === null ? '' : `$${formatCurrencyValue(parsed)}`;
  };

  const involved = normalizeInvolved(source.involved);
  const sources = Array.isArray(source.sources) ? source.sources : [];
  const normalizedSources = sources
    .map(entry => {
      if (!entry || typeof entry !== 'object') return null;
      const name = String(entry.name || '').trim();
      const coverage = String(entry.coverage || '').trim();
      const rawAmount = entry.amount ?? entry.fundingAmount ?? entry.funding_amount ?? '';
      const amount = formatAmount(rawAmount);
      const notes = String(entry.notes || '').trim();
      const rawStatus = entry.status || entry.fundingStatus || entry.funding_status;
      if (!name && !coverage && !amount && !notes && !rawStatus) return null;
      const type = normalizeType(entry.type);
      const typeLabel = typeLabelLookup[type] || 'Other';
      const status = normalizeStatus(rawStatus, entry);
      return {
        typeLabel,
        name,
        coverage,
        amount,
        notes,
        status,
        statusLabel: statusLabelLookup[status] || statusLabelLookup.unknown,
      };
    })
    .filter(Boolean);
  const nwacCoverage = String(source.nwacCoverage || source.nwac_coverage || '').trim();
  const notes = String(source.notes || '').trim();

  const lines = [];
  if (involved) {
    const involvedLabel = involved === 'yes' ? 'Yes' : involved === 'no' ? 'No' : 'Unknown';
    lines.push(`Other funding involved: ${involvedLabel}`);
  }
  if (normalizedSources.length) {
    normalizedSources.forEach((entry, index) => {
      const nameLabel = entry.name || 'Unnamed funder';
      const details = [entry.statusLabel];
      if (entry.amount) {
        details.push(`Amount: ${entry.amount}`);
      } else if (entry.status !== 'confirmed') {
        details.push('Amount not confirmed');
      }
      if (entry.coverage) {
        details.push(entry.coverage);
      } else if (entry.status !== 'confirmed') {
        details.push('No confirmed coverage');
      } else {
        details.push('Coverage not specified');
      }
      if (entry.notes) {
        details.push(`Notes: ${entry.notes}`);
      }
      lines.push(`${index + 1}. ${entry.typeLabel}: ${nameLabel} - ${details.join('; ')}`);
    });
  }
  if (nwacCoverage) {
    lines.push(`NWAC funding covers: ${nwacCoverage}`);
  }
  if (notes) {
    lines.push(`Notes: ${notes}`);
  }

  if (!lines.length) {
    return normaliseString(fallbackText) || '';
  }
  return lines.join('\n');
}

async function buildAssessmentPdfSnapshot({
  caseRow,
  applicantName,
  referenceNumber,
  caseContext
}) {
  const resolvedAssessmentDate = toDateOnlyString(
    caseRow?.assessment_date_of_assessment ??
    caseRow?.date_of_assessment ??
    caseRow?.assessmentDateOfAssessment ??
    caseRow?.dateOfAssessment ??
    null
  );
  const barriers = Array.isArray(caseRow?.assessment_employment_barriers)
    ? caseRow.assessment_employment_barriers
    : [];
  const priorities = Array.isArray(caseRow?.assessment_local_area_priorities)
    ? caseRow.assessment_local_area_priorities
    : [];
  const normalizeListValue = value => (value || '').toString().trim().toLowerCase();
  const barrierSet = new Set(barriers.map(normalizeListValue));
  const prioritySet = new Set(priorities.map(normalizeListValue));
  const barriersOtherDetails = normaliseString(caseRow?.assessment_employment_barriers_other_details);
  const hasOtherBarrier = barrierSet.has('other') || Boolean(barriersOtherDetails);
  const itp = caseRow?.assessment_itp && typeof caseRow.assessment_itp === 'object' ? caseRow.assessment_itp : {};
  const wage = caseRow?.assessment_wage && typeof caseRow.assessment_wage === 'object' ? caseRow.assessment_wage : {};
  const booksMaterialsTotal = sumCurrencyValues(itp.books, itp.materials);
  const itpTotal = sumCurrencyValues(
    itp.tuition,
    itp.books,
    itp.materials,
    itp.living,
    itp.childcare,
    itp.otherAmount
  );
  const wageTotal = sumCurrencyValues(
    wage.wages,
    wage.mercs,
    wage.nonwages,
    wage.other1Amount,
    wage.other2Amount
  );
  const recommendationValue = normalizeRecommendationValue(caseRow?.assessment_recommendation);
  const previouslyFundedValue = normalizeYesNoValue(caseRow?.assessment_previous_iset);
  const esdcEligibilityValue = normalizeEsdcEligibilityValue(caseRow?.assessment_esdc_eligibility);
  const agreeCoordinatorValue = caseRow?.assessment_nwac_review ? String(caseRow.assessment_nwac_review).trim() : null;
  const interventionLabel = normaliseString(caseRow?.assessment_intervention_label);
  const interventionCode = normaliseString(caseRow?.assessment_intervention_code);
  const interventionDisplay = interventionLabel
    ? (interventionCode ? `${interventionLabel} (${interventionCode})` : interventionLabel)
    : (interventionCode || '');
  const interventionDuration = normaliseString(caseRow?.assessment_intervention_duration_days);
  const nocCode = normaliseString(caseRow?.assessment_intervention_related_noc);
  const nocVersion = normaliseString(caseRow?.assessment_intervention_related_noc_version);
  const interventionLabelLookup = new Map();
  if (interventionCode && interventionLabel) {
    interventionLabelLookup.set(interventionCode, interventionLabel);
  }

  const resolvedCaseContext =
    caseContext ||
    caseRow?.caseContext ||
    (caseRow?.case_context_json ? safeJsonParse(caseRow.case_context_json, null) : null) ||
    {};
  const otherFundingSourcesDetails = formatAssessmentOtherFundingDetailsForPdf(
    resolvedCaseContext?.assessmentOtherFunding,
    caseRow?.assessment_other_funding_details
  );
  const costSettings = resolvedCaseContext?.assessmentCostSettings || resolvedCaseContext?.assessment_cost_settings || null;
  const costTypeRaw = typeof costSettings?.type === 'string' ? costSettings.type.trim().toLowerCase() : '';
  let costType = costTypeRaw === 'recurring' ? 'recurring' : costTypeRaw === 'one_time' ? 'one_time' : null;
  if (!costType && parseCurrencyValue(caseRow?.assessment_intervention_cost_total) !== null) {
    costType = 'one_time';
  }
  const recurringPeriodRaw = costSettings?.period || costSettings?.recurringPeriod || '';
  const recurringPeriod = recurringPeriodRaw ? formatCaseStatusLabel(recurringPeriodRaw) : '';
  const recurringAmountRaw = costSettings?.amountPerPeriod ?? costSettings?.amount_per_period ?? null;
  const recurringOccurrencesRaw = costSettings?.occurrences ?? costSettings?.occurrence ?? null;
  const recurringTotalRaw =
    costSettings?.calculatedTotal ??
    costSettings?.calculated_total ??
    (costType === 'recurring' ? caseRow?.assessment_intervention_cost_total : null);
  const legacyInterventionCostTotalRaw =
    costSettings?.calculatedTotal ??
    costSettings?.calculated_total ??
    caseRow?.assessment_intervention_cost_total ??
    null;
  let interventionCostTotalRaw = legacyInterventionCostTotalRaw;

  const deliveryModeRaw = resolvedCaseContext?.assessmentDeliveryMode || resolvedCaseContext?.deliveryMode || '';
  const deliveryModeLabel = resolveDeliveryModeLabel(deliveryModeRaw);

  const proposedInterventionsRaw =
    caseRow?.assessment_proposed_interventions ??
    caseRow?.assessmentProposedInterventions ??
    caseRow?.proposed_interventions ??
    caseRow?.proposedInterventions ??
    null;
  let proposedInterventions = normalizeAssessmentProposedInterventions(proposedInterventionsRaw);
  if (!proposedInterventions.length) {
    const legacyCostLines = [];
    const pushLegacyLine = (type, amount, notes) => {
      const parsed = parseCurrencyValue(amount);
      if (!Number.isFinite(parsed) || parsed === 0) return;
      const note = normaliseString(notes);
      legacyCostLines.push({
        type,
        amount: parsed,
        notes: note || null,
        recurrence: { enabled: false }
      });
    };
    pushLegacyLine('TuitionFeesDirect', itp.tuition, 'Tuition');
    pushLegacyLine('BooksMaterialsDirect', itp.books, 'Books');
    pushLegacyLine('BooksMaterialsDirect', itp.materials, 'Materials');
    pushLegacyLine('LivingAllowance', itp.living, 'Living allowance');
    pushLegacyLine('Childcare', itp.childcare, 'Childcare');
    pushLegacyLine('OtherEligibleCost', itp.otherAmount, itp.otherLabel || 'Other');
    pushLegacyLine('WageSubsidyEmployer', wage.wages, 'Wages');
    pushLegacyLine('WageSubsidyEmployer', wage.mercs, 'MERCs');
    pushLegacyLine('WageSubsidyEmployer', wage.nonwages, 'Non-wages');
    pushLegacyLine('WageSubsidyEmployer', wage.other1Amount, wage.other1Label || 'Other');
    pushLegacyLine('WageSubsidyEmployer', wage.other2Amount, wage.other2Label || 'Other');
    if (!legacyCostLines.length) {
      const legacyTotal = parseCurrencyValue(caseRow?.assessment_intervention_cost_total);
      if (Number.isFinite(legacyTotal)) {
        legacyCostLines.push({
          type: 'OtherEligibleCost',
          amount: legacyTotal,
          notes: null,
          recurrence: { enabled: false }
        });
      }
    }
    const legacyHasValues = Boolean(
      interventionCode ||
      caseRow?.assessment_intervention_start_date ||
      caseRow?.assessment_intervention_end_date ||
      caseRow?.assessment_institution ||
      caseRow?.assessment_program_name ||
      itp.details ||
      wage.subsidyDetails ||
      nocCode ||
      nocVersion ||
      legacyCostLines.length
    );
    if (legacyHasValues) {
      const legacyIntervention = normalizeProposedIntervention({
        code: interventionCode || null,
        startDate: caseRow?.assessment_intervention_start_date || null,
        endDate: caseRow?.assessment_intervention_end_date || null,
        deliveryMode: deliveryModeRaw || null,
        institution: caseRow?.assessment_institution || null,
        programName: caseRow?.assessment_program_name || null,
        itpDetails: itp.details || null,
        wageSubsidyDetails: wage.subsidyDetails || null,
        interventionNoc: nocCode || null,
        interventionNocVersion: nocVersion || null,
        costLines: legacyCostLines
      });
      if (legacyIntervention) {
        proposedInterventions = [legacyIntervention];
      }
    }
  }
  const proposedTotal = computeProposedInterventionsTotal(proposedInterventions);
  if (proposedTotal !== null) {
    interventionCostTotalRaw = proposedTotal;
  }
  const interventionCodes = Array.from(new Set(
    [interventionCode]
      .concat(proposedInterventions.map(intervention => intervention?.code || null))
      .filter(Boolean)
  ));
  const fetchedInterventionLabels = await fetchInterventionCodeLabels(pool, interventionCodes);
  fetchedInterventionLabels.forEach((label, code) => {
    if (!interventionLabelLookup.has(code)) {
      interventionLabelLookup.set(code, label);
    }
  });
  const interventionCount = String(proposedInterventions.length);

  const childcareNeedValue = normalizeYesNoValue(caseRow?.assessment_childcare_need);
  const childcareNeedYes = childcareNeedValue === 'yes';
  const childcareNeedNo = childcareNeedValue === 'no';

  const budgetPotCode = normaliseString(caseRow?.assessment_intervention_pot_code);
  const budgetPotLabel = budgetPotCode || '';
  const postingContextLabel = normalizePostingContext(caseRow?.assessment_posting_context) || '';

  const conflictChoice = normaliseString(caseRow?.assessment_conflict_declaration_choice);
  const conflictChoiceNormalized = conflictChoice ? conflictChoice.toLowerCase() : null;
  const conflictChoiceNo = conflictChoiceNormalized === 'no_conflict';
  const conflictChoiceYes = conflictChoiceNormalized === 'conflict';

  const barrierFields = {
    barriers_none: barrierSet.has('none'),
    barriers_education: barrierSet.has('education'),
    barriers_lack_marketable_skills: barrierSet.has('lack of marketable skills'),
    barriers_lack_work_experience: barrierSet.has('lack of work experience'),
    barriers_remoteness: barrierSet.has('remoteness'),
    barriers_lack_transportation: barrierSet.has('lack of transportation'),
    barriers_economic: barrierSet.has('economic'),
    barriers_language: barrierSet.has('language'),
    barriers_lack_labour_force_attachment: barrierSet.has('lack of labour force attachment'),
    barriers_dependent_care: barrierSet.has('dependent care'),
    barriers_health: barrierSet.has('physical, emotional, or mental health'),
    barriers_other: hasOtherBarrier
  };

  const priorityFields = {
    priorities_off_reserve: prioritySet.has('off reserve'),
    priorities_single_parent_family: prioritySet.has('single parent family'),
    priorities_woman_over_45: prioritySet.has('woman over 45'),
    priorities_literacy: prioritySet.has('literacy'),
    priorities_youth: prioritySet.has('youth'),
    priorities_unskilled_clerical_service_worker: prioritySet.has('unskilled clerical/service worker'),
    priorities_no_grade_12: prioritySet.has('no grade 12'),
    priorities_unskilled_labourer: prioritySet.has('unskilled labourer'),
    priorities_non_targeted: prioritySet.has('non-targeted')
  };

  const resolvedReference =
    normaliseString(referenceNumber) ||
    normaliseString(caseRow?.tracking_id) ||
    normaliseString(caseRow?.reference_number) ||
    (caseRow?.application_id ? String(caseRow.application_id) : '');

  return {
    reference_number: resolvedReference,
    date_of_assessment: resolvedAssessmentDate,
    client_name: applicantName || '',
    conflict_declaration_signed: Boolean(caseRow?.assessment_conflict_declaration_signed),
    conflict_choice_no: conflictChoiceNo,
    conflict_choice_yes: conflictChoiceYes,
    conflict_details: caseRow?.assessment_conflict_declaration_details || '',
    client_application_overview: caseRow?.case_summary || caseRow?.overview || '',
    training_employment_goal: caseRow?.assessment_employment_goals || '',
    previously_funded_iset: previouslyFundedValue,
    previously_funded_iset_details: caseRow?.assessment_previous_iset_details || '',
    other_funding_sources_details: otherFundingSourcesDetails,
    esdc_eligibility: esdcEligibilityValue,
    proposed_interventions: proposedInterventions,
    intervention_label_lookup: Object.fromEntries(interventionLabelLookup),
    intervention_code: interventionDisplay,
    delivery_mode: deliveryModeLabel,
    intervention_start_date: toDateOnlyString(caseRow?.assessment_intervention_start_date),
    intervention_end_date: toDateOnlyString(caseRow?.assessment_intervention_end_date),
    intervention_duration_days: interventionDuration || '',
    training_institution_or_employer: caseRow?.assessment_institution || '',
    program_name: caseRow?.assessment_program_name || '',
    intervention_noc: nocCode || '',
    intervention_noc_version: nocVersion || '',
    itp_details: itp.details || '',
    wage_subsidy_details: wage.subsidyDetails || '',
    childcare_need_yes: childcareNeedYes,
    childcare_need_no: childcareNeedNo,
    childcare_funding_details: caseRow?.assessment_childcare_funding_details || '',
    intervention_cost_total_raw: interventionCostTotalRaw,
    intervention_count: interventionCount,
    cost_type: costType,
    recurring_period: recurringPeriod,
    recurring_amount_raw: recurringAmountRaw,
    recurring_occurrences: recurringOccurrencesRaw === null || typeof recurringOccurrencesRaw === 'undefined'
      ? ''
      : String(recurringOccurrencesRaw),
    recurring_total_raw: recurringTotalRaw,
    budget_pot_label: budgetPotLabel,
    posting_context: postingContextLabel,
    itp_tuition_amount: formatCurrencyValue(itp.tuition),
    itp_books_materials_amount: booksMaterialsTotal === null ? '' : formatCurrencyValue(booksMaterialsTotal),
    itp_living_allowance_amount: formatCurrencyValue(itp.living),
    itp_childcare_amount: formatCurrencyValue(itp.childcare),
    itp_other_specify: itp.otherLabel || '',
    itp_other_amount: formatCurrencyValue(itp.otherAmount),
    itp_total_cost: itpTotal === null ? '' : formatCurrencyValue(itpTotal),
    wage_wages_amount: formatCurrencyValue(wage.wages),
    wage_mercs_amount: formatCurrencyValue(wage.mercs),
    wage_non_wages_amount: formatCurrencyValue(wage.nonwages),
    wage_other_1_specify: wage.other1Label || '',
    wage_other_1_amount: formatCurrencyValue(wage.other1Amount),
    wage_other_2_specify: wage.other2Label || '',
    wage_other_2_amount: formatCurrencyValue(wage.other2Amount),
    wage_total_cost: wageTotal === null ? '' : formatCurrencyValue(wageTotal),
    recommendation: recommendationValue,
    recommendation_justification: caseRow?.assessment_justification || '',
    agree_with_coordinator: agreeCoordinatorValue,
    denial_reason: caseRow?.assessment_nwac_reason || '',
    barriers_other_specify: barriersOtherDetails || '',
    ...barrierFields,
    ...priorityFields
  };
}

async function buildAssessmentPdfFields({
  caseRow,
  applicantName,
  referenceNumber,
  caseContext,
  snapshotOverride = null,
  recommendationSignature = null,
  approvalSignature = null,
  includeAgreementSection = false,
  versionNumber = null,
  variant = 'submitted',
  previousVersionNumber = null,
  redlineBaseSnapshot = null
}) {
  const snapshot = hasAssessmentSnapshotContent(snapshotOverride)
    ? snapshotOverride
    : await buildAssessmentPdfSnapshot({
        caseRow,
        applicantName,
        referenceNumber,
        caseContext
      });
  const previousSnapshot = hasAssessmentSnapshotContent(redlineBaseSnapshot)
    ? redlineBaseSnapshot
    : null;
  const currentLookup = snapshot?.intervention_label_lookup && typeof snapshot.intervention_label_lookup === 'object'
    ? snapshot.intervention_label_lookup
    : {};
  const previousLookup = previousSnapshot?.intervention_label_lookup && typeof previousSnapshot.intervention_label_lookup === 'object'
    ? previousSnapshot.intervention_label_lookup
    : {};
  const mergedInterventionLabelLookup = new Map(Object.entries({
    ...previousLookup,
    ...currentLookup
  }));
  const currentInterventions = Array.isArray(snapshot?.proposed_interventions) ? snapshot.proposed_interventions : [];
  const previousInterventions = Array.isArray(previousSnapshot?.proposed_interventions)
    ? previousSnapshot.proposed_interventions
    : [];
  const renderedInterventions = previousSnapshot
    ? buildAssessmentInterventionDiffList({
        previousInterventions,
        currentInterventions
      })
    : currentInterventions;
  const proposedInterventionsHtml = buildAssessmentProposedInterventionsHtml({
    interventions: renderedInterventions,
    interventionLabelLookup: mergedInterventionLabelLookup,
    fallbackDeliveryModeLabel: snapshot?.delivery_mode || ''
  });
  const recommendationSignatureHtml = buildPdfSignaturePanelHtml({
    signerName: recommendationSignature?.signerName,
    signedAt: recommendationSignature?.signedAt
  });
  const approvalSignatureHtml = buildPdfSignaturePanelHtml({
    signerName: approvalSignature?.signerName,
    signedAt: approvalSignature?.signedAt
  });
  const agreementSectionHtml = includeAgreementSection
    ? buildAssessmentAgreementSectionHtml({
        agreeWithCoordinator: snapshot?.agree_with_coordinator || '',
        denialReason: snapshot?.denial_reason || '',
        approvalSignatureHtml
      })
    : '';
  const inlineField = (fieldName, { emptyValue = '&mdash;' } = {}) => {
    const currentValue = snapshot?.[fieldName] ?? '';
    if (!previousSnapshot) return currentValue;
    const previousValue = previousSnapshot?.[fieldName] ?? '';
    return {
      html: buildAssessmentInlineDiffHtml({
        currentValue,
        previousValue,
        emptyValue
      })
    };
  };
  const multilineField = fieldName => {
    const currentValue = snapshot?.[fieldName] ?? '';
    if (!previousSnapshot) return currentValue;
    const previousValue = previousSnapshot?.[fieldName] ?? '';
    return {
      html: buildAssessmentMultilineDiffHtml({
        currentValue,
        previousValue
      })
    };
  };
  const currentTotal = snapshot?.intervention_cost_total_raw === null || typeof snapshot?.intervention_cost_total_raw === 'undefined'
    ? ''
    : `$${formatCurrencyValue(snapshot.intervention_cost_total_raw)}`;
  const previousTotal = previousSnapshot?.intervention_cost_total_raw === null || typeof previousSnapshot?.intervention_cost_total_raw === 'undefined'
    ? ''
    : `$${formatCurrencyValue(previousSnapshot.intervention_cost_total_raw)}`;

  return {
    nwac_logo: getNwacLogoDataUri(),
    assessment_version_label: buildAssessmentVersionLabel({
      versionNumber,
      variant,
      previousVersionNumber
    }),
    reference_number: inlineField('reference_number', { emptyValue: '' }),
    date_of_assessment: inlineField('date_of_assessment', { emptyValue: '' }),
    client_name: inlineField('client_name', { emptyValue: '' }),
    conflict_declaration_signed: Boolean(snapshot?.conflict_declaration_signed),
    conflict_choice_no: Boolean(snapshot?.conflict_choice_no),
    conflict_choice_yes: Boolean(snapshot?.conflict_choice_yes),
    conflict_details: multilineField('conflict_details'),
    client_application_overview: multilineField('client_application_overview'),
    training_employment_goal: multilineField('training_employment_goal'),
    previously_funded_iset: snapshot?.previously_funded_iset || '',
    previously_funded_iset_details: inlineField('previously_funded_iset_details', { emptyValue: '' }),
    other_funding_sources_details: multilineField('other_funding_sources_details'),
    esdc_eligibility: snapshot?.esdc_eligibility || '',
    proposed_interventions_html: { html: proposedInterventionsHtml },
    childcare_need_yes: Boolean(snapshot?.childcare_need_yes),
    childcare_need_no: Boolean(snapshot?.childcare_need_no),
    childcare_funding_details: multilineField('childcare_funding_details'),
    intervention_cost_total: previousSnapshot
      ? { html: buildAssessmentInlineDiffHtml({ currentValue: currentTotal, previousValue: previousTotal, emptyValue: '' }) }
      : currentTotal,
    intervention_count: inlineField('intervention_count', { emptyValue: '' }),
    budget_pot_label: inlineField('budget_pot_label', { emptyValue: '' }),
    posting_context: inlineField('posting_context', { emptyValue: '' }),
    recommendation: snapshot?.recommendation || '',
    recommendation_justification: multilineField('recommendation_justification'),
    recommendation_signature_html: { html: recommendationSignatureHtml },
    agreement_section_html: { html: agreementSectionHtml },
    barriers_other_specify: inlineField('barriers_other_specify', { emptyValue: '' }),
    barriers_none: Boolean(snapshot?.barriers_none),
    barriers_education: Boolean(snapshot?.barriers_education),
    barriers_lack_marketable_skills: Boolean(snapshot?.barriers_lack_marketable_skills),
    barriers_lack_work_experience: Boolean(snapshot?.barriers_lack_work_experience),
    barriers_remoteness: Boolean(snapshot?.barriers_remoteness),
    barriers_lack_transportation: Boolean(snapshot?.barriers_lack_transportation),
    barriers_economic: Boolean(snapshot?.barriers_economic),
    barriers_language: Boolean(snapshot?.barriers_language),
    barriers_lack_labour_force_attachment: Boolean(snapshot?.barriers_lack_labour_force_attachment),
    barriers_dependent_care: Boolean(snapshot?.barriers_dependent_care),
    barriers_health: Boolean(snapshot?.barriers_health),
    barriers_other: Boolean(snapshot?.barriers_other),
    priorities_off_reserve: Boolean(snapshot?.priorities_off_reserve),
    priorities_single_parent_family: Boolean(snapshot?.priorities_single_parent_family),
    priorities_woman_over_45: Boolean(snapshot?.priorities_woman_over_45),
    priorities_literacy: Boolean(snapshot?.priorities_literacy),
    priorities_youth: Boolean(snapshot?.priorities_youth),
    priorities_unskilled_clerical_service_worker: Boolean(snapshot?.priorities_unskilled_clerical_service_worker),
    priorities_no_grade_12: Boolean(snapshot?.priorities_no_grade_12),
    priorities_unskilled_labourer: Boolean(snapshot?.priorities_unskilled_labourer),
    priorities_non_targeted: Boolean(snapshot?.priorities_non_targeted)
  };
}

