function canonicaliseAccessRole(role) {
  if (!role) return null;
  const mapped = ACCESS_MATRIX_ROLE_ALIASES[role] || role;
  return String(mapped).trim() || null;
}

function sanitiseAccessRoles(roles = []) {
  const set = new Set();
  if (Array.isArray(roles)) {
    roles.forEach(role => {
      const canonical = canonicaliseAccessRole(role);
      if (canonical) set.add(canonical);
    });
  }
  set.add('System Administrator');
  const ordered = [];
  for (const role of ACCESS_MATRIX_ROLE_ORDER) {
    if (set.has(role)) {
      ordered.push(role);
      set.delete(role);
    }
  }
  if (set.size > 0) {
    Array.from(set).sort().forEach(role => ordered.push(role));
  }
  return ordered;
}

function normaliseAccessControlRoutes(routes = {}) {
  if (!routes || typeof routes !== 'object') return {};
  const entries = Object.entries(routes)
    .filter(([route]) => typeof route === 'string' && route.trim().length > 0)
    .map(([route, allowed]) => {
      const trimmedRoute = route.trim();
      const roleList = sanitiseAccessRoles(Array.isArray(allowed) ? allowed : []);
      return [trimmedRoute, roleList];
    });
  return entries
    .sort(([a], [b]) => a.localeCompare(b))
    .reduce((acc, [route, allowed]) => {
      acc[route] = allowed;
      return acc;
    }, {});
}

function normaliseAccessControlMatrix(matrix) {
  if (!matrix || typeof matrix !== 'object') {
    return { default: 'deny', routes: {} };
  }
  const rawDefault = typeof matrix.default === 'string' ? matrix.default.trim().toLowerCase() : 'deny';
  const defaultPolicy = rawDefault === 'allow' ? 'allow' : 'deny';
  const routes = normaliseAccessControlRoutes(matrix.routes || {});
  return { default: defaultPolicy, routes };
}

function mergeAccessControlMatrixWithDefaults(matrix) {
  const base = DEFAULT_ACCESS_CONTROL_MATRIX && typeof DEFAULT_ACCESS_CONTROL_MATRIX === 'object'
    ? DEFAULT_ACCESS_CONTROL_MATRIX
    : { default: 'deny', routes: {} };
  const candidate = matrix && typeof matrix === 'object' ? matrix : {};
  return normaliseAccessControlMatrix({
    default: typeof candidate.default === 'string' ? candidate.default : base.default,
    routes: {
      ...(base.routes || {}),
      ...(candidate.routes || {}),
    },
  });
}


async function ensureEsdcPreparedHistoryEventType(connection) {
  if (ENSURED_HISTORY_EVENT_TYPE_ENUM.prepared) return;
  const executor = connection && typeof connection.query === 'function' ? connection : pool;
  if (!executor || typeof executor.query !== 'function') return;
  try {
    await executor.query(`
      ALTER TABLE esdc_participant_submission_history
      MODIFY COLUMN event_type ENUM('validated','ready','prepared','submitted','accepted','rejected') NOT NULL
    `);
    ENSURED_HISTORY_EVENT_TYPE_ENUM.prepared = true;
  } catch (err) {
    const code = err && err.code;
    if (code === 'ER_NO_SUCH_TABLE') {
      ENSURED_HISTORY_EVENT_TYPE_ENUM.prepared = true;
      return;
    }
    if (code === 'ER_TABLEACCESS_DENIED_ERROR') {
      console.warn('[esdc] insufficient privileges to alter history event_type enum:', err.message);
      return;
    }
    if (code && code.startsWith('ER_')) {
      const message = err.message || '';
      if (/duplicate/i.test(message) || /already exists/i.test(message)) {
        ENSURED_HISTORY_EVENT_TYPE_ENUM.prepared = true;
        return;
      }
    }
    if (!ENSURED_HISTORY_EVENT_TYPE_ENUM.prepared) {
      console.warn('[esdc] failed to ensure prepared event history enum:', err.message || err);
    }
  }
}

async function findPreferredActionPlanIdForCase(executor, caseId) {
  const db = executor && typeof executor.query === 'function' ? executor : pool;
  if (!db || !Number.isInteger(Number(caseId)) || Number(caseId) <= 0) return null;
  try {
    const [[row]] = await db.query(
      `
      SELECT ap.id
        FROM iset_case_action_plan ap
       WHERE ap.case_id = ?
         AND ap.archived_at IS NULL
         AND LOWER(COALESCE(ap.status, '')) <> 'archived'
       ORDER BY
         (LOWER(COALESCE(ap.status, '')) = 'active') DESC,
         ap.updated_at DESC,
         ap.id DESC
       LIMIT 1
      `,
      [caseId]
    );
    return row?.id || null;
  } catch (err) {
    console.warn('[esdc] failed to find preferred action plan for case', caseId, err?.message || err);
    return null;
  }
}

async function findEsdcSubmissionIdForCase(executor, caseId) {
  const db = executor && typeof executor.query === 'function' ? executor : pool;
  if (!db || !Number.isInteger(Number(caseId)) || Number(caseId) <= 0) return null;
  try {
    const [[row]] = await db.query(
      `
      SELECT eps.id
        FROM esdc_participant_submission eps
        LEFT JOIN iset_case_action_plan ap ON ap.id = eps.action_plan_id
       WHERE eps.case_id = ?
         AND (
           eps.action_plan_id IS NULL
           OR ap.id IS NULL
           OR (
             ap.archived_at IS NULL
             AND LOWER(COALESCE(ap.status, '')) <> 'archived'
           )
         )
       ORDER BY
         (LOWER(COALESCE(ap.status, '')) = 'active') DESC,
         (LOWER(COALESCE(ap.status, '')) IN ('closed', 'ready_to_close', 'ready-to-close', 'ready to close')) DESC,
         ap.updated_at DESC,
         eps.updated_at DESC,
         eps.id DESC
       LIMIT 1
      `,
      [caseId]
    );
    return row?.id || null;
  } catch (err) {
    console.warn('[esdc] failed to find submission for case', caseId, err?.message || err);
    return null;
  }
}

async function resolvePrimaryApplicationIdForCase(executor, caseId) {
  const db = executor && typeof executor.query === 'function' ? executor : pool;
  const numericCaseId = normalisePositiveInteger(caseId);
  if (!db || !numericCaseId) return null;
  try {
    const [[row]] = await db.query(
      `
      SELECT ${buildCasePrimaryApplicationIdSql('c')} AS application_id
        FROM iset_case c
       WHERE c.id = ?
       LIMIT 1
      `,
      [numericCaseId]
    );
    return normalisePositiveInteger(row?.application_id);
  } catch (err) {
    console.warn('[esdc] failed to resolve primary application for case', numericCaseId, err?.message || err);
    return null;
  }
}

async function resolveActionPlanApplicationId(executor, actionPlanId) {
  const db = executor && typeof executor.query === 'function' ? executor : pool;
  const numericPlanId = normalisePositiveInteger(actionPlanId);
  if (!db || !numericPlanId) return null;
  try {
    const [[row]] = await db.query(
      `SELECT application_id
         FROM iset_case_action_plan
        WHERE id = ?
        LIMIT 1`,
      [numericPlanId]
    );
    return normalisePositiveInteger(row?.application_id);
  } catch (err) {
    if (err?.code && err.code !== 'ER_BAD_FIELD_ERROR' && err.code !== 'ER_NO_SUCH_TABLE') {
      console.warn('[esdc] failed to resolve action-plan application', numericPlanId, err?.message || err);
    }
    return null;
  }
}

async function ensureEsdcParticipantSubmissionRecord(db, caseId, applicationId, actionPlanId) {
  if (!caseId) return;
  const executor = db && typeof db.query === 'function' ? db : pool;
  if (!executor) return;
  const resolvedPlanId = Number.isInteger(Number(actionPlanId)) && Number(actionPlanId) > 0
    ? Number(actionPlanId)
    : await findPreferredActionPlanIdForCase(executor, Number(caseId));
  let resolvedApplicationId = chooseIlmpApplicationId({ submissionApplicationId: applicationId });
  if (!resolvedApplicationId) {
    resolvedApplicationId = chooseIlmpApplicationId({
      actionPlanApplicationId: await resolveActionPlanApplicationId(executor, resolvedPlanId),
    });
  }
  if (!resolvedApplicationId) {
    resolvedApplicationId = chooseIlmpApplicationId({
      primaryApplicationId: await resolvePrimaryApplicationIdForCase(executor, Number(caseId)),
    });
  }
  try {
    await executor.query(
      `INSERT INTO esdc_participant_submission (
         case_id,
         action_plan_id,
         application_id,
         readiness_status,
         readiness_summary,
         warnings,
         blocking_issues,
         last_validated_at,
         submission_status,
         submitted_at,
         submitted_by_user_id,
         payload_snapshot,
         payload_storage_key,
         payload_checksum,
         rejection_reason
       ) VALUES (?, ?, ?, 'needs_review', NULL, NULL, NULL, NULL, 'pending', NULL, NULL, NULL, NULL, NULL, NULL)
       ON DUPLICATE KEY UPDATE
         application_id = VALUES(application_id),
         action_plan_id = VALUES(action_plan_id),
         readiness_status = 'needs_review',
         readiness_summary = NULL,
         warnings = NULL,
         blocking_issues = NULL,
         last_validated_at = NULL,
         submission_status = 'pending',
         submitted_at = NULL,
         submitted_by_user_id = NULL,
         payload_snapshot = NULL,
         payload_storage_key = NULL,
         payload_checksum = NULL,
         rejection_reason = NULL,
         updated_at = NOW()`,
      [caseId, resolvedPlanId || null, resolvedApplicationId || null]
    );
  } catch (err) {
    console.error('[esdc] ensure participant submission failed', err);
  }
}

async function markEsdcParticipantSubmissionNeedsReview(db, caseId, options = {}) {
  if (!caseId) return;
  const executor = db && typeof db.query === 'function' ? db : pool;
  if (!executor) return;
  const { resetSnapshot = true, resetSubmissionStatus = true } = options;
  const assignments = [
    "readiness_status = 'needs_review'",
    'readiness_summary = NULL',
    'warnings = NULL',
    'blocking_issues = NULL',
    'last_validated_at = NULL',
    'updated_at = NOW()'
  ];
  if (resetSnapshot) {
    assignments.push(
      'payload_snapshot = NULL',
      'payload_storage_key = NULL',
      'payload_checksum = NULL',
      'rejection_reason = NULL'
    );
  }
  if (resetSubmissionStatus) {
    assignments.push(
      "submission_status = 'pending'",
      'submitted_at = NULL',
      'submitted_by_user_id = NULL'
    );
  }
  try {
    const sql = `
      UPDATE esdc_participant_submission eps
      LEFT JOIN iset_case_action_plan ap ON ap.id = eps.action_plan_id
         SET ${assignments.map(assignment => `eps.${assignment}`).join(', ')}
       WHERE eps.case_id = ?
         AND (
           eps.action_plan_id IS NULL
           OR ap.id IS NULL
           OR (
             ap.archived_at IS NULL
             AND LOWER(COALESCE(ap.status, '')) <> 'archived'
           )
         )`;
    await executor.query(sql, [caseId]);
  } catch (err) {
    console.error('[esdc] mark participant submission needs review failed', err);
  }
}

