function formatCaseStatusLabel(value) {
  if (!value) return '';
  return String(value)
    .trim()
    .replace(/[_-]+/g, ' ')
    .replace(/\b\w/g, char => char.toUpperCase());
}

function normaliseString(value) {
  if (value === null || typeof value === 'undefined') return null;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    return trimmed.length ? trimmed : null;
  }
  if (typeof value === 'number' || typeof value === 'boolean') {
    return String(value);
  }
  if (Array.isArray(value)) {
    for (const entry of value) {
      const candidate = normaliseString(entry);
      if (candidate) return candidate;
    }
    return null;
  }
  if (typeof value === 'object') {
    if (value && typeof value.value !== 'undefined') {
      return normaliseString(value.value);
    }
    if (value && typeof value.text !== 'undefined') {
      return normaliseString(value.text);
    }
    try {
      return normaliseString(JSON.stringify(value));
    } catch {
      return null;
    }
  }
  return null;
}

function cleanSin(raw) {
  const str = normaliseString(raw);
  if (!str) return null;
  const digits = str.replace(/\D/g, '');
  return digits.length === 0 ? null : digits;
}

function maskSinForDisplay(raw) {
  const digits = cleanSin(raw);
  if (!digits) return null;
  const tail = digits.slice(-3).padStart(3, '*');
  return `*** *** ${tail}`;
}

function isValidSin(digits) {
  if (!/^\d{9}$/.test(digits)) return false;
  let sum = 0;
  for (let i = 0; i < digits.length; i += 1) {
    let digit = Number(digits[i]);
    if (i % 2 === 1) {
      digit *= 2;
      if (digit > 9) digit -= 9;
    }
    sum += digit;
  }
  return sum % 10 === 0;
}

function hashSin(digits) {
  if (!digits) return null;
  try {
    return crypto.createHash('sha256').update(digits).digest('hex');
  } catch (err) {
    console.warn('[sin:hash] failed to hash SIN:', err?.message || err);
    return null;
  }
}

function parseDate(value) {
  if (!value && value !== 0) return null;
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? null : value;
  }
  const str = normaliseString(value);
  if (!str) return null;
  // Accept YYYY-MM-DD, YYYY/MM/DD, DD/MM/YYYY, ISO 8601
  const normalized = str.replace(/\//g, '-');
  const fromParts = (yyyy, mm, dd) => {
    const year = Number(yyyy);
    const month = Number(mm);
    const day = Number(dd);
    if (!Number.isInteger(year) || !Number.isInteger(month) || !Number.isInteger(day)) return null;
    if (month < 1 || month > 12) return null;
    const maxDay = new Date(Date.UTC(year, month, 0)).getUTCDate();
    if (day < 1 || day > maxDay) return null;
    return new Date(Date.UTC(year, month - 1, day));
  };
  const isoMatch = normalized.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (isoMatch) return fromParts(isoMatch[1], isoMatch[2], isoMatch[3]);
  const parts = normalized.split('-');
  if (parts.length === 3 && parts[0].length === 2 && parts[2].length === 4) {
    const [dd, mm, yyyy] = parts;
    return fromParts(yyyy, mm, dd);
  }
  const date = new Date(normalized);
  if (!Number.isNaN(date.getTime())) return date;
  return null;
}

function normalizeNocDigits(value) {
  if (value === null || typeof value === 'undefined') return '';
  return String(value).replace(/\D/g, '');
}

async function isValidNocCodeForVersion(connection, nocCode, nocVersion) {
  const version = nocVersion === null || typeof nocVersion === 'undefined'
    ? ''
    : String(nocVersion).trim();
  const code = normalizeNocDigits(nocCode);
  if (!version || !code) return false;
  if (version !== '2016' && version !== '2021') return false;
  const queryable = connection || pool;
  try {
    const [[row]] = await queryable.query(
      `SELECT id
         FROM noc_code
        WHERE is_active = 1
          AND version_code = ?
          AND code = ?
        LIMIT 1`,
      [version, code]
    );
    return Boolean(row);
  } catch (err) {
    if (err?.code === 'ER_NO_SUCH_TABLE') {
      console.warn('[esdc] noc_code table not found; skipping strict NOC validity check');
      return true;
    }
    throw err;
  }
}

function calculateAge(date) {
  if (!date) return null;
  const today = new Date();
  let age = today.getFullYear() - date.getFullYear();
  const monthDiff = today.getMonth() - date.getMonth();
  if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < date.getDate())) {
    age -= 1;
  }
  return age;
}

