  const actorIdRaw = req?.auth?.sub ?? req?.auth?.id ?? req?.auth?.user_id ?? null;
  const regionRaw = req?.staffProfile?.region_id ?? req?.auth?.regionId ?? null;
  const regionId = Number.parseInt(regionRaw, 10);
