const CASE_STATUS_DORMANT = CASE_STATUS_DERIVED_VALUES.dormant;
const CASE_STATUS_READY_TO_CLOSE = CASE_STATUS_DERIVED_VALUES.readyToClose;
const CASE_STATUS_TERMINAL_VALUES_LOWER = CASE_STATUS_TERMINAL_VALUES.map(v => v.toLowerCase());
const READY_TO_CLOSE_EXCLUDED_STATUSES = CASE_STATUS_TERMINAL_VALUES_LOWER.filter(
  status => status !== CASE_STATUS_READY_TO_CLOSE
);
const FOLLOW_UP_WINDOW_DAYS = 7;
const ILMP_BLOCKED_STATUS = 'blocked';
const CASE_STATUS_HOLD_VALUES_LOWER = CASE_STATUS_HOLD_VALUES.map(v => v.toLowerCase());
const CASE_STATUS_EXCLUDED_FOR_ASSESSMENT_LOWER = CASE_STATUS_EXCLUDED_FOR_ASSESSMENT.map(v => v.toLowerCase());
const CASE_STATUS_AWAITING_DECISION_LOWER = CASE_STATUS_AWAITING_DECISION.map(v => v.toLowerCase());
const DUE_SOON_THRESHOLD_HOURS = 7 * 24;
const DUE_TODAY_THRESHOLD_HOURS = 24;
const INACTIVITY_THRESHOLD_DAYS = 30;
const ACTION_PLAN_ACTIVE_STATUS = 'active';
const APPLICATION_STATUS_HOLD_VALUES = [
  'docs_requested',
  'docs requested',
  'action_required',
  'action required',
  'action required (docs requested)',
  'closure_notice',
  'closure notice',
  'pending info',
  'pending information',
  'info requested',
  'information requested',
  'on hold',
  'on_hold',
];
const APPLICATION_STATUS_HOLD_VALUES_LOWER = APPLICATION_STATUS_HOLD_VALUES.map(v => v.toLowerCase());
const APPLICATION_COMPLETE_STATUSES = new Set(TERMINAL_APPLICATION_STATUSES);
const APPLICATION_DECISION_STATUSES = new Set(['pending_approval', 'decision_ready']);
const APPLICATION_ASSESSMENT_STATUSES = new Set([
  'in_review',
  'in review',
  'docs_requested',
  'docs requested',
  'action_required',
  'action required',
  'action required (docs requested)',
  'closure_notice',
  'closure notice',
  'pending info',
  'pending information',
  'info requested',
  'information requested',
  'on hold',
  'on_hold'
]);

function isAssessmentEligibilityPending(value) {
  return !normaliseString(value);
}

function isAssignedStaffProfileId(value) {
  const numeric = Number(value);
  return Number.isFinite(numeric) && numeric > 0;
}

function getApplicationSlaStageKey({ applicationStatus, assignedToUserId, assessmentEligibility }) {
  const statusKey = normaliseApplicationStatusValue(applicationStatus);
  if (statusKey && TERMINAL_APPLICATION_STATUSES.has(statusKey)) {
    return null;
  }
  if (statusKey === 'on_hold') {
    return null;
  }
  if (statusKey && APPLICATION_DECISION_STATUSES.has(statusKey)) {
    return 'program_decision';
  }
  const assigned = isAssignedStaffProfileId(assignedToUserId);
  if (
    assigned &&
    isAssessmentEligibilityPending(assessmentEligibility) &&
    (statusKey === 'submitted' || APPLICATION_ASSESSMENT_STATUSES.has(statusKey))
  ) {
    return 'ei_status_verification';
  }
  if (statusKey && (APPLICATION_ASSESSMENT_STATUSES.has(statusKey) || (statusKey === 'submitted' && assigned))) {
    return 'assessment';
  }
  return 'assignment';
}

function buildSlaStageTargetHoursMap(targets = []) {
  const stageTargets = new Map();
  for (const row of targets) {
    if (!row || row.applies_to_role) continue;
    stageTargets.set(row.stage_key, Number(row.target_hours) || 0);
  }
  return stageTargets;
}

function getSlaTargetHours(stageKey, stageTargets) {
  if (stageTargets && stageTargets.has(stageKey)) return stageTargets.get(stageKey);
  const fallback = SLA_STAGE_PLACEHOLDER.find(item => item.stage_key === stageKey);
  return fallback ? Number(fallback.target_hours) || 0 : 0;
}

function computeApplicationSlaTiming({
  applicationStatus,
  assignedToUserId,
  assessmentEligibility,
  submittedAt,
  createdAt,
}, stageTargets, nowMs = Date.now()) {
  const stageKey = getApplicationSlaStageKey({
    applicationStatus,
    assignedToUserId,
    assessmentEligibility,
  });
  if (!stageKey) {
    return { stageKey: null, targetHours: 0, diffHours: null, diffDays: null, dueAt: null };
  }
  const targetHours = getSlaTargetHours(stageKey, stageTargets);
  if (!targetHours || Number.isNaN(targetHours)) {
    return { stageKey, targetHours: 0, diffHours: null, diffDays: null, dueAt: null };
  }
  const baseValue = submittedAt || createdAt;
  const baseDate = baseValue ? new Date(baseValue) : null;
  if (!baseDate || Number.isNaN(baseDate.getTime())) {
    return { stageKey, targetHours, diffHours: null, diffDays: null, dueAt: null };
  }
  const dueAt = new Date(baseDate.getTime() + targetHours * 3600000);
  const diffHours = (dueAt.getTime() - nowMs) / 3600000;
  const diffDays = Math.floor((dueAt.getTime() - nowMs) / 86400000);
  return { stageKey, targetHours, diffHours, diffDays, dueAt };
}


const normaliseCaseStatusValue = value => {
  if (value === null || typeof value === 'undefined') {
    return null;
  }
  const trimmed = String(value).trim().toLowerCase();
  return trimmed || null;
};
const normaliseCaseLifecycleStatusValue = (value, { preserveUnknown = false } = {}) => {
  const key = normaliseCaseStatusValue(value);
  if (!key) return null;
  switch (key) {
    case 'pending_approval':
    case 'submitted':
    case 'in_review':
    case 'open':
    case 'pending':
    case CASE_STATUS_DERIVED_VALUES.intake:
      return CASE_STATUS_DERIVED_VALUES.intake;
    case 'approved':
    case CASE_STATUS_DERIVED_VALUES.initiated:
      return CASE_STATUS_DERIVED_VALUES.initiated;
    case CASE_STATUS_DERIVED_VALUES.active:
      return CASE_STATUS_DERIVED_VALUES.active;
    case CASE_STATUS_DERIVED_VALUES.dormant:
      return CASE_STATUS_DERIVED_VALUES.dormant;
    case CASE_STATUS_DERIVED_VALUES.readyToClose:
      return CASE_STATUS_DERIVED_VALUES.readyToClose;
    case 'closed':
    case 'completed':
    case 'cancelled':
    case 'withdrawn':
    case 'rejected':
      return CASE_STATUS_DERIVED_VALUES.closed;
    case CASE_STATUS_DERIVED_VALUES.archived:
      return CASE_STATUS_DERIVED_VALUES.archived;
    default:
      return preserveUnknown ? key : null;
  }
};
const deriveCaseClosureReason = (value, currentClosureReason = null) => {
  const key = normaliseCaseStatusValue(value);
  if (!key) return currentClosureReason || null;
  if (key === 'withdrawn') return 'withdrawn';
  if (['closed', 'completed', 'cancelled'].includes(key)) return 'administrative';
  if (key === 'rejected') return 'application_denied';
  return currentClosureReason || null;
};
function buildCaseStatusPersistence(status, current = {}) {
  const normalizedStatus = normaliseCaseStatusValue(status);
  if (!normalizedStatus) {
    return {
      legacyStatus: current.legacyStatus || null,
      lifecycleStatus: current.lifecycleStatus || null,
      closureReason: current.closureReason || null,
    };
  }
  const lifecycleStatus =
    normaliseCaseLifecycleStatusValue(normalizedStatus, { preserveUnknown: true }) ||
    current.lifecycleStatus ||
    null;
  return {
    legacyStatus: lifecycleStatus,
    lifecycleStatus,
    closureReason:
      lifecycleStatus === CASE_STATUS_DERIVED_VALUES.closed || lifecycleStatus === CASE_STATUS_DERIVED_VALUES.archived
        ? deriveCaseClosureReason(normalizedStatus, current.closureReason)
        : null,
  };
}
function buildApplicationLifecycleStatusExpr(applicationAlias = 'a') {
  const normalizedStatusExpr = `REPLACE(REPLACE(LOWER(TRIM(COALESCE(${applicationAlias}.status, ''))), '-', '_'), ' ', '_')`;
  return `
    CASE
      WHEN LOWER(COALESCE(${applicationAlias}.lifecycle_status, '')) <> '' THEN LOWER(COALESCE(${applicationAlias}.lifecycle_status, ''))
      WHEN ${normalizedStatusExpr} IN ('submitted', 'active', 'open', 'pending')
        THEN 'submitted'
      WHEN ${normalizedStatusExpr} = 'in_review'
        THEN 'in_review'
      WHEN ${normalizedStatusExpr} IN ('docs_requested', 'closure_notice', 'on_hold')
        THEN 'awaiting_applicant'
      WHEN ${normalizedStatusExpr} IN ('pending_approval', 'decision_ready')
        THEN 'pending_decision'
      WHEN ${normalizedStatusExpr} IN ('approved', 'rejected', 'declined')
        THEN 'decision_recorded'
      WHEN ${normalizedStatusExpr} IN ('completed', 'closed', 'withdrawn', 'cancelled')
        THEN 'closed'
      WHEN ${normalizedStatusExpr} = 'archived'
        THEN 'archived'
      ELSE ${normalizedStatusExpr}
    END
  `.replace(/\s+/g, ' ').trim();
}
function buildApplicationAwaitingReasonExpr(applicationAlias = 'a') {
  const normalizedStatusExpr = `REPLACE(REPLACE(LOWER(TRIM(COALESCE(${applicationAlias}.status, ''))), '-', '_'), ' ', '_')`;
  return `
    CASE
      WHEN LOWER(COALESCE(${applicationAlias}.awaiting_reason, '')) <> '' THEN LOWER(COALESCE(${applicationAlias}.awaiting_reason, ''))
      WHEN ${normalizedStatusExpr} = 'docs_requested'
        THEN 'documents'
      WHEN ${normalizedStatusExpr} = 'closure_notice'
        THEN 'closure_response'
      WHEN ${normalizedStatusExpr} = 'on_hold'
        THEN 'on_hold'
      ELSE 'none'
    END
  `.replace(/\s+/g, ' ').trim();
}
function buildCaseLifecycleStatusExpr(caseAlias = 'c') {
  return `
    CASE
      WHEN LOWER(COALESCE(${caseAlias}.lifecycle_status, '')) <> '' THEN LOWER(COALESCE(${caseAlias}.lifecycle_status, ''))
      WHEN REPLACE(REPLACE(LOWER(TRIM(COALESCE(${caseAlias}.status, ''))), '-', '_'), ' ', '_') IN ('pending_approval', 'submitted', 'in_review', 'open', 'pending', 'intake')
        THEN 'intake'
      WHEN REPLACE(REPLACE(LOWER(TRIM(COALESCE(${caseAlias}.status, ''))), '-', '_'), ' ', '_') IN ('approved', 'initiated')
        THEN 'initiated'
      WHEN REPLACE(REPLACE(LOWER(TRIM(COALESCE(${caseAlias}.status, ''))), '-', '_'), ' ', '_') = 'active'
        THEN 'active'
      WHEN REPLACE(REPLACE(LOWER(TRIM(COALESCE(${caseAlias}.status, ''))), '-', '_'), ' ', '_') = 'dormant'
        THEN 'dormant'
      WHEN REPLACE(REPLACE(LOWER(TRIM(COALESCE(${caseAlias}.status, ''))), '-', '_'), ' ', '_') = 'ready_to_close'
        THEN 'ready_to_close'
      WHEN REPLACE(REPLACE(LOWER(TRIM(COALESCE(${caseAlias}.status, ''))), '-', '_'), ' ', '_') IN ('closed', 'completed', 'cancelled', 'withdrawn', 'rejected')
        THEN 'closed'
      WHEN REPLACE(REPLACE(LOWER(TRIM(COALESCE(${caseAlias}.status, ''))), '-', '_'), ' ', '_') = 'archived'
        THEN 'archived'
      ELSE REPLACE(REPLACE(LOWER(TRIM(COALESCE(${caseAlias}.status, ''))), '-', '_'), ' ', '_')
    END
  `.replace(/\s+/g, ' ').trim();
}

async function recomputeCaseStatus(caseId, connection = null, options = {}) {
  const allowReopenFinal = options.allowReopenFinal === true;
  const numericCaseId = Number(caseId);
  if (!Number.isInteger(numericCaseId) || numericCaseId <= 0) {
    return { status: null, previousStatus: null, changed: false };
  }

  let conn = connection;
  let shouldRelease = false;
  if (!conn) {
    conn = await pool.getConnection();
    shouldRelease = true;
  }

  try {
    const [[caseRow]] = await conn.query(
      `SELECT c.id,
              c.status,
              c.lifecycle_status,
              c.closure_reason,
        a.id AS application_id
         FROM iset_case c
         ${buildCasePrimaryApplicationJoinSql('c', 'a')}
        WHERE c.id = ?
        LIMIT 1`,
      [numericCaseId]
    );
    if (!caseRow) {
      return { status: null, previousStatus: null, changed: false };
    }

    const currentStatus =
      normaliseCaseLifecycleStatusValue(caseRow.lifecycle_status || caseRow.status, { preserveUnknown: true }) ||
      normaliseCaseStatusValue(caseRow.status);
    const currentClosureReason = normaliseString(caseRow.closure_reason) || null;
    if (!allowReopenFinal && currentStatus && CASE_STATUS_FINAL_SET.has(currentStatus)) {
      return { status: currentStatus, previousStatus: currentStatus, changed: false };
    }

    const [[planSummary]] = await conn.query(
      `SELECT
          SUM(CASE WHEN status = 'active' THEN 1 ELSE 0 END) AS active_count,
          SUM(CASE WHEN status = 'closed' THEN 1 ELSE 0 END) AS closed_count,
          SUM(CASE WHEN status = 'archived' THEN 1 ELSE 0 END) AS archived_count,
          SUM(CASE WHEN status = 'draft' THEN 1 ELSE 0 END) AS draft_count,
          COUNT(*) AS total_count
        FROM iset_case_action_plan
        WHERE case_id = ?`,
      [numericCaseId]
    );

    const activePlans = Number(planSummary?.active_count || 0);
    const closedPlans = Number(planSummary?.closed_count || 0) + Number(planSummary?.archived_count || 0);
    const draftPlans = Number(planSummary?.draft_count || 0);
    const totalPlans = Number(planSummary?.total_count || 0);

    const appStatusExpr = buildNormalisedStatusSql('a.status');
    const appLifecycleExpr = buildNormalisedStatusSql('a.lifecycle_status');
    const appClosureReasonExpr = buildNormalisedStatusSql('a.closure_reason');
    const appDecisionOutcomeExpr = buildNormalisedStatusSql('a.decision_outcome');
    const [[applicationSummary]] = await conn.query(
      `SELECT
          COUNT(*) AS total_count,
          SUM(CASE WHEN ${buildApplicationTerminalRankSql('a')} = 0 THEN 1 ELSE 0 END) AS open_count,
          SUM(CASE WHEN ${appStatusExpr} = 'withdrawn' OR ${appClosureReasonExpr} = 'withdrawn' THEN 1 ELSE 0 END) AS withdrawn_count,
          SUM(CASE WHEN ${appStatusExpr} = 'archived' OR ${appLifecycleExpr} = 'archived' THEN 1 ELSE 0 END) AS archived_count,
          SUM(CASE WHEN ${appStatusExpr} IN ('rejected', 'declined', 'denied') OR ${appDecisionOutcomeExpr} = 'denied' THEN 1 ELSE 0 END) AS denied_count
        FROM iset_application a
        WHERE a.case_id = ?`,
      [numericCaseId]
    );
    const totalApplications = Number(applicationSummary?.total_count || 0);
    const openApplications = Number(applicationSummary?.open_count || 0);
    const withdrawnApplications = Number(applicationSummary?.withdrawn_count || 0);
    const archivedApplications = Number(applicationSummary?.archived_count || 0);
    const deniedApplications = Number(applicationSummary?.denied_count || 0);

    let nextStatus = currentStatus;
    let nextClosureReason = currentClosureReason;

    if (activePlans > 0) {
      nextStatus = CASE_STATUS_DERIVED_VALUES.active;
      nextClosureReason = null;
    } else if (closedPlans > 0) {
      nextStatus = CASE_STATUS_DERIVED_VALUES.dormant;
      nextClosureReason = null;
    } else if (draftPlans > 0) {
      nextStatus = CASE_STATUS_DERIVED_VALUES.initiated;
      nextClosureReason = null;
    } else if (totalPlans > 0) {
      nextStatus = CASE_STATUS_DERIVED_VALUES.initiated;
      nextClosureReason = null;
    } else if (totalApplications > 0 && openApplications === 0) {
      nextStatus = archivedApplications === totalApplications
        ? CASE_STATUS_DERIVED_VALUES.archived
        : CASE_STATUS_DERIVED_VALUES.closed;
      if (withdrawnApplications === totalApplications) {
        nextClosureReason = 'withdrawn';
      } else if (deniedApplications > 0) {
        nextClosureReason = 'application_denied';
      } else {
        nextClosureReason = 'administrative';
      }
    } else if (CASE_STATUS_INITIATED_SEEDS.has(currentStatus)) {
      nextStatus = CASE_STATUS_DERIVED_VALUES.initiated;
      nextClosureReason = null;
    } else if (CASE_STATUS_PENDING_SEEDS.has(currentStatus)) {
      nextStatus = CASE_STATUS_DERIVED_VALUES.intake;
      nextClosureReason = null;
    } else if (!currentStatus) {
      nextStatus = CASE_STATUS_DERIVED_VALUES.intake;
      nextClosureReason = null;
    } else {
      // Preserve unrecognised states to avoid accidental downgrade.
      nextStatus = currentStatus;
      nextClosureReason = currentClosureReason;
    }

    const shouldPersistClosureReason =
      nextStatus === CASE_STATUS_DERIVED_VALUES.closed ||
      nextStatus === CASE_STATUS_DERIVED_VALUES.archived;
    const closureReasonToPersist = shouldPersistClosureReason ? nextClosureReason : null;

    if (
      (nextStatus === currentStatus || !nextStatus) &&
      closureReasonToPersist === currentClosureReason
    ) {
      return { status: currentStatus, previousStatus: currentStatus, changed: false };
    }

    await conn.query(
      `UPDATE iset_case
          SET status = ?,
              lifecycle_status = ?,
              closure_reason = ?,
              closed_at = CASE
                WHEN ? IN ('closed', 'archived') THEN COALESCE(closed_at, NOW())
                ELSE closed_at
              END,
              updated_at = NOW()
        WHERE id = ?`,
      [nextStatus, nextStatus, closureReasonToPersist, nextStatus, numericCaseId]
    );

    return { status: nextStatus, previousStatus: currentStatus, changed: true };
  } finally {
    if (shouldRelease && conn) {
      conn.release();
    }
  }
}

async function buildClientProfileFromApplication(connection, applicationId, { forUpdate = false } = {}) {
  const applicationPayload = await readApplicationPayload(connection, applicationId, { forUpdate });
  if (!applicationPayload) return null;

  let submissionRow = null;
  const submissionId = applicationPayload.row?.submission_id || null;
  if (submissionId) {
    const [[submission]] = await connection.query(
      'SELECT * FROM iset_application_submission WHERE id = ? LIMIT 1',
      [submissionId]
    );
    submissionRow = submission || null;
  }

  const payload = applicationPayload.payload || {};
  const answers = payload.answers || {};
  const context = {
    payload,
    answers,
    submissionRow
  };

  const clamp = (value, limit) => {
    const normalised = normaliseString(value);
    if (!normalised) return null;
    return normalised.length > limit ? normalised.slice(0, limit) : normalised;
  };

  const firstName = clamp(extractFirstName(context) || extractPreferredName(context), 128) || 'Unknown';
  const lastName = clamp(extractLastName(context), 128) || 'Client';
  const initials = clamp(extractMiddleInitials(context), 16);
  const preferredName = clamp(extractPreferredName(context), 128);
  const dob = toDateOnly(extractDob(context));
  const gender = clamp(extractGender(context), 32);
  const aboriginalGroup = clamp(extractIndigenousIdentity(context), 64);
  const sinDigits = cleanSin(extractSin(context));
  const sinHash = sinDigits && isValidSin(sinDigits) ? hashSin(sinDigits) : null;

  const addressStructure = extractAddress(context);
  const sanitise = value => {
    const normalised = normaliseString(value);
    return normalised || null;
  };

  const address = addressStructure
    ? {
        line1: sanitise(addressStructure.line1),
        line2: sanitise(addressStructure.line2),
        city: sanitise(addressStructure.city),
        province: sanitise(addressStructure.province),
        postalCode: sanitise(addressStructure.postalCode)
      }
    : null;

  const contactDetailsRaw = extractContactDetails(context);
  const contactEmailNormalized = contactDetailsRaw?.email
    ? sanitise(contactDetailsRaw.email)?.toLowerCase() || null
    : null;
  const contact = contactDetailsRaw
    ? {
        email: sanitise(contactDetailsRaw.email),
        emailNormalized: contactEmailNormalized,
        phone: sanitise(contactDetailsRaw.phone),
        alternatePhone: sanitise(contactDetailsRaw.alternatePhone),
        mailingAddress: sanitise(contactDetailsRaw.mailingAddress),
        homeCommunity: sanitise(contactDetailsRaw.homeCommunity)
      }
    : null;

  const referenceNumber =
    sanitise(payload?.submission_snapshot?.reference_number) ||
    sanitise(submissionRow?.reference_number) ||
    null;

  const addressPayload = {
    source: 'iset_application',
    extractedAt: new Date().toISOString(),
    applicationId,
    submissionId,
    referenceNumber,
    preferredName,
    address,
    contact,
    sinHash
  };

  return {
    firstName,
    lastName,
    initials,
    dob,
    gender,
    aboriginalGroup,
    emailNormalized: contactEmailNormalized,
    sinHash,
    addressJson: JSON.stringify(addressPayload)
  };
}

function isDeniedReportingCaseContext(caseContext) {
  const context =
    caseContext && typeof caseContext === 'object'
      ? caseContext
      : safeJsonParse(caseContext, null);
  const reportingSeedSource = normaliseString(context?.reportingSeedSource);
  const reportingSeedSourceKey = reportingSeedSource ? reportingSeedSource.toLowerCase() : null;
  return Boolean(
    context?.reportingOnlyDenied === true ||
    context?.reportingOnlyDeniedIneligible === true ||
    context?.reportingOnlyWithdrawal === true ||
    REPORTING_ARTIFACT_METADATA_SOURCES.includes(reportingSeedSourceKey)
  );
}

function resolveReportingArtifactTrigger(value, context = null) {
  const normalized = normaliseString(value || context?.reportingTrigger || null);
  const key = normalized ? normalized.toLowerCase().replace(/[\s-]+/g, '_') : null;
  const contextSource = normaliseString(context?.reportingSeedSource);
  const contextSourceKey = contextSource ? contextSource.toLowerCase() : null;
  if (
    key === 'withdrawal' ||
    key === 'withdrawn' ||
    context?.reportingOnlyWithdrawal === true ||
    contextSourceKey === WITHDRAWN_REPORTING_SOURCE
  ) {
    return 'withdrawal';
  }
  return 'denial';
}

function resolveReportingArtifactConfig(trigger) {
  return trigger === 'withdrawal'
    ? {
        source: WITHDRAWN_REPORTING_SOURCE,
        planName: WITHDRAWN_REPORTING_PLAN_NAME,
        note: WITHDRAWN_REPORTING_NOTE,
        dateContextKey: 'reportingWithdrawnAt',
        dateMetadataKey: 'withdrawalDate',
      }
    : {
        source: DENIED_REPORTING_SOURCE,
        planName: DENIED_REPORTING_PLAN_NAME,
        note: DENIED_REPORTING_NOTE,
        dateContextKey: 'reportingDeniedAt',
        dateMetadataKey: 'denialDate',
      };
}

function resolveFundingDecisionReasonCode(caseContext, applicationId = null) {
  const context =
    caseContext && typeof caseContext === 'object'
      ? caseContext
      : safeJsonParse(caseContext, null);
  const assessmentContext = resolveApplicationAssessmentCaseContext(context, applicationId);
  const normalized = normaliseString(assessmentContext?.[FUNDING_DECISION_REASON_CODE_KEY]);
  return normalized ? normalized.toLowerCase() : null;
}

function mapEducationLevelToIlmpCode(value) {
  const normalized = normaliseString(value);
  if (!normalized) return null;
  const key = normalized.toLowerCase();
  if (ILMP_EDUCATION_LEVEL_CODE_MAP[key]) {
    return ILMP_EDUCATION_LEVEL_CODE_MAP[key];
  }
  const looseKey = key.replace(/[_-]+/g, ' ').replace(/\s+/g, ' ').trim();
  return ILMP_EDUCATION_LEVEL_CODE_MAP[looseKey] || null;
}

function mapProvinceToIlmpCode(value) {
  const normalized = normaliseString(value);
  if (!normalized) return null;
  const key = normalized.toLowerCase();
  const provinceCode = PROVINCE_CODE_MAP[key] || normalized.toUpperCase();
  return ILMP_PROVINCE_NUMERIC_CODE_MAP[provinceCode] || null;
}

function mapYesNoBooleanToIlmpCode(value) {
  if (value === null || typeof value === 'undefined') return null;
  const coerced = coerceBoolean(value);
  if (coerced === null) return null;
  return coerced ? '1' : '0';
}

function mapChildcareFundingToIlmpCode(value) {
  const normalized = normaliseString(value);
  if (!normalized) return null;
  const key = normalized.toLowerCase();
  return ILMP_CHILDCARE_FUNDING_CODE_MAP[key] || null;
}

function mapBarrierLabelsToIlmpCodes(labels = []) {
  return mapIlmpBarrierCodes(labels);
}

function firstDefinedValue(...values) {
  for (const value of values) {
    if (value !== null && typeof value !== 'undefined' && String(value).trim() !== '') {
      return value;
    }
  }
  return null;
}

function toMysqlDateTimeString(value) {
  const dateOnly = toDateOnlyString(value);
  if (!dateOnly) return null;
  return `${dateOnly} 00:00:00`;
}

function buildDeniedReportingCaseContext({
  existingCaseContext = null,
  payload = {},
  answers = {},
  applicationId = null,
  clientId = null,
  reportingDate = null,
  denialDate = null,
  denialReasonCode = null,
  reportingTrigger = 'denial',
} = {}) {
  const normalizedReportingTrigger = resolveReportingArtifactTrigger(reportingTrigger, existingCaseContext);
  const reportingConfig = resolveReportingArtifactConfig(normalizedReportingTrigger);
  const currentPayload = payload && typeof payload === 'object' ? payload : {};
  const currentAnswers = answers && typeof answers === 'object' ? answers : {};
  const currentPersonal =
    currentPayload.personal && typeof currentPayload.personal === 'object'
      ? clonePayload(currentPayload.personal)
      : null;
  const extractionContext = { payload: currentPayload, answers: currentAnswers, caseContext: {} };
  const address = extractAddress(extractionContext);
  const contact = extractContactDetails(extractionContext);
  const disability = extractDisabilityInfo(extractionContext) || {};
  const clientStatus = extractClientStatusDetails(extractionContext) || {};
  const dependentChildren = extractDependentChildrenInfo(extractionContext) || {};
  const normalizedDenialReason = (normaliseString(denialReasonCode) || '').toLowerCase() || null;
  const resolvedReportingDate = toDateOnlyString(
    reportingDate ||
    denialDate ||
    existingCaseContext?.[reportingConfig.dateContextKey] ||
    existingCaseContext?.reportingDeniedAt ||
    existingCaseContext?.reportingWithdrawnAt ||
    existingCaseContext?.reportingSeededAt ||
    null
  );
  const nextContextPatch = {
    excludeFromCaseworkQueues: true,
    reportingCorrectionAllowed: true,
    reportingTrigger: normalizedReportingTrigger,
    reportingSeedSource: reportingConfig.source,
    reportingSeededAt: existingCaseContext?.reportingSeededAt || new Date().toISOString(),
    reportingLastSyncedAt: new Date().toISOString(),
    [reportingConfig.dateContextKey]: resolvedReportingDate,
    applicationId: applicationId || null,
    clientId: clientId || null,
    applicationAnswers: Object.keys(currentAnswers).length ? currentAnswers : null,
    applicationPersonal:
      currentPersonal && Object.keys(currentPersonal).length ? currentPersonal : null,
    firstName: extractFirstName(extractionContext),
    lastName: extractLastName(extractionContext),
    preferredName: extractPreferredName(extractionContext),
    gender: extractGender(extractionContext),
    sin: extractSin(extractionContext),
    socialInsuranceNumber: extractSin(extractionContext),
    dateOfBirth: toDateOnlyString(extractDob(extractionContext)),
    indigenousIdentity: extractIndigenousIdentity(extractionContext),
    address: address ? pruneNullish(address) || null : null,
    emailPrimary: contact?.email || null,
    phonePrimary: contact?.phone || null,
    phoneAlt: contact?.alternatePhone || null,
    mailingAddress: contact?.mailingAddress || null,
    homeCommunity: contact?.homeCommunity || null,
    languageSpoken: extractLanguageSpoken(extractionContext),
    visibleMinority: extractVisibleMinority(extractionContext),
    maritalStatus: extractMaritalStatus(extractionContext),
    dependentChildren:
      dependentChildren.count === null || typeof dependentChildren.count === 'undefined'
        ? null
        : dependentChildren.count,
    agesOfChildren:
      Array.isArray(dependentChildren.ages) && dependentChildren.ages.length
        ? dependentChildren.ages
        : null,
    hasDisability:
      typeof disability.declared === 'boolean'
        ? disability.declared
        : null,
    disabilityDescription: disability.description || null,
    employmentStatus: clientStatus.status || null,
    labourForceStatus: clientStatus.status || null,
    socialAssistance: (() => {
      const raw = extractSocialAssistanceStatus(extractionContext);
      if (raw === 'Yes') return true;
      if (raw === 'No') return false;
      return null;
    })(),
    employmentNoc: clientStatus.noc || null,
    employmentNocVersion: clientStatus.nocVersion || null,
    prevEmployment: clientStatus.prevEmployment || null,
  };
  if (normalizedReportingTrigger === 'withdrawal') {
    nextContextPatch.reportingOnlyWithdrawal = true;
  } else {
    nextContextPatch.reportingOnlyDenied = true;
    nextContextPatch.reportingOnlyDeniedIneligible =
      existingCaseContext?.reportingOnlyDeniedIneligible === true ||
      normalizedDenialReason === DENIED_INELIGIBLE_TRIGGER_REASON;
    nextContextPatch[FUNDING_DECISION_REASON_CODE_KEY] =
      normalizedDenialReason || resolveFundingDecisionReasonCode(existingCaseContext, applicationId) || null;
  }
  return mergeCaseContext(existingCaseContext || {}, nextContextPatch);
}

async function syncCaseClientFromApplication(connection, {
  caseId,
  applicationId,
  existingClientId = null,
} = {}) {
  if (!Number.isInteger(Number(caseId)) || Number(caseId) <= 0) return null;
  if (!Number.isInteger(Number(applicationId)) || Number(applicationId) <= 0) return null;

  const profile = await buildClientProfileFromApplication(connection, Number(applicationId), { forUpdate: true });
  if (!profile) return existingClientId || null;

  const targetClientId = Number.isInteger(Number(existingClientId)) && Number(existingClientId) > 0
    ? Number(existingClientId)
    : null;

  if (targetClientId) {
    await connection.query(
      `UPDATE client
          SET dob = ?,
              gender = ?,
              aboriginal_group = ?,
              last_name = ?,
              first_name = ?,
              initials = ?,
              address_json = ?,
              updated_at = NOW()
        WHERE id = ?`,
      [
        profile.dob,
        profile.gender,
        profile.aboriginalGroup,
        profile.lastName,
        profile.firstName,
        profile.initials,
        profile.addressJson,
        targetClientId
      ]
    );
    await connection.query(
      'UPDATE iset_case SET client_id = ?, updated_at = NOW() WHERE id = ?',
      [targetClientId, Number(caseId)]
    );
    return targetClientId;
  }

  const [insertResult] = await connection.query(
    `INSERT INTO client
       (dob, gender, aboriginal_group, last_name, first_name, initials, address_json, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, NOW(), NOW())`,
    [
      profile.dob,
      profile.gender,
      profile.aboriginalGroup,
      profile.lastName,
      profile.firstName,
      profile.initials,
      profile.addressJson
    ]
  );
  const newClientId = insertResult.insertId || null;
  if (newClientId) {
    await connection.query(
      'UPDATE iset_case SET client_id = ?, updated_at = NOW() WHERE id = ?',
      [newClientId, Number(caseId)]
    );
  }
  return newClientId;
}

async function syncDeniedReportingArtifacts(connection, {
  caseId,
  applicationId,
  denialDate = null,
  reportingDate = null,
  reportingTrigger = 'denial',
} = {}) {
  const numericCaseId = Number(caseId);
  const numericApplicationId = Number(applicationId);
  if (!Number.isInteger(numericCaseId) || numericCaseId <= 0) return null;
  if (!Number.isInteger(numericApplicationId) || numericApplicationId <= 0) return null;

  const [[caseRow]] = await connection.query(
    `SELECT id, ? AS application_id, client_id, assigned_staff_profile_id AS assigned_to_user_id, assigned_staff_profile_id, status, closed_at, case_context_json
       FROM iset_case
      WHERE id = ?
      LIMIT 1 FOR UPDATE`,
    [numericApplicationId, numericCaseId]
  );
  if (!caseRow) return null;

  const assessmentRow = await fetchApplicationAssessmentRow(connection, {
    caseId: numericCaseId,
    applicationId: numericApplicationId,
  });
  const existingCaseContext = safeJsonParse(caseRow.case_context_json, null) || {};
  const normalizedReportingTrigger = resolveReportingArtifactTrigger(reportingTrigger, existingCaseContext);
  const reportingConfig = resolveReportingArtifactConfig(normalizedReportingTrigger);
  const denialReasonCode =
    normalizedReportingTrigger === 'withdrawal'
      ? null
      : (
          resolveFundingDecisionReasonCode(existingCaseContext, numericApplicationId) ||
          ((normaliseString(assessmentRow?.nwac_reason) || '').toLowerCase() || null)
        );

  const applicationPayload = await readApplicationPayload(connection, numericApplicationId, { forUpdate: true });
  const payload = applicationPayload?.payload || {};
  const answers = sanitiseAnswersPayload(payload.answers || {});
  const resolvedReportingDate = toDateOnlyString(
    reportingDate ||
    denialDate ||
    existingCaseContext?.[reportingConfig.dateContextKey] ||
    existingCaseContext?.reportingDeniedAt ||
    existingCaseContext?.reportingWithdrawnAt ||
    caseRow.closed_at ||
    new Date()
  );
  const resolvedDateTime = toMysqlDateTimeString(resolvedReportingDate);
  const syncedClientId = await syncCaseClientFromApplication(connection, {
    caseId: numericCaseId,
    applicationId: numericApplicationId,
    existingClientId: caseRow.client_id || null,
  });

  const nextCaseContext = buildDeniedReportingCaseContext({
    existingCaseContext,
    payload,
    answers,
    applicationId: numericApplicationId,
    clientId: syncedClientId,
    reportingDate: resolvedReportingDate,
    denialReasonCode,
    reportingTrigger: normalizedReportingTrigger,
  });

  await connection.query(
    `UPDATE iset_case
        SET status = ?,
            closed_at = COALESCE(closed_at, ?),
            case_context_json = ?,
            updated_at = NOW()
      WHERE id = ?`,
    [
      CASE_STATUS_DERIVED_VALUES.closed,
      resolvedDateTime,
      JSON.stringify(nextCaseContext),
      numericCaseId
    ]
  );

  const extractionContext = { payload, answers, caseContext: nextCaseContext };
  const clientStatus = extractClientStatusDetails(extractionContext) || {};
  const educationDetails = extractEducationDetails(extractionContext) || {};
  const disability = extractDisabilityInfo(extractionContext) || {};
  const socialAssistanceRaw = extractSocialAssistanceStatus(extractionContext);
  const socialAssistanceCode = socialAssistanceRaw === 'Yes' ? '1' : socialAssistanceRaw === 'No' ? '0' : null;
  const educationLevelCode = mapEducationLevelToIlmpCode(educationDetails.level);
  const educationProvinceCode = mapProvinceToIlmpCode(educationDetails.location);
  const prevEmploymentCode = clientStatus.prevEmployment || mapPrevEmploymentFromStatus(clientStatus.status) || null;
  const childcareNeedValue = firstDefinedValue(
    answers['childcare-need'],
    answers['childcare_need'],
    answers['childcare-required'],
    answers['childcare_required']
  );
  const childcareNeedCode = mapYesNoBooleanToIlmpCode(childcareNeedValue);
  const childcareFundingValue = firstDefinedValue(
    answers['childcare-fuding-status'],
    answers['childcare_fuding_status'],
    answers['childcare-funding-status'],
    answers['childcare_funding_status'],
    answers['childcare-funding'],
    answers['childcare_funding'],
    answers['childcare-supported'],
    answers['childcare_supported']
  );
  const childcareFundingCode =
    childcareNeedCode === '0'
      ? '1'
      : mapChildcareFundingToIlmpCode(childcareFundingValue);
  const barrierCodes = mapBarrierLabelsToIlmpCodes(extractEmploymentBarriers(extractionContext) || []);
  const explicitEiClaimantCode = (() => {
    const candidates = [
      assessmentRow?.esdc_eligibility,
      nextCaseContext?.eiClaimant,
      answers['ei-claimant'],
      answers['ei_claimant'],
      answers['ei-claimant-status'],
      answers['ei_claimant_status'],
      answers['employment-insurance-claimant'],
      answers['employment_insurance_claimant']
    ];
    for (const candidate of candidates) {
      const normalized = normalizeEiClaimantCode(candidate);
      if (normalized) return normalized;
    }
    return null;
  })();
  const deniedReportingEiClaimantCode = explicitEiClaimantCode || '3';
  const fundingStream =
    deniedReportingEiClaimantCode === '1' || deniedReportingEiClaimantCode === '2'
      ? 'EI'
      : deniedReportingEiClaimantCode === '3'
        ? 'CRF'
        : null;
  const agreementCandidate = fundingStream ? deriveAgreementNumberFromFundingStream(fundingStream) : null;
  const agreementNumber =
    agreementCandidate && agreementCandidate !== ILMP_PLACEHOLDER_AGREEMENT_NUMBER
      ? agreementCandidate
      : null;
  const actionPlanEsdcPayload = pruneNullish({
    agreementNumber,
    fundingStream,
    EIClaimant: deniedReportingEiClaimantCode || null,
    educationLevel: educationLevelCode,
    educationProvince: educationProvinceCode,
    socialAssistanceRecipient: socialAssistanceCode,
    actionPlanPreviousEmployment: prevEmploymentCode ? String(prevEmploymentCode) : null,
    actionPlanPreviousEmploymentNoc: prevEmploymentCode === 2 ? clientStatus.noc || null : null,
    actionPlanPreviousEmploymentNocVersion:
      prevEmploymentCode === 2 ? clientStatus.nocVersion || null : null,
    actionPlanPreviousEmploymentScheduleType:
      prevEmploymentCode === 2 ? clientStatus.scheduleType || null : null,
    actionPlanChildcareNeed: childcareNeedCode,
    actionPlanChildcareFundedCode: childcareFundingCode,
    BarrierToEmployment: barrierCodes,
    actionPlanResultCode: DENIED_REPORTING_ACTION_PLAN_RESULT_CODE,
    actionPlanResultDate: resolvedReportingDate,
    actionPlanResultEducationLevel: educationLevelCode,
  }) || null;
  const planMetadata = pruneNullish({
    source: reportingConfig.source,
    reportingOnly: true,
    reportingTrigger: normalizedReportingTrigger,
    generatedAt: existingCaseContext?.reportingSeededAt || new Date().toISOString(),
    denialReason: denialReasonCode || null,
    [reportingConfig.dateMetadataKey]: resolvedReportingDate,
    note: reportingConfig.note,
    applicantSnapshot: pruneNullish({
      firstName: extractFirstName(extractionContext),
      lastName: extractLastName(extractionContext),
      gender: extractGender(extractionContext),
      indigenousIdentity: extractIndigenousIdentity(extractionContext),
      dateOfBirth: toDateOnlyString(extractDob(extractionContext)),
      disability: typeof disability.declared === 'boolean' ? disability.declared : null,
    }),
  }) || null;

  const [[existingPlan]] = await connection.query(
    `SELECT id
       FROM iset_case_action_plan
      WHERE case_id = ?
        AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.source')) IN (${REPORTING_ARTIFACT_METADATA_SOURCES.map(() => '?').join(', ')})
      LIMIT 1
      FOR UPDATE`,
    [numericCaseId, ...REPORTING_ARTIFACT_METADATA_SOURCES]
  );

  let planId = existingPlan?.id || null;
  if (planId) {
    await connection.query(
      `UPDATE iset_case_action_plan
          SET name = ?,
              status = 'closed',
              agreement_number = ?,
              budget_pot = NULL,
              funding_stream = ?,
              owner_staff_profile_id = ?,
              effective_date = ?,
              review_date = NULL,
              activated_at = COALESCE(activated_at, ?),
              closed_at = COALESCE(closed_at, ?),
              result_code = ?,
              EIClaimant = ?,
              prev_employment = ?,
              result_date = ?,
              outcome_summary = ?,
              closure_notes = ?,
              notes = ?,
              metadata_json = ?,
              esdc_action_plan_json = ?,
              archived_at = NULL,
              updated_at = NOW()
        WHERE id = ?`,
      [
        reportingConfig.planName,
        agreementNumber,
        fundingStream,
        resolveCaseAssignedStaffProfileId(caseRow) || null,
        resolvedReportingDate,
        resolvedDateTime,
        resolvedDateTime,
        DENIED_REPORTING_ACTION_PLAN_RESULT_CODE,
        deniedReportingEiClaimantCode ? Number(deniedReportingEiClaimantCode) : null,
        prevEmploymentCode,
        resolvedReportingDate,
        reportingConfig.note,
        reportingConfig.note,
        reportingConfig.note,
        planMetadata ? JSON.stringify(planMetadata) : null,
        actionPlanEsdcPayload ? JSON.stringify(actionPlanEsdcPayload) : null,
        planId
      ]
    );
  } else {
    const [planInsert] = await connection.query(
      `INSERT INTO iset_case_action_plan
         (case_id, name, status, agreement_number, budget_pot, funding_stream, owner_staff_profile_id, effective_date, review_date, activated_at, closed_at, result_code, EIClaimant, prev_employment, result_date, outcome_summary, closure_notes, notes, metadata_json, esdc_action_plan_json)
       VALUES (?, ?, 'closed', ?, NULL, ?, ?, ?, NULL, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        numericCaseId,
        reportingConfig.planName,
        agreementNumber,
        fundingStream,
        resolveCaseAssignedStaffProfileId(caseRow) || null,
        resolvedReportingDate,
        resolvedDateTime,
        resolvedDateTime,
        DENIED_REPORTING_ACTION_PLAN_RESULT_CODE,
        deniedReportingEiClaimantCode ? Number(deniedReportingEiClaimantCode) : null,
        prevEmploymentCode,
        resolvedReportingDate,
        reportingConfig.note,
        reportingConfig.note,
        reportingConfig.note,
        planMetadata ? JSON.stringify(planMetadata) : null,
        actionPlanEsdcPayload ? JSON.stringify(actionPlanEsdcPayload) : null
      ]
    );
    planId = planInsert.insertId || null;
  }

  const interventionIds = [];
  const ownerStaffProfileId = resolveCaseAssignedStaffProfileId(caseRow) || null;
  for (const interventionDefinition of DENIED_REPORTING_INTERVENTIONS) {
    const interventionMetadata = pruneNullish({
      source: reportingConfig.source,
      reportingOnly: true,
      reportingTrigger: normalizedReportingTrigger,
      generatedAt: existingCaseContext?.reportingSeededAt || new Date().toISOString(),
      title: interventionDefinition.title,
      denialReason: denialReasonCode || null,
      [reportingConfig.dateMetadataKey]: resolvedReportingDate,
    }) || null;
    const interventionEsdcPayload = pruneNullish({
      interventionOutcome: String(DENIED_REPORTING_INTERVENTION_OUTCOME_CODE),
      interventionDuration: 0,
    }) || null;

    const [[existingIntervention]] = await connection.query(
      `SELECT id
         FROM iset_case_intervention
        WHERE case_id = ?
          AND action_plan_id = ?
          AND intervention_code = ?
          AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.source')) IN (${REPORTING_ARTIFACT_METADATA_SOURCES.map(() => '?').join(', ')})
        LIMIT 1
        FOR UPDATE`,
      [
        numericCaseId,
        planId,
        interventionDefinition.code,
        ...REPORTING_ARTIFACT_METADATA_SOURCES
      ]
    );

    let interventionId = existingIntervention?.id || null;
    if (interventionId) {
      await connection.query(
        `UPDATE iset_case_intervention
            SET action_plan_id = ?,
                intervention_code = ?,
                related_noc_version = NULL,
                related_noc = NULL,
                status = 'completed',
                delivery_status = 'completed',
                start_date = ?,
                end_date = ?,
                duration_days = 0,
                intervention_cost = NULL,
                budget_amount = NULL,
                approved_amount = NULL,
                actual_amount = NULL,
                outcome_code = ?,
                notes = ?,
                metadata_json = ?,
                esdc_intervention_json = ?,
                created_by_staff_profile_id = ?,
                reviewed_by_staff_profile_id = NULL,
                reviewed_at = NULL,
                review_notes = NULL,
                eligibility_result = NULL,
                funding_stream_decision = ?,
                required_docs_flags = NULL,
                closed_at = COALESCE(closed_at, ?),
                updated_at = NOW()
          WHERE id = ?`,
        [
          planId,
          interventionDefinition.code,
          resolvedReportingDate,
          resolvedReportingDate,
          DENIED_REPORTING_INTERVENTION_OUTCOME_CODE,
          reportingConfig.note,
          interventionMetadata ? JSON.stringify(interventionMetadata) : null,
          interventionEsdcPayload ? JSON.stringify(interventionEsdcPayload) : null,
          ownerStaffProfileId,
          fundingStream,
          resolvedDateTime,
          interventionId
        ]
      );
    } else {
      const [interventionInsert] = await connection.query(
        `INSERT INTO iset_case_intervention
           (case_id, action_plan_id, intervention_code, related_noc_version, related_noc, status, delivery_status, start_date, end_date, duration_days, intervention_cost, budget_amount, approved_amount, actual_amount, outcome_code, notes, metadata_json, esdc_intervention_json, created_by_staff_profile_id, reviewed_by_staff_profile_id, reviewed_at, review_notes, eligibility_result, funding_stream_decision, required_docs_flags, closed_at)
         VALUES (?, ?, ?, NULL, NULL, 'completed', 'completed', ?, ?, 0, NULL, NULL, NULL, NULL, ?, ?, ?, ?, ?, NULL, NULL, NULL, NULL, ?, NULL, ?)`,
        [
          numericCaseId,
          planId,
          interventionDefinition.code,
          resolvedReportingDate,
          resolvedReportingDate,
          DENIED_REPORTING_INTERVENTION_OUTCOME_CODE,
          reportingConfig.note,
          interventionMetadata ? JSON.stringify(interventionMetadata) : null,
          interventionEsdcPayload ? JSON.stringify(interventionEsdcPayload) : null,
          ownerStaffProfileId,
          fundingStream,
          resolvedDateTime
        ]
      );
      interventionId = interventionInsert.insertId || null;
    }
    if (interventionId) {
      interventionIds.push(interventionId);
    }
  }

  await ensureEsdcParticipantSubmissionRecord(connection, numericCaseId, numericApplicationId, planId);
  const submissionId = await findEsdcSubmissionIdForCase(connection, numericCaseId);
  if (!submissionId) {
    return {
      clientId: syncedClientId,
      planId,
      interventionId: interventionIds[0] || null,
      interventionIds,
      submissionId: null,
      compliance: null
    };
  }

  await validateEsdcParticipantSubmission(
    { submissionId, caseId: numericCaseId },
    { connection, transaction: false }
  );
  const [[updatedSubmission]] = await connection.query(
    `SELECT id, readiness_status, readiness_summary, warnings, blocking_issues, last_validated_at
       FROM esdc_participant_submission
      WHERE id = ?
      LIMIT 1`,
    [submissionId]
  );
  const compliance = mapIlmpComplianceFromSubmission(updatedSubmission);
  for (const interventionId of interventionIds) {
    await connection.query(
      `UPDATE iset_case_intervention
          SET metadata_json = JSON_SET(COALESCE(metadata_json, JSON_OBJECT()), '$.compliance.ilmp', ?),
              updated_at = NOW()
        WHERE id = ?`,
      [compliance.status, interventionId]
    );
  }

  return {
    clientId: syncedClientId,
    planId,
    interventionId: interventionIds[0] || null,
    interventionIds,
    submissionId,
    compliance
  };
}

async function syncDeniedReportingForApplicationIfNeeded(connection, {
  applicationId,
  denialDate = null,
} = {}) {
  const numericApplicationId = Number(applicationId);
  if (!Number.isInteger(numericApplicationId) || numericApplicationId <= 0) return null;
  const caseRow = await fetchCaseRowForApplicationId(numericApplicationId, {
    columns: ['id', 'case_context_json'],
    connection,
    forUpdate: true,
  });
  if (!caseRow) return null;
  const caseContext = safeJsonParse(caseRow.case_context_json, null) || {};
  if (!isDeniedReportingCaseContext(caseContext)) {
    return null;
  }
  return syncDeniedReportingArtifacts(connection, {
    caseId: caseRow.id,
    applicationId: numericApplicationId,
    denialDate,
    reportingTrigger: resolveReportingArtifactTrigger(null, caseContext),
  });
}

async function findExistingClientMatchForApplication(connection, applicationId) {
  if (!applicationId) return { clientId: null, matchSource: null };
  const profile = await buildClientProfileFromApplication(connection, applicationId, { forUpdate: false });
  if (!profile) return { clientId: null, matchSource: null };

  const lowerFirst = profile.firstName.toLowerCase();
  const lowerLast = profile.lastName.toLowerCase();
  const sinHash = profile.sinHash || null;

  let targetClientId = null;
  let matchSource = null;

  if (sinHash) {
    const params = [sinHash];
    let sql = `
      SELECT id
        FROM client
       WHERE JSON_UNQUOTE(JSON_EXTRACT(address_json, '$.sinHash')) = ?
    `;
    if (profile.dob) {
      sql += ' AND dob = ?';
      params.push(profile.dob);
    }
    sql += ' LIMIT 1';
    const [[bySinHash]] = await connection.query(sql, params);
    if (bySinHash) {
      targetClientId = bySinHash.id;
      matchSource = 'sin_hash';
    }
  }

  if (!targetClientId && sinHash) {
    const [sinCandidates] = await connection.query(
      `SELECT c.client_id, s.intake_payload
         FROM iset_case c
         ${buildCasePrimaryApplicationJoinSql('c', 'a', true)}
         JOIN iset_application_submission s ON s.id = a.submission_id
        WHERE c.client_id IS NOT NULL`
    );
    for (const row of sinCandidates) {
      if (!row?.intake_payload || !row?.client_id) continue;
      let payloadObj = null;
      try {
        payloadObj = typeof row.intake_payload === 'string'
          ? JSON.parse(row.intake_payload)
          : row.intake_payload;
      } catch (_) {
        payloadObj = null;
      }
      if (!payloadObj || typeof payloadObj !== 'object') continue;
      const candidateSinDigits = cleanSin(extractSin({ payload: {}, answers: payloadObj, caseContext: {} }));
      if (!candidateSinDigits || !isValidSin(candidateSinDigits)) continue;
      const candidateHash = hashSin(candidateSinDigits);
      if (candidateHash && candidateHash === sinHash) {
        targetClientId = row.client_id;
        matchSource = 'sin_submission';
        break;
      }
    }
  }

  if (!targetClientId && profile.emailNormalized) {
    const [[byEmail]] = await connection.query(
      `SELECT id
         FROM client
        WHERE address_json IS NOT NULL
          AND JSON_UNQUOTE(JSON_EXTRACT(address_json, '$.contact.emailNormalized')) = ?
        LIMIT 1`,
      [profile.emailNormalized]
    );
    if (byEmail) {
      targetClientId = byEmail.id;
      matchSource = 'email';
    }
  }

  if (!targetClientId) {
    if (profile.dob) {
      const [[byNameDob]] = await connection.query(
        `SELECT id
           FROM client
          WHERE LOWER(first_name) = ?
            AND LOWER(last_name) = ?
            AND dob = ?
          LIMIT 1`,
        [lowerFirst, lowerLast, profile.dob]
      );
      if (byNameDob) {
        targetClientId = byNameDob.id;
        matchSource = 'name_dob';
      }
    } else {
      const [[byNameOnly]] = await connection.query(
        `SELECT id
           FROM client
          WHERE LOWER(first_name) = ?
            AND LOWER(last_name) = ?
            AND dob IS NULL
          LIMIT 1`,
        [lowerFirst, lowerLast]
      );
      if (byNameOnly) {
        targetClientId = byNameOnly.id;
        matchSource = 'name_only';
      }
    }
  }

  return { clientId: targetClientId, matchSource };
}

async function findExistingClientCaseSummary(connection, { caseId, applicationId, clientId }) {
  let matchedClientId = clientId || null;
  let matchSource = matchedClientId ? 'linked' : null;
  if (!matchedClientId && applicationId) {
    const match = await findExistingClientMatchForApplication(connection, applicationId);
    if (match?.clientId) {
      matchedClientId = match.clientId;
      matchSource = match.matchSource;
    }
  }
  if (!matchedClientId) {
    return {
      clientId: null,
      matchSource,
      hasPriorCase: false,
      caseCount: 0,
      priorCase: null
    };
  }

  const [caseRows] = await connection.query(
    `SELECT c.id, c.status, c.case_number, ${buildCaseAssignedStaffProfileIdSql('c')} AS assigned_to_user_id, c.updated_at,
            sp.display_name, sp.name, sp.email
       FROM iset_case c
       LEFT JOIN staff_profiles sp ON sp.id = c.assigned_staff_profile_id
      WHERE c.client_id = ?
      ORDER BY c.updated_at DESC, c.id DESC`,
    [matchedClientId]
  );

  const normalizedCaseId = Number(caseId);
  const otherCases = caseRows.filter(row => {
    const rowId = Number(row?.id);
    return Number.isFinite(rowId) && Number.isFinite(normalizedCaseId)
      ? rowId !== normalizedCaseId
      : true;
  });
  const hasPriorCase = otherCases.length > 0;
  const priorCase = hasPriorCase
    ? (otherCases.find(row => row?.assigned_to_user_id) || otherCases[0])
    : null;

  return {
    clientId: matchedClientId,
    matchSource,
    hasPriorCase,
    caseCount: caseRows.length,
    priorCase
  };
}

async function ensureCaseClientLinkForApproval(connection, { caseId, applicationId, existingClientId, actorId = null, actorName = null }) {
  if (existingClientId) return existingClientId;
  if (!applicationId) return null;

  const profile = await buildClientProfileFromApplication(connection, applicationId, { forUpdate: true });
  if (!profile) {
    console.warn('[cases] unable to build client profile for application %s (case %s)', applicationId, caseId);
    return null;
  }

  const lowerFirst = profile.firstName.toLowerCase();
  const lowerLast = profile.lastName.toLowerCase();
  const sinHash = profile.sinHash || null;
  let targetClientId = null;

  let existingClientRow = null;

  if (sinHash) {
    const params = [sinHash];
    let sql = `
      SELECT id, address_json, dob, first_name, last_name
        FROM client
       WHERE JSON_UNQUOTE(JSON_EXTRACT(address_json, '$.sinHash')) = ?
    `;
    if (profile.dob) {
      sql += ' AND dob = ?';
      params.push(profile.dob);
    }
    sql += ' LIMIT 1';
    const [[bySinHash]] = await connection.query(sql, params);
    if (bySinHash) {
      targetClientId = bySinHash.id;
      existingClientRow = bySinHash;
    }
  }

  if (!targetClientId && sinHash) {
    // Fallback: scan prior submissions to reuse an existing client if the same SIN was used
    const [sinCandidates] = await connection.query(
      `SELECT c.client_id, s.intake_payload
         FROM iset_case c
         ${buildCasePrimaryApplicationJoinSql('c', 'a', true)}
         JOIN iset_application_submission s ON s.id = a.submission_id
        WHERE c.client_id IS NOT NULL`
    );
    for (const row of sinCandidates) {
      if (!row?.intake_payload || !row?.client_id) continue;
      let payloadObj = null;
      try {
        payloadObj = typeof row.intake_payload === 'string'
          ? JSON.parse(row.intake_payload)
          : row.intake_payload;
      } catch (_) {
        payloadObj = null;
      }
      if (!payloadObj || typeof payloadObj !== 'object') continue;
      const candidateSinDigits = cleanSin(extractSin({ payload: {}, answers: payloadObj, caseContext: {} }));
      if (!candidateSinDigits || !isValidSin(candidateSinDigits)) continue;
      const candidateHash = hashSin(candidateSinDigits);
      if (candidateHash && candidateHash === sinHash) {
        targetClientId = row.client_id;
        const [[clientRow]] = await connection.query('SELECT * FROM client WHERE id = ? LIMIT 1', [targetClientId]);
        existingClientRow = clientRow || null;
        break;
      }
    }
  }

  if (profile.emailNormalized) {
    const [[byEmail]] = await connection.query(
      `SELECT id
         FROM client
        WHERE address_json IS NOT NULL
          AND JSON_UNQUOTE(JSON_EXTRACT(address_json, '$.contact.emailNormalized')) = ?
        LIMIT 1`,
      [profile.emailNormalized]
    );
    if (byEmail) {
      targetClientId = byEmail.id;
      const [[clientRow]] = await connection.query('SELECT * FROM client WHERE id = ? LIMIT 1', [targetClientId]);
      existingClientRow = clientRow || null;
    }
  }

  if (!targetClientId) {
    if (profile.dob) {
      const [[byNameDob]] = await connection.query(
        `SELECT id
           FROM client
          WHERE LOWER(first_name) = ?
            AND LOWER(last_name) = ?
            AND dob = ?
          LIMIT 1`,
        [lowerFirst, lowerLast, profile.dob]
      );
      if (byNameDob) {
        targetClientId = byNameDob.id;
        const [[clientRow]] = await connection.query('SELECT * FROM client WHERE id = ? LIMIT 1', [targetClientId]);
        existingClientRow = clientRow || null;
      }
    } else {
      const [[byNameOnly]] = await connection.query(
        `SELECT id
           FROM client
          WHERE LOWER(first_name) = ?
            AND LOWER(last_name) = ?
            AND dob IS NULL
          LIMIT 1`,
        [lowerFirst, lowerLast]
      );
      if (byNameOnly) {
        targetClientId = byNameOnly.id;
        const [[clientRow]] = await connection.query('SELECT * FROM client WHERE id = ? LIMIT 1', [targetClientId]);
        existingClientRow = clientRow || null;
      }
    }
  }

  if (!targetClientId) {
    const [insertResult] = await connection.query(
      `INSERT INTO client (dob, gender, aboriginal_group, last_name, first_name, initials, address_json, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, NOW(), NOW())`,
      [
        profile.dob,
        profile.gender,
        profile.aboriginalGroup,
        profile.lastName,
        profile.firstName,
        profile.initials,
        profile.addressJson
      ]
    );
    targetClientId = insertResult.insertId;
  } else {
    await connection.query(
      `UPDATE client
          SET updated_at = NOW(),
              address_json = CASE
                WHEN ? IS NOT NULL AND (
                  address_json IS NULL
                  OR JSON_EXTRACT(address_json, '$.sinHash') IS NULL
                  OR JSON_UNQUOTE(JSON_EXTRACT(address_json, '$.sinHash')) <> ?
                )
                  THEN JSON_SET(COALESCE(address_json, JSON_OBJECT()), '$.sinHash', ?)
                ELSE address_json
              END
        WHERE id = ?`,
      [sinHash, sinHash, sinHash, targetClientId]
    );
  }

  await connection.query(
    'UPDATE iset_case SET client_id = ?, updated_at = NOW() WHERE id = ?',
    [targetClientId, caseId]
  );

  try {
    const changes = [];
    const addChange = (field, fromValue, toValue) => {
      const fromVal = fromValue === undefined ? null : fromValue;
      const toVal = toValue === undefined ? null : toValue;
      if (fromVal === toVal) return;
      changes.push({ field, from: fromVal, to: toVal });
    };
    const normalizeDob = value => {
      if (!value) return null;
      if (value instanceof Date) {
        return Number.isNaN(value.getTime()) ? null : value.toISOString().slice(0, 10);
      }
      const asString = String(value);
      if (!asString) return null;
      return asString.slice(0, 10);
    };

    if (existingClientRow) {
      addChange('first_name', existingClientRow.first_name, profile.firstName);
      addChange('last_name', existingClientRow.last_name, profile.lastName);
      addChange('dob', normalizeDob(existingClientRow.dob), profile.dob);
      addChange('gender', existingClientRow.gender, profile.gender);
      addChange('aboriginal_group', existingClientRow.aboriginal_group, profile.aboriginalGroup);
      addChange('address_json', existingClientRow.address_json, profile.addressJson);
    } else {
      addChange('created', null, profile);
    }
    const identityWarning = changes.some(change => change.field === 'dob' || change.field === 'first_name' || change.field === 'last_name');
    await captureCaseEvent({
      type: 'client_updated',
      caseId,
      payload: {
        clientId: targetClientId,
        applicationId,
        changes,
        identityWarning,
      },
      actorId,
      actorName,
      trackingId: null,
    });
  } catch (err) {
    console.warn('[client:update:audit] failed', err?.message || err);
  }

  return targetClientId;
}

async function getHighestApplicationVersion(connection, applicationId, fallbackCurrentVersion) {
  await ensureApplicationVersionTable();
  const [[maxRow]] = await connection.query('SELECT MAX(version) AS maxVersion FROM iset_application_version WHERE application_id = ?', [applicationId]);
  const maxVersion = Number(maxRow?.maxVersion || 0);
  return Math.max(Number(fallbackCurrentVersion || 0), maxVersion);
}

async function insertApplicationVersionRow(connection, {
  applicationId,
  version,
  payloadObj,
  changeSummary = null,
  actorStaffProfileId = null,
  actorUserId = null,
  actorName = null,
  restoredFromVersion = null,
} = {}) {
  await ensureApplicationVersionTable();
  const typedAuthorColumns = await getApplicationVersionTypedAuthorColumns(connection);
  const columns = [
    'application_id',
    'version',
    'payload_json',
    'change_summary',
  ];
  const values = [
    applicationId,
    version,
    JSON.stringify(payloadObj ?? {}),
    changeSummary || null,
  ];

  if (typedAuthorColumns.staffProfile) {
    columns.push('created_by_staff_profile_id');
    values.push(actorStaffProfileId || null);
  }
  if (typedAuthorColumns.user) {
    columns.push('created_by_user_id');
    values.push(actorUserId || null);
  }

  columns.push('created_by_name', 'restored_from_version');
  values.push(actorName || null, restoredFromVersion || null);

  await connection.query(
    `INSERT INTO iset_application_version (${columns.join(', ')})
     VALUES (${columns.map(() => '?').join(', ')})`,
    values
  );
}

