async function resolveVersionSavedByLabels(connection, versionRows = []) {
  const staffProfileIds = Array.from(
    new Set(
      (Array.isArray(versionRows) ? versionRows : [])
        .map(row => Number(row?.created_by_staff_profile_id || 0))
        .filter(value => Number.isInteger(value) && value > 0)
    )
  );
  const userIds = Array.from(
    new Set(
      (Array.isArray(versionRows) ? versionRows : [])
        .map(row => Number(row?.created_by_user_id || 0))
        .filter(value => Number.isInteger(value) && value > 0)
    )
  );
  const byKey = new Map();

  if (staffProfileIds.length) {
    const [staffRows] = await connection.query(
      `SELECT id, display_name, email
         FROM staff_profiles
        WHERE id IN (${staffProfileIds.map(() => '?').join(',')})`,
      staffProfileIds
    );
    for (const row of staffRows || []) {
      const label = normaliseString(row?.display_name) || normaliseString(row?.email) || null;
      if (label) byKey.set(`staff:${row.id}`, label);
    }
  }

  if (userIds.length) {
    const [userRows] = await connection.query(
      `SELECT id, name, email
         FROM user
        WHERE id IN (${userIds.map(() => '?').join(',')})`,
      userIds
    );
    for (const row of userRows || []) {
      const label = normaliseString(row?.name) || normaliseString(row?.email) || null;
      if (label) byKey.set(`user:${row.id}`, label);
    }
  }

  return byKey;
}

const DEFAULT_LOCK_CONFIG = Object.freeze({
  mode: 'optimistic',
  lockTtlMinutes: 15,
  heartbeatMinutes: 2
});
const DEMO_NAVIGATION_SCOPE = 'admin';
const DEMO_NAVIGATION_KEY = 'demoNavigation';
const DEMO_NAVIGATION_ROLES = Object.freeze([
  'System Administrator',
  'NWAC Administrator',
  'Regional Manager',
  'ISET Coordinator',
]);
const DEMO_NAVIGATION_DEFAULT_VISIBILITY = Object.freeze(
  DEMO_NAVIGATION_ROLES.reduce((acc, role) => {
    acc[role] = false;
    return acc;
  }, {})
);
const AUTO_ASSIGNMENT_SCOPE = 'workflow';
const AUTO_ASSIGNMENT_KEY = 'autoAssignment';
const AUTO_ASSIGNMENT_ALLOWED_FIELDS = new Set(['province', 'indigenous_group', 'any']);
const AUTO_ASSIGNMENT_ALLOWED_OPS = new Set(['equals', 'in', 'not_in', 'exists', 'always']);
const DEFAULT_AUTO_ASSIGNMENT_CONFIG = Object.freeze({ enabled: false, rules: [] });

function normaliseLockConfig(raw) {
  const config = { ...DEFAULT_LOCK_CONFIG };
  if (raw && typeof raw === 'object') {
    const mode = typeof raw.mode === 'string' ? raw.mode.trim().toLowerCase() : '';
    if (['optimistic', 'pessimistic', 'mixed'].includes(mode)) {
      config.mode = mode === 'mixed' ? 'pessimistic' : mode; // treat mixed as pessimistic for now
    }
    const ttl = Number(raw.lockTtlMinutes ?? raw.ttlMinutes);
    if (Number.isFinite(ttl) && ttl >= 1) {
      config.lockTtlMinutes = Math.min(Math.round(ttl), 240);
    }
    const heartbeat = Number(raw.heartbeatMinutes ?? raw.heartbeat);
    if (Number.isFinite(heartbeat) && heartbeat >= 1) {
      config.heartbeatMinutes = Math.min(Math.round(heartbeat), config.lockTtlMinutes);
    }
  }
  // If pessimistic requested but heartbeat exceeds ttl, clamp
  if (config.heartbeatMinutes > config.lockTtlMinutes) {
    config.heartbeatMinutes = config.lockTtlMinutes;
  }
  return config;
}

function normaliseDemoNavigationVisibilityConfig(raw) {
  const source = raw && typeof raw === 'object' && !Array.isArray(raw) && raw.visibility
    ? raw.visibility
    : raw;
  const visibility = { ...DEMO_NAVIGATION_DEFAULT_VISIBILITY };
  if (source && typeof source === 'object' && !Array.isArray(source)) {
    DEMO_NAVIGATION_ROLES.forEach(role => {
      if (Object.prototype.hasOwnProperty.call(source, role)) {
        visibility[role] = !!source[role];
      }
    });
  }
  return { visibility };
}

async function readLockConfig() {
  try {
    const [[row]] = await pool.query("SELECT v FROM iset_runtime_config WHERE scope='admin' AND k='locking' LIMIT 1");
    if (!row) return { ...DEFAULT_LOCK_CONFIG, source: 'default' };
    let value = row.v;
    if (value && typeof value === 'string') {
      try { value = JSON.parse(value); } catch { value = null; }
    }
    const config = normaliseLockConfig(value);
    return { ...config, source: row ? 'stored' : 'default' };
  } catch (err) {
    console.warn('[locking] read config failed:', err.message);
    return { ...DEFAULT_LOCK_CONFIG, source: 'error' };
  }
}

