function normalizeStaffIdList(list) {
  if (!Array.isArray(list)) return [];
  const normalized = [];
  for (const value of list) {
    const id = Number(value);
    if (Number.isInteger(id) && id > 0) normalized.push(id);
  }
  return Array.from(new Set(normalized));
}

function normalizeRegionIdList(list) {
  if (!Array.isArray(list)) return [];
  const normalized = [];
  for (const value of list) {
    const id = Number(value);
    if (Number.isInteger(id) && id > 0) normalized.push(id);
  }
  return Array.from(new Set(normalized));
}

function normalizeRegionIdInput(value) {
  if (Array.isArray(value)) return normalizeRegionIdList(value);
  const numeric = Number(value);
  if (Number.isInteger(numeric) && numeric > 0) return [numeric];
  return [];
}

function resolveRequestRegionIds(req) {
  if (Array.isArray(req?.auth?.regionIds)) {
    const ids = normalizeRegionIdList(req.auth.regionIds);
    if (ids.length) return ids;
  }
  if (Array.isArray(req?.staffProfile?.regionIds)) {
    const ids = normalizeRegionIdList(req.staffProfile.regionIds);
    if (ids.length) return ids;
  }
  return normalizeRegionIdInput(req?.staffProfile?.region_id ?? req?.auth?.regionId ?? null);
}

async function fetchStaffRegionIdsByStaffProfileId(staffProfileId) {
  const numeric = Number(staffProfileId);
  if (!Number.isInteger(numeric) || numeric <= 0) return [];
  try {
    const [rows] = await pool.query(
      'SELECT region_id FROM staff_region WHERE staff_profile_id = ?',
      [numeric]
    );
    const ids = (rows || []).map(row => row && row.region_id).filter(Boolean);
    return normalizeRegionIdList(ids);
  } catch (err) {
    if (isMissingTableErrorLocal(err)) return [];
    throw err;
  }
}

async function fetchRegionCodesByIds(regionIds) {
  const ids = normalizeRegionIdList(regionIds);
  if (!ids.length) return [];
  const placeholders = ids.map(() => '?').join(',');
  try {
    const [rows] = await pool.query(
      `SELECT region_id, code FROM canada_region WHERE region_id IN (${placeholders})`,
      ids
    );
    return (rows || [])
      .map(row => (row && row.code ? String(row.code).trim().toLowerCase() : null))
      .filter(Boolean);
  } catch (err) {
    if (isMissingTableErrorLocal(err)) return [];
    throw err;
  }
}

async function resolveRegionalCoordinatorContext(req) {
  if (!pool) return { valid: false, staffIds: [] };
  const candidateIdRaw = req.staffProfile?.id ?? null;
  let regionIdRaw = req.staffProfile?.region_id ?? req.auth?.regionId ?? null;

  const collected = [];
  let coordinatorId = null;

  const tryResolveCoordinator = async (rawId) => {
    const numeric = Number(rawId);
    if (!Number.isInteger(numeric) || numeric <= 0) return null;
    if (req.staffProfile && req.staffProfile.id === numeric) {
      if (!collected.includes(numeric)) collected.push(numeric);
      if (regionIdRaw == null && req.staffProfile.region_id != null) regionIdRaw = req.staffProfile.region_id;
      return numeric;
    }
    try {
      const [[profile]] = await pool.query('SELECT id, cognito_sub, email, primary_role, region_id FROM staff_profiles WHERE id = ? LIMIT 1', [numeric]);
      if (profile) {
        req.staffProfile = req.staffProfile || profile;
        if (!collected.includes(numeric)) collected.push(numeric);
        if (regionIdRaw == null && profile.region_id != null) regionIdRaw = profile.region_id;
        return numeric;
      }
    } catch (err) {
      if (!isMissingTableErrorLocal(err)) throw err;
    }
    return null;
  };

  coordinatorId = await tryResolveCoordinator(candidateIdRaw);

  if (regionIdRaw == null && coordinatorId != null) {
    try {
      const [[row]] = await pool.query('SELECT region_id FROM staff_profiles WHERE id = ? LIMIT 1', [coordinatorId]);
      if (row && row.region_id != null) regionIdRaw = row.region_id;
    } catch (err) {
      if (!isMissingTableErrorLocal(err)) throw err;
    }
  }

  const candidateRegionIds = [];
  if (regionIdRaw != null) candidateRegionIds.push(regionIdRaw);
  if (req.staffProfile?.region_id != null) candidateRegionIds.push(req.staffProfile.region_id);
  let regionIds = normalizeRegionIdList(candidateRegionIds);

  if (coordinatorId != null) {
    try {
      const mapped = await fetchStaffRegionIdsByStaffProfileId(coordinatorId);
      if (mapped.length) {
        regionIds = normalizeRegionIdList([...mapped, ...regionIds]);
      }
    } catch (err) {
      if (!isMissingTableErrorLocal(err)) throw err;
    }
  }

  if (regionIds.length) {
    const placeholders = regionIds.map(() => '?').join(',');
    try {
      const [rows] = await pool.query(`SELECT id FROM staff_profiles WHERE region_id IN (${placeholders})`, regionIds);
      for (const row of rows || []) {
        if (!row || row.id == null) continue;
        const id = Number(row.id);
        if (Number.isInteger(id) && id > 0 && !collected.includes(id)) collected.push(id);
      }
    } catch (err) {
      if (!isMissingTableErrorLocal(err)) throw err;
    }
  }

  const staffIds = normalizeStaffIdList(collected);
  const coordinatorInList = coordinatorId && staffIds.includes(coordinatorId) ? coordinatorId : null;
  const staffProfileId = coordinatorInList || (staffIds.length ? staffIds[0] : null);
  const primaryRegionId = regionIds.length ? regionIds[0] : null;

  return {
    valid: Number.isInteger(staffProfileId) && staffProfileId > 0 && regionIds.length > 0,
    staffProfileId: Number.isInteger(staffProfileId) && staffProfileId > 0 ? staffProfileId : null,
    regionId: primaryRegionId,
    regionIds,
    staffIds
  };
}

async function resolveApplicationAssessorContext(req) {
  if (!pool) return { valid: false, staffIds: [] };
  const candidateIdRaw = req.staffProfile?.id ?? null;
  let regionIdRaw = req.staffProfile?.region_id ?? req.auth?.regionId ?? null;

  const matchesAssessorRole = (profile) => {
    const role = profile?.primary_role;
    if (typeof role !== 'string') return false;
    return role.toLowerCase().replace(/\s+/g, '') === 'isetcoordinator';
  };

  const tryResolveById = async (rawId) => {
    const numeric = Number(rawId);
    if (!Number.isInteger(numeric) || numeric <= 0) return null;
    if (req.staffProfile && req.staffProfile.id === numeric) {
      return matchesAssessorRole(req.staffProfile) ? numeric : null;
    }
    try {
      const [[profile]] = await pool.query('SELECT id, cognito_sub, email, primary_role, region_id FROM staff_profiles WHERE id = ? LIMIT 1', [numeric]);
      if (profile && matchesAssessorRole(profile)) {
        req.staffProfile = req.staffProfile || profile;
        return numeric;
      }
    } catch (err) {
      if (!isMissingTableErrorLocal(err)) throw err;
    }
    return null;
  };

  const tryResolveByRegion = async (regionNumeric) => {
    try {
      const [rows] = await pool.query('SELECT id, cognito_sub, email, primary_role, region_id FROM staff_profiles WHERE region_id = ? ORDER BY id ASC', [regionNumeric]);
      const match = (rows || []).find(row => row && matchesAssessorRole(row));
      if (match && Number.isInteger(Number(match.id)) && Number(match.id) > 0) {
        req.staffProfile = req.staffProfile || match;
        return Number(match.id);
      }
    } catch (err) {
      if (!isMissingTableErrorLocal(err)) throw err;
    }
    return null;
  };

  let resolvedId = await tryResolveById(candidateIdRaw);

  if (!resolvedId && regionIdRaw != null) {
    const regionNumeric = Number(regionIdRaw);
    if (Number.isInteger(regionNumeric) && regionNumeric > 0) {
      resolvedId = await tryResolveByRegion(regionNumeric);
      if (resolvedId) {
        regionIdRaw = regionNumeric;
      }
    }
  }

  if (!resolvedId) {
    try {
      const [[row]] = await pool.query('SELECT id, cognito_sub, email, primary_role, region_id FROM staff_profiles WHERE primary_role = ? ORDER BY id ASC LIMIT 1', ['ISET Coordinator']);
      if (row && matchesAssessorRole(row)) {
        req.staffProfile = req.staffProfile || row;
        resolvedId = Number(row.id);
        if (row.region_id != null) regionIdRaw = row.region_id;
      }
    } catch (err) {
      if (!isMissingTableErrorLocal(err)) throw err;
    }
  }

  if (!resolvedId) {
    return { valid: false, staffIds: [] };
  }

  const staffIds = normalizeStaffIdList([resolvedId]);
  const context = {
    valid: staffIds.length === 1,
    staffProfileId: staffIds.length === 1 ? staffIds[0] : null,
    regionId: req.staffProfile?.region_id ?? (regionIdRaw != null ? Number(regionIdRaw) : null),
    staffIds
  };

  return context;
}


async function countActiveCasesWithScope(pool, { regionId = null, regionIds = null, ownerId = null } = {}) {
  try {
    const filters = ['LOWER(COALESCE(ap.status, \'\')) = ?'];
    const params = [ACTION_PLAN_ACTIVE_STATUS];

    if (Number.isInteger(ownerId) && ownerId > 0) {
      filters.push('c.assigned_staff_profile_id = ?');
      params.push(ownerId);
    }

    const regionList = normalizeRegionIdInput(regionIds?.length ? regionIds : regionId);
    if (regionList.length) {
      if (regionList.length === 1) {
        filters.push('sp.region_id = ?');
        params.push(regionList[0]);
      } else {
        const placeholders = regionList.map(() => '?').join(',');
        filters.push(`sp.region_id IN (${placeholders})`);
        params.push(...regionList);
      }
      filters.push('c.assigned_staff_profile_id IS NOT NULL');
    }

    if (READY_TO_CLOSE_EXCLUDED_STATUSES.length) {
      const placeholders = READY_TO_CLOSE_EXCLUDED_STATUSES.map(() => '?').join(',');
      filters.push(`(c.status IS NULL OR LOWER(c.status) NOT IN (${placeholders}))`);
      params.push(...READY_TO_CLOSE_EXCLUDED_STATUSES);
    }

    const sql = `SELECT COUNT(DISTINCT c.id) AS total
           FROM iset_case c
           JOIN iset_case_action_plan ap ON ap.case_id = c.id
           LEFT JOIN staff_profiles sp ON sp.id = c.assigned_staff_profile_id
          WHERE ${filters.join(' AND ')}
            AND ap.archived_at IS NULL`;
    const [[row]] = await pool.query(sql, params);
    return Number(row?.total ?? 0);
  } catch (err) {
    if (isMissingTableErrorLocal(err)) {
      return 0;
    }
    throw err;
  }
}

