function getMondayStartDateExpr() {
  // DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY) yields the Monday of the current calendar week.
  return 'DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY)';
}

