function inferUserRole(req) {
  const rawRole = req.staffProfile?.primary_role || req.auth?.role || null;
  return canonicaliseAccessRole(rawRole);
}

const ARCHIVED_APPLICATION_STATUS = 'archived';

function isArchivedApplicationStatus(status) {
  if (!status) return false;
  return String(status).trim().toLowerCase() === ARCHIVED_APPLICATION_STATUS;
}

function canViewArchivedApplications(req) {
  const role = canonicaliseAccessRole(inferUserRole(req));
  return role === 'System Administrator';
}

function buildArchivedApplicationFilter(req, alias = 'a') {
  if (canViewArchivedApplications(req)) return null;
  return `(${alias}.status IS NULL OR LOWER(${alias}.status) <> '${ARCHIVED_APPLICATION_STATUS}')`;
}

async function enforceApplicationVisibility(req, applicationId, connection = pool) {
  const normalizedApplicationId = normalisePositiveInteger(applicationId);
  if (!normalizedApplicationId) return { ok: false, reason: 'not_found', status: 404, body: { error: 'Application not found' } };
  const accessError = await validateCaseAccessByApplicationId(req, normalizedApplicationId, connection);
  if (accessError) {
    return {
      ok: false,
      reason: 'case_scope_denied',
      status: accessError.status,
      body: accessError.body,
    };
  }
  if (canViewArchivedApplications(req)) return { ok: true };
  const [[row]] = await connection.query(
    'SELECT status FROM iset_application WHERE id = ? LIMIT 1',
    [normalizedApplicationId]
  );
  if (!row) return { ok: false, reason: 'not_found', status: 404, body: { error: 'Application not found' } };
  if (isArchivedApplicationStatus(row.status)) {
    return { ok: false, reason: 'archived', status: 404, body: { error: 'Application not found' } };
  }
  return { ok: true };
}

function sendApplicationVisibilityFailure(res, visibility, fallbackError = 'Application not found') {
  return res.status(visibility?.status || 404).json(visibility?.body || { error: fallbackError });
}

function hasSlaAdminAccess(req) {
  const role = inferUserRole(req);
  return role === 'System Administrator' || role === 'NWAC Administrator';
}

function resolveActorLabel(req) {
  const { actorId, actorName } = resolveRequestActor(req) || {};
  if (actorName) return actorName;
  if (actorId) return actorId;
  return 'admin-dashboard';
}

async function ensureStaffProfile(pool, cognitoSub, email, roleLabel, legacyKey, regionId) {
  try {
    const subKey = cognitoSub || null;
    const legacy = legacyKey && legacyKey !== subKey ? legacyKey : null;

    let targetId = null;
    if (subKey) {
      const [[bySub]] = await pool.query('SELECT id FROM staff_profiles WHERE cognito_sub=? LIMIT 1', [subKey]);
      if (bySub && bySub.id) targetId = bySub.id;
    }
    if (!targetId && legacy) {
      const [[byLegacy]] = await pool.query('SELECT id FROM staff_profiles WHERE cognito_sub=? LIMIT 1', [legacy]);
      if (byLegacy && byLegacy.id) targetId = byLegacy.id;
    }
    if (!targetId && email) {
      const [[byEmail]] = await pool.query('SELECT id FROM staff_profiles WHERE email=? LIMIT 1', [email]);
      if (byEmail && byEmail.id) targetId = byEmail.id;
    }

    const finalSub = subKey || legacy || email || null;
    if (targetId) {
      const clauses = [];
      const values = [];
      if (finalSub) { clauses.push('cognito_sub=?'); values.push(finalSub); }
      if (email) { clauses.push('email=?'); values.push(email); }
      if (roleLabel) { clauses.push('primary_role=?'); values.push(roleLabel); }
      const hasRegionClause = Number.isFinite(regionId);
      if (hasRegionClause) { clauses.push('region_id=?'); values.push(regionId); }
      if (clauses.length) {
        const sql = `UPDATE staff_profiles SET ${clauses.join(', ')} WHERE id=?`;
        const params = [...values, targetId];
        try {
          await pool.query(sql, params);
        } catch (err) {
          if (hasRegionClause && /unknown column 'region_id'|ER_BAD_FIELD_ERROR/i.test(err?.message || '')) {
            const trimmedClauses = clauses.filter(c => c !== 'region_id=?');
            const trimmedValues = values.filter((_, idx) => clauses[idx] !== 'region_id=?');
            if (trimmedClauses.length) {
              const retrySql = `UPDATE staff_profiles SET ${trimmedClauses.join(', ')} WHERE id=?`;
              await pool.query(retrySql, [...trimmedValues, targetId]);
            }
          } else {
            throw err;
          }
        }
      }
      return targetId;
    }

    if (!finalSub && !email) return null;
    const insertKey = finalSub || email || legacy;
    if (!insertKey) return null;
    const insertEmail = email || `${insertKey}@placeholder.local`;
    if (Number.isFinite(regionId)) {
      try {
        await pool.query(`INSERT INTO staff_profiles (cognito_sub,email,primary_role,region_id) VALUES (?,?,?,?)
          ON DUPLICATE KEY UPDATE email=VALUES(email), primary_role=VALUES(primary_role), region_id=VALUES(region_id)`, [insertKey, insertEmail, roleLabel || null, regionId]);
      } catch (err) {
        // fallback if region column missing
        await pool.query(`INSERT INTO staff_profiles (cognito_sub,email,primary_role) VALUES (?,?,?)
          ON DUPLICATE KEY UPDATE email=VALUES(email), primary_role=VALUES(primary_role)`, [insertKey, insertEmail, roleLabel || null]);
      }
    } else {
      await pool.query(`INSERT INTO staff_profiles (cognito_sub,email,primary_role) VALUES (?,?,?)
        ON DUPLICATE KEY UPDATE email=VALUES(email), primary_role=VALUES(primary_role)`, [insertKey, insertEmail, roleLabel || null]);
    }
    const [[finalRow]] = await pool.query('SELECT id FROM staff_profiles WHERE cognito_sub=? LIMIT 1', [insertKey]);
    return finalRow && finalRow.id ? finalRow.id : null;
  } catch (err) {
    console.warn('[staff-assignable] ensureStaffProfile error:', err.message);
    return null;
  }
}
async function fetchAssignableFromCognito(pool) {
  if (!COGNITO_POOL_ID || !COGNITO_REGION) return null;
  try {
    const client = getCognitoIdpClient();
    const seen = new Map();
    for (const groupName of ASSIGNABLE_GROUP_NAMES) {
      let nextToken = undefined;
      do {
        const resp = await client.send(new ListUsersInGroupCommand({ UserPoolId: COGNITO_POOL_ID, GroupName: groupName, Limit: 60, NextToken: nextToken }));
        const users = resp.Users || [];
        for (const user of users) {
          const username = user?.Username;
          if (!username) continue;
          if (seen.has(username)) continue;
          const attr = Object.fromEntries((user.Attributes || []).map(a => [a.Name, a.Value]));
          const email = attr.email || username;
          if (!email) continue;
          const canonicalSub = attr.sub || username;
          const staffId = await ensureStaffProfile(pool, canonicalSub, email, ASSIGNABLE_GROUP_LABEL.get(groupName) || groupName, username, null);
          if (!staffId) continue;
          const displayName = attr.name || attr['custom:display_name'] || email;
          seen.set(username, {
            id: staffId,
            email,
            role: ASSIGNABLE_GROUP_LABEL.get(groupName) || groupName,
            display_name: displayName,
            region_id: null
          });
        }
        nextToken = resp.NextToken;
      } while (nextToken);
    }
    return Array.from(seen.values());
  } catch (err) {
    console.error('[staff-assignable] Cognito fetch failed:', err.message);
    return null;
  }
}

// List assignable staff for case assignment
// GET /api/staff/assignable
app.get('/api/staff/assignable', async (req, res) => {
  try {
    if (!req.auth || req.auth.subjectType !== 'staff') {
      return res.status(401).json({ error: 'forbidden' });
    }

    const merged = new Map();
    const addStaff = staff => {
      if (!staff) return;
      const key = staff.id ?? staff.email ?? staff.display_name ?? null;
      if (!key) return;
      const normalizedKey = String(key);
      if (!merged.has(normalizedKey)) {
        merged.set(normalizedKey, staff);
        return;
      }
      const existing = merged.get(normalizedKey) || {};
      merged.set(normalizedKey, {
        ...existing,
        ...Object.fromEntries(
          Object.entries(staff).filter(([, value]) => value !== null && typeof value !== 'undefined' && value !== '')
        ),
        region_id: staff.region_id ?? existing.region_id ?? null,
        display_name: staff.display_name || existing.display_name || staff.email || existing.email || null,
      });
    };

    const cognitoStaff = await fetchAssignableFromCognito(pool);
    if (Array.isArray(cognitoStaff)) {
      cognitoStaff.forEach(addStaff);
    }

    // Merge staff_profiles results so partial Cognito group listings still include known staff.
    const roles = ['NWAC Administrator','Regional Manager','ISET Coordinator','System Administrator'];
    const [rows] = await pool.query(
      `SELECT id, cognito_sub, email, primary_role AS role, email AS display_name, region_id
         FROM staff_profiles
        WHERE primary_role IN (${roles.map(()=>'?').join(',')})
        ORDER BY primary_role, email`, roles);
    rows.forEach(r => {
      addStaff({
        id: r.id,
        email: r.email,
        role: r.role,
        display_name: r.display_name,
        region_id: r.region_id ?? null,
      });
    });

    res.json(Array.from(merged.values()));
  } catch (e) {
    console.error('GET /api/staff/assignable failed:', e.message);
    res.status(500).json({ error: 'assignable_fetch_failed' });
  }
});

app.get('/api/reference/indigenous-bands', async (req, res) => {
  try {
    const query = (req.query.query || '').toString().trim();
    if (!query || query.length < 2) {
      return res.json([]);
    }
    const like = `%${query}%`;
    const [rows] = await pool.query(
      `SELECT id, band_number, band_name, type, coord_sys, latitude, longitude
         FROM iset_indigenous_bands
        WHERE band_name LIKE ? OR CAST(band_number AS CHAR) LIKE ?
        ORDER BY band_name ASC
        LIMIT 20`,
      [like, like]
    );
    const results = Array.isArray(rows)
      ? rows.map(row => ({
          id: row.id,
          bandNumber: row.band_number,
          bandName: row.band_name,
          type: row.type,
          coordSys: row.coord_sys,
          latitude: row.latitude,
          longitude: row.longitude,
        }))
      : [];
    return res.json(results);
  } catch (err) {
    console.error('Failed to search indigenous bands', err);
    return res.status(500).json({ error: 'Failed to search indigenous bands' });
  }
});

// PATCH /api/cases/:id/assign { assignee_id }
app.patch('/api/cases/:id/assign', async (req, res) => {
  const caseId = parseInt(req.params.id, 10);
  if (!Number.isInteger(caseId) || caseId < 1) return res.status(400).json({ error: 'invalid_case_id' });
  const { assignee_id } = req.body || {};
  try {
    const identity = getRequesterIdentity(req);
    const [[caseRow]] = await pool.query(
      `SELECT c.id,
        a.id AS application_id,
c.assigned_staff_profile_id AS assigned_to_user_id,
              c.assigned_staff_profile_id
         FROM iset_case c
         ${buildCasePrimaryApplicationJoinSql('c', 'a')}
        WHERE c.id = ?
        LIMIT 1`,
      [caseId]
    );
    if (!caseRow) return res.status(404).json({ error: 'case_not_found' });
    const accessError = await validateCaseAccessByCaseId(req, caseId);
    if (accessError) return res.status(accessError.status).json(accessError.body);
    const previousAssigneeId = resolveCaseAssignedStaffProfileId(caseRow);
    let previousAssigneeMeta = null;
    if (previousAssigneeId) {
      const [[prevMeta]] = await pool.query('SELECT id, display_name, email FROM staff_profiles WHERE id=? LIMIT 1', [previousAssigneeId]);
      previousAssigneeMeta = prevMeta || null;
    }
    let assignId = null;
    let targetStaff = null;
    if (assignee_id) {
      const [[staff]] = await pool.query('SELECT id, display_name AS name, email, region_id AS regionId FROM staff_profiles WHERE id=? LIMIT 1', [assignee_id]);
      if (!staff) return res.status(400).json({ error: 'staff_not_found' });
      targetStaff = staff;
      assignId = staff.id;
    } else {
      return res.status(400).json({ error: 'assignee_required' });
    }
    if (!ensureCanAssignCase(identity, targetStaff)) {
      return res.status(403).json({ error: 'forbidden', detail: 'assignment_not_permitted' });
    }
    const normalizedAssignId = assignId != null ? Number(assignId) : null;
    await pool.query(
      'UPDATE iset_case SET assigned_staff_profile_id=?, updated_at=NOW() WHERE id=?',
      [normalizedAssignId, caseId]
    );
    let newAssigneeMeta = null;
    if (normalizedAssignId) {
      const [[nextMeta]] = await pool.query('SELECT id, display_name, email FROM staff_profiles WHERE id=? LIMIT 1', [normalizedAssignId]);
      newAssigneeMeta = nextMeta || null;
    }
    let trackingId = null;
    if (caseRow.application_id) {
      const [[trackingRow]] = await pool.query(`SELECT JSON_UNQUOTE(JSON_EXTRACT(payload_json, '$.submission_snapshot.reference_number')) AS submission_ref FROM iset_application WHERE id=? LIMIT 1`, [caseRow.application_id]);
      trackingId = trackingRow?.submission_ref || null;
    }
    if (!trackingId) trackingId = `CASE-${caseId}`;
    const { actorId, actorName } = resolveRequestActor(req);
    let eventType = null;
    if (previousAssigneeId && normalizedAssignId && previousAssigneeId !== normalizedAssignId) {
      eventType = 'case_reassigned';
    } else if (!previousAssigneeId && normalizedAssignId) {
      eventType = 'case_assigned';
    } else if (previousAssigneeId && normalizedAssignId === null) {
      eventType = 'case_unassigned';
    }
    if (eventType) {
      const payload = {
        tracking_id: trackingId,
        from_assignee_id: previousAssigneeMeta?.id ?? null,
        from_assignee_staff_profile_id: previousAssigneeMeta?.id ?? null,
        from_assignee_email: previousAssigneeMeta?.email ?? null,
        from_assignee_name: previousAssigneeMeta?.display_name ?? null,
        to_assignee_id: newAssigneeMeta?.id ?? null,
        to_assignee_staff_profile_id: newAssigneeMeta?.id ?? null,
        assigned_staff_profile_id: newAssigneeMeta?.id ?? null,
        to_assignee_email: newAssigneeMeta?.email ?? null,
        to_assignee_name: newAssigneeMeta?.display_name ?? null,
      };
      const fromLabel = payload.from_assignee_name || payload.from_assignee_email || previousAssigneeId || 'previous assignee';
      const toLabel = eventType === 'case_unassigned' ? 'Unassigned' : (payload.to_assignee_name || payload.to_assignee_email || normalizedAssignId || 'assignee');
      if (eventType === 'case_reassigned') {
        payload.message = `Case reassigned from ${fromLabel} to ${toLabel}.`;
      } else if (eventType === 'case_assigned') {
        payload.message = `Case assigned to ${toLabel}.`;
      } else if (eventType === 'case_unassigned') {
        payload.message = `Case unassigned from ${fromLabel}.`;
      }
      try {
        await captureCaseEvent({
          type: eventType,
          caseId,
          payload,
          trackingId,
          actorId,
          actorName,
        });
      } catch (_) {}
    }
    return res.json({
      ok: true,
      case_id: caseId,
      ...buildAssignedStaffProfileResponseFields(normalizedAssignId),
    });
  } catch (e) {
    console.error('PATCH /api/cases/:id/assign failed:', e.message);
    res.status(500).json({ error: 'assign_failed', message: e.message });
  }
});

// POST /api/cases/:id/conflicts/revoke { staff_profile_id }
app.post('/api/cases/:id/conflicts/revoke', async (req, res) => {
  const caseId = parseInt(req.params.id, 10);
  const { staff_profile_id } = req.body || {};
  const role = inferUserRole(req) || 'Guest';
  if (!Number.isInteger(caseId) || caseId < 1) return res.status(400).json({ error: 'invalid_case_id' });
  if (!Number.isInteger(staff_profile_id) || staff_profile_id < 1) return res.status(400).json({ error: 'invalid_staff_profile_id' });
  if (role !== 'NWAC Administrator' && role !== 'Regional Manager') {
    return res.status(403).json({ error: 'forbidden' });
  }
  try {
    const accessError = await validateCaseAccessByCaseId(req, caseId);
    if (accessError) return res.status(accessError.status).json(accessError.body);

    if (role === 'Regional Manager') {
      const regionIds = resolveRequestRegionIds(req);
      if (!regionIds.length) {
        return res.status(403).json({ error: 'forbidden' });
      }
      const [[staffRow]] = await pool.query('SELECT region_id FROM staff_profiles WHERE id=? LIMIT 1', [staff_profile_id]);
      const staffRegion = staffRow?.region_id != null ? Number(staffRow.region_id) : null;
      if (!Number.isFinite(staffRegion) || !regionIds.includes(staffRegion)) {
        return res.status(403).json({ error: 'forbidden' });
      }
    }
    await pool.query(
      `UPDATE iset_case_conflict_declaration
         SET revoked_at = NOW(), revoked_reason = 'reassigned'
       WHERE case_id = ? AND staff_profile_id = ? AND revoked_at IS NULL`,
      [caseId, staff_profile_id]
    );
    return res.json({ ok: true });
  } catch (err) {
    if (err && (err.code === 'ER_NO_SUCH_TABLE' || err.code === 'ER_BAD_FIELD_ERROR')) {
      return res.json({ ok: true, note: 'table_missing' });
    }
    console.error('POST /api/cases/:id/conflicts/revoke failed:', err.message);
    return res.status(500).json({ error: 'conflict_revoke_failed', message: err.message });
  }
});

// POST /api/cases/:id/conflicts/resolve { staff_profile_id } -> set declaration_choice to no_conflict, keep details
app.post('/api/cases/:id/conflicts/resolve', async (req, res) => {
  const caseId = parseInt(req.params.id, 10);
  const { staff_profile_id } = req.body || {};
  const role = inferUserRole(req) || 'Guest';
  if (!Number.isInteger(caseId) || caseId < 1) return res.status(400).json({ error: 'invalid_case_id' });
  if (!Number.isInteger(staff_profile_id) || staff_profile_id < 1) return res.status(400).json({ error: 'invalid_staff_profile_id' });
  if (role !== 'NWAC Administrator' && role !== 'Regional Manager') {
    return res.status(403).json({ error: 'forbidden' });
  }
  try {
    const accessError = await validateCaseAccessByCaseId(req, caseId);
    if (accessError) return res.status(accessError.status).json(accessError.body);

    const [[conflictRow]] = await pool.query(`
      SELECT
        cd.case_id,
        cd.staff_profile_id,
        cd.declaration_choice,
        cd.conflict_details,
        cd.signed_at,
        sp.email AS staff_email,
        sp.primary_role AS staff_role,
        sp.display_name AS staff_display_name,
        sp.region_id AS staff_region_id,
        c.case_number,
        a.id AS application_id,
        s.reference_number
      FROM iset_case_conflict_declaration cd
      JOIN staff_profiles sp ON sp.id = cd.staff_profile_id
      LEFT JOIN iset_case c ON c.id = cd.case_id
      ${buildCasePrimaryApplicationJoinSql('c', 'a')}
      LEFT JOIN iset_application_submission s ON s.id = a.submission_id
     WHERE cd.case_id = ? AND cd.staff_profile_id = ? AND cd.revoked_at IS NULL
     ORDER BY cd.signed_at DESC
     LIMIT 1
    `, [caseId, staff_profile_id]);

    if (!conflictRow) {
      return res.json({ ok: true, note: 'conflict_not_found' });
    }

    if (role === 'Regional Manager') {
      const staffRegion = conflictRow?.staff_region_id != null ? Number(conflictRow.staff_region_id) : null;
      const regionIds = resolveRequestRegionIds(req);
      if (!regionIds.length || !Number.isFinite(staffRegion) || !regionIds.includes(staffRegion)) {
        return res.status(403).json({ error: 'forbidden' });
      }
    }

    const [updateResult] = await pool.query(
      `UPDATE iset_case_conflict_declaration
         SET declaration_choice = 'no_conflict'
       WHERE case_id = ? AND staff_profile_id = ? AND revoked_at IS NULL`,
      [caseId, staff_profile_id]
    );

    const resolvedAt = new Date();
    const trackingId = conflictRow?.reference_number || conflictRow?.case_number || `CASE-${caseId}`;
    const { actorId, actorName } = resolveRequestActor(req);
    const resolverEmail = req?.auth?.email || req?.staffProfile?.email || null;
    const resolverDisplay = actorName || resolverEmail || (actorId ? `User ${actorId}` : 'Resolver');
    const resolverRole = role || req?.auth?.role || req?.staffProfile?.primary_role || null;
    const payload = {
      tracking_id: trackingId,
      reference_number: conflictRow?.reference_number || null,
      case_number: conflictRow?.case_number || null,
      conflicted_staff_profile_id: conflictRow?.staff_profile_id || null,
      conflicted_staff_email: conflictRow?.staff_email || null,
      conflicted_staff_role: conflictRow?.staff_role || null,
      conflict_details: conflictRow?.conflict_details || null,
      resolved_by_id: actorId || null,
      resolved_by_email: resolverEmail || null,
      resolved_by_role: resolverRole || null,
      resolved_at: resolvedAt.toISOString(),
      message: `${resolverDisplay} resolved conflict declaration for ${conflictRow?.staff_email || 'staff member'}.`
    };

    try {
      await captureCaseEvent({
        type: 'conflict_declaration_resolved',
        caseId,
        payload,
        trackingId,
        actorId,
        actorName: resolverDisplay
      });
    } catch (_) {
      // event capture failures should not block the API
    }

    return res.json({ ok: true, updated: updateResult?.affectedRows ?? 0 });
  } catch (err) {
    if (err && (err.code === 'ER_NO_SUCH_TABLE' || err.code === 'ER_BAD_FIELD_ERROR')) {
      return res.json({ ok: true, note: 'table_missing' });
    }
    console.error('POST /api/cases/:id/conflicts/resolve failed:', err.message);
    return res.status(500).json({ error: 'conflict_resolve_failed', message: err.message });
  }
});

// ---------------------------------------------------------------------------
// Contact Messages (admin dashboard)
// ---------------------------------------------------------------------------
const CONTACT_MSG_PAGE_SIZE = 25;
const CONTACT_MSG_PAGE_SIZE_MAX = 100;

function resolveContactAdminRole(req) {
  const role = inferUserRole(req);
  if (role === 'System Administrator' || role === 'NWAC Administrator' || role === 'Regional Manager') {
    return role;
  }
  return null;
}

function buildContactMessageScope(req, { messageAlias = 'cm' } = {}) {
  const role = resolveContactAdminRole(req);
  if (!role) return { forbidden: true, role: null, clause: null, params: [] };
  if (role === 'System Administrator' || role === 'NWAC Administrator') {
    return { forbidden: false, role, clause: null, params: [] };
  }

  const requesterId = normalisePositiveInteger(
    req?.staffProfile?.id ?? req?.auth?.staffProfileId ?? req?.auth?.userId ?? null
  );
  const regionalScope = buildRegionalManagerCaseAccessSql({
    requesterId,
    regionIds: resolveRequestRegionIds(req),
    caseAlias: 'contact_case',
    ownerAlias: 'contact_owner'
  });
  if (!regionalScope) {
    return { forbidden: true, role, clause: null, params: [] };
  }

  const alias = /^[A-Za-z_][A-Za-z0-9_]*$/.test(String(messageAlias || ''))
    ? String(messageAlias)
    : 'cm';
  return {
    forbidden: false,
    role,
    clause: `EXISTS (
      SELECT 1
        FROM iset_application_submission contact_submission
        JOIN iset_application contact_application ON contact_application.submission_id = contact_submission.id
        JOIN iset_case contact_case ON contact_case.id = contact_application.case_id
        LEFT JOIN staff_profiles contact_owner ON contact_owner.id = contact_case.assigned_staff_profile_id
       WHERE contact_submission.user_id = ${alias}.user_id
         AND ${regionalScope.clause}
    )`,
    params: regionalScope.params,
  };
}

app.get('/api/admin/contact-messages', async (req, res) => {
  const accessScope = buildContactMessageScope(req);
  if (accessScope.forbidden) return res.status(403).json({ error: 'forbidden' });

  const page = Math.max(1, parseInt(req.query.page ?? '1', 10) || 1);
  const pageSize = Math.min(
    CONTACT_MSG_PAGE_SIZE_MAX,
    Math.max(1, parseInt(req.query.pageSize ?? `${CONTACT_MSG_PAGE_SIZE}`, 10) || CONTACT_MSG_PAGE_SIZE)
  );
  const offset = (page - 1) * pageSize;

  const status = typeof req.query.status === 'string' && req.query.status !== 'all'
    ? req.query.status.trim()
    : null;
  const search = typeof req.query.search === 'string' ? req.query.search.trim() : '';
  const submittedAfter = req.query.submittedAfter ? new Date(req.query.submittedAfter) : null;
  const submittedBefore = req.query.submittedBefore ? new Date(req.query.submittedBefore) : null;

  const where = [];
  const params = [];
  if (accessScope.clause) {
    where.push(accessScope.clause);
    params.push(...accessScope.params);
  }

  if (status) {
    where.push('cm.status = ?');
    params.push(status);
  }
  if (search) {
    const like = `%${search}%`;
    where.push(`(
      cm.full_name LIKE ? OR
      cm.email LIKE ? OR
      cm.subject LIKE ? OR
      cm.message LIKE ?
    )`);
    params.push(like, like, like, like);
  }
  if (submittedAfter && !Number.isNaN(submittedAfter.valueOf())) {
    where.push('cm.submitted_at >= ?');
    params.push(submittedAfter);
  }
  if (submittedBefore && !Number.isNaN(submittedBefore.valueOf())) {
    where.push('cm.submitted_at <= ?');
    params.push(submittedBefore);
  }

  const whereClause = where.length ? `WHERE ${where.join(' AND ')}` : '';

  try {
    const [[{ total }]] = await pool.query(
      `SELECT COUNT(*) AS total
         FROM contact_message cm
         ${whereClause}`,
      params
    );

    const [items] = await pool.query(
      `SELECT
         cm.id,
         cm.submitted_at   AS submittedAt,
         cm.full_name      AS fullName,
         cm.email,
         cm.subject,
         cm.status,
         cm.user_id        AS userId
       FROM contact_message cm
       ${whereClause}
       ORDER BY cm.submitted_at DESC
       LIMIT ? OFFSET ?`,
      [...params, pageSize, offset]
    );

    res.json({ items, page, pageSize, total });
  } catch (err) {
    console.error('[contact-admin] list failed', err);
    res.status(500).json({ error: 'internal_error' });
  }
});

// --- ESDC participant submissions -------------------------------------------------
const esdcRouter = express.Router();

/**
 * GET /api/esdc/participants
 * Query parameters (optional):
 *   readiness (ready|needs_review|blocked)
 *   search (tracking ID / name)
 *   limit / offset
 */
esdcRouter.get('/participants', async (req, res, next) => {
  const {
    readiness,
    search,
    limit = 25,
    offset = 0,
    groupByClient: groupByClientRaw = 'true'
  } = req.query;

  const groupByClient = String(groupByClientRaw || 'true').toLowerCase() !== 'false';

  const params = [];
  const where = [];
  const startedInterventionStatuses = Array.from(ESDC_REPORTABLE_INTERVENTION_DELIVERY_STATUSES);
  const terminalInterventionStatuses = Array.from(ESDC_TERMINAL_INTERVENTION_DELIVERY_STATUSES);
  const esdcInterventionDeliveryStatusExpr = buildInterventionDeliveryStatusSql('ci');

  if (readiness && ['ready', 'needs_review', 'blocked'].includes(readiness)) {
    where.push('eps.readiness_status = ?');
    params.push(readiness);
  }

  if (search) {
    where.push('(COALESCE(ias.reference_number, CONCAT(\'CASE-\', eps.case_id)) LIKE ? OR ia.payload_json->>"$.personal.last_name" LIKE ? OR cl.last_name LIKE ? OR cl.first_name LIKE ?)');
    params.push(`%${search}%`, `%${search}%`, `%${search}%`, `%${search}%`);
  }

  // Include plans that are reportable either for first submission (active with started intervention)
  // or for close-out (closed/ready with only terminal interventions and result info).
  where.push(
    `
    ap.archived_at IS NULL
    AND (
      (
        LOWER(COALESCE(ap.status, '')) = 'active'
        AND EXISTS (
          SELECT 1
          FROM iset_case_intervention ci
          WHERE ci.case_id = eps.case_id
            AND (ci.action_plan_id = ap.id OR ci.action_plan_id IS NULL)
            AND ci.start_date IS NOT NULL
            AND ci.start_date <= CURDATE()
            AND ${esdcInterventionDeliveryStatusExpr} IN (${startedInterventionStatuses.map(() => '?').join(',')})
        )
      )
      OR (
        LOWER(COALESCE(ap.status, '')) IN ('closed','ready_to_close','ready-to-close','ready to close')
        AND ap.result_date IS NOT NULL
        AND ap.result_code IS NOT NULL
        AND EXISTS (
          SELECT 1
          FROM iset_case_intervention ci
          WHERE ci.case_id = eps.case_id
            AND (ci.action_plan_id = ap.id OR ci.action_plan_id IS NULL)
        )
        AND NOT EXISTS (
          SELECT 1
          FROM iset_case_intervention ci
          WHERE ci.case_id = eps.case_id
            AND (ci.action_plan_id = ap.id OR ci.action_plan_id IS NULL)
            AND (
              ci.start_date IS NULL
              OR ${esdcInterventionDeliveryStatusExpr} IS NULL
              OR ${esdcInterventionDeliveryStatusExpr} NOT IN (${terminalInterventionStatuses.map(() => '?').join(',')})
            )
        )
      )
    )
    `
  );
  params.push(...startedInterventionStatuses, ...terminalInterventionStatuses);

  // Only show submissions that still require action (pending or needing resubmission).
  where.push(
    `
    LOWER(COALESCE(eps.submission_status, '')) IN ('pending','rejected')
    `
  );

  const whereClause = where.length ? `WHERE ${where.join(' AND ')}` : '';

  try {
    const [rows] = await pool.query(
      `
      SELECT
        eps.id,
        eps.case_id,
        eps.action_plan_id,
        eps.readiness_status,
        eps.warnings,
        eps.blocking_issues,
        eps.submission_status,
        eps.last_validated_at,
        eps.submitted_at,
        ap.status AS action_plan_status,
        ap.effective_date AS action_plan_start_date,
        ap.result_code AS action_plan_result_code,
        ap.result_date AS action_plan_result_date,
        COALESCE(
          NULLIF(TRIM(CONCAT_WS(' ', cl.first_name, cl.last_name)), ''),
          NULLIF(JSON_UNQUOTE(JSON_EXTRACT(ia.payload_json, '$.personal.full_name')), ''),
          NULLIF(JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$.personal.full_name')), ''),
          NULLIF(JSON_UNQUOTE(JSON_EXTRACT(ia.payload_json, '$.answers."preferred-name"')), ''),
          NULLIF(JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$.answers."preferred-name"')), ''),
          NULLIF(TRIM(CONCAT_WS(' ',
            JSON_UNQUOTE(JSON_EXTRACT(ia.payload_json, '$.answers."first-name"')),
            JSON_UNQUOTE(JSON_EXTRACT(ia.payload_json, '$.answers."middle-names"')),
            JSON_UNQUOTE(JSON_EXTRACT(ia.payload_json, '$.answers."last-name"'))
          )), ''),
          NULLIF(TRIM(CONCAT_WS(' ',
            JSON_UNQUOTE(JSON_EXTRACT(ia.payload_json, '$.answers.first_name')),
            JSON_UNQUOTE(JSON_EXTRACT(ia.payload_json, '$.answers.middle_names')),
            JSON_UNQUOTE(JSON_EXTRACT(ia.payload_json, '$.answers.last_name'))
          )), ''),
          NULLIF(TRIM(CONCAT_WS(' ',
            JSON_UNQUOTE(JSON_EXTRACT(ia.payload_json, '$.personal.first_name')),
            JSON_UNQUOTE(JSON_EXTRACT(ia.payload_json, '$.personal.middle_name')),
            JSON_UNQUOTE(JSON_EXTRACT(ia.payload_json, '$.personal.last_name'))
          )), ''),
          NULLIF(TRIM(CONCAT_WS(' ',
            JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$.answers."first-name"')),
            JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$.answers."middle-names"')),
            JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$.answers."last-name"'))
          )), ''),
          NULLIF(TRIM(CONCAT_WS(' ',
            JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$.answers.first_name')),
            JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$.answers.middle_names')),
            JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$.answers.last_name'))
          )), ''),
          NULLIF(TRIM(CONCAT_WS(' ',
            JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$.personal.first_name')),
            JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$.personal.middle_name')),
            JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$.personal.last_name'))
          )), ''),
          COALESCE(ias.reference_number, CONCAT('CASE-', eps.case_id))
        ) AS participant_name,
        COALESCE(c.case_number, ias.reference_number, CONCAT('CASE-', eps.case_id)) AS tracking_id,
        c.case_number AS case_number,
        c.client_id,
        cl.first_name AS client_first_name,
        cl.last_name AS client_last_name
      FROM esdc_participant_submission eps
      LEFT JOIN iset_application ia ON ia.id = eps.application_id
      LEFT JOIN iset_application_submission ias ON ias.id = ia.submission_id
      LEFT JOIN iset_case c ON c.id = eps.case_id
      LEFT JOIN client cl ON cl.id = c.client_id
      LEFT JOIN iset_case_action_plan ap ON ap.id = eps.action_plan_id
      ${whereClause}
      ORDER BY eps.last_validated_at DESC, eps.id DESC
      LIMIT ? OFFSET ?
      `,
      [...params, Number(limit), Number(offset)]
    );

    const [[{ total }]] = await pool.query(
      `
      SELECT COUNT(*) AS total
      FROM esdc_participant_submission eps
      LEFT JOIN iset_application ia ON ia.id = eps.application_id
      LEFT JOIN iset_application_submission ias ON ias.id = ia.submission_id
      LEFT JOIN iset_case c ON c.id = eps.case_id
      LEFT JOIN client cl ON cl.id = c.client_id
      LEFT JOIN iset_case_action_plan ap ON ap.id = eps.action_plan_id
      ${whereClause}
      `,
      params
    );

    const normalizeReadiness = value => {
      const key = typeof value === 'string' ? value.trim().toLowerCase() : '';
      if (key === 'blocked') return 'blocked';
      if (key === 'ready') return 'ready';
      return 'needs_review';
    };
    const readinessPriority = { blocked: 3, needs_review: 2, ready: 1 };
    const normalizeSubmissionStatus = value => {
      const key = typeof value === 'string' ? value.trim().toLowerCase() : '';
      if (key === 'rejected') return 'rejected';
      if (key === 'submitted') return 'submitted';
      if (key === 'accepted') return 'accepted';
      return 'pending';
    };
    const submissionPriority = { rejected: 4, pending: 3, submitted: 2, accepted: 1 };

    if (!groupByClient) {
      const items = rows.map(row => ({
        id: row.id,
        case_id: row.case_id,
        action_plan_id: row.action_plan_id,
        readiness_status: normalizeReadiness(row.readiness_status || 'needs_review'),
        warnings: row.warnings,
        blocking_issues: row.blocking_issues,
        submission_status: normalizeSubmissionStatus(row.submission_status || 'pending'),
        last_validated_at: row.last_validated_at,
        submitted_at: row.submitted_at,
        action_plan_status: row.action_plan_status,
        action_plan_start_date: row.action_plan_start_date,
        action_plan_result_code: row.action_plan_result_code,
        action_plan_result_date: row.action_plan_result_date,
        tracking_id: row.tracking_id,
        case_number: row.case_number,
        participant_name: row.participant_name || row.tracking_id
      }));
      res.json({ total, items, grouped: false });
      return;
    }

    const groups = new Map();
    rows.forEach(row => {
      const clientKey = row.client_id || `case-${row.case_id}`;
      if (!groups.has(clientKey)) {
        groups.set(clientKey, {
          id: `client-${clientKey}`,
          client_id: row.client_id || null,
          participant_name:
            row.participant_name ||
            (row.client_first_name && row.client_last_name ? `${row.client_first_name} ${row.client_last_name}` : row.tracking_id),
          readiness_status: 'ready',
          submission_status: 'accepted',
          last_validated_at: null,
          submitted_at: null,
          tracking_id: row.tracking_id,
          case_number: row.case_number,
          children: []
        });
      }
      const group = groups.get(clientKey);
      const readiness = normalizeReadiness(row.readiness_status);
      const submission = normalizeSubmissionStatus(row.submission_status);
      if (readinessPriority[readiness] > readinessPriority[group.readiness_status]) {
        group.readiness_status = readiness;
      }
      if (submissionPriority[submission] > submissionPriority[group.submission_status]) {
        group.submission_status = submission;
      }
      if (!group.last_validated_at || (row.last_validated_at && new Date(row.last_validated_at) > new Date(group.last_validated_at))) {
        group.last_validated_at = row.last_validated_at;
      }
      if (!group.submitted_at || (row.submitted_at && new Date(row.submitted_at) > new Date(group.submitted_at))) {
        group.submitted_at = row.submitted_at;
      }
      group.children.push({
        id: row.id,
        case_id: row.case_id,
        action_plan_id: row.action_plan_id,
        readiness_status: readiness,
        warnings: row.warnings,
        blocking_issues: row.blocking_issues,
        submission_status: submission,
        last_validated_at: row.last_validated_at,
        submitted_at: row.submitted_at,
        action_plan_status: row.action_plan_status,
        action_plan_start_date: row.action_plan_start_date,
        action_plan_result_code: row.action_plan_result_code,
        action_plan_result_date: row.action_plan_result_date,
        tracking_id: row.tracking_id,
        case_number: row.case_number,
        participant_name: row.participant_name || row.tracking_id,
        isChild: true
      });
    });

    const items = Array.from(groups.values()).map(group => {
      const pickPrimary = () => {
        const priorities = { active: 0, closed: 1, ready_to_close: 2, 'ready-to-close': 2, dormant: 3 };
        return [...group.children].sort((a, b) => {
          const pa = priorities[(a.action_plan_status || '').toLowerCase()] ?? 4;
          const pb = priorities[(b.action_plan_status || '').toLowerCase()] ?? 4;
          if (pa !== pb) return pa - pb;
          const da = a.action_plan_start_date ? new Date(a.action_plan_start_date).getTime() : 0;
          const db = b.action_plan_start_date ? new Date(b.action_plan_start_date).getTime() : 0;
          return db - da;
        })[0];
      };
      const primary = pickPrimary() || group.children[0] || {};
      return {
        ...group,
        tracking_id: primary.tracking_id || group.tracking_id,
        case_number: primary.case_number || group.case_number,
        action_plan_status: primary.action_plan_status || null,
        action_plan_start_date: primary.action_plan_start_date || null,
        action_plan_result_code: primary.action_plan_result_code || null,
        action_plan_result_date: primary.action_plan_result_date || null
      };
    });

    res.json({ total: items.length, items, grouped: true });
  } catch (err) {
    next(err);
  }
});

/**
 * POST /api/esdc/participants/validate-all
 * Re-run ILMP validation for all queued participants (filtered to active plans with started interventions and pending/rejected submissions).
 */
esdcRouter.post('/participants/validate-all', async (req, res, next) => {
  const startedInterventionStatuses = Array.from(ESDC_REPORTABLE_INTERVENTION_DELIVERY_STATUSES);
  const terminalInterventionStatuses = Array.from(ESDC_TERMINAL_INTERVENTION_DELIVERY_STATUSES);
  const esdcInterventionDeliveryStatusExpr = buildInterventionDeliveryStatusSql('ci');
  try {
    const [rows] = await pool.query(
      `
      SELECT eps.id
      FROM esdc_participant_submission eps
      LEFT JOIN iset_case_action_plan ap ON ap.id = eps.action_plan_id
      WHERE ap.archived_at IS NULL
        AND LOWER(COALESCE(eps.submission_status, '')) IN ('pending','rejected')
        AND (
          (
            LOWER(COALESCE(ap.status, '')) = 'active'
            AND EXISTS (
              SELECT 1
              FROM iset_case_intervention ci
              WHERE ci.case_id = eps.case_id
                AND (ci.action_plan_id = ap.id OR ci.action_plan_id IS NULL)
                AND ci.start_date IS NOT NULL
                AND ci.start_date <= CURDATE()
                AND ${esdcInterventionDeliveryStatusExpr} IN (${startedInterventionStatuses.map(() => '?').join(',')})
            )
          )
          OR (
            LOWER(COALESCE(ap.status, '')) IN ('closed','ready_to_close','ready-to-close','ready to close')
            AND ap.result_date IS NOT NULL
            AND ap.result_code IS NOT NULL
            AND EXISTS (
              SELECT 1
              FROM iset_case_intervention ci
              WHERE ci.case_id = eps.case_id
                AND (ci.action_plan_id = ap.id OR ci.action_plan_id IS NULL)
            )
            AND NOT EXISTS (
              SELECT 1
              FROM iset_case_intervention ci
              WHERE ci.case_id = eps.case_id
                AND (ci.action_plan_id = ap.id OR ci.action_plan_id IS NULL)
                AND (
                  ci.start_date IS NULL
                  OR ${esdcInterventionDeliveryStatusExpr} IS NULL
                  OR ${esdcInterventionDeliveryStatusExpr} NOT IN (${terminalInterventionStatuses.map(() => '?').join(',')})
                )
            )
          )
        )
      `,
      [...startedInterventionStatuses, ...terminalInterventionStatuses]
    );

    const ids = rows.map(r => r.id).filter(Boolean);
    const failures = [];
    let validated = 0;
    for (const id of ids) {
      try {
        await validateEsdcParticipantSubmission({ submissionId: id }, { transaction: false });
        validated += 1;
      } catch (err) {
        failures.push({ id, error: err?.message || 'validation_failed' });
      }
    }

    res.json({ ok: true, total: ids.length, validated, failures });
  } catch (err) {
    next(err);
  }
});

/**
 * POST /api/esdc/participants/batch-prepare
 * Generate batch XML for all ready participants (allows bypassing warnings).
 */
const extractClientFragment = xml => {
  if (!xml || typeof xml !== 'string') return null;
  const start = xml.indexOf('<client>');
  const end = xml.lastIndexOf('</client>');
  if (start === -1 || end === -1) return null;
  return xml.slice(start, end + '</client>'.length).trim();
};

const normalisePlanStatusShort = status => {
  const key = typeof status === 'string' ? status.trim().toLowerCase() : '';
  if (key === 'in_progress' || key === 'in-progress') return 'in_progress';
  if (key === 'ready_to_close' || key === 'ready-to-close') return 'ready_to_close';
  return key || '';
};

async function buildGroupedIlmpClientPayload(clientRows, { ignoreWarnings = false } = {}) {
  if (!Array.isArray(clientRows) || !clientRows.length) {
    return { error: 'no_rows' };
  }
  const connection = await pool.getConnection();
  try {
    const contexts = [];
    for (const row of clientRows) {
      const ctx = await loadEsdcParticipantSubmissionContext(connection, row.id, {
        caseId: row.case_id,
        forUpdate: false
      });
      contexts.push(ctx);
    }
    const combinedPlansRaw = contexts.flatMap(ctx => ctx.caseActionPlans || []);
    const planKey = plan => {
      if (!plan || typeof plan !== 'object') return null;
      if (plan.id !== null && typeof plan.id !== 'undefined') return `id:${plan.id}`;
      const agreement = normaliseString(plan.agreementNumber || plan.agreement_number || '') || '';
      const startDate = normaliseString(plan.startDate || plan.effectiveDate || plan.actionPlanStartDate || '') || '';
      const status = normalisePlanStatusShort(plan.status || '');
      return `fallback:${agreement}|${startDate}|${status}`;
    };
    const seenPlanKeys = new Set();
    const combinedPlans = [];
    combinedPlansRaw.forEach(plan => {
      const key = planKey(plan);
      if (!key || seenPlanKeys.has(key)) return;
      seenPlanKeys.add(key);
      combinedPlans.push(plan);
    });

    const activePlans = combinedPlans.filter(plan => normalisePlanStatusShort(plan.status) === 'active');
    const baseContext = [...contexts].sort((a, b) => {
      const aTs = a?.caseRow?.updated_at ? new Date(a.caseRow.updated_at).getTime() : 0;
      const bTs = b?.caseRow?.updated_at ? new Date(b.caseRow.updated_at).getTime() : 0;
      return bTs - aTs;
    })[0];
    const combinedContext = { ...baseContext, caseActionPlans: combinedPlans };
    const evaluation = runIlmpValidation(combinedContext);
    const blockingIssues = [...(evaluation.blockingIssues || [])];
    if (activePlans.length > 1) {
      blockingIssues.push('Only one active action plan is permitted per client.');
    }
    const warnings = evaluation.warnings || [];
    if (blockingIssues.length > 0) {
      return {
        blockingIssues,
        warnings,
        readinessStatus: 'blocked',
        evaluation
      };
    }
    if (warnings.length > 0 && !ignoreWarnings) {
      return {
        warnings,
        blockingIssues,
        readinessStatus: evaluation.readinessStatus || 'needs_review',
        evaluation
      };
    }
    const snapshot = buildIlmpParticipantPayload(combinedContext);
    return {
      evaluation,
      blockingIssues,
      warnings,
      snapshot,
      readinessStatus: evaluation.readinessStatus || 'ready'
    };
  } finally {
    connection.release();
  }
}

async function collectReadyEsdcBatchParticipants() {
  const startedInterventionStatuses = Array.from(ESDC_REPORTABLE_INTERVENTION_DELIVERY_STATUSES);
  const terminalInterventionStatuses = Array.from(ESDC_TERMINAL_INTERVENTION_DELIVERY_STATUSES);
  const esdcInterventionDeliveryStatusExpr = buildInterventionDeliveryStatusSql('ci');
  const [rows] = await pool.query(
    `
    SELECT eps.id, eps.case_id, eps.readiness_status, eps.action_plan_id,
           c.case_number,
           c.client_id,
           COALESCE(cl.first_name, '') AS first_name,
           COALESCE(cl.last_name, '') AS last_name,
           COALESCE(ias.reference_number, CONCAT('CASE-', eps.case_id)) AS tracking_id
    FROM esdc_participant_submission eps
    LEFT JOIN iset_case_action_plan ap ON ap.id = eps.action_plan_id
    LEFT JOIN iset_case c ON c.id = eps.case_id
    LEFT JOIN client cl ON cl.id = c.client_id
    LEFT JOIN iset_application ia ON ia.id = eps.application_id
    LEFT JOIN iset_application_submission ias ON ias.id = ia.submission_id
    WHERE ap.archived_at IS NULL
      AND (
        (
          LOWER(COALESCE(ap.status, '')) = 'active'
          AND EXISTS (
            SELECT 1
            FROM iset_case_intervention ci
            WHERE ci.case_id = eps.case_id
              AND (ci.action_plan_id = ap.id OR ci.action_plan_id IS NULL)
              AND ci.start_date IS NOT NULL
              AND ci.start_date <= CURDATE()
              AND ${esdcInterventionDeliveryStatusExpr} IN (${startedInterventionStatuses.map(() => '?').join(',')})
          )
        )
        OR (
          LOWER(COALESCE(ap.status, '')) IN ('closed','ready_to_close','ready-to-close','ready to close')
          AND ap.result_date IS NOT NULL
          AND ap.result_code IS NOT NULL
          AND EXISTS (
            SELECT 1
            FROM iset_case_intervention ci
            WHERE ci.case_id = eps.case_id
              AND (ci.action_plan_id = ap.id OR ci.action_plan_id IS NULL)
          )
          AND NOT EXISTS (
            SELECT 1
            FROM iset_case_intervention ci
            WHERE ci.case_id = eps.case_id
              AND (ci.action_plan_id = ap.id OR ci.action_plan_id IS NULL)
              AND (
                ci.start_date IS NULL
                OR ${esdcInterventionDeliveryStatusExpr} IS NULL
                OR ${esdcInterventionDeliveryStatusExpr} NOT IN (${terminalInterventionStatuses.map(() => '?').join(',')})
              )
          )
        )
      )
      AND LOWER(COALESCE(eps.submission_status, '')) IN ('pending','rejected')
    `,
    [...startedInterventionStatuses, ...terminalInterventionStatuses]
  );

  const clientGroups = new Map();
  rows.forEach(row => {
    const key = row.client_id || `case-${row.case_id}`;
    if (!clientGroups.has(key)) clientGroups.set(key, []);
    clientGroups.get(key).push(row);
  });

  const participants = [];
  const skipped = [];
  const clientFragments = [];

  for (const [key, clientRows] of clientGroups.entries()) {
    const displayName = (() => {
      const named = clientRows.find(row => row.first_name || row.last_name);
      if (named) return `${named.first_name || ''} ${named.last_name || ''}`.trim() || named.tracking_id;
      return clientRows[0]?.tracking_id || `Client ${key}`;
    })();
    const baseDetail = {
      id: clientRows[0]?.id || null,
      case_id: clientRows[0]?.case_id || null,
      client_id: clientRows[0]?.client_id || null,
      tracking_id: clientRows[0]?.tracking_id || null,
      participant_name: displayName,
      submission_ids: clientRows.map(row => row.id).filter(Boolean),
    };

    try {
      const aggregated = await buildGroupedIlmpClientPayload(clientRows, { ignoreWarnings: false });
      const readiness = (aggregated?.readinessStatus || '').toLowerCase() || 'needs_review';
      const blockingIssues = Array.isArray(aggregated?.blockingIssues) ? aggregated.blockingIssues : [];
      const warningList = Array.isArray(aggregated?.warnings) ? aggregated.warnings : [];
      if (readiness !== 'ready') {
        skipped.push({
          ...baseDetail,
          readiness_status: readiness,
          detail: blockingIssues.join('; ') || warningList.join('; ') || 'Participant is not ready for ESDC submission.',
        });
        continue;
      }

      participants.push({
        ...baseDetail,
        readiness_status: 'ready',
      });
      if (aggregated?.snapshot?.xml) {
        const fragment = extractClientFragment(aggregated.snapshot.xml);
        if (fragment) clientFragments.push(fragment);
      }
    } catch (err) {
      skipped.push({
        ...baseDetail,
        readiness_status: 'blocked',
        detail: err?.message || 'prepare_failed',
      });
    }
  }

  return { participants, skipped, clientFragments };
}

esdcRouter.post('/participants/batch-prepare', async (_req, res, next) => {
  try {
    const { participants, skipped, clientFragments } = await collectReadyEsdcBatchParticipants();
    const agreementHolderName = process.env.ESDC_AGREEMENT_HOLDER || 'NWAC ISET';
    const batchXml = participants.length
      ? [
          '<?xml version="1.0" encoding="UTF-8"?>',
          '<ALMP:contentALMP xmlns:ALMP="http://servicecanada.gc.ca/ALMP/contentExchange" xmlns:p="http://servicecanada.gc.ca/ALMP/contentTypes" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">',
          '  <SchemaVersion>1.4</SchemaVersion>',
          `  <agreementHolderName>${agreementHolderName}</agreementHolderName>`,
          '  <sysComment>Awentech nForm System</sysComment>',
          ...clientFragments.map(fragment => `  ${fragment}`),
          '</ALMP:contentALMP>'
        ].join('\n')
      : '';

    res.json({
      ok: true,
      participants,
      skipped,
      xml: batchXml,
    });
  } catch (err) {
    next(err);
  }
});

/**
 * POST /api/esdc/participants/batch-submit
 * Validate, generate, and mark batch as submitted. Returns XML + participant list.
 */
esdcRouter.post('/participants/batch-submit', async (req, res, next) => {
  const {
    filename: downloadFilenameRaw = null,
    downloadPath: downloadPathRaw = null
  } = req.body || {};
  const downloadFilename = (downloadFilenameRaw && String(downloadFilenameRaw).trim()) || `esdc-participants-${Date.now()}.xml`;
  const downloadPath = downloadPathRaw && String(downloadPathRaw).trim() ? String(downloadPathRaw).trim() : null;
  const batchId = `ilmp-batch-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`;
  try {
    const { participants, skipped, clientFragments } = await collectReadyEsdcBatchParticipants();
    if (!participants.length) {
      return res.status(400).json({
        error: 'no_ready_participants',
        skipped,
        message: 'There are no ready participants available for batch submission.',
      });
    }

    const agreementHolderName = process.env.ESDC_AGREEMENT_HOLDER || 'NWAC ISET';
    const batchXml = [
      '<?xml version="1.0" encoding="UTF-8"?>',
      '<ALMP:contentALMP xmlns:ALMP="http://servicecanada.gc.ca/ALMP/contentExchange" xmlns:p="http://servicecanada.gc.ca/ALMP/contentTypes" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">',
      '  <SchemaVersion>1.4</SchemaVersion>',
      `  <agreementHolderName>${agreementHolderName}</agreementHolderName>`,
      '  <sysComment>Awentech nForm System</sysComment>',
      ...clientFragments.map(fragment => `  ${fragment}`),
      '</ALMP:contentALMP>'
    ].join('\n');
    const xmlChecksum = crypto.createHash('sha256').update(batchXml, 'utf8').digest('hex');
    const xmlSize = Buffer.byteLength(batchXml, 'utf8');

    if (participants.length) {
      const ids = participants.flatMap(p => Array.isArray(p.submission_ids) ? p.submission_ids : [p.id]);
      await pool.query(
        `
        UPDATE esdc_participant_submission
        SET submission_status = 'submitted', submitted_at = NOW(), updated_at = NOW()
        WHERE id IN (${ids.map(() => '?').join(',')})
        `,
        ids
      );
      const historyDetails = JSON.stringify({
        batchId,
        filename: downloadFilename,
        downloadPath,
        xmlChecksum,
        xmlSize,
        participantCount: participants.length,
        xml: batchXml
      });
      await pool.query(
        `
        INSERT INTO esdc_participant_submission_history (participant_submission_id, event_type, actor_user_id, event_details)
        VALUES ${ids.map(() => '(?, "submitted", ?, ?)').join(',')}
        `,
        ids.flatMap(id => [id, req.user?.id || null, historyDetails])
      );
    }

    res.json({
      ok: true,
      participants,
      skipped,
      xml: batchXml,
      batchId,
      filename: downloadFilename,
      downloadPath,
      xmlChecksum,
      xmlSize
    });
  } catch (err) {
    next(err);
  }
});

/**
 * GET /api/esdc/participants/batches
 * Returns recent batch downloads (derived from submission history).
 */
esdcRouter.get('/participants/batches', async (req, res, next) => {
  const limit = Math.min(Math.max(Number(req.query.limit) || 10, 1), 50);
  try {
    const [rows] = await pool.query(
      `
      SELECT
        h.id AS history_id,
        h.participant_submission_id,
        h.event_details,
        h.occurred_at,
        h.actor_user_id,
        eps.case_id,
        eps.action_plan_id,
        eps.submission_status,
        c.case_number,
        COALESCE(cl.first_name, '') AS first_name,
        COALESCE(cl.last_name, '') AS last_name,
        COALESCE(ias.reference_number, CONCAT('CASE-', eps.case_id)) AS tracking_id
      FROM esdc_participant_submission_history h
      JOIN esdc_participant_submission eps ON eps.id = h.participant_submission_id
      LEFT JOIN iset_case c ON c.id = eps.case_id
      LEFT JOIN client cl ON cl.id = c.client_id
      LEFT JOIN iset_application ia ON ia.id = eps.application_id
      LEFT JOIN iset_application_submission ias ON ias.id = ia.submission_id
      WHERE h.event_type = 'submitted'
        AND JSON_EXTRACT(h.event_details, '$.batchId') IS NOT NULL
      ORDER BY h.occurred_at DESC, h.id DESC
      LIMIT ?
      `,
      [limit * 5]
    );

    const batchesMap = new Map();

    rows.forEach(row => {
      const details = safeJsonParse(row.event_details, {}) || {};
      const batchId = details.batchId || null;
      if (!batchId) return;
      let batch = batchesMap.get(batchId);
      if (!batch) {
        batch = {
          batchId,
          submittedAt: row.occurred_at,
          filename: details.filename || null,
          downloadPath: details.downloadPath || null,
          xmlChecksum: details.xmlChecksum || null,
          xmlSize: details.xmlSize || null,
          participants: []
        };
        batchesMap.set(batchId, batch);
      }
      if (row.occurred_at && (!batch.submittedAt || new Date(row.occurred_at) > new Date(batch.submittedAt))) {
        batch.submittedAt = row.occurred_at;
      }
      if (!batch.filename && details.filename) batch.filename = details.filename;
      if (!batch.downloadPath && details.downloadPath) batch.downloadPath = details.downloadPath;
      if (!batch.xmlChecksum && details.xmlChecksum) batch.xmlChecksum = details.xmlChecksum;
      if (!batch.xmlSize && typeof details.xmlSize !== 'undefined') batch.xmlSize = details.xmlSize;
      const participantName = [row.first_name, row.last_name].filter(Boolean).join(' ') ||
        row.tracking_id ||
        `Submission #${row.participant_submission_id}`;
      batch.participants.push({
        submissionId: row.participant_submission_id,
        caseId: row.case_id,
        trackingId: row.tracking_id,
        participantName,
        submissionStatus: row.submission_status
      });
      if (details.xml && !batch.xml) {
        batch.xml = details.xml;
      }
    });

    const items = Array.from(batchesMap.values())
      .map(entry => ({
        ...entry,
        participantCount: entry.participants.length
      }))
      .sort((a, b) => new Date(b.submittedAt) - new Date(a.submittedAt))
      .slice(0, limit);

    res.json({ items });
  } catch (err) {
    next(err);
  }
});

/**
 * POST /api/esdc/participants/batch-reset
 * Marks a list of participant submissions back to pending.
 */
esdcRouter.post('/participants/batch-reset', async (req, res, next) => {
  const ids = Array.isArray(req.body?.ids) ? req.body.ids : [];
  const numericIds = ids.map(id => Number(id)).filter(id => Number.isInteger(id) && id > 0);
  if (!numericIds.length) {
    return res.status(400).json({ error: 'no_ids', message: 'No participant submission ids provided.' });
  }
  try {
    await pool.query(
      `
      UPDATE esdc_participant_submission
      SET submission_status = 'pending', submitted_at = NULL, rejection_reason = NULL, updated_at = NOW()
      WHERE id IN (${numericIds.map(() => '?').join(',')})
      `,
      numericIds
    );
    await pool.query(
      `
      INSERT INTO esdc_participant_submission_history (participant_submission_id, event_type, actor_user_id, event_details)
      VALUES ${numericIds.map(() => '(?, "validated", ?, JSON_OBJECT("reset", true))').join(',')}
      `,
      numericIds.flatMap(id => [id, req.user?.id || null])
    );
    res.json({ ok: true, count: numericIds.length });
  } catch (err) {
    next(err);
  }
});

/**
 * GET /api/esdc/participants/:id
 */
esdcRouter.get('/participants/:id', async (req, res, next) => {
  const { id } = req.params;
  try {
    const [[submission]] = await pool.query(
      `
      SELECT
        eps.*,
        COALESCE(
          NULLIF(TRIM(CONCAT_WS(' ', cl.first_name, cl.last_name)), ''),
          NULLIF(JSON_UNQUOTE(JSON_EXTRACT(ia.payload_json, '$.personal.full_name')), ''),
          NULLIF(TRIM(CONCAT_WS(' ',
            JSON_UNQUOTE(JSON_EXTRACT(ia.payload_json, '$.personal.first_name')),
            JSON_UNQUOTE(JSON_EXTRACT(ia.payload_json, '$.personal.last_name'))
          )), ''),
          COALESCE(ias.reference_number, CONCAT('CASE-', eps.case_id))
        ) AS participant_name,
        COALESCE(c.case_number, ias.reference_number, CONCAT('CASE-', eps.case_id)) AS tracking_id,
        c.case_number AS case_number
      FROM esdc_participant_submission eps
      LEFT JOIN iset_application ia ON ia.id = eps.application_id
      LEFT JOIN iset_application_submission ias ON ias.id = ia.submission_id
      LEFT JOIN iset_case c ON c.id = eps.case_id
      LEFT JOIN client cl ON cl.id = c.client_id
      WHERE eps.id = ?
      `,
      [id]
    );
    if (!submission) {
      return res.status(404).json({ error: 'Participant submission not found' });
    }

    const [history] = await pool.query(
      `
      SELECT *
      FROM esdc_participant_submission_history
      WHERE participant_submission_id = ?
      ORDER BY occurred_at DESC
      `,
      [id]
    );

    res.json({ submission, history });
  } catch (err) {
    next(err);
  }
});

/**
 * POST /api/esdc/participants/:id/validate
 * (Re-run validation logic; placeholder updates metadata right now.)
 */
esdcRouter.post('/participants/:id/validate', async (req, res, next) => {
  const { id } = req.params;
  try {
    const numericId = Number(id);
    if (!Number.isInteger(numericId) || numericId <= 0) {
      return res.status(400).json({ error: 'invalid_participant_id' });
    }

    await validateEsdcParticipantSubmission({ submissionId: numericId });

    const [[submission]] = await pool.query(
      `
      SELECT eps.*, COALESCE(ias.reference_number, CONCAT('CASE-', eps.case_id)) AS tracking_id
      FROM esdc_participant_submission eps
      LEFT JOIN iset_application ia ON ia.id = eps.application_id
      LEFT JOIN iset_application_submission ias ON ias.id = ia.submission_id
      WHERE eps.id = ?
      `,
      [numericId]
    );
    if (!submission) {
      return res.status(404).json({ error: 'Participant submission not found' });
    }

    const [history] = await pool.query(
      `
      SELECT *
      FROM esdc_participant_submission_history
      WHERE participant_submission_id = ?
      ORDER BY occurred_at DESC, id DESC
      `,
      [numericId]
    );

    res.json({ ok: true, submission, history });
  } catch (err) {
    if (err && err.statusCode) {
      return res.status(err.statusCode).json({ error: err.message || 'validation_failed' });
    }
    next(err);
  }
});

/**
 * POST /api/esdc/participants/:id/prepare
 * Generates/stores payload snapshot based on latest validated data.
 */
esdcRouter.post('/participants/:id/prepare', async (req, res, next) => {
  const numericId = Number(req.params.id);
  if (!Number.isInteger(numericId) || numericId <= 0) {
    return res.status(400).json({ error: 'invalid_participant_id' });
  }

  try {
    const result = await prepareEsdcParticipantSubmission({ submissionId: numericId });
    if (result.blocking) {
      return res.status(409).json({
        error: 'blocking_validation_issues',
        readinessStatus: result.evaluation.readinessStatus,
        readinessSummary: result.evaluation.readinessSummary,
        warnings: result.evaluation.warnings,
        blockingIssues: result.evaluation.blockingIssues
      });
    }
    res.json({
      ok: true,
      submission: result.submission,
      history: result.history,
      payload: result.payload,
      checksum: result.checksum,
      storageKey: result.storageKey
    });
  } catch (err) {
    if (err && err.statusCode) {
      return res.status(err.statusCode).json({ error: err.message || 'validation_failed' });
    }
    next(err);
  }
});

/**
 * GET /api/esdc/participants/:id/payload
 * Returns the stored payload snapshot (if generated).
 */
esdcRouter.get('/participants/:id/payload', async (req, res, next) => {
  const numericId = Number(req.params.id);
  if (!Number.isInteger(numericId) || numericId <= 0) {
    return res.status(400).json({ error: 'invalid_participant_id' });
  }
  try {
    const [[row]] = await pool.query(
      `
      SELECT payload_snapshot, payload_checksum, payload_storage_key, updated_at
      FROM esdc_participant_submission
      WHERE id = ?
      `,
      [numericId]
    );
    if (!row) {
      return res.status(404).json({ error: 'Participant submission not found' });
    }
    let snapshot = row.payload_snapshot;
    if (snapshot && typeof snapshot === 'string') {
      try {
        snapshot = JSON.parse(snapshot);
      } catch {
        // leave as-is (raw string)
      }
    }
    res.json({
      payload: snapshot || null,
      checksum: row.payload_checksum || null,
      storageKey: row.payload_storage_key || null,
      updatedAt: row.updated_at || null
    });
  } catch (err) {
    next(err);
  }
});

/**
 * POST /api/esdc/participants/:id/submit
 * Marks submission as sent and logs history. Body can include rejectionReason or success flag.
 */
esdcRouter.post('/participants/:id/submit', async (req, res, next) => {
  const { id } = req.params;
  const { status = 'submitted', rejectionReason = null } = req.body || {};
  const actorUserId = req.user?.id || null;

  if (!['submitted', 'accepted', 'rejected'].includes(status)) {
    return res.status(400).json({ error: 'Invalid submission status' });
  }

  try {
    const [result] = await pool.query(
      `
      UPDATE esdc_participant_submission
      SET submission_status = ?, submitted_at = NOW(), submitted_by_user_id = ?, rejection_reason = ?
      WHERE id = ?
      `,
      [status, actorUserId, rejectionReason, id]
    );
    if (!result.affectedRows) {
      return res.status(404).json({ error: 'Participant submission not found' });
    }

    await pool.query(
      `
      INSERT INTO esdc_participant_submission_history
        (participant_submission_id, event_type, actor_user_id, event_details)
      VALUES
        (?, ?, ?, JSON_OBJECT('rejectionReason', ?))
      `,
      [id, status, actorUserId, rejectionReason]
    );

    res.json({ ok: true });
  } catch (err) {
    next(err);
  }
});

