function buildReportingSnapshotPeriods(startYear) {
  const nextYear = startYear + 1;
  return [
    { key: 'April (p1)', cutoff: buildReportingMonthEndDate(startYear, 4) },
    { key: 'May (p2)', cutoff: buildReportingMonthEndDate(startYear, 5) },
    { key: 'June (p3)', cutoff: buildReportingMonthEndDate(startYear, 6) },
    { key: 'July (p4)', cutoff: buildReportingMonthEndDate(startYear, 7) },
    { key: 'August (p5)', cutoff: buildReportingMonthEndDate(startYear, 8) },
    { key: 'September (p6)', cutoff: buildReportingMonthEndDate(startYear, 9) },
    { key: 'October (p7)', cutoff: buildReportingMonthEndDate(startYear, 10) },
    { key: 'November (p8)', cutoff: buildReportingMonthEndDate(startYear, 11) },
    { key: 'December (p9)', cutoff: buildReportingMonthEndDate(startYear, 12) },
    { key: 'January (p10)', cutoff: buildReportingMonthEndDate(nextYear, 1) },
    { key: 'February (p11)', cutoff: buildReportingMonthEndDate(nextYear, 2) },
    { key: 'March (p12)', cutoff: buildReportingMonthEndDate(nextYear, 3) },
    { key: 'Final (p14)', cutoff: buildReportingMonthEndDate(nextYear, 3) },
  ];
}

function buildReportingPeriodValues(periods) {
  return periods.reduce((acc, period) => {
    acc[period.key] = 0;
    return acc;
  }, {});
}

function parseReportingFiscalYearStartValue(rawValue) {
  const parsed = Number.parseInt(String(rawValue ?? ''), 10);
  if (Number.isInteger(parsed) && parsed >= 2020 && parsed <= 2100) {
    return parsed;
  }
  return null;
}

function resolveReportingFiscalYearStartValue(rawValue, fallbackDate = new Date()) {
  return parseReportingFiscalYearStartValue(rawValue) || resolveReportingFiscalYearStartYear(fallbackDate);
}

function buildReportingMatrixRows(labels, periods) {
  return labels.map(label => ({
    label,
    values: buildReportingPeriodValues(periods),
  }));
}

function resolveReportingApplicationActivityRowCodes(provinceCodes) {
  const filteredCodes = Array.isArray(provinceCodes)
    ? provinceCodes.filter(code => REPORTING_APPLICATION_ACTIVITY_ROW_CODE_SET.has(code))
    : [];
  return filteredCodes.length ? filteredCodes : REPORTING_APPLICATION_ACTIVITY_ROW_CODES;
}

function buildReportingApplicationActivityRows(periods, provinceCodes) {
  return resolveReportingApplicationActivityRowCodes(provinceCodes).map(provinceCode => ({
    provinceCode,
    values: buildReportingPeriodValues(periods),
  }));
}

function normaliseReportingProvinceCode(value) {
  const normalised = normaliseString(value);
  if (!normalised) return null;
  return PROVINCE_CODE_MAP[normalised.toLowerCase()] || normalised.toUpperCase();
}

function matchesReportingProvinceFilter(rawProvince, provinceCodes) {
  if (!Array.isArray(provinceCodes) || !provinceCodes.length) {
    return true;
  }
  const provinceCode = normaliseReportingProvinceCode(rawProvince);
  return Boolean(provinceCode && provinceCodes.includes(provinceCode));
}

function addReportingCumulativeValue(values, isoDate, periods, amount = 1) {
  const comparableDate = toDateOnly(isoDate);
  if (!comparableDate) return false;
  periods.forEach(period => {
    if (comparableDate <= period.cutoff) {
      values[period.key] = Number(values[period.key] || 0) + amount;
    }
  });
  return true;
}

function countReportingRowsWithValues(rows = [], periods = []) {
  const keys = periods.map(period => period.key);
  return rows.reduce((count, row) => {
    const values = row?.values || {};
    const hasValue = keys.some(key => Number(values[key] || 0) > 0);
    return count + (hasValue ? 1 : 0);
  }, 0);
}

function buildReportingTargetsKey(fiscalYearStart) {
  return `targets.${fiscalYearStart}`;
}

function buildReportingTargetsConfigCandidates(fiscalYearStart) {
  const candidates = [];
  if (Number.isInteger(fiscalYearStart) && fiscalYearStart >= 2020 && fiscalYearStart <= 2100) {
    candidates.push({
      scope: REPORTING_TARGETS_CONFIG_SCOPE,
      key: buildReportingTargetsKey(fiscalYearStart),
    });
  }
  candidates.push(REPORTING_TARGETS_CONFIG_PRIMARY, ...REPORTING_TARGETS_CONFIG_LEGACY_CANDIDATES);
  return candidates;
}

function normalizeReportingTargetNumber(value) {
  if (value === null || typeof value === 'undefined' || value === '') return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function normaliseReportingTargetsConfig(rawValue) {
  const parsed = safeJsonParse(rawValue, rawValue);
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return {};
  }
  const clientsServed =
    normalizeReportingTargetNumber(parsed.clientsServed) ??
    normalizeReportingTargetNumber(parsed['Clients Served']) ??
    normalizeReportingTargetNumber(parsed.clients_served);
  const clientsEmployed =
    normalizeReportingTargetNumber(parsed.clientsEmployed) ??
    normalizeReportingTargetNumber(parsed['Clients Employed']) ??
    normalizeReportingTargetNumber(parsed.clients_employed);
  const clientsReturnedToSchool =
    normalizeReportingTargetNumber(parsed.clientsReturnedToSchool) ??
    normalizeReportingTargetNumber(parsed['Clients Returned to School']) ??
    normalizeReportingTargetNumber(parsed.clients_returned_to_school);

  return {
    clientsServed,
    clientsEmployed,
    clientsReturnedToSchool,
  };
}

function validateReportingDataAndResultsTargets(rawValue) {
  const payload = rawValue && typeof rawValue === 'object' && !Array.isArray(rawValue)
    ? rawValue
    : {};
  const fields = [
    { key: 'clientsServed', label: 'Clients Served target' },
    { key: 'clientsEmployed', label: 'Clients Employed target' },
    { key: 'clientsReturnedToSchool', label: 'Clients Returned to School target' },
  ];
  const value = {};

  for (const field of fields) {
    const rawFieldValue = payload[field.key];
    if (rawFieldValue === null || typeof rawFieldValue === 'undefined' || rawFieldValue === '') {
      value[field.key] = null;
      continue;
    }
    const parsed = Number(rawFieldValue);
    if (!Number.isFinite(parsed) || parsed < 0 || !Number.isInteger(parsed)) {
      return {
        ok: false,
        error: 'invalid_reporting_target',
        message: `${field.label} must be a whole number or blank.`,
      };
    }
    value[field.key] = parsed;
  }

  return { ok: true, value };
}

async function readReportingDataAndResultsTargetsConfig(fiscalYearStart, executor = pool) {
  const runner = executor || pool;
  const resolvedFiscalYearStart = resolveReportingFiscalYearStartValue(fiscalYearStart);
  const defaultKey = buildReportingTargetsKey(resolvedFiscalYearStart);
  if (!runner || typeof runner.query !== 'function') {
    return {
      targets: {},
      source: 'default',
      scope: REPORTING_TARGETS_CONFIG_SCOPE,
      key: defaultKey,
      fiscalYearStart: resolvedFiscalYearStart,
      fiscalYear: formatReportingFiscalYearLabel(resolvedFiscalYearStart),
      updatedAt: null,
    };
  }

  for (const candidate of buildReportingTargetsConfigCandidates(resolvedFiscalYearStart)) {
    try {
      const [rows] = await runner.query(
        'SELECT v, updated_at FROM iset_runtime_config WHERE scope = ? AND k = ? LIMIT 1',
        [candidate.scope, candidate.key]
      );
      if (Array.isArray(rows) && rows.length) {
        return {
          targets: normaliseReportingTargetsConfig(rows[0].v),
          source: 'stored',
          scope: candidate.scope,
          key: candidate.key,
          fiscalYearStart: resolvedFiscalYearStart,
          fiscalYear: formatReportingFiscalYearLabel(resolvedFiscalYearStart),
          updatedAt: rows[0].updated_at ? toIsoDateTime(rows[0].updated_at) : null,
        };
      }
    } catch (err) {
      if (isMissingTableErrorLocal(err) || isMissingColumnErrorLocal(err)) {
        return {
          targets: {},
          source: 'default',
          scope: REPORTING_TARGETS_CONFIG_SCOPE,
          key: defaultKey,
          fiscalYearStart: resolvedFiscalYearStart,
          fiscalYear: formatReportingFiscalYearLabel(resolvedFiscalYearStart),
          updatedAt: null,
        };
      }
      console.warn('[reporting:data-and-results] targets load failed:', err?.message || err);
      return {
        targets: {},
        source: 'error',
        scope: REPORTING_TARGETS_CONFIG_SCOPE,
        key: defaultKey,
        fiscalYearStart: resolvedFiscalYearStart,
        fiscalYear: formatReportingFiscalYearLabel(resolvedFiscalYearStart),
        updatedAt: null,
      };
    }
  }

  return {
    targets: {},
    source: 'default',
    scope: REPORTING_TARGETS_CONFIG_SCOPE,
    key: defaultKey,
    fiscalYearStart: resolvedFiscalYearStart,
    fiscalYear: formatReportingFiscalYearLabel(resolvedFiscalYearStart),
    updatedAt: null,
  };
}

async function writeReportingDataAndResultsTargetsConfig(fiscalYearStart, nextTargets, executor = pool) {
  const runner = executor || pool;
  const resolvedFiscalYearStart = resolveReportingFiscalYearStartValue(fiscalYearStart);
  const targetKey = buildReportingTargetsKey(resolvedFiscalYearStart);
  if (!runner || typeof runner.query !== 'function') {
    return {
      targets: nextTargets,
      source: 'memory',
      scope: REPORTING_TARGETS_CONFIG_SCOPE,
      key: targetKey,
      fiscalYearStart: resolvedFiscalYearStart,
      fiscalYear: formatReportingFiscalYearLabel(resolvedFiscalYearStart),
      updatedAt: null,
    };
  }
  await ensureRuntimeConfigTable();
  await runner.query(
    'INSERT INTO iset_runtime_config (scope,k,v) VALUES (?,?,CAST(? AS JSON)) ON DUPLICATE KEY UPDATE v=VALUES(v), updated_at=CURRENT_TIMESTAMP',
    [
      REPORTING_TARGETS_CONFIG_SCOPE,
      targetKey,
      JSON.stringify(nextTargets),
    ]
  );
  return readReportingDataAndResultsTargetsConfig(resolvedFiscalYearStart, runner);
}

async function loadReportingDataAndResultsTargets(executor = pool, fiscalYearStart) {
  const config = await readReportingDataAndResultsTargetsConfig(fiscalYearStart, executor);
  return config.targets || {};
}

function buildReportingAdditionalCommentsKey(fiscalYearStart) {
  return `additionalComments.${fiscalYearStart}`;
}

function normaliseReportingAdditionalCommentsConfig(rawValue) {
  const parsed = safeJsonParse(rawValue, rawValue);
  if (typeof parsed === 'string') {
    return parsed.replace(/\r\n?/g, '\n').trim();
  }
  if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
    const comments =
      typeof parsed.comments === 'string'
        ? parsed.comments
        : typeof parsed.comment === 'string'
          ? parsed.comment
          : '';
    return comments.replace(/\r\n?/g, '\n').trim();
  }
  return '';
}

function validateReportingAdditionalComments(rawValue) {
  const payload = rawValue && typeof rawValue === 'object' && !Array.isArray(rawValue)
    ? rawValue
    : {};
  const comments = String(payload.comments ?? payload.comment ?? '')
    .replace(/\r\n?/g, '\n')
    .trim();
  if (comments.length > REPORTING_ADDITIONAL_COMMENTS_MAX_LENGTH) {
    return {
      ok: false,
      error: 'invalid_reporting_comments',
      message: `Additional comments must be ${REPORTING_ADDITIONAL_COMMENTS_MAX_LENGTH} characters or fewer.`,
    };
  }
  return { ok: true, value: { comments } };
}

async function readReportingAdditionalCommentsConfig(fiscalYearStart, executor = pool) {
  const runner = executor || pool;
  const key = buildReportingAdditionalCommentsKey(fiscalYearStart);
  const fallback = {
    comments: '',
    source: 'default',
    scope: REPORTING_ADDITIONAL_COMMENTS_SCOPE,
    key,
    fiscalYearStart,
    fiscalYear: formatReportingFiscalYearLabel(fiscalYearStart),
    updatedAt: null,
  };
  if (!runner || typeof runner.query !== 'function') {
    return fallback;
  }

  try {
    const [rows] = await runner.query(
      'SELECT v, updated_at FROM iset_runtime_config WHERE scope = ? AND k = ? LIMIT 1',
      [REPORTING_ADDITIONAL_COMMENTS_SCOPE, key]
    );
    if (!Array.isArray(rows) || !rows.length) {
      return fallback;
    }
    return {
      comments: normaliseReportingAdditionalCommentsConfig(rows[0].v),
      source: 'stored',
      scope: REPORTING_ADDITIONAL_COMMENTS_SCOPE,
      key,
      fiscalYearStart,
      fiscalYear: formatReportingFiscalYearLabel(fiscalYearStart),
      updatedAt: rows[0].updated_at ? toIsoDateTime(rows[0].updated_at) : null,
    };
  } catch (err) {
    if (isMissingTableErrorLocal(err) || isMissingColumnErrorLocal(err)) {
      return fallback;
    }
    console.warn('[reporting:data-and-results] additional comments load failed:', err?.message || err);
    return {
      ...fallback,
      source: 'error',
    };
  }
}

async function writeReportingAdditionalCommentsConfig(fiscalYearStart, commentsPayload, executor = pool) {
  const runner = executor || pool;
  const key = buildReportingAdditionalCommentsKey(fiscalYearStart);
  if (!runner || typeof runner.query !== 'function') {
    return {
      comments: commentsPayload.comments || '',
      source: 'memory',
      scope: REPORTING_ADDITIONAL_COMMENTS_SCOPE,
      key,
      fiscalYearStart,
      fiscalYear: formatReportingFiscalYearLabel(fiscalYearStart),
      updatedAt: null,
    };
  }
  await ensureRuntimeConfigTable();
  await runner.query(
    'INSERT INTO iset_runtime_config (scope,k,v) VALUES (?,?,CAST(? AS JSON)) ON DUPLICATE KEY UPDATE v=VALUES(v), updated_at=CURRENT_TIMESTAMP',
    [
      REPORTING_ADDITIONAL_COMMENTS_SCOPE,
      key,
      JSON.stringify({ comments: commentsPayload.comments || '' }),
    ]
  );
  return readReportingAdditionalCommentsConfig(fiscalYearStart, runner);
}

function normaliseRegionalSnapshotPeriodType(rawValue) {
  const value = normaliseString(rawValue)?.toLowerCase() || '';
  return REGIONAL_SNAPSHOT_PERIOD_TYPES.has(value) ? value : 'year';
}

function normaliseRegionalSnapshotPeriodKey(periodType, rawValue) {
  const value = normaliseString(rawValue)?.toLowerCase() || '';
  if (periodType === 'month') {
    return ['apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec', 'jan', 'feb', 'mar'].includes(value)
      ? value
      : 'apr';
  }
  if (periodType === 'quarter') {
    return ['q1', 'q2', 'q3', 'q4'].includes(value) ? value : 'q1';
  }
  return 'annual';
}

function buildRegionalSnapshotPeriodDefinition(fiscalYearStart, rawPeriodType, rawPeriodKey) {
  const periodType = normaliseRegionalSnapshotPeriodType(rawPeriodType);
  const periodKey = normaliseRegionalSnapshotPeriodKey(periodType, rawPeriodKey);
  const nextYear = fiscalYearStart + 1;
  if (periodType === 'month') {
    const monthMap = {
      apr: { label: 'April', year: fiscalYearStart, month: 4 },
      may: { label: 'May', year: fiscalYearStart, month: 5 },
      jun: { label: 'June', year: fiscalYearStart, month: 6 },
      jul: { label: 'July', year: fiscalYearStart, month: 7 },
      aug: { label: 'August', year: fiscalYearStart, month: 8 },
      sep: { label: 'September', year: fiscalYearStart, month: 9 },
      oct: { label: 'October', year: fiscalYearStart, month: 10 },
      nov: { label: 'November', year: fiscalYearStart, month: 11 },
      dec: { label: 'December', year: fiscalYearStart, month: 12 },
      jan: { label: 'January', year: nextYear, month: 1 },
      feb: { label: 'February', year: nextYear, month: 2 },
      mar: { label: 'March', year: nextYear, month: 3 },
    };
    const monthDef = monthMap[periodKey] || monthMap.apr;
    return {
      periodType,
      periodKey,
      label: monthDef.label,
      fiscalYearStart,
      fiscalYear: formatReportingFiscalYearLabel(fiscalYearStart),
      start: buildReportingIsoDate(monthDef.year, monthDef.month, 1),
      end: buildReportingMonthEndDate(monthDef.year, monthDef.month),
    };
  }
  if (periodType === 'quarter') {
    const quarterDef = buildReportingQuarterSchedule(fiscalYearStart)
      .map(item => ({
        key: item.period.toLowerCase(),
        label: item.period,
        start: item.periodStart,
        end: item.periodEnd,
      }))
      .find(item => item.key === periodKey) || {
        key: 'q1',
        label: 'Q1',
        start: buildReportingIsoDate(fiscalYearStart, 4, 1),
        end: buildReportingIsoDate(fiscalYearStart, 6, 30),
      };
    return {
      periodType,
      periodKey: quarterDef.key,
      label: quarterDef.label,
      fiscalYearStart,
      fiscalYear: formatReportingFiscalYearLabel(fiscalYearStart),
      start: quarterDef.start,
      end: quarterDef.end,
    };
  }
  return {
    periodType: 'year',
    periodKey: 'annual',
    label: `FY ${formatReportingFiscalYearLabel(fiscalYearStart)}`,
    fiscalYearStart,
    fiscalYear: formatReportingFiscalYearLabel(fiscalYearStart),
    start: buildReportingIsoDate(fiscalYearStart, 4, 1),
    end: buildReportingIsoDate(nextYear, 3, 31),
  };
}

function buildRegionalSnapshotEndExclusive(endDate) {
  const date = new Date(`${toDateOnly(endDate)}T00:00:00Z`);
  if (Number.isNaN(date.getTime())) return null;
  date.setUTCDate(date.getUTCDate() + 1);
  return date.toISOString().slice(0, 19).replace('T', ' ');
}

function normaliseRegionalSnapshotText(value, maxLength) {
  const text = typeof value === 'string' ? value.replace(/\r\n?/g, '\n').trim() : '';
  if (!text) return null;
  return text.slice(0, maxLength);
}

function normaliseRegionalSnapshotAmount(value) {
  if (value === null || typeof value === 'undefined' || value === '') return null;
  const numeric = Number(value);
  return Number.isFinite(numeric) ? Number(numeric.toFixed(2)) : NaN;
}

function validateRegionalSnapshotPayload(rawValue) {
  const payload = rawValue && typeof rawValue === 'object' && !Array.isArray(rawValue)
    ? rawValue
    : {};
  const fieldDefs = [
    { key: 'regionalManagerName', maxLength: REGIONAL_SNAPSHOT_NAME_MAX_LENGTH, type: 'text' },
    { key: 'regionalCoordinatorName', maxLength: REGIONAL_SNAPSHOT_NAME_MAX_LENGTH, type: 'text' },
    { key: 'complianceFlag', maxLength: REGIONAL_SNAPSHOT_FLAG_MAX_LENGTH, type: 'text' },
    { key: 'commentsRecommendations', maxLength: REGIONAL_SNAPSHOT_COMMENT_MAX_LENGTH, type: 'text' },
    { key: 'operatingCostsAmount', type: 'amount' },
  ];
  const value = {};
  for (const field of fieldDefs) {
    if (field.type === 'text') {
      value[field.key] = normaliseRegionalSnapshotText(payload[field.key], field.maxLength);
      continue;
    }
    const amount = normaliseRegionalSnapshotAmount(payload[field.key]);
    if (Number.isNaN(amount) || (amount !== null && amount < 0)) {
      return {
        ok: false,
        error: 'invalid_regional_snapshot_amount',
        message: `${field.key} must be a positive amount or blank.`,
      };
    }
    value[field.key] = amount;
  }
  const snapshotStatusRaw = normaliseString(payload.snapshotStatus)?.toLowerCase() || 'draft';
  value.snapshotStatus = REGIONAL_SNAPSHOT_SNAPSHOT_STATUSES.has(snapshotStatusRaw) ? snapshotStatusRaw : 'draft';
  return { ok: true, value };
}

function sumRegionalSnapshotPair(firstValue, secondValue) {
  const first = Number(firstValue);
  const second = Number(secondValue);
  const hasFirst = Number.isFinite(first);
  const hasSecond = Number.isFinite(second);
  if (!hasFirst && !hasSecond) return null;
  return (hasFirst ? first : 0) + (hasSecond ? second : 0);
}

function buildRegionalSnapshotDerivedValues(snapshot, liveMetrics, fundingMetrics) {
  const totalFunding = sumRegionalSnapshotPair(
    fundingMetrics?.crfFundingAmount,
    fundingMetrics?.eiFundingAmount
  );
  const totalAdminCost = sumRegionalSnapshotPair(snapshot?.coordinatorSalaryAmount, snapshot?.operatingCostsAmount);
  const fundedCount = Number(liveMetrics?.funded ?? 0);
  return {
    totalFunding,
    totalAdminCost,
    clientAverageAmountFunded:
      Number.isFinite(totalFunding) && fundedCount > 0 ? totalFunding / fundedCount : null,
    adminCostPerClient:
      Number.isFinite(totalAdminCost) && fundedCount > 0 ? totalAdminCost / fundedCount : null,
    adminRatioPercent:
      Number.isFinite(totalFunding) && totalFunding > 0 && Number.isFinite(totalAdminCost)
        ? (totalAdminCost / totalFunding) * 100
        : null,
  };
}

function resolveRegionalSnapshotPeriodMonthCount(periodType) {
  if (periodType === 'month') return 1;
  if (periodType === 'quarter') return 3;
  return 12;
}

async function readRegionalSnapshotSalaryMetrics(
  { regionCode, fiscalYearStart, periodType },
  executor = pool
) {
  const runner = executor || pool;
  const fallback = {
    annualSalaryAmount: null,
    derivedMonthlyAmount: null,
    coordinatorSalaryAmount: null,
    budgetPotId: null,
    budgetPotName: null,
  };
  if (!runner || typeof runner.query !== 'function' || !regionCode) return fallback;
  try {
    const [rows] = await runner.query(
      `
      SELECT
        frse.annual_salary_amount,
        frse.budget_pot_id,
        bp.name AS budget_pot_name
      FROM finance_regional_salary_entry frse
      LEFT JOIN budget_pot bp ON bp.id = frse.budget_pot_id
      WHERE frse.region_code = ?
        AND frse.fiscal_year_start = ?
      LIMIT 1
      `,
      [regionCode, fiscalYearStart]
    );
    const row = Array.isArray(rows) && rows.length ? rows[0] : null;
    const annualSalaryAmount =
      row?.annual_salary_amount === null || typeof row?.annual_salary_amount === 'undefined'
        ? null
        : Number(Number(row.annual_salary_amount).toFixed(2));
    const derivedMonthlyAmount =
      annualSalaryAmount === null
        ? null
        : Number((annualSalaryAmount / FINANCE_SALARY_MONTH_COUNT).toFixed(2));
    const monthCount = resolveRegionalSnapshotPeriodMonthCount(periodType);
    return {
      annualSalaryAmount,
      derivedMonthlyAmount,
      coordinatorSalaryAmount:
        annualSalaryAmount === null
          ? null
          : Number(((annualSalaryAmount * monthCount) / FINANCE_SALARY_MONTH_COUNT).toFixed(2)),
      budgetPotId: row?.budget_pot_id ? Number(row.budget_pot_id) : null,
      budgetPotName: row?.budget_pot_name || null,
    };
  } catch (err) {
    if (isMissingTableErrorLocal(err) || isMissingColumnErrorLocal(err)) {
      return fallback;
    }
    throw err;
  }
}

async function readRegionalSnapshotRegionOptions(executor = pool) {
  const runner = executor || pool;
  if (!runner || typeof runner.query !== 'function') return [];
  const [rows] = await runner.query(
    'SELECT region_id, code, name_en FROM canada_region ORDER BY CASE WHEN code = ? THEN 1 ELSE 0 END, name_en ASC',
    ['XX']
  );
  return Array.isArray(rows)
    ? rows.map(row => ({
        regionId: Number(row.region_id),
        code: row.code,
        name: row.name_en,
      }))
    : [];
}

async function readRegionalSnapshotDefaults(regionId, executor = pool) {
  const runner = executor || pool;
  if (!runner || typeof runner.query !== 'function') {
    return { regionalManagerName: null, regionalCoordinatorName: null };
  }
  const [rows] = await runner.query(
    `
    SELECT
      primary_role,
      COALESCE(NULLIF(TRIM(display_name), ''), NULLIF(TRIM(name), ''), NULLIF(TRIM(email), '')) AS label
    FROM staff_profiles
    WHERE status = 'active'
      AND region_id = ?
      AND primary_role IN ('Regional Manager', 'ISET Coordinator')
    ORDER BY label ASC
    `,
    [regionId]
  );
  const manager = (rows || []).find(row => row.primary_role === 'Regional Manager');
  const coordinator = (rows || []).find(row => row.primary_role === 'ISET Coordinator');
  return {
    regionalManagerName: manager?.label || null,
    regionalCoordinatorName: coordinator?.label || null,
  };
}

async function readRegionalSnapshotRow({ regionId, periodType, periodStart, periodEnd }, executor = pool) {
  const runner = executor || pool;
  if (!runner || typeof runner.query !== 'function') return null;
  const [rows] = await runner.query(
    `
    SELECT
      rs.*,
      COALESCE(NULLIF(TRIM(cb.display_name), ''), NULLIF(TRIM(cb.name), ''), NULLIF(TRIM(cb.email), '')) AS created_by_name,
      COALESCE(NULLIF(TRIM(ub.display_name), ''), NULLIF(TRIM(ub.name), ''), NULLIF(TRIM(ub.email), '')) AS updated_by_name
    FROM iset_regional_snapshot_report rs
    LEFT JOIN staff_profiles cb ON cb.id = rs.created_by_staff_profile_id
    LEFT JOIN staff_profiles ub ON ub.id = rs.updated_by_staff_profile_id
    WHERE rs.region_id = ?
      AND rs.period_type = ?
      AND rs.period_start = ?
      AND rs.period_end = ?
    LIMIT 1
    `,
    [regionId, periodType, periodStart, periodEnd]
  );
  return Array.isArray(rows) && rows.length ? rows[0] : null;
}

function buildRegionalSnapshotProvinceFilter(regionCode) {
  const provinceCode = normaliseReportingProvinceCode(regionCode);
  return provinceCode && provinceCode !== 'XX' ? [provinceCode] : [];
}

function isRegionalSnapshotFundedApplication(row) {
  const decisionOutcome = normaliseApplicationDecisionOutcomeValue(row?.decision_outcome);
  if (decisionOutcome === 'approved') return true;
  if (decisionOutcome === 'denied') return false;
  const status = normaliseApplicationStatusValue(row?.status);
  return status === 'approved' || status === 'completed';
}

function isRegionalSnapshotDeniedApplication(row) {
  const decisionOutcome = normaliseApplicationDecisionOutcomeValue(row?.decision_outcome);
  if (decisionOutcome === 'denied') return true;
  if (decisionOutcome === 'approved') return false;
  const status = normaliseApplicationStatusValue(row?.status);
  return ['rejected', 'declined', 'denied', 'withdrawn', 'cancelled'].includes(status);
}

function isRegionalSnapshotPendingApplication(row) {
  if (isRegionalSnapshotFundedApplication(row) || isRegionalSnapshotDeniedApplication(row)) {
    return false;
  }
  const status = normaliseApplicationStatusValue(row?.status);
  return !['closed', 'archived'].includes(status);
}

async function readRegionalSnapshotLiveMetrics({ regionCode, periodStart, periodEnd }, executor = pool) {
  const runner = executor || pool;
  const fallback = {
    applicationsReceived: 0,
    funded: 0,
    fundedApplications: 0,
    deniedIneligibleWithdrawn: 0,
    pendingDecision: 0,
  };
  if (!runner || typeof runner.query !== 'function') return fallback;
  const startDateTime = `${toDateOnly(periodStart)} 00:00:00`;
  const endExclusive = buildRegionalSnapshotEndExclusive(periodEnd);
  if (!endExclusive) return fallback;
  const provinceCodes = buildRegionalSnapshotProvinceFilter(regionCode);
  const clientProvinceExpr = `COALESCE(
    NULLIF(JSON_UNQUOTE(JSON_EXTRACT(cl.address_json, '$.address.province')), ''),
    NULLIF(JSON_UNQUOTE(JSON_EXTRACT(cl.address_json, '$.address.provinceCode')), ''),
    NULLIF(JSON_UNQUOTE(JSON_EXTRACT(cl.address_json, '$.province')), ''),
    NULLIF(JSON_UNQUOTE(JSON_EXTRACT(cl.address_json, '$.provinceCode')), '')
  )`;
  try {
    const [rows] = await runner.query(
      `
      SELECT
        a.id AS application_id,
        a.status,
        a.decision_outcome,
        s.id AS submission_id,
        s.submitted_at,
        COALESCE(a.updated_at, a.created_at) AS decision_at,
        (s.submitted_at >= ? AND s.submitted_at < ?) AS submitted_in_period,
        (COALESCE(a.updated_at, a.created_at) >= ? AND COALESCE(a.updated_at, a.created_at) < ?) AS decision_in_period,
        ${REPORTING_ADDRESS_PROVINCE_EXPR} AS submission_address_province,
        ${clientProvinceExpr} AS client_address_province
      FROM iset_application a
      JOIN iset_case c ON ${APPLICATION_CASE_JOIN_PREDICATE}
      LEFT JOIN client cl ON cl.id = c.client_id
      LEFT JOIN iset_application_submission s ON s.id = a.submission_id
      LEFT JOIN iset_application_submission ias ON ias.id = a.submission_id
      WHERE (
        (s.submitted_at >= ? AND s.submitted_at < ?)
        OR (COALESCE(a.updated_at, a.created_at) >= ? AND COALESCE(a.updated_at, a.created_at) < ?)
      )
      `,
      [
        startDateTime,
        endExclusive,
        startDateTime,
        endExclusive,
        startDateTime,
        endExclusive,
        startDateTime,
        endExclusive,
      ]
    );

    const applicationsReceivedSet = new Set();
    const fundedApplicationsSet = new Set();
    const deniedSet = new Set();
    const pendingSet = new Set();

    (rows || [])
      .filter(row => matchesReportingProvinceFilter(buildMetricProvince(row), provinceCodes))
      .forEach(row => {
        const applicationId = normalisePositiveInteger(row?.application_id);
        const submissionId = normalisePositiveInteger(row?.submission_id);
        const applicationKey = applicationId ? `application-${applicationId}` : null;
        if (Number(row?.submitted_in_period || 0)) {
          applicationsReceivedSet.add(submissionId ? `submission-${submissionId}` : applicationKey);
          if (applicationKey && isRegionalSnapshotPendingApplication(row)) {
            pendingSet.add(applicationKey);
          }
        }
        if (applicationKey && Number(row?.decision_in_period || 0)) {
          if (isRegionalSnapshotFundedApplication(row)) {
            fundedApplicationsSet.add(applicationKey);
          } else if (isRegionalSnapshotDeniedApplication(row)) {
            deniedSet.add(applicationKey);
          }
        }
      });

    const applicationsReceived = Array.from(applicationsReceivedSet).filter(Boolean).length;
    const fundedApplications = fundedApplicationsSet.size;
    const deniedIneligibleWithdrawn = deniedSet.size;
    return {
      applicationsReceived,
      funded: fundedApplications,
      fundedApplications,
      deniedIneligibleWithdrawn,
      pendingDecision: pendingSet.size,
    };
  } catch (err) {
    if (isMissingTableErrorLocal(err) || isMissingColumnErrorLocal(err)) {
      return fallback;
    }
    throw err;
  }
}

async function readRegionalSnapshotFundingMetrics({
  regionCode,
  fiscalYearStart,
  periodType,
  periodKey,
}, executor = pool) {
  const runner = executor || pool;
  const fallback = {
    crfFundingAmount: 0,
    eiFundingAmount: 0,
    fundedClientCount: 0,
    fundedInterventionCount: 0,
  };
  if (!runner || typeof runner.query !== 'function') return fallback;
  try {
    const provinceCodes = buildRegionalSnapshotProvinceFilter(regionCode);
    const financePayload = await readFinanceInterventionReportPayload(
      {
        fiscalYearStart,
        periodType,
        periodKey,
        provinces: provinceCodes,
        includeCarryOver: false,
      },
      runner
    );
    const fundedRows = (Array.isArray(financePayload?.rows) ? financePayload.rows : [])
      .filter(row => Number(row?.totalAmount || 0) > 0);
    const summary = buildFinanceInterventionReportSummary(fundedRows, {
      includeCarryOver: false,
    });

    return {
      crfFundingAmount: summary.fundingTotals.CRF,
      eiFundingAmount: summary.fundingTotals.EI,
      fundedClientCount: summary.participantCount,
      fundedInterventionCount: summary.interventionCount,
    };
  } catch (err) {
    if (isMissingTableErrorLocal(err) || isMissingColumnErrorLocal(err)) {
      return fallback;
    }
    throw err;
  }
}

async function buildRegionalSnapshotPayload({
  regionId,
  fiscalYearStart,
  periodType,
  periodKey,
  executor = pool,
}) {
  const period = buildRegionalSnapshotPeriodDefinition(fiscalYearStart, periodType, periodKey);
  const [regionRows] = await executor.query(
    'SELECT region_id, code, name_en FROM canada_region WHERE region_id = ? LIMIT 1',
    [regionId]
  );
  const regionRow = Array.isArray(regionRows) && regionRows.length ? regionRows[0] : null;
  if (!regionRow) {
    const error = new Error('Region not found.');
    error.statusCode = 404;
    throw error;
  }
  const [snapshotRow, defaults, liveMetrics, fundingMetrics] = await Promise.all([
    readRegionalSnapshotRow({
      regionId,
      periodType: period.periodType,
      periodStart: period.start,
      periodEnd: period.end,
    }, executor),
    readRegionalSnapshotDefaults(regionId, executor),
    readRegionalSnapshotLiveMetrics({
      regionCode: regionRow.code,
      periodStart: period.start,
      periodEnd: period.end,
    }, executor),
    readRegionalSnapshotFundingMetrics({
      regionCode: regionRow.code,
      fiscalYearStart,
      periodType: period.periodType,
      periodKey: period.periodKey,
    }, executor),
  ]);
  const salaryMetrics = await readRegionalSnapshotSalaryMetrics(
    {
      regionCode: regionRow.code,
      fiscalYearStart,
      periodType: period.periodType,
    },
    executor
  );

  const snapshot = {
    id: snapshotRow?.id ? Number(snapshotRow.id) : null,
    snapshotStatus: snapshotRow?.snapshot_status || 'draft',
    regionalManagerName: snapshotRow?.regional_manager_name || defaults.regionalManagerName || '',
    regionalCoordinatorName: snapshotRow?.regional_coordinator_name || defaults.regionalCoordinatorName || '',
    coordinatorSalaryAmount: salaryMetrics.coordinatorSalaryAmount,
    operatingCostsAmount: snapshotRow?.operating_costs_amount !== null && snapshotRow?.operating_costs_amount !== undefined ? Number(snapshotRow.operating_costs_amount) : null,
    complianceFlag: snapshotRow?.compliance_flag || '',
    commentsRecommendations: snapshotRow?.comments_recommendations || '',
    updatedAt: snapshotRow?.updated_at ? toIsoDateTime(snapshotRow.updated_at) : null,
    updatedByName: snapshotRow?.updated_by_name || null,
    createdAt: snapshotRow?.created_at ? toIsoDateTime(snapshotRow.created_at) : null,
    createdByName: snapshotRow?.created_by_name || null,
  };
  const mergedLiveMetrics = {
    ...liveMetrics,
    funded:
      Number.isFinite(Number(fundingMetrics?.fundedClientCount))
        ? Number(fundingMetrics.fundedClientCount)
        : Number(liveMetrics?.funded || 0),
  };
  return {
    region: {
      regionId: Number(regionRow.region_id),
      code: regionRow.code,
      name: regionRow.name_en,
    },
    period,
    liveMetrics: mergedLiveMetrics,
    fundingMetrics,
    salaryMetrics,
    snapshot,
    derivedMetrics: buildRegionalSnapshotDerivedValues(snapshot, mergedLiveMetrics, fundingMetrics),
  };
}

function normaliseReportingProvinceCodes(rawValue) {
  const inputs = Array.isArray(rawValue)
    ? rawValue
    : String(rawValue || '')
      .split(',');
  return Array.from(
    new Set(
      inputs
        .map(value => {
          const normalised = normaliseString(value);
          if (!normalised) return null;
          return PROVINCE_CODE_MAP[normalised.toLowerCase()] || normalised.toUpperCase();
        })
        .filter(code => code && /^[A-Z]{2}$/.test(code))
    )
  );
}

function normaliseReportingCaseManagerIds(rawValue) {
  const inputs = Array.isArray(rawValue)
    ? rawValue
    : String(rawValue || '')
      .split(',');
  return Array.from(
    new Set(
      inputs
        .map(value => normalisePositiveInteger(value))
        .filter(Boolean)
    )
  );
}

function matchesReportingCaseManagerFilter(rawAssignedToUserId, caseManagerIds) {
  if (!Array.isArray(caseManagerIds) || !caseManagerIds.length) {
    return true;
  }
  const assignedToUserId = normalisePositiveInteger(rawAssignedToUserId);
  return Boolean(assignedToUserId && caseManagerIds.includes(assignedToUserId));
}

function normaliseReportingInterventionStatusView(rawValue) {
  const value = normaliseString(rawValue)?.toLowerCase() || '';
  return REPORTING_INTERVENTION_STATUS_GROUPS[value] ? value : 'completed';
}

function normaliseReportingInterventionMeasure(rawValue) {
  const value = normaliseString(rawValue)?.toLowerCase() || '';
  return REPORTING_INTERVENTION_MEASURES.has(value) ? value : 'count';
}

function normaliseReportingResultsView(rawValue) {
  const value = normaliseString(rawValue)?.toLowerCase() || '';
  return REPORTING_RESULTS_VIEW_MODES.has(value) ? value : 'cumulative';
}

function normaliseReportingApplicationActivityMetric(rawValue) {
  const value = normaliseString(rawValue) || '';
  return REPORTING_APPLICATION_ACTIVITY_METRICS.has(value) ? value : 'newApplications';
}

function normaliseReportingInterventionDateBasis(rawValue) {
  const value = normaliseString(rawValue)?.toLowerCase() || '';
  if (value === 'payment' || value === 'payment_month' || value === 'bypaymentmonth') {
    return 'payment';
  }
  if (value === 'start' || value === 'start_date' || value === 'bystartdate') {
    return 'start';
  }
  return 'end';
}

function resolveReportingInterventionStatusKey(record) {
  const state = resolveInterventionStateFields(record, { fallbackStatus: null });
  return state.deliveryStatus || (state.reviewStatus === 'approved' ? 'planned' : null);
}

function matchesReportingInterventionStatus(record, statusView) {
  const allowedStatuses =
    REPORTING_INTERVENTION_STATUS_GROUPS[normaliseReportingInterventionStatusView(statusView)] ||
    REPORTING_INTERVENTION_STATUS_GROUPS.completed;
  const statusKey = resolveReportingInterventionStatusKey(record);
  return Boolean(statusKey && allowedStatuses.has(statusKey));
}

function resolveReportingInterventionBucketDate(row, dateBasis) {
  if (normaliseReportingInterventionDateBasis(dateBasis) === 'start') {
    return toDateOnly(row?.started_on);
  }
  return toDateOnly(row?.ended_on);
}

function addDaysToDateOnlyValue(isoDate, days) {
  const date = isoDate ? new Date(`${isoDate}T00:00:00Z`) : null;
  if (!date || Number.isNaN(date.getTime())) return null;
  date.setUTCDate(date.getUTCDate() + Number(days || 0));
  return date.toISOString().slice(0, 10);
}

function resolveReportingSnapshotPeriod(snapshotPeriods, rawPeriodKey) {
  const periodKey = normaliseString(rawPeriodKey) || '';
  if (!periodKey) return null;
  return (Array.isArray(snapshotPeriods) ? snapshotPeriods : []).find(
    period => normaliseString(period?.key) === periodKey
  ) || null;
}

function resolveReportingDrilldownRange({
  snapshotPeriods,
  fiscalYearStartDate,
  rawPeriodKey,
  resultsView,
}) {
  const period = resolveReportingSnapshotPeriod(snapshotPeriods, rawPeriodKey);
  if (!period) return null;
  const normalizedResultsView = normaliseReportingResultsView(resultsView);
  if (normalizedResultsView === 'monthly' && period.key !== 'Final (p14)') {
    const periodIndex = snapshotPeriods.findIndex(entry => entry?.key === period.key);
    const previousPeriod = periodIndex > 0 ? snapshotPeriods[periodIndex - 1] : null;
    return {
      period,
      startDate: previousPeriod ? addDaysToDateOnlyValue(previousPeriod.cutoff, 1) : fiscalYearStartDate,
      endDate: period.cutoff,
    };
  }
  return {
    period,
    startDate: fiscalYearStartDate,
    endDate: period.cutoff,
  };
}

function buildReportingDrilldownTitleSecondaryText(reference, eventDate, eventLabel) {
  return buildMetricSubtitle(
    reference,
    buildMetricDateLabel(eventDate, eventLabel)
  );
}

function scaleReportingCurrencyAmounts(amounts, targetTotal) {
  const list = Array.isArray(amounts) ? amounts.map(value => Number(value) || 0) : [];
  const targetCents = Math.max(0, Math.round(Number(targetTotal || 0) * 100));
  if (!list.length) return [];
  if (!targetCents) return list.map(() => 0);
  const sourceCents = list.map(value => Math.max(0, Math.round(value * 100)));
  const sourceTotal = sourceCents.reduce((sum, value) => sum + value, 0);
  if (!sourceTotal) {
    const evenAllocation = list.map(() => 0);
    for (let index = 0; index < targetCents; index += 1) {
      evenAllocation[index % evenAllocation.length] += 1;
    }
    return evenAllocation.map(value => value / 100);
  }
  const rawAllocations = sourceCents.map(value => (targetCents * value) / sourceTotal);
  const scaledCents = rawAllocations.map(value => Math.floor(value));
  let remaining = targetCents - scaledCents.reduce((sum, value) => sum + value, 0);
  const remainderOrder = rawAllocations
    .map((value, index) => ({
      index,
      remainder: value - scaledCents[index],
      weight: sourceCents[index],
    }))
    .sort((left, right) =>
      right.remainder - left.remainder ||
      right.weight - left.weight ||
      left.index - right.index
    );
  for (let index = 0; index < remainderOrder.length && remaining > 0; index += 1) {
    scaledCents[remainderOrder[index].index] += 1;
    remaining -= 1;
  }
  return scaledCents.map(value => value / 100);
}

function resolveReportingInterventionScheduledDate(lineInput, interventionRow, submissionTimingByType) {
  const submissionTiming = resolveCostLineSubmissionTiming(
    { type: lineInput?.paymentType || null },
    submissionTimingByType
  );
  const interventionStartDate = toDateOnly(interventionRow?.started_on || interventionRow?.start_date || null);
  const interventionEndDate = toDateOnly(interventionRow?.ended_on || interventionRow?.end_date || null);
  const requestedDate = toDateOnly(lineInput?.requestedPaymentDate || lineInput?.requested_payment_date || null);
  const serviceStart = toDateOnly(lineInput?.servicePeriodStart || lineInput?.service_period_start || null);
  const serviceEnd = toDateOnly(lineInput?.servicePeriodEnd || lineInput?.service_period_end || null);
  if (submissionTiming === 'intervention_start') {
    return interventionStartDate || serviceStart || requestedDate || null;
  }
  if (submissionTiming === 'intervention_end') {
    return interventionEndDate || serviceEnd || requestedDate || interventionStartDate || null;
  }
  if (submissionTiming === 'recurrence_schedule') {
    return requestedDate || serviceStart || interventionStartDate || null;
  }
  return requestedDate || serviceStart || interventionStartDate || null;
}

function buildReportingInterventionAmountEntries(
  row,
  {
    paymentTypeMapping = null,
    recurrencePolicyByType = null,
    submissionTimingByType = null,
    statusView = 'completed',
  } = {}
) {
  const metadata = safeJsonParse(row?.metadata_json, null) || {};
  const snapshotSource = metadata?.snapshot && typeof metadata.snapshot === 'object'
    ? metadata.snapshot
    : {};
  const mergedCostLines = Array.isArray(metadata.costLines)
    ? metadata.costLines
    : Array.isArray(metadata.cost_lines)
    ? metadata.cost_lines
    : Array.isArray(snapshotSource.costLines)
    ? snapshotSource.costLines
    : [];
  const allowedPaymentTypes = paymentTypeMapping
    ? resolveAllowedPaymentTypesForIntervention(paymentTypeMapping, row)
    : null;
  const paymentLines = buildAutoPaymentLinesFromCostLines({
    interventionRow: {
      ...row,
      start_date: row?.started_on ?? row?.start_date ?? null,
      end_date: row?.ended_on ?? row?.end_date ?? null,
    },
    interventionMetadata: {
      ...metadata,
      costLines: mergedCostLines,
    },
    clientPayeeName: 'Client',
    partnerName: null,
    fallbackPayeeType: 'Client',
    fallbackPayeeName: 'Client',
    allowedPaymentTypes,
    recurrencePolicyByType,
  });
  let entries = paymentLines
    .map(line => ({
      date: resolveReportingInterventionScheduledDate(line, row, submissionTimingByType),
      amount: Number(line?.amount || 0),
    }))
    .filter(entry => entry.date && Number.isFinite(entry.amount) && entry.amount > 0);

  const plannedTotalFromEntries = entries.reduce((sum, entry) => sum + entry.amount, 0);
  const plannedTotalFallback = parseCurrencyValue(
    metadata.costTotal ??
    snapshotSource.costTotal ??
    metadata.cost ??
    snapshotSource.cost ??
    row?.intervention_cost ??
    row?.budget_amount ??
    row?.approved_amount ??
    null
  );
  const plannedTotal = plannedTotalFromEntries > 0
    ? Math.round(plannedTotalFromEntries * 100) / 100
    : (Number.isFinite(plannedTotalFallback) ? plannedTotalFallback : null);
  const actualTotal = parseCurrencyValue(row?.actual_amount ?? null);
  const resolvedTotal =
    statusView === 'completed' && Number.isFinite(actualTotal) && actualTotal > 0
      ? actualTotal
      : plannedTotal;

  if (entries.length && Number.isFinite(resolvedTotal) && resolvedTotal > 0) {
    const scaledAmounts = scaleReportingCurrencyAmounts(
      entries.map(entry => entry.amount),
      resolvedTotal
    );
    entries = entries.map((entry, index) => ({
      ...entry,
      amount: scaledAmounts[index],
    }));
    return entries;
  }

  if (Number.isFinite(resolvedTotal) && resolvedTotal > 0) {
    const fallbackDate =
      toDateOnly(row?.ended_on || null) ||
      toDateOnly(row?.started_on || null) ||
      toDateOnly(row?.start_date || null) ||
      toDateOnly(row?.end_date || null) ||
      null;
    if (fallbackDate) {
      return [{ date: fallbackDate, amount: Math.round(resolvedTotal * 100) / 100 }];
    }
  }

  return entries;
}

async function fetchReportingApplicationActivityDrilldown({
  executor = pool,
  startDate,
  endDate,
  provinceCodes = [],
  caseManagerIds = [],
  metric = 'newApplications',
  provinceCode,
}) {
  try {
    const normalizedMetric = normaliseReportingApplicationActivityMetric(metric);
    const normalizedProvinceCode = normaliseReportingProvinceCode(provinceCode);
    if (!normalizedProvinceCode || !REPORTING_APPLICATION_ACTIVITY_ROW_CODE_SET.has(normalizedProvinceCode)) {
      return {
        truncated: false,
        items: [],
      };
    }

    const dateExpr =
      normalizedMetric === 'newApplications'
        ? 'ias.submitted_at'
        : 'COALESCE(a.updated_at, a.created_at)';
    const statusFilterSql =
      normalizedMetric === 'approvedApplications'
        ? `AND REPLACE(LOWER(TRIM(a.status)), ' ', '_') IN ('approved', 'completed')`
        : normalizedMetric === 'deniedApplications'
        ? `AND REPLACE(LOWER(TRIM(a.status)), ' ', '_') IN ('rejected', 'declined')`
        : '';
    const eventLabel = normalizedMetric === 'newApplications' ? 'Submitted' : 'Decision';

    const [rows] = await executor.query(
      `
      SELECT
        a.id AS application_id,
        a.status AS application_status,
        REPLACE(LOWER(TRIM(a.status)), ' ', '_') AS status_key,
        ${dateExpr} AS metric_event_at,
        c.id AS case_id,
        c.case_number,
        c.status AS case_status,
c.assigned_staff_profile_id AS assigned_to_user_id,
        cl.first_name AS client_first_name,
        cl.last_name AS client_last_name,
        COALESCE(
          JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.submission_snapshot.reference_number')),
          ias.reference_number
        ) AS tracking_id,
        JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$."first-name"')) AS submission_first_name,
        JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$."last-name"')) AS submission_last_name,
        JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$."preferred-name"')) AS submission_preferred_name,
        ${REPORTING_ADDRESS_PROVINCE_EXPR} AS submission_address_province,
        sp.display_name AS owner_display_name,
        sp.name AS owner_name,
        sp.email AS assigned_user_email,
        sp.primary_role AS assigned_user_role,
        sp.region_id AS assigned_user_region_id
      FROM iset_application a
      LEFT JOIN iset_application_submission ias ON ias.id = a.submission_id
      LEFT JOIN iset_case c ON ${APPLICATION_CASE_JOIN_PREDICATE}
      LEFT JOIN client cl ON cl.id = c.client_id
      LEFT JOIN staff_profiles sp ON sp.id = c.assigned_staff_profile_id
      WHERE ${dateExpr} IS NOT NULL
        AND DATE(${dateExpr}) BETWEEN ? AND ?
        ${statusFilterSql}
      ORDER BY ${dateExpr} DESC, a.id DESC
      LIMIT ${METRICS_DETAIL_FETCH_LIMIT}
      `,
      [startDate, endDate]
    );

    const filteredRows = (Array.isArray(rows) ? rows : []).filter(row =>
      matchesReportingProvinceFilter(row.submission_address_province, provinceCodes) &&
      matchesReportingProvinceFilter(row.submission_address_province, [normalizedProvinceCode]) &&
      matchesReportingCaseManagerFilter(row.assigned_to_user_id, caseManagerIds)
    );

    return mapMetricApplicationRows(filteredRows, { eventLabel });
  } catch (err) {
    if (isMissingTableErrorLocal(err) || isMissingColumnErrorLocal(err)) {
      return { items: [], truncated: false };
    }
    throw err;
  }
}

async function fetchReportingInterventionDrilldown({
  executor = pool,
  startDate,
  endDate,
  provinceCodes = [],
  caseManagerIds = [],
  rowLabel = 'TOTAL',
  measure = 'count',
  statusView = 'completed',
  dateBasis = 'end',
  paymentTypeMapping = null,
  recurrencePolicyByType = null,
}) {
  try {
    const normalizedMeasure = normaliseReportingInterventionMeasure(measure);
    const normalizedRowLabel = normaliseString(rowLabel) || 'TOTAL';
    const normalizedDateBasis = normalizedMeasure === 'cost'
      ? 'payment'
      : normaliseReportingInterventionDateBasis(dateBasis);
    const eventLabel =
      normalizedMeasure === 'cost'
        ? 'Payment month'
        : normalizedDateBasis === 'start'
        ? 'Start date'
        : 'End date';

    const [rows] = await executor.query(
      `
      SELECT
        ci.id AS intervention_id,
        ci.case_id,
        ci.status AS intervention_status,
        ci.delivery_status AS intervention_delivery_status,
        ci.intervention_code,
        ci.metadata_json,
        ci.intervention_cost,
        ci.budget_amount,
        ci.approved_amount,
        ci.actual_amount,
        ci.start_date AS intervention_start_date,
        ci.start_date AS started_on,
        COALESCE(ci.end_date, DATE(ci.closed_at)) AS ended_on,
        c.case_number,
c.assigned_staff_profile_id AS assigned_to_user_id,
        a.id AS application_id,
        cl.first_name AS client_first_name,
        cl.last_name AS client_last_name,
        COALESCE(
          JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.submission_snapshot.reference_number')),
          ias.reference_number
        ) AS tracking_id,
        JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$."first-name"')) AS submission_first_name,
        JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$."last-name"')) AS submission_last_name,
        JSON_UNQUOTE(JSON_EXTRACT(ias.intake_payload, '$."preferred-name"')) AS submission_preferred_name,
        ${REPORTING_ADDRESS_PROVINCE_EXPR} AS submission_address_province,
        sp.display_name AS owner_display_name,
        sp.name AS owner_name,
        sp.email AS assigned_user_email,
        sp.primary_role AS assigned_user_role,
        sp.region_id AS assigned_user_region_id,
        ic.label AS intervention_label
      FROM iset_case_intervention ci
      JOIN iset_case c ON c.id = ci.case_id
      ${buildCasePrimaryApplicationJoinSql('c', 'a')}
      LEFT JOIN iset_application_submission ias ON ias.id = a.submission_id
      LEFT JOIN client cl ON cl.id = c.client_id
      LEFT JOIN staff_profiles sp ON sp.id = c.assigned_staff_profile_id
      LEFT JOIN esdc_intervention_code ic ON ic.code = ci.intervention_code
      WHERE ci.intervention_code IS NOT NULL
        AND (
          (ci.start_date IS NOT NULL AND ci.start_date <= ?)
          OR (
            COALESCE(ci.end_date, DATE(ci.closed_at)) IS NOT NULL
            AND COALESCE(ci.end_date, DATE(ci.closed_at)) <= ?
          )
        )
      ORDER BY COALESCE(ci.end_date, DATE(ci.closed_at), ci.start_date, DATE(ci.updated_at), DATE(ci.created_at)) DESC,
        ci.id DESC
      LIMIT ${METRICS_DETAIL_FETCH_LIMIT}
      `,
      [endDate, endDate]
    );

    const scopedRows = (Array.isArray(rows) ? rows : []).filter(row => {
      if (!matchesReportingInterventionStatus(row, statusView)) {
        return false;
      }
      if (!matchesReportingProvinceFilter(row.submission_address_province, provinceCodes)) {
        return false;
      }
      if (!matchesReportingCaseManagerFilter(row.assigned_to_user_id, caseManagerIds)) {
        return false;
      }
      if (normalizedRowLabel === 'TOTAL') {
        return true;
      }
      const resolvedLabel = REPORTING_INTERVENTION_LABEL_BY_CODE[Number(row.intervention_code)] || null;
      return resolvedLabel === normalizedRowLabel;
    });

    if (normalizedMeasure === 'count') {
      const filteredRows = scopedRows
        .map(row => ({
          ...row,
          metric_event_at: resolveReportingInterventionBucketDate(row, normalizedDateBasis),
        }))
        .filter(row =>
          Boolean(
            row.metric_event_at &&
            row.metric_event_at >= startDate &&
            row.metric_event_at <= endDate
          )
        );

      return mapMetricInterventionRows(filteredRows, { eventLabel });
    }

    const submissionTimingByType = buildSubmissionTimingByTypeLookup(paymentTypeMapping);
    const items = [];

    scopedRows.forEach((row, rowIndex) => {
      const amountEntries = buildReportingInterventionAmountEntries(row, {
        paymentTypeMapping,
        recurrencePolicyByType,
        submissionTimingByType,
        statusView,
      }).filter(entry => entry.date >= startDate && entry.date <= endDate);

      if (!amountEntries.length) {
        return;
      }

      const caseId = normalisePositiveInteger(row?.case_id) || null;
      const interventionId = normalisePositiveInteger(row?.intervention_id) || null;
      const applicantName = buildMetricApplicantName(row);
      const reference =
        normaliseString(row?.case_number) ||
        buildMetricReference(row) ||
        (caseId ? `CASE-${caseId}` : null);
      const resolvedInterventionLabel =
        normaliseString(row?.intervention_label) ||
        (interventionId ? `Intervention ${interventionId}` : null);
      const reportingStatus = resolveReportingInterventionStatusKey(row);

      amountEntries.forEach((entry, entryIndex) => {
        items.push({
          id: `reporting-intervention-cost-${interventionId || rowIndex}-${entry.date}-${entryIndex}`,
          caseId,
          case_id: caseId,
          applicationId: normalisePositiveInteger(row?.application_id) || null,
          application_id: normalisePositiveInteger(row?.application_id) || null,
          interventionId,
          intervention_id: interventionId,
          trackingId: buildMetricReference(row),
          applicantName,
          applicant_name: applicantName,
          address_province: buildMetricProvince(row),
          owner: buildMetricOwnerLabel(row),
          ...buildAssignedStaffProfileResponseFields(row),
          assigned_user_email: normaliseString(row?.assigned_user_email) || null,
          assigned_user_role: normaliseString(row?.assigned_user_role) || null,
          assigned_user_region_id: normalisePositiveInteger(row?.assigned_user_region_id) || null,
          status: reportingStatus,
          type: 'Intervention',
          delivery_status: normaliseString(row?.intervention_delivery_status) || null,
          deliveryStatus: normaliseString(row?.intervention_delivery_status) || null,
          intervention_status: normaliseString(row?.intervention_status) || null,
          intervention_delivery_status: normaliseString(row?.intervention_delivery_status) || null,
          intervention_effective_status: reportingStatus,
          intervention_code: normaliseString(row?.intervention_code) || null,
          intervention_label: resolvedInterventionLabel,
          intervention_start_date: row?.intervention_start_date || null,
          metricEventDate: toIsoDateTime(entry.date),
          amount: Number(entry.amount || 0),
          titleSecondaryText: buildReportingDrilldownTitleSecondaryText(reference, entry.date, eventLabel),
          workspacePath: buildMetricWorkspacePath({ caseId, mode: 'intervention' }),
        });
      });
    });

    items.sort((left, right) => {
      const rightDate = normaliseString(right?.metricEventDate) || '';
      const leftDate = normaliseString(left?.metricEventDate) || '';
      if (rightDate !== leftDate) {
        return rightDate.localeCompare(leftDate);
      }
      return Number(right?.amount || 0) - Number(left?.amount || 0);
    });

    return truncateMetricDetailRows(items);
  } catch (err) {
    if (isMissingTableErrorLocal(err) || isMissingColumnErrorLocal(err)) {
      return { items: [], truncated: false };
    }
    throw err;
  }
}

function mapReportingPackageStatus(status) {
  const key = normaliseString(status)?.toLowerCase() || '';
  if (key === 'accepted') return { statusKey: 'accepted', statusLabel: 'Accepted' };
  if (key === 'submitted') return { statusKey: 'submitted', statusLabel: 'Submitted' };
  if (key === 'ready') return { statusKey: 'ready', statusLabel: 'Ready to submit' };
  if (key === 'in_review') return { statusKey: 'in-review', statusLabel: 'In review' };
  if (key === 'rejected') return { statusKey: 'rejected', statusLabel: 'Rejected' };
  return { statusKey: 'pending', statusLabel: 'Pending' };
}

app.get('/api/reporting/data-and-results/filter-options', async (req, res) => {
  if (!hasOperationalReportingAccess(req)) {
    return res.status(403).json({ error: 'forbidden' });
  }

  const fiscalYearStart = resolveReportingFiscalYearStartValue(
    req.query.fiscalYearStart ?? req.query.fiscalYear
  );

  try {
    const [rows] = await pool.query(
      `
      SELECT
        sp.id,
        COALESCE(NULLIF(TRIM(sp.display_name), ''), NULLIF(TRIM(sp.name), ''), NULLIF(TRIM(sp.email), ''), CONCAT('Staff #', sp.id)) AS label,
        sp.primary_role
      FROM staff_profiles sp
      WHERE sp.status = 'active'
        AND sp.primary_role IN (${REPORTING_CASE_MANAGER_ROLE_KEYS.map(() => '?').join(', ')})
      ORDER BY label ASC
      `,
      REPORTING_CASE_MANAGER_ROLE_KEYS
    );

    const caseManagers = Array.isArray(rows) && rows.length
      ? rows.map(row => ({
          value: String(row.id),
          label: row.label,
          role: normaliseString(row.primary_role) || null,
        }))
      : [];

    res.set('Cache-Control', 'no-store, max-age=0');
    return res.json({
      fiscalYearStart,
      fiscalYear: formatReportingFiscalYearLabel(fiscalYearStart),
      caseManagers,
    });
  } catch (err) {
    if (isMissingTableErrorLocal(err) || isMissingColumnErrorLocal(err)) {
      res.set('Cache-Control', 'no-store, max-age=0');
      return res.json({
        fiscalYearStart,
        fiscalYear: formatReportingFiscalYearLabel(fiscalYearStart),
        caseManagers: [],
      });
    }
    console.error('[reporting:data-and-results] filter options fetch failed:', err?.message || err);
    return res.status(500).json({
      error: 'reporting_filter_options_fetch_failed',
      message: err?.message || 'Reporting filter options fetch failed.',
    });
  }
});

