app.put('/api/reporting/regional-snapshot', async (req, res) => {
  if (!hasOperationalReportingAccess(req)) {
    return res.status(403).json({ error: 'forbidden' });
  }
  const regionId = normalisePositiveInteger(req.body?.regionId ?? req.body?.region_id);
  if (!regionId) {
    return res.status(400).json({ error: 'region_required', message: 'Select a region.' });
  }
  const fiscalYearStart = resolveReportingFiscalYearStartValue(
    req.body?.fiscalYearStart ?? req.body?.fiscalYear
  );
  const periodType = normaliseRegionalSnapshotPeriodType(req.body?.periodType ?? req.body?.period_type);
  const periodKey = normaliseRegionalSnapshotPeriodKey(
    periodType,
    req.body?.periodKey ?? req.body?.period_key
  );
  const validation = validateRegionalSnapshotPayload(req.body || {});
  if (!validation.ok) {
    return res.status(422).json({
      error: validation.error,
      message: validation.message,
    });
  }
  const period = buildRegionalSnapshotPeriodDefinition(fiscalYearStart, periodType, periodKey);
  const actorStaffProfileId = resolveActiveStaffProfileId(req) || null;
  let connection;
  try {
    connection = await pool.getConnection();
    await connection.beginTransaction();
    await connection.query(
      `
      INSERT INTO iset_regional_snapshot_report (
        region_id,
        period_type,
        period_start,
        period_end,
        snapshot_status,
        regional_manager_name,
        regional_coordinator_name,
        operating_costs_amount,
        compliance_flag,
        comments_recommendations,
        created_by_staff_profile_id,
        updated_by_staff_profile_id
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON DUPLICATE KEY UPDATE
        snapshot_status = VALUES(snapshot_status),
        regional_manager_name = VALUES(regional_manager_name),
        regional_coordinator_name = VALUES(regional_coordinator_name),
        operating_costs_amount = VALUES(operating_costs_amount),
        compliance_flag = VALUES(compliance_flag),
        comments_recommendations = VALUES(comments_recommendations),
        updated_by_staff_profile_id = VALUES(updated_by_staff_profile_id),
        updated_at = CURRENT_TIMESTAMP
      `,
      [
        regionId,
        period.periodType,
        period.start,
        period.end,
        validation.value.snapshotStatus,
        validation.value.regionalManagerName,
        validation.value.regionalCoordinatorName,
        validation.value.operatingCostsAmount,
        validation.value.complianceFlag,
        validation.value.commentsRecommendations,
        actorStaffProfileId,
        actorStaffProfileId,
      ]
    );
    await connection.commit();
    const payload = await buildRegionalSnapshotPayload({
      regionId,
      fiscalYearStart,
      periodType,
      periodKey,
      executor: pool,
    });
    res.set('Cache-Control', 'no-store, max-age=0');
    return res.json(payload);
  } catch (err) {
    if (connection) {
      try { await connection.rollback(); } catch (_) {}
    }
    console.error('[reporting:regional-snapshot] save failed:', err?.message || err);
    return res.status(500).json({
      error: 'regional_snapshot_save_failed',
      message: err?.message || 'Regional snapshot save failed.',
    });
  } finally {
    if (connection) {
      connection.release();
    }
  }
});

app.get('/api/reporting/data-and-results/live-report', async (req, res) => {
  if (!hasOperationalReportingAccess(req)) {
    return res.status(403).json({ error: 'forbidden' });
  }

  const fiscalYearStartInput = Number.parseInt(
    String(req.query.fiscalYearStart ?? req.query.fiscalYear ?? ''),
    10
  );
  const fiscalYearStart = Number.isInteger(fiscalYearStartInput) && fiscalYearStartInput >= 2020 && fiscalYearStartInput <= 2100
    ? fiscalYearStartInput
    : resolveReportingFiscalYearStartYear();
  const fiscalYearEnd = buildReportingIsoDate(fiscalYearStart + 1, 3, 31);
  const fiscalYearStartDate = buildReportingIsoDate(fiscalYearStart, 4, 1);
  const provinceCodes = normaliseReportingProvinceCodes(req.query.provinces ?? req.query.province ?? []);
  const caseManagerIds = normaliseReportingCaseManagerIds(
    req.query.caseManagers ?? req.query.caseManager ?? req.query.manager ?? []
  );
  const interventionMeasure = normaliseReportingInterventionMeasure(
    req.query.interventionMeasure ?? req.query.interventionsMeasure ?? req.query.interventionShow
  );
  const interventionStatusView = normaliseReportingInterventionStatusView(
    req.query.interventionStatus ?? req.query.interventionsStatus ?? req.query.interventionView
  );
  const requestedInterventionDateBasis = normaliseReportingInterventionDateBasis(
    req.query.interventionDateBasis ?? req.query.interventionDate ?? req.query.interventionDateView
  );
  const interventionDateBasis = interventionMeasure === 'cost'
    ? 'payment'
    : requestedInterventionDateBasis;
  const snapshotPeriods = buildReportingSnapshotPeriods(fiscalYearStart);

  const applicationActivity = {
    newApplications: buildReportingApplicationActivityRows(snapshotPeriods, provinceCodes),
    approvedApplications: buildReportingApplicationActivityRows(snapshotPeriods, provinceCodes),
    deniedApplications: buildReportingApplicationActivityRows(snapshotPeriods, provinceCodes),
  };
  const interventions = buildReportingMatrixRows(REPORTING_INTERVENTION_ROW_LABELS, snapshotPeriods);
  const clientResults = buildReportingMatrixRows(REPORTING_CLIENT_RESULT_ROW_LABELS, snapshotPeriods);
  const dataUploads = buildReportingMatrixRows(REPORTING_DATA_UPLOAD_ROW_LABELS, snapshotPeriods);
  const actionPlanStatuses = buildReportingMatrixRows(REPORTING_ACTION_PLAN_STATUS_ROW_LABELS, snapshotPeriods);

  const applicationActivityByMetric = {
    newApplications: new Map(applicationActivity.newApplications.map(row => [row.provinceCode, row])),
    approvedApplications: new Map(applicationActivity.approvedApplications.map(row => [row.provinceCode, row])),
    deniedApplications: new Map(applicationActivity.deniedApplications.map(row => [row.provinceCode, row])),
  };
  const interventionsByLabel = new Map(interventions.map(row => [row.label, row]));
  const clientResultsByLabel = new Map(clientResults.map(row => [row.label, row]));
  const dataUploadsByLabel = new Map(dataUploads.map(row => [row.label, row]));
  const actionPlanStatusesByLabel = new Map(actionPlanStatuses.map(row => [row.label, row]));

  try {
    const [
      applicationRows,
      interventionRows,
      actionPlanRows,
      participantSubmissionRows,
      submissionHistoryRows,
      reportingTargets,
      paymentTypeMapping,
      recurrencePolicyByType,
    ] = await Promise.all([
      pool.query(
        `
        SELECT
          a.id,
          REPLACE(LOWER(TRIM(a.status)), ' ', '_') AS status_key,
          ias.submitted_at,
          COALESCE(a.updated_at, a.created_at) AS status_observed_at,
c.assigned_staff_profile_id AS assigned_to_user_id,
          ${REPORTING_ADDRESS_PROVINCE_EXPR} AS address_province
        FROM iset_application a
        LEFT JOIN iset_application_submission ias ON ias.id = a.submission_id
        LEFT JOIN iset_case c ON ${APPLICATION_CASE_JOIN_PREDICATE}
        WHERE (
          (ias.submitted_at IS NOT NULL AND DATE(ias.submitted_at) BETWEEN ? AND ?)
          OR (
            REPLACE(LOWER(TRIM(a.status)), ' ', '_') IN ('approved', 'completed', 'rejected', 'declined')
            AND DATE(COALESCE(a.updated_at, a.created_at)) BETWEEN ? AND ?
          )
        )
        `,
        [fiscalYearStartDate, fiscalYearEnd, fiscalYearStartDate, fiscalYearEnd]
      ),
      pool.query(
        `
        SELECT
          ci.id,
          ci.intervention_code,
          ci.status,
          ci.delivery_status,
          ci.metadata_json,
          ci.intervention_cost,
          ci.budget_amount,
          ci.approved_amount,
          ci.actual_amount,
          ci.start_date AS started_on,
          COALESCE(ci.end_date, DATE(ci.closed_at)) AS ended_on,
c.assigned_staff_profile_id AS assigned_to_user_id,
          ${REPORTING_ADDRESS_PROVINCE_EXPR} AS address_province
        FROM iset_case_intervention ci
        JOIN iset_case c ON c.id = ci.case_id
        ${buildCasePrimaryApplicationJoinSql('c', 'a')}
        LEFT JOIN iset_application_submission ias ON ias.id = a.submission_id
        WHERE ci.intervention_code IS NOT NULL
          AND (
            (ci.start_date IS NOT NULL AND ci.start_date <= ?)
            OR (
              COALESCE(ci.end_date, DATE(ci.closed_at)) IS NOT NULL
              AND COALESCE(ci.end_date, DATE(ci.closed_at)) <= ?
            )
          )
        `,
        [fiscalYearEnd, fiscalYearEnd]
      ),
      pool.query(
        `
        SELECT
          ap.id,
          ap.case_id,
          COALESCE(CAST(c.client_id AS CHAR), CONCAT('case-', c.id)) AS client_key,
          ap.status,
          ap.effective_date,
          DATE(ap.activated_at) AS activated_on,
          DATE(ap.closed_at) AS closed_on,
          DATE(ap.archived_at) AS archived_on,
          DATE(ap.created_at) AS created_on,
          ap.result_code,
          ap.result_date,
c.assigned_staff_profile_id AS assigned_to_user_id,
          ${REPORTING_ADDRESS_PROVINCE_EXPR} AS address_province
        FROM iset_case_action_plan ap
        JOIN iset_case c ON c.id = ap.case_id
        ${buildCasePrimaryApplicationJoinSql('c', 'a')}
        LEFT JOIN iset_application_submission ias ON ias.id = a.submission_id
        WHERE COALESCE(ap.effective_date, DATE(ap.activated_at), DATE(ap.created_at)) <= ?
           OR (ap.result_date IS NOT NULL AND ap.result_date <= ?)
        `,
        [fiscalYearEnd, fiscalYearEnd]
      ),
      pool.query(
        `
        SELECT
          eps.id,
          eps.case_id,
          eps.action_plan_id,
          eps.readiness_status,
          COALESCE(eps.last_validated_at, eps.updated_at, eps.created_at) AS observed_at,
          c.assigned_staff_profile_id AS assigned_to_user_id
        FROM esdc_participant_submission eps
        JOIN iset_case c ON c.id = eps.case_id
        WHERE COALESCE(eps.last_validated_at, eps.updated_at, eps.created_at) <= ?
        `,
        [fiscalYearEnd]
      ),
      pool.query(
        `
        SELECT
          h.event_type,
          h.occurred_at,
          eps.case_id,
          eps.action_plan_id,
c.assigned_staff_profile_id AS assigned_to_user_id,
          ${REPORTING_ADDRESS_PROVINCE_EXPR} AS address_province
        FROM esdc_participant_submission_history h
        JOIN esdc_participant_submission eps ON eps.id = h.participant_submission_id
        JOIN iset_case c ON c.id = eps.case_id
        ${buildCasePrimaryApplicationJoinSql('c', 'a')}
        LEFT JOIN iset_application_submission ias ON ias.id = a.submission_id
        WHERE h.event_type IN ('submitted')
          AND DATE(h.occurred_at) BETWEEN ? AND ?
        `,
        [fiscalYearStartDate, fiscalYearEnd]
      ),
      loadReportingDataAndResultsTargets(pool, fiscalYearStart),
      interventionMeasure === 'cost' ? readPaymentInterventionMapping(pool) : Promise.resolve(null),
      interventionMeasure === 'cost' ? readPaymentRecurrencePolicyByType(pool) : Promise.resolve(null),
    ]);

    const applicationRowsRaw = Array.isArray(applicationRows?.[0]) ? applicationRows[0] : [];
    const interventionsRaw = Array.isArray(interventionRows?.[0]) ? interventionRows[0] : [];
    const actionPlansRaw = Array.isArray(actionPlanRows?.[0]) ? actionPlanRows[0] : [];
    const participantSubmissionsRaw = Array.isArray(participantSubmissionRows?.[0]) ? participantSubmissionRows[0] : [];
    const submissionHistoryRaw = Array.isArray(submissionHistoryRows?.[0]) ? submissionHistoryRows[0] : [];

    const filteredApplicationRows = applicationRowsRaw.filter(row => (
      matchesReportingProvinceFilter(row.address_province, provinceCodes) &&
      matchesReportingCaseManagerFilter(row.assigned_to_user_id, caseManagerIds)
    ));

    filteredApplicationRows.forEach(row => {
      const provinceCode = normaliseReportingProvinceCode(row.address_province);
      if (!provinceCode || !applicationActivityByMetric.newApplications.has(provinceCode)) {
        return;
      }

      const submittedAt = toDateOnly(row.submitted_at);
      const statusObservedAt = toDateOnly(row.status_observed_at);
      const statusKey = normaliseString(row.status_key)?.toLowerCase() || '';

      if (submittedAt && submittedAt >= fiscalYearStartDate && submittedAt <= fiscalYearEnd) {
        addReportingCumulativeValue(
          applicationActivityByMetric.newApplications.get(provinceCode).values,
          submittedAt,
          snapshotPeriods,
          1
        );
      }

      if (
        ['approved', 'completed'].includes(statusKey) &&
        statusObservedAt &&
        statusObservedAt >= fiscalYearStartDate &&
        statusObservedAt <= fiscalYearEnd
      ) {
        addReportingCumulativeValue(
          applicationActivityByMetric.approvedApplications.get(provinceCode).values,
          statusObservedAt,
          snapshotPeriods,
          1
        );
      }

      if (
        ['rejected', 'declined'].includes(statusKey) &&
        statusObservedAt &&
        statusObservedAt >= fiscalYearStartDate &&
        statusObservedAt <= fiscalYearEnd
      ) {
        addReportingCumulativeValue(
          applicationActivityByMetric.deniedApplications.get(provinceCode).values,
          statusObservedAt,
          snapshotPeriods,
          1
        );
      }
    });

    const scopedInterventions = interventionsRaw.filter(row => (
      matchesReportingInterventionStatus(row, interventionStatusView) &&
      matchesReportingProvinceFilter(row.address_province, provinceCodes) &&
      matchesReportingCaseManagerFilter(row.assigned_to_user_id, caseManagerIds)
    ));
    const submissionTimingByType = interventionMeasure === 'cost'
      ? buildSubmissionTimingByTypeLookup(paymentTypeMapping)
      : null;
    const filteredInterventions = [];

    if (interventionMeasure === 'cost') {
      scopedInterventions.forEach(row => {
        const label = REPORTING_INTERVENTION_LABEL_BY_CODE[Number(row.intervention_code)];
        if (!label || !interventionsByLabel.has(label)) return;
        const amountEntries = buildReportingInterventionAmountEntries(row, {
          paymentTypeMapping,
          recurrencePolicyByType,
          submissionTimingByType,
          statusView: interventionStatusView,
        }).filter(entry => entry.date >= fiscalYearStartDate && entry.date <= fiscalYearEnd);
        if (!amountEntries.length) return;
        filteredInterventions.push(row);
        amountEntries.forEach(entry => {
          addReportingCumulativeValue(
            interventionsByLabel.get(label).values,
            entry.date,
            snapshotPeriods,
            entry.amount
          );
        });
      });
    } else {
      scopedInterventions
        .filter(row => {
          const bucketDate = resolveReportingInterventionBucketDate(row, interventionDateBasis);
          return Boolean(bucketDate && bucketDate >= fiscalYearStartDate && bucketDate <= fiscalYearEnd);
        })
        .forEach(row => {
          filteredInterventions.push(row);
          const label = REPORTING_INTERVENTION_LABEL_BY_CODE[Number(row.intervention_code)];
          if (!label || !interventionsByLabel.has(label)) return;
          addReportingCumulativeValue(
            interventionsByLabel.get(label).values,
            resolveReportingInterventionBucketDate(row, interventionDateBasis),
            snapshotPeriods,
            1
          );
        });
    }

    const totalInterventionsRow = interventionsByLabel.get('TOTAL');
    if (totalInterventionsRow) {
      REPORTING_PERIOD_KEYS.forEach(periodKey => {
        totalInterventionsRow.values[periodKey] = interventions
          .filter(row => row.label !== 'TOTAL')
          .reduce((total, row) => total + Number(row.values[periodKey] || 0), 0);
      });
    }

    const filteredActionPlans = actionPlansRaw.filter(row => (
      matchesReportingProvinceFilter(row.address_province, provinceCodes) &&
      matchesReportingCaseManagerFilter(row.assigned_to_user_id, caseManagerIds)
    ));

    filteredActionPlans.forEach(row => {
      const resultDate = toDateOnly(row.result_date);
      const resultCode = normaliseString(row.result_code);

      if (resultCode && resultDate && resultDate >= fiscalYearStartDate && resultDate <= fiscalYearEnd) {
        addReportingCumulativeValue(
          clientResultsByLabel.get('Clients Served - Total').values,
          resultDate,
          snapshotPeriods,
          1
        );
      }
      if (resultCode === '2' && resultDate && resultDate >= fiscalYearStartDate && resultDate <= fiscalYearEnd) {
        addReportingCumulativeValue(
          clientResultsByLabel.get('Employed - Total').values,
          resultDate,
          snapshotPeriods,
          1
        );
      }
      if (resultCode === '4' && resultDate && resultDate >= fiscalYearStartDate && resultDate <= fiscalYearEnd) {
        addReportingCumulativeValue(
          clientResultsByLabel.get('Returned to school - Total').values,
          resultDate,
          snapshotPeriods,
          1
        );
      }
      if (resultCode === '1' && resultDate && resultDate >= fiscalYearStartDate && resultDate <= fiscalYearEnd) {
        addReportingCumulativeValue(
          actionPlanStatusesByLabel.get('8. Action Plans with an Unemployed Result').values,
          resultDate,
          snapshotPeriods,
          1
        );
      }
    });

    const submissionsByActionPlanId = new Map();
    const submissionsByCaseId = new Map();
    participantSubmissionsRaw
      .filter(row => matchesReportingCaseManagerFilter(row.assigned_to_user_id, caseManagerIds))
      .forEach(row => {
        if (row.action_plan_id && !submissionsByActionPlanId.has(row.action_plan_id)) {
          submissionsByActionPlanId.set(row.action_plan_id, row);
        }
        if (row.case_id && !submissionsByCaseId.has(row.case_id)) {
          submissionsByCaseId.set(row.case_id, row);
        }
      });

    snapshotPeriods.forEach(period => {
      let pendingResultCount = 0;
      let dataIntegrityCount = 0;

      filteredActionPlans.forEach(row => {
        const statusKey = normaliseString(row.status)?.toLowerCase() || '';
        if (statusKey === 'draft' || statusKey === 'archived') {
          return;
        }

        const planStartDate =
          toDateOnly(row.effective_date) ||
          toDateOnly(row.activated_on) ||
          toDateOnly(row.created_on);
        const archivedOn = toDateOnly(row.archived_on);
        const resultDate = toDateOnly(row.result_date);
        const resultCode = normaliseString(row.result_code);

        if (!planStartDate || planStartDate > period.cutoff) {
          return;
        }
        if (archivedOn && archivedOn <= period.cutoff) {
          return;
        }
        if (!resultCode || !resultDate || resultDate > period.cutoff) {
          pendingResultCount += 1;
        }

        const submissionRow =
          submissionsByActionPlanId.get(row.id) ||
          submissionsByCaseId.get(row.case_id) ||
          null;
        const observedAt = toDateOnly(submissionRow?.observed_at);
        if (
          submissionRow &&
          submissionRow.readiness_status === 'blocked' &&
          observedAt &&
          observedAt <= period.cutoff
        ) {
          dataIntegrityCount += 1;
        }
      });

      actionPlanStatusesByLabel.get('3. Action Plans with a pending result').values[period.key] = pendingResultCount;
      actionPlanStatusesByLabel.get('4. Action Plans with data integrity issues').values[period.key] = dataIntegrityCount;
    });

    const addRepeatResultCounts = (resultCode, rowLabel) => {
      const grouped = new Map();
      filteredActionPlans.forEach(row => {
        const rowResultCode = normaliseString(row.result_code);
        const resultDate = toDateOnly(row.result_date);
        if (rowResultCode !== resultCode || !resultDate || resultDate > fiscalYearEnd) {
          return;
        }
        const clientKey = row.client_key || `plan-${row.id}`;
        if (!grouped.has(clientKey)) {
          grouped.set(clientKey, []);
        }
        grouped.get(clientKey).push({ id: row.id, resultDate });
      });

      grouped.forEach(entries => {
        entries
          .sort((left, right) => {
            if (left.resultDate !== right.resultDate) {
              return left.resultDate.localeCompare(right.resultDate);
            }
            return Number(left.id || 0) - Number(right.id || 0);
          })
          .forEach((entry, index) => {
            if (index === 0) return;
            if (entry.resultDate < fiscalYearStartDate) return;
            addReportingCumulativeValue(
              actionPlanStatusesByLabel.get(rowLabel).values,
              entry.resultDate,
              snapshotPeriods,
              1
            );
          });
      });
    };

    addRepeatResultCounts('2', '5. Action Plans with a repeat Employed Result');
    addRepeatResultCounts('4', '6. Action Plans with a repeat Returned to School Result');

    const filteredSubmissionHistory = submissionHistoryRaw.filter(row => (
      matchesReportingProvinceFilter(row.address_province, provinceCodes) &&
      matchesReportingCaseManagerFilter(row.assigned_to_user_id, caseManagerIds)
    ));

    filteredSubmissionHistory.forEach(row => {
      const occurredAt = toDateOnly(row.occurred_at);
      if (!occurredAt || occurredAt < fiscalYearStartDate || occurredAt > fiscalYearEnd) {
        return;
      }
      if (row.event_type === 'submitted') {
        addReportingCumulativeValue(
          dataUploadsByLabel.get('Submitted').values,
          occurredAt,
          snapshotPeriods,
          1
        );
      }
    });

    const overallResults = REPORTING_SUMMARY_METRICS.map(definition => {
      const resultRow = clientResultsByLabel.get(definition.rowLabel);
      return {
        metric: definition.metric,
        target: reportingTargets?.[definition.targetKey] ?? null,
        result: Number(resultRow?.values?.['Final (p14)'] || 0),
      };
    });

    const applicationActivityRowCounts = {
      newApplications: countReportingRowsWithValues(
        applicationActivity.newApplications,
        snapshotPeriods
      ),
      approvedApplications: countReportingRowsWithValues(
        applicationActivity.approvedApplications,
        snapshotPeriods
      ),
      deniedApplications: countReportingRowsWithValues(
        applicationActivity.deniedApplications,
        snapshotPeriods
      ),
    };
    const hasApplicationActivityData = Object.values(applicationActivityRowCounts).some(
      count => count > 0
    );
    const hasTargetsConfigured = overallResults.some(item => item.target !== null);
    const hasAnyOperationalData =
      hasApplicationActivityData ||
      filteredInterventions.length > 0 ||
      filteredActionPlans.length > 0 ||
      filteredSubmissionHistory.length > 0;

    const sectionStatus = {
      overall: hasAnyOperationalData ? (hasTargetsConfigured ? 'live' : 'partial') : 'no_records',
      applicationActivity: hasApplicationActivityData ? 'live' : 'no_records',
      interventions: filteredInterventions.length ? 'live' : 'no_records',
      clientResults: filteredActionPlans.length ? 'live' : 'no_records',
      dataUploads: filteredSubmissionHistory.length ? 'live' : 'no_records',
      actionPlanStatuses: filteredActionPlans.length ? 'live' : 'no_records',
    };

    res.set('Cache-Control', 'no-store, max-age=0');
    return res.json({
      fiscalYear: formatReportingFiscalYearLabel(fiscalYearStart),
      fiscalYearStart,
      generatedAt: new Date().toISOString(),
      selectedProvinceCodes: provinceCodes,
      selectedCaseManagerIds: caseManagerIds,
      interventionMeasure,
      interventionStatusView,
      interventionDateBasis,
      overallResults,
      applicationActivity,
      interventions,
      clientResults,
      dataUploads,
      actionPlanStatuses,
      meta: {
        hasAnyOperationalData,
        hasTargetsConfigured,
        sectionStatus,
        notes: {
          overall: hasTargetsConfigured
            ? 'Year-end results and annual targets are shown below.'
            : 'Year-end results are shown below. Annual targets have not been entered for this fiscal year yet.',
          applicationActivity: 'New applications use submission date. Approved and denied applications currently use the application record updated date as the decision-month proxy because PATH does not yet store a dedicated decision timestamp.',
          interventions: interventionMeasure === 'cost'
            ? `Intervention costs are shown cumulatively for ${interventionStatusView} interventions by payment month. Completed interventions use actual cost when available; other statuses use planned cost.`
            : `Intervention counts are shown cumulatively for ${interventionStatusView} interventions by ${interventionDateBasis} date.`,
          clientResults: 'Client results are shown cumulatively for the selected fiscal year.',
          dataUploads: 'ILMP data upload submissions are shown cumulatively for the selected fiscal year.',
          actionPlanStatuses: 'Action plan status counts are shown cumulatively for the selected fiscal year.',
        },
        rowCounts: {
          applications: filteredApplicationRows.length,
          filteredInterventions: filteredInterventions.length,
          actionPlans: filteredActionPlans.length,
          submissionEvents: filteredSubmissionHistory.length,
          applicationActivityRowsWithValues: applicationActivityRowCounts,
          interventionRowsWithValues: countReportingRowsWithValues(interventions, snapshotPeriods),
          clientResultRowsWithValues: countReportingRowsWithValues(clientResults, snapshotPeriods),
          dataUploadRowsWithValues: countReportingRowsWithValues(dataUploads, snapshotPeriods),
          actionPlanStatusRowsWithValues: countReportingRowsWithValues(actionPlanStatuses, snapshotPeriods),
        },
      },
    });
  } catch (err) {
    if (err && (err.code === 'ER_NO_SUCH_TABLE' || err.code === 'ER_BAD_FIELD_ERROR')) {
      res.set('Cache-Control', 'no-store, max-age=0');
      return res.json({
        fiscalYear: formatReportingFiscalYearLabel(fiscalYearStart),
        fiscalYearStart,
        generatedAt: new Date().toISOString(),
        selectedProvinceCodes: provinceCodes,
        selectedCaseManagerIds: caseManagerIds,
        interventionMeasure,
        interventionStatusView,
        interventionDateBasis,
        overallResults: REPORTING_SUMMARY_METRICS.map(definition => ({
          metric: definition.metric,
          target: null,
          result: 0,
        })),
        applicationActivity,
        interventions,
        clientResults,
        dataUploads,
        actionPlanStatuses,
        meta: {
          hasAnyOperationalData: false,
          hasTargetsConfigured: false,
          sectionStatus: {
            overall: 'no_records',
            applicationActivity: 'no_records',
            interventions: 'no_records',
            clientResults: 'no_records',
            dataUploads: 'no_records',
            actionPlanStatuses: 'no_records',
          },
          notes: {
            overall: 'Reporting information is not available at the moment.',
            applicationActivity: 'Reporting information is not available at the moment.',
            interventions: 'Reporting information is not available at the moment.',
            clientResults: 'Reporting information is not available at the moment.',
            dataUploads: 'Reporting information is not available at the moment.',
            actionPlanStatuses: 'Reporting information is not available at the moment.',
          },
          rowCounts: {
            applications: 0,
            filteredInterventions: 0,
            actionPlans: 0,
            submissionEvents: 0,
            applicationActivityRowsWithValues: {
              newApplications: 0,
              approvedApplications: 0,
              deniedApplications: 0,
            },
            interventionRowsWithValues: 0,
            clientResultRowsWithValues: 0,
            dataUploadRowsWithValues: 0,
            actionPlanStatusRowsWithValues: 0,
          },
        },
      });
    }
    console.error('[reporting:data-and-results] live report fetch failed:', err?.message || err);
    return res.status(500).json({
      error: 'live_report_fetch_failed',
      message: err?.message || 'Live report fetch failed.',
    });
  }
});

app.get('/api/reporting/data-and-results/drilldown', async (req, res) => {
  if (!hasOperationalReportingAccess(req)) {
    return res.status(403).json({ error: 'forbidden' });
  }

  const sectionId = normaliseString(req.query.sectionId)?.toLowerCase() || '';
  const rowKey = normaliseString(req.query.rowKey) || null;
  const periodKey = normaliseString(req.query.periodKey) || null;
  const resultsView = normaliseReportingResultsView(req.query.resultsView);
  const fiscalYearStart = resolveReportingFiscalYearStartValue(
    req.query.fiscalYearStart ?? req.query.fiscalYear
  );
  const fiscalYearStartDate = buildReportingIsoDate(fiscalYearStart, 4, 1);
  const snapshotPeriods = buildReportingSnapshotPeriods(fiscalYearStart);
  const drilldownRange = resolveReportingDrilldownRange({
    snapshotPeriods,
    fiscalYearStartDate,
    rawPeriodKey: periodKey,
    resultsView,
  });
  const provinceCodes = normaliseReportingProvinceCodes(req.query.provinces ?? req.query.province ?? []);
  const caseManagerIds = normaliseReportingCaseManagerIds(
    req.query.caseManagers ?? req.query.caseManager ?? req.query.manager ?? []
  );

  if (!rowKey) {
    return res.status(400).json({
      error: 'row_required',
      message: 'Select a row to drill into.',
    });
  }

  if (!drilldownRange) {
    return res.status(400).json({
      error: 'period_required',
      message: 'Select a valid reporting period.',
    });
  }

  try {
    let payload = {
      rowKey,
      rowLabel: rowKey,
      metric: null,
      metricLabel: null,
      eventDateLabel: null,
      valueFormat: 'number',
      items: [],
      truncated: false,
    };

    if (sectionId === 'application-activity') {
      const applicationMetric = normaliseReportingApplicationActivityMetric(
        req.query.applicationMetric ?? req.query.metric
      );
      const provinceCode = normaliseReportingProvinceCode(rowKey);
      if (!provinceCode || !REPORTING_APPLICATION_ACTIVITY_ROW_CODE_SET.has(provinceCode)) {
        return res.status(400).json({
          error: 'invalid_row',
          message: 'Select a valid province or territory row.',
        });
      }

      const result = await fetchReportingApplicationActivityDrilldown({
        executor: pool,
        startDate: drilldownRange.startDate,
        endDate: drilldownRange.endDate,
        provinceCodes,
        caseManagerIds,
        metric: applicationMetric,
        provinceCode,
      });

      payload = {
        ...payload,
        rowKey: provinceCode,
        rowLabel: PROVINCE_LABEL_MAP[provinceCode] || provinceCode,
        metric: applicationMetric,
        metricLabel:
          applicationMetric === 'approvedApplications'
            ? 'Approved applications'
            : applicationMetric === 'deniedApplications'
            ? 'Denied applications'
            : 'New applications',
        eventDateLabel: applicationMetric === 'newApplications' ? 'Submitted' : 'Decision',
        items: Array.isArray(result?.items) ? result.items : [],
        truncated: Boolean(result?.truncated),
      };
    } else if (sectionId === 'interventions') {
      const interventionMeasure = normaliseReportingInterventionMeasure(
        req.query.interventionMeasure ?? req.query.metric
      );
      const interventionStatusView = normaliseReportingInterventionStatusView(
        req.query.interventionStatus ?? req.query.interventionView
      );
      const requestedInterventionDateBasis = normaliseReportingInterventionDateBasis(
        req.query.interventionDateBasis ?? req.query.interventionDate
      );
      const interventionDateBasis = interventionMeasure === 'cost'
        ? 'payment'
        : requestedInterventionDateBasis;
      const normalizedRowLabel = rowKey === 'TOTAL'
        ? 'TOTAL'
        : REPORTING_INTERVENTION_ROW_LABELS.find(label => label === rowKey) || null;
      if (!normalizedRowLabel) {
        return res.status(400).json({
          error: 'invalid_row',
          message: 'Select a valid intervention row.',
        });
      }

      const [paymentTypeMapping, recurrencePolicyByType] = interventionMeasure === 'cost'
        ? await Promise.all([
            readPaymentInterventionMapping(pool),
            readPaymentRecurrencePolicyByType(pool),
          ])
        : [null, null];

      const result = await fetchReportingInterventionDrilldown({
        executor: pool,
        startDate: drilldownRange.startDate,
        endDate: drilldownRange.endDate,
        provinceCodes,
        caseManagerIds,
        rowLabel: normalizedRowLabel,
        measure: interventionMeasure,
        statusView: interventionStatusView,
        dateBasis: interventionDateBasis,
        paymentTypeMapping,
        recurrencePolicyByType,
      });

      payload = {
        ...payload,
        rowKey: normalizedRowLabel,
        rowLabel: normalizedRowLabel,
        metric: interventionMeasure,
        metricLabel: interventionMeasure === 'cost' ? 'Cost' : 'Count',
        eventDateLabel:
          interventionMeasure === 'cost'
            ? 'Payment month'
            : interventionDateBasis === 'start'
            ? 'Start date'
            : 'End date',
        valueFormat: interventionMeasure === 'cost' ? 'currency' : 'number',
        items: Array.isArray(result?.items) ? result.items : [],
        truncated: Boolean(result?.truncated),
      };
    } else {
      return res.status(400).json({
        error: 'invalid_section',
        message: 'Unsupported reporting drilldown requested.',
      });
    }

    res.set('Cache-Control', 'no-store, max-age=0');
    return res.json({
      fiscalYearStart,
      fiscalYear: formatReportingFiscalYearLabel(fiscalYearStart),
      generatedAt: new Date().toISOString(),
      sectionId,
      rowKey: payload.rowKey,
      rowLabel: payload.rowLabel,
      periodKey: drilldownRange.period.key,
      periodLabel: drilldownRange.period.key,
      resultsView,
      rangeStart: drilldownRange.startDate,
      rangeEnd: drilldownRange.endDate,
      metric: payload.metric,
      metricLabel: payload.metricLabel,
      eventDateLabel: payload.eventDateLabel,
      valueFormat: payload.valueFormat,
      truncated: payload.truncated,
      items: payload.items,
    });
  } catch (err) {
    console.error('[reporting:data-and-results] drilldown fetch failed:', err?.message || err);
    return res.status(500).json({
      error: 'reporting_drilldown_fetch_failed',
      message: err?.message || 'Reporting drilldown fetch failed.',
    });
  }
});

app.get('/api/reporting/data-and-results/quarterly-uploads', async (req, res) => {
  if (!hasOperationalReportingAccess(req)) {
    return res.status(403).json({ error: 'forbidden' });
  }

  const fiscalYearStartInput = Number.parseInt(
    String(req.query.fiscalYearStart ?? req.query.fiscalYear ?? ''),
    10
  );
  const fiscalYearStart = Number.isInteger(fiscalYearStartInput) && fiscalYearStartInput >= 2020 && fiscalYearStartInput <= 2100
    ? fiscalYearStartInput
    : resolveReportingFiscalYearStartYear();
  const quarterSchedule = buildReportingQuarterSchedule(fiscalYearStart);
  const provinceCodes = normaliseReportingProvinceCodes(req.query.provinces ?? req.query.province ?? []);
  const caseManagerIds = normaliseReportingCaseManagerIds(
    req.query.caseManagers ?? req.query.caseManager ?? req.query.manager ?? []
  );

  const buildPendingItems = () => quarterSchedule.map(quarter => ({
    period: quarter.period,
    reportingPeriod: quarter.reportingPeriod,
    fiscalYear: quarter.fiscalYear,
    periodStart: quarter.periodStart,
    periodEnd: quarter.periodEnd,
    dueDate: quarter.dueDate,
    receivedDate: null,
    statusKey: 'pending',
    statusLabel: 'Pending',
    packageId: null,
    ownerTeam: null,
    rejectionReason: null,
    updatedAt: null,
  }));

  try {
    const [rows] = await pool.query(
      `
      SELECT
        id,
        reporting_period,
        period_start,
        period_end,
        due_date,
        status,
        owner_team,
        submitted_at,
        rejection_reason,
        updated_at
      FROM esdc_reporting_package
      WHERE due_date BETWEEN ? AND ?
      ORDER BY due_date ASC, id DESC
      `,
      [quarterSchedule[0].dueDate, quarterSchedule[quarterSchedule.length - 1].dueDate]
    );

    const packageByDueDate = new Map();
    rows.forEach(row => {
      const dueDateKey = toDateOnly(row.due_date);
      if (!dueDateKey || packageByDueDate.has(dueDateKey)) return;
      packageByDueDate.set(dueDateKey, row);
    });

    const items = quarterSchedule.map(quarter => {
      const packageRow = packageByDueDate.get(quarter.dueDate);
      const mappedStatus = mapReportingPackageStatus(packageRow?.status);
      return {
        period: quarter.period,
        reportingPeriod: packageRow?.reporting_period || quarter.reportingPeriod,
        fiscalYear: quarter.fiscalYear,
        periodStart: quarter.periodStart,
        periodEnd: quarter.periodEnd,
        dueDate: quarter.dueDate,
        receivedDate: packageRow?.submitted_at ? toDateOnly(packageRow.submitted_at) : null,
        statusKey: mappedStatus.statusKey,
        statusLabel: mappedStatus.statusLabel,
        packageId: packageRow?.id ?? null,
        ownerTeam: packageRow?.owner_team ?? null,
        rejectionReason: packageRow?.rejection_reason ?? null,
        updatedAt: packageRow?.updated_at ? toIsoDateTime(packageRow.updated_at) : null,
      };
    });

    const hasLivePackageRows = items.some(item => item.packageId !== null);
    res.set('Cache-Control', 'no-store, max-age=0');
    return res.json({
      fiscalYear: formatReportingFiscalYearLabel(fiscalYearStart),
      fiscalYearStart,
      source: 'esdc_reporting_package',
      sourceStatus: hasLivePackageRows ? 'live' : 'schedule_only',
      generatedAt: new Date().toISOString(),
      selectedProvinceCodes: provinceCodes,
      selectedCaseManagerIds: caseManagerIds,
      filterAffectsSection: false,
      filterNote: 'Quarterly submission dates and statuses apply to the agreement as a whole, so province/territory and case manager filters do not change this section.',
      items,
    });
  } catch (err) {
    if (err && (err.code === 'ER_NO_SUCH_TABLE' || err.code === 'ER_BAD_FIELD_ERROR')) {
      res.set('Cache-Control', 'no-store, max-age=0');
      return res.json({
        fiscalYear: formatReportingFiscalYearLabel(fiscalYearStart),
        fiscalYearStart,
        source: 'esdc_reporting_package',
        sourceStatus: 'schedule_only',
        generatedAt: new Date().toISOString(),
        selectedProvinceCodes: provinceCodes,
        selectedCaseManagerIds: caseManagerIds,
        filterAffectsSection: false,
        filterNote: 'Quarterly submission dates and statuses apply to the agreement as a whole, so province/territory and case manager filters do not change this section.',
        items: buildPendingItems(),
      });
    }
    console.error('[reporting:data-and-results] quarterly uploads fetch failed:', err?.message || err);
    return res.status(500).json({
      error: 'quarterly_uploads_fetch_failed',
      message: err?.message || 'Quarterly uploads fetch failed.',
    });
  }
});


app.get('/api/admin/contact-messages/:id', async (req, res) => {
  const accessScope = buildContactMessageScope(req);
  if (accessScope.forbidden) return res.status(403).json({ error: 'forbidden' });

  const id = Number.parseInt(req.params.id, 10);
  if (!Number.isFinite(id) || id <= 0) return res.status(400).json({ error: 'invalid_id' });

  try {
    const [[message]] = await pool.query(
      `SELECT
         cm.id,
         cm.submitted_at   AS submittedAt,
         cm.full_name      AS fullName,
         cm.email,
         cm.subject,
         cm.message,
         cm.status,
         cm.user_id        AS userId,
         cm.submitted_ip   AS submittedIp,
         cm.updated_at     AS updatedAt
       FROM contact_message cm
       WHERE cm.id = ?
         ${accessScope.clause ? `AND ${accessScope.clause}` : ''}
       LIMIT 1`,
      [id, ...accessScope.params]
    );
    if (!message) return res.status(404).json({ error: 'not_found' });

    const [history] = await pool.query(
      `SELECT
         h.id,
         h.previous_status AS previousStatus,
         h.new_status      AS newStatus,
         h.changed_by_staff_profile_id AS changedByStaffProfileId,
         h.changed_at      AS changedAt,
         sp.display_name   AS changedByName,
         sp.email          AS changedByEmail,
         CASE
           WHEN sp.display_name IS NOT NULL AND TRIM(sp.display_name) <> '' THEN sp.display_name
           WHEN sp.name IS NOT NULL AND TRIM(sp.name) <> '' THEN sp.name
           WHEN sp.email IS NOT NULL AND sp.email <> '' THEN sp.email
           ELSE NULL
         END AS changedByDisplay
       FROM contact_message_status_history h
       LEFT JOIN staff_profiles sp ON sp.id = h.changed_by_staff_profile_id
       WHERE h.contact_message_id = ?
       ORDER BY h.changed_at DESC, h.id DESC`,
      [id]
    );

    const [notes] = await pool.query(
      `SELECT
         n.id,
         n.note_text       AS noteText,
         n.author_user_id  AS authorUserId,
         n.created_at      AS createdAt,
         u.name            AS authorName,
         u.email           AS authorEmail,
         CASE
           WHEN u.name IS NOT NULL AND TRIM(u.name) <> '' THEN u.name
           WHEN u.email IS NOT NULL AND u.email <> '' THEN u.email
           ELSE NULL
         END AS authorDisplay
       FROM contact_message_note n
       LEFT JOIN user u ON u.id = n.author_user_id
       WHERE n.contact_message_id = ?
       ORDER BY n.created_at DESC, n.id DESC`,
      [id]
    );

    res.json({ message, history, notes });
  } catch (err) {
    console.error('[contact-admin] detail failed', err);
    res.status(500).json({ error: 'internal_error' });
  }
});

app.patch('/api/admin/contact-messages/:id/status', async (req, res) => {
  const accessScope = buildContactMessageScope(req);
  if (accessScope.forbidden) return res.status(403).json({ error: 'forbidden' });

  const id = Number.parseInt(req.params.id, 10);
  if (!Number.isFinite(id) || id <= 0) return res.status(400).json({ error: 'invalid_id' });

  const nextStatus = typeof req.body?.status === 'string' ? req.body.status.trim() : '';
  if (!nextStatus) return res.status(400).json({ error: 'invalid_status' });

  const actorStaffProfileId = req.staffProfile?.id || null;

  let connection;
  const pendingReminderCreates = [];
  try {
    connection = await pool.getConnection();
    await connection.beginTransaction();

    const [[current]] = await connection.query(
      `SELECT cm.status
         FROM contact_message cm
        WHERE cm.id = ?
          ${accessScope.clause ? `AND ${accessScope.clause}` : ''}
        LIMIT 1`,
      [id, ...accessScope.params]
    );
    if (!current) {
      await connection.rollback();
      return res.status(404).json({ error: 'not_found' });
    }

    if (current.status !== nextStatus) {
      if (!actorStaffProfileId) {
        await connection.rollback();
        return res.status(400).json({ error: 'staff_profile_required' });
      }
      await connection.query(
        `UPDATE contact_message
           SET status = ?, updated_at = NOW()
         WHERE id = ?`,
        [nextStatus, id]
      );

      await connection.query(
        `INSERT INTO contact_message_status_history
           (contact_message_id, previous_status, new_status, changed_by_staff_profile_id, changed_at)
         VALUES (?, ?, ?, ?, NOW())`,
        [id, current.status, nextStatus, actorStaffProfileId]
      );
    }

    await connection.commit();

    try {
      await dispatchInternalNotifications?.({
        type: 'contact_message.updated',
        payload: {
          messageId: id,
          previousStatus: current.status,
          newStatus: nextStatus,
          changedBy: actorStaffProfileId
        }
      });
    } catch (notifyErr) {
      console.warn('[contact-admin] status notification failed', notifyErr.message);
    }

    res.json({ success: true, status: nextStatus });
  } catch (err) {
    if (connection) {
      try { await connection.rollback(); } catch (_) {}
    }
    console.error('[contact-admin] status update failed', err);
    res.status(500).json({ error: 'internal_error' });
  } finally {
    if (connection) connection.release();
  }
});

app.post('/api/admin/contact-messages/:id/notes', async (req, res) => {
  const accessScope = buildContactMessageScope(req);
  if (accessScope.forbidden) return res.status(403).json({ error: 'forbidden' });

  const id = Number.parseInt(req.params.id, 10);
  if (!Number.isFinite(id) || id <= 0) return res.status(400).json({ error: 'invalid_id' });

  const noteText = typeof req.body?.noteText === 'string' ? req.body.noteText.trim() : '';
  if (!noteText) return res.status(400).json({ error: 'invalid_note' });

  let authorUserId = null;
  try {
    authorUserId = await resolveExistingUserIdFromAuth(req, pool);
    if (authorUserId === null) {
      const candidateEmails = new Set();
      if (typeof req.auth?.email === 'string' && req.auth.email.trim()) {
        candidateEmails.add(req.auth.email.trim());
      }
      if (typeof req.staffProfile?.email === 'string' && req.staffProfile.email.trim()) {
        candidateEmails.add(req.staffProfile.email.trim());
      }
      if (candidateEmails.size) {
        const emailList = Array.from(candidateEmails);
        const placeholders = emailList.map(() => '?').join(', ');
        const [emailRows] = await pool.query(
          `SELECT id FROM user WHERE email IN (${placeholders}) LIMIT 1`,
          emailList
        );
        if (emailRows && emailRows[0] && Number.isFinite(Number(emailRows[0].id))) {
          authorUserId = Number(emailRows[0].id);
        }
      }
    }
  } catch (lookupErr) {
    console.warn('[contact-admin] unable to resolve note author user id', lookupErr.message);
    authorUserId = null;
  }

  try {
    const [[messageRow]] = await pool.query(
      `SELECT cm.id
         FROM contact_message cm
        WHERE cm.id = ?
          ${accessScope.clause ? `AND ${accessScope.clause}` : ''}
        LIMIT 1`,
      [id, ...accessScope.params]
    );
    if (!messageRow) return res.status(404).json({ error: 'not_found' });

    await pool.query(
      `INSERT INTO contact_message_note
         (contact_message_id, author_user_id, note_text, created_at)
       VALUES (?, ?, ?, NOW())`,
      [id, authorUserId, noteText]
    );
    res.status(201).json({ success: true });
  } catch (err) {
    console.error('[contact-admin] add note failed', err);
    res.status(500).json({ error: 'internal_error' });
  }
});

app.get('/api/admin/contact-messages/:id/notes', async (req, res) => {
  const accessScope = buildContactMessageScope(req);
  if (accessScope.forbidden) return res.status(403).json({ error: 'forbidden' });

  const id = Number.parseInt(req.params.id, 10);
  if (!Number.isFinite(id) || id <= 0) return res.status(400).json({ error: 'invalid_id' });

  try {
    const [[messageRow]] = await pool.query(
      `SELECT cm.id
         FROM contact_message cm
        WHERE cm.id = ?
          ${accessScope.clause ? `AND ${accessScope.clause}` : ''}
        LIMIT 1`,
      [id, ...accessScope.params]
    );
    if (!messageRow) return res.status(404).json({ error: 'not_found' });

    const [notes] = await pool.query(
      `SELECT
         n.id,
         n.note_text       AS noteText,
         n.author_user_id  AS authorUserId,
         n.created_at      AS createdAt,
         u.name            AS authorName,
         u.email           AS authorEmail,
         CASE
           WHEN u.name IS NOT NULL AND TRIM(u.name) <> '' THEN u.name
           WHEN u.email IS NOT NULL AND u.email <> '' THEN u.email
           ELSE NULL
         END AS authorDisplay
       FROM contact_message_note n
       LEFT JOIN user u ON u.id = n.author_user_id
       WHERE n.contact_message_id = ?
       ORDER BY n.created_at DESC, n.id DESC`,
      [id]
    );
    res.json({ items: notes });
  } catch (err) {
    console.error('[contact-admin] notes fetch failed', err);
    res.status(500).json({ error: 'internal_error' });
  }
});

async function loadAdminFeedbackReportDetail(reportId) {
  const numericReportId = Number.parseInt(reportId, 10);
  if (!Number.isFinite(numericReportId) || numericReportId <= 0) return null;

  const [[reportRow]] = await pool.query(
    `SELECT
       id,
       report_type AS reportType,
       severity,
       status,
       summary,
       description,
       submitted_by_staff_profile_id AS submittedByStaffProfileId,
       submitted_by_name AS submittedByName,
       submitted_by_email AS submittedByEmail,
       submitted_by_role AS submittedByRole,
       page_title AS pageTitle,
       page_path AS pagePath,
       page_url AS pageUrl,
       context_json AS contextJson,
       submitted_at AS submittedAt,
       updated_at AS updatedAt
     FROM admin_feedback_report
     WHERE id = ?
     LIMIT 1`,
    [numericReportId]
  );
  if (!reportRow) return null;

  const [attachmentRows] = await pool.query(
    `SELECT
       id,
       file_name AS fileName,
       storage_key AS storageKey,
       mime_type AS mimeType,
       size_bytes AS sizeBytes,
       checksum_sha256 AS checksumSha256,
       uploaded_by_staff_profile_id AS uploadedByStaffProfileId,
       uploaded_at AS uploadedAt
     FROM admin_feedback_attachment
     WHERE report_id = ?
     ORDER BY uploaded_at ASC, id ASC`,
    [numericReportId]
  );

  let historyRows = [];
  try {
    const [rows] = await pool.query(
      `SELECT
         id,
         previous_status AS previousStatus,
         new_status AS newStatus,
         changed_by_staff_profile_id AS changedByStaffProfileId,
         changed_by_name AS changedByName,
         changed_by_email AS changedByEmail,
         changed_at AS changedAt
       FROM admin_feedback_status_history
       WHERE report_id = ?
       ORDER BY changed_at DESC, id DESC`,
      [numericReportId]
    );
    historyRows = rows || [];
  } catch (err) {
    if (!isMissingTableErrorLocal(err)) throw err;
  }

  let noteRows = [];
  try {
    const [rows] = await pool.query(
      `SELECT
         id,
         author_staff_profile_id AS authorStaffProfileId,
         author_name AS authorName,
         author_email AS authorEmail,
         note_text AS noteText,
         created_at AS createdAt
       FROM admin_feedback_note
       WHERE report_id = ?
       ORDER BY created_at DESC, id DESC`,
      [numericReportId]
    );
    noteRows = rows || [];
  } catch (err) {
    if (!isMissingTableErrorLocal(err)) throw err;
  }

  const attachments = await Promise.all(
    (attachmentRows || []).map(async row => {
      let downloadUrl = null;
      try {
        downloadUrl = await presignObjectStoreDownloadUrl(row.storageKey);
      } catch (err) {
        console.warn('[admin:feedback] failed to sign attachment %s: %s', row.storageKey, err?.message || err);
      }
      return {
        id: row.id,
        fileName: row.fileName,
        mimeType: row.mimeType || null,
        sizeBytes: row.sizeBytes != null ? Number(row.sizeBytes) : null,
        checksumSha256: row.checksumSha256 || null,
        uploadedByStaffProfileId: row.uploadedByStaffProfileId || null,
        uploadedAt: row.uploadedAt,
        downloadUrl,
      };
    })
  );

  return {
    report: {
      id: reportRow.id,
      reportType: reportRow.reportType,
      severity: reportRow.severity,
      status: reportRow.status,
      summary: reportRow.summary,
      description: reportRow.description,
      submittedByStaffProfileId: reportRow.submittedByStaffProfileId || null,
      submittedByName: reportRow.submittedByName || null,
      submittedByEmail: reportRow.submittedByEmail || null,
      submittedByRole: reportRow.submittedByRole || null,
      pageTitle: reportRow.pageTitle || null,
      pagePath: reportRow.pagePath || null,
      pageUrl: reportRow.pageUrl || null,
      contextSnapshot: safeJsonParse(reportRow.contextJson, null),
      submittedAt: reportRow.submittedAt,
      updatedAt: reportRow.updatedAt,
      attachmentCount: attachments.length,
      attachments,
      history: historyRows,
      notes: noteRows,
    },
  };
}

app.get(['/api/dashboard/system-admin-feedback-reports', '/api/dashboard/admin-feedback-reports'], async (req, res) => {
  if (!canReviewAdminFeedback(req)) {
    return res.status(403).json({ error: 'forbidden' });
  }

  const limitParam = Number(req.query.limit);
  const offsetParam = Number(req.query.offset);
  const limit = Number.isFinite(limitParam) && limitParam > 0 ? Math.min(Math.trunc(limitParam), 50) : 8;
  const offset = Number.isFinite(offsetParam) && offsetParam >= 0 ? Math.trunc(offsetParam) : 0;
  const statusFilter = sanitizeAdminFeedbackDashboardStatusFilter(req.query.status);
  const reportTypeFilter = sanitizeAdminFeedbackDashboardTypeFilter(req.query.reportType ?? req.query.type);
  const search = typeof req.query.search === 'string' ? req.query.search.trim().slice(0, 200) : '';

  const where = [];
  const params = [];
  if (statusFilter === 'open') {
    where.push(`r.status IN (${ADMIN_FEEDBACK_OPEN_STATUSES.map(() => '?').join(', ')})`);
    params.push(...ADMIN_FEEDBACK_OPEN_STATUSES);
  } else if (statusFilter !== 'all') {
    where.push('r.status = ?');
    params.push(statusFilter);
  }
  if (reportTypeFilter !== 'all') {
    where.push('r.report_type = ?');
    params.push(reportTypeFilter);
  }
  if (search) {
    const searchValue = `%${search}%`;
    where.push(`(
      r.summary LIKE ?
      OR r.description LIKE ?
      OR r.submitted_by_name LIKE ?
      OR r.submitted_by_email LIKE ?
      OR r.page_title LIKE ?
      OR r.page_path LIKE ?
    )`);
    params.push(searchValue, searchValue, searchValue, searchValue, searchValue, searchValue);
  }
  const whereSql = where.length ? `WHERE ${where.join(' AND ')}` : '';

  try {
    const [[summaryRow]] = await pool.query(
      `SELECT
         SUM(CASE WHEN status = 'submitted' THEN 1 ELSE 0 END) AS awaitingTriage,
         SUM(CASE WHEN status IN ('triaging', 'planned', 'in_progress') THEN 1 ELSE 0 END) AS inProgress,
         SUM(CASE WHEN status IN ('submitted', 'triaging', 'planned', 'in_progress') AND severity IN ('critical', 'high') THEN 1 ELSE 0 END) AS highPriorityOpen,
         SUM(CASE WHEN status IN ('submitted', 'triaging', 'planned', 'in_progress') AND report_type = 'change_request' THEN 1 ELSE 0 END) AS openChangeRequests
       FROM admin_feedback_report`
    );

    const [[countRow]] = await pool.query(
      `SELECT COUNT(*) AS total
       FROM admin_feedback_report r
       ${whereSql}`,
      params
    );

    const [rows] = await pool.query(
      `SELECT
         r.id,
         r.report_type AS reportType,
         r.severity,
         r.status,
         r.summary,
         r.submitted_by_name AS submittedByName,
         r.submitted_by_email AS submittedByEmail,
         r.page_title AS pageTitle,
         r.page_path AS pagePath,
         r.submitted_at AS submittedAt,
         r.updated_at AS updatedAt,
         COALESCE(att.attachmentCount, 0) AS attachmentCount
       FROM admin_feedback_report r
       LEFT JOIN (
         SELECT report_id, COUNT(*) AS attachmentCount
         FROM admin_feedback_attachment
         GROUP BY report_id
       ) att ON att.report_id = r.id
       ${whereSql}
       ORDER BY
         FIELD(r.status, 'submitted', 'triaging', 'planned', 'in_progress', 'resolved', 'closed'),
         FIELD(r.severity, 'critical', 'high', 'medium', 'low'),
         r.submitted_at DESC,
         r.id DESC
       LIMIT ? OFFSET ?`,
      [...params, limit, offset]
    );

    return res.json({
      metrics: {
        awaitingTriage: Number(summaryRow?.awaitingTriage || 0),
        inProgress: Number(summaryRow?.inProgress || 0),
        highPriorityOpen: Number(summaryRow?.highPriorityOpen || 0),
        openChangeRequests: Number(summaryRow?.openChangeRequests || 0),
      },
      total: Number(countRow?.total || 0),
      limit,
      offset,
      statusFilter,
      reportTypeFilter,
      search,
      items: (rows || []).map(row => ({
        id: row.id,
        reportType: row.reportType,
        severity: row.severity,
        status: row.status,
        summary: row.summary,
        submittedByName: row.submittedByName || null,
        submittedByEmail: row.submittedByEmail || null,
        pageTitle: row.pageTitle || null,
        pagePath: row.pagePath || null,
        submittedAt: row.submittedAt,
        updatedAt: row.updatedAt,
        attachmentCount: Number(row.attachmentCount || 0),
      })),
      generatedAt: new Date().toISOString(),
    });
  } catch (err) {
    if (isMissingTableErrorLocal(err)) {
      return res.status(503).json({
        error: 'feedback_storage_unavailable',
        message: 'Admin feedback storage is not available in this environment.',
      });
    }
    console.error('[dashboard] failed to load admin feedback reports', err);
    return res.status(500).json({
      error: 'admin_feedback_reports_failed',
      message: err?.message || 'Unable to load admin feedback reports.',
    });
  }
});

