function validateChecklistConfigPayload(raw, { allowEmptyStatuses = false } = {}) {
  if (!raw || typeof raw !== 'object') {
    return { ok: false, error: 'invalid_payload', message: 'Checklist payload is missing or invalid.' };
  }
  const id = String(raw.id || '').trim() || 'checklist';
  const label = String(raw.label || '').trim() || 'Checklist';
  const version = typeof raw.version === 'string' ? raw.version.trim() : '';
  const gates = Array.isArray(raw.gates) ? raw.gates.map(normaliseChecklistGate).filter(Boolean) : [];
  if (!gates.length) {
    return { ok: false, error: 'gates_required', message: 'At least one gate is required.' };
  }
  for (const gate of gates) {
    const scope = gate.statusScope || 'application';
    if (!['application', 'case', 'intervention'].includes(scope)) {
      return { ok: false, error: 'invalid_status_scope', message: `Invalid status scope: ${scope}` };
    }
    if (!allowEmptyStatuses && (!Array.isArray(gate.statuses) || gate.statuses.length === 0)) {
      return { ok: false, error: 'gate_statuses_required', message: `Gate "${gate.label}" needs at least one status.` };
    }
    if (!Array.isArray(gate.items)) {
      return { ok: false, error: 'gate_items_required', message: `Gate "${gate.label}" must include items.` };
    }
    for (const item of gate.items) {
      if (!item || typeof item !== 'object') {
        return { ok: false, error: 'invalid_item', message: `Gate "${gate.label}" has an invalid item.` };
      }
      if (!item.id || !item.label) {
        return { ok: false, error: 'item_fields_required', message: `Every item in "${gate.label}" needs an id and label.` };
      }
      if (!Array.isArray(item.documentTypes) || item.documentTypes.length === 0) {
        return { ok: false, error: 'item_doc_types_required', message: `Item "${item.label}" needs at least one document type.` };
      }
    }
  }
  return { ok: true, value: { id, label, version, gates } };
}

async function readChecklistConfigSnapshot(key, fallbackPath) {
  const template = loadChecklistTemplate(fallbackPath);
  const raw = await loadChecklistConfig(key);
  if (raw) {
    return { config: coerceChecklistConfig(raw, template), source: 'db' };
  }
  const fallback = loadChecklistConfigFromFile(fallbackPath);
  return {
    config: coerceChecklistConfig(fallback, template),
    source: fallback ? 'file' : 'missing'
  };
}

async function writeChecklistConfigSnapshot(key, config) {
  await ensureRuntimeConfigTable();
  await pool.query(
    'INSERT INTO iset_runtime_config (scope,k,v) VALUES (?,?,CAST(? AS JSON)) ON DUPLICATE KEY UPDATE v=VALUES(v), updated_at=CURRENT_TIMESTAMP',
    [CHECKLIST_SCOPE, key, JSON.stringify(config)]
  );
  clearChecklistCache(key);
  return config;
}

const normaliseAssessmentCostingDefaults = (payload) => {
  const source = payload && typeof payload === 'object' ? payload : {};
  const paymentTypesRaw = Array.isArray(source.paymentTypes) ? source.paymentTypes : [];
  const paymentTypesByCode = new Map();
  paymentTypesRaw.forEach(entry => {
    const code = normalizePaymentTypeCode(
      entry?.code ?? entry?.type ?? entry?.paymentType ?? entry?.payment_type ?? null
    );
    if (!code) return;
    const mode = normalizeRecurrenceMode(
      entry?.recurrence?.mode ?? entry?.recurrenceMode ?? entry?.recurrence_mode ?? null
    );
    paymentTypesByCode.set(code, {
      code,
      recurrence: { mode },
    });
  });
  const defaults = buildDefaultAssessmentCostingPaymentTypes();
  const paymentTypes = defaults.map(entry =>
    paymentTypesByCode.get(entry.code) || entry
  );
  paymentTypesByCode.forEach((value, key) => {
    if (!paymentTypes.some(entry => entry.code === key)) {
      paymentTypes.push(value);
    }
  });
  return {
    enabled: source.enabled !== false,
    strategy: typeof source.strategy === 'string' && source.strategy.trim() ? source.strategy.trim() : 'allowed',
    paymentTypes,
    interventions: Array.isArray(source.interventions) ? source.interventions : []
  };
};

async function readAssessmentCostingDefaults(connection = null) {
  const runner = connection || pool;
  if (!runner || typeof runner.query !== 'function') {
    return { ...DEFAULT_ASSESSMENT_COSTING_DEFAULTS, source: 'default' };
  }
  try {
    await ensureRuntimeConfigTable();
    const [[row]] = await runner.query(
      'SELECT v, updated_at FROM iset_runtime_config WHERE scope = ? AND k = ? LIMIT 1',
      [ASSESSMENT_COSTING_SCOPE, ASSESSMENT_COSTING_KEY]
    );
    if (!row) {
      return { ...DEFAULT_ASSESSMENT_COSTING_DEFAULTS, source: 'default' };
    }
    let value = row.v;
    if (value && typeof value === 'string') {
      try { value = JSON.parse(value); } catch { value = null; }
    }
    const normalised = normaliseAssessmentCostingDefaults(value);
    return { ...normalised, source: 'stored', updated_at: row.updated_at };
  } catch (err) {
    console.warn('[assessment-costing] read config failed:', err.message);
    return { ...DEFAULT_ASSESSMENT_COSTING_DEFAULTS, source: 'error' };
  }
}

async function writeAssessmentCostingDefaults(payload, connection = null) {
  const normalised = normaliseAssessmentCostingDefaults(payload);
  const runner = connection || pool;
  if (!runner || typeof runner.query !== 'function') {
    return normalised;
  }
  await ensureRuntimeConfigTable();
  await runner.query(
    'INSERT INTO iset_runtime_config (scope,k,v) VALUES (?,?,CAST(? AS JSON)) ON DUPLICATE KEY UPDATE v=VALUES(v), updated_at=CURRENT_TIMESTAMP',
    [ASSESSMENT_COSTING_SCOPE, ASSESSMENT_COSTING_KEY, JSON.stringify(normalised)]
  );
  return normalised;
}

async function readPaymentRecurrencePolicyByType(connection = null) {
  const config = await readAssessmentCostingDefaults(connection);
  return buildRecurrencePolicyByPaymentType(config);
}

