    return res.json({
      enabled: true,
      ...serializePaymentInterventionMapping(mapping),
      payeeTypes,
      updatedAt: updatedAt || null,
      paymentEvidence,
      paymentEvidenceUpdatedAt: paymentEvidenceUpdatedAt || null,
      evidenceTypes,
    });
