    const paymentEvidence = paymentEvidenceSnapshot?.rules || mergePaymentEvidenceRules(DEFAULT_PAYMENT_EVIDENCE_RULES, null);
    const paymentEvidenceUpdatedAt = paymentEvidenceSnapshot?.updatedAt || null;
