let __dummyDraftSampleDirCache = null;

function dummyDraftResolveText(value) {
  if (!value && value !== 0) return '';
  if (typeof value === 'string' || typeof value === 'number') return String(value);
  if (typeof value === 'object') {
    return value.en || value.fr || Object.values(value).find(v => typeof v === 'string') || '';
  }
  return '';
}

function dummyDraftGetByPath(obj, rawPath) {
  if (obj == null || !rawPath || typeof rawPath !== 'string') return undefined;
  const tokens = rawPath.replace(/\[(\d+)\]/g, '.$1').split('.').filter(Boolean);
  let cursor = obj;
  for (const token of tokens) {
    if (cursor == null) return undefined;
    cursor = cursor[token];
  }
  return cursor;
}

function dummyDraftCoerceNumeric(left, right) {
  const a = typeof left === 'string' && left.trim() !== '' ? Number(left) : left;
  const b = typeof right === 'string' && right.trim() !== '' ? Number(right) : right;
  if (Number.isFinite(a) && Number.isFinite(b)) return [a, b];
  return [left, right];
}

function dummyDraftLooselyEqual(left, right) {
  if ((left === null && typeof right === 'undefined') || (typeof left === 'undefined' && right === null)) {
    return true;
  }
  const [a, b] = dummyDraftCoerceNumeric(left, right);
  if (Number.isFinite(a) && Number.isFinite(b)) return a === b;
  return a === b;
}

function evaluateDummyDraftUploadVisibility(component, answers) {
  if (!component || typeof component !== 'object') return true;
  const conds = component.conditions || component.props?.conditions;
  const rules = Array.isArray(conds?.all) ? conds.all : [];
  if (!rules.length) return true;
  for (const rule of rules) {
    if (!rule || typeof rule !== 'object') return true;
    const current = dummyDraftGetByPath(answers, rule.ref);
    switch (rule.op) {
      case 'exists':
        if (current === undefined || current === null || (typeof current === 'string' && current.trim() === '')) return false;
        break;
      case 'notExists':
        if (!(current === undefined || current === null || (typeof current === 'string' && current.trim() === ''))) return false;
        break;
      case 'emptyOrZero':
        if (current === undefined || current === null || current === false) break;
        if (typeof current === 'string') {
          const trimmed = current.trim();
          if (!trimmed) break;
          const numeric = Number(trimmed);
          if (Number.isFinite(numeric) && numeric === 0) break;
          return false;
        }
        if (typeof current === 'number') {
          if (Number.isFinite(current) && current === 0) break;
          return false;
        }
        if (Array.isArray(current)) {
          if (current.length === 0) break;
          return false;
        }
        return false;
      case 'equals':
        if (!dummyDraftLooselyEqual(current, rule.value)) return false;
        break;
      case 'notEquals':
        if (dummyDraftLooselyEqual(current, rule.value)) return false;
        break;
      case '>': {
        const [a, b] = dummyDraftCoerceNumeric(current, rule.value);
        if (!(Number.isFinite(a) && Number.isFinite(b)) || !(a > b)) return false;
        break;
      }
      case '<': {
        const [a, b] = dummyDraftCoerceNumeric(current, rule.value);
        if (!(Number.isFinite(a) && Number.isFinite(b)) || !(a < b)) return false;
        break;
      }
      default:
        break;
    }
  }
  return true;
}

function resolveDummyDraftSampleDir() {
  if (__dummyDraftSampleDirCache !== null) {
    return __dummyDraftSampleDirCache;
  }
  __dummyDraftSampleDirCache = DUMMY_DRAFT_SAMPLE_DIR_CANDIDATES.find(candidate => {
    try {
      return fs.existsSync(candidate);
    } catch (_) {
      return false;
    }
  }) || '';
  return __dummyDraftSampleDirCache;
}

function guessDummyDraftMimeType(fileName) {
  const ext = String(path.extname(fileName || '') || '').toLowerCase();
  switch (ext) {
    case '.png':
      return 'image/png';
    case '.jpg':
    case '.jpeg':
      return 'image/jpeg';
    case '.gif':
      return 'image/gif';
    case '.bmp':
      return 'image/bmp';
    case '.webp':
      return 'image/webp';
    case '.heic':
      return 'image/heic';
    case '.pdf':
      return 'application/pdf';
    case '.doc':
      return 'application/msword';
    case '.docx':
      return 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
    case '.rtf':
      return 'application/rtf';
    case '.txt':
      return 'text/plain';
    default:
      return 'application/octet-stream';
  }
}

function resolveDummyDraftSampleMeta(sampleName, displayName) {
  const sampleDir = resolveDummyDraftSampleDir();
  const fallbackMimeType = guessDummyDraftMimeType(sampleName || displayName);
  const fallbackSize = 1024;
  if (!sampleDir || !sampleName) {
    return { mimeType: fallbackMimeType, sizeBytes: fallbackSize };
  }
  try {
    const samplePath = path.join(sampleDir, sampleName);
    const stats = fs.statSync(samplePath);
    return {
      mimeType: guessDummyDraftMimeType(sampleName || displayName),
      sizeBytes: Number.isFinite(Number(stats.size)) ? Number(stats.size) : fallbackSize
    };
  } catch (_) {
    return { mimeType: fallbackMimeType, sizeBytes: fallbackSize };
  }
}

function sanitizeDummyDraftUploadName(fileName) {
  const lower = String(fileName || 'file')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9._-]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
  return lower || 'file';
}

function buildDummyDraftUploadPath(userId, fileName) {
  const now = new Date();
  return [
    DUMMY_DRAFT_UPLOAD_PREFIX,
    now.getUTCFullYear(),
    String(now.getUTCMonth() + 1).padStart(2, '0'),
    String(now.getUTCDate()).padStart(2, '0'),
    normalisePositiveInteger(userId) || 'anon',
    `${crypto.randomUUID()}-${sanitizeDummyDraftUploadName(fileName)}`
  ].join('/');
}

function selectDummyDraftUploadTemplates(component) {
  const storageKey = String(component?.storageKey || component?.id || '').trim();
  const configured = DUMMY_DRAFT_UPLOAD_SAMPLE_FILES[storageKey] || DUMMY_DRAFT_UPLOAD_SAMPLE_FILES.default;
  return configured.map((entry, index) => ({
    sampleName: entry.sampleName,
    displayName: entry.displayName || entry.sampleName || `${storageKey || 'upload'}-${index + 1}`
  }));
}

function findDummyDraftDocumentUploadStep(schemaSteps) {
  const candidates = (schemaSteps || []).filter(step => (
    Array.isArray(step?.components) && step.components.some(component => String(component?.type || '').toLowerCase() === 'file-upload')
  ));
  if (!candidates.length) return null;
  return candidates.find(step => {
    const stepId = String(step?.stepId || step?.id || '').toLowerCase();
    const title = dummyDraftResolveText(step?.title).toLowerCase();
    return stepId.includes('document-upload') || title.includes('document upload');
  }) || candidates[candidates.length - 1];
}

async function clearDummyDraftUploadMetadata(userId) {
  const normalizedUserId = normalisePositiveInteger(userId);
  if (!normalizedUserId) return;
  const prefixLike = `${DUMMY_DRAFT_UPLOAD_PREFIX}/%`;
  await pool.query(
    'DELETE FROM iset_application_file WHERE user_id = ? AND file_path LIKE ?',
    [normalizedUserId, prefixLike]
  );
  await pool.query(
    `DELETE FROM iset_document
      WHERE applicant_user_id = ?
        AND application_id IS NULL
        AND source = 'application_submission'
        AND file_path LIKE ?`,
    [normalizedUserId, prefixLike]
  );
}

async function seedDummyDraftUploadMetadata({ schemaSteps, payloadData, userId }) {
  const normalizedUserId = normalisePositiveInteger(userId);
  if (!normalizedUserId) {
    return { payloadPatch: {}, warnings: ['dummy_upload_seed_skipped:user_missing'], seededCount: 0 };
  }
  const documentStep = findDummyDraftDocumentUploadStep(schemaSteps);
  if (!documentStep) {
    return { payloadPatch: {}, warnings: ['dummy_upload_seed_skipped:document_step_missing'], seededCount: 0 };
  }
  const components = Array.isArray(documentStep.components) ? documentStep.components : [];
  const uploadComponents = components.filter(component => String(component?.type || '').toLowerCase() === 'file-upload');
  if (!uploadComponents.length) {
    return { payloadPatch: {}, warnings: ['dummy_upload_seed_skipped:no_file_components'], seededCount: 0 };
  }

  const warnings = [];
  try {
    await clearDummyDraftUploadMetadata(normalizedUserId);
  } catch (err) {
    warnings.push('dummy_upload_seed_cleanup_failed');
    console.warn('[dummy-draft-uploads] cleanup failed for user %s: %s', normalizedUserId, err?.message || err);
  }

  const payloadPatch = {};
  let seededCount = 0;
  for (const component of uploadComponents) {
    const storageKey = String(component?.storageKey || component?.id || '').trim();
    if (!storageKey) continue;
    if (!evaluateDummyDraftUploadVisibility(component, payloadData)) continue;

    const templates = selectDummyDraftUploadTemplates(component);
    const label = dummyDraftResolveText(component?.documentLabel || component?.label) || storageKey;
    const documentType = String(component?.documentType || component?.document_type || '').trim();
    const nextEntries = [];
    let componentInsertFailed = false;

    for (const template of templates) {
      const displayName = template.displayName || template.sampleName || `${storageKey}.bin`;
      const { mimeType, sizeBytes } = resolveDummyDraftSampleMeta(template.sampleName, displayName);
      const filePath = buildDummyDraftUploadPath(normalizedUserId, displayName);
      nextEntries.push({
        name: displayName,
        size: sizeBytes,
        type: mimeType,
        fileId: null,
        filePath
      });
      try {
        await pool.query(
          `INSERT INTO iset_application_file
             (user_id, file_path, original_filename, document_type, status, virus_scan_status, detected_mime, scan_notes)
           VALUES (?, ?, ?, ?, 'clean', 'skipped', ?, ?)`,
          [
            normalizedUserId,
            filePath,
            displayName,
            documentType,
            mimeType,
            'admin_ai_dummy_draft_placeholder'
          ]
        );
      } catch (err) {
        componentInsertFailed = true;
        console.warn('[dummy-draft-uploads] metadata insert failed for %s (%s): %s', storageKey, normalizedUserId, err?.message || err);
      }
      seededCount += 1;
    }

    payloadPatch[storageKey] = component.multiple ? nextEntries : (nextEntries[0] || null);
    if (componentInsertFailed) {
      warnings.push(`dummy_upload_seed_metadata_failed:${storageKey}`);
    }
  }

  return { payloadPatch, warnings, seededCount };
}

// --- AI-generated dummy draft helpers --------------------------------------
const AI_DUMMY_DEFAULT_MODEL = (global.__AI_MODEL_OVERRIDE || process.env.OPENROUTER_MODEL || '').trim() || DEFAULT_OPENROUTER_MODEL;
const AI_DUMMY_MAX_TOKENS = Math.max(400, Math.min(1600, parseInt(process.env.AI_DUMMY_MAX_TOKENS || '900', 10) || 900));
const AI_DUMMY_TEMP = Math.min(1, Math.max(0.1, parseFloat(process.env.AI_DUMMY_TEMPERATURE || '0.55')));
const AI_DUMMY_TOP_P = Math.min(1, Math.max(0.1, parseFloat(process.env.AI_DUMMY_TOP_P || '0.9')));
const AI_DUMMY_CACHE_TTL_MS = 60 * 1000;
let __publishedWorkflowSchemaCache = { fetchedAt: 0, payload: null };
let __runtimeAiModelCache = { fetchedAt: 0, model: null };

function extractModelIdFromRuntimeValue(input) {
  if (!input && input !== 0) return null;
  if (typeof input === 'string') {
    const trimmed = input.trim();
    if (!trimmed) return null;
    if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
      try {
        return extractModelIdFromRuntimeValue(JSON.parse(trimmed));
      } catch (_) {
        return trimmed;
      }
    }
    return trimmed;
  }
  if (typeof input === 'object') {
    const candidate = input.model || input.defaultModel || input.id || null;
    if (typeof candidate === 'string' && candidate.trim()) return candidate.trim();
  }
  return null;
}

async function resolveRuntimeAiModel({ force = false } = {}) {
  const now = Date.now();
  if (!force && __runtimeAiModelCache.model && (now - __runtimeAiModelCache.fetchedAt) < AI_DUMMY_CACHE_TTL_MS) {
    return __runtimeAiModelCache.model;
  }
  let dbModel = null;
  try {
    const [[row]] = await pool.query("SELECT v FROM iset_runtime_config WHERE scope='public' AND k='ai.model' LIMIT 1");
    dbModel = extractModelIdFromRuntimeValue(row?.v);
  } catch (_) {
    dbModel = null;
  }
  const resolved = dbModel || (global.__AI_MODEL_OVERRIDE || process.env.OPENROUTER_MODEL || '').trim() || AI_DUMMY_DEFAULT_MODEL;
  __runtimeAiModelCache = { fetchedAt: now, model: resolved };
  return resolved;
}

async function fetchPublishedWorkflowSchema(force = false) {
  const now = Date.now();
  if (!force && __publishedWorkflowSchemaCache.payload && (now - __publishedWorkflowSchemaCache.fetchedAt) < AI_DUMMY_CACHE_TTL_MS) {
    return __publishedWorkflowSchemaCache.payload;
  }
  const [[row]] = await pool.query(
    "SELECT v FROM iset_runtime_config WHERE scope='publish' AND k='workflow.schema.intake' LIMIT 1"
  );
  if (!row || !row.v) {
    throw new Error('runtime_schema_missing');
  }
  let payload = row.v;
  if (typeof payload === 'string') {
    payload = JSON.parse(payload);
  }
  __publishedWorkflowSchemaCache = { fetchedAt: now, payload };
  return payload;
}

function summarizeSchemaForAi(schemaSteps) {
  const seen = new Set();
  const summary = [];
  (schemaSteps || []).forEach(step => {
    const stepId = step?.id || step?.name || step?.key || 'step';
    (step?.components || []).forEach(comp => {
      const key = comp?.storageKey || comp?.props?.name;
      if (!key || seen.has(key)) return;
      seen.add(key);
      const type = comp?.type || comp?.template_key || 'text';
      let options = [];
      if (Array.isArray(comp?.options)) {
        options = comp.options
          .map(o => o?.value || o)
          .filter(Boolean)
          .slice(0, 6);
      }
      summary.push({ key, type, step: stepId, options });
    });
  });
  return summary.slice(0, 140); // keep prompt compact
}

function getComponentStorageType(component) {
  const rawType = String(component?.type || component?.template_key || '').trim().toLowerCase();
  if (!rawType) return 'scalar';
  if (rawType === 'signature-ack') return 'signature';
  if (rawType === 'checkbox' || rawType === 'checkboxes') return 'multi';
  if (rawType === 'file-upload') return 'files';
  if (rawType === 'summary-list' || rawType === 'paragraph' || rawType === 'text-block') return 'non_input';
  return 'scalar';
}

function buildSchemaFieldSpecs(schemaSteps) {
  const specs = new Map();
  (schemaSteps || []).forEach(step => {
    const components = Array.isArray(step?.components) ? step.components : [];
    components.forEach(comp => {
      const key = comp?.storageKey || comp?.props?.name;
      if (!key || specs.has(key)) return;
      const storageType = getComponentStorageType(comp);
      if (storageType === 'non_input') return;
      specs.set(key, { key, storageType });
    });
  });
  return specs;
}

function extractPrimitiveFromObject(input) {
  if (!input || typeof input !== 'object' || Array.isArray(input)) return null;
  const priorityKeys = ['value', 'label', 'text', 'name', 'title', 'registration_number', 'first_nations_band', 'id'];
  for (const k of priorityKeys) {
    const v = input[k];
    if (v === null || typeof v === 'undefined') continue;
    if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') return v;
  }
  for (const v of Object.values(input)) {
    if (v === null || typeof v === 'undefined') continue;
    if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') return v;
  }
  try {
    return JSON.stringify(input);
  } catch (_) {
    return null;
  }
}

function coerceScalarValue(value) {
  if (value === null || typeof value === 'undefined') return null;
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return value;
  if (Array.isArray(value)) {
    const first = value.find(v => v !== null && typeof v !== 'undefined');
    return coerceScalarValue(first);
  }
  if (typeof value === 'object') {
    const extracted = extractPrimitiveFromObject(value);
    return extracted === null || typeof extracted === 'undefined' ? null : extracted;
  }
  return String(value);
}

function normalizePayloadToPublishedSchema(payloadData, fieldSpecs, { signatureName } = {}) {
  const normalized = {};
  const droppedKeys = [];
  const coercedKeys = [];
  if (!payloadData || typeof payloadData !== 'object') {
    return { normalized, droppedKeys, coercedKeys };
  }
  const fallbackSigName = String(signatureName || '').trim();
  Object.entries(payloadData).forEach(([key, value]) => {
    const spec = fieldSpecs.get(key);
    if (!spec) {
      droppedKeys.push(key);
      return;
    }
    let nextValue = value;
    if (spec.storageType === 'signature') {
      nextValue = coerceSignatureField(value, fallbackSigName || (value && value.name) || '');
    } else if (spec.storageType === 'multi') {
      if (Array.isArray(value)) {
        nextValue = value
          .map(v => coerceScalarValue(v))
          .filter(v => v !== null && typeof v !== 'undefined' && String(v).trim() !== '');
      } else {
        const scalar = coerceScalarValue(value);
        nextValue = (scalar === null || typeof scalar === 'undefined' || String(scalar).trim() === '') ? [] : [scalar];
      }
    } else if (spec.storageType === 'files') {
      nextValue = Array.isArray(value) ? value : [];
    } else {
      nextValue = coerceScalarValue(value);
    }
    if (nextValue !== value) coercedKeys.push(key);
    normalized[key] = nextValue;
  });
  return { normalized, droppedKeys, coercedKeys };
}

function coerceSignatureField(value, name) {
  const finalName = name || (value && value.name) || '';
  return { name: finalName, signed: true };
}

function parseFirstLastFromUserName(rawName) {
  const cleaned = String(rawName || '').trim().replace(/\s+/g, ' ');
  if (!cleaned) return null;

  // Handle "Last, First ..." format.
  if (cleaned.includes(',')) {
    const [lastPart, firstPart] = cleaned.split(',', 2);
    const lastName = String(lastPart || '').trim();
    const firstName = String(firstPart || '').trim().split(' ').filter(Boolean)[0] || '';
    const fullName = [firstName, lastName].filter(Boolean).join(' ').trim() || cleaned;
    return { firstName, lastName, fullName };
  }

  const parts = cleaned.split(' ').filter(Boolean);
  if (parts.length === 1) {
    return { firstName: parts[0], lastName: '', fullName: parts[0] };
  }
  const firstName = parts[0];
  const lastName = parts[parts.length - 1];
  return { firstName, lastName, fullName: `${firstName} ${lastName}`.trim() };
}

async function fetchUserIdentityById(userId, connection = pool) {
  const normalized = Number(userId);
  if (!Number.isFinite(normalized) || normalized <= 0) return null;
  if (!connection || typeof connection.query !== 'function') return null;
  try {
    const [[row]] = await connection.query('SELECT name, email FROM user WHERE id = ? LIMIT 1', [normalized]);
    if (!row) return null;
    return {
      name: row?.name ? String(row.name) : null,
      email: row?.email ? String(row.email) : null,
    };
  } catch (_) {
    return null;
  }
}

function extractJsonObject(text) {
  if (!text) return null;
  try { return JSON.parse(text); } catch (_) {}
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    try { return JSON.parse(match[0]); } catch (_) {}
  }
  return null;
}

async function generateAiDummyDraft({ provinceCode, stepCursor = 'summary-page', workflowId = 'iset-v1', userId = 48, additionalRequestDetails = '', onProgress = null }) {
  if (!AI_KEY) {
    const err = new Error('ai_disabled');
    err.status = 501;
    throw err;
  }
  const aiModel = await resolveRuntimeAiModel();
  const callDiagnostics = [];
  const callAi = async ({ messages, label, maxTokens = 480 }) => {
    const payload = {
      model: aiModel,
      messages,
      temperature: AI_DUMMY_TEMP,
      top_p: AI_DUMMY_TOP_P,
      max_tokens: maxTokens
    };
    const headers = {
      Authorization: `Bearer ${AI_KEY}`,
      'Content-Type': 'application/json',
      'HTTP-Referer': process.env.ALLOWED_ORIGIN || 'http://localhost:3001',
      'X-Title': 'Admin Dummy Draft Generator'
    };
    try {
      const resp = await axios.post('https://openrouter.ai/api/v1/chat/completions', payload, { headers, timeout: 20000 });
      const content = resp.data?.choices?.[0]?.message?.content || '';
      callDiagnostics.push({
        attempt: label,
        status: resp.status,
        model: aiModel,
        contentPreview: String(content || '').slice(0, 200)
      });
      return { content, providerData: resp.data };
    } catch (err) {
      callDiagnostics.push({
        attempt: `${label}-error`,
        status: err?.response?.status || 500,
        message: err?.message || 'request_failed',
        providerData: err?.response?.data || null
      });
      const e = new Error(err?.response?.data?.error || err?.message || 'ai_request_failed');
      e.status = err?.response?.status || 500;
      e.details = err?.response?.data || null;
      throw e;
    }
  };

function buildStepChunks(schemaSteps, stepOrder = DUMMY_STEP_ORDER_FALLBACK) {
  const chunks = [];
  const sourceOrder = Array.isArray(stepOrder) && stepOrder.length ? stepOrder : DUMMY_STEP_ORDER_FALLBACK;
  const orderMap = new Map(sourceOrder.map((id, idx) => [id, idx]));
  const grouped = new Map();
  (schemaSteps || []).forEach(step => {
    const stepId = step?.stepId || step?.step_id || step?.id || step?.name || step?.key || 'step';
    const comps = Array.isArray(step?.components) ? step.components : [];
    comps.forEach(comp => {
      const key = comp?.storageKey || comp?.props?.name || comp?.id;
      if (!key) return;
      if (!grouped.has(stepId)) grouped.set(stepId, []);
      grouped.get(stepId).push(key);
    });
  });
  Array.from(grouped.entries())
    .sort((a, b) => {
      const ia = orderMap.has(a[0]) ? orderMap.get(a[0]) : 999;
      const ib = orderMap.has(b[0]) ? orderMap.get(b[0]) : 999;
      return ia - ib;
    })
    .forEach(([stepId, keys]) => {
      const uniqueKeys = Array.from(new Set(keys)).filter(Boolean);
      if (!uniqueKeys.length) return;
      chunks.push({
        name: stepId,
        keys: uniqueKeys,
        maxTokens: Math.min(480, 180 + keys.length * 18),
        concise: true
      });
    });
  return chunks;
}

  const schemaPayload = await fetchPublishedWorkflowSchema();
  const schemaSteps = schemaPayload?.schema || schemaPayload?.schemaEnvelope?.steps || [];
  const schemaFieldSpecs = buildSchemaFieldSpecs(schemaSteps);
  const stepOrder = resolveStepOrder(schemaSteps);
  const canonicalStepCursor = normalizeStepCursor(stepCursor, stepOrder);
  const fieldSummary = summarizeSchemaForAi(schemaSteps);
  const stepChunks = buildStepChunks(schemaSteps, stepOrder);
  const regionSet = await fetchValidRegionCodeSet().catch(() => new Set());
  const province = (() => {
    const normalized = (provinceCode || '').trim().toUpperCase();
    if (normalized && regionSet.has(normalized)) return normalized;
    if (regionSet.size) return Array.from(regionSet)[0];
    return 'ON';
  })();
  const userRequestDetails = String(additionalRequestDetails || '').trim().slice(0, 4000);
  const payloadData = {};
  const errors = [];
  const warnings = [];
  const chunkLogs = [];
  let identityFullName = null;

  if (typeof onProgress === 'function') {
    onProgress({ type: 'plan', steps: stepChunks.map(c => c.name) });
  }

  for (const chunk of stepChunks) {
    const keyList = chunk.keys;
    const exampleSnippet = chunk.example ? `Example values (do not repeat verbatim): ${JSON.stringify(chunk.example)}` : '';
    const conditionalRules = [];
    if (keyList.includes('social-assistance') || keyList.includes('income-social-assist')) {
      conditionalRules.push('- If social-assistance is yes, set income-social-assist to a realistic monthly amount (200-1800).');
    }
    if (keyList.includes('expenses_transport') || keyList.includes('expenses_bus_pass')) {
      conditionalRules.push('- If expenses_transport includes bus/buss_pass, set expenses_bus_pass to a realistic monthly amount (40-200).');
    }
    if (keyList.includes('loan-grant') || keyList.includes('loan-grant-details')) {
      conditionalRules.push('- If loan-grant is yes, provide loan-grant-details with name and monthly amount (concise).');
    }
    if (keyList.some(k => String(k).startsWith('paragraph'))) {
      conditionalRules.push('- Do not leave paragraph fields blank; for each paragraph* key, write a short sentence (8-20 words), plain and neutral.');
    }
    if (keyList.some(k => String(k).startsWith('income-'))) {
      conditionalRules.push('- Incomes are monthly amounts in CAD; keep them reasonable (0-6000 depending on type).');
    }
    if (keyList.some(k => String(k).startsWith('expenses'))) {
      conditionalRules.push('- Expenses are monthly amounts in CAD; keep them reasonable (rent 400-2000, groceries 150-1200, transport 0-500).');
    }
    if (keyList.includes('first-name') || keyList.includes('last-name')) {
      conditionalRules.push('- Use varied first/last initials; avoid reusing the same starting letters (do not default to A/B).');
    }
    const conditionalSnippet = conditionalRules.length ? `\nConditional rules:\n${conditionalRules.join('\n')}\n` : '';
    const systemPrompt = `
You are generating realistic, respectful dummy intake data for the ISET program.
Return ONLY JSON for the requested keys as: { "payload": { <keys...> } } with no prose, no comments.
- Applicant is an Indigenous woman in Canada.
- Use province ${province} for address-province.
- Use fake-but-plausible values; avoid placeholders and long paragraphs.
- Use option values where applicable; arrays for multi-selects.
- Signatures must be objects { "name": "<full name>", "signed": true } when asked.
- Keep sentences concise (max ~120 characters). Avoid newlines unless list explicitly allows.
- For Canadian addresses: postal code format A1A 1A1 (uppercase), phone format (###) ###-####.
- Long-term goal or descriptions: keep under 90 characters, plain sentences.
${userRequestDetails ? `- Additional requester constraints must be followed when relevant fields are included: ${userRequestDetails}` : ''}
${exampleSnippet}
${conditionalSnippet}
Vary applicant names across drafts; avoid repeating similar first/last initials.
`.trim();
    const userPayload = {
      instruction: 'Fill only the listed keys with plausible values.',
      province,
      keys: keyList,
      schemaHints: fieldSummary.filter(f => keyList.includes(f.key)),
      alreadyFilled: Object.keys(payloadData),
      concise: !!chunk.concise,
      fullName: payloadData['first-name'] ? `${payloadData['first-name']} ${payloadData['last-name']}`.trim() : null,
      additionalRequestDetails: userRequestDetails || null
    };
    const messages = [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: JSON.stringify(userPayload) }
    ];
    let aiContent = '';
    let parsed = null;
    try {
      const { content } = await callAi({ messages, label: `chunk-${chunk.name}`, maxTokens: chunk.maxTokens || 360 });
      aiContent = content;
      parsed = extractJsonObject(aiContent);
      if (!parsed || typeof parsed !== 'object' || typeof parsed.payload !== 'object') {
        // Fallback retry with stricter minimal prompt for any invalid parse
        const retryMessages = [
          { role: 'system', content: `Return ONLY JSON as {"payload":{...keys...}}. No prose. Keep values short and valid. Keys: ${keyList.join(', ')}. Use postal code A1A 1A1, phone (###) ###-#### where applicable. Numbers must be plain numbers.` },
          { role: 'user', content: JSON.stringify(userPayload) }
        ];
        const retry = await callAi({ messages: retryMessages, label: `chunk-${chunk.name}-retry`, maxTokens: Math.min((chunk.maxTokens || 340), 340) });
        aiContent = retry.content;
        parsed = extractJsonObject(aiContent);
      }
    } catch (err) {
      errors.push(`chunk_${chunk.name}_request_failed`);
      chunkLogs.push({ chunk: chunk.name, raw: err.details || err.message, ok: false });
      continue;
    }
    if (!parsed || typeof parsed !== 'object' || typeof parsed.payload !== 'object') {
      errors.push(`chunk_${chunk.name}_invalid_json`);
      chunkLogs.push({ chunk: chunk.name, raw: aiContent, ok: false });
      continue;
    }
    const chunkPayload = parsed.payload;
    const missing = [];
    keyList.forEach(k => {
      if (!(k in chunkPayload)) missing.push(k);
    });
    if (missing.length) {
      warnings.push(`chunk_${chunk.name}_missing:${missing.join(',')}`);
    }
    Object.entries(chunkPayload).forEach(([k, v]) => {
      payloadData[k] = v;
    });
    const logEntry = { chunk: chunk.name, ok: true, missing, preview: JSON.stringify(chunkPayload).slice(0, 200) };
    chunkLogs.push(logEntry);
    if (typeof onProgress === 'function') onProgress({ type: 'chunk', ...logEntry });
    if (chunk.name === 'identity') {
      const fn = chunkPayload['first-name'] || payloadData['first-name'] || 'Sky';
      const ln = chunkPayload['last-name'] || payloadData['last-name'] || 'Test';
      payloadData['first-name'] = fn;
      payloadData['last-name'] = ln;
      if (!payloadData['preferred-name']) payloadData['preferred-name'] = fn;
      identityFullName = `${fn || ''} ${ln || ''}`.trim() || null;
    }
  }

  // Override identity fields with the DB display name for the selected applicant (if present).
  const userIdentity = await fetchUserIdentityById(userId);
  const nameParts = parseFirstLastFromUserName(userIdentity?.name);
  if (nameParts) {
    if (nameParts.firstName) payloadData['first-name'] = nameParts.firstName;
    if (nameParts.lastName) payloadData['last-name'] = nameParts.lastName;
    if (nameParts.firstName) payloadData['preferred-name'] = nameParts.firstName;
    identityFullName = nameParts.fullName || identityFullName;
  }
  if (userIdentity?.email) {
    payloadData['contact-email-address'] = userIdentity.email;
  }

  const firstName = (payloadData && payloadData['first-name']) || 'Sky';
  const lastName = (payloadData && payloadData['last-name']) || 'Test';
  const fullName = `${firstName} ${lastName}`.trim() || 'Test Applicant';
  if (!payloadData['address-province']) payloadData['address-province'] = province;
  payloadData['first-name'] = String(firstName).trim() || 'Sky';
  payloadData['last-name'] = String(lastName).trim() || 'Test';
  payloadData['preferred-name'] = String(payloadData['preferred-name'] || firstName).trim();
  payloadData['address-province'] = province.toLowerCase();
  if (!payloadData['address-city']) payloadData['address-city'] = 'Winnipeg';
  if (!payloadData['address-street-address']) payloadData['address-street-address'] = '123 River Rd';
  if (!payloadData['address-postcode']) payloadData['address-postcode'] = 'K1A 0B1';
  // Normalize province code casing to lowercase
  if (payloadData['address-province']) {
    payloadData['address-province'] = String(payloadData['address-province']).trim().toLowerCase();
  }
  if (!payloadData['contact-email-address']) {
    payloadData['contact-email-address'] = `${payloadData['first-name'].toLowerCase()}.${payloadData['last-name'].toLowerCase()}@example.com`;
  }
  if (!payloadData['telephone-day']) payloadData['telephone-day'] = '(204) 555-0101';
  if (!payloadData['dob']) payloadData['dob'] = '1988-05-14';
  if (!payloadData['target-program']) payloadData['target-program'] = null;
  // Numeric coercion for known fields
  const NUMERIC_FIELDS = [
    'income-employment','income-spousal','income-social-assist','income-child-support','income-child-benefit','income-other-description',
    'expenses-rent','expenses-groceries','expenses-utilities','expenses-electricity','expenses-heating','expenses-water','expenses-sewerage','expenses-garbage',
    'expenses_transport','expenses_bus_pass','expenses-other-total'
  ];
  NUMERIC_FIELDS.forEach(key => {
    if (key in payloadData) {
      const raw = payloadData[key];
      const num = Number(raw);
      if (Number.isFinite(num)) {
        payloadData[key] = num;
      }
    }
  });
  // No automatic program/support defaults; rely on LLM output
  // Student loan/grant conditional details
  if (payloadData['loan-grant'] === 'yes' || payloadData['loan-grant'] === true) {
    if (!payloadData['loan-grant-details']) {
      payloadData['loan-grant-details'] = 'Provincial student loan (QC) – $250/month.';
    }
  }
  if (!payloadData['labour-force-status']) {
    payloadData['labour-force-status'] = 'unemployed';
    warnings.push('labour_fallback_applied');
  }
  if (!payloadData['highest-education']) {
    payloadData['highest-education'] = 'secondary_school_diploma_or_ged';
  }
  if (!payloadData['education-year']) {
    payloadData['education-year'] = 2015;
  }
  if (!payloadData['education-location']) {
    payloadData['education-location'] = province.toLowerCase();
  }
  const incomeFields = ['income-employment','income-spousal','income-social-assist','income-child-support','income-child-benefit','income-other','income-other-description'];
  incomeFields.forEach(f => {
    if (!(f in payloadData)) payloadData[f] = 0;
  });
  if (!payloadData['ei_status']) {
    payloadData['ei_status'] = 'planning';
  }
  // Normalize income numbers to realistic monthly ranges
  const clamp = (val, min, max) => Math.min(max, Math.max(min, val));
  const monthlyRanges = {
    'income-employment': [0, 6000],
    'income-spousal': [0, 6000],
    'income-social-assist': [0, 2500],
    'income-child-support': [0, 2000],
    'income-child-benefit': [0, 2000],
    'income-other-description': [0, 4000]
  };
  Object.entries(monthlyRanges).forEach(([key, [mn, mx]]) => {
    if (key in payloadData) {
      const num = Number(payloadData[key]);
      if (Number.isFinite(num)) {
        payloadData[key] = clamp(num, mn, mx);
      }
    }
  });
  // Normalize expenses to reasonable monthly amounts
  const expenseRanges = {
    'expenses-rent': [400, 2000],
    'expenses-groceries': [150, 1200],
    'expenses-utilities': [50, 600],
    'expenses-electricity': [20, 400],
    'expenses-heating': [20, 400],
    'expenses-water': [10, 200],
    'expenses-sewerage': [5, 150],
    'expenses-garbage': [5, 150],
    'expenses_transport': [0, 500],
    'expenses_bus_pass': [0, 250],
    'expenses-other-total': [0, 800]
  };
  Object.entries(expenseRanges).forEach(([key, [mn, mx]]) => {
    if (key in payloadData) {
      const num = Number(payloadData[key]);
      if (Number.isFinite(num)) {
        payloadData[key] = clamp(num, mn, mx);
      }
    }
  });
  // Transport-specific: ensure bus pass amount when selected
  const transportOpts = Array.isArray(payloadData['expenses_transport'])
    ? payloadData['expenses_transport']
    : (payloadData['expenses_transport'] ? [payloadData['expenses_transport']] : []);
  if (transportOpts.some(opt => ['buss_pass','bus_pass','bus'].includes(String(opt).toLowerCase()))) {
    const amt = Number(payloadData['expenses_bus_pass']);
    if (!Number.isFinite(amt) || amt <= 0) {
      const val = Math.round(60 + Math.random() * 80); // 60-140 monthly
      payloadData['expenses_bus_pass'] = val;
    }
  }
  // Normalize loan-grant-details to a string if object provided
  if (payloadData['loan-grant-details'] && typeof payloadData['loan-grant-details'] === 'object') {
    const name = payloadData['loan-grant-details'].name || payloadData['loan-grant-details'].title || 'Student grant';
    const amt = payloadData['loan-grant-details'].monthly_amount || payloadData['loan-grant-details'].amount || payloadData['loan-grant-details'].value || '';
    const amtStr = Number.isFinite(Number(amt)) ? `$${Number(amt)}` : String(amt || '$400');
    payloadData['loan-grant-details'] = `${name} – ${amtStr} per month`;
  }
  // Generic fallbacks for missing paragraph fields (avoid empty text blocks)
  if (!payloadData['paragraph']) {
    payloadData['paragraph'] = 'I am applying to improve my skills and employment opportunities.';
  }
  if (!payloadData['paragraph-2']) {
    payloadData['paragraph-2'] = 'I am committed to completing this program and contributing to my community.';
  }
  if (!payloadData['paragraph-3']) {
    payloadData['paragraph-3'] = 'My goal is to secure stable work and support my family.';
  }
  // Emergency contact defaults
  if (!payloadData['emergency-contact-name']) payloadData['emergency-contact-name'] = fullName || 'Contact Name';
  if (!payloadData['emergency-contact-telephone']) payloadData['emergency-contact-telephone'] = '(204) 555-0102';
  if (!payloadData['emergency-contact-relationship']) payloadData['emergency-contact-relationship'] = 'Family';
  // Fallbacks for program/support/income if still missing
  if (!payloadData['target-program']) {
    payloadData['target-program'] = 'skills_development';
    warnings.push('program_fallback_applied');
    chunkLogs.push({ chunk: 'program-core-fallback', ok: true, missing: ['target-program'], preview: 'skills_development' });
    if (typeof onProgress === 'function') onProgress({ type: 'chunk', chunk: 'program-core-fallback', ok: true, missing: ['target-program'] });
  }
  if (!payloadData['long-term-goal']) {
    payloadData['long-term-goal'] = 'Secure skills training and stable employment in community.';
    warnings.push('program_goal_fallback_applied');
  }
  if (!Array.isArray(payloadData['barriers'])) {
    payloadData['barriers'] = ['education', 'funding'];
    warnings.push('program_supports_fallback_applied');
  }
  if (!Array.isArray(payloadData['requested-supports']) || !payloadData['requested-supports'].length) {
    payloadData['requested-supports'] = ['tuition', 'books'];
    warnings.push('requested-supports defaulted');
  }
  if (!payloadData['disability-support']) {
    payloadData['disability-support'] = 'no';
  }
  if (!payloadData['labour-force-status']) {
    payloadData['labour-force-status'] = 'unemployed';
    warnings.push('labour_fallback_applied');
  }
  if (!payloadData['highest-education']) {
    payloadData['highest-education'] = 'secondary_school_diploma_or_ged';
  }
  if (!payloadData['education-year']) {
    payloadData['education-year'] = 2015;
  }
  if (!payloadData['education-location']) {
    payloadData['education-location'] = province.toLowerCase();
  }
  ['consent', 'indigenous_declaration', 'conflict_applicant_signature', 'legal_submission_sig'].forEach(key => {
    payloadData[key] = coerceSignatureField(payloadData[key], fullName);
  });

  // Deterministic signatures and identity-linked fields
  const reg = payloadData['registration-number'] || `REG-${province}-${String(Date.now()).slice(-5)}`;
  // Normalize registration number: 10 digits with a space after first three (e.g., 123 4567890)
  const regNum = (() => {
    const digits = String(reg).replace(/\D+/g, '').padEnd(10, '0').slice(0, 10);
    return `${digits.slice(0,3)} ${digits.slice(3)}`;
  })();
  const sin = payloadData['social-insurance-number'] || '123-456-789';
  const affiliation = payloadData['indigenous-affiliation-declaration'] || `Member of the Atikamekw Nation in ${province}`;
  payloadData['registration-number'] = regNum;
  payloadData['social-insurance-number'] = sin;
  payloadData['indigenous-affiliation-declaration'] = affiliation;
  payloadData['conflict_of_interest'] = payloadData['conflict_of_interest'] || 'no_conflict';
  const sigName = identityFullName || fullName;
  payloadData['consent'] = coerceSignatureField(payloadData['consent'], sigName);
  payloadData['indigenous_declaration'] = coerceSignatureField(payloadData['indigenous_declaration'], sigName);
  payloadData['conflict_applicant_signature'] = coerceSignatureField(payloadData['conflict_applicant_signature'], sigName);
  payloadData['legal_submission_sig'] = coerceSignatureField(payloadData['legal_submission_sig'], sigName);
  // Defensive schema conformance: keep only published input fields and coerce to expected value shapes.
  const schemaNormalized = normalizePayloadToPublishedSchema(payloadData, schemaFieldSpecs, { signatureName: sigName });
  const finalPayloadData = schemaNormalized.normalized;
  if (schemaNormalized.droppedKeys.length) {
    warnings.push(`schema_dropped_keys:${schemaNormalized.droppedKeys.join(',')}`);
  }
  if (schemaNormalized.coercedKeys.length) {
    warnings.push(`schema_coerced_keys:${schemaNormalized.coercedKeys.join(',')}`);
  }

  // Field-specific safety for identity object spillover.
  const affiliationRaw = finalPayloadData['indigenous-affiliation-declaration'];
  if (affiliationRaw && typeof affiliationRaw === 'object' && !Array.isArray(affiliationRaw)) {
    const affiliationFromObject = affiliationRaw.first_nations_band || affiliationRaw.name || extractPrimitiveFromObject(affiliationRaw);
    finalPayloadData['indigenous-affiliation-declaration'] = affiliationFromObject ? String(affiliationFromObject) : null;
  }
  const regRaw = finalPayloadData['registration-number'];
  if (regRaw && typeof regRaw === 'object' && !Array.isArray(regRaw)) {
    const regFromObject = regRaw.registration_number || regRaw.value || extractPrimitiveFromObject(regRaw);
    finalPayloadData['registration-number'] = regFromObject ? String(regFromObject) : null;
  }
  try {
    const seededUploads = await seedDummyDraftUploadMetadata({
      schemaSteps,
      payloadData: finalPayloadData,
      userId
    });
    if (seededUploads?.payloadPatch && Object.keys(seededUploads.payloadPatch).length) {
      Object.assign(finalPayloadData, seededUploads.payloadPatch);
    }
    if (Array.isArray(seededUploads?.warnings) && seededUploads.warnings.length) {
      warnings.push(...seededUploads.warnings);
    }
    if (Number.isFinite(seededUploads?.seededCount) && seededUploads.seededCount > 0) {
      const uploadSeedEvent = {
        chunk: 'dummy-document-uploads',
        ok: true,
        missing: [],
        preview: `${seededUploads.seededCount} placeholder uploads`
      };
      chunkLogs.push(uploadSeedEvent);
      if (typeof onProgress === 'function') onProgress({ type: 'chunk', ...uploadSeedEvent });
    }
  } catch (err) {
    warnings.push('dummy_upload_seed_failed');
    console.warn('[ai-dummy-draft] placeholder upload seeding failed for user %s: %s', userId, err?.message || err);
  }
  const history = buildHistoryForStep(canonicalStepCursor, stepOrder);
  const draftPayload = { ...finalPayloadData, history };
  const summary = {
    applicantName: `${finalPayloadData['first-name']} ${finalPayloadData['last-name']}`.trim(),
    profileId: finalPayloadData['registration-number'] || finalPayloadData['indigenous-affiliation-declaration'] || 'ai-generated',
    homeCommunity: finalPayloadData['home-comminuty'] || finalPayloadData['address-city'] || null,
    targetProgram: finalPayloadData['target-program'] || null
  };
  return {
    draftPayload,
    history,
    summary,
    stepCursor: canonicalStepCursor,
    workflowId,
    validation: { errors, warnings, province, chunks: chunkLogs, calls: callDiagnostics }
  };
}

