async function buildDummyDraft(stepCursor = 'summary-page') {
  const choice = DUMMY_DRAFTS[Math.floor(Math.random() * DUMMY_DRAFTS.length)];
  let stepOrder = [...DUMMY_STEP_ORDER_FALLBACK];
  try {
    const schemaPayload = await fetchPublishedWorkflowSchema();
    const schemaSteps = schemaPayload?.schema || schemaPayload?.schemaEnvelope?.steps || [];
    stepOrder = resolveStepOrder(schemaSteps);
  } catch (_) {}
  const canonicalStepCursor = normalizeStepCursor(stepCursor, stepOrder);
  const history = buildHistoryForStep(canonicalStepCursor, stepOrder);
  const draftPayload = { ...choice.payload, history: [...history] };
  const summary = {
    applicantName: `${choice.payload['first-name']} ${choice.payload['last-name']}`.trim(),
    profileId: choice.id,
    homeCommunity: draftPayload['home-comminuty'] || null,
    targetProgram: draftPayload['target-program'] || null
  };
  return { draftPayload, history, summary, stepCursor: canonicalStepCursor };
}

// GET /api/regions/canada -> province/territory list for dummy generation UI
app.get('/api/regions/canada', async (_req, res) => {
  try {
    const [rows] = await pool.query('SELECT region_id, code, name_en FROM canada_region ORDER BY name_en');
    const options = (rows || []).map(row => ({
      regionId: row.region_id,
      code: String(row.code || '').trim().toUpperCase(),
      name: row.name_en || row.code
    })).filter(opt => opt.code);
    res.json(options);
  } catch (err) {
    console.error('[canada-regions] lookup failed:', err.message);
    res.status(500).json({ error: 'region_lookup_failed', message: err.message });
  }
});

// POST /api/ai/create-dummy-draft
// Body: { province?: string, userId?: number, stepCursor?: string, workflowId?: string, additionalRequestDetails?: string }
// Query: ?stream=1 to receive NDJSON progress events per chunk and final result.
app.post('/api/ai/create-dummy-draft', requireUnsafeAdminDebugAccess, async (req, res) => {
  const stream = req.query.stream === '1';
  const body = req.body || {};
  const userId = Number(body.userId) || 48; // enforce single test user by default
  const workflowId = String(body.workflowId || 'iset-v1');
  const requestedStepCursor = String(body.stepCursor || 'summary-page');
  const province = body.province || body.provinceCode || body.regionCode;
  const additionalRequestDetails = typeof body.additionalRequestDetails === 'string' ? body.additionalRequestDetails : '';
  if (detectAdminAiExternalSensitiveContent(additionalRequestDetails)) {
    return res.status(400).json({
      error: 'sensitive_ai_content',
      message: 'Remove applicant/client identifiers, credentials, or contact details from dummy-generation guidance.'
    });
  }

  const sendEvent = (obj) => {
    if (!stream) return;
    try {
      res.write(JSON.stringify(obj) + '\n');
    } catch (_) {
      // ignore write errors
    }
  };

  try {
    if (stream) {
      res.setHeader('Content-Type', 'application/x-ndjson');
      res.setHeader('Cache-Control', 'no-cache, no-transform');
      res.flushHeaders?.();
    }

    const generated = await generateAiDummyDraft({
      provinceCode: province,
      stepCursor: requestedStepCursor,
      workflowId,
      userId,
      additionalRequestDetails,
      onProgress: (event) => sendEvent(event)
    });
    const { draftPayload, history, summary, validation, stepCursor } = generated;

    const [existingRows] = await pool.query(
      'SELECT id, version FROM iset_intake.iset_application_draft_dynamic WHERE user_id = ? LIMIT 1',
      [userId]
    );

    let action = 'inserted';
    let version = 1;
    if (existingRows.length) {
      const current = existingRows[0];
      version = Number(current.version || 1) + 1;
      await pool.query(
        `UPDATE iset_intake.iset_application_draft_dynamic
           SET workflow_id = ?, step_cursor = ?, draft_payload = ?, history = ?, doc_refs = NULL, version = ?
         WHERE user_id = ?`,
        [workflowId, stepCursor, JSON.stringify(draftPayload), JSON.stringify(history), version, userId]
      );
      action = 'updated';
    } else {
      await pool.query(
        `INSERT INTO iset_intake.iset_application_draft_dynamic
           (user_id, workflow_id, step_cursor, draft_payload, history, doc_refs, version)
         VALUES (?,?,?,?,?,NULL,1)`,
        [userId, workflowId, stepCursor, JSON.stringify(draftPayload), JSON.stringify(history)]
      );
    }

    const finalPayload = {
      ok: true,
      action,
      userId,
      version,
      stepCursor,
      workflowId,
      applicant: summary,
      validation
    };

    if (stream) {
      sendEvent({ type: 'done', result: finalPayload });
      return res.end();
    }
    return res.json(finalPayload);
  } catch (err) {
    const status = err.status || 500;
    console.error('[ai-dummy-draft] error:', err.message);
    if (stream) {
      sendEvent({ type: 'error', error: 'ai_dummy_draft_failed', message: err.message, details: err.details || null });
      return res.end();
    }
    res.status(status).json({ error: 'ai_dummy_draft_failed', message: err.message, details: err.details || null });
  }
});

// POST /api/create-dummy-draft
// Body (optional): { userId?: number, stepCursor?: string, workflowId?: string }
// Inserts or updates a single-row draft (table has UNIQUE user_id) to speed portal testing.
app.post('/api/create-dummy-draft', requireUnsafeAdminDebugAccess, async (req, res) => {
  try {
    const body = req.body || {};
    const userId = Number(body.userId) || 48;               // default test applicant
    const workflowId = String(body.workflowId || 'iset-v1');
    const requestedStepCursor = String(body.stepCursor || 'summary-page');

    let { draftPayload, history, summary, stepCursor } = await buildDummyDraft(requestedStepCursor);
    const userIdentity = await fetchUserIdentityById(userId);
    const nameParts = parseFirstLastFromUserName(userIdentity?.name);
    if (nameParts && nameParts.firstName) {
      draftPayload['first-name'] = nameParts.firstName;
      if (nameParts.lastName) {
        draftPayload['last-name'] = nameParts.lastName;
      }
      draftPayload['preferred-name'] = nameParts.firstName;
      const fullName = nameParts.fullName || [nameParts.firstName, nameParts.lastName].filter(Boolean).join(' ').trim();
      // Keep signature fields aligned with the overridden applicant name.
      ['consent', 'indigenous_declaration', 'conflict_applicant_signature', 'legal_submission_sig'].forEach((key) => {
        if (key in draftPayload) {
          draftPayload[key] = coerceSignatureField(draftPayload[key], fullName);
        }
      });
      summary = { ...(summary || {}), applicantName: fullName || summary?.applicantName };
    }
    if (userIdentity?.email) {
      draftPayload['contact-email-address'] = userIdentity.email;
    }

    // Check existing row
    const [existingRows] = await pool.query(
      'SELECT id, version FROM iset_intake.iset_application_draft_dynamic WHERE user_id = ? LIMIT 1',
      [userId]
    );

    if (existingRows.length) {
      const current = existingRows[0];
      const newVersion = Number(current.version || 1) + 1;
      await pool.query(
        `UPDATE iset_intake.iset_application_draft_dynamic
           SET workflow_id = ?, step_cursor = ?, draft_payload = ?, history = ?, doc_refs = NULL, version = ?
         WHERE user_id = ?`,
        [workflowId, stepCursor, JSON.stringify(draftPayload), JSON.stringify(history), newVersion, userId]
      );
      return res.json({
        ok: true,
        action: 'updated',
        userId,
        version: newVersion,
        stepCursor,
        workflowId,
        applicant: summary
      });
    }

    // Insert fresh
    await pool.query(
      `INSERT INTO iset_intake.iset_application_draft_dynamic
         (user_id, workflow_id, step_cursor, draft_payload, history, doc_refs, version)
       VALUES (?,?,?,?,?,NULL,1)`,
      [userId, workflowId, stepCursor, JSON.stringify(draftPayload), JSON.stringify(history)]
    );

    res.json({
      ok: true,
      action: 'inserted',
      userId,
      version: 1,
      stepCursor,
      workflowId,
      applicant: summary
    });
  } catch (err) {
    console.error('[dummy-draft] error:', err.message);
    res.status(500).json({ error: 'dummy_draft_failed', message: err.message });
  }
});

