// Intervention proposals awaiting approval
app.get('/api/dashboard/intervention-approval-items', async (req, res) => {
  const role = inferUserRole(req) || 'Guest';
  if (role !== 'NWAC Administrator' && role !== 'Regional Manager' && role !== 'ISET Coordinator') {
    return res.json({ role, items: [] });
  }
  const regionIds = resolveRequestRegionIds(req);
  const regionId = regionIds.length ? regionIds[0] : null;
  const proposalReviewStatusExpr = `REPLACE(REPLACE(LOWER(TRIM(COALESCE(p.review_status, ''))), '-', '_'), ' ', '_')`;
  const interventionReviewStatusExpr = buildInterventionReviewStatusSql('ci');
  const interventionDeliveryStatusExpr = buildInterventionDeliveryStatusSql('ci');
  const interventionEffectiveStatusExpr = buildInterventionEffectiveStatusSql('ci');
  const legacyFilters = [`${interventionReviewStatusExpr} IN (?, ?)`];
  const legacyParams = ['submitted', 'in_review'];
  const proposalOuterFilters = [];
  const proposalParams = ['submitted', 'in_review', 'submitted', 'in_review'];
  if (role === 'Regional Manager') {
    if (!regionIds.length) {
      return res.json({ role, items: [] });
    }
    if (regionIds.length === 1) {
      legacyFilters.push('sp.region_id = ?');
      legacyParams.push(regionIds[0]);
      proposalOuterFilters.push('q.assigned_user_region_id = ?');
      proposalParams.push(regionIds[0]);
    } else {
      const placeholders = regionIds.map(() => '?').join(',');
      legacyFilters.push(`sp.region_id IN (${placeholders})`);
      legacyParams.push(...regionIds);
      proposalOuterFilters.push(`q.assigned_user_region_id IN (${placeholders})`);
      proposalParams.push(...regionIds);
    }
  } else if (role === 'ISET Coordinator') {
    const staffId = normalisePositiveInteger(req.staffProfile?.id);
    if (!staffId) {
      return res.json({ role, items: [] });
    }
    legacyFilters.push('c.assigned_staff_profile_id = ?');
    legacyParams.push(staffId);
    proposalOuterFilters.push('q.assigned_to_user_id = ?');
    proposalParams.push(staffId);
  }
  const legacyWhere = legacyFilters.length ? `WHERE ${legacyFilters.join(' AND ')}` : '';
  const proposalOuterWhere = proposalOuterFilters.length ? `WHERE ${proposalOuterFilters.join(' AND ')}` : '';
  const legacySql = `
    SELECT
      NULL AS proposal_id,
      NULL AS proposal_kind,
      ci.id AS intervention_id,
      ci.case_id,
      ci.action_plan_id,
      ci.intervention_code AS intervention_code,
      ci.metadata_json,
      JSON_UNQUOTE(JSON_EXTRACT(ci.metadata_json, '$.title')) AS intervention_title,
      ci.status AS intervention_status,
      ${interventionReviewStatusExpr} AS intervention_review_status,
      ${interventionDeliveryStatusExpr} AS intervention_delivery_status,
      ${interventionEffectiveStatusExpr} AS intervention_effective_status,
      ci.start_date AS intervention_start_date,
      COALESCE(ci.intervention_cost, ci.budget_amount, ci.approved_amount) AS intervention_cost_total,
      COALESCE(ci.updated_at, ci.created_at) AS submitted_at,
      c.case_number,
c.assigned_staff_profile_id AS assigned_to_user_id,
      sp.email AS assigned_user_email,
      sp.primary_role AS assigned_user_role,
      sp.region_id AS assigned_user_region_id,
      ca.esdc_eligibility AS assessment_esdc_eligibility,
      bp.code AS budget_pot_code,
      a.id AS application_id,
      c.case_context_json,
      cl.first_name AS client_first_name,
      cl.last_name AS client_last_name,
      JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.submission_snapshot.reference_number')) AS tracking_id,
      JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.personal.full_name')) AS application_full_name,
      JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.answers."preferred-name"')) AS application_preferred_name,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.\"first-name\"')) AS submission_first_name,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.\"last-name\"')) AS submission_last_name,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.\"preferred-name\"')) AS submission_preferred_name,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.\"address-province\"')) AS submission_address_province,
      JSON_UNQUOTE(JSON_EXTRACT(cl.address_json, '$.address.province')) AS client_address_province,
      ic.label AS intervention_label
    FROM iset_case_intervention ci
    JOIN iset_case c ON c.id = ci.case_id
    LEFT JOIN iset_case_action_plan ap ON ap.id = ci.action_plan_id
    LEFT JOIN iset_case_assessment ca ON ca.case_id = c.id
    LEFT JOIN client cl ON cl.id = c.client_id
    ${buildCasePrimaryApplicationJoinSql('c', 'a')}
    LEFT JOIN iset_application_submission s ON s.id = a.submission_id
    LEFT JOIN staff_profiles sp ON sp.id = c.assigned_staff_profile_id
    LEFT JOIN esdc_intervention_code ic ON ic.code = ci.intervention_code
    LEFT JOIN budget_pot bp
      ON (
        (ap.budget_pot REGEXP '^[0-9]+$' AND bp.id = CAST(ap.budget_pot AS UNSIGNED))
        OR bp.code = ap.budget_pot
      )
    ${legacyWhere}
    ORDER BY ci.updated_at DESC, ci.created_at DESC
    LIMIT 200
  `;
  const proposalSql = `
    SELECT *
      FROM (
        SELECT
          p.id AS proposal_id,
          p.proposal_kind AS proposal_kind,
          COALESCE(p.legacy_intervention_id, p.source_intervention_id, NULL) AS intervention_id,
          p.case_id,
          COALESCE(p.action_plan_id, ci.action_plan_id) AS action_plan_id,
          COALESCE(p.intervention_code, ci.intervention_code) AS intervention_code,
          COALESCE(p.metadata_json, ci.metadata_json) AS metadata_json,
          COALESCE(
            p.title,
            JSON_UNQUOTE(JSON_EXTRACT(p.metadata_json, '$.title')),
            JSON_UNQUOTE(JSON_EXTRACT(ci.metadata_json, '$.title'))
          ) AS intervention_title,
          ci.status AS intervention_status,
          ${proposalReviewStatusExpr} AS intervention_review_status,
          NULL AS intervention_delivery_status,
          ${proposalReviewStatusExpr} AS intervention_effective_status,
          COALESCE(p.start_date, ci.start_date) AS intervention_start_date,
          COALESCE(p.proposed_cost, ci.intervention_cost, ci.budget_amount, ci.approved_amount) AS intervention_cost_total,
          COALESCE(p.submitted_at, p.created_at, ci.updated_at, ci.created_at) AS submitted_at,
          c.case_number,
c.assigned_staff_profile_id AS assigned_to_user_id,
          sp.email AS assigned_user_email,
          sp.primary_role AS assigned_user_role,
          sp.region_id AS assigned_user_region_id,
          ca.esdc_eligibility AS assessment_esdc_eligibility,
          bp.code AS budget_pot_code,
          COALESCE(p.application_id, a.id) AS application_id,
          c.case_context_json,
          cl.first_name AS client_first_name,
          cl.last_name AS client_last_name,
          JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.submission_snapshot.reference_number')) AS tracking_id,
          JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.personal.full_name')) AS application_full_name,
          JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.answers."preferred-name"')) AS application_preferred_name,
          JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.\"first-name\"')) AS submission_first_name,
          JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.\"last-name\"')) AS submission_last_name,
          JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.\"preferred-name\"')) AS submission_preferred_name,
          JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.\"address-province\"')) AS submission_address_province,
          JSON_UNQUOTE(JSON_EXTRACT(cl.address_json, '$.address.province')) AS client_address_province,
          ic.label AS intervention_label
        FROM iset_intervention_proposal p
        JOIN iset_case c ON c.id = p.case_id
        LEFT JOIN iset_case_intervention ci ON ci.id = p.legacy_intervention_id
        LEFT JOIN iset_case_action_plan ap ON ap.id = COALESCE(p.action_plan_id, ci.action_plan_id)
        LEFT JOIN iset_case_assessment ca ON ca.case_id = c.id
        LEFT JOIN client cl ON cl.id = c.client_id
        LEFT JOIN iset_application a ON a.id = COALESCE(p.application_id, ${buildCasePrimaryApplicationIdSql('c')})
        LEFT JOIN iset_application_submission s ON s.id = a.submission_id
        LEFT JOIN staff_profiles sp ON sp.id = c.assigned_staff_profile_id
        LEFT JOIN esdc_intervention_code ic ON ic.code = COALESCE(p.intervention_code, ci.intervention_code)
        LEFT JOIN budget_pot bp
          ON (
            (ap.budget_pot REGEXP '^[0-9]+$' AND bp.id = CAST(ap.budget_pot AS UNSIGNED))
            OR bp.code = ap.budget_pot
          )
        WHERE ${proposalReviewStatusExpr} IN (?, ?)

        UNION ALL

        SELECT
          NULL AS proposal_id,
          NULL AS proposal_kind,
          ci.id AS intervention_id,
          ci.case_id,
          ci.action_plan_id,
          ci.intervention_code AS intervention_code,
          ci.metadata_json,
          JSON_UNQUOTE(JSON_EXTRACT(ci.metadata_json, '$.title')) AS intervention_title,
          ci.status AS intervention_status,
          ${interventionReviewStatusExpr} AS intervention_review_status,
          ${interventionDeliveryStatusExpr} AS intervention_delivery_status,
          ${interventionEffectiveStatusExpr} AS intervention_effective_status,
          ci.start_date AS intervention_start_date,
          COALESCE(ci.intervention_cost, ci.budget_amount, ci.approved_amount) AS intervention_cost_total,
          COALESCE(ci.updated_at, ci.created_at) AS submitted_at,
          c.case_number,
c.assigned_staff_profile_id AS assigned_to_user_id,
          sp.email AS assigned_user_email,
          sp.primary_role AS assigned_user_role,
          sp.region_id AS assigned_user_region_id,
          ca.esdc_eligibility AS assessment_esdc_eligibility,
          bp.code AS budget_pot_code,
          a.id AS application_id,
          c.case_context_json,
          cl.first_name AS client_first_name,
          cl.last_name AS client_last_name,
          JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.submission_snapshot.reference_number')) AS tracking_id,
          JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.personal.full_name')) AS application_full_name,
          JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.answers."preferred-name"')) AS application_preferred_name,
          JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.\"first-name\"')) AS submission_first_name,
          JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.\"last-name\"')) AS submission_last_name,
          JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.\"preferred-name\"')) AS submission_preferred_name,
          JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.\"address-province\"')) AS submission_address_province,
          JSON_UNQUOTE(JSON_EXTRACT(cl.address_json, '$.address.province')) AS client_address_province,
          ic.label AS intervention_label
        FROM iset_case_intervention ci
        LEFT JOIN iset_intervention_proposal p_existing ON p_existing.legacy_intervention_id = ci.id
        JOIN iset_case c ON c.id = ci.case_id
        LEFT JOIN iset_case_action_plan ap ON ap.id = ci.action_plan_id
        LEFT JOIN iset_case_assessment ca ON ca.case_id = c.id
        LEFT JOIN client cl ON cl.id = c.client_id
        ${buildCasePrimaryApplicationJoinSql('c', 'a')}
        LEFT JOIN iset_application_submission s ON s.id = a.submission_id
        LEFT JOIN staff_profiles sp ON sp.id = c.assigned_staff_profile_id
        LEFT JOIN esdc_intervention_code ic ON ic.code = ci.intervention_code
        LEFT JOIN budget_pot bp
          ON (
            (ap.budget_pot REGEXP '^[0-9]+$' AND bp.id = CAST(ap.budget_pot AS UNSIGNED))
            OR bp.code = ap.budget_pot
          )
        WHERE p_existing.id IS NULL
          AND ${interventionReviewStatusExpr} IN (?, ?)
      ) q
    ${proposalOuterWhere}
    ORDER BY q.submitted_at DESC, q.intervention_id DESC
    LIMIT 200
  `;
  try {
    let rows = [];
    try {
      [rows] = await pool.query(proposalSql, proposalParams);
    } catch (proposalError) {
      if (proposalError && (proposalError.code === 'ER_NO_SUCH_TABLE' || proposalError.code === 'ER_BAD_FIELD_ERROR')) {
        [rows] = await pool.query(legacySql, legacyParams);
      } else {
        throw proposalError;
      }
    }
    const proposalInterventionsByRow = new Map();
    const interventionCodes = new Set();
    (Array.isArray(rows) ? rows : []).forEach((row, index) => {
      const metadata = safeJsonParse(row?.metadata_json, {}) || {};
      const proposedInterventions = normalizeAssessmentProposedInterventions(
        metadata?.proposedInterventions ?? metadata?.proposed_interventions ?? null
      );
      proposalInterventionsByRow.set(index, proposedInterventions);
      proposedInterventions.forEach(entry => {
        if (entry?.code) {
          interventionCodes.add(String(entry.code));
        }
      });
      if (row?.intervention_code != null) {
        interventionCodes.add(String(row.intervention_code));
      }
    });
    const interventionLabelMap = await fetchInterventionCodeLabels(pool, Array.from(interventionCodes));
    const items = Array.isArray(rows) ? rows.map((r, rowIndex) => {
      const caseContext = safeJsonParse(r.case_context_json, null) || {};
      const metadata = safeJsonParse(r?.metadata_json, {}) || {};
      const contextPersonal = caseContext?.applicationPersonal || {};
      const contextAnswers = caseContext?.applicationAnswers || {};
      const first = [
        r.submission_first_name,
        contextPersonal.first_name,
        contextPersonal.firstName,
        contextPersonal.given_name,
        contextPersonal.givenName,
        caseContext?.firstName,
        r.client_first_name,
      ].map(value => normaliseString(value)).find(Boolean) || null;
      const last = [
        r.submission_last_name,
        contextPersonal.last_name,
        contextPersonal.lastName,
        contextPersonal.family_name,
        contextPersonal.familyName,
        caseContext?.lastName,
        r.client_last_name,
      ].map(value => normaliseString(value)).find(Boolean) || null;
      const preferred = [
        r.submission_preferred_name,
        contextPersonal.preferred_name,
        contextPersonal.preferredName,
        caseContext?.preferredName,
        contextAnswers['preferred-name'],
        contextAnswers['preferred_name'],
        r.application_preferred_name,
      ].map(value => normaliseString(value)).find(Boolean) || null;
      const full = [first, last].filter(Boolean).join(' ').trim();
      const applicantName =
        full ||
        preferred ||
        normaliseString(r.application_full_name) ||
        normaliseString(r.tracking_id) ||
        normaliseString(r.case_number) ||
        'Applicant';
      const interventionLabel = normaliseString(r.intervention_label) || normaliseString(r.intervention_title) || null;
      const interventionGroups = buildApprovalInterventionGroups({
        proposedInterventions: proposalInterventionsByRow.get(rowIndex) || [],
        labelMap: interventionLabelMap,
        fallbackCode: r.intervention_code,
        fallbackLabel: interventionLabel,
      });
      const interventionSummaries = buildApprovalInterventionSummaries({
        proposedInterventions: proposalInterventionsByRow.get(rowIndex) || [],
        labelMap: interventionLabelMap,
        fallbackCode: r.intervention_code,
        fallbackLabel: interventionLabel,
        fallbackCost: r.intervention_cost_total,
      });
      const revisionSourceInterventionId =
        normalisePositiveInteger(
          metadata?.revision?.sourceInterventionId ??
          metadata?.revision?.source_intervention_id ??
          null
        ) || null;
      const proposalKind = normaliseString(r.proposal_kind || null) || null;
      const approvalRequestType =
        proposalKind === 'revision' || revisionSourceInterventionId
          ? 'revised_intervention'
          : 'new_intervention';
      const approvalRequestTypeLabel =
        approvalRequestType === 'revised_intervention'
          ? 'Proposed change to intervention'
          : 'Additional intervention proposal';
      return {
        proposalId: r.proposal_id || null,
        interventionId: r.intervention_id || null,
        caseId: r.case_id || null,
        caseNumber: r.case_number || null,
        applicationId: r.application_id || null,
        actionPlanId: r.action_plan_id || null,
        trackingId: r.tracking_id || null,
        applicantName,
        applicant_name: applicantName,
        address_province:
          normaliseString(r.submission_address_province) ||
          normaliseString(r.client_address_province) ||
          null,
        status: normaliseString(r.intervention_review_status) || normaliseString(r.intervention_status) || null,
        review_status: normaliseString(r.intervention_review_status) || null,
        delivery_status: normaliseString(r.intervention_delivery_status) || null,
        intervention_effective_status: normaliseString(r.intervention_effective_status) || null,
        submittedAt: r.submitted_at ? new Date(r.submitted_at).toISOString() : null,
        owner: r.assigned_user_email || null,
        ...buildAssignedStaffProfileResponseFields(r),
        assigned_user_email: r.assigned_user_email || null,
        assigned_user_role: r.assigned_user_role || null,
        assigned_user_region_id: r.assigned_user_region_id || null,
        intervention_code: r.intervention_code || null,
        intervention_label: interventionLabel,
        intervention_cost_total: r.intervention_cost_total || null,
        interventionGroups,
        intervention_groups: interventionGroups,
        interventionSummaries,
        intervention_summaries: interventionSummaries,
        intervention_start_date: r.intervention_start_date || null,
        assessment_esdc_eligibility: r.assessment_esdc_eligibility || null,
        budgetPotCode: normaliseString(r.budget_pot_code) || null,
        budget_pot_code: normaliseString(r.budget_pot_code) || null,
        approval_request_type: approvalRequestType,
        approval_request_type_label: approvalRequestTypeLabel,
      };
    }) : [];
    return res.json({ role, regionId: regionId ?? null, regionIds: regionIds.length ? regionIds : null, items });
  } catch (err) {
    if (err && (err.code === 'ER_NO_SUCH_TABLE' || err.code === 'ER_BAD_FIELD_ERROR')) {
      return res.json({ role, regionId: regionId ?? null, regionIds: regionIds.length ? regionIds : null, items: [] });
    }
    console.error('[intervention-approval-items] fetch failed:', err.message);
    return res.status(500).json({ error: 'intervention_approval_items_fetch_failed', message: err.message });
  }
});

// Approved intervention proposals/revisions still waiting on approval-letter follow-up
app.get('/api/dashboard/intervention-completion-items', async (req, res) => {
  const role = inferUserRole(req) || 'Guest';
  if (!['ISET Coordinator', 'NWAC Administrator', 'Regional Manager'].includes(role)) {
    return res.json({ role, items: [] });
  }

  const filters = [];
  const params = [];
  const regionIds = resolveRequestRegionIds(req);
  const regionId = regionIds.length ? regionIds[0] : null;

  if (role === 'ISET Coordinator') {
    const staffId = normalisePositiveInteger(req.staffProfile?.id);
    if (!staffId) {
      return res.json({ role, items: [] });
    }
    filters.push('c.assigned_staff_profile_id = ?');
    params.push(staffId);
  } else if (role === 'Regional Manager') {
    if (!regionIds.length) {
      return res.json({ role, items: [] });
    }
    const placeholders = regionIds.map(() => '?').join(',');
    const requesterStaffProfileId = normalisePositiveInteger(req.staffProfile?.id) || 0;
    filters.push(`(sp.region_id IN (${placeholders}) OR c.assigned_staff_profile_id = ?)`);
    params.push(...regionIds, requesterStaffProfileId);
  }

  const proposalReviewStatusExpr = `REPLACE(REPLACE(LOWER(TRIM(COALESCE(p.review_status, ''))), '-', '_'), ' ', '_')`;
  const pickedProposalReviewStatusExpr = `REPLACE(REPLACE(LOWER(TRIM(COALESCE(p_pick.review_status, ''))), '-', '_'), ' ', '_')`;
  const interventionReviewStatusExpr = buildInterventionReviewStatusSql('ci');
  const interventionDeliveryStatusExpr = buildInterventionDeliveryStatusSql('ci');
  const interventionEffectiveStatusExpr = buildInterventionEffectiveStatusSql('ci');
  const jsonStringExpr = path => `NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(ci.metadata_json, '${path}')), ''), 'null')`;
  const followUpStatusExpr = `LOWER(COALESCE(
    ${jsonStringExpr('$.approvalLetterFollowUp.status')},
    ${jsonStringExpr('$.approval_letter_follow_up.status')},
    ''
  ))`;
  const followUpSentAtExpr = `COALESCE(
    ${jsonStringExpr('$.approvalLetterFollowUp.sentAt')},
    ${jsonStringExpr('$.approvalLetterFollowUp.approvalLetterSentAt')},
    ${jsonStringExpr('$.approvalLetterFollowUp.firstSentAt')},
    ${jsonStringExpr('$.approval_letter_follow_up.sentAt')},
    ${jsonStringExpr('$.approval_letter_follow_up.approvalLetterSentAt')},
    ${jsonStringExpr('$.approval_letter_follow_up.firstSentAt')}
  )`;
  const followUpCompletedExpr = `LOWER(COALESCE(
    ${jsonStringExpr('$.approvalLetterFollowUp.completed')},
    ${jsonStringExpr('$.approval_letter_follow_up.completed')},
    ''
  ))`;
  const followUpSentCondition = `(
    ${followUpStatusExpr} IN ('sent', 'complete', 'completed')
    OR ${followUpSentAtExpr} IS NOT NULL
    OR ${followUpCompletedExpr} IN ('true', '1', 'yes')
  )`;
  const appliedRevisionCondition = `(
    JSON_TYPE(JSON_EXTRACT(ci.metadata_json, '$.lastAppliedRevision')) = 'OBJECT'
    OR COALESCE(JSON_LENGTH(JSON_EXTRACT(ci.metadata_json, '$.revisionHistory')), 0) > 0
  )`;
  const manualBackloadCondition = `(
    LOWER(COALESCE(${jsonStringExpr('$.source')}, '')) IN ('manual_backload', '${AUTO_PLAN_METADATA_SOURCE}')
    OR LOWER(COALESCE(${jsonStringExpr('$.entryMode')}, ${jsonStringExpr('$.entry_mode')}, '')) = 'existing'
  )`;

  const completionFilters = [
    `${interventionReviewStatusExpr} = 'approved'`,
    `NOT ${followUpSentCondition}`,
    `(
      (${proposalReviewStatusExpr} = 'approved' AND p.id IS NOT NULL AND NOT ${manualBackloadCondition})
      OR ${appliedRevisionCondition}
    )`,
    ...filters,
  ];

  const sql = `
    SELECT
      p.id AS proposal_id,
      p.proposal_kind,
      p.review_status AS proposal_review_status,
      ci.id AS intervention_id,
      ci.case_id,
      ci.action_plan_id,
      ci.intervention_code AS intervention_code,
      ci.metadata_json,
      COALESCE(
        p.title,
        JSON_UNQUOTE(JSON_EXTRACT(p.metadata_json, '$.title')),
        JSON_UNQUOTE(JSON_EXTRACT(p.payload_json, '$.title')),
        JSON_UNQUOTE(JSON_EXTRACT(ci.metadata_json, '$.title'))
      ) AS intervention_title,
      ci.status AS intervention_status,
      ${interventionReviewStatusExpr} AS intervention_review_status,
      ${interventionDeliveryStatusExpr} AS intervention_delivery_status,
      ${interventionEffectiveStatusExpr} AS intervention_effective_status,
      ci.start_date AS intervention_start_date,
      COALESCE(p.proposed_cost, ci.intervention_cost, ci.budget_amount, ci.approved_amount) AS intervention_cost_total,
      COALESCE(p.reviewed_at, ci.reviewed_at, p.updated_at, ci.updated_at, ci.created_at) AS approved_at,
      ${appliedRevisionCondition} AS has_applied_revision,
      c.case_number,
c.assigned_staff_profile_id AS assigned_to_user_id,
      sp.email AS assigned_user_email,
      sp.primary_role AS assigned_user_role,
      sp.region_id AS assigned_user_region_id,
      ca.esdc_eligibility AS assessment_esdc_eligibility,
      bp.code AS budget_pot_code,
      COALESCE(p.application_id, a.id) AS application_id,
      c.case_context_json,
      cl.first_name AS client_first_name,
      cl.last_name AS client_last_name,
      JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.submission_snapshot.reference_number')) AS tracking_id,
      JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.personal.full_name')) AS application_full_name,
      JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.answers."preferred-name"')) AS application_preferred_name,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$."first-name"')) AS submission_first_name,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$."last-name"')) AS submission_last_name,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$."preferred-name"')) AS submission_preferred_name,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$."address-province"')) AS submission_address_province,
      JSON_UNQUOTE(JSON_EXTRACT(cl.address_json, '$.address.province')) AS client_address_province,
      ic.label AS intervention_label
    FROM iset_case_intervention ci
    JOIN iset_case c ON c.id = ci.case_id
    LEFT JOIN iset_intervention_proposal p ON p.id = (
      SELECT p_pick.id
        FROM iset_intervention_proposal p_pick
       WHERE p_pick.legacy_intervention_id = ci.id
          OR p_pick.source_intervention_id = ci.id
       ORDER BY CASE WHEN ${pickedProposalReviewStatusExpr} = 'approved' THEN 0 ELSE 1 END,
                p_pick.updated_at DESC,
                p_pick.id DESC
       LIMIT 1
    )
    LEFT JOIN iset_case_action_plan ap ON ap.id = COALESCE(p.action_plan_id, ci.action_plan_id)
    LEFT JOIN iset_case_assessment ca ON ca.case_id = c.id
    LEFT JOIN client cl ON cl.id = c.client_id
    ${buildCasePrimaryApplicationJoinSql('c', 'a')}
    LEFT JOIN iset_application_submission s ON s.id = a.submission_id
    LEFT JOIN staff_profiles sp ON sp.id = c.assigned_staff_profile_id
    LEFT JOIN esdc_intervention_code ic ON ic.code = COALESCE(p.intervention_code, ci.intervention_code)
    LEFT JOIN budget_pot bp
      ON (
        (ap.budget_pot REGEXP '^[0-9]+$' AND bp.id = CAST(ap.budget_pot AS UNSIGNED))
        OR bp.code = ap.budget_pot
      )
    WHERE ${completionFilters.join(' AND ')}
    ORDER BY COALESCE(p.reviewed_at, ci.reviewed_at, p.updated_at, ci.updated_at, ci.created_at) DESC,
             ci.id DESC
    LIMIT 200
  `;

  try {
    const [rows] = await pool.query(sql, params);
    const items = Array.isArray(rows) ? rows.map(r => {
      const caseContext = safeJsonParse(r.case_context_json, null) || {};
      const contextPersonal = caseContext?.applicationPersonal || {};
      const contextAnswers = caseContext?.applicationAnswers || {};
      const first = [
        r.submission_first_name,
        contextPersonal.first_name,
        contextPersonal.firstName,
        contextPersonal.given_name,
        contextPersonal.givenName,
        caseContext?.firstName,
        r.client_first_name,
      ].map(value => normaliseString(value)).find(Boolean) || null;
      const last = [
        r.submission_last_name,
        contextPersonal.last_name,
        contextPersonal.lastName,
        contextPersonal.family_name,
        contextPersonal.familyName,
        caseContext?.lastName,
        r.client_last_name,
      ].map(value => normaliseString(value)).find(Boolean) || null;
      const preferred = [
        r.submission_preferred_name,
        contextPersonal.preferred_name,
        contextPersonal.preferredName,
        caseContext?.preferredName,
        contextAnswers['preferred-name'],
        contextAnswers.preferred_name,
        r.application_preferred_name,
      ].map(value => normaliseString(value)).find(Boolean) || null;
      const full = [first, last].filter(Boolean).join(' ').trim();
      const applicantName =
        full ||
        preferred ||
        normaliseString(r.application_full_name) ||
        normaliseString(r.tracking_id) ||
        normaliseString(r.case_number) ||
        'Applicant';
      const isRevision =
        normaliseInterventionProposalKind(r.proposal_kind, 'new') === 'revision' ||
        Number(r.has_applied_revision || 0) === 1;
      const approvalRequestType = isRevision ? 'revised_intervention' : 'new_intervention';
      const approvalRequestTypeLabel = isRevision
        ? 'Approved intervention revision'
        : 'Approved intervention proposal';
      return {
        proposalId: r.proposal_id || null,
        interventionId: r.intervention_id || null,
        caseId: r.case_id || null,
        caseNumber: r.case_number || null,
        applicationId: r.application_id || null,
        actionPlanId: r.action_plan_id || null,
        trackingId: r.tracking_id || null,
        applicantName,
        applicant_name: applicantName,
        address_province:
          normaliseString(r.submission_address_province) ||
          normaliseString(r.client_address_province) ||
          null,
        status: 'approved',
        review_status: 'approved',
        delivery_status: normaliseString(r.intervention_delivery_status) || null,
        intervention_effective_status: normaliseString(r.intervention_effective_status) || 'approved',
        approvedAt: r.approved_at ? new Date(r.approved_at).toISOString() : null,
        submittedAt: r.approved_at ? new Date(r.approved_at).toISOString() : null,
        owner: r.assigned_user_email || null,
        ...buildAssignedStaffProfileResponseFields(r),
        assigned_user_email: r.assigned_user_email || null,
        assigned_user_role: r.assigned_user_role || null,
        assigned_user_region_id: r.assigned_user_region_id || null,
        intervention_code: r.intervention_code || null,
        intervention_label: normaliseString(r.intervention_label) || normaliseString(r.intervention_title) || null,
        intervention_cost_total: r.intervention_cost_total || null,
        intervention_start_date: r.intervention_start_date || null,
        assessment_esdc_eligibility: r.assessment_esdc_eligibility || null,
        budgetPotCode: normaliseString(r.budget_pot_code) || null,
        budget_pot_code: normaliseString(r.budget_pot_code) || null,
        approval_request_type: approvalRequestType,
        approval_request_type_label: approvalRequestTypeLabel,
      };
    }) : [];
    return res.json({ role, regionId: regionId ?? null, regionIds: regionIds.length ? regionIds : null, items });
  } catch (err) {
    if (err && (err.code === 'ER_NO_SUCH_TABLE' || err.code === 'ER_BAD_FIELD_ERROR')) {
      return res.json({ role, regionId: regionId ?? null, regionIds: regionIds.length ? regionIds : null, items: [] });
    }
    console.error('[intervention-completion-items] fetch failed:', err.message);
    return res.status(500).json({ error: 'intervention_completion_items_fetch_failed', message: err.message });
  }
});

// Active interventions with milestones due (for ISET Coordinators)
app.get('/api/dashboard/intervention-milestone-items', async (req, res) => {
  const role = inferUserRole(req) || 'Guest';
  if (role !== 'ISET Coordinator') {
    return res.json({ role, items: [] });
  }
  const context = await resolveApplicationAssessorContext(req);
  const staffId = context?.staffProfileId || null;
  if (!context?.valid || !staffId) {
    return res.json({ role, items: [] });
  }

  const rawWindow = Number(req.query?.windowDays ?? 14);
  const windowDays = Number.isFinite(rawWindow) && rawWindow > 0 ? Math.min(Math.floor(rawWindow), 90) : 14;
  const windowDate = new Date();
  windowDate.setDate(windowDate.getDate() + windowDays);
  const windowDateValue = windowDate.toISOString().slice(0, 10);

  const interventionReviewStatusExpr = buildInterventionReviewStatusSql('ci');
  const interventionDeliveryStatusExpr = buildInterventionDeliveryStatusSql('ci');
  const interventionEffectiveStatusExpr = buildInterventionEffectiveStatusSql('ci');
  const sql = `
    SELECT
      ci.id AS intervention_id,
      ci.case_id,
      ci.action_plan_id,
      ci.intervention_code AS intervention_code,
      JSON_UNQUOTE(JSON_EXTRACT(ci.metadata_json, '$.title')) AS intervention_title,
      ci.status AS intervention_status,
      ${interventionReviewStatusExpr} AS intervention_review_status,
      ${interventionDeliveryStatusExpr} AS intervention_delivery_status,
      ${interventionEffectiveStatusExpr} AS intervention_effective_status,
      ci.start_date AS intervention_start_date,
      ci.end_date AS intervention_end_date,
      COALESCE(ci.updated_at, ci.created_at) AS submitted_at,
      c.case_number,
c.assigned_staff_profile_id AS assigned_to_user_id,
      sp.email AS assigned_user_email,
      sp.primary_role AS assigned_user_role,
      a.id AS application_id,
      JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.submission_snapshot.reference_number')) AS tracking_id,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$."first-name"')) AS submission_first_name,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$."last-name"')) AS submission_last_name,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$."preferred-name"')) AS submission_preferred_name,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$."address-province"')) AS submission_address_province,
      ic.label AS intervention_label
    FROM iset_case_intervention ci
    JOIN iset_case c ON c.id = ci.case_id
    ${buildCasePrimaryApplicationJoinSql('c', 'a')}
    LEFT JOIN iset_application_submission s ON s.id = a.submission_id
    LEFT JOIN staff_profiles sp ON sp.id = c.assigned_staff_profile_id
    LEFT JOIN esdc_intervention_code ic ON ic.code = ci.intervention_code
    WHERE c.assigned_staff_profile_id = ?
      AND ${interventionDeliveryStatusExpr} IN (?, ?)
      AND (ci.start_date IS NOT NULL OR ci.end_date IS NOT NULL)
      AND (
        (ci.start_date IS NOT NULL AND DATE(ci.start_date) <= ?)
        OR (ci.end_date IS NOT NULL AND DATE(ci.end_date) <= ?)
      )
    ORDER BY COALESCE(ci.end_date, ci.start_date) ASC, ci.id ASC
    LIMIT 200
  `;
  const params = [staffId, 'in_progress', 'suspended', windowDateValue, windowDateValue];
  try {
    const [rows] = await pool.query(sql, params);
    const items = Array.isArray(rows) ? rows.map(r => {
      const preferred = normaliseString(r.submission_preferred_name);
      const first = normaliseString(r.submission_first_name);
      const last = normaliseString(r.submission_last_name);
      const full = [first, last].filter(Boolean).join(' ').trim();
      const applicantName = full || preferred || normaliseString(r.tracking_id) || 'Applicant';
      const interventionLabel = normaliseString(r.intervention_label) || normaliseString(r.intervention_title) || null;
      return {
        interventionId: r.intervention_id || null,
        caseId: r.case_id || null,
        caseNumber: r.case_number || null,
        applicationId: r.application_id || null,
        trackingId: r.tracking_id || null,
        applicantName,
        applicant_name: applicantName,
        address_province: normaliseString(r.submission_address_province) || null,
        status: normaliseString(r.intervention_effective_status) || normaliseString(r.intervention_status) || null,
        review_status: normaliseString(r.intervention_review_status) || null,
        delivery_status: normaliseString(r.intervention_delivery_status) || null,
        intervention_effective_status: normaliseString(r.intervention_effective_status) || null,
        submittedAt: r.submitted_at ? new Date(r.submitted_at).toISOString() : null,
        owner: r.assigned_user_email || null,
        ...buildAssignedStaffProfileResponseFields(r),
        assigned_user_email: r.assigned_user_email || null,
        assigned_user_role: r.assigned_user_role || null,
        intervention_code: r.intervention_code || null,
        intervention_label: interventionLabel,
        intervention_start_date: r.intervention_start_date || null,
        intervention_end_date: r.intervention_end_date || null
      };
    }) : [];
    return res.json({ role, windowDays, items });
  } catch (err) {
    if (err && (err.code === 'ER_NO_SUCH_TABLE' || err.code === 'ER_BAD_FIELD_ERROR')) {
      return res.json({ role, windowDays, items: [] });
    }
    console.error('[intervention-milestone-items] fetch failed:', err.message);
    return res.status(500).json({ error: 'intervention_milestone_items_fetch_failed', message: err.message });
  }
});

// Payment packets/lines where evidence or payment proof is outstanding (for ISET Coordinators)
app.get('/api/dashboard/payment-proof-due-items', async (req, res) => {
  const role = inferUserRole(req) || 'Guest';
  if (role !== 'ISET Coordinator') {
    return res.json({ role, items: [] });
  }
  const context = await resolveApplicationAssessorContext(req);
  const staffId = context?.staffProfileId || null;
  if (!context?.valid || !staffId) {
    return res.json({ role, items: [] });
  }

  const normaliseStatusKey = (value) =>
    String(value || '').trim().toLowerCase().replace(/\s+/g, '_');

  const excludedPacketStatuses = new Set(['cancelled', 'confirmed']);
  const sql = `
    SELECT
      pp.id AS payment_packet_id,
      pp.status AS payment_packet_status,
      pp.updated_at AS payment_packet_updated_at,
      pp.case_id,
      c.case_number,
c.assigned_staff_profile_id AS assigned_to_user_id,
      a.id AS application_id,
      JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.submission_snapshot.reference_number')) AS tracking_id,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$."first-name"')) AS submission_first_name,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$."last-name"')) AS submission_last_name,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$."preferred-name"')) AS submission_preferred_name,
      JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$."address-province"')) AS submission_address_province,
      ppl.id AS payment_packet_line_id,
      ppl.status AS payment_line_status,
      ppl.payment_type,
      ppl.payee_type,
      ppl.amount,
      ppl.paid_at,
      ppl.payment_reference,
      ppl.payment_proof_document_id,
      ppl.intervention_id,
      ci.intervention_code,
      ic.label AS intervention_label,
      JSON_UNQUOTE(JSON_EXTRACT(ci.metadata_json, '$.title')) AS intervention_title
    FROM payment_packet pp
    JOIN iset_case c ON c.id = pp.case_id
    JOIN payment_packet_line ppl ON ppl.payment_packet_id = pp.id AND ppl.status <> 'cancelled'
    LEFT JOIN iset_case_intervention ci ON ci.id = ppl.intervention_id
    LEFT JOIN esdc_intervention_code ic ON ic.code = ci.intervention_code
    ${buildCasePrimaryApplicationJoinSql('c', 'a')}
    LEFT JOIN iset_application_submission s ON s.id = a.submission_id
    WHERE c.assigned_staff_profile_id = ?
    ORDER BY COALESCE(pp.updated_at, pp.created_at) DESC, pp.id DESC, ppl.id ASC
    LIMIT 300
  `;

  try {
    const [rows] = await pool.query(sql, [staffId]);
    const packetRows = Array.isArray(rows) ? rows : [];
    const packetMap = new Map();
    packetRows.forEach(row => {
      const packetId = row?.payment_packet_id ? Number(row.payment_packet_id) : null;
      if (!Number.isFinite(packetId) || packetId <= 0) return;
      const statusKey = normaliseStatusKey(row.payment_packet_status);
      if (statusKey && excludedPacketStatuses.has(statusKey)) return;
      let entry = packetMap.get(packetId);
      if (!entry) {
        const preferred = normaliseString(row.submission_preferred_name);
        const first = normaliseString(row.submission_first_name);
        const last = normaliseString(row.submission_last_name);
        const full = [first, last].filter(Boolean).join(' ').trim();
        const applicantName = full || preferred || normaliseString(row.tracking_id) || 'Applicant';
        entry = {
          packetId,
          packetStatus: row.payment_packet_status || null,
          caseId: row.case_id || null,
          applicationId: row.application_id || null,
          trackingId: row.tracking_id || null,
          applicantName,
          address_province: normaliseString(row.submission_address_province) || null,
          updatedAt: row.payment_packet_updated_at ? new Date(row.payment_packet_updated_at).toISOString() : null,
          lines: []
        };
        packetMap.set(packetId, entry);
      }
      entry.lines.push({
        lineId: row.payment_packet_line_id || null,
        status: row.payment_line_status || null,
        paymentType: row.payment_type || null,
        payeeType: row.payee_type || null,
        amount: row.amount ?? null,
        paidAt: row.paid_at ? new Date(row.paid_at).toISOString() : null,
        paymentReference: row.payment_reference || null,
        paymentProofDocumentId: row.payment_proof_document_id || null,
        interventionId: row.intervention_id || null,
        intervention_code: row.intervention_code || null,
        intervention_label: normaliseString(row.intervention_label) || normaliseString(row.intervention_title) || null
      });
    });

    const packetIds = Array.from(packetMap.keys()).slice(0, 120);
    const missingByPacket = new Map();
    for (const packetId of packetIds) {
      try {
        // Uses the same evidence rules as the finance gates. We treat missing evidence as "proof due".
        const missing = await fetchMissingRequiredEvidence({ packetId, connection: pool });
        missingByPacket.set(packetId, Array.isArray(missing) ? missing : []);
      } catch (_) {
        missingByPacket.set(packetId, []);
      }
    }

    const items = [];
    for (const packetId of packetIds) {
      const packet = packetMap.get(packetId);
      if (!packet) continue;
      const missing = missingByPacket.get(packetId) || [];

      const baselineMissing = missing
        .filter(m => !m?.lineId && m?.evidenceType)
        .map(m => String(m.evidenceType))
        .filter(Boolean);
      if (baselineMissing.length) {
        items.push({
          packetId: String(packetId),
          packetStatus: packet.packetStatus || null,
          caseId: packet.caseId || null,
          applicationId: packet.applicationId || null,
          trackingId: packet.trackingId || null,
          applicantName: packet.applicantName,
          applicant_name: packet.applicantName,
          address_province: packet.address_province,
          updatedAt: packet.updatedAt || null,
          lineId: null,
          kind: 'baseline_evidence_missing',
          missingEvidence: baselineMissing
        });
      }

      const missingByLine = new Map();
      missing
        .filter(m => m?.lineId && m?.evidenceType)
        .forEach(m => {
          const key = String(m.lineId);
          const list = missingByLine.get(key) || [];
          list.push(String(m.evidenceType));
          missingByLine.set(key, list);
        });

      (packet.lines || []).forEach(line => {
        const lineId = line?.lineId ? String(line.lineId) : null;
        const evidenceMissing = lineId ? (missingByLine.get(lineId) || []) : [];
        const proofMissing = normaliseStatusKey(line?.status) === 'paid' && !line?.paymentProofDocumentId;
        if (!evidenceMissing.length && !proofMissing) return;
        items.push({
          packetId: String(packetId),
          packetStatus: packet.packetStatus || null,
          caseId: packet.caseId || null,
          applicationId: packet.applicationId || null,
          trackingId: packet.trackingId || null,
          applicantName: packet.applicantName,
          applicant_name: packet.applicantName,
          address_province: packet.address_province,
          updatedAt: packet.updatedAt || null,
          lineId: lineId,
          paymentType: line?.paymentType || null,
          lineStatus: line?.status || null,
          intervention_label: line?.intervention_label || null,
          kind: proofMissing ? 'payment_proof_missing' : 'evidence_missing',
          missingEvidence: evidenceMissing,
        });
      });
    }

    return res.json({ role, items });
  } catch (err) {
    if (err && (err.code === 'ER_NO_SUCH_TABLE' || err.code === 'ER_BAD_FIELD_ERROR')) {
      return res.json({ role, items: [] });
    }
    console.error('[payment-proof-due-items] fetch failed:', err.message);
    return res.status(500).json({ error: 'payment_proof_due_items_fetch_failed', message: err.message });
  }
});

// Homepage metrics (activity snapshot)
app.get('/api/dashboard/metrics', async (req, res) => {
  const role = inferUserRole(req) || 'Guest';
  if (role === 'System Administrator') {
    return res.json({ role, periods: {} });
  }
  try {
    const context = await resolveMetricsScope(req, role);
    const timeZone = await resolveMetricsTimezone(context.timeZoneRegionId);
    const periods = buildMetricsPeriods(timeZone);
    if (!context.valid) {
      return res.json({
        role,
        timeZone,
        scope: context.scope,
        generatedAt: new Date().toISOString(),
        periods: buildEmptyMetricsPeriods(periods)
      });
    }

    const activeCases = await countMetricsActiveCases(pool, context.scope);
    const periodKeys = Object.keys(periods);
    const results = await Promise.all(periodKeys.map(async key => {
      const period = periods[key];
      const start = formatDateTimeForSql(period.startUtc);
      const end = formatDateTimeForSql(period.endUtc);
      const [
        newApplications,
        applicationStatusBuckets,
        actionPlansStarted,
        newInterventionProposals,
        interventionsCompleted,
        actionPlanOutcomeBuckets,
        fundsApproved,
        fundsCommitted,
        fundsActual
      ] = await Promise.all([
        safeMetricsValue('newApplications', () => countMetricsNewApplications(pool, { start, end, scope: context.scope })),
        safeMetricsValue(
          'applicationStatusBuckets',
          () => countMetricsApplicationStatusBuckets(pool, { start, end, scope: context.scope }),
          { approved: 0, denied: 0, inReview: 0, awaitingApproval: 0 }
        ),
        safeMetricsValue('actionPlansStarted', () => countMetricsActionPlanStarts(pool, { start, end, scope: context.scope })),
        safeMetricsValue(
          'newInterventionProposals',
          () => countMetricsNewInterventionProposals(pool, { start, end, scope: context.scope })
        ),
        safeMetricsValue(
          'interventionsCompleted',
          () => countMetricsCompletedInterventions(pool, { start, end, scope: context.scope })
        ),
        safeMetricsValue(
          'actionPlanOutcomeBuckets',
          () => countMetricsActionPlanOutcomeBuckets(pool, { start, end, scope: context.scope }),
          { employed: 0, returnedToSchool: 0 }
        ),
        safeMetricsValue(
          'fundsApproved',
          () => sumMetricsApprovedInterventionAmounts(pool, { start, end, scope: context.scope })
        ),
        safeMetricsValue(
          'fundsCommitted',
          () => sumMetricsTransactions(pool, { start, end, scope: context.scope, statuses: METRICS_COMMITTED_TRANSACTION_STATUSES })
        ),
        safeMetricsValue(
          'fundsActual',
          () => sumMetricsTransactions(pool, { start, end, scope: context.scope, statuses: METRICS_ACTUAL_TRANSACTION_STATUSES })
        )
      ]);
      const approved = Number(applicationStatusBuckets?.approved ?? 0);
      const denied = Number(applicationStatusBuckets?.denied ?? 0);
      return {
        key,
        value: {
          label: period.label,
          startLocal: period.startLocal,
          endLocal: period.endLocal,
          rangeLabel: period.rangeLabel,
          metrics: {
            newApplications,
            approved,
            denied,
            inReview: Number(applicationStatusBuckets?.inReview ?? 0),
            awaitingApproval: Number(applicationStatusBuckets?.awaitingApproval ?? 0),
            activeCases,
            actionPlansStarted,
            newInterventionProposals,
            interventionsCompleted,
            employed: Number(actionPlanOutcomeBuckets?.employed ?? 0),
            returnedToSchool: Number(actionPlanOutcomeBuckets?.returnedToSchool ?? 0),
            fundsApproved,
            fundsCommitted,
            fundsActual,
            decisionsMade: approved + denied,
          }
        }
      };
    }));

    const periodPayload = {};
    results.forEach(entry => {
      periodPayload[entry.key] = entry.value;
    });
    res.set('Cache-Control', 'no-store, max-age=0');
    return res.json({
      role,
      timeZone,
      scope: context.scope,
      generatedAt: new Date().toISOString(),
      periods: periodPayload
    });
  } catch (err) {
    console.error('[dashboard-metrics] fetch failed:', err.message);
    return res.status(500).json({ error: 'dashboard_metrics_fetch_failed', message: err.message });
  }
});

app.get('/api/dashboard/metrics/details', async (req, res) => {
  const role = inferUserRole(req) || 'Guest';
  if (role === 'System Administrator') {
    return res.json({ role, items: [] });
  }

  const metricId = normaliseString(req.query?.metricId) || null;
  const periodKey = normaliseString(req.query?.period) || 'week';
  const definition = metricId ? METRICS_DRILLDOWN_DEFINITIONS[metricId] : null;

  if (!definition) {
    return res.status(400).json({
      error: 'invalid_metric_id',
      message: 'Unsupported metric drilldown requested.'
    });
  }

  try {
    const context = await resolveMetricsScope(req, role);
    const timeZone = await resolveMetricsTimezone(context.timeZoneRegionId);
    const periods = buildMetricsPeriods(timeZone);
    const period = periods[periodKey];

    if (!period) {
      return res.status(400).json({
        error: 'invalid_period',
        message: 'Unsupported metrics period requested.'
      });
    }

    const responseBase = {
      role,
      timeZone,
      scope: context.scope,
      generatedAt: new Date().toISOString(),
      metricId,
      metricLabel: definition.label,
      columnPreset: definition.columnPreset || 'metric-applications',
      subjectLabel: definition.subjectLabel || null,
      eventDateLabel: definition.eventDateLabel || null,
      periodIndependent: Boolean(definition.periodIndependent),
      scopeNote: definition.scopeNote || null,
      period: {
        key: periodKey,
        label: period.label,
        rangeLabel: period.rangeLabel,
        startLocal: period.startLocal,
        endLocal: period.endLocal
      }
    };

    if (!context.valid) {
      res.set('Cache-Control', 'no-store, max-age=0');
      return res.json({
        ...responseBase,
        truncated: false,
        items: []
      });
    }

    const start = formatDateTimeForSql(period.startUtc);
    const end = formatDateTimeForSql(period.endUtc);
    const result = await definition.load({
      pool,
      start,
      end,
      scope: context.scope,
      periodKey,
      period,
      timeZone
    });

    res.set('Cache-Control', 'no-store, max-age=0');
    return res.json({
      ...responseBase,
      truncated: Boolean(result?.truncated),
      items: Array.isArray(result?.items) ? result.items : []
    });
  } catch (err) {
    console.error('[dashboard-metrics-details] fetch failed:', err.message);
    return res.status(500).json({
      error: 'dashboard_metrics_details_fetch_failed',
      message: err.message
    });
  }
});


