const REMINDER_ALLOWED_STATUSES = new Set(['open', 'completed', 'cancelled']);
const REMINDER_METADATA_ERROR = 'ERR_INVALID_REMINDER_METADATA';
const REMINDER_DATE_ERROR = 'ERR_INVALID_REMINDER_DATE';

const coerceOptionalPositiveInt = (value) => {
  if (typeof value === 'undefined') return undefined;
  if (value === null) return null;
  const token = typeof value === 'string' ? value.trim() : value;
  if (token === '') return null;
  const numeric = Number(token);
  if (!Number.isFinite(numeric)) return Number.NaN;
  const intValue = Math.trunc(numeric);
  if (!Number.isInteger(intValue) || intValue <= 0) return Number.NaN;
  return intValue;
};

const coerceOptionalNonNegativeInt = (value) => {
  if (typeof value === 'undefined') return undefined;
  if (value === null) return null;
  const token = typeof value === 'string' ? value.trim() : value;
  if (token === '') return null;
  const numeric = Number(token);
  if (!Number.isFinite(numeric)) return Number.NaN;
  const intValue = Math.trunc(numeric);
  if (!Number.isInteger(intValue) || intValue < 0) return Number.NaN;
  return intValue;
};

const parseBooleanFlag = (value, defaultValue = false) => {
  if (typeof value === 'undefined') return defaultValue;
  if (value === null) return false;
  const token = String(value).trim().toLowerCase();
  if (!token) return false;
  if (token === '1' || token === 'true' || token === 'yes' || token === 'y' || token === 'on') return true;
  if (token === '0' || token === 'false' || token === 'no' || token === 'n' || token === 'off') return false;
  return defaultValue;
};

const hasOwn = (obj, key) => Object.prototype.hasOwnProperty.call(obj, key);

const normaliseReminderStatus = (value, fallback = 'open', options = {}) => {
  const { allowAll = false } = options;
  if (value === undefined || value === null) return fallback;
  const token = String(value).trim().toLowerCase();
  if (!token) return fallback;
  if (token === 'all') {
    return allowAll ? null : undefined;
  }
  return REMINDER_ALLOWED_STATUSES.has(token) ? token : undefined;
};

const parseReminderDateInput = (value, fieldName = null) => {
  if (typeof value === 'undefined') return undefined;
  if (value === null) return null;
  if (typeof value === 'string' && value.trim() === '') return null;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    const match = trimmed.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (match) {
      const [, year, month, day] = match;
      const utcMs = Date.UTC(Number(year), Number(month) - 1, Number(day), 12, 0, 0, 0);
      const date = new Date(utcMs);
      if (!Number.isNaN(date.getTime())) {
        return date;
      }
    }
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    const err = new Error('invalid_date');
    err.code = REMINDER_DATE_ERROR;
    if (fieldName) err.field = fieldName;
    throw err;
  }
  return date;
};

const encodeReminderMetadataValue = (value) => {
  if (typeof value === 'undefined') return undefined;
  if (value === null) return null;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return null;
    try {
      JSON.parse(trimmed);
      return trimmed;
    } catch {
      return JSON.stringify(trimmed);
    }
  }
  try {
    return JSON.stringify(value);
  } catch (err) {
    const metadataError = new Error('invalid_metadata');
    metadataError.code = REMINDER_METADATA_ERROR;
    throw metadataError;
  }
};

const resolveReminderMetadataInput = (body = {}) => {
  if (Object.prototype.hasOwnProperty.call(body, 'metadata')) {
    return encodeReminderMetadataValue(body.metadata);
  }
  if (Object.prototype.hasOwnProperty.call(body, 'metadataJson')) {
    const value = body.metadataJson;
    if (value === null) return null;
    if (typeof value !== 'string') {
      const err = new Error('invalid_metadata');
      err.code = REMINDER_METADATA_ERROR;
      throw err;
    }
    const trimmed = value.trim();
    if (!trimmed) return null;
    try {
      JSON.parse(trimmed);
      return trimmed;
    } catch {
      const err = new Error('invalid_metadata');
      err.code = REMINDER_METADATA_ERROR;
      throw err;
    }
  }
  return undefined;
};

const mapReminderStaffProfile = (row, prefix) => {
  if (!row) return null;
  const idKey = `${prefix}_staff_profile_id`;
  const id = row[idKey] || null;
  if (!id) return null;
  return {
    staffProfileId: id,
    displayName: row[`${prefix}_display_name`] || row[`${prefix}_name`] || null,
    name: row[`${prefix}_name`] || null,
    role: row[`${prefix}_role`] || null,
    email: row[`${prefix}_email`] || null
  };
};

const REMINDER_SELECT = `
  SELECT
    r.id,
    r.case_id,
    r.application_id,
    r.action_plan_id,
    r.intervention_id,
    r.title,
    r.description,
    r.category,
    r.status,
    r.due_at,
    r.completed_at,
    r.completed_by_staff_profile_id,
    r.assigned_staff_profile_id,
    r.metadata_json,
    r.created_at,
    r.created_by_staff_profile_id,
    r.updated_at,
    r.updated_by_staff_profile_id,
    r.deleted_at,
    assigned.display_name AS assigned_display_name,
    assigned.name AS assigned_name,
    assigned.primary_role AS assigned_role,
    assigned.email AS assigned_email,
    completed.display_name AS completed_by_display_name,
    completed.name AS completed_by_name,
    completed.primary_role AS completed_by_role,
    completed.email AS completed_by_email,
    created.display_name AS created_by_display_name,
    created.name AS created_by_name,
    created.primary_role AS created_by_role,
    created.email AS created_by_email,
    updated.display_name AS updated_by_display_name,
    updated.name AS updated_by_name,
    updated.primary_role AS updated_by_role,
    updated.email AS updated_by_email
  FROM iset_case_reminder r
  LEFT JOIN staff_profiles assigned ON assigned.id = r.assigned_staff_profile_id
  LEFT JOIN staff_profiles completed ON completed.id = r.completed_by_staff_profile_id
  LEFT JOIN staff_profiles created ON created.id = r.created_by_staff_profile_id
  LEFT JOIN staff_profiles updated ON updated.id = r.updated_by_staff_profile_id`;

const mapReminderRow = (row = {}) => {
  if (!row || Object.keys(row).length === 0) return null;
  return {
    id: row.id,
    caseId: row.case_id || null,
    applicationId: row.application_id || null,
    actionPlanId: row.action_plan_id || null,
    interventionId: row.intervention_id || null,
    title: row.title,
    description: row.description || null,
    category: row.category || null,
    status: row.status,
    dueAt: row.due_at || null,
    completedAt: row.completed_at || null,
    completedByStaffProfileId: row.completed_by_staff_profile_id || null,
    assignedStaffProfileId: row.assigned_staff_profile_id || null,
    metadata: safeJsonParse(row.metadata_json, null),
    createdAt: row.created_at || null,
    createdByStaffProfileId: row.created_by_staff_profile_id || null,
    updatedAt: row.updated_at || null,
    updatedByStaffProfileId: row.updated_by_staff_profile_id || null,
    deletedAt: row.deleted_at || null,
    assignedTo: mapReminderStaffProfile(row, 'assigned'),
    completedBy: mapReminderStaffProfile(row, 'completed_by'),
    createdBy: mapReminderStaffProfile(row, 'created_by'),
    updatedBy: mapReminderStaffProfile(row, 'updated_by')
  };
};

const fetchReminderById = async (reminderId) => {
  const sql = `${REMINDER_SELECT}\n WHERE r.id = ? AND r.deleted_at IS NULL\n LIMIT 1`;
  const [rows] = await pool.query(sql, [reminderId]);
  return rows.length ? mapReminderRow(rows[0]) : null;
};

async function validateReminderTargetAccess(req, {
  caseId = null,
  applicationId = null,
  actionPlanId = null,
  interventionId = null,
  allowGlobal = false,
  connection = pool,
} = {}) {
  const normalizedCaseId = normalisePositiveInteger(caseId);
  const normalizedApplicationId = normalisePositiveInteger(applicationId);
  const normalizedActionPlanId = normalisePositiveInteger(actionPlanId);
  const normalizedInterventionId = normalisePositiveInteger(interventionId);

  let hasScopedTarget = false;
  if (normalizedInterventionId) {
    hasScopedTarget = true;
    const accessError = await validateCaseAccessByInterventionId(req, normalizedInterventionId, connection);
    if (accessError) return accessError;
  }
  if (normalizedActionPlanId) {
    hasScopedTarget = true;
    const accessError = await validateCaseAccessByActionPlanId(req, normalizedActionPlanId, connection);
    if (accessError) return accessError;
  }
  if (normalizedCaseId) {
    hasScopedTarget = true;
    const accessError = await validateCaseAccessByCaseId(req, normalizedCaseId, connection);
    if (accessError) return accessError;
  }
  if (normalizedApplicationId) {
    hasScopedTarget = true;
    const accessError = await validateCaseAccessByApplicationId(req, normalizedApplicationId, connection);
    if (accessError) return accessError;
  }
  if (hasScopedTarget) {
    return null;
  }
  if (allowGlobal && hasSystemOrNwacAdminAccess(req)) {
    return null;
  }
  return { status: allowGlobal ? 403 : 400, body: { error: allowGlobal ? 'forbidden' : 'case_or_application_scope_required' } };
}

async function validateReminderAccess(req, reminder, { allowGlobal = false, connection = pool } = {}) {
  if (!reminder) {
    return { status: 404, body: { error: 'reminder_not_found' } };
  }
  return validateReminderTargetAccess(req, {
    caseId: reminder.caseId ?? reminder.case_id ?? null,
    applicationId: reminder.applicationId ?? reminder.application_id ?? null,
    actionPlanId: reminder.actionPlanId ?? reminder.action_plan_id ?? null,
    interventionId: reminder.interventionId ?? reminder.intervention_id ?? null,
    allowGlobal,
    connection,
  });
}

const emitReminderEvent = async ({ type, reminder, actorId, actorName }) => {
  if (!reminder || !reminder.caseId) return;
  const payload = {
    reminder_id: reminder.id,
    title: reminder.title || null,
    description: reminder.description || null,
    category: reminder.category || null,
    status: reminder.status || null,
    due_at: reminder.dueAt || null,
    completed_at: reminder.completedAt || null,
    overdue_days: reminder.daysOverdue || null,
    assigned_staff_profile_id: reminder.assignedStaffProfileId || null,
  };
  await captureCaseEvent({
    type,
    caseId: reminder.caseId,
    payload,
    trackingId: reminder.applicationId || null,
    actorId: actorId || null,
    actorName: actorName || null,
  });
};

const updateReminderMetadata = async (reminderId, metadata) => {
  const encoded = metadata ? JSON.stringify(metadata) : null;
  await pool.query(
    'UPDATE iset_case_reminder SET metadata_json = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ? AND deleted_at IS NULL',
    [encoded, reminderId]
  );
};

const mapReminderMetadata = (row) => {
  if (!row) return {};
  const meta = safeJsonParse(row.metadata_json, {});
  return meta && typeof meta === 'object' ? meta : {};
};

const clearReminderEmissionMetadata = (metadata) => {
  if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) {
    return metadata ?? null;
  }
  const next = { ...metadata };
  delete next.due_emitted;
  delete next.overdue_emitted;
  delete next.overdue_days_on_emit;
  return next;
};

const MS_PER_HOUR = 60 * 60 * 1000;
const MS_PER_DAY = 24 * MS_PER_HOUR;

function pollRemindersForDue() {
  return (async () => {
  const now = new Date();
  const todayBusinessDay = getReminderBusinessDayStamp(now);
  let rows = [];
  try {
    const [result] = await pool.query(
      `SELECT id, case_id, application_id, title, description, category, status, due_at, metadata_json
         FROM iset_case_reminder
        WHERE deleted_at IS NULL
          AND status = 'open'
          AND due_at IS NOT NULL
        LIMIT 500`
    );
    rows = result || [];
  } catch (err) {
    if (isMissingTableErrorLocal(err)) {
      return;
    }
    console.warn('[reminders] due poll failed', err?.message || err);
    return;
  }

  for (const row of rows) {
    const reminder = {
      id: row.id,
      caseId: row.case_id || null,
      applicationId: row.application_id || null,
      title: row.title || null,
      description: row.description || null,
      category: row.category || null,
      status: row.status || null,
      dueAt: row.due_at || null,
      metadata: mapReminderMetadata(row),
    };
    const meta = reminder.metadata || {};
    const dueAt = reminder.dueAt ? new Date(reminder.dueAt) : null;
    if (!dueAt || Number.isNaN(dueAt.getTime())) continue;
    const dueBusinessDay = getReminderBusinessDayStamp(dueAt);
    if (dueBusinessDay === null || todayBusinessDay === null) continue;

    const dueEmitted = meta.due_emitted === true;
    const overdueEmitted = meta.overdue_emitted === true;

    if (!dueEmitted && dueBusinessDay === todayBusinessDay) {
      try {
        await emitReminderEvent({ type: 'reminder_due', reminder, actorId: null, actorName: null });
        meta.due_emitted = true;
        await updateReminderMetadata(reminder.id, meta);
      } catch (eventErr) {
        console.warn('[reminders] failed to emit reminder_due', eventErr?.message || eventErr);
      }
      continue;
    }

    if (!overdueEmitted && dueBusinessDay < todayBusinessDay) {
      const daysOverdue = Math.max(1, getReminderBusinessDayDiffDays(dueAt, now) || 0);
      reminder.daysOverdue = daysOverdue;
      try {
        await emitReminderEvent({ type: 'reminder_overdue', reminder, actorId: null, actorName: null });
        meta.overdue_emitted = true;
        meta.overdue_days_on_emit = daysOverdue;
        await updateReminderMetadata(reminder.id, meta);
      } catch (eventErr) {
        console.warn('[reminders] failed to emit reminder_overdue', eventErr?.message || eventErr);
      }
    }
  }
  })();
}

const DOC_REQUEST_EVENT_TYPES = Object.freeze({
  reminder: 'document_request_reminder_due',
  closure: 'document_request_closure_due',
});

const DOC_REQUEST_STAGE_KEYS = Object.freeze({
  reminder: 'docs_request_reminder',
  closure: 'docs_request_closure',
});

const DOC_REQUEST_DEFAULT_HOURS = Object.freeze({
  reminder: 7 * 24,
  closure: 28 * 24,
});

const normaliseThresholdHours = (value, fallback) => {
  const numeric = Number(value);
  if (!Number.isFinite(numeric) || numeric < 0) return fallback;
  return Math.round(numeric);
};

const loadDocRequestThresholds = async () => {
  try {
    const targets = await fetchActiveSlaTargets(pool);
    const byKey = new Map();
    (targets || []).forEach(target => {
      if (target?.stage_key) byKey.set(target.stage_key, target);
    });
    const reminderHours = normaliseThresholdHours(
      byKey.get(DOC_REQUEST_STAGE_KEYS.reminder)?.target_hours,
      DOC_REQUEST_DEFAULT_HOURS.reminder
    );
    const closureHours = normaliseThresholdHours(
      byKey.get(DOC_REQUEST_STAGE_KEYS.closure)?.target_hours,
      DOC_REQUEST_DEFAULT_HOURS.closure
    );
    return { reminderHours, closureHours };
  } catch (err) {
    if (!isMissingTableErrorLocal(err)) {
      console.warn('[doc-requests] SLA target lookup failed', err?.message || err);
    }
    return {
      reminderHours: DOC_REQUEST_DEFAULT_HOURS.reminder,
      closureHours: DOC_REQUEST_DEFAULT_HOURS.closure,
    };
  }
};

const buildDocRequestPayload = ({
  caseId,
  applicationId,
  trackingId,
  docsRequestedAt,
  docsRequestedSource,
  thresholdHours,
  hoursSinceRequested,
  message,
}) => {
  const dueAt = docsRequestedAt
    ? new Date(new Date(docsRequestedAt).getTime() + thresholdHours * MS_PER_HOUR)
    : null;
  const hoursSince = Math.max(0, Math.floor(hoursSinceRequested));
  const daysSince = Math.floor(hoursSince / 24);
  return {
    tracking_id: trackingId || null,
    application_id: applicationId || null,
    case_id: caseId || null,
    docs_requested_at: toIsoDateTime(docsRequestedAt),
    source: docsRequestedSource || null,
    threshold_hours: thresholdHours,
    threshold_days: Math.floor(thresholdHours / 24),
    hours_since_requested: hoursSince,
    days_since_requested: daysSince,
    due_at: toIsoDateTime(dueAt),
    message,
  };
};

function pollDocsRequestedThresholds() {
  return (async () => {
    const { reminderHours, closureHours } = await loadDocRequestThresholds();
    const now = new Date();
    let rows = [];

    try {
      const [result] = await pool.query(
        `SELECT
            c.id AS case_id,
            a.id AS application_id,
            a.docs_requested_at,
            a.docs_requested_source,
            JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.submission_snapshot.reference_number')) AS tracking_id,
            EXISTS(
              SELECT 1
                FROM iset_event_entry e_reminder
               WHERE e_reminder.subject_type = 'case'
                 AND e_reminder.subject_id = CAST(c.id AS CHAR)
                 AND e_reminder.event_type = ?
                 AND e_reminder.captured_at >= a.docs_requested_at
               LIMIT 1
            ) AS reminder_emitted,
            EXISTS(
              SELECT 1
                FROM iset_event_entry e_closure
               WHERE e_closure.subject_type = 'case'
                 AND e_closure.subject_id = CAST(c.id AS CHAR)
                 AND e_closure.event_type = ?
                 AND e_closure.captured_at >= a.docs_requested_at
               LIMIT 1
            ) AS closure_emitted
          FROM iset_application a
          JOIN iset_case c ON ${APPLICATION_CASE_JOIN_PREDICATE}
         WHERE a.docs_requested_active = 1
           AND a.docs_requested_at IS NOT NULL
         LIMIT 500`,
        [
          DOC_REQUEST_EVENT_TYPES.reminder,
          DOC_REQUEST_EVENT_TYPES.closure
        ]
      );
      rows = result || [];
    } catch (err) {
      if (isMissingTableErrorLocal(err)) {
        return;
      }
      console.warn('[doc-requests] threshold poll failed', err?.message || err);
      return;
    }

    for (const row of rows) {
      const caseId = Number(row.case_id);
      if (!Number.isFinite(caseId)) continue;
      const applicationId = Number(row.application_id) || null;
      const docsRequestedAt = row.docs_requested_at || null;
      const docsRequestedSource = row.docs_requested_source || null;
      const trackingId = row.tracking_id || `CASE-${caseId}`;

      if (!docsRequestedAt) continue;
      const requestedDate = docsRequestedAt instanceof Date ? docsRequestedAt : new Date(docsRequestedAt);
      if (Number.isNaN(requestedDate.getTime())) continue;

      const hoursSinceRequested = (now.getTime() - requestedDate.getTime()) / MS_PER_HOUR;
      if (!Number.isFinite(hoursSinceRequested) || hoursSinceRequested < 0) continue;

      if (
        Number.isFinite(reminderHours) &&
        hoursSinceRequested >= reminderHours &&
        Number(row.reminder_emitted || 0) === 0
      ) {
        try {
          await captureCaseEvent({
            type: DOC_REQUEST_EVENT_TYPES.reminder,
            caseId,
            payload: buildDocRequestPayload({
              caseId,
              applicationId,
              trackingId,
              docsRequestedAt: requestedDate,
              docsRequestedSource,
              thresholdHours: reminderHours,
              hoursSinceRequested,
              message: 'Document request reminder due'
            }),
            trackingId,
            actorId: null,
            actorName: null,
            actorType: 'system',
          });
        } catch (eventErr) {
          console.warn('[doc-requests] failed to emit reminder due', eventErr?.message || eventErr);
        }
      }

      if (
        Number.isFinite(closureHours) &&
        hoursSinceRequested >= closureHours &&
        Number(row.closure_emitted || 0) === 0
      ) {
        try {
          await captureCaseEvent({
            type: DOC_REQUEST_EVENT_TYPES.closure,
            caseId,
            payload: buildDocRequestPayload({
              caseId,
              applicationId,
              trackingId,
              docsRequestedAt: requestedDate,
              docsRequestedSource,
              thresholdHours: closureHours,
              hoursSinceRequested,
              message: 'Document request closure due'
            }),
            trackingId,
            actorId: null,
            actorName: null,
            actorType: 'system',
          });
        } catch (eventErr) {
          console.warn('[doc-requests] failed to emit closure due', eventErr?.message || eventErr);
        }
      }
    }
  })();
}

const DOC_REQUEST_REMINDER_CATEGORY = 'Docs requested';
const DOC_REQUEST_REMINDER_SOURCE = 'docs_requested';
const DOC_REQUEST_REMINDER_KINDS = Object.freeze({
  reminder: 'reminder',
  closure: 'closure',
});
const DOC_REQUEST_REMINDER_TITLES = Object.freeze({
  reminder: 'Docs requested reminder',
  closure: 'Docs requested closure',
});

const formatDocRequestThresholdLabel = (thresholdHours) => {
  if (!Number.isFinite(thresholdHours) || thresholdHours < 0) return null;
  const rounded = Math.round(thresholdHours);
  if (rounded === 0) return '0 hours';
  if (rounded % 24 === 0) {
    const days = Math.floor(rounded / 24);
    return `${days} day${days === 1 ? '' : 's'}`;
  }
  return `${rounded} hour${rounded === 1 ? '' : 's'}`;
};

const formatDocRequestReminderDescription = ({ kind, thresholdHours }) => {
  const thresholdLabel = formatDocRequestThresholdLabel(thresholdHours);
  if (!thresholdLabel) return null;
  const label = kind === DOC_REQUEST_REMINDER_KINDS.closure ? 'closure' : 'reminder';
  return `Docs requested ${label} due ${thresholdLabel} after documents were requested.`;
};

const buildDocRequestReminderMetadata = ({ kind, docsRequestedAt, docsRequestedSource, thresholdHours }) =>
  JSON.stringify({
    source: DOC_REQUEST_REMINDER_SOURCE,
    kind,
    docs_requested_at: toIsoDateTime(docsRequestedAt),
    docs_requested_source: docsRequestedSource || null,
    threshold_hours: thresholdHours,
    threshold_days: Math.floor(Number(thresholdHours || 0) / 24),
  });

const fetchDocRequestReminders = async (caseId) => {
  const [rows] = await pool.query(
    `SELECT id,
            status,
            JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.kind')) AS kind
       FROM iset_case_reminder
      WHERE case_id = ?
        AND deleted_at IS NULL
        AND status = 'open'
        AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.source')) = ?`,
    [caseId, DOC_REQUEST_REMINDER_SOURCE]
  );
  return rows || [];
};

const upsertDocRequestReminders = async ({
  caseId,
  applicationId,
  docsRequestedAt,
  docsRequestedSource,
  actorStaffProfileId
}) => {
  const numericCaseId = Number(caseId);
  if (!Number.isFinite(numericCaseId) || numericCaseId <= 0) return [];
  if (!docsRequestedAt) return [];
  const baseDate = docsRequestedAt instanceof Date ? docsRequestedAt : new Date(docsRequestedAt);
  if (Number.isNaN(baseDate.getTime())) return [];

  let existingRows = [];
  try {
    existingRows = await fetchDocRequestReminders(numericCaseId);
  } catch (err) {
    if (isMissingTableErrorLocal(err)) return [];
    throw err;
  }
  const existingByKind = new Map();
  existingRows.forEach(row => {
    if (row?.kind) existingByKind.set(row.kind, row);
  });

  const { reminderHours, closureHours } = await loadDocRequestThresholds();
  const thresholds = [
    { kind: DOC_REQUEST_REMINDER_KINDS.reminder, hours: reminderHours, title: DOC_REQUEST_REMINDER_TITLES.reminder },
    { kind: DOC_REQUEST_REMINDER_KINDS.closure, hours: closureHours, title: DOC_REQUEST_REMINDER_TITLES.closure },
  ];
  const createdIds = [];
  const actorId = Number.isInteger(actorStaffProfileId) && actorStaffProfileId > 0 ? actorStaffProfileId : null;
  const applicationIdValue = Number.isFinite(Number(applicationId)) ? Number(applicationId) : null;

  for (const threshold of thresholds) {
    if (!Number.isFinite(threshold.hours)) continue;
    const dueAt = new Date(baseDate.getTime() + threshold.hours * MS_PER_HOUR);
    if (Number.isNaN(dueAt.getTime())) continue;
    const description = formatDocRequestReminderDescription({
      kind: threshold.kind,
      thresholdHours: threshold.hours
    });
    const metadataJson = buildDocRequestReminderMetadata({
      kind: threshold.kind,
      docsRequestedAt: baseDate,
      docsRequestedSource,
      thresholdHours: threshold.hours
    });
    const existing = existingByKind.get(threshold.kind);
    try {
      if (existing?.id) {
        await pool.query(
          `UPDATE iset_case_reminder
              SET title = ?,
                  description = ?,
                  category = ?,
                  status = 'open',
                  due_at = ?,
                  completed_at = NULL,
                  completed_by_staff_profile_id = NULL,
                  metadata_json = ?,
                  updated_at = CURRENT_TIMESTAMP,
                  updated_by_staff_profile_id = COALESCE(?, updated_by_staff_profile_id),
                  deleted_at = NULL
            WHERE id = ? AND deleted_at IS NULL`,
          [
            threshold.title,
            description,
            DOC_REQUEST_REMINDER_CATEGORY,
            dueAt,
            metadataJson,
            actorId,
            existing.id
          ]
        );
      } else {
        const [insertResult] = await pool.query(
          `INSERT INTO iset_case_reminder
            (case_id, application_id, title, description, category, status, due_at, metadata_json, created_by_staff_profile_id, updated_by_staff_profile_id)
            VALUES (?,?,?,?,?,?,?,?,?,?)`,
          [
            numericCaseId,
            applicationIdValue,
            threshold.title,
            description,
            DOC_REQUEST_REMINDER_CATEGORY,
            'open',
            dueAt,
            metadataJson,
            actorId,
            actorId
          ]
        );
        if (insertResult?.insertId) {
          createdIds.push(insertResult.insertId);
        }
      }
    } catch (err) {
      if (isMissingTableErrorLocal(err)) {
        return [];
      }
      throw err;
    }
  }

  return createdIds;
};

const cancelDocRequestReminders = async ({ caseId, actorStaffProfileId }) => {
  const numericCaseId = Number(caseId);
  if (!Number.isFinite(numericCaseId) || numericCaseId <= 0) return;
  const actorId = Number.isInteger(actorStaffProfileId) && actorStaffProfileId > 0 ? actorStaffProfileId : null;
  try {
    await pool.query(
      `UPDATE iset_case_reminder
          SET status = 'cancelled',
              deleted_at = CURRENT_TIMESTAMP,
              updated_at = CURRENT_TIMESTAMP,
              updated_by_staff_profile_id = COALESCE(?, updated_by_staff_profile_id)
        WHERE case_id = ?
          AND deleted_at IS NULL
          AND status = 'open'
          AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json, '$.source')) = ?`,
      [actorId, numericCaseId, DOC_REQUEST_REMINDER_SOURCE]
    );
  } catch (err) {
    if (isMissingTableErrorLocal(err)) return;
    throw err;
  }
};

const setDocsRequestedFromSecureMessage = async ({
  caseId,
  applicationId,
  actorUserId = null,
  actorName = null,
  actorStaffProfileId = null
}) => {
  const numericCaseId = Number(caseId);
  const numericApplicationId = Number(applicationId);
  if (!Number.isFinite(numericCaseId) || numericCaseId <= 0) return { updated: false, reason: 'invalid_case_id' };
  if (!Number.isFinite(numericApplicationId) || numericApplicationId <= 0) return { updated: false, reason: 'invalid_application_id' };

  const [[currentRow]] = await pool.query(
    `SELECT status,
            docs_requested_active,
            docs_requested_at,
            docs_requested_cleared_at,
            docs_requested_source
       FROM iset_application
      WHERE id = ?
      LIMIT 1`,
    [numericApplicationId]
  );
  if (!currentRow) return { updated: false, reason: 'application_not_found' };

  const alreadyActive = Number(currentRow.docs_requested_active || 0) === 1;
  if (alreadyActive) {
    return { updated: false, reason: 'already_active' };
  }

  const statusKey =
    normaliseCaseStatusValue(currentRow.status) ||
    String(currentRow.status || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
  const shouldSetDocsRequestedStatus = statusKey === 'submitted' || statusKey === 'in_review';

  if (shouldSetDocsRequestedStatus) {
    await pool.query(
      `UPDATE iset_application
          SET status = 'docs_requested',
              docs_requested_active = 1,
              docs_requested_at = NOW(),
              docs_requested_cleared_at = NULL,
              docs_requested_source = 'secure_message'
        WHERE id = ?`,
      [numericApplicationId]
    );
  } else {
    await pool.query(
      `UPDATE iset_application
          SET docs_requested_active = 1,
              docs_requested_at = NOW(),
              docs_requested_cleared_at = NULL,
              docs_requested_source = 'secure_message'
        WHERE id = ?`,
      [numericApplicationId]
    );
  }

  const [[updatedRow]] = await pool.query(
    `SELECT status,
            docs_requested_active,
            docs_requested_at,
            docs_requested_cleared_at,
            docs_requested_source
       FROM iset_application
      WHERE id = ?
      LIMIT 1`,
    [numericApplicationId]
  );
  const trackingId = await fetchTrackingIdForCase(numericApplicationId, numericCaseId);
  const docsRequestedAt = updatedRow?.docs_requested_at || new Date();
  const docsRequestedSource = updatedRow?.docs_requested_source || 'secure_message';

  try {
    await captureCaseEvent({
      type: 'document_request_set',
      caseId: numericCaseId,
      actorId: actorUserId || null,
      actorName: actorName || null,
      actorStaffProfileId: Number.isFinite(Number(actorStaffProfileId)) ? Number(actorStaffProfileId) : null,
      payload: {
        tracking_id: trackingId,
        application_id: numericApplicationId,
        case_id: numericCaseId,
        docs_requested_at: toIsoDateTime(docsRequestedAt),
        docs_requested_cleared_at: null,
        source: docsRequestedSource,
        message: 'Documents requested.'
      },
      trackingId
    });
  } catch (eventErr) {
    console.warn('[doc-requests] failed to emit document_request_set', eventErr?.message || eventErr);
  }

  try {
    await upsertDocRequestReminders({
      caseId: numericCaseId,
      applicationId: numericApplicationId,
      docsRequestedAt,
      docsRequestedSource,
      actorStaffProfileId: Number.isFinite(Number(actorStaffProfileId)) ? Number(actorStaffProfileId) : null
    });
  } catch (reminderErr) {
    if (!isMissingTableErrorLocal(reminderErr)) {
      console.warn('[doc-requests] reminder sync failed', reminderErr?.message || reminderErr);
    }
  }

  return {
    updated: true,
    status: updatedRow?.status || null,
    docsRequestedAt: toIsoDateTime(docsRequestedAt),
    source: docsRequestedSource
  };
};


const listReminders = async (options = {}) => {
  const { caseId, applicationId, includeGlobal = false, statuses = [], limit, offset } = options;
  const conditions = ['r.deleted_at IS NULL'];
  const params = [];
  const scopeClauses = [];

  if (Number.isInteger(caseId) && caseId > 0) {
    scopeClauses.push('r.case_id = ?');
    params.push(caseId);
  }
  if (Number.isInteger(applicationId) && applicationId > 0) {
    scopeClauses.push('r.application_id = ?');
    params.push(applicationId);
  }
  if (includeGlobal) {
    scopeClauses.push('(r.case_id IS NULL AND r.application_id IS NULL)');
  }
  if (scopeClauses.length) {
    conditions.push(`(${scopeClauses.join(' OR ')})`);
  }
  if (Array.isArray(statuses) && statuses.length) {
    const placeholders = statuses.map(() => '?').join(',');
    conditions.push(`r.status IN (${placeholders})`);
    params.push(...statuses);
  }

  let sql = `${REMINDER_SELECT}\n`;
  if (conditions.length) {
    sql += `WHERE ${conditions.join('\n  AND ')}\n`;
  }
  sql += 'ORDER BY r.due_at IS NULL ASC, r.due_at ASC, r.id DESC';

  const limitIsValid = Number.isInteger(limit) && limit > 0;
  const offsetIsValid = Number.isInteger(offset) && offset >= 0;
  if (limitIsValid) {
    sql += ' LIMIT ?';
    params.push(limit);
    if (offsetIsValid) {
      sql += ' OFFSET ?';
      params.push(offset);
    }
  }

  const [rows] = await pool.query(sql, params);
  return rows.map(mapReminderRow);
};

const NOTE_REMINDER_CATEGORY = 'Case note follow-up';

const deriveReminderTitleFromNote = (body = '') => {
  if (!body) return 'Case follow-up';
  const text = String(body).trim();
  if (!text) return 'Case follow-up';
  const firstLine = text.split(/\r?\n/).find(line => line.trim());
  const value = (firstLine || text).trim();
  if (value.length <= 120) return value;
  return `${value.slice(0, 117)}...`;
};

const deriveReminderDescriptionFromNote = (body = '') => {
  if (!body) return null;
  const text = String(body).trim();
  if (!text) return null;
  return text.length > 2000 ? `${text.slice(0, 2000)}...` : text;
};

const buildNoteReminderMetadata = (noteId) =>
  JSON.stringify({
    source: 'case_note',
    case_note_id: noteId,
  });

const loadCaseIdentifiers = async (connection, caseId) => {
  const [[row]] = await connection.query(
    `SELECT c.id,
            a.id AS application_id
       FROM iset_case c
       ${buildCasePrimaryApplicationJoinSql('c', 'a')}
      WHERE c.id = ?
      LIMIT 1`,
    [caseId]
  );
  return row || null;
};

const createReminderForCaseNote = async (connection, { caseId, applicationId, noteId, noteBody, dueAt, staffProfileId }) => {
  if (!dueAt) return null;
  const title = deriveReminderTitleFromNote(noteBody);
  const description = deriveReminderDescriptionFromNote(noteBody);
  const metadataJson = buildNoteReminderMetadata(noteId);
  const actorId = Number.isInteger(staffProfileId) && staffProfileId > 0 ? staffProfileId : null;
  const assignedId = actorId;
  const sql = `INSERT INTO iset_case_reminder
    (case_id, application_id, title, description, category, status, due_at, assigned_staff_profile_id, metadata_json, created_by_staff_profile_id, updated_by_staff_profile_id)
    VALUES (?,?,?,?,?,?,?,?,?,?,?)`;
  const params = [
    caseId,
    applicationId ?? null,
    title,
    description,
    NOTE_REMINDER_CATEGORY,
    'open',
    dueAt,
    assignedId,
    metadataJson,
    actorId,
    actorId,
  ];
  const [result] = await connection.query(sql, params);
  return result.insertId;
};

const updateReminderForCaseNote = async (connection, reminderId, { noteId, noteBody, dueAt, staffProfileId }) => {
  if (!reminderId) return null;
  const title = deriveReminderTitleFromNote(noteBody);
  const description = deriveReminderDescriptionFromNote(noteBody);
  const metadataJson = buildNoteReminderMetadata(noteId);
  const actorId = Number.isInteger(staffProfileId) && staffProfileId > 0 ? staffProfileId : null;
  const sql = `UPDATE iset_case_reminder
    SET title = ?, description = ?, category = ?, status = 'open', due_at = ?, completed_at = NULL, completed_by_staff_profile_id = NULL,
        assigned_staff_profile_id = ?, metadata_json = ?, updated_by_staff_profile_id = ?, deleted_at = NULL, updated_at = CURRENT_TIMESTAMP
    WHERE id = ? AND deleted_at IS NULL`;
  const params = [
    title,
    description,
    NOTE_REMINDER_CATEGORY,
    dueAt,
    actorId,
    metadataJson,
    actorId,
    reminderId,
  ];
  const [result] = await connection.query(sql, params);
  if (!result.affectedRows) {
    return null;
  }
  return reminderId;
};

const cancelReminderForCaseNote = async (connection, reminderId, staffProfileId) => {
  if (!reminderId) return;
  const actorId = Number.isInteger(staffProfileId) && staffProfileId > 0 ? staffProfileId : null;
  await connection.query(
    `UPDATE iset_case_reminder
       SET status = 'cancelled',
           deleted_at = CURRENT_TIMESTAMP,
           updated_at = CURRENT_TIMESTAMP,
           updated_by_staff_profile_id = COALESCE(?, updated_by_staff_profile_id)
     WHERE id = ? AND deleted_at IS NULL`,
    [actorId, reminderId]
  );
};

