// Unified applicant documents endpoint now sources from iset_document (generalized store)
async function emitDocumentUploadedEvent({ req, caseId, applicationId, applicantUserId, fileName, source, sizeBytes, message }) {
  const normalizedCaseId = normalisePositiveInteger(caseId);
  if (!normalizedCaseId) return;
  const { actorId, actorName } = resolveRequestActor(req) || {};
  let trackingId = null;
  try {
    trackingId = await fetchTrackingIdForCase(applicationId, normalizedCaseId);
  } catch (err) {
    console.warn('[events] failed to resolve tracking id for document upload', err?.message || err);
  }
  const payload = {
    file_name: fileName || null,
    source: source || null,
    size_bytes: typeof sizeBytes === 'number' && Number.isFinite(sizeBytes) ? sizeBytes : null,
    applicant_user_id: applicantUserId || null,
    tracking_id: trackingId,
    document_type: req?.body?.documentType || req?.body?.document_type || null,
    message: message || (fileName ? `Document uploaded: ${fileName}.` : 'Document uploaded.')
  };
  try {
    await captureCaseEvent({
      type: 'document_uploaded',
      caseId: normalizedCaseId,
      payload,
      trackingId,
      actorId,
      actorName,
    });
  } catch (err) {
    console.warn('[events] document_uploaded emit failed', err?.message || err);
  }
}

function handleAdminDocumentUpload({ requireApplicant = false, applicantIdHint = null, caseIdHint = null } = {}) {
  return (req, res) => {
  adminDocumentUpload.single('file')(req, res, async err => {
    if (err) {
      const isMulterError = err instanceof multer.MulterError;
      if (err.code === 'LIMIT_FILE_SIZE' || (isMulterError && err.code === 'LIMIT_FILE_SIZE')) {
        return res.status(400).json({
          error: 'file_too_large',
          maxBytes: ADMIN_UPLOAD_MAX_BYTES
        });
      }
      if (err.code === 'UNSUPPORTED_FILE_TYPE' || err.message === 'unsupported_file_type') {
        return res.status(400).json({ error: 'unsupported_file_type' });
      }
      console.error('[admin:documents:upload] multer error', err);
      return res.status(400).json({ error: 'upload_failed', message: err.message || 'Upload failed' });
    }

    const applicantId = normalisePositiveInteger(
      applicantIdHint ||
        (requireApplicant ? req.params.id : null) ||
        req.body?.applicantUserId ||
        req.body?.applicant_user_id
    );
    const cleanupUploadedFile = () => {
      if (req.file && req.file.path) {
        fs.unlink(req.file.path, unlinkErr => {
          if (unlinkErr && unlinkErr.code !== 'ENOENT') {
            console.warn('[admin:documents:upload] cleanup failed for %s: %s', req.file.path, unlinkErr.message);
          }
        });
      }
    };

    if (requireApplicant && !applicantId) {
      cleanupUploadedFile();
      return res.status(400).json({ error: 'invalid_applicant_id' });
    }

    const file = req.file;
    if (!file) {
      return res.status(400).json({ error: 'file_required' });
    }

    const labelRaw = typeof req.body?.label === 'string' ? req.body.label.trim() : '';
    const label = labelRaw ? labelRaw.slice(0, 255) : null;
    const docTypeRaw = typeof req.body?.documentType === 'string' ? req.body.documentType.trim() : '';
    const docType = docTypeRaw || null;
    const isEiVerificationDocument = docType && docType.toLowerCase() === 'ei_verification';
    if (isEiVerificationDocument) {
      const eligibilityRoleAllowlist = new Set([
        'systemadministrator',
        'nwacadministrator',
        'regionalmanager'
      ]);
      const identity = getRequesterIdentity(req);
      const roleKeyRaw = normaliseString(identity.role);
      const roleKey = roleKeyRaw ? roleKeyRaw.toLowerCase().replace(/[\s_-]+/g, '') : '';
      if (!eligibilityRoleAllowlist.has(roleKey)) {
        cleanupUploadedFile();
        return res.status(403).json({
          error: 'ei_verification_forbidden',
          message: 'You do not have permission to upload EI verification documents.'
        });
      }
    }
    let docTypeScope = null;
    if (docType) {
      try {
        const [[docTypeRow]] = await pool.query(
          'SELECT COALESCE(scope, \"application\") AS scope FROM document_type WHERE code = ? AND is_active = 1 LIMIT 1',
          [docType]
        );
        if (!docTypeRow) {
          cleanupUploadedFile();
          return res.status(400).json({ error: 'invalid_document_type' });
        }
        docTypeScope = docTypeRow.scope || 'application';
      } catch (err) {
        cleanupUploadedFile();
        console.error('[admin:documents:upload] doc type lookup failed', err);
        return res.status(500).json({ error: 'document_type_lookup_failed' });
      }
    }
    const caseIdRaw = normalisePositiveInteger(
      caseIdHint || req.body?.caseId || req.body?.case_id || (!requireApplicant ? req.params.id : null)
    );
    const applicationIdRaw = normalisePositiveInteger(req.body?.applicationId || req.body?.application_id);
    const actionPlanIdRaw = normalisePositiveInteger(req.body?.actionPlanId || req.body?.action_plan_id);
    const interventionIdRaw = normalisePositiveInteger(req.body?.interventionId || req.body?.linkedInterventionId);
    const interventionIdsRaw = normalizeIdList(req.body?.interventionIds || req.body?.intervention_ids);
    let caseId = caseIdRaw;
    let applicationId = applicationIdRaw;
    let actionPlanId = actionPlanIdRaw;
    let interventionIds = Array.from(new Set([...interventionIdsRaw, interventionIdRaw].filter(Boolean)));
    const normalizedScope = docTypeScope || 'application';
    const metadataObj = {};
    if (label) metadataObj.label = label;
    if (docType) metadataObj.document_type = docType;

    try {
      const attachment = await resolveDocumentAttachmentContext({
        requestedScope: normalizedScope,
        caseId,
        applicationId,
        actionPlanId,
        interventionIds,
      });
      caseId = attachment.caseId;
      applicationId = attachment.applicationId;
      actionPlanId = attachment.actionPlanId;
      interventionIds = attachment.interventionIds;
      if (isEiVerificationDocument) {
        const requestedInterventionIds = Array.from(
          new Set([...interventionIdsRaw, interventionIdRaw].filter(Boolean))
        );
        if (requestedInterventionIds.length) {
          interventionIds = requestedInterventionIds;
          if (!actionPlanId) {
            actionPlanId = await resolveActionPlanIdForInterventions({
              interventionIds,
              connection: pool,
            });
          }
          if (actionPlanId) {
            interventionIds = await ensureInterventionsBelongToActionPlan({
              actionPlanId,
              interventionIds,
              connection: pool,
            });
          }
        }
        if (!actionPlanId) {
          actionPlanId = actionPlanIdRaw || null;
        }
        if (!caseId) {
          caseId = caseIdRaw || null;
          if (!caseId && actionPlanId) {
            caseId = await resolveCaseIdForActionPlan(actionPlanId, pool);
          }
        }
      }
      if (attachment.usedApplicationFallback) {
        metadataObj.scope_fallback = {
          requested: normalizedScope,
          storedAs: attachment.effectiveStorageScope,
        };
      } else if (metadataObj.scope_fallback) {
        delete metadataObj.scope_fallback;
      }

      if (requireApplicant) {
        const applicantAccessError = await validateApplicantDocumentContextAccess(req, {
          applicantId,
          caseId,
          applicationId,
          actionPlanId,
          interventionId: interventionIds[0] || null,
          requireScopedContext: true,
        });
        if (applicantAccessError) {
          cleanupUploadedFile();
          return res.status(applicantAccessError.status).json(applicantAccessError.body);
        }
      }
      const targetAccessError = await validateDocumentAttachmentContextAccess(req, {
        caseId,
        applicationId,
        actionPlanId,
        interventionIds,
        requireScopedContext: true,
      });
      if (targetAccessError) {
        cleanupUploadedFile();
        return res.status(targetAccessError.status).json(targetAccessError.body);
      }
    } catch (err) {
      cleanupUploadedFile();
      const errorCode = err?.code || 'document_link_validation_failed';
      return res.status(400).json({ error: errorCode });
    }
    const metadata = Object.keys(metadataObj).length ? JSON.stringify(metadataObj) : null;
    const source = 'manual_upload';
    const uploaderUserId = await resolveAdminActorUserId(req, pool);
    const mimeType = file.mimetype || null;
    const sizeBytes = Number.isFinite(Number(file.size)) ? Number(file.size) : null;
    const checksum = await computeFileSha256(file.path);
    const originalNameRaw = typeof file.originalname === 'string' ? file.originalname.trim() : '';
    const fileNameForDb = (originalNameRaw || file.filename || 'document').slice(0, 255);

    let relativePath = null;
    try {
      const { generateKey, presignPut, DRIVER } = require('../ISET-intake/s3Provider');
      if (DRIVER !== 's3') {
        throw new Error('s3 driver not configured');
      }
      const key = generateKey(applicantId || uploaderUserId || 'admin', originalNameRaw || fileNameForDb);
      const contentType = mimeType || 'application/octet-stream';
      const presigned = await presignPut({ key, contentType });
      await axios.put(presigned.url, fs.createReadStream(file.path), {
        headers: {
          ...(presigned.headers || {}),
          'Content-Type': contentType,
          ...(sizeBytes ? { 'Content-Length': sizeBytes } : {})
        }
      });
      relativePath = key;
      cleanupUploadedFile();
    } catch (uploadErr) {
      cleanupUploadedFile();
      console.error('[admin:documents:upload:s3] upload failed', uploadErr);
      return res.status(500).json({ error: 'object_store_upload_failed' });
    }

    let insertId = null;
    let resolvedClientId = null;
    try {
      resolvedClientId = await resolveClientIdForDocument({
        applicantUserId: applicantId,
        caseId: caseId || caseIdRaw,
        actionPlanId: actionPlanId || actionPlanIdRaw,
        applicationId: applicationId || applicationIdRaw,
      });
      if (!resolvedClientId) {
        cleanupUploadedFile();
        return res.status(422).json({ error: 'client_id_required' });
      }
    } catch (err) {
      cleanupUploadedFile();
      const errorCode = err?.code || 'client_id_resolution_failed';
      return res.status(400).json({ error: errorCode });
    }

    try {
      const insertPayload = [
        caseId,
        applicationId,
        actionPlanId,
        resolvedClientId,
        applicantId,
        uploaderUserId,
        source,
        fileNameForDb,
        relativePath,
        mimeType,
        label,
        metadata,
        sizeBytes,
        checksum,
        docType
      ];
      const [result] = await pool.query(
        `INSERT INTO iset_document
           (case_id, application_id, action_plan_id, client_id, applicant_user_id, user_id, source, file_name, file_path, mime_type, label, metadata, size_bytes, checksum_sha256, status, document_category)
         VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?, 'active', ?)
         ON DUPLICATE KEY UPDATE
           applicant_user_id = VALUES(applicant_user_id),
           application_id = VALUES(application_id),
           action_plan_id = VALUES(action_plan_id),
           case_id = VALUES(case_id),
           client_id = VALUES(client_id),
           user_id = VALUES(user_id),
           label = VALUES(label),
           metadata = VALUES(metadata),
           mime_type = VALUES(mime_type),
           size_bytes = VALUES(size_bytes),
           checksum_sha256 = VALUES(checksum_sha256),
           status = 'active',
           document_category = VALUES(document_category),
           updated_at = NOW()`,
        insertPayload
      );
      insertId = result.insertId || null;
    } catch (dbErr) {
      console.error('[admin:documents:upload] insert failed', dbErr);
      cleanupUploadedFile();
      return res.status(500).json({ error: 'document_store_failed' });
    }

    const documentIdForLinks = insertId || null;

      try {
        const lookupKey = insertId
          ? ['id = ?', [insertId]]
          : ['file_path = ?', [relativePath]];
        const [rows] = await pool.query(
        `SELECT id, case_id, application_id, action_plan_id, client_id, applicant_user_id, file_name, file_path, label, metadata, document_category, source, mime_type, size_bytes, status, created_at AS uploaded_at
           FROM iset_document
         WHERE ${lookupKey[0]}
         LIMIT 1`,
        lookupKey[1]
      );
        if (!rows || !rows.length) {
          return res.status(200).json({
            ok: true,
            message: 'uploaded',
            document: null
          });
        }
        const documentRow = rows[0];
        if (interventionIds.length) {
          documentRow.intervention_ids = interventionIds;
        }
        const resolvedDocId = documentIdForLinks || documentRow?.id || null;
        if (resolvedDocId && interventionIds.length) {
          try {
            await updateDocumentInterventionLinks({
              documentId: resolvedDocId,
              interventionIds,
            });
          } catch (linkErr) {
            console.warn('[admin:documents:upload] intervention link failed', linkErr?.message || linkErr);
          }
        }

        let resolvedCaseId = caseId || normalisePositiveInteger(documentRow?.case_id);
        if (!resolvedCaseId && documentRow?.action_plan_id) {
          resolvedCaseId = await resolveCaseIdForActionPlan(documentRow.action_plan_id);
        }
        let resolvedApplicationId = applicationId || normalisePositiveInteger(documentRow?.application_id);
        if (!resolvedApplicationId && resolvedCaseId) {
          resolvedApplicationId = await resolveApplicationIdForCaseId(resolvedCaseId);
        }

        if (resolvedCaseId) {
          await emitDocumentUploadedEvent({
            req,
            caseId: resolvedCaseId,
            applicationId: resolvedApplicationId,
            applicantUserId: applicantId,
            fileName: documentRow?.file_name || label || fileNameForDb,
            source,
            sizeBytes,
            message: `Document uploaded (${source}): ${documentRow?.file_name || fileNameForDb}.`
          });
        }

        return res.status(200).json({
          ok: true,
          message: 'uploaded',
          document: documentRow
        });
      } catch (lookupErr) {
        console.warn('[admin:documents:upload] lookup failed', lookupErr);
        return res.status(200).json({
          ok: true,
        message: 'uploaded',
        document: null
      });
    }
  });
  };
}

