async function resolveCaseApplicantMessagingContext(caseId, { applicationId = null } = {}) {
  const numericCaseId = Number.parseInt(caseId, 10);
  if (!Number.isInteger(numericCaseId) || numericCaseId < 1) {
    return null;
  }
  const requestedApplicationId = normalisePositiveInteger(applicationId);
  const applicationJoinSql = requestedApplicationId
    ? 'JOIN iset_application a ON a.case_id = c.id AND a.id = ?'
    : buildCasePrimaryApplicationJoinSql('c', 'a');

  const [[row] = []] = await pool.query(
    `SELECT
       c.id AS case_id,
       c.client_id,
       a.id AS application_id,
       c.case_number,
       c.case_context_json,
       c.status AS case_status,
       c.lifecycle_status AS case_lifecycle_status,
       a.status AS application_status,
       a.lifecycle_status AS application_lifecycle_status,
       a.decision_outcome AS decision_outcome,
       a.awaiting_reason AS application_awaiting_reason,
       a.closure_reason AS application_closure_reason,
       s.reference_number AS submission_reference,
       applicant_submission.id AS applicant_submission_user_id,
       applicant_submission_client.id AS applicant_submission_client_id,
       applicant_client_sub.id AS applicant_client_sub_user_id,
       NULLIF(CONCAT_WS(' ', NULLIF(TRIM(cl.first_name), ''), NULLIF(TRIM(cl.last_name), '')), '') AS client_name,
       NULLIF(TRIM(cl.applicant_account_email), '') AS client_email,
       COALESCE(
         applicant_submission.name,
         applicant_client_sub.name,
         JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.personal.full_name')),
         NULLIF(CONCAT_WS(' ', NULLIF(TRIM(cl.first_name), ''), NULLIF(TRIM(cl.last_name), '')), '')
       ) AS applicant_name,
       COALESCE(
         applicant_submission.email,
         applicant_client_sub.email,
         NULLIF(TRIM(cl.applicant_account_email), '')
       ) AS applicant_email
	     FROM iset_case c
	     LEFT JOIN client cl ON cl.id = c.client_id
	     ${applicationJoinSql}
	     LEFT JOIN iset_application_submission s ON s.id = a.submission_id
	     LEFT JOIN user applicant_submission ON applicant_submission.id = s.user_id
	     LEFT JOIN client applicant_submission_client ON applicant_submission_client.applicant_cognito_sub = applicant_submission.cognito_sub
	     LEFT JOIN user applicant_client_sub ON applicant_client_sub.cognito_sub = cl.applicant_cognito_sub
	     WHERE c.id = ?
	     LIMIT 1`,
    requestedApplicationId ? [requestedApplicationId, numericCaseId] : [numericCaseId]
  );

  if (!row) {
    return null;
  }

  const submissionApplicantUserId = normalisePositiveInteger(row.applicant_submission_user_id);
  const submissionApplicantClientId = normalisePositiveInteger(row.applicant_submission_client_id);
  const clientSubApplicantUserId = normalisePositiveInteger(row.applicant_client_sub_user_id);
  const caseClientId = normalisePositiveInteger(row.client_id);
  // Manual-intake submissions can be authored under an account that is not the case participant.
  const hasApplicantUserConflict =
    submissionApplicantUserId &&
    clientSubApplicantUserId &&
    submissionApplicantUserId !== clientSubApplicantUserId;
  const hasApplicantClientConflict =
    submissionApplicantUserId &&
    submissionApplicantClientId &&
    caseClientId &&
    submissionApplicantClientId !== caseClientId;
  const hasStrongIdentityConflict = Boolean(hasApplicantUserConflict || hasApplicantClientConflict);
  const applicantUserId = hasStrongIdentityConflict
    ? null
    : (submissionApplicantUserId || clientSubApplicantUserId || null);
  const clientName = normaliseString(row.client_name) || null;
  const clientEmail = normaliseString(row.client_email) || null;

  return {
    ...row,
    applicant_user_id: applicantUserId,
    applicant_resolution_source: applicantUserId
      ? (submissionApplicantUserId ? 'submission_user_id' : 'client_cognito_sub')
      : null,
    applicant_resolution_conflict: Boolean(hasStrongIdentityConflict),
    applicant_name: hasStrongIdentityConflict
      ? clientName
      : (normaliseString(row.applicant_name) || clientName),
    applicant_email: hasStrongIdentityConflict
      ? clientEmail
      : (normaliseString(row.applicant_email) || clientEmail),
    submission_reference: normaliseString(row.submission_reference) || null,
    case_number: normaliseString(row.case_number) || null,
  };
}


// Get a single case by case id
app.get('/api/cases/:id/workspace', async (req, res) => {
  const caseId = Number.parseInt(req.params.id, 10);
  if (!Number.isInteger(caseId) || caseId <= 0) {
    return res.status(400).json({ error: 'invalid_case_id' });
  }
  const requestedApplicationId = normalisePositiveInteger(req.query.applicationId || req.query.application_id);

  try {
    const applicationJoinSql = requestedApplicationId
      ? 'JOIN iset_application a ON a.case_id = c.id AND a.id = ?'
      : buildCasePrimaryApplicationJoinSql('c', 'a');
    const sql = `
      SELECT
        c.id,
        a.id AS application_id,
        c.client_id,
c.assigned_staff_profile_id AS assigned_to_user_id,
        c.assigned_staff_profile_id AS assigned_staff_profile_id,
        c.case_number,
        c.status,
        c.lifecycle_status AS case_lifecycle_status,
        c.closure_reason AS case_closure_reason,
        c.priority,
        c.risk_rating,
        c.opened_at,
        c.closed_at,
        c.updated_at,
        c.next_action_due_at,
        c.case_context_json,
        a.docs_requested_active,
        a.docs_requested_at,
        a.docs_requested_cleared_at,
        a.docs_requested_source,
        a.status AS application_status,
        a.lifecycle_status AS application_lifecycle_status,
        a.decision_outcome AS decision_outcome,
        a.awaiting_reason AS application_awaiting_reason,
        a.closure_reason AS application_closure_reason,
        COALESCE(task_counts.open_task_count, 0) AS open_task_count,
        COALESCE(task_counts.overdue_task_count, 0) AS overdue_task_count,
        COALESCE(intervention_counts.open_intervention_count, 0) AS open_intervention_count,
        COALESCE(intervention_counts.total_intervention_count, 0) AS total_intervention_count,
        c.portfolio_region_id,
        cl.first_name AS client_first_name,
        cl.last_name AS client_last_name,
        cl.dob AS client_dob,
        cl.gender AS client_gender,
        cl.aboriginal_group AS client_aboriginal_group,
        cl.address_json AS client_address_json,
        cl.applicant_cognito_sub AS client_applicant_cognito_sub,
        cl.applicant_cognito_username AS client_applicant_cognito_username,
        cl.applicant_account_status AS client_applicant_account_status,
        cl.applicant_account_email AS client_applicant_account_email,
        cl.applicant_invited_at AS client_applicant_invited_at,
        cl.applicant_activated_at AS client_applicant_activated_at,
        sp.display_name AS owner_display_name,
        sp.name AS owner_name,
        sp.email AS owner_email,
        sp.primary_role AS owner_role,
        sp.region_id AS owner_region_id,
        cr.code AS region_code,
        cr.name_en AS region_name,
        owner_region.code AS owner_region_code,
        owner_region.name_en AS owner_region_name,
        s.reference_number AS submission_reference_number,
        JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.\"first-name\"')) AS submission_first_name,
        JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.\"last-name\"')) AS submission_last_name,
        JSON_UNQUOTE(JSON_EXTRACT(s.intake_payload, '$.\"preferred-name\"')) AS submission_preferred_name,
        c.created_at AS case_created_at,
        COALESCE(
          applicant_submission.id,
          NULLIF(JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.submission_snapshot.user_id')), '')
        ) AS applicant_user_id,
        COALESCE(
          applicant_submission.name,
          JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.personal.full_name')),
          JSON_UNQUOTE(JSON_EXTRACT(a.payload_json, '$.answers."first-name"'))
        ) AS applicant_name,
        applicant_submission.email AS applicant_email
      FROM iset_case c
      LEFT JOIN client cl ON cl.id = c.client_id
      LEFT JOIN staff_profiles sp ON sp.id = c.assigned_staff_profile_id
      LEFT JOIN canada_region cr ON cr.region_id = c.portfolio_region_id
      LEFT JOIN canada_region owner_region ON owner_region.region_id = sp.region_id
      ${applicationJoinSql}
      LEFT JOIN iset_application_submission s ON s.id = a.submission_id
      LEFT JOIN user applicant_submission ON applicant_submission.id = s.user_id
      LEFT JOIN (
        SELECT
          case_id,
          SUM(
            CASE
              WHEN LOWER(COALESCE(status, '')) IN ('open', 'in_progress', 'in-progress', 'inprogress')
              THEN 1
              ELSE 0
            END
          ) AS open_task_count,
          SUM(
            CASE
              WHEN LOWER(COALESCE(status, '')) IN ('open', 'in_progress', 'in-progress', 'inprogress')
                AND due_at IS NOT NULL
                AND due_at < NOW()
              THEN 1
              ELSE 0
            END
          ) AS overdue_task_count
        FROM iset_case_task
        GROUP BY case_id
      ) task_counts ON task_counts.case_id = c.id
      LEFT JOIN (
        SELECT
          ci.case_id,
          SUM(
            CASE
              WHEN ${buildInterventionDeliveryStatusSql('ci')} IN ('planned', 'in_progress', 'suspended')
              THEN 1
              ELSE 0
            END
          ) AS open_intervention_count,
          SUM(
            CASE
              WHEN ${buildInterventionDeliveryStatusSql('ci')} IS NOT NULL
              THEN 1
              ELSE 0
            END
          ) AS total_intervention_count
        FROM iset_case_intervention ci
        GROUP BY ci.case_id
      ) intervention_counts ON intervention_counts.case_id = c.id
      WHERE c.id = ?
      LIMIT 1
    `;

    const [[row] = []] = await pool.query(
      sql,
      requestedApplicationId ? [requestedApplicationId, caseId] : [caseId]
    );
    if (!row) {
      return res.status(404).json({ error: 'case_not_found' });
    }

    const identity = getRequesterIdentity(req);
    const role = inferUserRole(req);
    const allowAll =
      role === 'System Administrator' ||
      role === 'NWAC Administrator' ||
      role === 'System_Administrator' ||
      role === 'NWAC_Administrator';

    if (!allowAll) {
      if (role === 'Regional Manager' || role === 'Regional_Manager') {
        const accessError = getRegionalManagerCaseAccessError({
          requesterId: identity.staffProfileId,
          regionIds: resolveRequestRegionIds(req),
          caseRow: row,
        });
        if (accessError) {
          return res.status(accessError.status).json(accessError.body);
        }
      } else if (role === 'ISET Coordinator' || role === 'ISET_Coordinator') {
        const requesterId = Number.isFinite(identity.staffProfileId) ? Number(identity.staffProfileId) : null;
        if (!Number.isFinite(requesterId)) {
          return res.status(403).json({ error: 'forbidden', detail: 'assessor_scope_missing' });
        }
        if (resolveCaseAssignedStaffProfileId(row) !== requesterId) {
          return res.status(403).json({ error: 'forbidden' });
        }
      } else {
        return res.status(403).json({ error: 'forbidden' });
      }
    }

    let applicantMessagingContext = null;
    try {
      applicantMessagingContext = await resolveCaseApplicantMessagingContext(caseId);
    } catch (err) {
      const noTable = err && err.code === 'ER_NO_SUCH_TABLE';
      const badField = err && err.code === 'ER_BAD_FIELD_ERROR';
      if (!noTable && !badField) {
        throw err;
      }
      console.warn('[workspace] applicant messaging context unavailable for case %s (%s)', caseId, err?.code || err);
    }

    let clientRegionObject = null;
    let clientRegionLabel = null;
    const parsedAddress = safeJsonParse(row.client_address_json, null);
    if (parsedAddress && typeof parsedAddress === 'object') {
      const addressDetails =
        parsedAddress.address && typeof parsedAddress.address === 'object'
          ? parsedAddress.address
          : parsedAddress;
      const provinceCandidate = normaliseString(
        addressDetails?.province ||
          addressDetails?.province_code ||
          addressDetails?.provinceCode ||
          parsedAddress?.province ||
          parsedAddress?.province_code ||
          parsedAddress?.provinceCode
      );
      if (provinceCandidate) {
        const provinceCode =
          PROVINCE_CODE_MAP[provinceCandidate.toLowerCase()] || provinceCandidate.toUpperCase();
        const provinceName = PROVINCE_LABEL_MAP[provinceCode] || provinceCode;
        clientRegionObject = {
          code: provinceCode,
          name: provinceName,
        };
        clientRegionLabel = provinceName;
      }
    }

    const [planRows] = await pool.query(
      `SELECT
         ap.id,
         ap.case_id,
         ap.name,
         ap.status,
         ap.effective_date,
         ap.review_date,
         ap.activated_at,
         ap.closed_at,
        ap.result_code,
        ap.result_date,
        ap.EIClaimant,
        ap.agreement_number,
        ap.prev_employment,
        ap.outcome_summary,
        ap.closure_notes,
        ap.owner_staff_profile_id,
        ap.owner_user_id,
        ap.notes,
        ap.metadata_json,
        ap.esdc_action_plan_json,
        ap.budget_pot,
        ap.funding_stream,
        ap.esdc_action_plan_json AS esdcActionPlanJson,
        bp.id AS budget_pot_id,
        bp.code AS budget_pot_code,
        bp.name AS budget_pot_name,
        ap.archived_at,
        ap.created_at,
        ap.updated_at,
         (
           SELECT COUNT(*)
           FROM iset_case_intervention ci
           WHERE ci.action_plan_id = ap.id
         ) AS intervention_count
       FROM iset_case_action_plan ap
       LEFT JOIN budget_pot bp
         ON (
           (ap.budget_pot REGEXP '^[0-9]+$' AND bp.id = CAST(ap.budget_pot AS UNSIGNED))
           OR bp.code = ap.budget_pot
         )
       WHERE ap.case_id = ?
       ORDER BY ap.created_at ASC, ap.id ASC`,
      [caseId]
    );

    const planIds = planRows.map(plan => plan.id).filter(id => Number.isFinite(Number(id)));
    const financeTotalsByIntervention = new Map();
    const financeTotalsByPot = new Map();
    const interventionsByPlan = new Map();
    if (planIds.length > 0) {
      const [interventionRows] = await pool.query(
        `SELECT
           ci.*,
           ap.funding_stream AS plan_funding_stream,
           p.id AS proposal_id,
           p.proposal_kind AS proposal_kind,
           p.review_status AS proposal_review_status,
           p.reviewed_at AS proposal_reviewed_at,
           p.source_intervention_id AS proposal_source_intervention_id
         FROM iset_case_intervention ci
         LEFT JOIN iset_case_action_plan ap ON ap.id = ci.action_plan_id
         LEFT JOIN iset_intervention_proposal p ON p.legacy_intervention_id = ci.id
         WHERE ci.action_plan_id IN (?)
         ORDER BY ci.start_date IS NULL, ci.start_date ASC, ci.id ASC`,
        [planIds]
      );
      const interventionIds = Array.from(
        new Set(
          interventionRows
            .map(intervention => normalisePositiveInteger(intervention?.id))
            .filter(Boolean)
        )
      );
      if (interventionIds.length) {
        const [financeRows] = await pool.query(
          `SELECT
             case_intervention_id AS intervention_id,
             budget_pot_id,
             COALESCE(SUM(CASE WHEN LOWER(TRIM(COALESCE(status, ''))) = 'submitted' THEN amount ELSE 0 END), 0) AS committed_amount,
             COALESCE(SUM(CASE WHEN LOWER(TRIM(COALESCE(status, ''))) = 'posted' THEN amount ELSE 0 END), 0) AS actual_amount
           FROM finance_transaction
           WHERE case_id = ?
             AND case_intervention_id IN (?)
           GROUP BY case_intervention_id, budget_pot_id`,
          [caseId, interventionIds]
        );
        (Array.isArray(financeRows) ? financeRows : []).forEach(financeRow => {
          const interventionId = normalisePositiveInteger(financeRow?.intervention_id);
          const potId = normalisePositiveInteger(financeRow?.budget_pot_id);
          const committedAmount = Number(financeRow?.committed_amount || 0);
          const actualAmount = Number(financeRow?.actual_amount || 0);

          if (interventionId) {
            const currentInterventionTotals = financeTotalsByIntervention.get(interventionId) || { committed: 0, actual: 0 };
            currentInterventionTotals.committed += committedAmount;
            currentInterventionTotals.actual += actualAmount;
            financeTotalsByIntervention.set(interventionId, currentInterventionTotals);
          }

          if (potId) {
            const currentPotTotals = financeTotalsByPot.get(String(potId)) || { committed: 0, actual: 0 };
            currentPotTotals.committed += committedAmount;
            currentPotTotals.actual += actualAmount;
            financeTotalsByPot.set(String(potId), currentPotTotals);
          }
        });
      }
      interventionRows.forEach(row => {
        const mapped = mapInterventionRow(row);
        if (!mapped) return;
        const interventionId = normalisePositiveInteger(row?.id);
        const financeTotals = interventionId ? financeTotalsByIntervention.get(interventionId) : null;
        mapped.financeCommittedAmount = roundFinanceCurrencyAmount(financeTotals?.committed || 0);
        mapped.financeActualAmount = roundFinanceCurrencyAmount(financeTotals?.actual || 0);
        const key = row.action_plan_id || 0;
        if (!interventionsByPlan.has(key)) interventionsByPlan.set(key, []);
        interventionsByPlan.get(key).push(mapped);
      });
    }

    const actionPlans = planRows.map(plan => {
      const interventions = interventionsByPlan.get(plan.id) || [];
      const mapped = mapActionPlanRow({ ...plan, interventions });
      mapped.interventions = interventions;
      mapped.interventionCount = interventions.length;
      return mapped;
    });

    const toCurrencyValue = value => {
      const numeric = Number(value);
      if (!Number.isFinite(numeric)) {
        return null;
      }
      return Math.round(numeric * 100) / 100;
    };

    const approvedFundingStatuses = new Set(normalizeStatusList(METRICS_APPROVED_INTERVENTION_STATUSES));
    const isApprovedFundingIntervention = intervention => {
      const effectiveStatus = resolveInterventionStateFields(intervention, { fallbackStatus: null }).effectiveStatus;
      return approvedFundingStatuses.has(normaliseString(effectiveStatus) || '');
    };
    const resolveApprovedFundingAmount = intervention => {
      if (!isApprovedFundingIntervention(intervention)) {
        return null;
      }
      const candidates = [
        intervention?.approvedAmount,
        intervention?.budgetAmount,
        intervention?.plannedCost,
        intervention?.cost,
        intervention?.intervention_cost,
        intervention?.metadata?.cost,
      ];
      for (const candidate of candidates) {
        const numeric = toCurrencyValue(candidate);
        if (numeric !== null) {
          return numeric;
        }
      }
      return null;
    };
    const resolveFinancePotId = intervention => {
      const directPotId = normalisePositiveInteger(intervention?.potId);
      if (directPotId) return String(directPotId);
      const metadataPotId =
        normalisePositiveInteger(intervention?.metadata?.budget?.id) ||
        normalisePositiveInteger(intervention?.metadata?.finance?.potId) ||
        null;
      return metadataPotId ? String(metadataPotId) : null;
    };

    const potIdsForLabels = Array.from(
      new Set(
        [
          ...planRows.map(plan => normalisePositiveInteger(plan?.budget_pot)),
          ...actionPlans.flatMap(plan =>
            (Array.isArray(plan?.interventions) ? plan.interventions : []).map(intervention =>
              normalisePositiveInteger(resolveFinancePotId(intervention))
            )
          ),
          ...Array.from(financeTotalsByPot.keys()).map(key => normalisePositiveInteger(key)),
        ].filter(Boolean)
      )
    );
    const budgetPotLabelById = new Map();
    if (potIdsForLabels.length) {
      const [budgetPotRows] = await pool.query(
        `SELECT id, name, code
           FROM budget_pot
          WHERE id IN (?)`,
        [potIdsForLabels]
      );
      (Array.isArray(budgetPotRows) ? budgetPotRows : []).forEach(budgetPotRow => {
        const potId = normalisePositiveInteger(budgetPotRow?.id);
        if (!potId) return;
        budgetPotLabelById.set(
          String(potId),
          normaliseString(budgetPotRow?.name) ||
            normaliseString(budgetPotRow?.code) ||
            `Budget pot ${potId}`
        );
      });
    }

    const normalisePotEntry = (entry, index = 0) => {
      if (!entry || typeof entry !== 'object') {
        return null;
      }
      const approved =
        toCurrencyValue(
          entry.approved ??
            entry.approved_amount ??
          entry.allocated ??
            entry.allocated_amount ??
            entry.totalAllocated ??
            entry.budget ??
            entry.limit ??
            entry.allocation
        ) ?? 0;
      const committed =
        toCurrencyValue(
          entry.committed ??
            entry.committed_amount ??
            entry.totalCommitted ??
            entry.encumbered ??
            entry.commitment
        ) ?? 0;
      const actual =
        toCurrencyValue(
          entry.actual ??
            entry.actual_amount ??
            entry.spent ??
            entry.spent_amount ??
            entry.disbursed ??
            entry.actuals
        ) ?? 0;
      const remaining = toCurrencyValue(approved - committed - actual) ?? 0;
      const id = entry.id || entry.potId || entry.budgetPotId || `pot-${index}`;
      const nameCandidate =
        entry.name ||
        entry.title ||
        entry.label ||
        entry.potName ||
        entry.pot_label ||
        entry.pot ||
        entry.category ||
        entry.fundingStream ||
        entry.funding_stream ||
        id;
      const name =
        typeof nameCandidate === 'string' && nameCandidate.trim().length
          ? nameCandidate.trim()
          : `Budget pot ${index + 1}`;
      return {
        id,
        name,
        approved,
        allocated: approved,
        committed,
        actual,
        remaining,
      };
    };

    const parseSnapshotDetails = value => {
      if (!value) return [];
      let parsed = value;
      if (typeof value === 'string') {
        try {
          parsed = JSON.parse(value);
        } catch (_) {
          return [];
        }
      }
      if (Array.isArray(parsed)) {
        return parsed;
      }
      if (parsed && typeof parsed === 'object') {
        if (Array.isArray(parsed.pots)) {
          return parsed.pots;
        }
        return Object.values(parsed);
      }
      return [];
    };

    const buildLiveFinanceSummary = () => {
      if (!actionPlans.length && !financeTotalsByPot.size) {
        return null;
      }
      const potMap = new Map();
      const ensurePotBucket = (id, fallbackName = null) => {
        const key = id ? String(id) : fallbackName || 'General allocation';
        if (!potMap.has(key)) {
          potMap.set(key, {
            id: key,
            name:
              fallbackName ||
              budgetPotLabelById.get(key) ||
              (id ? `Budget pot ${id}` : 'General allocation'),
            approved: 0,
            committed: 0,
            actual: 0,
          });
        }
        return potMap.get(key);
      };

      actionPlans.forEach(plan => {
        (plan.interventions || []).forEach(intervention => {
          const potId = resolveFinancePotId(intervention);
          const nameCandidates = [
            potId ? budgetPotLabelById.get(String(potId)) : null,
            intervention?.metadata?.finance?.potName,
            intervention?.metadata?.finance?.potLabel,
            intervention?.metadata?.budget?.name,
            intervention?.metadata?.budget?.label,
            intervention?.metadata?.potName,
            intervention?.fundingStream,
            intervention?.metadata?.title,
          ];
          const name =
            nameCandidates.find(value => typeof value === 'string' && value.trim().length) ||
            'General allocation';
          const bucket = ensurePotBucket(potId, name);
          const approvedAmount = resolveApprovedFundingAmount(intervention);
          if (approvedAmount !== null) {
            bucket.approved += approvedAmount;
          }
          const financeActualAmount = toCurrencyValue(intervention?.financeActualAmount);
          const legacyActualAmount = toCurrencyValue(intervention?.actualAmount);
          if ((financeActualAmount === null || financeActualAmount === 0) && legacyActualAmount !== null) {
            bucket.actual += legacyActualAmount;
          }
        });
      });

      financeTotalsByPot.forEach((totals, potId) => {
        const bucket = ensurePotBucket(potId, budgetPotLabelById.get(String(potId)) || null);
        bucket.committed += Number(totals?.committed || 0);
        bucket.actual += Number(totals?.actual || 0);
      });

      const pots = Array.from(potMap.values())
        .map(pot => {
          const approved = toCurrencyValue(pot.approved) ?? 0;
          const committed = toCurrencyValue(pot.committed) ?? 0;
          const actual = toCurrencyValue(pot.actual) ?? 0;
          return {
            id: pot.id,
            name: pot.name,
            approved,
            allocated: approved,
            committed,
            actual,
            remaining: toCurrencyValue(approved - committed - actual) ?? 0,
          };
        })
        .sort((a, b) => (b.approved || 0) - (a.approved || 0));

      if (!pots.length) {
        return null;
      }

      const approved = pots.reduce((sum, pot) => sum + (pot.approved || 0), 0);
      const committed = pots.reduce((sum, pot) => sum + (pot.committed || 0), 0);
      const actuals = pots.reduce((sum, pot) => sum + (pot.actual || 0), 0);
      return {
        approved: toCurrencyValue(approved),
        allocated: toCurrencyValue(approved),
        committed: toCurrencyValue(committed),
        actual: toCurrencyValue(actuals),
        actuals: toCurrencyValue(actuals),
        remaining: toCurrencyValue(approved - committed - actuals),
        variance: toCurrencyValue(approved - committed - actuals),
        pots,
      };
    };

    let financeSummary = buildLiveFinanceSummary();
    let snapshotFinanceSummary = null;
    try {
      const [[snapshotRow]] = await pool.query(
        `SELECT
           as_of_date,
           allocated_amount,
           committed_amount,
           spent_amount,
           variance_amount,
           details_json
         FROM iset_case_financial_snapshot
         WHERE case_id = ?
         ORDER BY as_of_date DESC, created_at DESC
         LIMIT 1`,
        [caseId]
      );
      if (snapshotRow) {
        const approved = toCurrencyValue(snapshotRow.allocated_amount);
        const committed = toCurrencyValue(snapshotRow.committed_amount);
        const actuals = toCurrencyValue(snapshotRow.spent_amount);
        const variance =
          toCurrencyValue(snapshotRow.variance_amount) ??
          (approved !== null && committed !== null && actuals !== null
            ? toCurrencyValue(approved - committed - actuals)
            : null);
        const potEntries = parseSnapshotDetails(snapshotRow.details_json)
          .map((entry, index) => normalisePotEntry(entry, index))
          .filter(Boolean)
          .sort((a, b) => (b.approved || 0) - (a.approved || 0));
        snapshotFinanceSummary = {
          approved: approved ?? (potEntries.length ? potEntries.reduce((sum, pot) => sum + pot.approved, 0) : null),
          allocated: approved ?? (potEntries.length ? potEntries.reduce((sum, pot) => sum + pot.approved, 0) : null),
          committed:
            committed ?? (potEntries.length ? potEntries.reduce((sum, pot) => sum + pot.committed, 0) : null),
          actual:
            actuals ?? (potEntries.length ? potEntries.reduce((sum, pot) => sum + pot.actual, 0) : null),
          actuals:
            actuals ?? (potEntries.length ? potEntries.reduce((sum, pot) => sum + pot.actual, 0) : null),
          remaining:
            approved !== null && committed !== null && actuals !== null
              ? toCurrencyValue(approved - committed - actuals)
              : null,
          variance:
            variance ??
            (approved !== null && committed !== null && actuals !== null
              ? toCurrencyValue(approved - committed - actuals)
              : null),
          asOfDate: snapshotRow.as_of_date ? toDateOnlyString(snapshotRow.as_of_date) : null,
          pots: potEntries,
        };
      }
    } catch (err) {
      console.warn('[workspace] failed to load finance snapshot for case', caseId, err);
    }
    if (!financeSummary) {
      financeSummary = snapshotFinanceSummary;
    } else if (snapshotFinanceSummary?.asOfDate) {
      financeSummary.asOfDate = snapshotFinanceSummary.asOfDate;
    }

    const parseJsonField = (value, fallback) => {
      if (value === null || typeof value === 'undefined') return fallback;
      if (typeof value === 'string') {
        const trimmed = value.trim();
        if (!trimmed) return fallback;
        try {
          const parsed = JSON.parse(trimmed);
          return typeof parsed === 'object' && parsed !== null ? parsed : fallback;
        } catch (_) {
          return fallback;
        }
      }
      if (typeof value === 'object') return value;
      return fallback;
    };

	    const caseContext = parseJsonField(row.case_context_json, null);
	    const applicationAssessmentContext = resolveApplicationAssessmentCaseContext(
	      caseContext,
	      row.application_id || null
	    );
	    const contextPersonal = caseContext?.applicationPersonal || {};
    const contextAnswers = caseContext?.applicationAnswers || {};

    const firstNameCandidates = [
      row.submission_first_name,
      contextPersonal.first_name,
      contextPersonal.firstName,
      contextPersonal.given_name,
      contextPersonal.givenName,
      caseContext?.firstName,
      row.client_first_name,
    ];
    const lastNameCandidates = [
      row.submission_last_name,
      contextPersonal.last_name,
      contextPersonal.lastName,
      contextPersonal.family_name,
      contextPersonal.familyName,
      caseContext?.lastName,
      row.client_last_name,
    ];
    const preferredNameCandidates = [
      row.submission_preferred_name,
      contextPersonal.preferred_name,
      contextPersonal.preferredName,
      caseContext?.preferredName,
      contextAnswers['preferred-name'],
      contextAnswers['preferred_name'],
    ];

    const firstName = firstNameCandidates.map(value => normaliseString(value)).find(Boolean) || null;
    const lastName = lastNameCandidates.map(value => normaliseString(value)).find(Boolean) || null;
    const preferredName = preferredNameCandidates.map(value => normaliseString(value)).find(Boolean) || null;
    const clientFullName =
      [firstName, lastName].filter(Boolean).join(' ') ||
      preferredName ||
      null;

    const contextDob =
      contextPersonal.date_of_birth ||
      contextPersonal.dateOfBirth ||
      caseContext?.dateOfBirth ||
      contextAnswers['dob'] ||
      contextAnswers['date-of-birth'] ||
      contextAnswers['birth-date'] ||
      contextAnswers['birthdate'] ||
      null;
    const dateOfBirth = toDateOnly(contextDob) || toDateOnly(row.client_dob) || null;

    const trackingId =
      normaliseString(row.submission_reference_number) ||
      normaliseString(row.case_number) ||
      (row.id ? `CASE-${row.id}` : null);

    const agreementNumber =
      trackingId ||
      normaliseString(row.case_number) ||
      (row.id ? `CASE-${row.id}` : null);

    const caseNumber =
      normaliseString(row.case_number) ||
      trackingId ||
      (row.id ? `CASE-${row.id}` : null);

    const ownerName =
      normaliseString(row.owner_display_name) ||
      normaliseString(row.owner_name) ||
      normaliseString(row.owner_email) ||
      null;

    const caseRegion =
      row.region_name
        ? {
            id: row.portfolio_region_id || null,
            code: normaliseString(row.region_code),
            name: normaliseString(row.region_name),
          }
        : null;
    const ownerRegion =
      row.owner_region_name
        ? {
            id: row.owner_region_id || null,
            code: normaliseString(row.owner_region_code),
            name: normaliseString(row.owner_region_name),
          }
        : null;
    const counts = {
      openTasks: Number.isFinite(Number(row.open_task_count)) ? Number(row.open_task_count) : 0,
      overdueTasks: Number.isFinite(Number(row.overdue_task_count))
        ? Number(row.overdue_task_count)
        : 0,
      openInterventions: Number.isFinite(Number(row.open_intervention_count))
        ? Number(row.open_intervention_count)
        : 0,
      totalInterventions: Number.isFinite(Number(row.total_intervention_count))
        ? Number(row.total_intervention_count)
        : 0,
    };

    const statusNormalized =
      normaliseCaseLifecycleStatusValue(row.case_lifecycle_status || row.status, { preserveUnknown: true }) ||
      normaliseCaseStatusValue(row.status);
    const applicationStatusNormalised = normaliseApplicationStatusValue(row.application_status);
    const applicationLifecycleStatus =
      normaliseApplicationLifecycleStatusValue(row.application_lifecycle_status || row.application_status, {
        preserveUnknown: true,
      }) || null;
    const decisionOutcome =
      normaliseApplicationDecisionOutcomeValue(row.decision_outcome || row.application_status) || null;
    console.debug('[workspace] status payload', {
      caseId,
      caseStatus: statusNormalized || row.status || null,
      applicationStatus: applicationStatusNormalised || row.application_status || null,
    });

    const resolveApplicantUserId = value => {
      if (value === null || typeof value === 'undefined') return null;
      const numeric = Number(value);
      return Number.isFinite(numeric) ? numeric : null;
    };

    const hasApplicantMessagingContext = Boolean(
      applicantMessagingContext &&
      Object.prototype.hasOwnProperty.call(applicantMessagingContext, 'applicant_user_id')
    );
    const applicantUserIdValue = resolveApplicantUserId(
      hasApplicantMessagingContext ? applicantMessagingContext.applicant_user_id : row.applicant_user_id
    );
    const applicantNameValue = hasApplicantMessagingContext
      ? (normaliseString(applicantMessagingContext?.applicant_name) || null)
      : (normaliseString(row.applicant_name) || null);
    const applicantLegalNameValue =
      [firstName, lastName].filter(Boolean).join(' ') ||
      (applicantNameValue && applicantNameValue.includes(' ') ? applicantNameValue : null);
    const applicantEmailValue = hasApplicantMessagingContext
      ? (normaliseString(applicantMessagingContext?.applicant_email) || null)
      : (normaliseString(row.applicant_email) || null);
    const pathAccountEmailValue =
      normaliseString(row.client_applicant_account_email) ||
      normaliseString(
        parsedAddress?.contact?.emailNormalized ||
        parsedAddress?.contact?.email ||
        parsedAddress?.emailNormalized ||
        parsedAddress?.email
      ) ||
      null;
    const rawPathAccountStatus =
      normaliseString(row.client_applicant_account_status) ||
      (normaliseString(row.client_applicant_cognito_sub) || normaliseString(row.client_applicant_cognito_username)
        ? 'created'
        : 'no_account');
    const pathAccountStatus =
      rawPathAccountStatus === 'invitation_sent' ||
      rawPathAccountStatus === 'activated' ||
      rawPathAccountStatus === 'created'
        ? rawPathAccountStatus
        : 'no_account';

    const assignmentFields = buildAssignedStaffProfileResponseFields(row);
    const response = {
      id: row.id,
      caseNumber,
      status: statusNormalized || CASE_STATUS_DERIVED_VALUES.intake,
      statusRaw: row.status || null,
      caseLifecycleStatus: statusNormalized || null,
      caseClosureReason: row.case_closure_reason || null,
      applicantUserId: applicantUserIdValue,
      applicant_user_id: applicantUserIdValue,
      applicantName: applicantNameValue,
      applicant_name: applicantNameValue,
      applicantLegalName: applicantLegalNameValue,
      applicant_legal_name: applicantLegalNameValue,
      submission_first_name: normaliseString(row.submission_first_name) || null,
      submission_last_name: normaliseString(row.submission_last_name) || null,
      submission_preferred_name: normaliseString(row.submission_preferred_name) || null,
      applicantEmail: applicantEmailValue,
      applicant_email: applicantEmailValue,
      applicationStatus: applicationStatusNormalised || row.application_status || null,
      application_status: applicationStatusNormalised || row.application_status || null,
      applicationLifecycleStatus,
      application_lifecycle_status: applicationLifecycleStatus,
      decisionOutcome,
      decision_outcome: decisionOutcome,
      applicationAwaitingReason: row.application_awaiting_reason || null,
      application_awaiting_reason: row.application_awaiting_reason || null,
      applicationClosureReason: row.application_closure_reason || null,
      application_closure_reason: row.application_closure_reason || null,
      docsRequestedActive:
        row.docs_requested_active === null || typeof row.docs_requested_active === 'undefined'
          ? false
          : Number(row.docs_requested_active) === 1,
      docsRequestedAt: toIsoDateTime(row.docs_requested_at),
      docsRequestedClearedAt: toIsoDateTime(row.docs_requested_cleared_at),
      docsRequestedSource: row.docs_requested_source || null,
      priority: row.priority || null,
      riskRating: row.risk_rating || null,
      openedAt: toIsoDateTime(row.opened_at),
      closedAt: toIsoDateTime(row.closed_at),
      updatedAt: toIsoDateTime(row.updated_at),
      nextActionDueAt: toIsoDateTime(row.next_action_due_at),
      trackingId,
      applicationId: row.application_id || null,
      ...assignmentFields,
      submittedAt: toIsoDateTime(row.case_created_at),
      client: {
        id: row.client_id || null,
        firstName,
        lastName,
        fullName: clientFullName || (firstName || lastName ? [firstName, lastName].filter(Boolean).join(' ') : 'Unknown client'),
        preferredName: normaliseString(row.payload_preferred_name) || null,
        dateOfBirth,
        gender: row.client_gender || null,
        aboriginalGroup: row.client_aboriginal_group || null,
        region: clientRegionObject,
        regionLabel: clientRegionLabel,
      },
      pathAccount: {
        status: pathAccountStatus,
        email: pathAccountEmailValue,
        cognitoSub: normaliseString(row.client_applicant_cognito_sub) || null,
        cognitoUsername: normaliseString(row.client_applicant_cognito_username) || null,
        invitedAt: toIsoDateTime(row.client_applicant_invited_at),
        activatedAt: toIsoDateTime(row.client_applicant_activated_at),
      },
      owner: {
        id: assignmentFields.assignedStaffProfileId || null,
        staffProfileId: assignmentFields.assignedStaffProfileId || null,
        staff_profile_id: assignmentFields.assignedStaffProfileId || null,
        name: ownerName,
        email: row.owner_email || null,
        role: row.owner_role || null,
        regionId: row.owner_region_id || null,
        region: ownerRegion,
      },
      eligibility: normaliseString(row.assessment_esdc_eligibility) || null,
      counts,
      actionPlans,
    };

    const firstDefined = (...values) => {
      for (const value of values) {
        if (value !== undefined && value !== null) return value;
      }
      return null;
    };

    const normaliseYesNo = value => {
      if (value === null || typeof value === 'undefined') return null;
      const trimmed = String(value).trim().toLowerCase();
      if (['1', 'yes', 'true', 'y', 'on'].includes(trimmed)) return 'yes';
      if (['0', 'no', 'false', 'n', 'off'].includes(trimmed)) return 'no';
      return null;
    };

    const parseArrayField = value => {
      if (value === null || typeof value === 'undefined') return [];
      if (Array.isArray(value)) return value;
      if (typeof value === 'string') {
        const trimmed = value.trim();
        if (!trimmed) return [];
        try {
          const parsed = JSON.parse(trimmed);
          if (Array.isArray(parsed)) return parsed;
        } catch (_) {
          return trimmed
            .split(',')
            .map(entry => entry.trim())
            .filter(Boolean);
        }
        return [trimmed];
      }
      if (typeof value === 'object') {
        return Object.values(value)
          .map(entry => (typeof entry === 'string' ? entry.trim() : entry))
          .filter(Boolean);
      }
      return [];
    };

    const toStringOrNull = value => (value === null || typeof value === 'undefined' ? null : String(value));
    const toTrimmedStringOrNull = value => {
      const result = toStringOrNull(value);
      if (!result) return null;
      const trimmed = result.trim();
      return trimmed.length ? trimmed : null;
    };

    let assessmentRow = null;
    try {
      assessmentRow = await fetchApplicationAssessmentRow(pool, {
        caseId,
        applicationId: row.application_id || null,
      });
    } catch (err) {
      console.warn('[workspace] failed to load assessment for case', caseId, err);
    }

    const DEFAULT_ITP_PAYLOAD = { tuition: '', books: '', materials: '', living: '', childcare: '', otherLabel: '', otherAmount: '', details: '' };
    const DEFAULT_WAGE_PAYLOAD = { wages: '', mercs: '', nonwages: '', other1Label: '', other1Amount: '', other2Label: '', other2Amount: '', subsidyDetails: '' };

    const employmentBarriers = parseArrayField(
      firstDefined(assessmentRow?.employment_barriers, row.assessment_employment_barriers)
    );
    const localAreaPriorities = parseArrayField(
      firstDefined(assessmentRow?.local_area_priorities, row.assessment_local_area_priorities)
    );
    const previousIsetNormalised = normaliseYesNo(
      firstDefined(assessmentRow?.previous_iset, row.assessment_previous_iset)
    );
    const childcareNeedNormalised = normaliseYesNo(
      firstDefined(assessmentRow?.childcare_need, row.assessment_childcare_need)
    );

    const interventionCodeValue = toStringOrNull(
      firstDefined(assessmentRow?.intervention_code, row.assessment_intervention_code)
    );
    const interventionOutcomeValue = toStringOrNull(
      firstDefined(assessmentRow?.intervention_outcome_code, row.assessment_intervention_outcome_code)
    );
    const interventionDurationValue = toStringOrNull(
      firstDefined(assessmentRow?.intervention_duration_days, row.assessment_intervention_duration_days)
    );
    const interventionCostValue = toStringOrNull(
      firstDefined(assessmentRow?.intervention_cost_total, row.assessment_intervention_cost_total)
    );
    const interventionNocValue = toTrimmedStringOrNull(
      firstDefined(caseContext?.employmentNoc, assessmentRow?.intervention_related_noc, row.assessment_intervention_related_noc)
    );
    const interventionNocVersionValue = toTrimmedStringOrNull(
      firstDefined(caseContext?.employmentNocVersion, assessmentRow?.intervention_related_noc_version, row.assessment_intervention_related_noc_version)
    );
    const barriersOtherDetailsValue = toTrimmedStringOrNull(
      firstDefined(assessmentRow?.employment_barriers_other_details, row.assessment_employment_barriers_other_details)
    );

    const rawAssessmentItp = parseJsonField(
      firstDefined(assessmentRow?.itp_payload, row.assessment_itp),
      null
    );
    const assessmentItp =
      rawAssessmentItp && typeof rawAssessmentItp === 'object'
        ? rawAssessmentItp
        : { ...DEFAULT_ITP_PAYLOAD };
    const rawAssessmentWage = parseJsonField(
      firstDefined(assessmentRow?.wage_payload, row.assessment_wage),
      null
    );
    const assessmentWage =
      rawAssessmentWage && typeof rawAssessmentWage === 'object'
        ? rawAssessmentWage
        : { ...DEFAULT_WAGE_PAYLOAD };
    const proposedInterventionsValue = parseJsonField(
      firstDefined(assessmentRow?.proposed_interventions, row.assessment_proposed_interventions),
      null
    );

    const dateOfAssessmentRaw = firstDefined(
      assessmentRow?.date_of_assessment,
      row.assessment_date_of_assessment
    );
    const startDateRaw = firstDefined(
      assessmentRow?.intervention_start_date,
      row.assessment_intervention_start_date
    );
    const endDateRaw = firstDefined(
      assessmentRow?.intervention_end_date,
      row.assessment_intervention_end_date
    );
    const resultDateRaw = firstDefined(
      assessmentRow?.action_plan_result_date,
      row.assessment_action_plan_result_date
    );

    response.case_summary = assessmentRow?.overview ?? row.case_summary ?? null;
    response.assessment_date_of_assessment = toDateOnlyString(dateOfAssessmentRaw);
    response.caseContext = caseContext || null;
    response.assessment_employment_goals =
      firstDefined(caseContext?.employmentGoals, assessmentRow?.employment_goals, row.assessment_employment_goals) ?? null;
    response.assessment_previous_iset = firstDefined(caseContext?.previousIset, previousIsetNormalised);
    response.assessment_previous_iset_details =
      firstDefined(caseContext?.previousIsetDetails, assessmentRow?.previous_iset_details, row.assessment_previous_iset_details) ?? null;
    response.assessment_employment_barriers = employmentBarriers;
    response.assessment_employment_barriers_other_details = barriersOtherDetailsValue;
    response.assessment_local_area_priorities = localAreaPriorities;
    response.assessment_other_funding_details =
      firstDefined(caseContext?.otherFunding, assessmentRow?.other_funding_details, row.assessment_other_funding_details) ?? null;
    response.assessment_esdc_eligibility =
      normaliseString(firstDefined(assessmentRow?.esdc_eligibility, row.assessment_esdc_eligibility)) || null;
    response.assessment_intervention_start_date = toDateOnlyString(startDateRaw);
    response.assessment_intervention_end_date = toDateOnlyString(endDateRaw);
    response.assessment_institution = assessmentRow?.institution ?? row.assessment_institution ?? null;
    response.assessment_program_name = assessmentRow?.program_name ?? row.assessment_program_name ?? null;
    response.assessment_itp = assessmentItp;
    response.assessment_wage = assessmentWage;
    response.assessment_recommendation =
      assessmentRow?.recommendation ?? row.assessment_recommendation ?? null;
    response.assessment_justification =
      assessmentRow?.justification ?? row.assessment_justification ?? null;
    response.assessment_nwac_review =
      assessmentRow?.nwac_review ?? row.assessment_nwac_review ?? null;
	    const assessmentReviewStatusRaw = typeof applicationAssessmentContext?.assessment_nwac_review_status === 'string'
	      ? applicationAssessmentContext.assessment_nwac_review_status.trim().toLowerCase()
	      : null;
    response.assessment_nwac_review_status =
      assessmentReviewStatusRaw === 'approve' ||
      assessmentReviewStatusRaw === 'reject' ||
      assessmentReviewStatusRaw === 'push_back'
        ? assessmentReviewStatusRaw
        : null;
    response.assessment_nwac_reason =
      assessmentRow?.nwac_reason ?? row.assessment_nwac_reason ?? null;
    response.assessment_intervention_code = interventionCodeValue;
    response.assessment_intervention_outcome_code = interventionOutcomeValue;
    response.assessment_intervention_duration_days = interventionDurationValue;
    response.assessment_intervention_cost_total = interventionCostValue;
    response.assessment_intervention_related_noc = interventionNocValue;
    response.assessment_intervention_related_noc_version = interventionNocVersionValue;
    response.assessment_proposed_interventions = proposedInterventionsValue;
    response.assessment_childcare_need = childcareNeedNormalised;
    response.assessment_childcare_funding_details =
      assessmentRow?.childcare_funding_details ?? row.assessment_childcare_funding_details ?? null;
    response.assessment_action_plan_result_code =
      assessmentRow?.action_plan_result_code ?? row.assessment_action_plan_result_code ?? null;
    response.assessment_action_plan_result_date = toDateOnlyString(resultDateRaw);
    const conflictSignedRaw = row.assessment_conflict_declaration_signed;
    const conflictSignedValue =
      conflictSignedRaw === null || typeof conflictSignedRaw === 'undefined'
        ? null
        : Number(conflictSignedRaw) === 1;
    response.assessment_conflict_declaration_signed = conflictSignedValue === true;
    response.assessment_conflict_declaration_signed_at = toIsoDateTime(row.assessment_conflict_declaration_signed_at);
    response.assessment_conflict_declaration_signed_by =
      row.assessment_conflict_declaration_signed_by === null ||
      typeof row.assessment_conflict_declaration_signed_by === 'undefined'
        ? null
        : Number(row.assessment_conflict_declaration_signed_by);
    const conflictChoiceRaw = typeof row.assessment_conflict_declaration_choice === 'string'
      ? row.assessment_conflict_declaration_choice.trim().toLowerCase()
      : null;
    response.assessment_conflict_declaration_choice =
      conflictChoiceRaw || (response.assessment_conflict_declaration_signed ? 'no_conflict' : null);
    const conflictDetailsRaw = typeof row.assessment_conflict_declaration_details === 'string'
      ? row.assessment_conflict_declaration_details.trim()
      : null;
    response.assessment_conflict_declaration_details = conflictDetailsRaw || null;

    response.eligibility = response.assessment_esdc_eligibility;
    response.finance = financeSummary;

    const submissionIdForCase = await findEsdcSubmissionIdForCase(pool, caseId);
    const [[ilmpComplianceRow]] = submissionIdForCase
      ? await pool.query(
          `SELECT readiness_status, readiness_summary, warnings, blocking_issues, last_validated_at, payload_snapshot, payload_checksum, payload_storage_key
             FROM esdc_participant_submission
             WHERE id = ?
             LIMIT 1`,
          [submissionIdForCase]
        )
      : [[]];
    response.compliance = {
      ilmp: mapIlmpComplianceFromSubmission(ilmpComplianceRow),
      finance: { status: 'pending', messages: [] },
    };
    if (ilmpComplianceRow) {
      const snapshot = safeJsonParse(ilmpComplianceRow.payload_snapshot, null);
      response.exportPreview = {
        ilmp: snapshot
          ? {
              schema: snapshot.schema || null,
              generatedAt: snapshot.generatedAt || null,
              storageKey: ilmpComplianceRow.payload_storage_key || snapshot.storageKey || null,
              checksum: ilmpComplianceRow.payload_checksum || snapshot.checksum || null,
              canonical: snapshot.canonical || null,
              xml: snapshot.xml || null,
            }
          : null,
      };
    } else {
      response.exportPreview = { ilmp: null };
    }

    res.set('Cache-Control', 'no-store, max-age=0');
    res.json(response);
  } catch (error) {
    console.error('GET /api/cases/:id/workspace failed:', error);
    res.status(500).json({ error: 'workspace_fetch_failed', detail: error?.message || String(error) });
  }
});

app.post('/api/cases/:id/validate-ilmp', async (req, res) => {
  const caseId = Number.parseInt(req.params.id, 10);
  if (!Number.isInteger(caseId) || caseId <= 0) {
    return res.status(400).json({ error: 'invalid_case_id' });
  }

  try {
    const accessError = await validateCaseAccessByCaseId(req, caseId);
    if (accessError) return res.status(accessError.status).json(accessError.body);

    const [[caseRow]] = await pool.query(
      `SELECT c.id,
              a.id AS application_id
         FROM iset_case c
         ${buildCasePrimaryApplicationJoinSql('c', 'a')}
        WHERE c.id = ?
        LIMIT 1`,
      [caseId]
    );
    if (!caseRow) {
      return res.status(404).json({ error: 'case_not_found' });
    }

    await ensureEsdcParticipantSubmissionRecord(null, caseId, caseRow.application_id || null);

    const submissionId = await findEsdcSubmissionIdForCase(pool, caseId);
    if (!submissionId) {
      return res.status(500).json({ error: 'submission_initialization_failed' });
    }

    await validateEsdcParticipantSubmission({ submissionId, caseId });

    const [[updatedSubmission]] = await pool.query(
      `SELECT readiness_status, readiness_summary, warnings, blocking_issues, last_validated_at
         FROM esdc_participant_submission
         WHERE id = ?`,
      [submissionId]
    );

    const compliance = {
      ilmp: mapIlmpComplianceFromSubmission(updatedSubmission),
      finance: { status: 'pending', messages: [] },
    };

    await setInterventionComplianceForCase(caseId, compliance.ilmp.status);

    res.json({ compliance });
  } catch (error) {
    if (error && error.statusCode) {
      return res.status(error.statusCode).json({ error: error.message || 'case_ilmp_validation_failed' });
    }
    console.error('POST /api/cases/:id/validate-ilmp failed:', error);
    res
      .status(500)
      .json({ error: 'case_ilmp_validation_failed', detail: error?.message || String(error) });
  }
});

app.post('/api/cases/:id/ready-to-close', async (req, res) => {
  const caseId = Number.parseInt(req.params.id, 10);
  if (!Number.isInteger(caseId) || caseId <= 0) {
    return res.status(400).json({ error: 'invalid_case_id' });
  }

  try {
    const accessError = await validateCaseAccessByCaseId(req, caseId);
    if (accessError) return res.status(accessError.status).json(accessError.body);

    const result = await markCaseReadyToClose({ caseId });
    return res.json({
      success: true,
      status: CASE_STATUS_READY_TO_CLOSE,
      compliance: result.compliance,
      warnings: result.warnings || null
    });
  } catch (err) {
    const status = err?.statusCode || err?.status || 500;
    const payload = { error: err?.message || 'ready_to_close_failed' };
    if (err?.blockers) payload.blockers = err.blockers;
    if (err?.compliance) payload.compliance = err.compliance;
    if (err?.warnings) payload.warnings = err.warnings;
    return res.status(status).json(payload);
  }
});

app.post('/api/cases/:id/prepare-ilmp', async (req, res) => {
  const caseId = Number.parseInt(req.params.id, 10);
  if (!Number.isInteger(caseId) || caseId <= 0) {
    return res.status(400).json({ error: 'invalid_case_id' });
  }

  try {
    const accessError = await validateCaseAccessByCaseId(req, caseId);
    if (accessError) return res.status(accessError.status).json(accessError.body);

    const [[caseRow]] = await pool.query(
      `SELECT c.id,
              a.id AS application_id
         FROM iset_case c
         ${buildCasePrimaryApplicationJoinSql('c', 'a')}
        WHERE c.id = ?
        LIMIT 1`,
      [caseId]
    );
    if (!caseRow) {
      return res.status(404).json({ error: 'case_not_found' });
    }

    await ensureEsdcParticipantSubmissionRecord(null, caseId, caseRow.application_id || null);

    const submissionId = await findEsdcSubmissionIdForCase(pool, caseId);
    if (!submissionId) {
      return res.status(500).json({ error: 'submission_initialization_failed' });
    }

    const result = await prepareEsdcParticipantSubmission({ submissionId, caseId });
    if (result.blocking) {
      return res.status(409).json({
        error: 'blocking_validation_issues',
        readinessStatus: result.evaluation.readinessStatus,
        readinessSummary: result.evaluation.readinessSummary,
        warnings: result.evaluation.warnings,
        blockingIssues: result.evaluation.blockingIssues
      });
    }

    const compliance = {
      ilmp: mapIlmpComplianceFromSubmission(result.submission),
      finance: { status: 'pending', messages: [] }
    };

    const payloadSnapshot = result.payload
      ? {
          schema: result.payload.schema || null,
          generatedAt: result.payload.generatedAt || null,
          storageKey: result.storageKey || result.payload.storageKey || null,
          checksum: result.checksum || result.payload.checksum || null,
          canonical: result.payload.canonical || null,
          xml: result.payload.xml || null
        }
      : null;

    res.json({ compliance, payload: payloadSnapshot });
  } catch (error) {
    if (error && error.statusCode) {
      return res.status(error.statusCode).json({ error: error.message || 'case_ilmp_prepare_failed' });
    }
    console.error('POST /api/cases/:id/prepare-ilmp failed:', error);
    res
      .status(500)
      .json({ error: 'case_ilmp_prepare_failed', detail: error?.message || String(error) });
  }
});

app.get('/api/cases/:id/action-plan/context', async (req, res) => {
  const caseId = Number.parseInt(req.params.id, 10);
  if (!Number.isInteger(caseId) || caseId <= 0) {
    return res.status(400).json({ error: 'invalid_case_id' });
  }

  let connection;
  try {
    connection = await pool.getConnection();

    const [[caseRow]] = await connection.query(
      `SELECT
         a.id AS application_id,
c.assigned_staff_profile_id AS assigned_to_user_id,
         c.portfolio_region_id,
         c.case_context_json,
         sp.region_id AS owner_region_id
       FROM iset_case c
       ${buildCasePrimaryApplicationJoinSql('c', 'a')}
       LEFT JOIN staff_profiles sp ON sp.id = c.assigned_staff_profile_id
       WHERE c.id = ?
       LIMIT 1`,
      [caseId]
    );

    if (!caseRow) {
      return res.status(404).json({ error: 'case_not_found' });
    }

    const role = inferUserRole(req);
    const identity = getRequesterIdentity(req);
    const allowAll =
      role === 'System Administrator' ||
      role === 'NWAC Administrator' ||
      role === 'System_Administrator' ||
      role === 'NWAC_Administrator';

    if (!allowAll) {
      if (role === 'Regional Manager' || role === 'Regional_Manager') {
        const accessError = getRegionalManagerCaseAccessError({
          requesterId: identity.staffProfileId,
          regionIds: resolveRequestRegionIds(req),
          caseRow,
        });
        if (accessError) {
          return res.status(accessError.status).json(accessError.body);
        }
      } else if (role === 'ISET Coordinator' || role === 'ISET_Coordinator') {
        const requesterId = Number.isFinite(identity.staffProfileId) ? Number(identity.staffProfileId) : null;
        if (!Number.isFinite(requesterId)) {
          return res.status(403).json({ error: 'forbidden', detail: 'assessor_scope_missing' });
        }
        if (resolveCaseAssignedStaffProfileId(caseRow) !== requesterId) {
          return res.status(403).json({ error: 'forbidden' });
        }
      } else {
        return res.status(403).json({ error: 'forbidden' });
      }
    }

    const assessmentRow = await fetchApplicationAssessmentRow(connection, {
      caseId,
      applicationId: caseRow.application_id || null,
    });

    const caseContext = safeJsonParse(caseRow?.case_context_json, null) || null;

    let answers = {};
    if (caseRow.application_id) {
      const applicationPayload = await readApplicationPayload(connection, caseRow.application_id, { forUpdate: false });
      answers = applicationPayload?.payload?.answers || {};
    }

    const parseArray = value => {
      if (!value) return [];
      if (Array.isArray(value)) {
        return value.map(entry => normaliseString(entry)).filter(Boolean);
      }
      const parsed = safeJsonParse(value, null);
      if (Array.isArray(parsed)) {
        return parsed.map(entry => normaliseString(entry)).filter(Boolean);
      }
      if (typeof value === 'string') {
        try {
          const attempt = JSON.parse(value);
          if (Array.isArray(attempt)) {
            return attempt.map(entry => normaliseString(entry)).filter(Boolean);
          }
        } catch (_) {
          return value
            .split(',')
            .map(entry => normaliseString(entry))
            .filter(Boolean);
        }
      }
      return [];
    };

    const readAnswer = key => {
      if (!answers || typeof answers !== 'object') return null;
      const raw = answers[key];
      if (raw === null || typeof raw === 'undefined') return null;
      if (Array.isArray(raw)) {
        return raw.map(entry => normaliseString(entry)).filter(Boolean);
      }
      if (typeof raw === 'object') return raw;
      return normaliseString(raw);
    };

    const readFirstAnswer = (...keys) => {
      for (const key of keys) {
        if (!key) continue;
        const value = readAnswer(key);
        if (value !== null && typeof value !== 'undefined') {
          return value;
        }
      }
      return null;
    };

    const firstDefined = (...values) => {
      for (const value of values) {
        if (value !== undefined && value !== null) return value;
      }
      return null;
    };

    const employmentBarriers =
      parseArray(caseContext?.employmentBarriers) ||
      parseArray(assessmentRow?.employment_barriers) ||
      parseArray(readAnswer('barriers'));
    const localAreaPriorities =
      parseArray(caseContext?.localAreaPriorities) ||
      parseArray(assessmentRow?.local_area_priorities) ||
      parseArray(readAnswer('local-area-priorities'));

    const normaliseYesNo = value => {
      if (value === null || typeof value === 'undefined') return null;
      const trimmed = String(value).trim().toLowerCase();
      if (['1', 'yes', 'true'].includes(trimmed)) return 'yes';
      if (['0', 'no', 'false'].includes(trimmed)) return 'no';
      return null;
    };

    const previousIsetNormalised = normaliseYesNo(
      caseContext?.previousIset ?? assessmentRow?.previous_iset
    );
    const previousIsetBoolean = previousIsetNormalised === null ? null : previousIsetNormalised === 'yes';
    const childcareNeedNormalised = normaliseYesNo(
      caseContext?.childcareNeed ?? assessmentRow?.childcare_need
    );

    const interventionCodeValue =
      assessmentRow && assessmentRow.intervention_code !== null && typeof assessmentRow.intervention_code !== 'undefined'
        ? String(assessmentRow.intervention_code)
        : null;
    const interventionOutcomeValue =
      assessmentRow && assessmentRow.intervention_outcome_code !== null && typeof assessmentRow.intervention_outcome_code !== 'undefined'
        ? String(assessmentRow.intervention_outcome_code)
        : null;
    const interventionDurationValue =
      assessmentRow && assessmentRow.intervention_duration_days !== null && typeof assessmentRow.intervention_duration_days !== 'undefined'
        ? String(assessmentRow.intervention_duration_days)
        : null;
    const interventionCostValue =
      assessmentRow && assessmentRow.intervention_cost_total !== null && typeof assessmentRow.intervention_cost_total !== 'undefined'
        ? String(assessmentRow.intervention_cost_total)
        : null;
    const interventionNocValue =
      caseContext?.employmentNoc ||
      (assessmentRow?.intervention_related_noc ? String(assessmentRow.intervention_related_noc).trim() : null);
    const interventionNocVersionValue =
      caseContext?.employmentNocVersion ||
      (assessmentRow?.intervention_related_noc_version ? String(assessmentRow.intervention_related_noc_version).trim() : null);
    const assessmentItp = safeJsonParse(assessmentRow?.itp_payload, assessmentRow?.itp_payload ?? null);
    const assessmentWage = safeJsonParse(assessmentRow?.wage_payload, assessmentRow?.wage_payload ?? null);

    const context = {
      eligibility: normaliseString(assessmentRow?.esdc_eligibility) || null,
      employmentGoals:
        caseContext?.employmentGoals ||
        assessmentRow?.employment_goals ||
        normaliseString(readFirstAnswer('long-term-goal', 'short-term-goal', 'employment-goals')) ||
        null,
      previousIset: caseContext?.previousIset ?? previousIsetBoolean,
      previousIsetDetails: caseContext?.previousIsetDetails || assessmentRow?.previous_iset_details || null,
      employmentBarriers,
      localAreaPriorities,
      otherFunding: caseContext?.otherFunding || assessmentRow?.other_funding_details || null,
      labourForceStatus: caseContext?.employmentStatus || readFirstAnswer('labour-force-status', 'employment-status') || null,
      employmentNoc: caseContext?.employmentNoc || interventionNocValue || readFirstAnswer('action-plan-result-related-noc', 'current-noc') || null,
      employmentNocVersion: caseContext?.employmentNocVersion || interventionNocVersionValue || readFirstAnswer('action-plan-result-related-noc-version', 'current-noc-version') || null,
      educationLevel:
        caseContext?.educationLevel ||
        readFirstAnswer(
          'action-plan-result-education-level',
          'highest-education',
          'education-level',
          'education-highest-level'
        ) ||
        null,
      childcareNeed:
        caseContext?.childcareNeed ||
        childcareNeedNormalised ||
        readFirstAnswer('action-plan-childcare-need', 'childcare-need', 'childcare-required') ||
        null,
      childcareFunding:
        caseContext?.childcareFunding ||
        assessmentRow?.childcare_funding_details ||
        readFirstAnswer(
          'action-plan-childcare-funded-code',
          'childcare-funding',
          'childcare-funded',
          'childcare-supported'
        ) ||
        null,
      socialAssistance: caseContext?.socialAssistance || readFirstAnswer('social-assistance', 'receives-social-assistance') || null,
      employmentInsurance:
        caseContext?.employmentInsurance ||
        readFirstAnswer(
          'employment-insurance-status',
          'employment-insurance',
          'ei-status',
          'ei-benefits'
        ) || null,
      barriersFromApplication: Array.isArray(readAnswer('barriers'))
        ? readAnswer('barriers')
        : parseArray(readAnswer('barriers')),
      longTermGoal: normaliseString(readFirstAnswer('long-term-goal')) || null,
      shortTermGoal: normaliseString(readFirstAnswer('short-term-goal')) || null,
      targetProgram: normaliseString(readFirstAnswer('target-program')) || null,
    };

    const assessmentPayload = {
      case_summary: assessmentRow?.overview || null,
      assessment_employment_goals: caseContext?.employmentGoals || assessmentRow?.employment_goals || null,
      assessment_previous_iset: normaliseYesNo(firstDefined(caseContext?.previousIset, assessmentRow?.previous_iset)),
      assessment_previous_iset_details: caseContext?.previousIsetDetails || assessmentRow?.previous_iset_details || null,
      assessment_employment_barriers: employmentBarriers,
      assessment_employment_barriers_other_details: assessmentRow?.employment_barriers_other_details || null,
      assessment_local_area_priorities: localAreaPriorities,
      assessment_other_funding_details: caseContext?.otherFunding || assessmentRow?.other_funding_details || null,
      assessment_esdc_eligibility: normaliseString(assessmentRow?.esdc_eligibility) || null,
      assessment_intervention_start_date: assessmentRow?.intervention_start_date ? toDateOnlyString(assessmentRow.intervention_start_date) : null,
      assessment_intervention_end_date: assessmentRow?.intervention_end_date ? toDateOnlyString(assessmentRow.intervention_end_date) : null,
      assessment_intervention_code: assessmentRow && assessmentRow.intervention_code !== null && typeof assessmentRow.intervention_code !== "undefined" ? String(assessmentRow.intervention_code) : null,
      assessment_intervention_outcome_code: assessmentRow && assessmentRow.intervention_outcome_code !== null && typeof assessmentRow.intervention_outcome_code !== "undefined" ? String(assessmentRow.intervention_outcome_code) : null,
      assessment_intervention_duration_days: assessmentRow && assessmentRow.intervention_duration_days !== null && typeof assessmentRow.intervention_duration_days !== "undefined" ? String(assessmentRow.intervention_duration_days) : null,
      assessment_intervention_cost_total: assessmentRow && assessmentRow.intervention_cost_total !== null && typeof assessmentRow.intervention_cost_total !== "undefined" ? String(assessmentRow.intervention_cost_total) : null,
      assessment_intervention_related_noc: assessmentRow?.intervention_related_noc ? String(assessmentRow.intervention_related_noc).trim() : null,
      assessment_intervention_related_noc_version: assessmentRow?.intervention_related_noc_version ? String(assessmentRow.intervention_related_noc_version).trim() : null,
      assessment_childcare_need: normaliseYesNo(assessmentRow?.childcare_need),
      assessment_childcare_funding_details: assessmentRow?.childcare_funding_details || null,
      assessment_institution: assessmentRow?.institution || null,
      assessment_program_name: assessmentRow?.program_name || null,
      assessment_itp: safeJsonParse(assessmentRow?.itp_payload, assessmentRow?.itp_payload ?? null),
      assessment_wage: safeJsonParse(assessmentRow?.wage_payload, assessmentRow?.wage_payload ?? null),
      assessment_recommendation: assessmentRow?.recommendation || null,
      assessment_justification: assessmentRow?.justification || null,
    };

    res.json({ context, caseContext: caseContext || null, ...assessmentPayload });
  } catch (error) {
    console.error('GET /api/cases/:id/action-plan/context failed:', error);
    res.status(500).json({ error: 'action_plan_context_failed', detail: error?.message || String(error) });
  } finally {
    if (connection) connection.release();
  }
});

