// Mark a message as deleted
app.put('/api/admin/messages/:id/delete', async (req, res) => {
  const messageId = Number.parseInt(req.params.id, 10);
  try {
    if (!Number.isFinite(messageId) || messageId <= 0) {
      return res.status(400).json({ error: 'invalid_message_id' });
    }
    const ownerUserId = await resolveOrCreateUserIdFromAuth(req);
    if (!ownerUserId) return res.status(401).json({ error: 'unauthorized' });
    await ensureCaseMessageItemTable();
    const messageRow = await fetchCaseSecureMessageRow(messageId);
    const accessResult = await resolveCaseSecureMessageAccess(req, messageRow, { ownerUserId });
    if (accessResult.error) {
      return res.status(accessResult.error.status).json(accessResult.error.body);
    }
    if (!messageParticipantMatchesUser(messageRow, ownerUserId)) {
      return res.status(403).json({ error: 'message_mailbox_state_not_available' });
    }
    await seedCaseMessageItemForOwner({ messageId, ownerUserId });
    const [result] = await pool.query(
      `UPDATE message_item
          SET folder_before_deleted = CASE
              WHEN folder IN ('inbox','sent') THEN folder
              ELSE folder_before_deleted
            END,
            folder = 'deleted',
            deleted_at = COALESCE(deleted_at, CURRENT_TIMESTAMP)
        WHERE message_id = ? AND owner_user_id = ? AND purged_at IS NULL`,
      [messageId, ownerUserId]
    );
    if (result.affectedRows === 0) {
      return res.status(404).json({ error: 'Message not found' });
    }
    res.status(200).json({ message: 'Message deleted' });
  } catch (error) {
    console.error('Error deleting message:', error);
    res.status(500).json({ error: 'Failed to delete message' });
  }
});

// Update message status (PUT /api/admin/messages/:id/status)
app.put('/api/admin/messages/:id/status', async (req, res) => {
  const messageId = Number.parseInt(req.params.id, 10);
  const { status } = req.body;
  if (!status) {
    return res.status(400).json({ error: 'Missing status' });
  }
  try {
    if (!Number.isFinite(messageId) || messageId <= 0) {
      return res.status(400).json({ error: 'invalid_message_id' });
    }
    const ownerUserId = await resolveOrCreateUserIdFromAuth(req);
    if (!ownerUserId) return res.status(401).json({ error: 'unauthorized' });
    await ensureCaseMessageItemTable();
    const messageRow = await fetchCaseSecureMessageRow(messageId);
    const accessResult = await resolveCaseSecureMessageAccess(req, messageRow, { ownerUserId });
    if (accessResult.error) {
      return res.status(accessResult.error.status).json(accessResult.error.body);
    }
    if (!messageParticipantMatchesUser(messageRow, ownerUserId)) {
      return res.status(403).json({ error: 'message_mailbox_state_not_available' });
    }
    await seedCaseMessageItemForOwner({ messageId, ownerUserId });

    const statusValue = String(status).trim().toLowerCase();
    if (!['unread', 'read', 'replied', 'archived', 'deleted'].includes(statusValue)) {
      return res.status(400).json({ error: 'invalid_status' });
    }

    if (statusValue === 'read' || statusValue === 'replied') {
      await pool.query(
        `UPDATE message_item
            SET read_at = COALESCE(read_at, CURRENT_TIMESTAMP)
          WHERE message_id = ? AND owner_user_id = ? AND purged_at IS NULL`,
        [messageId, ownerUserId]
      );
    } else if (statusValue === 'unread') {
      await pool.query(
        `UPDATE message_item
            SET read_at = NULL
          WHERE message_id = ? AND owner_user_id = ? AND folder = 'inbox' AND purged_at IS NULL`,
        [messageId, ownerUserId]
      );
    } else if (statusValue === 'archived' || statusValue === 'deleted') {
      await pool.query(
        `UPDATE message_item
            SET folder_before_deleted = CASE
                WHEN folder IN ('inbox','sent') THEN folder
                ELSE folder_before_deleted
              END,
              folder = 'deleted',
              deleted_at = COALESCE(deleted_at, CURRENT_TIMESTAMP)
          WHERE message_id = ? AND owner_user_id = ? AND purged_at IS NULL`,
        [messageId, ownerUserId]
      );
    }

    if (statusValue === 'read' || statusValue === 'replied' || statusValue === 'unread') {
      await pool.query(
        `UPDATE messages
            SET status = ?
          WHERE id = ?
            AND recipient_user_id = ?`,
        [statusValue, messageId, ownerUserId]
      );
    }
    res.status(200).json({ message: 'Status updated' });
  } catch (error) {
    console.error('Error updating message status:', error);
    res.status(500).json({ error: 'Failed to update message status' });
  }
});

// --- Staff-to-staff secure messaging (internal) -----------------------------
// Schema lives in sql/20251218_create_staff_messaging_tables.sql
// Routes below intentionally avoid /api/admin/messages, which is already used for applicant/case messaging.

const STAFF_MESSAGE_FOLDERS = new Set(['inbox', 'sent', 'deleted']);
const CASE_MESSAGE_FOLDERS = new Set(['inbox', 'sent', 'deleted']);
let __caseMessageItemTableReady = false;

function normaliseStaffProfileSummaryRow(row) {
  if (!row) return null;
  const displayName = row.display_name || row.name || row.email || null;
  return {
    staff_profile_id: row.id,
    display_name: displayName,
    primary_role: row.primary_role || null,
    email: row.email || null,
  };
}

function truncatePreview(value, maxLen = 160) {
  if (!value) return '';
  const text = String(value).replace(/\s+/g, ' ').trim();
  if (!text) return '';
  if (text.length <= maxLen) return text;
  return `${text.slice(0, Math.max(0, maxLen - 1))}…`;
}

function normaliseStaffMessageFolder(raw) {
  const value = String(raw || '').trim().toLowerCase();
  return STAFF_MESSAGE_FOLDERS.has(value) ? value : null;
}

function normaliseCaseMessageFolder(raw) {
  const value = String(raw || '').trim().toLowerCase();
  return CASE_MESSAGE_FOLDERS.has(value) ? value : null;
}

async function ensureCaseMessageItemTable(connection = pool) {
  if (__caseMessageItemTableReady) return;
  await connection.query(`CREATE TABLE IF NOT EXISTS message_item (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    message_id INT NOT NULL,
    owner_user_id INT NOT NULL,
    folder ENUM('inbox','sent','deleted') NOT NULL,
    folder_before_deleted ENUM('inbox','sent') NULL,
    read_at DATETIME NULL,
    deleted_at DATETIME NULL,
    purged_at DATETIME NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uniq_message_owner (message_id, owner_user_id),
    KEY idx_message_item_owner_folder (owner_user_id, folder, purged_at),
    KEY idx_message_item_message (message_id)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;`);
  __caseMessageItemTableReady = true;
}

async function seedCaseMessageItemForOwner({ runner = pool, messageId, ownerUserId }) {
  const numericMessageId = Number(messageId);
  const numericOwnerUserId = Number(ownerUserId);
  if (!Number.isFinite(numericMessageId) || numericMessageId <= 0) return false;
  if (!Number.isFinite(numericOwnerUserId) || numericOwnerUserId <= 0) return false;
  await ensureCaseMessageItemTable(runner);
  const [result] = await runner.query(
    `INSERT IGNORE INTO message_item (message_id, owner_user_id, folder, folder_before_deleted, read_at, deleted_at, purged_at)
     SELECT
       m.id,
       ?,
       CASE
         WHEN COALESCE(m.deleted, 0) = 1 THEN 'deleted'
         WHEN m.sender_user_id = ? THEN 'sent'
         ELSE 'inbox'
       END AS folder,
       CASE
         WHEN COALESCE(m.deleted, 0) = 1
           THEN CASE WHEN m.sender_user_id = ? THEN 'sent' ELSE 'inbox' END
         ELSE NULL
       END AS folder_before_deleted,
       CASE
         WHEN m.sender_user_id = ? THEN COALESCE(m.created_at, NOW())
         WHEN LOWER(COALESCE(m.status, '')) IN ('read', 'replied') THEN COALESCE(m.created_at, NOW())
         ELSE NULL
       END AS read_at,
       CASE WHEN COALESCE(m.deleted, 0) = 1 THEN COALESCE(m.created_at, NOW()) ELSE NULL END AS deleted_at,
       NULL AS purged_at
     FROM messages m
    WHERE m.id = ?
      AND (m.sender_user_id = ? OR m.recipient_user_id = ?)`,
    [
      numericOwnerUserId,
      numericOwnerUserId,
      numericOwnerUserId,
      numericOwnerUserId,
      numericMessageId,
      numericOwnerUserId,
      numericOwnerUserId,
    ]
  );
  return Boolean(result?.affectedRows);
}

async function fetchCaseSecureMessageRow(messageId, connection = pool) {
  const numericMessageId = normalisePositiveInteger(messageId);
  if (!numericMessageId) return null;
  const [[row]] = await connection.query(
    `SELECT id,
            case_id,
            application_id,
            sender_actor_type,
            sender_user_id,
            sender_staff_profile_id,
            recipient_actor_type,
            recipient_user_id,
            recipient_staff_profile_id
       FROM messages
      WHERE id = ?
      LIMIT 1`,
    [numericMessageId]
  );
  return row || null;
}

function messageParticipantMatchesUser(messageRow, userId) {
  const numericUserId = normalisePositiveInteger(userId);
  if (!messageRow || !numericUserId) return false;
  return (
    Number(messageRow.sender_user_id) === Number(numericUserId) ||
    Number(messageRow.recipient_user_id) === Number(numericUserId)
  );
}

function messageActorMatchesUser(messageRow, prefix, actorType, userId) {
  const numericUserId = normalisePositiveInteger(userId);
  if (!messageRow || !numericUserId || !prefix || !actorType) return false;
  return (
    String(messageRow[`${prefix}_actor_type`] || '') === actorType &&
    Number(messageRow[`${prefix}_user_id`]) === Number(numericUserId)
  );
}

function buildSecureMessageActorResponse(messageRow, prefix) {
  const actorType = normaliseString(messageRow?.[`${prefix}_actor_type`] || null) || null;
  const userId = normalisePositiveInteger(messageRow?.[`${prefix}_user_id`]);
  const staffProfileId = normalisePositiveInteger(messageRow?.[`${prefix}_staff_profile_id`]);
  return {
    actorType,
    actor_type: actorType,
    userId,
    user_id: userId,
    staffProfileId,
    staff_profile_id: staffProfileId,
    applicantUserId: actorType === 'applicant_user' ? userId : null,
    applicant_user_id: actorType === 'applicant_user' ? userId : null,
  };
}

function buildSecureMessageThreadResponse(messageRow, { applicantUserId = null } = {}) {
  const caseId = normalisePositiveInteger(messageRow?.case_id);
  const applicationId = normalisePositiveInteger(messageRow?.application_id);
  const resolvedApplicantUserId = normalisePositiveInteger(applicantUserId);
  return {
    type: 'case_application',
    caseId,
    case_id: caseId,
    applicationId,
    application_id: applicationId,
    applicantUserId: resolvedApplicantUserId,
    applicant_user_id: resolvedApplicantUserId,
  };
}

function mapCaseSecureMessageResponse(row, { applicantUserId = null } = {}) {
  const sender = buildSecureMessageActorResponse(row, 'sender');
  const recipient = buildSecureMessageActorResponse(row, 'recipient');
  const thread = buildSecureMessageThreadResponse(row, { applicantUserId });
  const applicantId = normalisePositiveInteger(applicantUserId);
  const applicantIsSender =
    applicantId &&
    sender.actorType === 'applicant_user' &&
    Number(sender.userId) === Number(applicantId);
  const applicantIsRecipient =
    applicantId &&
    recipient.actorType === 'applicant_user' &&
    Number(recipient.userId) === Number(applicantId);
  return {
    ...row,
    sender,
    recipient,
    thread,
    senderActor: sender,
    recipientActor: recipient,
    messageThread: thread,
    applicantActorRole: applicantIsSender ? 'sender' : applicantIsRecipient ? 'recipient' : null,
    direction: applicantIsSender ? 'received' : applicantIsRecipient ? 'sent' : null,
  };
}

async function resolveCaseSecureMessageAccess(req, messageRow, {
  requestedCaseId = null,
  ownerUserId = null,
  requireCaseScope = false,
  connection = pool,
} = {}) {
  if (!messageRow) {
    return { error: { status: 404, body: { error: 'message_not_found' } } };
  }

  const messageCaseId = normalisePositiveInteger(messageRow.case_id);
  const queryCaseId = normalisePositiveInteger(requestedCaseId);
  if (messageCaseId && queryCaseId && messageCaseId !== queryCaseId) {
    return { error: { status: 400, body: { error: 'message_case_mismatch' } } };
  }

  const effectiveCaseId = messageCaseId || queryCaseId;
  if (effectiveCaseId) {
    const accessError = await validateCaseAccessByCaseId(req, effectiveCaseId, connection);
    if (accessError) {
      return { error: accessError };
    }

    const applicantContext = await resolveCaseApplicantMessagingContext(effectiveCaseId);
    if (applicantContext?.applicant_resolution_conflict) {
      return { error: { status: 409, body: { error: 'applicant_identity_conflict' } } };
    }
    const applicantUserId = normalisePositiveInteger(applicantContext?.applicant_user_id);
    if (!messageCaseId) {
      const messageApplicationId = normalisePositiveInteger(messageRow.application_id);
      const caseApplicationId = normalisePositiveInteger(applicantContext?.application_id);
      if (messageApplicationId && caseApplicationId && messageApplicationId !== caseApplicationId) {
        return { error: { status: 403, body: { error: 'forbidden', detail: 'message_application_scope_mismatch' } } };
      }
      const messageMatchesCaseApplicant =
        applicantUserId &&
        (messageActorMatchesUser(messageRow, 'sender', 'applicant_user', applicantUserId) ||
          messageActorMatchesUser(messageRow, 'recipient', 'applicant_user', applicantUserId));
      if (!messageMatchesCaseApplicant && !messageParticipantMatchesUser(messageRow, ownerUserId)) {
        return { error: { status: 403, body: { error: 'forbidden', detail: 'message_case_scope_mismatch' } } };
      }
    }

    return {
      caseId: effectiveCaseId,
      applicationId:
        normalisePositiveInteger(applicantContext?.application_id) ||
        normalisePositiveInteger(messageRow.application_id),
      applicantUserId,
    };
  }

  if (messageParticipantMatchesUser(messageRow, ownerUserId)) {
    return {
      caseId: null,
      applicationId: normalisePositiveInteger(messageRow.application_id),
      applicantUserId: null,
    };
  }

  return {
    error: {
      status: requireCaseScope ? 400 : 403,
      body: {
        error: requireCaseScope ? 'message_case_scope_required' : 'forbidden',
        detail: 'message_scope_mismatch',
      },
    },
  };
}

app.get('/api/me/staff-profiles', async (req, res) => {
  try {
    const limitRaw = Number.parseInt(String(req.query.limit || '50'), 10);
    const limit = Number.isFinite(limitRaw) ? Math.min(Math.max(limitRaw, 1), 250) : 50;
    const q = typeof req.query.q === 'string' ? req.query.q.trim() : '';
    const like = q ? `%${q}%` : null;

    const where = ["COALESCE(sp.status, 'active') = 'active'"];
    const params = [];
    if (like) {
      where.push('(sp.display_name LIKE ? OR sp.name LIKE ? OR sp.email LIKE ?)');
      params.push(like, like, like);
    }
    params.push(limit);

    const [rows] = await pool.query(
      `SELECT sp.id, sp.display_name, sp.name, sp.email, sp.primary_role, sp.region_id, cr.code AS region_code
         FROM staff_profiles sp
         LEFT JOIN canada_region cr ON cr.region_id = sp.region_id
        WHERE ${where.join(' AND ')}
        ORDER BY COALESCE(sp.display_name, sp.name, sp.email, CAST(sp.id AS CHAR)) ASC
        LIMIT ?`,
      params
    );

    const items = (rows || [])
      .map((row) => {
        const summary = normaliseStaffProfileSummaryRow(row);
        if (!summary) return null;
        return {
          id: summary.staff_profile_id,
          displayName: summary.display_name,
          primaryRole: summary.primary_role,
          email: summary.email,
          regionCode: row.region_code || null,
          regionId: row.region_id ?? null,
        };
      })
      .filter(Boolean);

    return res.json({ items });
  } catch (err) {
    console.error('[staff-messages] GET /api/me/staff-profiles failed:', err.message);
    return res.status(500).json({ error: 'failed_to_list_staff_profiles' });
  }
});

app.get('/api/me/staff-messages', async (req, res) => {
  try {
    const staffProfileId = resolveActiveStaffProfileId(req);
    if (!staffProfileId) {
      return res.status(401).json({ error: 'staff_profile_required' });
    }

    const folder = normaliseStaffMessageFolder(req.query.folder || 'inbox');
    if (!folder) {
      return res.status(400).json({ error: 'invalid_folder', allowed: Array.from(STAFF_MESSAGE_FOLDERS) });
    }

    const limitRaw = Number.parseInt(String(req.query.limit || '100'), 10);
    const offsetRaw = Number.parseInt(String(req.query.offset || '0'), 10);
    const limit = Number.isFinite(limitRaw) ? Math.min(Math.max(limitRaw, 1), 250) : 100;
    const offset = Number.isFinite(offsetRaw) ? Math.max(offsetRaw, 0) : 0;

    const q = typeof req.query.q === 'string' ? req.query.q.trim() : '';
    const like = q ? `%${q}%` : null;

    const where = [
      'smi.owner_staff_profile_id = ?',
      'smi.folder = ?',
      'smi.purged_at IS NULL',
    ];
    const params = [staffProfileId, folder];

    if (like) {
      where.push('(smt.subject LIKE ? OR sm.body LIKE ? OR sender.display_name LIKE ? OR sender.name LIKE ? OR sender.email LIKE ?)');
      params.push(like, like, like, like, like);
    }

    params.push(limit, offset);

    const [rows] = await pool.query(
      `SELECT
          smi.id AS item_id,
          smi.owner_staff_profile_id AS owner_staff_profile_id,
          smi.folder AS folder,
          smi.folder_before_deleted AS folder_before_deleted,
          smi.read_at AS read_at,
          smi.deleted_at AS deleted_at,
          smi.purged_at AS purged_at,
          sm.id AS message_id,
          sm.thread_id AS thread_id,
          sm.sender_staff_profile_id AS sender_staff_profile_id,
          sm.body AS body,
          sm.created_at AS created_at,
          smt.subject AS subject,
          sender.id AS sender_id,
          sender.display_name AS sender_display_name,
          sender.name AS sender_name,
          sender.email AS sender_email,
          sender.primary_role AS sender_primary_role
        FROM staff_message_item smi
        JOIN staff_message sm ON sm.id = smi.message_id
        JOIN staff_message_thread smt ON smt.id = sm.thread_id
        LEFT JOIN staff_profiles sender ON sender.id = sm.sender_staff_profile_id
       WHERE ${where.join(' AND ')}
       ORDER BY sm.created_at DESC
       LIMIT ? OFFSET ?`,
      params
    );

    const messageIds = (rows || [])
      .map((row) => Number(row.message_id))
      .filter((id) => Number.isFinite(id) && id > 0);
    const uniqueMessageIds = Array.from(new Set(messageIds));

    let recipientsByMessage = new Map();
    if (uniqueMessageIds.length) {
      const placeholders = uniqueMessageIds.map(() => '?').join(',');
      const [recipientRows] = await pool.query(
        `SELECT
            smi.message_id,
            sp.id,
            sp.display_name,
            sp.name,
            sp.email,
            sp.primary_role
          FROM staff_message_item smi
          JOIN staff_profiles sp ON sp.id = smi.owner_staff_profile_id
          JOIN staff_message sm ON sm.id = smi.message_id
         WHERE smi.message_id IN (${placeholders})
           AND smi.owner_staff_profile_id <> sm.sender_staff_profile_id
         ORDER BY smi.message_id ASC, COALESCE(sp.display_name, sp.name, sp.email, CAST(sp.id AS CHAR)) ASC`,
        uniqueMessageIds
      );
      recipientsByMessage = (recipientRows || []).reduce((map, row) => {
        const messageId = Number(row.message_id);
        if (!Number.isFinite(messageId)) return map;
        if (!map.has(messageId)) map.set(messageId, []);
        const summary = normaliseStaffProfileSummaryRow(row);
        if (summary) {
          map.get(messageId).push({
            staffProfileId: summary.staff_profile_id,
            displayName: summary.display_name,
            primaryRole: summary.primary_role,
            email: summary.email,
          });
        }
        return map;
      }, new Map());
    }

    const items = (rows || []).map((row) => {
      const senderProfile = normaliseStaffProfileSummaryRow({
        id: row.sender_id || row.sender_staff_profile_id || null,
        display_name: row.sender_display_name || null,
        name: row.sender_name || null,
        email: row.sender_email || null,
        primary_role: row.sender_primary_role || null,
      });
      const sender = senderProfile
        ? {
          staffProfileId: senderProfile.staff_profile_id,
          displayName: senderProfile.display_name,
          primaryRole: senderProfile.primary_role,
          email: senderProfile.email,
        }
        : null;
      const threadId = Number(row.thread_id);
      const messageId = Number(row.message_id);
      const recipients = recipientsByMessage.get(messageId) || [];
      const participantById = new Map();
      if (sender?.staffProfileId) {
        participantById.set(String(sender.staffProfileId), sender);
      }
      for (const recipient of recipients) {
        if (!recipient?.staffProfileId) continue;
        participantById.set(String(recipient.staffProfileId), recipient);
      }
      const participants = Array.from(participantById.values());
      const createdAt = row.created_at instanceof Date ? row.created_at.toISOString() : (row.created_at ? String(row.created_at) : null);
      const readAt = row.read_at instanceof Date ? row.read_at.toISOString() : (row.read_at ? String(row.read_at) : null);
      return {
        id: Number(row.item_id),
        messageId: Number(row.message_id),
        threadId,
        ownerStaffProfileId: Number(row.owner_staff_profile_id),
        folder: row.folder,
        deletedFrom: row.folder_before_deleted || null,
        unread: row.folder === 'inbox' && !row.read_at,
        receivedAt: createdAt,
        readAt,
        subject: row.subject || '(No subject)',
        body: row.body || '',
        preview: truncatePreview(row.body || ''),
        sender,
        recipients,
        participants,
      };
    });

    return res.json({
      folder,
      items,
      viewer: { staffProfileId },
    });
  } catch (err) {
    console.error('[staff-messages] GET /api/me/staff-messages failed:', err.message);
    return res.status(500).json({ error: 'failed_to_list_staff_messages' });
  }
});

app.get('/api/me/staff-messages/counts', async (req, res) => {
  try {
    const staffProfileId = resolveActiveStaffProfileId(req);
    if (!staffProfileId) {
      return res.status(401).json({ error: 'staff_profile_required' });
    }
    const [rows] = await pool.query(
      `SELECT folder,
              COUNT(*) AS total,
              SUM(CASE WHEN read_at IS NULL AND folder = 'inbox' THEN 1 ELSE 0 END) AS unread
         FROM staff_message_item
        WHERE owner_staff_profile_id = ? AND purged_at IS NULL
        GROUP BY folder`,
      [staffProfileId]
    );
    const counts = { inbox: { total: 0, unread: 0 }, sent: { total: 0, unread: 0 }, deleted: { total: 0, unread: 0 } };
    for (const row of rows || []) {
      const folder = row.folder;
      if (!counts[folder]) continue;
      counts[folder].total = Number(row.total) || 0;
      counts[folder].unread = Number(row.unread) || 0;
    }
    return res.json(counts);
  } catch (err) {
    console.error('[staff-messages] GET /api/me/staff-messages/counts failed:', err.message);
    return res.status(500).json({ error: 'failed_to_fetch_counts' });
  }
});

app.post('/api/me/staff-messages', async (req, res) => {
  let connection;
  try {
    const staffProfileId = resolveActiveStaffProfileId(req);
    if (!staffProfileId) {
      return res.status(401).json({ error: 'staff_profile_required' });
    }
    const senderStaffProfileId = Number(staffProfileId);

    const body = req.body || {};
    const threadIdRaw = body.threadId ?? body.thread_id ?? null;
    const threadId = threadIdRaw === null || typeof threadIdRaw === 'undefined' ? null : Number(threadIdRaw);
    if (threadId !== null && (!Number.isFinite(threadId) || threadId <= 0)) {
      return res.status(400).json({ error: 'invalid_thread_id' });
    }

    const subjectValue = typeof body.subject === 'string' ? body.subject.trim() : '';
    const bodyValue = typeof body.body === 'string' ? body.body.trim() : '';
    if (!bodyValue) {
      return res.status(400).json({ error: 'message_body_required' });
    }

    const rawRecipients = body.toStaffProfileIds ?? body.to_staff_profile_ids ?? body.recipients ?? body.to ?? [];
    const recipientIds = Array.from(new Set(
      (Array.isArray(rawRecipients) ? rawRecipients : [rawRecipients])
        .map((value) => Number(value))
        .filter((value) => Number.isFinite(value) && value > 0 && value !== senderStaffProfileId)
    ));
    if (!recipientIds.length) {
      return res.status(400).json({ error: 'recipients_required' });
    }

    connection = await pool.getConnection();
    await connection.beginTransaction();

    let effectiveThreadId = threadId;
    let threadSubject = null;
    const threadParticipantIds = Array.from(new Set([senderStaffProfileId, ...recipientIds]));

    if (effectiveThreadId) {
      const [[threadRow]] = await connection.query(
        'SELECT id, subject FROM staff_message_thread WHERE id = ? LIMIT 1 FOR UPDATE',
        [effectiveThreadId]
      );
      if (!threadRow) {
        await connection.rollback();
        return res.status(404).json({ error: 'thread_not_found' });
      }
      threadSubject = threadRow.subject || null;

      const [[membershipRow]] = await connection.query(
        `SELECT 1 AS is_participant
           FROM staff_message_thread_participant
          WHERE thread_id = ? AND staff_profile_id = ?
          LIMIT 1`,
        [effectiveThreadId, senderStaffProfileId]
      );
      if (!membershipRow) {
        await connection.rollback();
        return res.status(403).json({ error: 'thread_access_denied' });
      }

      const valuesSql = threadParticipantIds.map(() => '(?, ?)').join(',');
      const values = threadParticipantIds.flatMap((id) => [effectiveThreadId, id]);
      await connection.query(
        `INSERT IGNORE INTO staff_message_thread_participant (thread_id, staff_profile_id) VALUES ${valuesSql}`,
        values
      );

      if (!threadSubject && subjectValue) {
        await connection.query('UPDATE staff_message_thread SET subject = ? WHERE id = ?', [subjectValue, effectiveThreadId]);
        threadSubject = subjectValue;
      }
    } else {
      const [result] = await connection.query(
        'INSERT INTO staff_message_thread (subject, created_by_staff_profile_id) VALUES (?, ?)',
        [subjectValue || null, senderStaffProfileId]
      );
      effectiveThreadId = result.insertId;
      threadSubject = subjectValue || null;
      const valuesSql = threadParticipantIds.map(() => '(?, ?)').join(',');
      const values = threadParticipantIds.flatMap((id) => [effectiveThreadId, id]);
      await connection.query(
        `INSERT INTO staff_message_thread_participant (thread_id, staff_profile_id) VALUES ${valuesSql}`,
        values
      );
    }

    const [msgResult] = await connection.query(
      'INSERT INTO staff_message (thread_id, sender_staff_profile_id, body, metadata_json) VALUES (?, ?, ?, NULL)',
      [effectiveThreadId, senderStaffProfileId, bodyValue]
    );
    const messageId = msgResult.insertId;

    await connection.query('UPDATE staff_message_thread SET updated_at = CURRENT_TIMESTAMP WHERE id = ?', [effectiveThreadId]);

    const now = new Date();
    const deliveryIds = Array.from(new Set([senderStaffProfileId, ...recipientIds]));
    const itemValuesSql = deliveryIds.map(() => '(?, ?, ?, ?, NULL, NULL)').join(',');
    const itemValues = deliveryIds.flatMap((participantId) => ([
      messageId,
      participantId,
      participantId === senderStaffProfileId ? 'sent' : 'inbox',
      participantId === senderStaffProfileId ? now : null,
    ]));
    await connection.query(
      `INSERT INTO staff_message_item (message_id, owner_staff_profile_id, folder, read_at, deleted_at, purged_at)
       VALUES ${itemValuesSql}`,
      itemValues
    );

    await connection.commit();

    // Return the sender's mailbox item (suitable for UI insert)
    const [[senderItem]] = await pool.query(
      `SELECT smi.id AS item_id
         FROM staff_message_item smi
        WHERE smi.message_id = ? AND smi.owner_staff_profile_id = ?
        LIMIT 1`,
      [messageId, senderStaffProfileId]
    );
    return res.status(201).json({
      ok: true,
      threadId: effectiveThreadId,
      messageId,
      itemId: senderItem?.item_id ? Number(senderItem.item_id) : null,
      subject: threadSubject || subjectValue || '(No subject)',
    });
  } catch (err) {
    if (connection) {
      try { await connection.rollback(); } catch {}
    }
    console.error('[staff-messages] POST /api/me/staff-messages failed:', err.message);
    return res.status(500).json({ error: 'failed_to_send_staff_message' });
  } finally {
    if (connection) connection.release();
  }
});

