const PAYMENT_SUBMISSION_TIMING_DEFAULTS = {
  LivingAllowance: 'recurrence_schedule',
  TuitionFeesDirect: 'intervention_start',
  TuitionFeesReimbursement: 'intervention_end',
  SpecializedEquipmentAdvance: 'intervention_start',
  SpecializedEquipmentReimbursement: 'intervention_end',
  WageSubsidyEmployer: 'recurrence_schedule',
  Childcare: 'recurrence_schedule',
  Transportation: 'recurrence_schedule',
  BooksMaterialsDirect: 'intervention_start',
  BooksMaterialsReimbursement: 'intervention_end',
  JCPProjectCost: 'manual_trigger',
  SEBSupport: 'recurrence_schedule',
  OtherEligibleCost: 'manual_trigger',
};

const normalizePaymentSubmissionTiming = value => {
  if (typeof value !== 'string') return null;
  const normalized = value.trim().toLowerCase().replace(/[\s-]+/g, '_');
  if (normalized === 'intervention_start') return 'intervention_start';
  if (normalized === 'intervention_end') return 'intervention_end';
  if (normalized === 'recurrence_schedule') return 'recurrence_schedule';
  if (normalized === 'manual_trigger') return 'manual_trigger';
  return null;
};

const normalizePaymentTypeMappingEntry = entry => {
  if (!entry || typeof entry !== 'object') return null;
  const code = normalizePaymentTypeCode(
    entry.code ?? entry.value ?? entry.paymentType ?? entry.payment_type ?? null
  );
  if (!code) return null;
  const labelRaw = entry.label ?? entry.name ?? null;
  const label = typeof labelRaw === 'string' && labelRaw.trim() ? labelRaw.trim() : code;
  const notesRaw = entry.notes ?? entry.note ?? null;
  const notes = typeof notesRaw === 'string' && notesRaw.trim() ? notesRaw.trim() : '';
  const submissionTiming =
    normalizePaymentSubmissionTiming(
      entry.submissionTiming ??
        entry.submission_timing ??
        entry.schedulePolicy ??
        entry.schedule_policy ??
        null
    ) ||
    PAYMENT_SUBMISSION_TIMING_DEFAULTS[code] ||
    'manual_trigger';
  return { code, label, notes, submissionTiming };
};

const normalizePaymentInterventionMappingEntry = entry => {
  if (!entry || typeof entry !== 'object') return null;
  const code = normalizeInterventionCodeValue(
    entry.code ?? entry.interventionCode ?? entry.intervention_code ?? null
  );
  if (!code) return null;
  const nameRaw = entry.name ?? entry.label ?? null;
  const name = typeof nameRaw === 'string' && nameRaw.trim() ? nameRaw.trim() : null;
  const listRaw =
    entry.availablePaymentTypes ||
    entry.available_payment_types ||
    entry.paymentTypes ||
    entry.payment_types ||
    [];
  const list = Array.isArray(listRaw)
    ? listRaw
    : typeof listRaw === 'string'
      ? listRaw
          .split(',')
          .map(item => item.trim())
          .filter(Boolean)
      : [];
  const normalizedList = Array.from(
    new Set(list.map(normalizePaymentTypeCode).filter(Boolean))
  );
  const defaultOnAssessmentRaw =
    entry.defaultOnAssessment ??
    entry.default_on_assessment ??
    entry.defaultInAssessment ??
    entry.default_in_assessment ??
    entry.defaultOnApplicationAssessment ??
    entry.default_on_application_assessment;
  const defaultOnAssessment = normalizeBooleanLike(defaultOnAssessmentRaw) === true;
  return {
    code,
    name,
    availablePaymentTypes: normalizedList,
    defaultOnAssessment,
  };
};

const buildInterventionPaymentTypeLookup = interventions => {
  const map = new Map();
  if (!Array.isArray(interventions)) return map;
  interventions.forEach(entry => {
    const code = normalizeInterventionCodeValue(entry?.code);
    if (!code) return;
    const types = Array.isArray(entry.availablePaymentTypes)
      ? entry.availablePaymentTypes
      : [];
    const normalizedTypes = Array.from(
      new Set(types.map(normalizePaymentTypeCode).filter(Boolean))
    );
    map.set(code, new Set(normalizedTypes));
  });
  return map;
};

const normalizePaymentInterventionMapping = raw => {
  if (!raw || typeof raw !== 'object') return null;
  const version = typeof raw.version === 'string' ? raw.version.trim() : null;
  const generatedOn =
    typeof raw.generated_on === 'string'
      ? raw.generated_on.trim()
      : typeof raw.generatedOn === 'string'
        ? raw.generatedOn.trim()
        : null;
  const notes = Array.isArray(raw.notes)
    ? raw.notes.map(note => (typeof note === 'string' ? note.trim() : '')).filter(Boolean)
    : [];
  const paymentTypesRaw = raw.payment_types || raw.paymentTypes || [];
  const paymentTypes = Array.isArray(paymentTypesRaw)
    ? paymentTypesRaw.map(normalizePaymentTypeMappingEntry).filter(Boolean)
    : [];
  const interventionsRaw = raw.interventions || [];
  const interventionsMap = new Map();
  if (Array.isArray(interventionsRaw)) {
    interventionsRaw.forEach(entry => {
      const normalized = normalizePaymentInterventionMappingEntry(entry);
      if (!normalized) return;
      interventionsMap.set(normalized.code, normalized);
    });
  }
  const interventions = Array.from(interventionsMap.values()).sort((a, b) => {
    const aNum = Number(a.code);
    const bNum = Number(b.code);
    if (Number.isFinite(aNum) && Number.isFinite(bNum)) {
      return aNum - bNum;
    }
    return String(a.code).localeCompare(String(b.code));
  });
  if (!paymentTypes.length && !interventions.length) return null;
  const mapping = {
    version: version || null,
    generatedOn: generatedOn || null,
    notes,
    paymentTypes,
    interventions,
  };
  mapping.allowedByIntervention = buildInterventionPaymentTypeLookup(interventions);
  return mapping;
};

const serializePaymentInterventionMapping = mapping => {
  if (!mapping || typeof mapping !== 'object') return null;
  const { allowedByIntervention, ...rest } = mapping;
  return rest;
};

const normalizePaymentPayeeTypeOption = entry => {
  if (!entry || typeof entry !== 'object') return null;
  const codeRaw = entry.code ?? entry.value ?? entry.payeeType ?? entry.payee_type ?? null;
  const code = typeof codeRaw === 'string' ? codeRaw.trim() : codeRaw === null || codeRaw === undefined ? '' : String(codeRaw).trim();
  if (!code) return null;
  const labelRaw = entry.label ?? entry.name ?? null;
  const label = typeof labelRaw === 'string' && labelRaw.trim() ? labelRaw.trim() : code;
  const descriptionRaw = entry.description ?? entry.helpText ?? entry.help_text ?? null;
  const description = typeof descriptionRaw === 'string' && descriptionRaw.trim() ? descriptionRaw.trim() : '';
  return { code, label, description };
};

const normalizePaymentPayeeTypeOptions = raw => {
  const list = Array.isArray(raw)
    ? raw
    : Array.isArray(raw?.payeeTypes)
      ? raw.payeeTypes
      : Array.isArray(raw?.payee_types)
        ? raw.payee_types
        : [];
  const map = new Map();
  list.forEach(entry => {
    const normalized = normalizePaymentPayeeTypeOption(entry);
    if (!normalized) return;
    map.set(normalized.code.toLowerCase(), normalized);
  });
  return Array.from(map.values());
};

