async function fetchLatestBatchInfoForLines({ lineIds, connection = null }) {
  const runner = connection || pool;
  const uniqueIds = Array.from(new Set((lineIds || []).map(id => Number(id)).filter(Number.isFinite)));
  if (!uniqueIds.length) return new Map();
  try {
    const [rows] = await runner.query(
      `SELECT pbl.payment_packet_line_id,
              pb.id AS batch_id,
              pb.status AS batch_status,
              pb.created_by_user_id,
              pb.approved_by_user_id,
              pb.approved_at,
              pb.exported_at,
              creator.name AS created_by_name,
              creator.email AS created_by_email,
              approver.name AS approved_by_name,
              approver.email AS approved_by_email
         FROM payment_batch_line pbl
         LEFT JOIN payment_batch pb ON pb.id = pbl.payment_batch_id
         LEFT JOIN user creator ON creator.id = pb.created_by_user_id
         LEFT JOIN user approver ON approver.id = pb.approved_by_user_id
        WHERE pbl.payment_packet_line_id IN (${uniqueIds.map(() => '?').join(',')})
        ORDER BY pb.id DESC`,
      uniqueIds
    );
    const map = new Map();
    (rows || []).forEach(row => {
      const lineId = row?.payment_packet_line_id ? String(row.payment_packet_line_id) : null;
      if (!lineId || map.has(lineId)) return;
      map.set(lineId, mapPaymentLineBatchInfo(row));
    });
    return map;
  } catch (err) {
    if (!isMissingTableErrorLocal(err)) {
      throw err;
    }
    return new Map();
  }
}

async function hydratePaymentPackets(packetRows, connection = null, options = {}) {
  if (!Array.isArray(packetRows) || packetRows.length === 0) return [];
  const runner = connection || pool;
  const includeAuthorization = options?.includeAuthorization === true;
  const packetIds = Array.from(
    new Set(
      packetRows
        .map(row => Number(row.id))
        .filter(Number.isFinite)
    )
  );
  if (!packetIds.length) return [];
  const placeholders = packetIds.map(() => '?').join(',');

  const [lineRows] = await runner.query(
    `SELECT ppl.*, bp.name AS pot_name, bp.funding_source AS pot_funding_source
       FROM payment_packet_line ppl
       LEFT JOIN budget_pot bp ON bp.id = ppl.budget_pot_id
      WHERE ppl.payment_packet_id IN (${placeholders})
      ORDER BY ppl.payment_packet_id ASC, ppl.id ASC`,
    packetIds
  );

  const [docRows] = await runner.query(
    `SELECT ppd.*, d.file_name, d.label, d.document_category,
            u.name AS verified_by_name,
            u.email AS verified_by_email
       FROM payment_packet_document ppd
       LEFT JOIN iset_document d ON d.id = ppd.document_id
       LEFT JOIN user u ON u.id = ppd.verified_by_user_id
      WHERE ppd.payment_packet_id IN (${placeholders})
      ORDER BY ppd.payment_packet_id ASC, ppd.id ASC`,
    packetIds
  );

  const [eventRows] = await runner.query(
    `SELECT pse.*, u.name AS actor_name, u.email AS actor_email
       FROM payment_status_event pse
       LEFT JOIN user u ON u.id = pse.actor_user_id
      WHERE pse.payment_packet_id IN (${placeholders})
      ORDER BY pse.payment_packet_id ASC, pse.created_at ASC`,
    packetIds
  );

  const [followUpRows] = await runner.query(
    `SELECT pfe.*, u.name AS actor_name, u.email AS actor_email
       FROM payment_followup_event pfe
       LEFT JOIN user u ON u.id = pfe.actor_user_id
      WHERE pfe.payment_packet_id IN (${placeholders})
      ORDER BY pfe.payment_packet_id ASC, pfe.created_at ASC, pfe.id ASC`,
    packetIds
  );

  const evidenceRules = await readPaymentEvidenceRules(runner);
  const packets = [];
  const packetMap = new Map();
  const lineMap = new Map();
  const documentsMap = new Map();
  const batchInfoMap = await fetchLatestBatchInfoForLines({
    lineIds: lineRows.map(row => row.id),
    connection: runner,
  });

  packetRows.forEach(row => {
    const packet = mapPaymentPacketRow(row);
    packet.lines = [];
    packet.baselineEvidence = [];
    packet.documents = [];
    packet.timeline = [];
    packet.followUpEvents = [];
    packet.approvals = buildApprovalsFromPacketRow(row);
    packetMap.set(String(row.id), packet);
    packets.push(packet);
  });

  lineRows.forEach(row => {
    const packetId = String(row.payment_packet_id);
    const packet = packetMap.get(packetId);
    if (!packet) return;
    const line = mapPaymentLineRow(row);
    line.evidenceChecklist = [];
    line.followUpEvents = [];
    line.reportingUnit = packet.reportingUnit || packet.reporting_unit || null;
    line.batch = batchInfoMap.get(String(row.id)) || null;
    packet.lines.push(line);
    lineMap.set(String(row.id), line);
  });

  docRows.forEach(row => {
    const packetId = String(row.payment_packet_id);
    const packet = packetMap.get(packetId);
    if (!packet) return;
    const evidence = mapPaymentDocumentRow(row);
    if (row.payment_packet_line_id) {
      const line = lineMap.get(String(row.payment_packet_line_id));
      if (line) {
        line.evidenceChecklist.push(evidence);
      }
    } else {
      packet.baselineEvidence.push(evidence);
    }
    if (row.document_id) {
      const docId = String(row.document_id);
      let perPacket = documentsMap.get(packetId);
      if (!perPacket) {
        perPacket = new Map();
        documentsMap.set(packetId, perPacket);
      }
      if (!perPacket.has(docId)) {
        perPacket.set(docId, {
          id: docId,
          name: row.file_name || row.label || row.evidence_type || `Document ${docId}`,
        });
      }
    }
  });

  eventRows.forEach(row => {
    const packet = packetMap.get(String(row.payment_packet_id));
    if (!packet) return;
    packet.timeline.push({
      label: formatStatusLabel(row.to_status),
      at: row.created_at,
      actor: row.actor_name || row.actor_email || row.actor_user_id || null,
      notes: row.notes || null,
    });
  });

  followUpRows.forEach(row => {
    const packet = packetMap.get(String(row.payment_packet_id));
    if (!packet) return;
    const event = mapPaymentFollowUpEventRow(row);
    packet.followUpEvents.push(event);
    if (row.payment_packet_line_id) {
      const line = lineMap.get(String(row.payment_packet_line_id));
      if (line) {
        line.followUpEvents.push(event);
      }
    }
    packet.timeline.push({
      label: event.label ? `Follow-up: ${event.label}` : 'Follow-up updated',
      at: event.createdAt,
      actor: event.actor,
      notes: event.note || null,
    });
  });

  documentsMap.forEach((docMap, packetId) => {
    const packet = packetMap.get(packetId);
    if (!packet) return;
    packet.documents = Array.from(docMap.values());
  });

  packets.forEach(packet => {
    const potIds = Array.from(new Set(packet.lines.map(line => line.potId).filter(Boolean)));
    const potNames = Array.from(new Set(packet.lines.map(line => line.potName).filter(Boolean)));
    if (!packet.potId) {
      packet.potId = potIds.length === 1 ? potIds[0] : null;
    }
    if (!packet.potName) {
      packet.potName = potNames.length === 1 ? potNames[0] : potNames.length > 1 ? 'Multiple' : null;
    }
    packet.timeline.sort((a, b) => {
      const aTime = a.at ? new Date(a.at).getTime() : 0;
      const bTime = b.at ? new Date(b.at).getTime() : 0;
      return aTime - bTime;
    });
    applyEvidenceRulesToPacket(packet, evidenceRules);
  });

  if (includeAuthorization) {
    const packetInfoMap = new Map();
    const interventionCaseMap = new Map();
    packetRows.forEach(row => {
      const packetId = String(row.id);
      packetInfoMap.set(packetId, {
        interventionId: row.intervention_id ? Number(row.intervention_id) : null,
        caseId: row.case_id ? Number(row.case_id) : null,
      });
      if (row.intervention_id) {
        interventionCaseMap.set(String(row.intervention_id), row.case_id ? Number(row.case_id) : null);
      }
    });

    const interventionIds = new Set();
    lineRows.forEach(row => {
      if (row.intervention_id) {
        interventionIds.add(Number(row.intervention_id));
        return;
      }
      const packetInfo = packetInfoMap.get(String(row.payment_packet_id));
      if (packetInfo?.interventionId) {
        interventionIds.add(Number(packetInfo.interventionId));
      }
    });

    const interventionIdList = Array.from(interventionIds).filter(Number.isFinite);
    if (interventionIdList.length) {
      const interventionMap = await fetchInterventionsById({ ids: interventionIdList, connection: runner });
      const usageMap = await fetchFundingUsageForInterventions({ interventionIds: interventionIdList, connection: runner });
      const authMap = new Map();
      for (const id of interventionIdList) {
        const interventionRow = interventionMap.get(Number(id)) || null;
        const caseId =
          interventionRow?.case_id ||
          interventionCaseMap.get(String(id)) ||
          null;
        const auth = await resolveFundingAuthorizationForIntervention({
          interventionRow,
          caseId,
          connection: runner,
        });
        if (auth) {
          authMap.set(String(id), auth);
        }
      }
      packets.forEach(packet => {
        const fallbackInterventionId = packet.interventionId ? Number(packet.interventionId) : null;
        packet.lines.forEach(line => {
          const interventionId = line.interventionId ? Number(line.interventionId) : fallbackInterventionId;
          if (!interventionId) return;
          const auth = authMap.get(String(interventionId));
          const usage = usageMap.get(String(interventionId));
          if (!auth || !usage) return;
          const summary = buildFundingAuthorizationSummary({ line, auth, usage });
          if (summary) {
            line.authorization = summary;
          }
        });
      });
    }
  }

  return packets;
}

async function fetchMissingRequiredEvidence({ packetId, lineId = null, connection = null }) {
  const runner = connection || pool;
  if (!runner) return [];
  const packetKey = Number(packetId);
  if (!Number.isFinite(packetKey)) return [];
  const [[packetRow]] = await runner.query(
    'SELECT id, case_id, client_id FROM payment_packet WHERE id = ? LIMIT 1',
    [packetKey]
  );
  if (!packetRow) return [];

  const [lineRows] = await runner.query(
    'SELECT id, payment_type, payee_type, status FROM payment_packet_line WHERE payment_packet_id = ?',
    [packetKey]
  );
  const targetLineId = Number.isFinite(lineId) ? Number(lineId) : null;
  const linesToCheck = targetLineId
    ? lineRows.filter(row => Number(row.id) === targetLineId)
    : lineRows.filter(row => row.status !== 'cancelled');
  if (targetLineId && !linesToCheck.length) return [];

  const [docRows] = await runner.query(
    `SELECT payment_packet_line_id, evidence_type, received_at, verified_at, notes, document_id
       FROM payment_packet_document
      WHERE payment_packet_id = ?`,
    [packetKey]
  );

  const evidenceByLine = new Map();
  const addEvidencePresence = (lineKey, row) => {
    const key = normalizeEvidenceTypeKey(row?.evidence_type);
    if (!key) return;
    const received = !!(row?.received_at || row?.document_id);
    const verified = !!row?.verified_at;
    const note = typeof row?.notes === 'string' ? row.notes : null;
    let bucket = evidenceByLine.get(lineKey);
    if (!bucket) {
      bucket = new Map();
      evidenceByLine.set(lineKey, bucket);
    }
    const existing = bucket.get(key);
    if (existing) {
      existing.received = existing.received || received;
      existing.verified = existing.verified || verified;
      if (!existing.note && note) {
        existing.note = note;
      }
    } else {
      bucket.set(key, { received, verified, note });
    }
  };

  (docRows || []).forEach(row => {
    const lineKey = row.payment_packet_line_id ? String(row.payment_packet_line_id) : null;
    addEvidencePresence(lineKey, row);
  });

  const rules = await readPaymentEvidenceRules(runner);
  const requiresBaseline = shouldApplyBaselineEvidence(packetRow);
  const baselineRules = requiresBaseline ? rules?.baseline : null;
  const baselineRequired = Array.isArray(baselineRules?.required) ? baselineRules.required : [];
  const baselineRequiredKeys = new Set(baselineRequired.map(normalizeEvidenceTypeKey).filter(Boolean));

  const combinedBaselinePresence = mergeEvidencePresenceMaps(...Array.from(evidenceByLine.values()));
  const getLinePresence = lineKey => {
    const baselinePresence = evidenceByLine.get(null) || new Map();
    const linePresence = evidenceByLine.get(String(lineKey)) || new Map();
    return mergeEvidencePresenceMaps(baselinePresence, linePresence);
  };

  const missing = [];
  const addMissingFromRequired = (requiredList, presenceMap, target) => {
    if (!Array.isArray(requiredList) || !requiredList.length) return;
    requiredList.forEach(type => {
      const key = normalizeEvidenceTypeKey(type);
      if (!key) return;
      const presence = presenceMap.get(key);
      if (!presence?.received) {
        missing.push({ lineId: target, evidenceType: type });
      }
    });
  };

  if (requiresBaseline && baselineRequired.length) {
    addMissingFromRequired(baselineRequired, combinedBaselinePresence, null);
  }

  linesToCheck.forEach(line => {
    const lineRules = resolveLineEvidenceRules({
      line,
      rules,
      baselineRequiredKeys,
    });
    const presenceMap = getLinePresence(line.id);
    addMissingFromRequired(lineRules.required, presenceMap, String(line.id));
  });

  return missing;
}

const runPaymentPacketValidation = async ({ packetRow, lineRows, connection }) => {
  if (!packetRow || !connection) {
    return { passed: false, details: [], missingEvidence: [] };
  }
  const activeLines = (lineRows || []).filter(row => row && row.status !== 'cancelled');
  const details = [];

  const policyRules = await readPaymentPolicyRules(connection);
  const recurrencePolicyByType = await readPaymentRecurrencePolicyByType(connection);
  const paymentTypeMap = await readPaymentInterventionMapping(connection);
  const interventionIds = activeLines.map(line => line.intervention_id).filter(Boolean);
  if (packetRow.intervention_id) {
    interventionIds.push(packetRow.intervention_id);
  }
  const interventionMap = await fetchInterventionsById({ ids: interventionIds, connection });
  const [evidenceRows] = await connection.query(
    `SELECT payment_packet_line_id, evidence_type, received_at, document_id
       FROM payment_packet_document
      WHERE payment_packet_id = ?`,
    [packetRow.id]
  );
  const evidenceMap = buildEvidenceTypeSetMap(evidenceRows || []);

  activeLines.forEach(line => {
    const intervention = line.intervention_id
      ? interventionMap.get(Number(line.intervention_id))
      : packetRow.intervention_id
        ? interventionMap.get(Number(packetRow.intervention_id))
        : null;
    const lineEvidence = mergeEvidenceTypeSets(
      evidenceMap.baseline,
      evidenceMap.byLine.get(String(line.id))
    );
    const validationErrors = validatePaymentLinePolicy({
      line,
      intervention,
      evidenceTypeKeys: lineEvidence,
      policyRules,
      interventionPaymentTypeMap: paymentTypeMap,
      recurrencePolicyByType,
      validationStage: 'submission',
    });
    validationErrors.forEach(err => {
      details.push({
        lineId: String(line.id),
        field: err.field,
        error: err.code,
        message: err.message,
      });
    });
  });

  if (EI_GATE_PACKET_STATUSES.has('submitted')) {
    const eiViolations = await findEiEligibilityViolations({
      lines: activeLines,
      packetRow,
      interventionMap,
      connection,
    });
    eiViolations.forEach(violation => {
      details.push({
        lineId: violation.lineId || null,
        field: 'eligibility',
        error: violation.code || 'ei_active_claim',
        message: violation.message || 'Client is not eligible for this payment.',
      });
    });
  }

  const requiresFundingCheck = true;
  if (requiresFundingCheck) {
    const interventionIdsForFunding = new Set();
    activeLines.forEach(line => {
      if (line.intervention_id) {
        interventionIdsForFunding.add(Number(line.intervention_id));
      } else if (packetRow.intervention_id) {
        interventionIdsForFunding.add(Number(packetRow.intervention_id));
      }
    });
    const interventionIdList = Array.from(interventionIdsForFunding).filter(Number.isFinite);
    if (interventionIdList.length) {
      const fundingInterventionMap = interventionMap?.size
        ? interventionMap
        : await fetchInterventionsById({ ids: interventionIdList, connection });
      const usageMap = await fetchFundingUsageForInterventions({
        interventionIds: interventionIdList,
        connection,
      });
      const authMap = new Map();
      for (const line of activeLines) {
        const interventionId = line.intervention_id || packetRow.intervention_id || null;
        if (!interventionId) continue;
        const key = String(interventionId);
        let auth = authMap.get(key);
        if (auth === undefined) {
          const interventionRow = fundingInterventionMap.get(Number(interventionId)) || null;
          auth = await resolveFundingAuthorizationForIntervention({
            interventionRow,
            caseId: packetRow.case_id || interventionRow?.case_id || null,
            connection,
          });
          authMap.set(key, auth || null);
        }
        if (!auth) continue;
        const usage = usageMap.get(key) || { byCategory: {}, total: 0, byLine: new Map() };
        const lineErrors = validateFundingAuthorizationForLine({ line, auth, usage });
        lineErrors.forEach(err => {
          details.push({
            lineId: String(line.id),
            field: err.field,
            error: err.code,
            message: err.message,
          });
        });
      }
    }
  }

  const missingEvidence = await fetchMissingRequiredEvidence({
    packetId: packetRow.id,
    connection,
  });

  const passed = details.length === 0 && missingEvidence.length === 0;
  return { passed, details, missingEvidence };
};

const resolveAutoPacketPayeeType = raw => {
  const rawKey =
    typeof raw === 'string' && raw.trim()
      ? raw.trim().toLowerCase().replace(/[^a-z0-9]+/g, '')
      : null;
  const directMap = {
    participantclient: 'ParticipantClient',
    accreditededucationaltraininginstitution: 'AccreditedEducationalTrainingInstitution',
    employerwagesubsidypartner: 'EmployerWageSubsidyPartner',
    childcareprovider: 'ChildcareProvider',
    communitynonprofitorganization: 'CommunityNonProfitOrganization',
    trainingrelatedsupplier: 'TrainingRelatedSupplier',
    professionalbusinessservicesprovider: 'ProfessionalBusinessServicesProvider',
    studentloanservicer: 'StudentLoanServicer',
  };
  if (rawKey && directMap[rawKey]) return directMap[rawKey];
  const key = normalizePayeeTypeKey(raw);
  if (!key) return null;
  const map = {
    client: 'ParticipantClient',
    vendor: 'TrainingRelatedSupplier',
    institution: 'AccreditedEducationalTrainingInstitution',
    traininginstitution: 'AccreditedEducationalTrainingInstitution',
    employer: 'EmployerWageSubsidyPartner',
    other: 'Other',
  };
  return map[key] || null;
};

const resolveAutoPacketPaymentType = raw => {
  const normalized = normalizePaymentTypeKey(raw);
  if (normalized) return normalized;
  if (typeof raw === 'string' && raw.trim()) return raw.trim();
  return null;
};

const resolveAutoPacketAmount = (interventionRow, metadata = {}) => {
  const candidates = [
    interventionRow?.approved_amount,
    interventionRow?.intervention_cost,
    interventionRow?.budget_amount,
    interventionRow?.actual_amount,
    metadata?.cost,
  ];
  for (const candidate of candidates) {
    const numeric = Number(candidate);
    if (Number.isFinite(numeric) && numeric > 0) {
      return Math.round(numeric * 100) / 100;
    }
  }
  return null;
};

const AUTO_PACKET_EMPLOYER_CODES = new Set(['6', '7', '8', '17']);
const AUTO_PACKET_WAGE_SUBSIDY_CODES = new Set(['7', '8']);

const resolveAutoPacketInterventionCode = (interventionRow, metadata = {}) => {
  const metaCode =
    metadata?.code ||
    metadata?.interventionCode ||
    metadata?.intervention_code ||
    null;
  return normalizeInterventionCodeValue(
    interventionRow?.intervention_code ??
      metaCode ??
      interventionRow?.interventionCode ??
      interventionRow?.code ??
      null
  );
};

const normalizeAutoPacketAmount = value => {
  const amount = normaliseCurrencyAmount(value);
  if (!Number.isFinite(amount) || amount <= 0) return null;
  return Math.round(amount * 100) / 100;
};

const parseAssessmentItpPayloadDetailed = rawPayload => {
  const payload = safeJsonParse(rawPayload, null);
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return null;
  return {
    tuition: normalizeAutoPacketAmount(payload.tuition),
    books: normalizeAutoPacketAmount(payload.books),
    materials: normalizeAutoPacketAmount(payload.materials),
    living: normalizeAutoPacketAmount(payload.living),
    childcare: normalizeAutoPacketAmount(payload.childcare),
    otherLabel: typeof payload.otherLabel === 'string' ? payload.otherLabel.trim() : '',
    otherAmount: normalizeAutoPacketAmount(payload.otherAmount),
  };
};

const parseAssessmentWagePayloadDetailed = rawPayload => {
  const payload = safeJsonParse(rawPayload, null);
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return null;
  return {
    wages: normalizeAutoPacketAmount(payload.wages),
    mercs: normalizeAutoPacketAmount(payload.mercs),
    nonwages: normalizeAutoPacketAmount(payload.nonwages),
    other1Label: typeof payload.other1Label === 'string' ? payload.other1Label.trim() : '',
    other1Amount: normalizeAutoPacketAmount(payload.other1Amount),
    other2Label: typeof payload.other2Label === 'string' ? payload.other2Label.trim() : '',
    other2Amount: normalizeAutoPacketAmount(payload.other2Amount),
  };
};

const resolveAutoPacketPartnerName = ({ assessmentRow, interventionMetadata, planMetadata }) => {
  const candidates = [
    assessmentRow?.institution,
    interventionMetadata?.trainingInstitution,
    interventionMetadata?.training_institution,
    interventionMetadata?.institution,
    planMetadata?.trainingInstitution,
    planMetadata?.training_institution,
    planMetadata?.institution,
    planMetadata?.recommendedIntervention?.trainingInstitution,
    planMetadata?.recommendedIntervention?.training_institution,
    planMetadata?.recommendedIntervention?.institution,
  ];
  for (const entry of candidates) {
    if (typeof entry === 'string' && entry.trim()) {
      return entry.trim();
    }
  }
  return null;
};

const resolveAutoPacketAmountMode = ({ tableTotal, amountPerPeriod, calculatedTotal, interventionCostTotal }) => {
  const closeEnough = (a, b) =>
    Number.isFinite(a) && Number.isFinite(b) && Math.abs(a - b) <= 1;
  if (Number.isFinite(tableTotal) && Number.isFinite(amountPerPeriod) && closeEnough(tableTotal, amountPerPeriod)) {
    return 'per_period';
  }
  if (Number.isFinite(tableTotal) && Number.isFinite(calculatedTotal) && closeEnough(tableTotal, calculatedTotal)) {
    return 'total';
  }
  if (Number.isFinite(tableTotal) && Number.isFinite(interventionCostTotal) && closeEnough(tableTotal, interventionCostTotal)) {
    return 'total';
  }
  return 'total';
};

const resolveAutoPacketPayee = ({ paymentType, partnerName, clientName, fallbackType, fallbackName }) => {
  const typeKey = normalizePaymentTypeKey(paymentType);
  const fallbackPayeeName = fallbackName || clientName || partnerName || 'Client';
  const fallbackPayeeType = fallbackType || 'Client';
  if (partnerName) {
    if (typeKey === 'TuitionFeesDirect') {
      return { payeeType: 'Institution', payeeName: partnerName };
    }
    if (typeKey === 'WageSubsidyEmployer' || typeKey === 'JCPProjectCost') {
      return { payeeType: 'Employer', payeeName: partnerName };
    }
  }
  return { payeeType: fallbackPayeeType, payeeName: fallbackPayeeName };
};

const resolveAutoPacketPayeeFromCostLine = payeeRaw => {
  if (!payeeRaw || typeof payeeRaw !== 'object') return null;
  const payeeType = resolveAutoPacketPayeeType(payeeRaw.type || payeeRaw.payeeType || payeeRaw.payee_type) || null;
  const payeeName = normaliseString(payeeRaw.name || payeeRaw.payeeName || payeeRaw.payee_name || null);
  const payeeReference = normaliseString(
    payeeRaw.reference || payeeRaw.payeeReference || payeeRaw.payee_reference || null
  );
  if (!payeeType || !payeeName) return null;
  return { payeeType, payeeName, payeeReference: payeeReference || null };
};

const buildAutoPaymentLinesFromCostLines = ({
  interventionRow,
  interventionMetadata,
  clientPayeeName,
  partnerName,
  fallbackPayeeType,
  fallbackPayeeName,
  allowedPaymentTypes,
  recurrencePolicyByType,
}) => {
  const lines = [];
  const isAllowed = paymentType =>
    !allowedPaymentTypes || allowedPaymentTypes.size === 0 || allowedPaymentTypes.has(paymentType);
  const pushLine = line => {
    if (!line) return;
    if (!Number.isFinite(line.amount) || line.amount <= 0) return;
    if (!isAllowed(line.paymentType)) return;
    lines.push(line);
  };

  const rawCostLines =
    interventionMetadata?.costLines ||
    interventionMetadata?.cost_lines ||
    [];
  const costLines = Array.isArray(rawCostLines)
    ? rawCostLines.map(normalizeProposedCostLine).filter(Boolean)
    : [];
  if (!costLines.length) return lines;

  const interventionStart = toDateOnly(interventionRow?.start_date || null);
  const interventionEnd = toDateOnly(interventionRow?.end_date || null);

  costLines.forEach((entry, index) => {
    const paymentType =
      resolveAutoPacketPaymentType(entry.type || entry.paymentType || entry.payment_type) || null;
    if (!paymentType) return;
    const amount = Number(entry.amount);
    if (!Number.isFinite(amount) || amount <= 0) return;
    const recurrence = entry.recurrence && typeof entry.recurrence === 'object' ? entry.recurrence : null;
    const recurrenceMode = resolveRecurrenceModeForPaymentType(paymentType, recurrencePolicyByType);
    const recurrenceEnabled =
      recurrenceMode === RECURRENCE_MODE_REQUIRED
        ? true
        : recurrenceMode === RECURRENCE_MODE_NOT_ALLOWED
          ? false
          : Boolean(recurrence?.enabled);
    const occurrences = normaliseRecurringNumber(recurrence?.occurrences);
    const amountPerPeriod = normaliseRecurringNumber(recurrence?.amountPerPeriod);
    const recurrenceStart = toDateOnly(recurrence?.startDate || interventionStart || null);
    const recurrenceEnd = toDateOnly(recurrence?.endDate || interventionEnd || null);
    const payee = resolveAutoPacketPayee({
      paymentType,
      partnerName,
      clientName: clientPayeeName,
      fallbackType: fallbackPayeeType,
      fallbackName: fallbackPayeeName,
    });
    const payeeFromCostLine = resolveAutoPacketPayeeFromCostLine(entry.payee);
    const resolvedPayee = payeeFromCostLine || payee;
    const baseMeta = pruneNullish({
      autoGenerated: true,
      source: 'assessment_cost_line',
      costLineId: entry.id || null,
      costLineIndex: index + 1,
      costLineNotes: entry.notes || null,
      costLineRecurrence: recurrence || null,
    });

    const isRecurring = recurrenceEnabled && recurrenceStart && (recurrenceEnd || occurrences);
    if (isRecurring) {
      const { periods } = buildRecurringServicePeriods({
        startDate: recurrenceStart,
        endDate: recurrenceEnd,
        period: 'monthly',
        occurrences,
      });
      if (periods.length) {
        const splitAmounts =
          Number.isFinite(amountPerPeriod) && amountPerPeriod > 0
            ? periods.map(() => amountPerPeriod)
            : splitRecurringAmount(amount, periods.length);
        splitAmounts.forEach((lineAmount, periodIndex) => {
          const periodItem = periods[periodIndex];
          if (!periodItem) return;
          const recurrenceMeta = {
            period: 'monthly',
            index: periodIndex + 1,
            total: periods.length,
            scheduleStart: periods[0]?.start || null,
            scheduleEnd: periods[periods.length - 1]?.end || null,
            autoGenerated: true,
          };
          pushLine({
            paymentType,
            payeeType: resolvedPayee.payeeType,
            payeeName: resolvedPayee.payeeName,
            payeeReference: resolvedPayee.payeeReference || null,
            amount: lineAmount,
            currency: 'CAD',
            servicePeriodStart: periodItem.start,
            servicePeriodEnd: periodItem.end,
            requestedPaymentDate: periodItem.end,
            status: 'needs_evidence',
            holdReason: null,
            metadata: {
              ...(baseMeta || {}),
              recurrence: recurrenceMeta,
            },
          });
        });
        return;
      }
    }

    const requiresPeriod = recurrenceMode !== RECURRENCE_MODE_NOT_ALLOWED;
    pushLine({
      paymentType,
      payeeType: resolvedPayee.payeeType,
      payeeName: resolvedPayee.payeeName,
      payeeReference: resolvedPayee.payeeReference || null,
      amount,
      currency: 'CAD',
      servicePeriodStart: requiresPeriod ? recurrenceStart || interventionStart : null,
      servicePeriodEnd: requiresPeriod ? recurrenceEnd || interventionEnd : null,
      requestedPaymentDate: null,
      status: 'needs_evidence',
      holdReason: null,
      metadata: baseMeta || {},
    });
  });

  return lines;
};

const buildAutoPaymentLinesFromAssessment = ({
  assessmentRow,
  interventionRow,
  interventionMetadata,
  planMetadata,
  clientPayeeName,
  partnerName,
  fallbackPayeeType,
  fallbackPayeeName,
  allowedPaymentTypes,
  recurrencePolicyByType,
}) => {
  const lines = [];
  const isAllowed = paymentType =>
    !allowedPaymentTypes || allowedPaymentTypes.size === 0 || allowedPaymentTypes.has(paymentType);
  const pushLine = line => {
    if (!line) return;
    if (!Number.isFinite(line.amount) || line.amount <= 0) return;
    if (!isAllowed(line.paymentType)) return;
    lines.push(line);
  };

  const itp = parseAssessmentItpPayloadDetailed(assessmentRow?.itp_payload);
  const wage = parseAssessmentWagePayloadDetailed(assessmentRow?.wage_payload);
  const hasItpAmounts = itp
    ? ['tuition', 'books', 'materials', 'living', 'childcare', 'otherAmount'].some(
        key => Number.isFinite(itp[key]) && itp[key] > 0
      )
    : false;
  const hasWageAmounts = wage
    ? ['wages', 'mercs', 'nonwages', 'other1Amount', 'other2Amount'].some(
        key => Number.isFinite(wage[key]) && wage[key] > 0
      )
    : false;

  const planFunding = planMetadata?.recommendedIntervention?.fundingBreakdown ||
    planMetadata?.recommendedIntervention?.funding_breakdown ||
    planMetadata?.fundingBreakdown ||
    planMetadata?.funding_breakdown ||
    null;
  const planBreakdown = !hasItpAmounts && !hasWageAmounts ? parseFundingBreakdown(planFunding) : null;

  const interventionCode = resolveAutoPacketInterventionCode(interventionRow, interventionMetadata);
  const isEmployerIntervention = interventionCode ? AUTO_PACKET_EMPLOYER_CODES.has(interventionCode) : false;
  const isWageSubsidyIntervention = interventionCode ? AUTO_PACKET_WAGE_SUBSIDY_CODES.has(interventionCode) : false;
  const wagePaymentType = isWageSubsidyIntervention
    ? 'WageSubsidyEmployer'
    : isEmployerIntervention
      ? 'JCPProjectCost'
      : 'WageSubsidyEmployer';

  const entries = [];
  const addEntry = entry => {
    if (!entry || !Number.isFinite(entry.amount) || entry.amount <= 0) return;
    entries.push(entry);
  };

  if (hasItpAmounts && itp) {
    addEntry({ key: 'tuition', amount: itp.tuition, paymentType: 'TuitionFeesDirect', fundingCategory: 'tuition' });
    addEntry({ key: 'books', amount: itp.books, paymentType: 'BooksMaterialsDirect', fundingCategory: 'books' });
    addEntry({ key: 'materials', amount: itp.materials, paymentType: 'BooksMaterialsDirect', fundingCategory: 'materials' });
    addEntry({
      key: 'living',
      amount: itp.living,
      paymentType: 'LivingAllowance',
      fundingCategory: 'living',
      recurring:
        resolveRecurrenceModeForPaymentType('LivingAllowance', recurrencePolicyByType) ===
        RECURRENCE_MODE_REQUIRED,
    });
    addEntry({
      key: 'childcare',
      amount: itp.childcare,
      paymentType: 'Childcare',
      fundingCategory: 'childcare',
      recurring:
        resolveRecurrenceModeForPaymentType('Childcare', recurrencePolicyByType) ===
        RECURRENCE_MODE_REQUIRED,
    });
    addEntry({
      key: 'other',
      amount: itp.otherAmount,
      paymentType: 'OtherEligibleCost',
      fundingCategory: 'other',
      label: itp.otherLabel || null,
    });
  }

  if (hasWageAmounts && wage) {
    addEntry({ key: 'wages', amount: wage.wages, paymentType: wagePaymentType, fundingCategory: 'wage_wages' });
    addEntry({ key: 'mercs', amount: wage.mercs, paymentType: wagePaymentType, fundingCategory: 'wage_mercs' });
    addEntry({ key: 'nonwages', amount: wage.nonwages, paymentType: wagePaymentType, fundingCategory: 'wage_nonwages' });
    addEntry({
      key: 'other1',
      amount: wage.other1Amount,
      paymentType: wagePaymentType,
      fundingCategory: 'wage_other',
      label: wage.other1Label || null,
    });
    addEntry({
      key: 'other2',
      amount: wage.other2Amount,
      paymentType: wagePaymentType,
      fundingCategory: 'wage_other',
      label: wage.other2Label || null,
    });
  }

  if (!entries.length && planBreakdown) {
    Object.entries(planBreakdown).forEach(([category, amount]) => {
      if (!Number.isFinite(amount) || amount <= 0) return;
      if (['tuition', 'books', 'materials', 'living', 'childcare', 'other'].includes(category)) {
        const paymentType =
          category === 'tuition'
            ? 'TuitionFeesDirect'
            : category === 'books' || category === 'materials'
              ? 'BooksMaterialsDirect'
              : category === 'living'
                ? 'LivingAllowance'
                : category === 'childcare'
                  ? 'Childcare'
                  : 'OtherEligibleCost';
        addEntry({
          key: category,
          amount,
          paymentType,
          fundingCategory: category,
          recurring:
            resolveRecurrenceModeForPaymentType(paymentType, recurrencePolicyByType) ===
            RECURRENCE_MODE_REQUIRED,
        });
        return;
      }
      if (category.startsWith('wage_') || category === 'wage_total') {
        addEntry({
          key: category,
          amount,
          paymentType: wagePaymentType,
          fundingCategory: category,
        });
      }
    });
  }

  if (!entries.length) return lines;

  const startDate =
    toDateOnly(interventionRow?.start_date || assessmentRow?.intervention_start_date) || null;
  const endDate =
    toDateOnly(interventionRow?.end_date || assessmentRow?.intervention_end_date) || null;
  const canBuildRecurringPeriods = Boolean(startDate && endDate);

  entries.forEach(entry => {
    const recurrenceMode = resolveRecurrenceModeForPaymentType(
      entry.paymentType,
      recurrencePolicyByType
    );
    const recurrenceRequired = recurrenceMode === RECURRENCE_MODE_REQUIRED;
    const recurrenceAllowed = recurrenceMode !== RECURRENCE_MODE_NOT_ALLOWED;
    const recurringRequested = Boolean(entry.recurring);
    const shouldGenerateRecurring = recurrenceAllowed && (recurringRequested || recurrenceRequired);
    const baseMeta = pruneNullish({
      autoGenerated: true,
      source: 'assessment_breakdown',
      fundingCategory: entry.fundingCategory || null,
      fundingLabel: entry.label || null,
    });
    const payee = resolveAutoPacketPayee({
      paymentType: entry.paymentType,
      partnerName,
      clientName: clientPayeeName,
      fallbackType: fallbackPayeeType,
      fallbackName: fallbackPayeeName,
    });

    if (shouldGenerateRecurring && canBuildRecurringPeriods) {
      const { periods } = buildRecurringServicePeriods({
        startDate,
        endDate,
        period: 'monthly',
      });
      if (!periods.length) return;
      const splitAmounts = splitRecurringAmount(entry.amount, periods.length);
      splitAmounts.forEach((amount, index) => {
        const periodItem = periods[index];
        if (!periodItem) return;
        const recurrenceMeta = {
          period: 'monthly',
          index: index + 1,
          total: periods.length,
          scheduleStart: periods[0]?.start || null,
          scheduleEnd: periods[periods.length - 1]?.end || null,
          autoGenerated: true,
        };
        pushLine({
          paymentType: entry.paymentType,
          payeeType: payee.payeeType,
          payeeName: payee.payeeName,
          amount,
          currency: 'CAD',
          servicePeriodStart: periodItem.start,
          servicePeriodEnd: periodItem.end,
          requestedPaymentDate: periodItem.end,
          status: 'needs_evidence',
          holdReason: null,
          metadata: {
            ...(baseMeta || {}),
            recurrence: recurrenceMeta,
          },
        });
      });
      return;
    }

    const needsServicePeriod = recurrenceAllowed && (recurringRequested || recurrenceRequired);
    pushLine({
      paymentType: entry.paymentType,
      payeeType: payee.payeeType,
      payeeName: payee.payeeName,
      amount: entry.amount,
      currency: 'CAD',
      servicePeriodStart: needsServicePeriod ? startDate : null,
      servicePeriodEnd: needsServicePeriod ? endDate : null,
      requestedPaymentDate: null,
      status: 'needs_evidence',
      holdReason: null,
      metadata: baseMeta || {},
    });
  });

  return lines;
};

async function createAutoPaymentPacketFromIntervention({
  interventionRow,
  actorUserId = null,
  actorRole = null,
  connection = null,
  requireCostLines = false,
  allowExistingHistoricalPackets = false,
} = {}) {
  if (!connection) {
    return withTx(conn =>
      createAutoPaymentPacketFromIntervention({
        interventionRow,
        actorUserId,
        actorRole,
        connection: conn,
        requireCostLines,
        allowExistingHistoricalPackets,
      })
    );
  }

  const runner = connection;
  if (!runner || !interventionRow) return null;
  const interventionId = Number(interventionRow.id);
  if (!Number.isFinite(interventionId)) return null;
  let resolvedActorUserId = Number.isFinite(Number(actorUserId)) ? Number(actorUserId) : null;
  if (resolvedActorUserId) {
    resolvedActorUserId = await ensureUserExists(runner, resolvedActorUserId);
  }

  const blockedStatuses = allowExistingHistoricalPackets
    ? Array.from(HISTORICAL_PAYMENT_PACKET_STATUSES)
    : ['cancelled'];
  const blockedPlaceholders = blockedStatuses.map(() => '?').join(',');
  const [existingPackets] = await runner.query(
    `SELECT id
       FROM payment_packet
      WHERE intervention_id = ?
        AND (status IS NULL OR status NOT IN (${blockedPlaceholders}))
      LIMIT 1`,
    [interventionId, ...blockedStatuses]
  );
  if (existingPackets?.length) {
    return { packetId: String(existingPackets[0].id), created: false };
  }

  const caseId = Number(interventionRow.case_id) || null;
  const caseRow = caseId ? await fetchCaseRow(caseId, runner) : null;
  const clientId = Number(caseRow?.client_id) || null;
  const actionPlanContext = interventionRow.action_plan_id
    ? await fetchActionPlanAssessmentContext(interventionRow.action_plan_id, runner)
    : null;
  const applicationId = normalisePositiveInteger(actionPlanContext?.applicationId) || null;

  const metadata = safeJsonParse(interventionRow.metadata_json, {}) || {};
  const assessmentRow = caseId
    ? await fetchAssessmentFundingRow({
        caseId,
        applicationId,
        connection: runner,
      })
    : null;
  const planMetadata = actionPlanContext?.metadata || null;
  const partnerName = resolveAutoPacketPartnerName({
    assessmentRow,
    interventionMetadata: metadata,
    planMetadata,
  });
  const riskFlags = ['Auto-generated'];

  let reportingUnit =
    metadata.reportingUnit || metadata.reporting_unit || null;
  const regionId =
    Number(interventionRow.portfolio_region_id) ||
    Number(interventionRow.owner_region_id) ||
    null;
  if (!reportingUnit && regionId) {
    const [[regionRow]] = await runner.query(
      'SELECT code FROM canada_region WHERE region_id = ? LIMIT 1',
      [regionId]
    );
    reportingUnit = regionRow?.code ? String(regionRow.code).trim().toUpperCase() : null;
  }

  let potId =
    normalisePositiveInteger(
      metadata.potId ||
        metadata.budgetPotId ||
        metadata.budget_pot_id
    ) || null;
  if (!potId) {
    const [[txRow]] = await runner.query(
      `SELECT budget_pot_id
         FROM finance_transaction
        WHERE case_intervention_id = ?
        ORDER BY updated_at DESC, id DESC
        LIMIT 1`,
      [interventionId]
    );
    potId = normalisePositiveInteger(txRow?.budget_pot_id) || null;
  }
  if (!potId && interventionRow.action_plan_id) {
    const [[planRow]] = await runner.query(
      'SELECT budget_pot FROM iset_case_action_plan WHERE id = ? LIMIT 1',
      [interventionRow.action_plan_id]
    );
    potId = normalisePositiveInteger(planRow?.budget_pot) || null;
  }

  let potRow = null;
  if (potId) {
    const [[row]] = await runner.query(
      'SELECT id, funding_source FROM budget_pot WHERE id = ? LIMIT 1',
      [potId]
    );
    potRow = row || null;
    if (!potRow) {
      potId = null;
    }
  }
  if (!potId) {
    riskFlags.push('Missing budget pot');
  }

  const paymentAmount = resolveAutoPacketAmount(interventionRow, metadata);
  if (!paymentAmount) {
    riskFlags.push('Missing approved amount');
  }

  let clientPayeeName = null;
  if (clientId) {
    const [[clientRow]] = await runner.query(
      'SELECT first_name, last_name FROM client WHERE id = ? LIMIT 1',
      [clientId]
    );
    const first = clientRow?.first_name || null;
    const last = clientRow?.last_name || null;
    const combined = [first, last].filter(Boolean).join(' ').trim();
    clientPayeeName = combined || null;
  }
  const fallbackPayeeName = typeof metadata.payeeName === 'string' ? metadata.payeeName.trim() : null;
  clientPayeeName = clientPayeeName || fallbackPayeeName || 'Client';

  const fallbackPayeeType =
    resolveAutoPacketPayeeType(metadata.payeeType || metadata.payee_type) || 'Client';
  const paymentType =
    resolveAutoPacketPaymentType(metadata.paymentType || metadata.payment_type) || 'OtherEligibleCost';
  const paymentTypeMapping = await readPaymentInterventionMapping(runner);
  const submissionTimingByType = new Map();
  (paymentTypeMapping?.paymentTypes || []).forEach(entry => {
    const code = normalizePaymentTypeCode(entry?.code);
    if (!code) return;
    const timing =
      normalizePaymentSubmissionTiming(entry?.submissionTiming) ||
      PAYMENT_SUBMISSION_TIMING_DEFAULTS[code] ||
      'manual_trigger';
    submissionTimingByType.set(code, timing);
  });
  const recurrencePolicyByType = await readPaymentRecurrencePolicyByType(runner);
  const allowedPaymentTypes = paymentTypeMapping
    ? resolveAllowedPaymentTypesForIntervention(paymentTypeMapping, interventionRow)
    : null;

  const costLineInputs = buildAutoPaymentLinesFromCostLines({
    interventionRow,
    interventionMetadata: metadata,
    clientPayeeName,
    partnerName,
    fallbackPayeeType,
    fallbackPayeeName,
    allowedPaymentTypes,
    recurrencePolicyByType,
  });
  if (requireCostLines && !costLineInputs.length) {
    return { packetId: null, created: false, reason: 'missing_cost_lines' };
  }

  let requesterName =
    metadata.requesterName ||
    metadata.requester_name ||
    null;
  if (!requesterName && resolvedActorUserId) {
    const [[userRow]] = await runner.query(
      'SELECT name, email FROM user WHERE id = ? LIMIT 1',
      [resolvedActorUserId]
    );
    requesterName = userRow?.name || userRow?.email || null;
  }
  const requesterRole =
    metadata.requesterRole ||
    metadata.requester_role ||
    (actorRole ? String(actorRole) : null);

  const interventionStartDate = toDateOnly(interventionRow.start_date || null);
  const interventionEndDate = toDateOnly(interventionRow.end_date || null);
  const resolveSubmissionTimingForPaymentType = paymentTypeCode => {
    const code = normalizePaymentTypeCode(paymentTypeCode);
    if (!code) return 'manual_trigger';
    return (
      submissionTimingByType.get(code) ||
      PAYMENT_SUBMISSION_TIMING_DEFAULTS[code] ||
      'manual_trigger'
    );
  };
  const resolveLineScheduledDate = (lineInput, submissionTiming) => {
    const requestedDate = toDateOnly(lineInput?.requestedPaymentDate || null);
    const serviceStart = toDateOnly(lineInput?.servicePeriodStart || null);
    const serviceEnd = toDateOnly(lineInput?.servicePeriodEnd || null);
    if (submissionTiming === 'intervention_start') {
      return interventionStartDate || serviceStart || requestedDate || null;
    }
    if (submissionTiming === 'intervention_end') {
      return interventionEndDate || serviceEnd || requestedDate || interventionStartDate || null;
    }
    if (submissionTiming === 'recurrence_schedule') {
      return requestedDate || serviceStart || interventionStartDate || null;
    }
    return requestedDate || serviceStart || interventionStartDate || null;
  };

  const autoLineInputs = costLineInputs.length
    ? costLineInputs
    : buildAutoPaymentLinesFromAssessment({
        assessmentRow,
        interventionRow,
        interventionMetadata: metadata,
        planMetadata,
        clientPayeeName,
        partnerName,
        fallbackPayeeType,
        fallbackPayeeName,
        allowedPaymentTypes,
        recurrencePolicyByType,
      });
  const fallbackPayee = resolveAutoPacketPayee({
    paymentType,
    partnerName,
    clientName: clientPayeeName,
    fallbackType: fallbackPayeeType,
    fallbackName: fallbackPayeeName,
  });
  const fallbackLines =
    !autoLineInputs.length &&
    paymentAmount &&
    (!allowedPaymentTypes || allowedPaymentTypes.size === 0 || allowedPaymentTypes.has(paymentType))
      ? [
          {
            paymentType,
            payeeType: fallbackPayee.payeeType,
            payeeName: fallbackPayee.payeeName,
            amount: paymentAmount,
            currency: 'CAD',
            servicePeriodStart: interventionStartDate,
            servicePeriodEnd: interventionEndDate,
            requestedPaymentDate: null,
            status: 'needs_evidence',
            holdReason: null,
            metadata: { autoGenerated: true },
          },
        ]
      : [];
  const lineInputs = autoLineInputs.length ? autoLineInputs : fallbackLines;
  if (!lineInputs.length) {
    return { packetId: null, created: false, reason: 'missing_payment_lines' };
  }
  if (!potId) {
    return { packetId: null, created: false, reason: 'missing_budget_pot' };
  }

  const fundingStream = potRow?.funding_source ? normalizeFundingSource(potRow.funding_source) : null;
  const grouped = new Map();
  lineInputs.forEach(line => {
    const submissionTiming = resolveSubmissionTimingForPaymentType(line.paymentType);
    const scheduledPaymentDate = resolveLineScheduledDate(line, submissionTiming);
    const manualTrigger = submissionTiming === 'manual_trigger';
    const groupKey = `${scheduledPaymentDate || 'none'}::${manualTrigger ? 'manual' : 'auto'}`;
    if (!grouped.has(groupKey)) {
      grouped.set(groupKey, {
        scheduledPaymentDate,
        submissionTiming,
        manualTrigger,
        lines: [],
      });
    }
    grouped.get(groupKey).lines.push({
      ...line,
      metadata: {
        ...(line.metadata || {}),
        scheduling: pruneNullish({
          submissionTiming,
          scheduledPaymentDate,
          manualTrigger,
        }),
      },
    });
  });
  const groups = Array.from(grouped.values()).sort((a, b) => {
    if (!a.scheduledPaymentDate && !b.scheduledPaymentDate) return 0;
    if (!a.scheduledPaymentDate) return 1;
    if (!b.scheduledPaymentDate) return -1;
    return String(a.scheduledPaymentDate).localeCompare(String(b.scheduledPaymentDate));
  });

  const createdPacketIds = [];
  for (const group of groups) {
    const packetStatus = 'draft';
    const packetMeta = {
      autoGeneratedFromInterventionId: String(interventionId),
      autoGeneratedAt: new Date().toISOString(),
      scheduling: pruneNullish({
        scheduledPaymentDate: group.scheduledPaymentDate || null,
        submissionTiming: group.submissionTiming || null,
        manualTrigger: group.manualTrigger || false,
      }),
    };
    if (requesterName) packetMeta.requesterName = requesterName;
    if (requesterRole) packetMeta.requesterRole = requesterRole;

    const [packetResult] = await runner.query(
      `INSERT INTO payment_packet
        (case_id, client_id, intervention_id, reporting_unit, status, requester_user_id,
         submitted_at, due_by, notes_internal, risk_flags, metadata, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, NULL, ?, ?, ?, ?, NOW(), NOW())`,
      [
        caseId || null,
        clientId || null,
        interventionId,
        reportingUnit || null,
        packetStatus,
        resolvedActorUserId || null,
        group.scheduledPaymentDate || null,
        'Auto-generated from intervention.',
        JSON.stringify(riskFlags),
        JSON.stringify(packetMeta),
      ]
    );
    const packetId = packetResult.insertId;
    createdPacketIds.push(packetId);

    const lineValues = group.lines.map(line => [
      packetId,
      interventionId,
      line.paymentType,
      line.payeeType,
      line.payeeName,
      null,
      line.payeeReference || null,
      line.amount,
      line.currency || 'CAD',
      line.servicePeriodStart || null,
      line.servicePeriodEnd || null,
      line.invoiceReferenceNumber || null,
      line.requestedPaymentDate || null,
      potId,
      fundingStream,
      line.status || 'needs_evidence',
      line.holdReason || null,
      JSON.stringify(line.metadata || {}),
    ]);
    await runner.query(
      `INSERT INTO payment_packet_line
        (payment_packet_id, intervention_id, payment_type, payee_type, payee_name, payee_profile_id, payee_reference,
         amount, currency, service_period_start, service_period_end, invoice_reference_number, requested_payment_date,
         budget_pot_id, funding_stream, status, hold_reason, metadata)
       VALUES ?`,
      [lineValues]
    );

    try {
      await attachSupportingDocumentsToPaymentPacket({
        packetId,
        caseId,
        clientId,
        applicationId,
        interventionIds: interventionId ? [interventionId] : [],
        connection: runner,
      });
    } catch (err) {
      console.warn('[payments] failed to attach evidence for auto packet', err?.message || err);
    }

    await runner.query(
      `INSERT INTO payment_status_event
        (payment_packet_id, payment_packet_line_id, from_status, to_status, actor_user_id, notes, metadata, created_at)
       VALUES (?, NULL, NULL, ?, ?, 'Auto-generated from intervention', NULL, NOW())`,
      [packetId, packetStatus, resolvedActorUserId || null]
    );
  }

  return {
    packetId: createdPacketIds.length ? String(createdPacketIds[0]) : null,
    packetIds: createdPacketIds.map(id => String(id)),
    created: createdPacketIds.length > 0,
  };
}

async function createFinanceTransactionForLine({ lineRow, packetRow, connection = null, status = 'posted', transactionDate = null }) {
  if (!lineRow) return null;
  const runner = connection || pool;
  const lineId = Number(lineRow.id);
  if (!Number.isFinite(lineId)) return null;
  const [[existingLink]] = await runner.query(
    'SELECT finance_transaction_id FROM payment_line_transaction WHERE payment_packet_line_id = ? LIMIT 1',
    [lineId]
  );
  const lineMeta = safeJsonParse(lineRow.metadata, {}) || {};
  const packetMeta = safeJsonParse(packetRow?.metadata, {}) || {};
  const postingContextRaw =
    lineMeta.postingContext ||
    lineMeta.posting_context ||
    packetMeta.postingContext ||
    packetMeta.posting_context ||
    'external';
  const postingContext = normalizePostingContext(postingContextRaw) || 'external';
  const { glProjectCodeUsed } = await ensureChargeablePot({
    runner,
    potId: lineRow.budget_pot_id,
    postingContext,
  });
  const amount = Number(lineRow.amount || 0);
  const currency = lineRow.currency || 'CAD';
  const resolvedTransactionDate =
    transactionDate || lineRow?.paid_at || lineRow?.paidAt || packetRow?.confirmed_at || new Date();
  let reportingUnit =
    packetRow?.reporting_unit ||
    packetRow?.reportingUnit ||
    packetMeta.reportingUnit ||
    packetMeta.reporting_unit ||
    null;
  if (!reportingUnit && lineRow.payment_packet_id) {
    const [[packetInfo]] = await runner.query(
      'SELECT reporting_unit, metadata FROM payment_packet WHERE id = ? LIMIT 1',
      [Number(lineRow.payment_packet_id)]
    );
    reportingUnit =
      packetInfo?.reporting_unit ||
      safeJsonParse(packetInfo?.metadata, {})?.reportingUnit ||
      null;
  }
  const evidence = await fetchPaymentEvidenceDocuments({
    packetId: Number(lineRow.payment_packet_id),
    lineId,
    connection: runner,
  });
  const txMetadata = {
    ...(typeof lineMeta === 'object' ? lineMeta : {}),
    reportingUnit,
    paymentPacketId: lineRow.payment_packet_id ? String(lineRow.payment_packet_id) : null,
    paymentLineId: String(lineId),
    paidAt: lineRow?.paid_at || lineRow?.paidAt || null,
    paymentReference: lineRow?.payment_reference || lineRow?.paymentReference || null,
    paymentProofDocumentId: lineRow?.payment_proof_document_id || lineRow?.paymentProofDocumentId || null,
    evidenceDocumentIds: evidence.documentIds,
    evidenceTypes: evidence.evidenceTypes,
  };
  const evidenceRef = evidence.documentIds.length ? evidence.documentIds.join(',') : null;
  if (existingLink?.finance_transaction_id) {
    await runner.query(
      `UPDATE finance_transaction
         SET amount = ?, currency = ?, status = ?, transaction_date = ?, evidence_ref = ?, metadata = ?, updated_at = NOW()
       WHERE id = ?`,
      [
        amount,
        currency,
        status,
        resolvedTransactionDate,
        evidenceRef,
        JSON.stringify(txMetadata),
        existingLink.finance_transaction_id,
      ]
    );
    return existingLink.finance_transaction_id;
  }

  const [result] = await runner.query(
    `INSERT INTO finance_transaction
       (case_id, case_intervention_id, budget_pot_id, posting_context, gl_project_code_used, amount, currency, status, transaction_date, evidence_ref, metadata, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), NOW())`,
    [
      packetRow?.case_id || null,
      lineRow.intervention_id || packetRow?.intervention_id || null,
      lineRow.budget_pot_id,
      postingContext,
      glProjectCodeUsed,
      amount,
      currency,
      status,
      resolvedTransactionDate,
      evidenceRef,
      JSON.stringify(txMetadata),
    ]
  );
  await runner.query(
    'INSERT INTO payment_line_transaction (payment_packet_line_id, finance_transaction_id, created_at) VALUES (?, ?, NOW())',
    [lineId, result.insertId]
  );
  return result.insertId;
}

async function fetchPaymentPacketById(packetId, connection = null) {
  const runner = connection || pool;
  const [[row]] = await runner.query(
    `SELECT pp.*,
            c.case_number,
            a.id AS application_id,
            cl.first_name AS client_first_name,
            cl.last_name AS client_last_name,
            ci.metadata_json AS intervention_metadata_json,
            ci.notes AS intervention_notes,
            ci.intervention_code AS intervention_code,
            req.name AS requester_name,
            req.email AS requester_email,
            prog.name AS program_approver_name,
            prog.email AS program_approver_email,
            fin.name AS finance_approver_name,
            fin.email AS finance_approver_email,
            COALESCE(s.user_id, applicant_client_sub.id, applicant_client_email.id) AS applicant_user_id
       FROM payment_packet pp
       LEFT JOIN iset_case c ON c.id = pp.case_id
       LEFT JOIN client cl ON cl.id = pp.client_id
       ${buildCasePrimaryApplicationJoinSql('c', 'a')}
       LEFT JOIN iset_application_submission s ON s.id = a.submission_id
       LEFT JOIN user applicant_client_sub ON applicant_client_sub.cognito_sub = cl.applicant_cognito_sub
       LEFT JOIN user applicant_client_email ON applicant_client_email.email = cl.applicant_account_email
       LEFT JOIN iset_case_intervention ci ON ci.id = pp.intervention_id
       LEFT JOIN user req ON req.id = pp.requester_user_id
       LEFT JOIN user prog ON prog.id = pp.program_approved_by_user_id
       LEFT JOIN user fin ON fin.id = pp.finance_approved_by_user_id
      WHERE pp.id = ?
      LIMIT 1`,
    [packetId]
  );
  if (!row) return null;
  const packets = await hydratePaymentPackets([row], connection, { includeAuthorization: true });
  return packets[0] || null;
}

async function fetchPaymentBatchById(batchId, connection = null) {
  const runner = connection || pool;
  const [[batchRow]] = await runner.query(
    'SELECT * FROM payment_batch WHERE id = ? LIMIT 1',
    [batchId]
  );
  if (!batchRow) return null;
  const [lineRows] = await runner.query(
    `SELECT bl.payment_packet_line_id,
            ppl.payment_packet_id,
            ppl.payment_type,
            ppl.payee_name,
            ppl.amount,
            ppl.currency,
            ppl.status,
            pp.case_id,
            cl.first_name AS client_first_name,
            cl.last_name AS client_last_name,
            bp.name AS pot_name,
            bp.code AS pot_code
       FROM payment_batch_line bl
       LEFT JOIN payment_packet_line ppl ON ppl.id = bl.payment_packet_line_id
       LEFT JOIN payment_packet pp ON pp.id = ppl.payment_packet_id
       LEFT JOIN client cl ON cl.id = pp.client_id
       LEFT JOIN budget_pot bp ON bp.id = ppl.budget_pot_id
      WHERE bl.payment_batch_id = ?
      ORDER BY bl.id ASC`,
    [batchId]
  );
  const lines = (lineRows || []).map(row => ({
    lineId: row.payment_packet_line_id ? String(row.payment_packet_line_id) : null,
    packetId: row.payment_packet_id ? String(row.payment_packet_id) : null,
    caseId: row.case_id || null,
    clientName: resolveClientNameFromRow(row) || null,
    paymentType: row.payment_type || null,
    payeeName: row.payee_name || null,
    amount: Number(row.amount || 0),
    currency: row.currency || 'CAD',
    status: row.status || null,
    potName: row.pot_name || null,
    potCode: row.pot_code || null,
  }));
  return { ...mapPaymentBatchRow(batchRow), lines };
}

