const formatCurrencyCad = value => {
  const num = Number(value);
  if (!Number.isFinite(num)) return value ?? '';
  return num.toLocaleString('en-CA', { style: 'currency', currency: 'CAD' });
};

const formatPacketIdLabel = value => {
  if (value === null || value === undefined) return '';
  const str = String(value).trim();
  return str ? `PKT-${str}` : '';
};

const formatCsvValue = value => {
  if (value === null || value === undefined) return '';
  const raw = String(value);
  if (raw.includes('"') || raw.includes(',') || raw.includes('\n')) {
    return `"${raw.replace(/"/g, '""')}"`;
  }
  return raw;
};

const buildPaymentBatchCsv = rows => {
  const headers = [
    'Batch ID',
    'Packet ID',
    'Line ID',
    'Case ID',
    'Case Number',
    'Client Name',
    'Payment Type',
    'Payee Type',
    'Payee Name',
    'Amount',
    'Currency',
    'Pot Code',
    'Pot Name',
    'Funding Stream',
    'Reporting Unit',
    'Service Period Start',
    'Service Period End',
    'Requested Payment Date',
    'Status',
  ];
  const lines = [headers.map(formatCsvValue).join(',')];
  (rows || []).forEach(row => {
    const line = [
      row.batchId,
      row.packetId,
      row.lineId,
      row.caseId,
      row.caseNumber,
      row.clientName,
      row.paymentType,
      row.payeeType,
      row.payeeName,
      row.amount,
      row.currency,
      row.potCode,
      row.potName,
      row.fundingStream,
      row.reportingUnit,
      row.servicePeriodStart,
      row.servicePeriodEnd,
      row.requestedPaymentDate,
      row.status,
    ];
    lines.push(line.map(formatCsvValue).join(','));
  });
  return lines.join('\n');
};

