async function fetchPaymentLedgerExportRows(connection = null) {
  const runner = connection || pool;
  if (!runner) return [];
  const [rows] = await runner.query(
    `SELECT ft.id AS transaction_id,
            ft.case_intervention_id,
            ft.transaction_date,
            ft.posted_at,
            ft.amount,
            ft.budget_pot_id,
            ft.evidence_ref,
            ft.metadata,
            ppl.intervention_id,
            ppl.funding_stream,
            bp.funding_source AS pot_funding_source,
            pp.reporting_unit
       FROM finance_transaction ft
       LEFT JOIN payment_line_transaction plt ON plt.finance_transaction_id = ft.id
       LEFT JOIN payment_packet_line ppl ON ppl.id = plt.payment_packet_line_id
       LEFT JOIN payment_packet pp ON pp.id = ppl.payment_packet_id
       LEFT JOIN budget_pot bp ON bp.id = ft.budget_pot_id
      WHERE plt.payment_packet_line_id IS NOT NULL
         OR JSON_UNQUOTE(JSON_EXTRACT(ft.metadata, '$.source')) = ?
      ORDER BY ft.id ASC`,
    [MANUAL_BACKLOAD_FINANCE_SOURCE]
  );
  return (rows || []).map(row => {
    const meta = safeJsonParse(row.metadata, {}) || {};
    let evidenceDocumentIds = [];
    if (Array.isArray(meta.evidenceDocumentIds)) {
      evidenceDocumentIds = meta.evidenceDocumentIds.map(value => String(value)).filter(Boolean);
    } else if (typeof row.evidence_ref === 'string') {
      evidenceDocumentIds = row.evidence_ref
        .split(',')
        .map(entry => entry.trim())
        .filter(Boolean);
    }
    return {
      transactionId: row.transaction_id ? String(row.transaction_id) : null,
      postingDate: toDateOnlyString(row.transaction_date || row.posted_at),
      amount: Number(row.amount || 0),
      potId: row.budget_pot_id ? String(row.budget_pot_id) : null,
      fundingStream:
        row.funding_stream ||
        meta.fundingStream ||
        meta.funding_stream ||
        row.pot_funding_source ||
        null,
      interventionId:
        row.intervention_id
          ? String(row.intervention_id)
          : row.case_intervention_id
          ? String(row.case_intervention_id)
          : null,
      reportingUnit: row.reporting_unit || meta.reportingUnit || meta.reporting_unit || null,
      evidenceDocumentIds,
    };
  });
}

const buildPacketAttachmentSummary = packet => {
  const documents = Array.isArray(packet?.documents) ? packet.documents : [];
  return documents
    .map(doc => ({
      documentId: doc.documentId || doc.document_id || doc.id || null,
      name: doc.documentName || doc.document_name || doc.label || doc.file_name || doc.name || null,
      type: doc.type || doc.evidenceType || doc.evidence_type || null,
    }))
    .filter(entry => entry.documentId || entry.name || entry.type);
};

const formatPaymentPayeeAddress = (address = {}) => {
  if (!address || typeof address !== 'object') return null;
  const parts = [
    normaliseString(address.street || address.line1 || null),
    normaliseString(address.city || null),
    normaliseString(address.province || null),
    normaliseString(address.postalCode || address.postal_code || null),
  ].filter(Boolean);
  return parts.length ? parts.join(', ') : null;
};

const sanitizePaymentPayeeIdentity = (raw) => {
  if (!raw || typeof raw !== 'object') return null;
  const addressRaw =
    raw.currentAddress && typeof raw.currentAddress === 'object'
      ? raw.currentAddress
      : {};
  const streetPrimary = normaliseString(
    addressRaw.street ||
      addressRaw.line1 ||
      raw.street ||
      raw.line1 ||
      raw.addressLine1 ||
      raw.address_line_1 ||
      null
  );
  const streetSecondary = normaliseString(
    addressRaw.line2 ||
      raw.line2 ||
      raw.addressLine2 ||
      raw.address_line_2 ||
      null
  );
  const street = [streetPrimary, streetSecondary].filter(Boolean).join(', ') || null;
  const city = normaliseString(addressRaw.city || raw.city || null);
  const provinceInput = addressRaw.province || raw.province || null;
  const province =
    normalizeRegionCode(provinceInput) ||
    (normaliseString(provinceInput) ? normaliseString(provinceInput).toUpperCase() : null);
  const postalRaw = normaliseString(addressRaw.postalCode || raw.postalCode || null);
  const postalCompact = postalRaw ? postalRaw.replace(/\s+/g, '').toUpperCase() : null;
  const postalCode =
    postalCompact && postalCompact.length === 6
      ? `${postalCompact.slice(0, 3)} ${postalCompact.slice(3)}`
      : postalCompact || null;
  const currentAddress = {
    street,
    city,
    province,
    postalCode,
    formatted: formatPaymentPayeeAddress({ street, city, province, postalCode }),
  };
  const identity = {
    legalFirstName: normaliseString(raw.legalFirstName || raw.firstName || null),
    legalLastName: normaliseString(raw.legalLastName || raw.lastName || null),
    dateOfBirth: toDateOnlyString(raw.dateOfBirth || raw.dob || null),
    sinMasked: maskSinForDisplay(
      raw.sinMasked ||
      raw.sin ||
      raw.sinDigits ||
      raw.socialInsuranceNumber ||
      null
    ),
    currentAddress,
    email: normaliseString(raw.email || raw.emailAddress || null),
    phone: normaliseString(raw.phone || raw.phoneNumber || null),
  };
  const hasAddress = !!(
    identity.currentAddress.street ||
    identity.currentAddress.city ||
    identity.currentAddress.province ||
    identity.currentAddress.postalCode
  );
  if (
    !identity.legalFirstName &&
    !identity.legalLastName &&
    !identity.dateOfBirth &&
    !identity.sinMasked &&
    !hasAddress &&
    !identity.email &&
    !identity.phone
  ) {
    return null;
  }
  return identity;
};

const buildPaymentPayeeIdentityRows = (payeeIdentity) => {
  const identity = sanitizePaymentPayeeIdentity(payeeIdentity);
  if (!identity) return [];
  return [
    { label: 'Legal First Name', value: identity.legalFirstName || '-' },
    { label: 'Legal Last Name', value: identity.legalLastName || '-' },
    { label: 'Date of Birth', value: identity.dateOfBirth || '-' },
    { label: 'SIN (masked)', value: identity.sinMasked || '-' },
    { label: 'Current Address', value: identity.currentAddress?.formatted || '-' },
    { label: 'Email Address', value: identity.email || '-' },
    { label: 'Phone Number', value: identity.phone || '-' },
  ];
};

async function resolvePaymentPacketPayeeIdentity({ packetId, packet = null, connection = null }) {
  const runner = connection || pool;
  const packetValue = parsePaymentPacketId(packetId || packet?.id);
  const packetIdentity = sanitizePaymentPayeeIdentity(packet?.payeeIdentity || null);
  if (!runner || !packetValue) return packetIdentity;
  try {
    const [[row]] = await runner.query(
      `SELECT pp.id,
              pp.case_id,
              pp.client_id,
              c.case_context_json,
              a.payload_json AS application_payload_json,
              cl.first_name AS client_first_name,
              cl.last_name AS client_last_name,
              cl.address_json AS client_address_json
         FROM payment_packet pp
         LEFT JOIN iset_case c ON c.id = pp.case_id
         ${buildCasePrimaryApplicationJoinSql('c', 'a')}
         LEFT JOIN client cl ON cl.id = pp.client_id
        WHERE pp.id = ?
        LIMIT 1`,
      [packetValue]
    );
    if (!row) return packetIdentity;
    const caseContext = safeJsonParse(row.case_context_json, null) || {};
    const parsedPayload = safeJsonParse(row.application_payload_json, null);
    const payload =
      parsedPayload && typeof parsedPayload === 'object'
        ? parsedPayload
        : {};
    const answers =
      payload?.answers && typeof payload.answers === 'object'
        ? payload.answers
        : {};
    const context = { payload, answers, caseContext };
    const contact = extractContactDetails(context) || {};
    let currentAddress = extractAddress(context);
    if (!currentAddress) {
      const parsedClientAddress = safeJsonParse(row.client_address_json, null);
      if (parsedClientAddress && typeof parsedClientAddress === 'object') {
        const candidateAddress =
          parsedClientAddress.address && typeof parsedClientAddress.address === 'object'
            ? parsedClientAddress.address
            : parsedClientAddress;
        currentAddress = extractAddressFromStructuredObject(candidateAddress);
      }
    }
    const resolvedIdentity = sanitizePaymentPayeeIdentity({
      legalFirstName:
        caseContext?.firstName ||
        caseContext?.first_name ||
        extractFirstName(context) ||
        row.client_first_name ||
        null,
      legalLastName:
        caseContext?.lastName ||
        caseContext?.last_name ||
        extractLastName(context) ||
        row.client_last_name ||
        null,
      dateOfBirth:
        caseContext?.dateOfBirth ||
        caseContext?.date_of_birth ||
        toDateOnlyString(extractDob(context)) ||
        null,
      sinMasked:
        caseContext?.sin ||
        caseContext?.socialInsuranceNumber ||
        extractSin(context) ||
        null,
      currentAddress: {
        street: currentAddress?.line1 || null,
        line2: currentAddress?.line2 || null,
        city: currentAddress?.city || null,
        province: currentAddress?.province || null,
        postalCode: currentAddress?.postalCode || null,
      },
      email:
        caseContext?.emailPrimary ||
        contact.email ||
        null,
      phone:
        caseContext?.phonePrimary ||
        contact.phone ||
        caseContext?.phoneAlt ||
        contact.alternatePhone ||
        null,
    });
    if (!packetIdentity) return resolvedIdentity;
    if (!resolvedIdentity) return packetIdentity;
    return sanitizePaymentPayeeIdentity({
      legalFirstName: resolvedIdentity.legalFirstName || packetIdentity.legalFirstName,
      legalLastName: resolvedIdentity.legalLastName || packetIdentity.legalLastName,
      dateOfBirth: resolvedIdentity.dateOfBirth || packetIdentity.dateOfBirth,
      sinMasked: resolvedIdentity.sinMasked || packetIdentity.sinMasked,
      currentAddress: {
        street: resolvedIdentity.currentAddress?.street || packetIdentity.currentAddress?.street,
        city: resolvedIdentity.currentAddress?.city || packetIdentity.currentAddress?.city,
        province: resolvedIdentity.currentAddress?.province || packetIdentity.currentAddress?.province,
        postalCode: resolvedIdentity.currentAddress?.postalCode || packetIdentity.currentAddress?.postalCode,
      },
      email: resolvedIdentity.email || packetIdentity.email,
      phone: resolvedIdentity.phone || packetIdentity.phone,
    });
  } catch (err) {
    console.warn('[payments] failed to resolve payee identity', err?.message || err);
    return packetIdentity;
  }
}

const getPaymentPacketBundleSigningSecret = () => (
  process.env.PAYMENT_PACKET_BUNDLE_SECRET ||
  process.env.ADMIN_DOWNLOAD_TOKEN_SECRET ||
  process.env.DEV_AUTH_TOKEN ||
  process.env.OBJECT_SECRET_KEY ||
  process.env.DB_PASS ||
  PAYMENT_PACKET_BUNDLE_FALLBACK_SECRET
);

const encodePaymentPacketBundleTokenPart = value =>
  Buffer.from(JSON.stringify(value), 'utf8').toString('base64url');

const signPaymentPacketBundlePayload = payloadPart =>
  crypto
    .createHmac('sha256', getPaymentPacketBundleSigningSecret())
    .update(payloadPart)
    .digest('base64url');

const createPaymentPacketBundleToken = ({ packetId, expiresInSeconds = PAYMENT_PACKET_BUNDLE_EXPIRY_SECONDS }) => {
  const packetValue = parsePaymentPacketId(packetId);
  if (!Number.isFinite(packetValue)) return null;
  const expiresAtSeconds = Math.floor(Date.now() / 1000) + Math.max(60, Number(expiresInSeconds) || PAYMENT_PACKET_BUNDLE_EXPIRY_SECONDS);
  const payloadPart = encodePaymentPacketBundleTokenPart({
    v: 1,
    scope: 'payment_packet_bundle',
    packetId: String(packetValue),
    exp: expiresAtSeconds,
  });
  return `${payloadPart}.${signPaymentPacketBundlePayload(payloadPart)}`;
};

const verifyPaymentPacketBundleToken = ({ token, packetId }) => {
  const packetValue = parsePaymentPacketId(packetId);
  if (!token || !Number.isFinite(packetValue)) {
    return { ok: false, error: 'invalid_payment_packet_bundle_token' };
  }
  const [payloadPart, signaturePart] = String(token).split('.');
  if (!payloadPart || !signaturePart) {
    return { ok: false, error: 'invalid_payment_packet_bundle_token' };
  }
  const expectedSignature = signPaymentPacketBundlePayload(payloadPart);
  const actualBuffer = Buffer.from(signaturePart);
  const expectedBuffer = Buffer.from(expectedSignature);
  if (actualBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(actualBuffer, expectedBuffer)) {
    return { ok: false, error: 'invalid_payment_packet_bundle_token' };
  }
  let payload = null;
  try {
    payload = JSON.parse(Buffer.from(payloadPart, 'base64url').toString('utf8'));
  } catch (_) {
    return { ok: false, error: 'invalid_payment_packet_bundle_token' };
  }
  if (
    payload?.scope !== 'payment_packet_bundle' ||
    String(payload?.packetId || '') !== String(packetValue)
  ) {
    return { ok: false, error: 'invalid_payment_packet_bundle_token' };
  }
  const expiresAtSeconds = Number(payload?.exp);
  if (!Number.isFinite(expiresAtSeconds) || expiresAtSeconds <= Math.floor(Date.now() / 1000)) {
    return { ok: false, error: 'payment_packet_bundle_token_expired' };
  }
  return { ok: true, payload, expiresAt: new Date(expiresAtSeconds * 1000) };
};

const resolveRequestPublicBaseUrl = req => {
  const configured = (
    process.env.PAYMENT_PACKET_BUNDLE_PUBLIC_BASE_URL ||
    process.env.ADMIN_PUBLIC_BASE_URL ||
    process.env.PUBLIC_ADMIN_BASE_URL ||
    process.env.API_BASE ||
    process.env.REACT_APP_API_BASE_URL ||
    ''
  ).trim();
  if (configured) return configured.replace(/\/+$/, '');
  const forwardedProto = String(req?.get?.('x-forwarded-proto') || '').split(',')[0].trim();
  const forwardedHost = String(req?.get?.('x-forwarded-host') || '').split(',')[0].trim();
  const proto = forwardedProto || req?.protocol || 'http';
  const host = forwardedHost || req?.get?.('host') || `localhost:${port}`;
  return `${proto}://${host}`.replace(/\/+$/, '');
};

const buildPaymentPacketEvidenceBundle = async ({ packetId, connection }) => {
  const runner = connection || pool;
  if (!packetId || !runner) return null;
  const evidenceRows = await fetchPaymentEvidenceDocumentRows({ packetId, connection: runner });
  const entries = [];
  const entryNames = new Set();

  for (const doc of evidenceRows) {
    if (!doc?.file_path) continue;
    let buffer = null;
    try {
      buffer = await loadDocumentBuffer(doc);
    } catch (err) {
      console.warn(
        '[payments] skipped payment bundle document %s for packet %s: %s',
        doc.document_id || doc.link_id || doc.file_name || 'unknown',
        packetId,
        err?.message || err
      );
      continue;
    }
    if (!buffer) continue;
    const safeName = sanitizeArchiveName(doc.file_name || `document-${doc.document_id || doc.link_id}`);
    const parsedName = path.parse(safeName);
    const baseName = `${doc.document_id ? `${doc.document_id}-` : ''}${parsedName.name || 'document'}`;
    const extension = parsedName.ext || '';
    let archiveName = `${baseName}${extension}`;
    let duplicateIndex = 2;
    while (entryNames.has(archiveName)) {
      archiveName = `${baseName}-${duplicateIndex}${extension}`;
      duplicateIndex += 1;
    }
    entryNames.add(archiveName);
    entries.push({ name: archiveName, buffer });
  }
  if (!entries.length) return null;

  const zipBuffer = await buildZipBuffer({ entries });
  const filename = `payment-packet-${packetId}-bundle-${Date.now()}.zip`;
  return { buffer: zipBuffer, fileName: filename, evidenceCount: entries.length };
};

const buildPaymentPacketBundleLink = async ({
  packetId,
  req,
  connection,
  expiresInSeconds,
}) => {
  const evidenceRows = await fetchPaymentEvidenceDocumentRows({ packetId, connection: connection || pool });
  if (!evidenceRows.some(row => row?.file_path)) return { url: null, expiresAt: null };
  const token = createPaymentPacketBundleToken({ packetId, expiresInSeconds });
  if (!token) return { url: null, expiresAt: null };
  const expiresAt = new Date(Date.now() + (Number(expiresInSeconds) || PAYMENT_PACKET_BUNDLE_EXPIRY_SECONDS) * 1000);
  const baseUrl = resolveRequestPublicBaseUrl(req);
  const url = `${baseUrl}/api/finance/payment-packets/${encodeURIComponent(String(packetId))}/document-bundle?token=${encodeURIComponent(token)}`;
  return { url, expiresAt };
};

const buildPaymentPacketEmail = ({
  packet,
  regionCode,
  note,
  statusOverride = null,
  bundleLink = null,
  bundleExpiresAt = null,
  bundleExpiresInDays = null,
  payeeIdentity = null,
}) => {
  const lines = Array.isArray(packet?.lines) ? packet.lines : [];
  const packetIdLabel = formatPacketIdLabel(packet?.id || '');
  const clientName = normaliseString(
    packet?.clientName ||
      packet?.client_name ||
      packet?.metadata?.clientName ||
      packet?.metadata?.client_name
  );
  const subjectPrefix = [packetIdLabel, clientName].filter(Boolean).join(' - ');
  const subject = subjectPrefix
    ? `${subjectPrefix} payment packet submitted to finance`
    : 'Payment packet submitted to finance';

  const attachments = buildPacketAttachmentSummary(packet);
  const uniqueValues = values =>
    Array.from(new Set((Array.isArray(values) ? values : []).map(value => String(value || '').trim()).filter(Boolean)));
  const formatLineType = (line, index) =>
    line?.paymentType ||
    line?.payment_type ||
    (line?.id ? `Line ${line.id}` : `Line ${index + 1}`);
  const uniquePayeeNames = uniqueValues(lines.map(line => line?.payeeName || line?.payee_name || null));
  const uniquePayeeReferences = uniqueValues(lines.map(line => line?.payeeReference || line?.payee_reference || null));
  const uniquePotLabels = uniqueValues(lines.map(line => line?.potName || line?.pot_name || line?.potId || line?.budget_pot_id || null));
  const uniqueFundingStreams = uniqueValues(lines.map(line => line?.fundingStream || line?.funding_stream || null));
  const uniqueReportingUnits = uniqueValues(
    lines.map(line => line?.reportingUnit || line?.reporting_unit || null).concat([
      packet?.reportingUnit || packet?.reporting_unit || regionCode || null,
    ])
  );

  const payeeSummary =
    uniquePayeeNames.length === 1
      ? uniquePayeeNames[0]
      : uniquePayeeNames.length > 1
        ? 'Multiple payees in packet'
        : '-';
  const vendorReference = uniquePayeeReferences.length === 1 ? uniquePayeeReferences[0] : null;
  const includeRequestedPaymentDateColumn = lines.some(line => Boolean(line?.requestedPaymentDate));
  const includePayeeReferenceColumn = lines.some(line => Boolean(line?.payeeReference || line?.payee_reference));
  const paymentTableColumns = [
    { key: 'paymentType', label: 'Payment type' },
    { key: 'amount', label: 'Amount' },
    { key: 'invoiceReference', label: 'Invoice reference' },
    ...(includeRequestedPaymentDateColumn
      ? [{ key: 'requestedPaymentDate', label: 'Requested payment date' }]
      : []),
    ...(includePayeeReferenceColumn
      ? [{ key: 'payeeReference', label: 'Payee reference' }]
      : []),
  ];
  const paymentTableRows = lines.map((line, index) => ({
    paymentType: formatLineType(line, index),
    amount: formatCurrencyCad(line?.amount || 0),
    invoiceReference: line?.invoiceReferenceNumber || '',
    requestedPaymentDate: line?.requestedPaymentDate || '',
    payeeReference: line?.payeeReference || line?.payee_reference || '',
  }));
  const bundleExpiresInDaysNumber = Number(bundleExpiresInDays);
  const bundleExpiryDate = bundleExpiresAt ? toDateOnlyString(bundleExpiresAt) : null;
  const bundleExpiryText =
    bundleExpiryDate && Number.isFinite(bundleExpiresInDaysNumber) && bundleExpiresInDaysNumber > 0
      ? `Link expires in ${bundleExpiresInDaysNumber} days (${bundleExpiryDate}).`
      : bundleExpiryDate
        ? `Link expires on ${bundleExpiryDate}.`
        : null;

  const bodyTextLines = [
    'A payment packet request has been submitted to finance for processing.',
    '',
    'Payee',
    `- Payee name: ${payeeSummary}`,
    ...(vendorReference ? [`- Vendor reference: ${vendorReference}`] : []),
    '',
    'Payment Instructions',
    paymentTableColumns.map(column => column.label).join(' | '),
    ...(paymentTableRows.length
      ? paymentTableRows.map(row =>
          paymentTableColumns
            .map(column => row[column.key] || '')
            .join(' | ')
        )
      : ['No payment lines listed.']),
    '',
    'Coding',
    `- Budget pot: ${uniquePotLabels[0] || '-'}`,
    `- Funding stream: ${uniqueFundingStreams[0] || '-'}`,
    `- Reporting unit: ${uniqueReportingUnits[0] || '-'}`,
    ...(bundleLink
      ? [
          '',
          'Packet bundle',
          `- Download packet bundle: ${bundleLink}`,
          ...(bundleExpiryText ? [`- ${bundleExpiryText}`] : []),
        ]
      : []),
    ...(note ? ['', `Requester note: ${note}`] : []),
  ];
  const bodyText = bodyTextLines.join('\n');

  const bodyHtml = `
    <p>A payment packet request has been submitted to finance for processing.</p>
    <p><strong>Payee</strong></p>
    <ul>
      <li>Payee name: ${escapeHtml(payeeSummary)}</li>
      ${vendorReference ? `<li>Vendor reference: ${escapeHtml(vendorReference)}</li>` : ''}
    </ul>
    <p><strong>Payment Instructions</strong></p>
    <table border="1" cellpadding="6" cellspacing="0" style="border-collapse: collapse; width: 100%;">
      <thead>
        <tr>
          ${paymentTableColumns.map(column => `<th align="left">${escapeHtml(column.label)}</th>`).join('')}
        </tr>
      </thead>
      <tbody>
        ${(paymentTableRows.length
          ? paymentTableRows
          : [{ paymentType: 'No payment lines listed.', amount: '', invoiceReference: '', requestedPaymentDate: '', payeeReference: '' }]
        ).map(row => `
          <tr>
            ${paymentTableColumns.map(column => `<td>${escapeHtml(row[column.key] || '')}</td>`).join('')}
          </tr>
        `).join('')}
      </tbody>
    </table>
    <p><strong>Coding</strong></p>
    <ul>
      <li>Budget pot: ${escapeHtml(uniquePotLabels[0] || '-')}</li>
      <li>Funding stream: ${escapeHtml(uniqueFundingStreams[0] || '-')}</li>
      <li>Reporting unit: ${escapeHtml(uniqueReportingUnits[0] || '-')}</li>
    </ul>
    ${bundleLink ? `
      <p><strong>Packet bundle</strong></p>
      <ul>
        <li><a href="${escapeHtml(bundleLink)}">Download packet bundle</a></li>
        ${bundleExpiryText ? `<li>${escapeHtml(bundleExpiryText)}</li>` : ''}
      </ul>
    ` : ''}
    ${note ? `<p>Requester note: ${escapeHtml(note)}</p>` : ''}
  `;

  return { subject, bodyText, bodyHtml, attachments };
};

