app.post('/api/finance/budget-pots', async (req, res) => {
  if (requireFinanceRole(req, res)) return;
  try {
    const body = req.body || {};
    if (!body.name || !body.code) {
      return res.status(400).json({ error: 'name_and_code_required' });
    }
    const glExternalRaw = body.glProjectCodeExternal || body.gl_project_code_external || null;
    const glInternalRaw = body.glProjectCodeInternal || body.gl_project_code_internal || null;
    const glExternal = glExternalRaw ? normalizeGlCode(glExternalRaw) : null;
    const glInternal = glInternalRaw ? normalizeGlCode(glInternalRaw) : null;
    if (glExternal && glExternal.length > 64) {
      return res.status(400).json({ error: 'invalid_gl_project_code_external', message: 'External GL/project code must be 64 characters or fewer.' });
    }
    if (glInternal && glInternal.length > 64) {
      return res.status(400).json({ error: 'invalid_gl_project_code_internal', message: 'Internal GL/project code must be 64 characters or fewer.' });
    }
    const regions = normalizeRegionCodes(body.regions || body.regionCodes || body.region_codes);
    const allowedRegions = await fetchValidRegionCodeSet();
    const invalidRegions = regions.filter(code => !allowedRegions.has(code));
    if (invalidRegions.length) {
      return res.status(400).json({ error: 'invalid_regions', invalidRegions });
    }
    const fundingSource = body.fundingSource || body.funding_source || null;
    const normalizedFundingSource = fundingSource ? normalizeFundingSource(fundingSource) : null;
    if (fundingSource && !normalizedFundingSource) {
      return res.status(400).json({ error: 'invalid_funding_source' });
    }
    const fiscalYearTagInput = body.fiscalYearTag || body.fiscal_year_tag || null;
    const fiscalYearTag = fiscalYearTagInput ? normalizeFiscalYearTag(fiscalYearTagInput) : null;
    if (fiscalYearTagInput && !fiscalYearTag) {
      return res.status(400).json({ error: 'invalid_fiscal_year_tag' });
    }
    const restricted = body.isRestricted !== undefined
      ? normalizeBooleanLike(body.isRestricted)
      : body.is_restricted !== undefined
        ? normalizeBooleanLike(body.is_restricted)
        : null;
    if (restricted === null && (body.isRestricted !== undefined || body.is_restricted !== undefined)) {
      return res.status(400).json({ error: 'invalid_is_restricted' });
    }
    const agreementId = typeof body.agreementId === 'string'
      ? body.agreementId.trim() || null
      : body.agreement_id || null;
    const parentId = body.parentId ? Number(body.parentId) : null;
    const insertSql = `
      INSERT INTO budget_pot
        (parent_id, agreement_code, agreement_id, fiscal_year, fiscal_year_tag, gl_project_code_external, gl_project_code_internal, name, code, pot_type, funding_source, is_restricted, owner, is_admin_cap, is_active,
         approved_amount, adjusted_amount, committed_amount, actual_amount, forecast_amount, admin_share_amount, metadata)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
    `;
    const params = [
      Number.isFinite(parentId) ? parentId : null,
      body.agreementCode || null,
      agreementId,
      body.fiscalYear || null,
      fiscalYearTag,
      glExternal,
      glInternal,
      body.name,
      body.code,
      body.nodeType || 'budget',
      normalizedFundingSource,
      restricted === null ? 0 : restricted ? 1 : 0,
      body.owner || null,
      body.isAdminCap ? 1 : 0,
      body.isActive === false ? 0 : 1,
      Number(body.approved) || 0,
      Number(body.adjusted ?? body.approved) || 0,
      Number(body.committed) || 0,
      Number(body.actual) || 0,
      Number(body.forecast ?? body.adjusted ?? body.approved) || 0,
      Number(body.adminShare) || 0,
      body.metadata ? JSON.stringify(body.metadata) : JSON.stringify({ nodeType: body.nodeType || 'budget' }),
    ];
    const [result] = await pool.query(insertSql, params);
    if (regions.length) {
      await replacePotRegions(result.insertId, regions);
    }
    const [[row]] = await pool.query('SELECT * FROM budget_pot WHERE id = ? LIMIT 1', [result.insertId]);
    const regionMap = await fetchPotRegions([result.insertId]);
    res.status(201).json(mapBudgetPotRow({ ...row, regions: regionMap.get(String(result.insertId)) || [] }));
  } catch (err) {
    console.error('[finance] failed to create budget pot', err);
    res.status(500).json({ error: 'failed_to_create_budget_pot' });
  }
});

app.put('/api/finance/budget-pots/:id', async (req, res) => {
  if (requireFinanceRole(req, res)) return;
  try {
    const potId = Number(req.params.id);
    if (!Number.isFinite(potId)) {
      return res.status(400).json({ error: 'invalid_pot_id' });
    }
    const body = req.body || {};
    const fundingSourceRaw = body.fundingSource || body.funding_source;
    const fundingSource = fundingSourceRaw ? normalizeFundingSource(fundingSourceRaw) : null;
    if (fundingSourceRaw && !fundingSource) {
      return res.status(400).json({ error: 'invalid_funding_source' });
    }
    const glExternalRaw = body.glProjectCodeExternal || body.gl_project_code_external;
    const glInternalRaw = body.glProjectCodeInternal || body.gl_project_code_internal;
    const glExternal = glExternalRaw ? normalizeGlCode(glExternalRaw) : null;
    const glInternal = glInternalRaw ? normalizeGlCode(glInternalRaw) : null;
    if (glExternalRaw !== undefined && glExternal && glExternal.length > 64) {
      return res.status(400).json({ error: 'invalid_gl_project_code_external', message: 'External GL/project code must be 64 characters or fewer.' });
    }
    if (glInternalRaw !== undefined && glInternal && glInternal.length > 64) {
      return res.status(400).json({ error: 'invalid_gl_project_code_internal', message: 'Internal GL/project code must be 64 characters or fewer.' });
    }
    const fiscalYearTagRaw = body.fiscalYearTag || body.fiscal_year_tag;
    const fiscalYearTag = fiscalYearTagRaw ? normalizeFiscalYearTag(fiscalYearTagRaw) : null;
    if (fiscalYearTagRaw && !fiscalYearTag) {
      return res.status(400).json({ error: 'invalid_fiscal_year_tag' });
    }
    const restrictedRaw = body.isRestricted !== undefined ? body.isRestricted : body.is_restricted;
    const restricted = restrictedRaw !== undefined ? normalizeBooleanLike(restrictedRaw) : null;
    if (restrictedRaw !== undefined && restricted === null) {
      return res.status(400).json({ error: 'invalid_is_restricted' });
    }
    const agreementId =
      typeof body.agreementId === 'string'
        ? body.agreementId.trim() || null
        : body.agreement_id !== undefined
          ? body.agreement_id
          : undefined;
    const regionsInput = body.regions || body.regionCodes || body.region_codes;
    const regionsProvided = regionsInput !== undefined;
    const regions = regionsProvided ? normalizeRegionCodes(regionsInput) : [];
    if (regionsProvided) {
      const allowedRegions = await fetchValidRegionCodeSet();
      const invalidRegions = regions.filter(code => !allowedRegions.has(code));
      if (invalidRegions.length) {
        return res.status(400).json({ error: 'invalid_regions', invalidRegions });
      }
    }
    const fields = [];
    const params = [];
    const assign = (col, val) => { fields.push(`${col} = ?`); params.push(val); };
    if (body.name !== undefined) assign('name', body.name);
    if (body.code !== undefined) assign('code', body.code);
    if (body.pot_type !== undefined || body.nodeType !== undefined) assign('pot_type', body.nodeType || body.pot_type);
    if (body.owner !== undefined) assign('owner', body.owner);
    if (body.parentId !== undefined) assign('parent_id', body.parentId ? Number(body.parentId) : null);
    if (body.agreementCode !== undefined) assign('agreement_code', body.agreementCode);
    if (agreementId !== undefined) assign('agreement_id', agreementId);
    if (body.fiscalYear !== undefined) assign('fiscal_year', body.fiscalYear);
    if (fiscalYearTagRaw !== undefined) assign('fiscal_year_tag', fiscalYearTag);
    if (glExternalRaw !== undefined) assign('gl_project_code_external', glExternal);
    if (glInternalRaw !== undefined) assign('gl_project_code_internal', glInternal);
    if (fundingSourceRaw !== undefined) assign('funding_source', fundingSource);
    if (restrictedRaw !== undefined) assign('is_restricted', restricted ? 1 : 0);
    if (body.is_admin_cap !== undefined || body.isAdminCap !== undefined) assign('is_admin_cap', body.isAdminCap ? 1 : 0);
    if (body.is_active !== undefined || body.isActive !== undefined) assign('is_active', body.isActive === false ? 0 : 1);
    if (body.approved !== undefined) assign('approved_amount', Number(body.approved) || 0);
    if (body.adjusted !== undefined) assign('adjusted_amount', Number(body.adjusted) || 0);
    if (body.committed !== undefined) assign('committed_amount', Number(body.committed) || 0);
    if (body.actual !== undefined) assign('actual_amount', Number(body.actual) || 0);
    if (body.forecast !== undefined) assign('forecast_amount', Number(body.forecast) || 0);
    if (body.adminShare !== undefined) assign('admin_share_amount', Number(body.adminShare) || 0);
    if (body.metadata !== undefined || body.nodeType !== undefined) {
      const currentMeta = body.metadata || {};
      const nodeType = body.nodeType || body.pot_type;
      const merged = { ...(typeof currentMeta === 'object' && currentMeta !== null ? currentMeta : {}), ...(nodeType ? { nodeType } : {}) };
      assign('metadata', JSON.stringify(merged));
    }
    if (!fields.length) {
      return res.status(400).json({ error: 'no_fields_to_update' });
    }
    params.push(potId);
    await pool.query(`UPDATE budget_pot SET ${fields.join(', ')} WHERE id = ?`, params);
    if (regionsProvided) {
      await replacePotRegions(potId, regions);
    }
    const [[row]] = await pool.query('SELECT * FROM budget_pot WHERE id = ? LIMIT 1', [potId]);
    if (!row) {
      return res.status(404).json({ error: 'pot_not_found' });
    }
    const regionMap = await fetchPotRegions([potId]);
    res.status(200).json(mapBudgetPotRow({ ...row, regions: regionMap.get(String(potId)) || [] }));
  } catch (err) {
    console.error('[finance] failed to update budget pot', err);
    res.status(500).json({ error: 'failed_to_update_budget_pot' });
  }
});

async function fetchAllocationById(allocationId) {
  const [[row]] = await pool.query(
    `SELECT ba.*,
            sp.name AS source_pot_name,
            dp.name AS dest_pot_name,
            u.name AS proposed_by_name,
            u.email AS proposed_by_email,
            au.name AS approved_by_name,
            au.email AS approved_by_email,
            ru.name AS rejected_by_name,
            ru.email AS rejected_by_email
       FROM budget_allocation ba
       LEFT JOIN budget_pot sp ON sp.id = ba.source_pot_id
       LEFT JOIN budget_pot dp ON dp.id = ba.dest_pot_id
       LEFT JOIN user u ON u.id = ba.proposed_by_user_id
       LEFT JOIN user au ON au.id = ba.approved_by_user_id
       LEFT JOIN user ru ON ru.id = ba.rejected_by_user_id
      WHERE ba.id = ?
      LIMIT 1`,
    [allocationId]
  );
  return row ? mapAllocationRow(row) : null;
}

const resolveEffectiveDate = allocation => {
  const raw =
    allocation?.metadata?.effectiveDate ||
    allocation?.metadata?.effective_date ||
    allocation?.effectiveDate ||
    allocation?.effective_date;
  if (!raw) return null;
  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return null;
  return date;
};

async function applyAllocationTransaction({ allocation, appliedAtOverride = null }) {
  const amount = Number(allocation.amount || 0);
  if (!Number.isFinite(amount) || amount <= 0) {
    throw new Error('invalid_amount');
  }
  const effectiveDate = resolveEffectiveDate(allocation);
  const appliedAt = appliedAtOverride || effectiveDate || new Date();
  // Capture before/after balances for audit using remaining available authority.
  const [[sourcePot]] = await pool.query(
    'SELECT adjusted_amount, committed_amount, actual_amount, metadata FROM budget_pot WHERE id = ? LIMIT 1',
    [allocation.sourcePotId]
  );
  const [[destPot]] = await pool.query(
    'SELECT adjusted_amount, committed_amount, actual_amount, metadata FROM budget_pot WHERE id = ? LIMIT 1',
    [allocation.destPotId]
  );
  const availableFor = pot =>
    pot
      ? Number(pot.adjusted_amount || 0) -
        Number(pot.committed_amount || 0) -
        Number(pot.actual_amount || 0)
      : null;
  const beforeBalances = {
    source: availableFor(sourcePot),
    destination: availableFor(destPot),
  };
  const afterBalances = {
    source: Number.isFinite(beforeBalances.source) ? beforeBalances.source - amount : null,
    destination: Number.isFinite(beforeBalances.destination)
      ? beforeBalances.destination + amount
      : null,
  };
  const meta = allocation.metadata || {};
  const appliedByName =
    allocation.appliedBy ||
    allocation.approvedBy ||
    meta.appliedBy ||
    allocation.requestedBy ||
    'Finance';
  const approvalOwner =
    (Array.isArray(meta.approvers) && meta.approvers.length ? meta.approvers.join(', ') : appliedByName) ||
    appliedByName;
  const allocationEvidence = Array.isArray(meta.evidence) ? meta.evidence : [];
  const normalizeEvidenceEntry = (entry, index) => {
    if (!entry) return null;
    if (typeof entry === 'string') {
      return { id: `alloc-${allocation.id}-ev-${index}`, label: entry, href: null, attachments: [] };
    }
    if (typeof entry === 'object') {
      const label = entry.label || entry.id || String(entry);
      const id = entry.id || `alloc-${allocation.id}-ev-${index}`;
      const attachments = Array.isArray(entry.attachments) ? entry.attachments : [];
      return { id, label, href: entry.href || null, type: entry.type || null, attachments };
    }
    return null;
  };
  const mergeEvidence = (metaObj, entries) => {
    const existing =
      Array.isArray(metaObj.evidence) && metaObj.evidence.length
        ? metaObj.evidence
            .map((entry, idx) => normalizeEvidenceEntry(entry, idx))
            .filter(Boolean)
        : [];
    const incoming = entries
      .map((entry, idx) => normalizeEvidenceEntry(entry, idx + existing.length))
      .filter(Boolean);
    metaObj.evidence = [...existing, ...incoming];
  };

  const sourceMeta = safeJsonParse(sourcePot?.metadata, {});
  const destMeta = safeJsonParse(destPot?.metadata, {});
  const applyAdjustment = (metaObj, entry) => {
    const arr = Array.isArray(metaObj.adjustments) ? metaObj.adjustments.slice() : [];
    arr.push(entry);
    metaObj.adjustments = arr;
  };
  const applyApproval = (metaObj, entry) => {
    const arr = Array.isArray(metaObj.approvals) ? metaObj.approvals.slice() : [];
    arr.push(entry);
    metaObj.approvals = arr;
  };

  const adjustmentDate = toDateOnly(appliedAt);
  applyAdjustment(sourceMeta, {
    id: `alloc-${allocation.id}-out`,
    date: adjustmentDate,
    type: 'Transfer out',
    amount: -amount,
    reason: `Transfer to ${allocation.destPotName || allocation.destPotId || 'destination pot'}`,
    user: appliedByName,
  });
  applyAdjustment(destMeta, {
    id: `alloc-${allocation.id}-in`,
    date: adjustmentDate,
    type: 'Transfer in',
    amount,
    reason: `Transfer from ${allocation.sourcePotName || allocation.sourcePotId || 'source pot'}`,
    user: appliedByName,
  });

  applyApproval(sourceMeta, {
    id: `alloc-${allocation.id}`,
    type: 'Transfer approved',
    date: toDateOnly(allocation.approvedAt || appliedAt),
    owner: approvalOwner,
  });
  applyApproval(destMeta, {
    id: `alloc-${allocation.id}`,
    type: 'Transfer approved',
    date: toDateOnly(allocation.approvedAt || appliedAt),
    owner: approvalOwner,
  });
  mergeEvidence(sourceMeta, allocationEvidence);
  mergeEvidence(destMeta, allocationEvidence);

  const metadata = {
    ...meta,
    evidence: allocationEvidence.map((entry, idx) => normalizeEvidenceEntry(entry, idx)).filter(Boolean),
    beforeBalances,
    afterBalances,
    appliedBy: appliedByName,
    appliedAtEffective: appliedAt.toISOString(),
    scheduledApplyAt: null,
  };

  const conn = await pool.getConnection();
  try {
    await conn.beginTransaction();
    await conn.query(
      `UPDATE budget_pot SET adjusted_amount = adjusted_amount - ?, metadata = ? WHERE id = ?`,
      [amount, JSON.stringify(sourceMeta), allocation.sourcePotId]
    );
    await conn.query(
      `UPDATE budget_pot SET adjusted_amount = adjusted_amount + ?, metadata = ? WHERE id = ?`,
      [amount, JSON.stringify(destMeta), allocation.destPotId]
    );
    await conn.query(
      `UPDATE budget_allocation
          SET status = 'applied',
              metadata = ?,
              applied_at = ?,
              updated_at = NOW()
        WHERE id = ?`,
      [JSON.stringify(metadata), appliedAt, allocation.id]
    );
    await conn.commit();
  } catch (err) {
    await conn.rollback();
    throw err;
  } finally {
    conn.release();
  }
  return fetchAllocationById(allocation.id);
}
app.get('/api/finance/allocations', async (req, res) => {
  if (requireFinanceRole(req, res)) return;
  try {
    const statusesRaw = (req.query.status || req.query.statuses || '').split(',').map(s => s.trim()).filter(Boolean);
    const statusFilter = statusesRaw.length ? statusesRaw : null;
    const where = [];
    const params = [];
    if (statusFilter) {
      where.push(`ba.status IN (${statusFilter.map(() => '?').join(',')})`);
      params.push(...statusFilter);
    }
    const whereClause = where.length ? `WHERE ${where.join(' AND ')}` : '';
    const limit = Math.min(Number(req.query.limit) || 200, 500);
    const [rows] = await pool.query(
      `SELECT ba.*,
              sp.name AS source_pot_name,
              dp.name AS dest_pot_name,
              u.name AS proposed_by_name,
              u.email AS proposed_by_email,
              au.name AS approved_by_name,
              au.email AS approved_by_email,
              ru.name AS rejected_by_name,
              ru.email AS rejected_by_email
         FROM budget_allocation ba
         LEFT JOIN budget_pot sp ON sp.id = ba.source_pot_id
         LEFT JOIN budget_pot dp ON dp.id = ba.dest_pot_id
         LEFT JOIN user u ON u.id = ba.proposed_by_user_id
         LEFT JOIN user au ON au.id = ba.approved_by_user_id
         LEFT JOIN user ru ON ru.id = ba.rejected_by_user_id
        ${whereClause}
        ORDER BY ba.updated_at DESC
        LIMIT ?`,
      [...params, limit]
    );
    res.status(200).json(rows.map(mapAllocationRow));
  } catch (err) {
    console.error('[finance] failed to list allocations', err);
    res.status(500).json({ error: 'failed_to_list_allocations' });
  }
});

