app.post('/api/finance/budget-snapshots', async (req, res) => {
  if (requireFinanceRole(req, res)) return;
  const body = req.body || {};
  const label = typeof body.label === 'string' && body.label.trim() ? body.label.trim() : `Snapshot ${new Date().toISOString()}`;
  const notes = typeof body.notes === 'string' ? body.notes : null;
  const agreementCode = typeof body.agreementCode === 'string' ? body.agreementCode : null;
  const fiscalYear = typeof body.fiscalYear === 'string' ? body.fiscalYear : null;
  // Auth IDs are not guaranteed to exist in user table; store null to avoid FK issues.
  const creator = null;
  try {
    const [pots] = await pool.query('SELECT * FROM budget_pot');
    const regionMap = await fetchPotRegions(pots.map(p => p.id));
    const conn = await pool.getConnection();
    try {
      await conn.beginTransaction();
      const [result] = await conn.query(
        `INSERT INTO budget_snapshot (label, snapshot_at, agreement_code, fiscal_year, created_by_user_id, notes, created_at)
         VALUES (?, NOW(), ?, ?, ?, ?, NOW())`,
        [label, agreementCode, fiscalYear, creator, notes]
      );
      const snapshotId = result.insertId;
      if (pots.length) {
        const insertValues = pots.map(pot => {
          const metaValue =
            pot.metadata === null || typeof pot.metadata === 'undefined'
              ? null
              : typeof pot.metadata === 'string'
                ? pot.metadata
                : JSON.stringify(pot.metadata);
          return [
            snapshotId,
            pot.id,
            pot.parent_id,
            pot.name,
            pot.code,
            pot.gl_project_code_external || null,
            pot.gl_project_code_internal || null,
          pot.agreement_id || null,
          pot.funding_source || null,
          pot.is_restricted ? 1 : 0,
          pot.pot_type,
          pot.is_admin_cap,
          pot.fiscal_year_tag || null,
          pot.approved_amount,
          pot.adjusted_amount,
          pot.committed_amount,
            pot.actual_amount,
            pot.forecast_amount,
            pot.admin_share_amount,
            metaValue,
          ];
        });
        await conn.query(
          `INSERT INTO budget_snapshot_pot
           (snapshot_id, budget_pot_id, parent_pot_id, name, code, gl_project_code_external, gl_project_code_internal, agreement_id, funding_source, is_restricted, pot_type, is_admin_cap, fiscal_year_tag,
            approved_amount, adjusted_amount, committed_amount, actual_amount, forecast_amount, admin_share_amount, metadata)
           VALUES ?`,
          [insertValues]
        );
        const regionValues = [];
        pots.forEach(pot => {
          const codes = regionMap.get(String(pot.id)) || [];
          codes.forEach(code => {
            regionValues.push([snapshotId, pot.id, code]);
          });
        });
        if (regionValues.length) {
          await conn.query(
            `INSERT INTO budget_snapshot_pot_region (snapshot_id, budget_pot_id, region_code, created_at, updated_at)
             VALUES ?`,
            [regionValues.map(v => [...v, new Date(), new Date()])]
          );
        }
      }
      await conn.commit();
      res.status(201).json({ id: snapshotId, label, snapshotAt: new Date().toISOString(), notes, agreementCode, fiscalYear });
    } catch (err) {
      await conn.rollback();
      throw err;
    } finally {
      conn.release();
    }
  } catch (err) {
    console.error('[finance] failed to create budget snapshot', err);
    res.status(500).json({ error: 'failed_to_create_budget_snapshot' });
  }
});

app.get('/api/finance/budget-snapshots/:id', async (req, res) => {
  if (requireFinanceRole(req, res)) return;
  const snapshotId = Number(req.params.id);
  if (!Number.isFinite(snapshotId)) {
    return res.status(400).json({ error: 'invalid_snapshot_id' });
  }
  try {
    const [[snapshot]] = await pool.query(
      `SELECT id, label, snapshot_at, agreement_code, fiscal_year, created_by_user_id, notes, created_at
         FROM budget_snapshot
        WHERE id = ?
        LIMIT 1`,
      [snapshotId]
    );
    if (!snapshot) {
      return res.status(404).json({ error: 'snapshot_not_found' });
    }
    const [pots] = await pool.query(
      `SELECT * FROM budget_snapshot_pot WHERE snapshot_id = ? ORDER BY parent_pot_id IS NULL DESC, parent_pot_id, id`,
      [snapshotId]
    );
    const [regionsRows] = await pool.query(
      'SELECT budget_pot_id, region_code FROM budget_snapshot_pot_region WHERE snapshot_id = ?',
      [snapshotId]
    );
    const snapshotRegionMap = new Map();
    (regionsRows || []).forEach(r => {
      const key = String(r.budget_pot_id);
      const code = r.region_code ? String(r.region_code).trim().toUpperCase() : null;
      if (!code) return;
      const list = snapshotRegionMap.get(key) || [];
      list.push(code);
      snapshotRegionMap.set(key, list);
    });
    res.status(200).json({
      id: snapshot.id,
      label: snapshot.label,
      snapshotAt: snapshot.snapshot_at,
      agreementCode: snapshot.agreement_code,
      fiscalYear: snapshot.fiscal_year,
      createdByUserId: snapshot.created_by_user_id,
      notes: snapshot.notes,
      createdAt: snapshot.created_at,
      pots: pots.map(row => {
        let meta = row.metadata ? safeJsonParse(row.metadata, {}) : {};
        if (typeof meta === 'string') {
          meta = safeJsonParse(meta, {});
        }
        return {
          id: row.budget_pot_id,
          parentId: row.parent_pot_id,
          name: row.name,
          code: row.code,
          glProjectCodeExternal: row.gl_project_code_external || null,
          glProjectCodeInternal: row.gl_project_code_internal || null,
          agreementId: row.agreement_id || null,
          fundingSource: row.funding_source || null,
          isRestricted: !!row.is_restricted,
          potType: row.pot_type,
          isAdminCap: !!row.is_admin_cap,
          fiscalYearTag: row.fiscal_year_tag || null,
          approved: Number(row.approved_amount || 0),
          adjusted: Number(row.adjusted_amount || 0),
          committed: Number(row.committed_amount || 0),
          actual: Number(row.actual_amount || 0),
          forecast: Number(row.forecast_amount || 0),
          adminShare: Number(row.admin_share_amount || 0),
          metadata: meta,
          regions: snapshotRegionMap.get(String(row.budget_pot_id)) || [],
        };
      }),
    });
  } catch (err) {
    console.error('[finance] failed to fetch budget snapshot', err);
    res.status(500).json({ error: 'failed_to_fetch_budget_snapshot' });
  }
});

