app.post('/api/finance/budget-drafts/:id/publish', async (req, res) => {
  if (requireFinanceRole(req, res)) return;
  const draftId = Number(req.params.id);
  if (!Number.isFinite(draftId)) {
    return res.status(400).json({ error: 'invalid_draft_id' });
  }
  const body = req.body || {};

  const normalizeFiscalYear = fy => {
    if (typeof fy !== 'string') return null;
    const trimmed = fy.trim();
    const match = /^(\d{4})-(\d{4})$/.exec(trimmed);
    if (!match) return null;
    const start = Number(match[1]);
    const end = Number(match[2]);
    if (!Number.isFinite(start) || !Number.isFinite(end) || end !== start + 1) return null;
    return trimmed;
  };

  const replaceYear = (text, targetYear) => {
    if (typeof text !== 'string') return text;
    const yearPattern = /\b(19|20)\d{2}\b/;
    if (!yearPattern.test(text)) return text;
    return text.replace(yearPattern, String(targetYear));
  };

  try {
    const [[draft]] = await pool.query(
      'SELECT id, label, payload_json, created_at FROM budget_pot_draft WHERE id = ? LIMIT 1',
      [draftId]
    );
    if (!draft) {
      return res.status(404).json({ error: 'draft_not_found' });
    }
    const payload = safeJsonParse(draft.payload_json, null);
    if (!payload || !Array.isArray(payload.pots) || !payload.pots.length) {
      return res.status(400).json({ error: 'invalid_draft_payload' });
    }
    const draftFiscalYear = normalizeFiscalYear(body.fiscalYear || payload.fiscalYear);
    if (!draftFiscalYear) {
      return res.status(400).json({ error: 'missing_fiscal_year' });
    }
    const targetYear = Number(draftFiscalYear.slice(0, 4));
    const autoIncrementYear = Boolean(body.autoIncrementYear);

    const conn = await pool.getConnection();
    try {
      await conn.beginTransaction();

      // Snapshot current live pots before applying the draft
      const [currentPots] = await conn.query('SELECT * FROM budget_pot');
      const currentRegions = await fetchPotRegions(currentPots.map(p => p.id), conn);
      const [snapshotResult] = await conn.query(
        `INSERT INTO budget_snapshot (label, snapshot_at, agreement_code, fiscal_year, created_by_user_id, notes, created_at)
         VALUES (?, NOW(), ?, ?, ?, ?, NOW())`,
        [`Pre-publish of ${draft.label}`, null, null, null, 'Draft publish rollback point']
      );
      const snapshotId = snapshotResult.insertId;
      if (currentPots.length) {
        const values = currentPots.map(pot => [
          snapshotId,
          pot.id,
          pot.parent_id,
          pot.name,
          pot.code,
          pot.gl_project_code_external || null,
          pot.gl_project_code_internal || null,
          pot.agreement_id || null,
          pot.funding_source || null,
          pot.is_restricted ? 1 : 0,
          pot.pot_type,
          pot.is_admin_cap,
          pot.fiscal_year_tag || null,
          pot.approved_amount,
          pot.adjusted_amount,
          pot.committed_amount,
          pot.actual_amount,
          pot.forecast_amount,
          pot.admin_share_amount,
          pot.metadata ? JSON.stringify(pot.metadata) : null,
        ]);
        await conn.query(
          `INSERT INTO budget_snapshot_pot
           (snapshot_id, budget_pot_id, parent_pot_id, name, code, gl_project_code_external, gl_project_code_internal, agreement_id, funding_source, is_restricted, pot_type, is_admin_cap, fiscal_year_tag,
            approved_amount, adjusted_amount, committed_amount, actual_amount, forecast_amount, admin_share_amount, metadata)
           VALUES ?`,
          [values]
        );
        const regionValues = [];
        currentPots.forEach(pot => {
          const codes = currentRegions.get(String(pot.id)) || [];
          codes.forEach(code => regionValues.push([snapshotId, pot.id, code, new Date(), new Date()]));
        });
        if (regionValues.length) {
          await conn.query(
            `INSERT INTO budget_snapshot_pot_region (snapshot_id, budget_pot_id, region_code, created_at, updated_at) VALUES ?`,
            [regionValues]
          );
        }
      }

      // Apply draft pots (upsert by id/code)
      const potsById = new Set();
      const draftPots = payload.pots;
      const preparedRegions = [];
      const allowedRegions = await fetchValidRegionCodeSet(conn);
      // Simple parent-first ordering: insert roots first, then children until all done.
      const remaining = [...draftPots];
      const prepared = [];
      const canInsert = pot => !pot.parentId || potsById.has(Number(pot.parentId));
      let guard = 0;
      while (remaining.length && guard < 10000) {
        const next = remaining.shift();
        const parentOk = canInsert(next);
        if (!parentOk) {
          remaining.push(next);
          guard += 1;
          continue;
        }
        const idNum = Number(next.id);
        const parentIdNum = next.parentId ? Number(next.parentId) : null;
        const approved = Number(next.approved) || 0;
        const adjusted = Number(next.adjusted ?? next.approved) || 0;
        const committed = Number(next.committed) || 0;
        const actual = Number(next.actual) || 0;
        const forecast = Number(next.forecast ?? adjusted ?? approved) || 0;
        const adminShare = Number(next.adminShare) || 0;
        const potFiscalYear = normalizeFiscalYear(next.fiscalYear) || draftFiscalYear;
        let name = next.name || '';
        let code = next.code || '';
        if (autoIncrementYear && targetYear) {
          name = replaceYear(name, targetYear);
          code = replaceYear(code, targetYear);
        }
        const fundingSourceRaw = next.fundingSource || next.funding_source || null;
        const fundingSource = fundingSourceRaw ? normalizeFundingSource(fundingSourceRaw) : null;
        if (fundingSourceRaw && !fundingSource) {
          throw new Error('invalid_funding_source');
        }
        const restrictedRaw =
          next.isRestricted !== undefined ? next.isRestricted : next.is_restricted;
        const restricted = restrictedRaw !== undefined ? normalizeBooleanLike(restrictedRaw) : null;
        if (restrictedRaw !== undefined && restricted === null) {
          throw new Error('invalid_is_restricted');
        }
        const agreementId =
          typeof next.agreementId === 'string'
            ? next.agreementId.trim() || null
            : next.agreement_id || null;
        const fiscalYearTagRaw = next.fiscalYearTag || next.fiscal_year_tag || null;
        const fiscalYearTag = fiscalYearTagRaw ? normalizeFiscalYearTag(fiscalYearTagRaw) : null;
        if (fiscalYearTagRaw && !fiscalYearTag) {
          throw new Error('invalid_fiscal_year_tag');
        }
        const glExternalRaw = next.glProjectCodeExternal || next.gl_project_code_external || null;
        const glInternalRaw = next.glProjectCodeInternal || next.gl_project_code_internal || null;
        const glExternal = glExternalRaw ? normalizeGlCode(glExternalRaw) : null;
        const glInternal = glInternalRaw ? normalizeGlCode(glInternalRaw) : null;
        if (glExternal && glExternal.length > 64) {
          throw new Error('invalid_gl_project_code_external');
        }
        if (glInternal && glInternal.length > 64) {
          throw new Error('invalid_gl_project_code_internal');
        }
        const regions = normalizeRegionCodes(next.regions || next.regionCodes || next.region_codes);
        const invalidRegions = regions.filter(code => !allowedRegions.has(code));
        if (invalidRegions.length) {
          const err = new Error('invalid_regions');
          err.code = 'invalid_regions';
          err.invalidRegions = invalidRegions;
          throw err;
        }
        const meta = {
          ...(typeof next.metadata === 'object' && next.metadata !== null ? next.metadata : {}),
          ...(next.nodeType ? { nodeType: next.nodeType } : {}),
          ...(next.description ? { description: next.description } : {}),
          ...(next.policyNotes ? { policyNotes: next.policyNotes } : {}),
          ...(next.adminTargetPct !== undefined ? { adminTargetPct: next.adminTargetPct } : {}),
        };
        prepared.push([
          Number.isFinite(idNum) ? idNum : null,
          Number.isFinite(parentIdNum) ? parentIdNum : null,
          next.agreementCode || null,
          agreementId,
          potFiscalYear,
          fiscalYearTag || potFiscalYear,
          glExternal,
          glInternal,
          name,
          code,
          next.nodeType || 'budget',
          fundingSource,
          restricted ? 1 : 0,
          next.owner || null,
          next.isAdminCap ? 1 : 0,
          next.status === 'archived' ? 0 : 1,
          approved,
          adjusted,
          committed,
          actual,
          forecast,
          adminShare,
          JSON.stringify(meta),
        ]);
        preparedRegions.push(regions);
        if (Number.isFinite(idNum)) {
          potsById.add(idNum);
        }
        guard += 1;
      }
      if (remaining.length) {
        throw new Error('failed_to_resolve_parent_order');
      }

      const potColumns = [
        'id',
        'parent_id',
        'agreement_code',
        'agreement_id',
        'fiscal_year',
        'fiscal_year_tag',
        'gl_project_code_external',
        'gl_project_code_internal',
        'name',
        'code',
        'pot_type',
        'funding_source',
        'is_restricted',
        'owner',
        'is_admin_cap',
        'is_active',
        'approved_amount',
        'adjusted_amount',
        'committed_amount',
        'actual_amount',
        'forecast_amount',
        'admin_share_amount',
        'metadata',
        'created_at',
        'updated_at',
      ];
      const potPlaceholders = potColumns.map(() => '?').join(', ');

      for (let i = 0; i < prepared.length; i += 1) {
        const values = prepared[i];
        const rowValues = [...values, new Date(), new Date()];
        const [result] = await conn.query(
          `INSERT INTO budget_pot
             (${potColumns.join(', ')})
           VALUES (${potPlaceholders})
           ON DUPLICATE KEY UPDATE
             parent_id = VALUES(parent_id),
             agreement_code = VALUES(agreement_code),
             agreement_id = VALUES(agreement_id),
             fiscal_year = VALUES(fiscal_year),
             fiscal_year_tag = VALUES(fiscal_year_tag),
             gl_project_code_external = VALUES(gl_project_code_external),
             gl_project_code_internal = VALUES(gl_project_code_internal),
             name = VALUES(name),
             code = VALUES(code),
             pot_type = VALUES(pot_type),
             funding_source = VALUES(funding_source),
             is_restricted = VALUES(is_restricted),
             owner = VALUES(owner),
             is_admin_cap = VALUES(is_admin_cap),
             is_active = VALUES(is_active),
             approved_amount = VALUES(approved_amount),
             adjusted_amount = VALUES(adjusted_amount),
             committed_amount = VALUES(committed_amount),
             actual_amount = VALUES(actual_amount),
             forecast_amount = VALUES(forecast_amount),
             admin_share_amount = VALUES(admin_share_amount),
             metadata = VALUES(metadata),
             updated_at = NOW()`,
          rowValues
        );
        const explicitId = Number(values[0]);
        const effectiveId = Number.isFinite(explicitId) ? explicitId : Number(result.insertId);
        if (Number.isFinite(effectiveId)) {
          potsById.add(effectiveId);
          const regions = preparedRegions[i] || [];
          await replacePotRegions(effectiveId, regions, conn);
        }
      }

      // Archive pots not present in the draft to avoid breaking history
      if (potsById.size) {
        await conn.query(
          `UPDATE budget_pot SET is_active = 0 WHERE id NOT IN (${Array.from(potsById).map(() => '?').join(',')})`,
          Array.from(potsById)
        );
      }

      await conn.commit();
      res.status(200).json({ success: true, snapshotId });
    } catch (err) {
      await conn.rollback();
      if (err && err.code === 'invalid_regions') {
        return res.status(400).json({ error: 'invalid_regions', invalidRegions: err.invalidRegions || [] });
      }
      console.error('[finance] failed to publish draft', err);
      return res.status(500).json({ error: 'failed_to_publish_draft' });
    } finally {
      conn.release();
    }
  } catch (err) {
    console.error('[finance] publish draft error', err);
    res.status(500).json({ error: 'failed_to_publish_draft' });
  }
});

// --- Finance: Payments ---

app.get('/api/finance/payment-intervention-type-map', async (req, res) => {
  if (requirePaymentsRole(req, res)) return;
  try {
    const mapping = await readPaymentInterventionMapping(pool);
    const recurrencePolicyByType = await readPaymentRecurrencePolicyByType(pool);
    const { options: payeeTypes } = await readPaymentPayeeTypeOptionsSnapshot(pool);
    const recurrencePolicies = Array.from(recurrencePolicyByType.entries())
      .map(([code, mode]) => ({ code, mode }))
      .sort((a, b) => String(a.code).localeCompare(String(b.code)));
    if (!mapping) {
      return res.status(200).json({ enabled: false, recurrencePolicies, payeeTypes });
    }
    return res.status(200).json({
      enabled: true,
      recurrencePolicies,
      payeeTypes,
      ...serializePaymentInterventionMapping(mapping),
    });
  } catch (err) {
    console.error('[payments] failed to fetch intervention payment mapping', err);
    return res.status(500).json({ error: 'payment_intervention_map_fetch_failed' });
  }
});

app.get('/api/finance/payment-packets', async (req, res) => {
  if (requirePaymentsRole(req, res)) return;
  try {
    const {
      status,
      statuses,
      caseId,
      clientId,
      interventionId,
      reportingUnit,
      limit = 200,
    } = req.query || {};

    const where = [];
    const params = [];
    const statusList = [];
    const addStatus = value => {
      const normalized = normalizePaymentStatus(value);
      if (normalized) statusList.push(normalized);
    };
    if (typeof statuses === 'string') {
      statuses
        .split(',')
        .map(item => item.trim())
        .filter(Boolean)
        .forEach(addStatus);
    }
    if (typeof status === 'string') {
      addStatus(status);
    }
    const uniqueStatuses = Array.from(new Set(statusList));
    if (uniqueStatuses.length === 1) {
      where.push('pp.status = ?');
      params.push(uniqueStatuses[0]);
    } else if (uniqueStatuses.length > 1) {
      where.push(`pp.status IN (${uniqueStatuses.map(() => '?').join(',')})`);
      params.push(...uniqueStatuses);
    }
    const caseIdValue = normalisePositiveInteger(caseId);
    if (caseIdValue) {
      where.push('pp.case_id = ?');
      params.push(caseIdValue);
    }
    const clientIdValue = normalisePositiveInteger(clientId);
    if (clientIdValue) {
      where.push('pp.client_id = ?');
      params.push(clientIdValue);
    }
    const interventionIdValue = normalisePositiveInteger(interventionId);
    if (interventionIdValue) {
      where.push('pp.intervention_id = ?');
      params.push(interventionIdValue);
    }
    if (typeof reportingUnit === 'string' && reportingUnit.trim()) {
      where.push('pp.reporting_unit = ?');
      params.push(reportingUnit.trim());
    }

    const whereClause = where.length ? `WHERE ${where.join(' AND ')}` : '';
    const cappedLimit = Math.min(Number(limit) || 200, 500);
    const [rows] = await pool.query(
      `SELECT pp.*,
              c.case_number,
c.assigned_staff_profile_id AS assigned_to_user_id,
              c.portfolio_region_id,
              case_owner_sp.region_id AS owner_region_id,
              a.id AS application_id,
              cl.first_name AS client_first_name,
              cl.last_name AS client_last_name,
              ci.metadata_json AS intervention_metadata_json,
              ci.notes AS intervention_notes,
              ci.intervention_code AS intervention_code,
              req.name AS requester_name,
              req.email AS requester_email,
              prog.name AS program_approver_name,
              prog.email AS program_approver_email,
              fin.name AS finance_approver_name,
              fin.email AS finance_approver_email,
              COALESCE(s.user_id, applicant_client_sub.id, applicant_client_email.id) AS applicant_user_id
         FROM payment_packet pp
         LEFT JOIN iset_case c ON c.id = pp.case_id
         LEFT JOIN staff_profiles case_owner_sp ON case_owner_sp.id = c.assigned_staff_profile_id
         LEFT JOIN client cl ON cl.id = pp.client_id
         ${buildCasePrimaryApplicationJoinSql('c', 'a')}
         LEFT JOIN iset_application_submission s ON s.id = a.submission_id
         LEFT JOIN user applicant_client_sub ON applicant_client_sub.cognito_sub = cl.applicant_cognito_sub
         LEFT JOIN user applicant_client_email ON applicant_client_email.email = cl.applicant_account_email
         LEFT JOIN iset_case_intervention ci ON ci.id = pp.intervention_id
         LEFT JOIN user req ON req.id = pp.requester_user_id
         LEFT JOIN user prog ON prog.id = pp.program_approved_by_user_id
         LEFT JOIN user fin ON fin.id = pp.finance_approved_by_user_id
        ${whereClause}
        ORDER BY
          (pp.due_by IS NULL) ASC,
          pp.due_by ASC,
          pp.updated_at DESC,
          pp.id DESC
        LIMIT ?`,
      [...params, cappedLimit]
    );
    const scopedRows = [];
    for (const row of rows || []) {
      const accessError = await validatePaymentPacketAccess(req, row);
      if (!accessError) scopedRows.push(row);
    }
    const packets = await hydratePaymentPackets(scopedRows);
    await applyPostPayEvidenceHolds({ packets, connection: pool });
    res.status(200).json(packets);
  } catch (err) {
    console.error('[payments] failed to list payment packets', err);
    res.status(500).json({ error: 'failed_to_list_payment_packets' });
  }
});

app.get('/api/finance/payment-packets/:id', async (req, res) => {
  if (requirePaymentsRole(req, res)) return;
  const packetId = parsePaymentPacketId(req.params.id);
  if (!Number.isFinite(packetId)) {
    return res.status(400).json({ error: 'invalid_payment_packet_id' });
  }
  try {
    const packet = await fetchPaymentPacketById(packetId);
    if (!packet) {
      return res.status(404).json({ error: 'payment_packet_not_found' });
    }
    const accessError = await validatePaymentPacketAccess(req, packetId);
    if (accessError) {
      return res.status(accessError.status).json(accessError.body);
    }
    await applyPostPayEvidenceHolds({ packets: [packet], connection: pool });
    res.status(200).json(packet);
  } catch (err) {
    console.error('[payments] failed to fetch payment packet', err);
    res.status(500).json({ error: 'failed_to_fetch_payment_packet' });
  }
});

