app.post('/api/finance/payment-packets', async (req, res) => {
  if (requirePaymentsRole(req, res)) return;
  const body = req.body || {};
  const rawPacketStatus = normaliseString(body.status);
  const status = rawPacketStatus ? normalizePaymentStatus(rawPacketStatus) : 'draft';
  if (rawPacketStatus && !status) {
    return res.status(400).json({ error: 'invalid_status' });
  }
  if (status !== 'draft') {
    return res.status(400).json({ error: 'payment_packet_create_requires_draft' });
  }
  const linesPayload = Array.isArray(body.lines)
    ? body.lines
    : Array.isArray(body.lineItems)
      ? body.lineItems
      : [];

  const caseId = normalisePositiveInteger(body.caseId || body.case_id) || null;
  const clientId = normalisePositiveInteger(body.clientId || body.client_id) || null;
  const applicationId = normalisePositiveInteger(body.applicationId || body.application_id) || null;
  const interventionId = normalisePositiveInteger(body.interventionId || body.intervention_id) || null;
  const reportingUnit =
    typeof body.reportingUnit === 'string'
      ? body.reportingUnit.trim() || null
      : body.reporting_unit || null;
  const dueBy = body.dueBy || body.due_by || null;
  const notes =
    typeof body.notes === 'string'
      ? body.notes.trim()
      : typeof body.notes_internal === 'string'
        ? body.notes_internal.trim()
        : null;
  const riskFlagsInput = Array.isArray(body.riskFlags)
    ? body.riskFlags
    : Array.isArray(body.risk_flags)
      ? body.risk_flags
      : [];
  const riskFlags = riskFlagsInput.filter(Boolean);
  const metadata = safeJsonParse(body.metadata, {}) || {};
  const requesterRoleRaw = inferUserRole(req);
  const requesterRole = canonicaliseAccessRole(requesterRoleRaw) || requesterRoleRaw || null;
  const requesterName =
    req.user?.name ||
    req.user?.email ||
    req.auth?.name ||
    req.auth?.email ||
    null;
  if (requesterName) {
    metadata.requesterName = requesterName;
  }
  if (requesterRole) {
    metadata.requesterRole = requesterRole;
  }
  const requesterUserId = await resolveFinanceRouteActorUserId(req, pool);
  if (!requesterUserId) {
    return res.status(400).json({ error: 'requester_user_required' });
  }
  const programApprovedByUserId = null;
  const financeApprovedByUserId = null;

  const now = new Date();
  const submittedStages = new Set(['submitted', 'confirmed']);
  const sentStages = new Set(['submitted', 'confirmed']);
  const confirmedStages = new Set(['confirmed']);

  const submittedAt = submittedStages.has(status) ? now : null;
  const programApprovedAt = null;
  const financeApprovedAt = null;
  const sentAt = sentStages.has(status) ? now : null;
  const confirmedAt = confirmedStages.has(status) ? now : null;

  const interventionIdsForPacket = new Set();
  if (interventionId) {
    interventionIdsForPacket.add(interventionId);
  }
  if (linesPayload.length) {
    linesPayload.forEach(line => {
      const lineInterventionId = normalisePositiveInteger(line?.interventionId || line?.intervention_id);
      if (lineInterventionId) {
        interventionIdsForPacket.add(lineInterventionId);
      }
    });
  }
  const targetAccessError = await validatePaymentTargetAccess(req, {
    caseId,
    applicationId,
    clientId,
    interventionIds: Array.from(interventionIdsForPacket),
    requireScopedContext: true,
  });
  if (targetAccessError) {
    return res.status(targetAccessError.status).json(targetAccessError.body);
  }

  const conn = await pool.getConnection();
  try {
    await conn.beginTransaction();
    if (interventionIdsForPacket.size) {
      const ids = Array.from(interventionIdsForPacket);
      const packetInterventionMap = await fetchInterventionsById({ ids, connection: conn });
      const historicalOnlyInterventionIds = ids.filter(id =>
        isManualBackloadInterventionRow(packetInterventionMap.get(Number(id)))
      );
      if (historicalOnlyInterventionIds.length) {
        await conn.rollback();
        return res.status(409).json({
          error: 'intervention_finance_history_only',
          message: 'Historical backloaded interventions cannot create payment packets. Create a new live intervention for any unpaid remainder.',
          interventionIds: historicalOnlyInterventionIds.map(id => Number(id)),
        });
      }
    }
    const [result] = await conn.query(
      `INSERT INTO payment_packet
        (case_id, client_id, intervention_id, reporting_unit, status, requester_user_id, program_approved_by_user_id, finance_approved_by_user_id,
         submitted_at, program_approved_at, finance_approved_at, sent_at, confirmed_at, due_by, notes_internal, risk_flags, metadata, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), NOW())`,
      [
        caseId,
        clientId,
        interventionId,
        reportingUnit,
        status,
        requesterUserId,
        programApprovedByUserId || null,
        financeApprovedByUserId || null,
        submittedAt,
        programApprovedAt,
        financeApprovedAt,
        sentAt,
        confirmedAt,
        dueBy,
        notes,
        JSON.stringify(riskFlags),
        JSON.stringify(metadata),
      ]
    );
    const packetId = result.insertId;

    const interventionIdsForEvidence = new Set();
    if (interventionId) {
      interventionIdsForEvidence.add(interventionId);
    }

    if (linesPayload.length > 0) {
      const lineErrors = [];
      const lineInputs = linesPayload.map((line, index) => {
        const paymentType = typeof line.paymentType === 'string'
          ? line.paymentType.trim()
          : typeof line.payment_type === 'string'
            ? line.payment_type.trim()
            : '';
        if (!paymentType) {
          lineErrors.push({ index, field: 'paymentType', error: 'required', message: 'Payment type is required.' });
        }
        const payeeType = typeof line.payeeType === 'string'
          ? line.payeeType.trim()
          : typeof line.payee_type === 'string'
            ? line.payee_type.trim()
            : '';
        if (!payeeType) {
          lineErrors.push({ index, field: 'payeeType', error: 'required', message: 'Payee type is required.' });
        }
        const payeeName = typeof line.payeeName === 'string'
          ? line.payeeName.trim()
          : typeof line.payee_name === 'string'
            ? line.payee_name.trim()
            : '';
        if (!payeeName) {
          lineErrors.push({ index, field: 'payeeName', error: 'required', message: 'Payee name is required.' });
        }
        const amount = Number(line.amount);
        if (!Number.isFinite(amount) || amount <= 0) {
          lineErrors.push({ index, field: 'amount', error: 'invalid', message: 'Amount must be greater than 0.' });
        }
        const potId = normalisePositiveInteger(
          line.potId || line.budgetPotId || line.budget_pot_id
        );
        if (!potId) {
          lineErrors.push({ index, field: 'budgetPotId', error: 'required', message: 'Budget pot is required.' });
        }
        const rawLineStatus = normaliseString(line.status);
        const lineStatus = rawLineStatus ? normalizePaymentLineStatus(rawLineStatus) : 'needs_evidence';
        if (rawLineStatus && !lineStatus) {
          lineErrors.push({ index, field: 'status', error: 'invalid', message: 'Payment line status is invalid.' });
        } else if (rawLineStatus && lineStatus !== 'needs_evidence') {
          lineErrors.push({
            index,
            field: 'status',
            error: 'create_requires_draft_line',
            message: 'Payment lines must be created in draft evidence-gathering status.',
          });
        }
        return {
          paymentType,
          payeeType,
          payeeName,
          amount,
          potId,
          status: lineStatus,
          payeeProfileId: normalisePositiveInteger(line.payeeProfileId || line.payee_profile_id),
          payeeReference: line.payeeReference || line.payee_reference || null,
          currency: line.currency || 'CAD',
          servicePeriodStart: line.servicePeriodStart || line.service_period_start || null,
          servicePeriodEnd: line.servicePeriodEnd || line.service_period_end || null,
          invoiceReferenceNumber: line.invoiceReferenceNumber || line.invoice_reference_number || null,
          requestedPaymentDate: line.requestedPaymentDate || line.requested_payment_date || null,
          fundingStream: line.fundingStream || line.funding_stream || null,
          holdReason: line.holdReason || line.hold_reason || null,
          interventionId: normalisePositiveInteger(line.interventionId || line.intervention_id) || interventionId || null,
          metadata: safeJsonParse(line.metadata, {}) || {},
        };
      });

      if (lineErrors.length) {
        await conn.rollback();
        return res.status(400).json({ error: 'invalid_line_items', message: 'One or more payment line items are invalid.', details: lineErrors });
      }

      const potIds = Array.from(new Set(lineInputs.map(line => line.potId)));
      const potMap = new Map();
      if (potIds.length) {
        const [potRows] = await conn.query(
          `SELECT id, funding_source FROM budget_pot WHERE id IN (${potIds.map(() => '?').join(',')})`,
          potIds
        );
        potRows.forEach(row => potMap.set(Number(row.id), row));
      }
      const missingPotIds = potIds.filter(id => !potMap.has(id));
      if (missingPotIds.length) {
        await conn.rollback();
        return res.status(400).json({ error: 'invalid_budget_pot_ids', invalidPotIds: missingPotIds });
      }

      const policyRules = await readPaymentPolicyRules(conn);
      const recurrencePolicyByType = await readPaymentRecurrencePolicyByType(conn);
      const paymentTypeMap = await readPaymentInterventionMapping(conn);
      const interventionIds = Array.from(
        new Set(lineInputs.map(line => line.interventionId).filter(Boolean))
      );
      const interventionMap = await fetchInterventionsById({ ids: interventionIds, connection: conn });
      const blockedInterventionIds = interventionIds.filter(id => {
        const intervention = interventionMap.get(Number(id));
        return intervention && isPaymentBlockedInterventionStatus(intervention.status);
      });
      if (blockedInterventionIds.length) {
        await conn.rollback();
        return res.status(400).json({
          error: 'intervention_status_blocked',
          message: 'Selected intervention is not eligible for payment initiation.',
          blockedInterventionIds,
        });
      }
      lineInputs.forEach((line, index) => {
        const intervention = line.interventionId ? interventionMap.get(Number(line.interventionId)) : null;
        const validationErrors = validatePaymentLinePolicy({
          line: {
            payment_type: line.paymentType,
            payee_type: line.payeeType,
            amount: line.amount,
            service_period_start: line.servicePeriodStart,
            service_period_end: line.servicePeriodEnd,
            payee_name: line.payeeName,
            metadata: line.metadata,
          },
          intervention,
          evidenceTypeKeys: new Set(),
          policyRules,
          interventionPaymentTypeMap: paymentTypeMap,
          recurrencePolicyByType,
          validationStage: 'draft',
        });
        if (validationErrors.length) {
          validationErrors.forEach(err => {
            lineErrors.push({ index, field: err.field, error: err.code, message: err.message });
          });
        }
      });
      if (lineErrors.length) {
        await conn.rollback();
        return res.status(400).json({ error: 'invalid_line_items', message: 'One or more payment line items are invalid.', details: lineErrors });
      }

      const fundingErrors = await validateFundingAuthorizationForNewLines({
        lineInputs,
        packetRow: { case_id: caseId, intervention_id: interventionId },
        interventionMap,
        connection: conn,
      });
      if (fundingErrors.length) {
        await conn.rollback();
        return res.status(400).json({ error: 'invalid_line_items', message: 'One or more payment line items exceed available funding.', details: fundingErrors });
      }

      const lineValues = lineInputs.map(line => {
        const pot = potMap.get(line.potId);
        const fallbackStream = pot?.funding_source ? normalizeFundingSource(pot.funding_source) : null;
        const fundingStream = line.fundingStream ? normalizeFundingSource(line.fundingStream) : fallbackStream;
        return [
          packetId,
          line.interventionId,
          line.paymentType,
          line.payeeType,
          line.payeeName,
          line.payeeProfileId || null,
          line.payeeReference,
          line.amount,
          line.currency,
          line.servicePeriodStart,
          line.servicePeriodEnd,
          line.invoiceReferenceNumber,
          line.requestedPaymentDate,
          line.potId,
          fundingStream,
          line.status,
          line.holdReason,
          JSON.stringify(line.metadata),
        ];
      });

      const [insertResult] = await conn.query(
        `INSERT INTO payment_packet_line
          (payment_packet_id, intervention_id, payment_type, payee_type, payee_name, payee_profile_id, payee_reference,
           amount, currency, service_period_start, service_period_end, invoice_reference_number, requested_payment_date,
           budget_pot_id, funding_stream, status, hold_reason, metadata)
         VALUES ?`,
        [lineValues]
      );

      const insertIdBase = Number(insertResult?.insertId);
      const insertedIds = lineInputs.map((_, index) =>
        Number.isFinite(insertIdBase) ? insertIdBase + index : null
      );
      const candidateLines = lineInputs.map((line, index) => ({
        id: insertedIds[index],
        payment_packet_id: packetId,
        intervention_id: line.interventionId || interventionId || null,
        payment_type: line.paymentType,
        payee_name: line.payeeName,
        payee_reference: line.payeeReference || null,
        amount: line.amount,
        service_period_start: line.servicePeriodStart,
        service_period_end: line.servicePeriodEnd,
        invoice_reference_number: line.invoiceReferenceNumber,
        requested_payment_date: line.requestedPaymentDate,
      }));
      const duplicateScan = await collectDuplicatePaymentMatches({
        lines: candidateLines,
        packetRow: {
          id: packetId,
          case_id: caseId,
          client_id: clientId,
          intervention_id: interventionId,
        },
        connection: conn,
      });
      if (duplicateScan.warnings.length) {
        await appendPacketDuplicateWarnings({
          packetId,
          warnings: duplicateScan.warnings,
          connection: conn,
        });
      }

      lineInputs.forEach(line => {
        if (line.interventionId) {
          interventionIdsForEvidence.add(line.interventionId);
        }
      });
    }

    await attachSupportingDocumentsToPaymentPacket({
      packetId,
      caseId,
      clientId,
      applicationId,
      interventionIds: Array.from(interventionIdsForEvidence),
      connection: conn,
    });

    await conn.query(
      `INSERT INTO payment_status_event
        (payment_packet_id, payment_packet_line_id, from_status, to_status, actor_user_id, notes, metadata, created_at)
       VALUES (?, NULL, NULL, ?, ?, NULL, NULL, NOW())`,
      [packetId, status, requesterUserId]
    );

    await conn.commit();
    const packet = await fetchPaymentPacketById(packetId);
    res.status(201).json(packet);
  } catch (err) {
    await conn.rollback();
    console.error('[payments] failed to create payment packet', err);
    res.status(500).json({ error: 'failed_to_create_payment_packet' });
  } finally {
    conn.release();
  }
});

app.put('/api/finance/payment-packets/:id', async (req, res) => {
  if (requirePaymentsRole(req, res)) return;
  const packetId = parsePaymentPacketId(req.params.id);
  if (!Number.isFinite(packetId)) {
    return res.status(400).json({ error: 'invalid_payment_packet_id' });
  }
  const body = req.body || {};
  if (body.status) {
    return res.status(400).json({ error: 'status_updates_require_status_endpoint' });
  }
  try {
    const existingAccessError = await validatePaymentPacketAccess(req, packetId);
    if (existingAccessError) {
      return res.status(existingAccessError.status).json(existingAccessError.body);
    }
    const fields = [];
    const params = [];
    const nextValues = {};
    const assign = (column, value) => {
      fields.push(`${column} = ?`);
      params.push(value);
      nextValues[column] = value;
    };
    if (body.caseId !== undefined || body.case_id !== undefined) {
      assign('case_id', normalisePositiveInteger(body.caseId || body.case_id) || null);
    }
    if (body.clientId !== undefined || body.client_id !== undefined) {
      assign('client_id', normalisePositiveInteger(body.clientId || body.client_id) || null);
    }
    if (body.interventionId !== undefined || body.intervention_id !== undefined) {
      assign('intervention_id', normalisePositiveInteger(body.interventionId || body.intervention_id) || null);
    }
    if (body.reportingUnit !== undefined || body.reporting_unit !== undefined) {
      const value =
        typeof body.reportingUnit === 'string'
          ? body.reportingUnit.trim() || null
          : body.reporting_unit || null;
      assign('reporting_unit', value);
    }
    if (body.dueBy !== undefined || body.due_by !== undefined) {
      assign('due_by', body.dueBy || body.due_by || null);
    }
    if (body.notes !== undefined || body.notes_internal !== undefined) {
      const value =
        typeof body.notes === 'string'
          ? body.notes.trim()
          : typeof body.notes_internal === 'string'
            ? body.notes_internal.trim()
            : null;
      assign('notes_internal', value);
    }
    if (body.riskFlags !== undefined || body.risk_flags !== undefined) {
      const riskFlagsInput = Array.isArray(body.riskFlags)
        ? body.riskFlags
        : Array.isArray(body.risk_flags)
          ? body.risk_flags
          : [];
      const flags = riskFlagsInput.filter(Boolean);
      assign('risk_flags', JSON.stringify(flags));
    }
    if (body.metadata !== undefined) {
      const meta = safeJsonParse(body.metadata, {}) || {};
      assign('metadata', JSON.stringify(meta));
    }
    if (!fields.length) {
      return res.status(400).json({ error: 'no_fields_to_update' });
    }
    if (
      Object.prototype.hasOwnProperty.call(nextValues, 'case_id') ||
      Object.prototype.hasOwnProperty.call(nextValues, 'client_id') ||
      Object.prototype.hasOwnProperty.call(nextValues, 'intervention_id')
    ) {
      const targetAccessError = await validatePaymentTargetAccess(req, {
        caseId: nextValues.case_id,
        clientId: nextValues.client_id,
        interventionIds: nextValues.intervention_id ? [nextValues.intervention_id] : [],
        requireScopedContext: Boolean(nextValues.case_id || nextValues.client_id || nextValues.intervention_id),
      });
      if (targetAccessError) {
        return res.status(targetAccessError.status).json(targetAccessError.body);
      }
    }
    params.push(packetId);
    await pool.query(
      `UPDATE payment_packet SET ${fields.join(', ')}, updated_at = NOW() WHERE id = ?`,
      params
    );
    await clearPaymentPacketValidation({ packetId, connection: pool });
    const packet = await fetchPaymentPacketById(packetId);
    if (!packet) {
      return res.status(404).json({ error: 'payment_packet_not_found' });
    }
    res.status(200).json(packet);
  } catch (err) {
    console.error('[payments] failed to update payment packet', err);
    res.status(500).json({ error: 'failed_to_update_payment_packet' });
  }
});

app.delete('/api/finance/payment-packets/:id', async (req, res) => {
  if (requirePaymentsRole(req, res)) return;
  const packetId = parsePaymentPacketId(req.params.id);
  if (!Number.isFinite(packetId)) {
    return res.status(400).json({ error: 'invalid_payment_packet_id' });
  }
  const conn = await pool.getConnection();
  try {
    await conn.beginTransaction();
    const accessError = await validatePaymentPacketAccess(req, packetId, { connection: conn });
    if (accessError) {
      await conn.rollback();
      return res.status(accessError.status).json(accessError.body);
    }
    const result = await deletePaymentPacket({ packetId, connection: conn });
    if (result.missing) {
      await conn.rollback();
      return res.status(404).json({ error: 'payment_packet_not_found' });
    }
    if (result.notDraft) {
      await conn.rollback();
      return res.status(409).json({
        error: 'payment_packet_not_draft',
        status: result.status || null,
      });
    }
    await conn.commit();
    return res.json({
      ok: true,
      deleted: true,
      packetId,
      lineCount: result.lineCount || 0,
    });
  } catch (err) {
    try {
      await conn.rollback();
    } catch (_) {}
    console.error('[payments] failed to delete payment packet', err);
    return res.status(500).json({ error: 'failed_to_delete_payment_packet' });
  } finally {
    conn.release();
  }
});

app.post('/api/finance/payment-packets/:id/validate', async (req, res) => {
  if (requirePaymentsRole(req, res)) return;
  const packetId = parsePaymentPacketId(req.params.id);
  if (!Number.isFinite(packetId)) {
    return res.status(400).json({ error: 'invalid_payment_packet_id' });
  }

  const conn = await pool.getConnection();
  try {
    await conn.beginTransaction();
    const actorUserId = await resolveFinanceRouteActorUserId(req, conn);
    if (!actorUserId) {
      await conn.rollback();
      return res.status(400).json({ error: 'actor_user_required' });
    }
    const [[packetRow]] = await conn.query(
      'SELECT * FROM payment_packet WHERE id = ? LIMIT 1 FOR UPDATE',
      [packetId]
    );
    if (!packetRow) {
      await conn.rollback();
      return res.status(404).json({ error: 'payment_packet_not_found' });
    }
    const accessError = await validatePaymentPacketAccess(req, packetId, { connection: conn });
    if (accessError) {
      await conn.rollback();
      return res.status(accessError.status).json(accessError.body);
    }
    if (normalizePacketWorkflowStage(packetRow.status) !== 'draft') {
      await conn.rollback();
      return res.status(409).json({ error: 'packet_not_editable', status: packetRow.status || null });
    }

    const [lineRows] = await conn.query(
      `SELECT ppl.id, ppl.payment_packet_id, ppl.amount, ppl.status, ppl.payment_type, ppl.payee_name, ppl.payee_reference,
              ppl.service_period_start, ppl.service_period_end, ppl.invoice_reference_number, ppl.requested_payment_date,
              ppl.metadata, ppl.intervention_id, ppl.payee_type, ppl.paid_at, ppl.payment_reference,
              bp.name AS pot_name, bp.code AS pot_code
         FROM payment_packet_line ppl
         LEFT JOIN budget_pot bp ON bp.id = ppl.budget_pot_id
        WHERE ppl.payment_packet_id = ?`,
      [packetId]
    );

    const intacctConfig = await readIntacctIntegrationConfig(conn);
    const submissionMode = normalizeIntacctSubmissionMode(intacctConfig?.submissionMode);
    if (submissionMode === 'intacct_rest') {
      await resolveMissingIntacctVendorReferences({ lineRows, connection: conn });
    }
    const intacctValidationIssues =
      submissionMode === 'intacct_rest'
        ? validateIntacctRestRequirements({ packetRow, lineRows, config: intacctConfig })
        : [];

    const validation = await runPaymentPacketValidation({
      packetRow,
      lineRows,
      connection: conn,
    });
    const combinedDetails = [
      ...(validation.details || []),
      ...intacctValidationIssues,
    ];
    const combinedMissingEvidence = validation.missingEvidence || [];
    const combinedValidation = {
      ...validation,
      details: combinedDetails,
      passed: combinedDetails.length === 0 && combinedMissingEvidence.length === 0,
    };

    await setPaymentPacketValidation({
      packetId,
      status: combinedValidation.passed ? 'passed' : 'failed',
      details: combinedValidation.details,
      missingEvidence: combinedMissingEvidence,
      actorUserId,
      connection: conn,
    });
    await syncFinanceTransactionEvidenceFromPacket({ packetId, connection: conn });

    const nextPacketStatus = combinedValidation.passed ? 'ready_to_send' : 'draft';
    const nextLineStatus = PACKET_STATUS_TO_LINE_STATUS[nextPacketStatus] || null;
    const fromPacketStatus = normalizePaymentStatus(packetRow.status) || 'draft';

    if (fromPacketStatus !== nextPacketStatus) {
      await conn.query(
        'UPDATE payment_packet SET status = ?, updated_at = NOW() WHERE id = ?',
        [nextPacketStatus, packetId]
      );
      await conn.query(
        `INSERT INTO payment_status_event
          (payment_packet_id, payment_packet_line_id, from_status, to_status, actor_user_id, notes, metadata, created_at)
         VALUES (?, NULL, ?, ?, ?, ?, NULL, NOW())`,
        [
          packetId,
          packetRow.status || null,
          nextPacketStatus,
          actorUserId,
          combinedValidation.passed
            ? 'Packet marked ready after validation passed.'
            : 'Packet returned to draft after validation failed.',
        ]
      );
    }

    if (nextLineStatus) {
      const eventTimestamp = new Date();
      const lineEventValues = (lineRows || [])
        .filter(row => row.status !== nextLineStatus && !['paid', 'cancelled'].includes(row.status))
        .map(row => [
          packetId,
          row.id,
          row.status || null,
          nextLineStatus,
          actorUserId,
          null,
          null,
          eventTimestamp,
        ]);
      if (lineEventValues.length) {
        await conn.query(
          'UPDATE payment_packet_line SET status = ?, updated_at = NOW() WHERE payment_packet_id = ? AND status NOT IN ("paid","cancelled")',
          [nextLineStatus, packetId]
        );
        await conn.query(
          `INSERT INTO payment_status_event
            (payment_packet_id, payment_packet_line_id, from_status, to_status, actor_user_id, notes, metadata, created_at)
           VALUES ?`,
          [lineEventValues]
        );
      }
    }

    await conn.commit();
    const packet = await fetchPaymentPacketById(packetId);
    if (!packet) {
      return res.status(404).json({ error: 'payment_packet_not_found' });
    }
    return res.status(200).json(packet);
  } catch (err) {
    await conn.rollback();
    console.error('[payments] failed to validate payment packet', err);
    return res.status(500).json({ error: 'failed_to_validate_payment_packet' });
  } finally {
    conn.release();
  }
});

app.post('/api/finance/payment-packets/:id/status', async (req, res) => {
  if (requirePaymentsRole(req, res)) return;
  const packetId = parsePaymentPacketId(req.params.id);
  if (!Number.isFinite(packetId)) {
    return res.status(400).json({ error: 'invalid_payment_packet_id' });
  }
  const body = req.body || {};
  const nextStatus = normalizePaymentStatus(body.status);
  if (!nextStatus) {
    return res.status(400).json({ error: 'invalid_status' });
  }
  let actorUserId = null;
  const actorRoleRaw = inferUserRole(req);
  const actorRole = canonicaliseAccessRole(actorRoleRaw) || actorRoleRaw;
  const notes = typeof body.notes === 'string' ? body.notes.trim() : null;
  const overrideReason = normalizeOverrideReason(
    body.overrideReason || body.override_reason || body.overrideNote || body.override_note
  );
  const overrideRequested = body.override === true || !!overrideReason || !!body.overrideType || !!body.override_type;
  const overrideTypeRaw = body.overrideType || body.override_type || null;
  const overrideType = typeof overrideTypeRaw === 'string' ? overrideTypeRaw.trim() : null;

  const conn = await pool.getConnection();
  try {
    await conn.beginTransaction();
    actorUserId = await resolveFinanceRouteActorUserId(req, conn);
    if (!actorUserId) {
      await conn.rollback();
      return res.status(400).json({ error: 'actor_user_required' });
    }
    const [[packetRow]] = await conn.query(
      'SELECT * FROM payment_packet WHERE id = ? LIMIT 1 FOR UPDATE',
      [packetId]
    );
    if (!packetRow) {
      await conn.rollback();
      return res.status(404).json({ error: 'payment_packet_not_found' });
    }
    const accessError = await validatePaymentPacketAccess(req, packetId, { connection: conn });
    if (accessError) {
      await conn.rollback();
      return res.status(accessError.status).json(accessError.body);
    }
    const fromStatus = packetRow.status || null;
    const packetMeta = safeJsonParse(packetRow.metadata, {}) || {};
    const latestIntacctAttempt = resolveLatestIntacctAttempt(packetMeta);
    const latestIntacctOutcome = resolveIntacctAttemptStatus(latestIntacctAttempt);
    const canReopenForIntacct = latestIntacctOutcome === 'failed' || latestIntacctOutcome === 'partial';
    const fromStage = normalizePacketWorkflowStage(fromStatus);
    const nextStage = normalizePacketWorkflowStage(nextStatus);
    const allowReopen = nextStatus === 'draft' && fromStage !== 'draft' && canReopenForIntacct;
    const duplicateSubmitRequest = nextStatus === 'submitted' && fromStage === 'submitted';
    if (duplicateSubmitRequest && !allowReopen) {
      await conn.rollback();
      return res.status(409).json({
        error: 'payment_packet_already_submitted',
        status: fromStatus,
        message: 'This packet has already been submitted.',
      });
    }
    if (fromStage !== 'draft' && nextStage !== fromStage && !allowReopen) {
      await conn.rollback();
      return res.status(409).json({ error: 'payment_packet_locked', status: fromStatus });
    }
    if (fromStage === 'draft' && nextStage === 'draft' && fromStatus === nextStatus) {
      await conn.rollback();
      const packet = await fetchPaymentPacketById(packetId);
      return packet
        ? res.status(200).json(packet)
        : res.status(404).json({ error: 'payment_packet_not_found' });
    }
    const [lineRows] = await conn.query(
      `SELECT id, payment_packet_id, amount, status, payment_type, payee_name, payee_reference,
              service_period_start, service_period_end, invoice_reference_number, requested_payment_date,
              metadata, intervention_id, payee_type, paid_at, payment_reference, follow_up_status
         FROM payment_packet_line
        WHERE payment_packet_id = ?`,
      [packetId]
    );
    const activeLines = (lineRows || []).filter(row => row.status !== 'cancelled');
    const totalAmount = activeLines.reduce((sum, row) => sum + Number(row.amount || 0), 0);
    const maxLineAmount = activeLines.reduce((max, row) => {
      const value = Number(row.amount || 0);
      return Number.isFinite(value) ? Math.max(max, value) : max;
    }, 0);

    if (nextStatus === 'submitted') {
      if (latestIntacctOutcome === 'success') {
        await conn.rollback();
        return res.status(409).json({
          error: 'intacct_rest_already_accepted',
          message: 'This packet has already been accepted by Sage Intacct.',
        });
      }
      const policyRules = await readPaymentPolicyRules(conn);
      const recurrencePolicyByType = await readPaymentRecurrencePolicyByType(conn);
      const paymentTypeMap = await readPaymentInterventionMapping(conn);
      const interventionIds = activeLines.map(line => line.intervention_id).filter(Boolean);
      if (packetRow.intervention_id) {
        interventionIds.push(packetRow.intervention_id);
      }
      const interventionMap = await fetchInterventionsById({ ids: interventionIds, connection: conn });
      const [evidenceRows] = await conn.query(
        `SELECT payment_packet_line_id, evidence_type, received_at, document_id
           FROM payment_packet_document
          WHERE payment_packet_id = ?`,
        [packetId]
      );
      const evidenceMap = buildEvidenceTypeSetMap(evidenceRows);
      const policyErrors = [];
      activeLines.forEach(line => {
        const intervention = line.intervention_id
          ? interventionMap.get(Number(line.intervention_id))
          : packetRow.intervention_id
            ? interventionMap.get(Number(packetRow.intervention_id))
            : null;
        const lineEvidence = mergeEvidenceTypeSets(
          evidenceMap.baseline,
          evidenceMap.byLine.get(String(line.id))
        );
        const validationErrors = validatePaymentLinePolicy({
          line,
          intervention,
          evidenceTypeKeys: lineEvidence,
          policyRules,
          interventionPaymentTypeMap: paymentTypeMap,
          recurrencePolicyByType,
          validationStage: 'submission',
        });
        validationErrors.forEach(err => {
          policyErrors.push({
            lineId: String(line.id),
            field: err.field,
            error: err.code,
            message: err.message,
          });
        });
      });
      if (policyErrors.length) {
        await conn.rollback();
        return res.status(409).json({ error: 'payment_policy_violation', details: policyErrors });
      }
    }

    if (EI_GATE_PACKET_STATUSES.has(nextStatus)) {
      const interventionIds = Array.from(new Set(
        activeLines
          .map(line => line.intervention_id)
          .filter(Boolean)
          .concat(packetRow.intervention_id ? [packetRow.intervention_id] : [])
      ));
      const interventionMap = await fetchInterventionsById({ ids: interventionIds, connection: conn });
      const eiViolations = await findEiEligibilityViolations({
        lines: activeLines,
        packetRow,
        interventionMap,
        connection: conn,
      });
      if (eiViolations.length) {
        await conn.rollback();
        return res.status(409).json({ error: 'ei_active_claim_ineligible', details: eiViolations });
      }
    }

    const requiresFundingCheck = ['submitted', 'confirmed'].includes(nextStatus);
    if (requiresFundingCheck) {
      const interventionIds = new Set();
      activeLines.forEach(line => {
        if (line.intervention_id) {
          interventionIds.add(Number(line.intervention_id));
        } else if (packetRow.intervention_id) {
          interventionIds.add(Number(packetRow.intervention_id));
        }
      });
      const interventionIdList = Array.from(interventionIds).filter(Number.isFinite);
      if (interventionIdList.length) {
        const interventionMap = await fetchInterventionsById({ ids: interventionIdList, connection: conn });
        const usageMap = await fetchFundingUsageForInterventions({
          interventionIds: interventionIdList,
          connection: conn,
        });
        const authMap = new Map();
        const fundingErrors = [];
        for (const line of activeLines) {
          const interventionId = line.intervention_id || packetRow.intervention_id || null;
          if (!interventionId) continue;
          const key = String(interventionId);
          let auth = authMap.get(key);
          if (auth === undefined) {
            const interventionRow = interventionMap.get(Number(interventionId)) || null;
            auth = await resolveFundingAuthorizationForIntervention({
              interventionRow,
              caseId: packetRow.case_id || interventionRow?.case_id || null,
              connection: conn,
            });
            authMap.set(key, auth || null);
          }
          if (!auth) continue;
          const usage = usageMap.get(key) || { byCategory: {}, total: 0, byLine: new Map() };
          const lineErrors = validateFundingAuthorizationForLine({ line, auth, usage });
          lineErrors.forEach(err => {
            fundingErrors.push({
              lineId: String(line.id),
              field: err.field,
              error: err.code,
              message: err.message,
            });
          });
        }
        if (fundingErrors.length) {
          await conn.rollback();
          return res.status(409).json({ error: 'payment_funding_violation', details: fundingErrors });
        }
      }
    }

    if (DUPLICATE_GATE_PACKET_STATUSES.has(nextStatus)) {
      const duplicateScan = await collectDuplicatePaymentMatches({
        lines: activeLines,
        packetRow,
        connection: conn,
      });
      if (duplicateScan.matches.length) {
        if (duplicateScan.warnings.length) {
          await appendPacketDuplicateWarnings({
            packetId,
            warnings: duplicateScan.warnings,
            connection: conn,
          });
        }
        if (!overrideRequested || !overrideReason || !canUsePaymentOverride(actorRole)) {
          await conn.commit();
          return res.status(409).json({
            error: 'duplicate_payment_detected',
            details: duplicateScan.matches,
          });
        }
        const seenLines = new Set();
        for (const match of duplicateScan.matches) {
          if (!match.lineId) continue;
          const lineKey = String(match.lineId);
          if (seenLines.has(lineKey)) continue;
          seenLines.add(lineKey);
          await recordPaymentOverride({
            packetId,
            lineId: Number(match.lineId),
            overrideType: overrideType || 'duplicate_payment',
            reason: overrideReason,
            actorUserId,
            actorRole,
            fromStatus,
            toStatus: nextStatus,
            connection: conn,
          });
        }
      }
    }

    if (nextStatus === 'confirmed') {
      if (!isFinancePaymentsRole(actorRole)) {
        await conn.rollback();
        return res.status(403).json({ error: 'finance_role_required' });
      }
      const missingPaid = activeLines.filter(line =>
        line.status !== 'paid' ||
        !line.paid_at ||
        !normalizePaymentReference(line.payment_reference) ||
        !line.payment_proof_document_id
      );
      if (missingPaid.length) {
        await conn.rollback();
        return res.status(409).json({
          error: 'payment_line_not_paid',
          details: missingPaid.map(line => ({
            lineId: String(line.id),
            status: line.status,
            paidAt: line.paid_at || null,
            paymentReference: line.payment_reference || null,
          })),
        });
      }
    }

    if (nextStatus === 'submitted' || nextStatus === 'confirmed') {
      if (!actorUserId) {
        await conn.rollback();
        return res.status(400).json({ error: 'actor_user_required' });
      }
    }

    if (EVIDENCE_GATE_PACKET_STATUSES.has(nextStatus)) {
      const missing = await fetchMissingRequiredEvidence({ packetId, connection: conn });
      if (missing.length) {
        if (!overrideRequested || !overrideReason || !canUsePaymentOverride(actorRole)) {
          await conn.rollback();
          return res.status(409).json({ error: 'missing_required_evidence', missing });
        }
        await recordPaymentOverride({
          packetId,
          lineId: null,
          overrideType: overrideType || 'evidence_gate',
          reason: overrideReason,
          actorUserId,
          actorRole,
          fromStatus,
          toStatus: nextStatus,
          connection: conn,
        });
      }
    }

    if (nextStatus === 'submitted') {
      const submissionResult = await submitPaymentPacketExternally({
        packetId,
        packetRow,
        note: notes,
        req,
        connection: conn,
      });
      if (submissionResult?.error === 'intacct_rest_already_accepted') {
        await conn.rollback();
        return res.status(409).json({
          error: submissionResult.error,
          message: submissionResult.message,
        });
      }
      if (submissionResult?.error === 'finance_email_missing') {
        await conn.rollback();
        return res.status(409).json({
          error: submissionResult.error,
          message: submissionResult.message,
          regionCode: submissionResult.regionCode,
        });
      }
      if (submissionResult?.error === 'payment_packet_not_found') {
        await conn.rollback();
        return res.status(404).json({ error: submissionResult.error });
      }
      if (submissionResult?.error) {
        await conn.rollback();
        if (submissionResult?.mode === 'intacct_rest') {
          try {
            await recordPaymentPacketSubmissionMeta({
              packetId,
              mode: 'intacct_rest',
              detail: {
                status: 'failed',
                reason: 'submission',
                error: submissionResult.error,
                message: submissionResult.message || null,
                httpStatus: submissionResult.status || null,
                baseUrl: submissionResult.baseUrl || null,
              },
              connection: pool,
            });
          } catch (err) {
            console.warn('[intacct-rest] failed to record submission attempt after rollback', err?.message || err);
          }
        }
        return res.status(500).json({
          error: submissionResult.error,
          message: submissionResult.message,
          communication: submissionResult.communication,
          mode: submissionResult.mode,
        });
      }
    }

    const fields = ['status = ?', 'updated_at = NOW()'];
    const params = [nextStatus];
    if (nextStatus === 'draft' && fromStatus && normalizePaymentStatus(fromStatus) !== 'draft') {
      fields.push('submitted_at = NULL');
      fields.push('program_approved_at = NULL');
      fields.push('finance_approved_at = NULL');
      fields.push('sent_at = NULL');
      fields.push('confirmed_at = NULL');
      fields.push('program_approved_by_user_id = NULL');
      fields.push('finance_approved_by_user_id = NULL');
    }
    if (!packetRow.submitted_at && (nextStatus === 'submitted' || nextStatus === 'confirmed')) {
      fields.push('submitted_at = NOW()');
    }
    if (!packetRow.sent_at && (nextStatus === 'submitted' || nextStatus === 'confirmed')) {
      fields.push('sent_at = NOW()');
    }
    if (!packetRow.confirmed_at && nextStatus === 'confirmed') {
      fields.push('confirmed_at = NOW()');
    }
    if (nextStatus === 'submitted') {
      fields.push('follow_up_status = ?');
      params.push('sent_to_finance');
      fields.push('follow_up_updated_at = NOW()');
    } else if (nextStatus === 'cancelled') {
      fields.push('follow_up_status = ?');
      params.push('cancelled_not_proceeding');
      fields.push('follow_up_updated_at = NOW()');
    } else if (nextStatus === 'draft') {
      fields.push('follow_up_status = ?');
      params.push('not_required');
      fields.push('follow_up_due_at = NULL');
      fields.push('follow_up_updated_at = NULL');
    }
    params.push(packetId);
    await conn.query(`UPDATE payment_packet SET ${fields.join(', ')} WHERE id = ?`, params);

    const lineStatus = PACKET_STATUS_TO_LINE_STATUS[nextStatus];
    if (lineStatus && nextStatus !== 'confirmed') {
      const followUpLineStatus =
        nextStatus === 'submitted'
          ? 'sent_to_finance'
          : nextStatus === 'cancelled'
            ? 'cancelled_not_proceeding'
            : nextStatus === 'draft'
              ? 'not_required'
              : null;
      const [lineRows] = await conn.query(
        'SELECT id, status, follow_up_status FROM payment_packet_line WHERE payment_packet_id = ?',
        [packetId]
      );
      if (followUpLineStatus) {
        await conn.query(
          `UPDATE payment_packet_line
              SET status = ?,
                  follow_up_status = ?,
                  follow_up_due_at = CASE WHEN ? = 'not_required' THEN NULL ELSE follow_up_due_at END,
                  follow_up_updated_at = CASE WHEN ? = 'not_required' THEN NULL ELSE NOW() END
            WHERE payment_packet_id = ?
              AND status NOT IN ("paid","cancelled")`,
          [lineStatus, followUpLineStatus, followUpLineStatus, followUpLineStatus, packetId]
        );
      } else {
        await conn.query(
          'UPDATE payment_packet_line SET status = ? WHERE payment_packet_id = ? AND status NOT IN ("paid","cancelled")',
          [lineStatus, packetId]
        );
      }
      const eventTimestamp = new Date();
      const lineEventValues = (lineRows || [])
        .filter(row => row.status !== lineStatus && !['paid', 'cancelled'].includes(row.status))
        .map(row => [
          packetId,
          row.id,
          row.status || null,
          lineStatus,
          actorUserId,
          null,
          null,
          eventTimestamp,
        ]);
      if (lineEventValues.length) {
        await conn.query(
          `INSERT INTO payment_status_event
            (payment_packet_id, payment_packet_line_id, from_status, to_status, actor_user_id, notes, metadata, created_at)
           VALUES ?`,
          [lineEventValues]
        );
      }
      if (followUpLineStatus) {
        const followUpEventValues = (lineRows || [])
          .filter(row => !['paid', 'cancelled'].includes(row.status))
          .filter(row => (normalizePaymentFollowUpStatus(row.follow_up_status) || 'not_required') !== followUpLineStatus)
          .map(row => [
            packetId,
            row.id,
            normalizePaymentFollowUpStatus(row.follow_up_status) || 'not_required',
            followUpLineStatus,
            actorUserId,
            nextStatus === 'submitted' ? 'Finance email handoff recorded.' : null,
            null,
            null,
            JSON.stringify({ source: 'packet_status_transition', packetStatus: nextStatus }),
            eventTimestamp,
          ]);
        if (followUpEventValues.length) {
          await conn.query(
            `INSERT INTO payment_followup_event
              (payment_packet_id, payment_packet_line_id, from_status, to_status, actor_user_id, note, due_at, document_id, metadata, created_at)
             VALUES ?`,
            [followUpEventValues]
          );
        }
      }
    }

    if (nextStatus === 'submitted' || nextStatus === 'cancelled' || nextStatus === 'draft') {
      const fromFollowUpStatus = normalizePaymentFollowUpStatus(packetRow.follow_up_status) || 'not_required';
      const toFollowUpStatus =
        nextStatus === 'submitted'
          ? 'sent_to_finance'
          : nextStatus === 'cancelled'
            ? 'cancelled_not_proceeding'
            : 'not_required';
      if (fromFollowUpStatus !== toFollowUpStatus) {
        await createPaymentFollowUpEvent({
          packetId,
          fromStatus: fromFollowUpStatus,
          toStatus: toFollowUpStatus,
          actorUserId,
          note: nextStatus === 'submitted' ? 'Finance email handoff recorded.' : null,
          metadata: { source: 'packet_status_transition', packetStatus: nextStatus },
          connection: conn,
        });
      }
    }

    if (nextStatus === 'submitted') {
      const [lineRows] = await conn.query(
        'SELECT * FROM payment_packet_line WHERE payment_packet_id = ? AND status <> "cancelled"',
        [packetId]
      );
      const packetSnapshot = {
        case_id: packetRow.case_id,
        intervention_id: packetRow.intervention_id,
        submitted_at: packetRow.submitted_at || new Date(),
        reporting_unit: packetRow.reporting_unit,
        metadata: packetRow.metadata,
      };
      for (const line of lineRows) {
        await createFinanceTransactionForLine({
          lineRow: line,
          packetRow: packetSnapshot,
          connection: conn,
          status: 'submitted',
          transactionDate: packetSnapshot.submitted_at,
        });
      }
    }

    if (nextStatus === 'draft' && fromStatus && fromStatus !== 'draft') {
      await conn.query(
        `UPDATE finance_transaction ft
          JOIN payment_line_transaction plt ON plt.finance_transaction_id = ft.id
          JOIN payment_packet_line ppl ON ppl.id = plt.payment_packet_line_id
         SET ft.status = 'cancelled', ft.updated_at = NOW()
       WHERE ppl.payment_packet_id = ?`,
        [packetId]
      );
    }

    await conn.query(
      `INSERT INTO payment_status_event
        (payment_packet_id, payment_packet_line_id, from_status, to_status, actor_user_id, notes, metadata, created_at)
       VALUES (?, NULL, ?, ?, ?, ?, NULL, NOW())`,
      [packetId, fromStatus, nextStatus, actorUserId, notes]
    );

    if (nextStatus === 'confirmed') {
      const [lineRows] = await conn.query(
        'SELECT * FROM payment_packet_line WHERE payment_packet_id = ?',
        [packetId]
      );
      const packetSnapshot = {
        case_id: packetRow.case_id,
        intervention_id: packetRow.intervention_id,
        confirmed_at: packetRow.confirmed_at || new Date(),
        metadata: packetRow.metadata,
      };
      const evidenceRules = await readPaymentEvidenceRules(conn);
      const policyRules = await readPaymentPolicyRules(conn);
      const lineEventValues = [];
      const eventTimestamp = new Date();
      for (const line of lineRows) {
        if (line.status !== 'paid' && line.status !== 'cancelled') {
          await conn.query(
            'UPDATE payment_packet_line SET status = ?, updated_at = NOW() WHERE id = ?',
            ['paid', line.id]
          );
          lineEventValues.push([
            packetId,
            line.id,
            line.status || null,
            'paid',
            actorUserId,
            null,
            null,
            eventTimestamp,
          ]);
        }
        if (line.status !== 'cancelled') {
          const postPayTypes = extractPostPayEvidenceTypes(line, evidenceRules);
          if (postPayTypes.length) {
            const currentMeta = safeJsonParse(line.metadata, {}) || {};
            const schedule = ensurePostPayEvidenceSchedule({
              lineMeta: currentMeta,
              types: postPayTypes,
              referenceDate: eventTimestamp,
              policyRules,
            });
            if (schedule.changed) {
              await updatePaymentLineMetadata({
                lineId: line.id,
                metadata: schedule.metadata,
                connection: conn,
              });
            }
          }
        }
        if (line.status !== 'cancelled') {
          await createFinanceTransactionForLine({
            lineRow: line,
            packetRow: packetSnapshot,
            connection: conn,
            status: 'posted',
            transactionDate: packetSnapshot.confirmed_at || new Date(),
          });
        }
      }
      if (lineEventValues.length) {
        await conn.query(
          `INSERT INTO payment_status_event
            (payment_packet_id, payment_packet_line_id, from_status, to_status, actor_user_id, notes, metadata, created_at)
           VALUES ?`,
          [lineEventValues]
        );
      }
    }

    await conn.commit();
    await refreshFinancePotSums();
    const packet = await fetchPaymentPacketById(packetId);
    if (!packet) {
      return res.status(404).json({ error: 'payment_packet_not_found' });
    }
    res.status(200).json(packet);
  } catch (err) {
    await conn.rollback();
    console.error('[payments] failed to update payment packet status', err);
    res.status(500).json({ error: 'failed_to_update_payment_packet_status' });
  } finally {
    conn.release();
  }
});

app.post('/api/finance/payment-packets/:id/lines', async (req, res) => {
  if (requirePaymentsRole(req, res)) return;
  const packetId = parsePaymentPacketId(req.params.id);
  if (!Number.isFinite(packetId)) {
    return res.status(400).json({ error: 'invalid_payment_packet_id' });
  }
  const body = req.body || {};
  const linesPayload = Array.isArray(body.lines)
    ? body.lines
    : Array.isArray(body.lineItems)
      ? body.lineItems
      : body.line && typeof body.line === 'object'
        ? [body.line]
        : [];
  if (!linesPayload.length) {
    return res.status(400).json({ error: 'missing_line_items' });
  }

  const conn = await pool.getConnection();
  try {
    await conn.beginTransaction();
    const [[packetRow]] = await conn.query(
      'SELECT id, case_id, intervention_id, client_id FROM payment_packet WHERE id = ? LIMIT 1',
      [packetId]
    );
    if (!packetRow) {
      await conn.rollback();
      return res.status(404).json({ error: 'payment_packet_not_found' });
    }
    const accessError = await validatePaymentPacketAccess(req, packetId, { connection: conn });
    if (accessError) {
      await conn.rollback();
      return res.status(accessError.status).json(accessError.body);
    }

    const lineErrors = [];
    const lineInputs = linesPayload.map((line, index) => {
      const paymentType = typeof line.paymentType === 'string'
        ? line.paymentType.trim()
        : typeof line.payment_type === 'string'
          ? line.payment_type.trim()
          : '';
      if (!paymentType) {
        lineErrors.push({ index, field: 'paymentType', error: 'required', message: 'Payment type is required.' });
      }
      const payeeType = typeof line.payeeType === 'string'
        ? line.payeeType.trim()
        : typeof line.payee_type === 'string'
          ? line.payee_type.trim()
          : '';
      if (!payeeType) {
        lineErrors.push({ index, field: 'payeeType', error: 'required', message: 'Payee type is required.' });
      }
      const payeeName = typeof line.payeeName === 'string'
        ? line.payeeName.trim()
        : typeof line.payee_name === 'string'
          ? line.payee_name.trim()
            : '';
      if (!payeeName) {
        lineErrors.push({ index, field: 'payeeName', error: 'required', message: 'Payee name is required.' });
      }
      const amount = Number(line.amount);
      if (!Number.isFinite(amount) || amount <= 0) {
        lineErrors.push({ index, field: 'amount', error: 'invalid', message: 'Amount must be greater than 0.' });
      }
      const potId = normalisePositiveInteger(
        line.potId || line.budgetPotId || line.budget_pot_id
      );
      if (!potId) {
        lineErrors.push({ index, field: 'budgetPotId', error: 'required', message: 'Budget pot is required.' });
      }
      const rawLineStatus = normaliseString(line.status);
      const lineStatus = rawLineStatus ? normalizePaymentLineStatus(rawLineStatus) : 'needs_evidence';
      if (rawLineStatus && !lineStatus) {
        lineErrors.push({ index, field: 'status', error: 'invalid', message: 'Payment line status is invalid.' });
      }
      return {
        paymentType,
        payeeType,
        payeeName,
        amount,
        potId,
        status: lineStatus,
        payeeProfileId: normalisePositiveInteger(line.payeeProfileId || line.payee_profile_id),
        payeeReference: line.payeeReference || line.payee_reference || null,
        currency: line.currency || 'CAD',
        servicePeriodStart: line.servicePeriodStart || line.service_period_start || null,
        servicePeriodEnd: line.servicePeriodEnd || line.service_period_end || null,
        invoiceReferenceNumber: line.invoiceReferenceNumber || line.invoice_reference_number || null,
        requestedPaymentDate: line.requestedPaymentDate || line.requested_payment_date || null,
        fundingStream: line.fundingStream || line.funding_stream || null,
        holdReason: line.holdReason || line.hold_reason || null,
        interventionId: normalisePositiveInteger(line.interventionId || line.intervention_id) || packetRow.intervention_id || null,
        metadata: safeJsonParse(line.metadata, {}) || {},
      };
    });

    if (lineErrors.length) {
      await conn.rollback();
      return res.status(400).json({ error: 'invalid_line_items', message: 'One or more payment line items are invalid.', details: lineErrors });
    }
    const lineTargetAccessError = await validatePaymentTargetAccess(req, {
      caseId: packetRow.case_id,
      clientId: packetRow.client_id,
      interventionIds: lineInputs.map(line => line.interventionId).filter(Boolean),
      requireScopedContext: true,
      connection: conn,
    });
    if (lineTargetAccessError) {
      await conn.rollback();
      return res.status(lineTargetAccessError.status).json(lineTargetAccessError.body);
    }

    const potIds = Array.from(new Set(lineInputs.map(line => line.potId)));
    const potMap = new Map();
    if (potIds.length) {
      const [potRows] = await conn.query(
        `SELECT id, funding_source FROM budget_pot WHERE id IN (${potIds.map(() => '?').join(',')})`,
        potIds
      );
      potRows.forEach(row => potMap.set(Number(row.id), row));
    }
    const missingPotIds = potIds.filter(id => !potMap.has(id));
    if (missingPotIds.length) {
      await conn.rollback();
      return res.status(400).json({ error: 'invalid_budget_pot_ids', invalidPotIds: missingPotIds });
    }

    const policyRules = await readPaymentPolicyRules(conn);
    const recurrencePolicyByType = await readPaymentRecurrencePolicyByType(conn);
    const paymentTypeMap = await readPaymentInterventionMapping(conn);
    const interventionIds = Array.from(
      new Set(lineInputs.map(line => line.interventionId).filter(Boolean))
    );
    const interventionMap = await fetchInterventionsById({ ids: interventionIds, connection: conn });
    const blockedInterventionIds = interventionIds.filter(id => {
      const intervention = interventionMap.get(Number(id));
      return intervention && isPaymentBlockedInterventionStatus(intervention.status);
    });
    if (blockedInterventionIds.length) {
      await conn.rollback();
      return res.status(400).json({
        error: 'intervention_status_blocked',
        message: 'Selected intervention is not eligible for payment initiation.',
        blockedInterventionIds,
      });
    }
    lineInputs.forEach((line, index) => {
      const intervention = line.interventionId ? interventionMap.get(Number(line.interventionId)) : null;
      const validationErrors = validatePaymentLinePolicy({
        line: {
          payment_type: line.paymentType,
          payee_type: line.payeeType,
          amount: line.amount,
          service_period_start: line.servicePeriodStart,
          service_period_end: line.servicePeriodEnd,
          payee_name: line.payeeName,
          metadata: line.metadata,
        },
        intervention,
        evidenceTypeKeys: new Set(),
        policyRules,
        interventionPaymentTypeMap: paymentTypeMap,
        recurrencePolicyByType,
        validationStage: 'draft',
      });
      if (validationErrors.length) {
        validationErrors.forEach(err => {
          lineErrors.push({ index, field: err.field, error: err.code, message: err.message });
        });
      }
    });
    if (lineErrors.length) {
      await conn.rollback();
      return res.status(400).json({ error: 'invalid_line_items', message: 'One or more payment line items are invalid.', details: lineErrors });
    }

    const fundingErrors = await validateFundingAuthorizationForNewLines({
      lineInputs,
      packetRow,
      interventionMap,
      connection: conn,
    });
    if (fundingErrors.length) {
      await conn.rollback();
      return res.status(400).json({ error: 'invalid_line_items', message: 'One or more payment line items exceed available funding.', details: fundingErrors });
    }

    const lineValues = lineInputs.map(line => {
      const pot = potMap.get(line.potId);
      const fallbackStream = pot?.funding_source ? normalizeFundingSource(pot.funding_source) : null;
      const fundingStream = line.fundingStream ? normalizeFundingSource(line.fundingStream) : fallbackStream;
      return [
        packetId,
        line.interventionId,
        line.paymentType,
        line.payeeType,
        line.payeeName,
        line.payeeProfileId || null,
        line.payeeReference,
        line.amount,
        line.currency,
        line.servicePeriodStart,
        line.servicePeriodEnd,
        line.invoiceReferenceNumber,
        line.requestedPaymentDate,
        line.potId,
        fundingStream,
        line.status,
        line.holdReason,
        JSON.stringify(line.metadata),
      ];
    });

    const [insertResult] = await conn.query(
      `INSERT INTO payment_packet_line
        (payment_packet_id, intervention_id, payment_type, payee_type, payee_name, payee_profile_id, payee_reference,
         amount, currency, service_period_start, service_period_end, invoice_reference_number, requested_payment_date,
         budget_pot_id, funding_stream, status, hold_reason, metadata)
       VALUES ?`,
      [lineValues]
    );

    const insertIdBase = Number(insertResult?.insertId);
    const insertedIds = lineInputs.map((_, index) =>
      Number.isFinite(insertIdBase) ? insertIdBase + index : null
    );
    const candidateLines = lineInputs.map((line, index) => ({
      id: insertedIds[index],
      payment_packet_id: packetId,
      intervention_id: line.interventionId || packetRow.intervention_id || null,
      payment_type: line.paymentType,
      payee_name: line.payeeName,
      payee_reference: line.payeeReference || null,
      amount: line.amount,
      service_period_start: line.servicePeriodStart,
      service_period_end: line.servicePeriodEnd,
      invoice_reference_number: line.invoiceReferenceNumber,
      requested_payment_date: line.requestedPaymentDate,
    }));
    const duplicateScan = await collectDuplicatePaymentMatches({
      lines: candidateLines,
      packetRow,
      connection: conn,
    });
    if (duplicateScan.warnings.length) {
      await appendPacketDuplicateWarnings({
        packetId,
        warnings: duplicateScan.warnings,
        connection: conn,
      });
    }

    const interventionIdsForEvidence = new Set(
      lineInputs.map(line => line.interventionId).filter(Boolean)
    );
    if (packetRow.intervention_id) {
      interventionIdsForEvidence.add(packetRow.intervention_id);
    }
    await attachSupportingDocumentsToPaymentPacket({
      packetId,
      caseId: packetRow.case_id,
      clientId: packetRow.client_id,
      interventionIds: Array.from(interventionIdsForEvidence),
      connection: conn,
    });

    await clearPaymentPacketValidation({ packetId, connection: conn });

    await conn.commit();
    const packet = await fetchPaymentPacketById(packetId);
    res.status(201).json(packet);
  } catch (err) {
    await conn.rollback();
    console.error('[payments] failed to add payment lines', err);
    res.status(500).json({ error: 'failed_to_add_payment_lines' });
  } finally {
    conn.release();
  }
});

app.post('/api/finance/payment-packets/:id/lines/recurring', async (req, res) => {
  if (requirePaymentsRole(req, res)) return;
  const packetId = parsePaymentPacketId(req.params.id);
  if (!Number.isFinite(packetId)) {
    return res.status(400).json({ error: 'invalid_payment_packet_id' });
  }
  const body = req.body || {};
  const recurrence = body.recurrence && typeof body.recurrence === 'object' ? body.recurrence : {};
  const period = normalizeRecurringPeriod(body.period || recurrence.period);
  const startDate = body.startDate || recurrence.startDate || body.servicePeriodStart || body.service_period_start || null;
  const endDate = body.endDate || recurrence.endDate || body.servicePeriodEnd || body.service_period_end || null;
  const occurrences = body.occurrences || recurrence.occurrences || null;
  const templateLineId = parsePaymentLineId(body.templateLineId || body.template_line_id);

  const conn = await pool.getConnection();
  try {
    await conn.beginTransaction();
    const [[packetRow]] = await conn.query(
      'SELECT id, case_id, intervention_id, client_id FROM payment_packet WHERE id = ? LIMIT 1',
      [packetId]
    );
    if (!packetRow) {
      await conn.rollback();
      return res.status(404).json({ error: 'payment_packet_not_found' });
    }
    const accessError = await validatePaymentPacketAccess(req, packetId, { connection: conn });
    if (accessError) {
      await conn.rollback();
      return res.status(accessError.status).json(accessError.body);
    }

    let templateLine = null;
    if (Number.isFinite(templateLineId)) {
      const [[lineRow]] = await conn.query(
        'SELECT * FROM payment_packet_line WHERE id = ? AND payment_packet_id = ? LIMIT 1',
        [templateLineId, packetId]
      );
      if (!lineRow) {
        await conn.rollback();
        return res.status(404).json({ error: 'template_line_not_found' });
      }
      templateLine = lineRow;
    }

    const amountMode =
      normalizeRecurringAmountMode(
        body.amountMode || body.amount_mode,
        body.splitAmount || body.split_amount
      ) || 'repeat_amount';
    const paymentType =
      (typeof body.paymentType === 'string' && body.paymentType.trim()) ||
      (typeof body.payment_type === 'string' && body.payment_type.trim()) ||
      templateLine?.payment_type ||
      '';
    const payeeType =
      (typeof body.payeeType === 'string' && body.payeeType.trim()) ||
      (typeof body.payee_type === 'string' && body.payee_type.trim()) ||
      templateLine?.payee_type ||
      '';
    const payeeName =
      (typeof body.payeeName === 'string' && body.payeeName.trim()) ||
      (typeof body.payee_name === 'string' && body.payee_name.trim()) ||
      templateLine?.payee_name ||
      '';
    const rawAmount =
      body.amount !== undefined && body.amount !== null
        ? Number(body.amount)
        : templateLine
          ? Number(templateLine.amount || 0)
          : NaN;
    const totalAmount =
      body.totalAmount !== undefined && body.totalAmount !== null
        ? Number(body.totalAmount)
        : body.total_amount !== undefined && body.total_amount !== null
          ? Number(body.total_amount)
          : rawAmount;
    const amountValue = amountMode === 'split_total' ? totalAmount : rawAmount;
    const potId = normalisePositiveInteger(
      body.potId || body.budgetPotId || body.budget_pot_id || templateLine?.budget_pot_id
    );
    const interventionId = normalisePositiveInteger(
      body.interventionId || body.intervention_id || templateLine?.intervention_id || packetRow.intervention_id
    );
    const targetAccessError = await validatePaymentTargetAccess(req, {
      caseId: packetRow.case_id,
      clientId: packetRow.client_id,
      interventionIds: interventionId ? [interventionId] : [],
      requireScopedContext: true,
      connection: conn,
    });
    if (targetAccessError) {
      await conn.rollback();
      return res.status(targetAccessError.status).json(targetAccessError.body);
    }
    const currency = body.currency || templateLine?.currency || 'CAD';
    const payeeProfileId = normalisePositiveInteger(
      body.payeeProfileId || body.payee_profile_id || templateLine?.payee_profile_id
    );
    const payeeReference =
      body.payeeReference ||
      body.payee_reference ||
      templateLine?.payee_reference ||
      null;
    const baseMetadata = safeJsonParse(body.metadata, {}) || {};
    const recurrencePolicyByType = await readPaymentRecurrencePolicyByType(conn);
    const recurrenceMode = resolveRecurrenceModeForPaymentType(paymentType, recurrencePolicyByType);

    const lineErrors = [];
    if (!paymentType) lineErrors.push({ field: 'paymentType', error: 'required' });
    if (!payeeType) lineErrors.push({ field: 'payeeType', error: 'required' });
    if (!payeeName) lineErrors.push({ field: 'payeeName', error: 'required' });
    if (!Number.isFinite(amountValue) || amountValue <= 0) {
      lineErrors.push({ field: amountMode === 'split_total' ? 'totalAmount' : 'amount', error: 'invalid' });
    }
    if (!potId) lineErrors.push({ field: 'budgetPotId', error: 'required' });
    if (!period) lineErrors.push({ field: 'period', error: 'required' });
    if (!startDate) lineErrors.push({ field: 'startDate', error: 'required' });
    if (!endDate && !occurrences) {
      lineErrors.push({ field: 'endDate', error: 'required' });
    }
    if (paymentType && recurrenceMode === RECURRENCE_MODE_NOT_ALLOWED) {
      lineErrors.push({
        field: 'paymentType',
        error: 'recurrence_not_allowed',
        message: 'Recurring lines are not allowed for this payment type.',
      });
    }
    if (lineErrors.length) {
      await conn.rollback();
      return res.status(400).json({ error: 'invalid_recurring_inputs', details: lineErrors });
    }

    const potIds = Array.from(new Set([potId].filter(Boolean)));
    const potMap = new Map();
    if (potIds.length) {
      const [potRows] = await conn.query(
        `SELECT id, funding_source FROM budget_pot WHERE id IN (${potIds.map(() => '?').join(',')})`,
        potIds
      );
      potRows.forEach(row => potMap.set(Number(row.id), row));
    }
    if (!potMap.has(potId)) {
      await conn.rollback();
      return res.status(400).json({ error: 'invalid_budget_pot_id', invalidPotIds: [potId] });
    }

    const { periods, error: periodError } = buildRecurringServicePeriods({
      startDate,
      endDate,
      period,
      occurrences,
    });
    if (periodError) {
      await conn.rollback();
      return res.status(400).json({ error: 'invalid_recurring_period', code: periodError });
    }
    if (!periods.length) {
      await conn.rollback();
      return res.status(400).json({ error: 'no_recurring_periods' });
    }

    const lineAmounts =
      amountMode === 'split_total'
        ? splitRecurringAmount(amountValue, periods.length)
        : Array.from({ length: periods.length }, () => amountValue);
    if (!lineAmounts.length || lineAmounts.some(amount => !Number.isFinite(amount) || amount <= 0)) {
      await conn.rollback();
      return res.status(400).json({
        error: 'invalid_recurring_inputs',
        details: [{ field: amountMode === 'split_total' ? 'totalAmount' : 'amount', error: 'invalid' }],
      });
    }

    const [existingRows] = await conn.query(
      `SELECT payment_type, payee_name, service_period_start, service_period_end
         FROM payment_packet_line
        WHERE payment_packet_id = ?`,
      [packetId]
    );
    const existingKeys = new Set(
      (existingRows || []).map(row => [
        normalizePaymentTypeKey(row.payment_type) || row.payment_type,
        normalizeComparableName(row.payee_name),
        toDateOnlyString(row.service_period_start),
        toDateOnlyString(row.service_period_end),
      ].join('|'))
    );

    const lineInputs = periods
      .map((periodItem, index) => {
        const key = [
          normalizePaymentTypeKey(paymentType) || paymentType,
          normalizeComparableName(payeeName),
          periodItem.start,
          periodItem.end,
        ].join('|');
        if (existingKeys.has(key)) return null;
        const metadata = {
          ...baseMetadata,
          recurrence: {
            period,
            index: index + 1,
            total: periods.length,
            scheduleStart: periods[0]?.start || null,
            scheduleEnd: periods[periods.length - 1]?.end || null,
            generatedFromLineId: templateLine ? String(templateLine.id) : null,
          },
        };
        return {
          paymentType,
          payeeType,
          payeeName,
          amount: lineAmounts[index],
          potId,
          status: 'needs_evidence',
          payeeProfileId,
          payeeReference,
          currency,
          servicePeriodStart: periodItem.start,
          servicePeriodEnd: periodItem.end,
          invoiceReferenceNumber: body.invoiceReferenceNumber || body.invoice_reference_number || null,
          requestedPaymentDate: periodItem.end,
          fundingStream: body.fundingStream || body.funding_stream || null,
          holdReason: null,
          interventionId: interventionId || null,
          metadata,
        };
      })
      .filter(Boolean);

    if (!lineInputs.length) {
      await conn.rollback();
      return res.status(409).json({ error: 'no_new_recurring_lines' });
    }

    const policyRules = await readPaymentPolicyRules(conn);
    const paymentTypeMap = await readPaymentInterventionMapping(conn);
    const interventionIds = Array.from(
      new Set(lineInputs.map(line => line.interventionId).filter(Boolean))
    );
    const interventionMap = await fetchInterventionsById({ ids: interventionIds, connection: conn });
    const blockedInterventionIds = interventionIds.filter(id => {
      const intervention = interventionMap.get(Number(id));
      return intervention && isPaymentBlockedInterventionStatus(intervention.status);
    });
    if (blockedInterventionIds.length) {
      await conn.rollback();
      return res.status(400).json({
        error: 'intervention_status_blocked',
        message: 'Selected intervention is not eligible for payment initiation.',
        blockedInterventionIds,
      });
    }
    const validationErrors = [];
    lineInputs.forEach((line, index) => {
      const intervention = line.interventionId ? interventionMap.get(Number(line.interventionId)) : null;
      const errors = validatePaymentLinePolicy({
        line: {
          payment_type: line.paymentType,
          payee_type: line.payeeType,
          amount: line.amount,
          service_period_start: line.servicePeriodStart,
          service_period_end: line.servicePeriodEnd,
          payee_name: line.payeeName,
          metadata: line.metadata,
        },
        intervention,
        evidenceTypeKeys: new Set(),
        policyRules,
        interventionPaymentTypeMap: paymentTypeMap,
        recurrencePolicyByType,
        validationStage: 'draft',
      });
      if (errors.length) {
        errors.forEach(err => {
          validationErrors.push({ index, field: err.field, error: err.code, message: err.message });
        });
      }
    });
    if (validationErrors.length) {
      await conn.rollback();
      return res.status(400).json({ error: 'invalid_line_items', message: 'One or more payment line items are invalid.', details: validationErrors });
    }

    const fundingErrors = await validateFundingAuthorizationForNewLines({
      lineInputs,
      packetRow,
      interventionMap,
      connection: conn,
    });
    if (fundingErrors.length) {
      await conn.rollback();
      return res.status(400).json({ error: 'invalid_line_items', message: 'One or more payment line items exceed available funding.', details: fundingErrors });
    }

    const lineValues = lineInputs.map(line => {
      const pot = potMap.get(line.potId);
      const fallbackStream = pot?.funding_source ? normalizeFundingSource(pot.funding_source) : null;
      const fundingStream = line.fundingStream ? normalizeFundingSource(line.fundingStream) : fallbackStream;
      return [
        packetId,
        line.interventionId,
        line.paymentType,
        line.payeeType,
        line.payeeName,
        line.payeeProfileId || null,
        line.payeeReference,
        line.amount,
        line.currency,
        line.servicePeriodStart,
        line.servicePeriodEnd,
        line.invoiceReferenceNumber,
        line.requestedPaymentDate,
        line.potId,
        fundingStream,
        line.status,
        line.holdReason,
        JSON.stringify(line.metadata),
      ];
    });

    const [insertResult] = await conn.query(
      `INSERT INTO payment_packet_line
        (payment_packet_id, intervention_id, payment_type, payee_type, payee_name, payee_profile_id, payee_reference,
         amount, currency, service_period_start, service_period_end, invoice_reference_number, requested_payment_date,
         budget_pot_id, funding_stream, status, hold_reason, metadata)
       VALUES ?`,
      [lineValues]
    );

    const insertIdBase = Number(insertResult?.insertId);
    const insertedIds = lineInputs.map((_, index) =>
      Number.isFinite(insertIdBase) ? insertIdBase + index : null
    );
    const candidateLines = lineInputs.map((line, index) => ({
      id: insertedIds[index],
      payment_packet_id: packetId,
      intervention_id: line.interventionId || packetRow.intervention_id || null,
      payment_type: line.paymentType,
      payee_name: line.payeeName,
      payee_reference: line.payeeReference || null,
      amount: line.amount,
      service_period_start: line.servicePeriodStart,
      service_period_end: line.servicePeriodEnd,
      invoice_reference_number: line.invoiceReferenceNumber,
      requested_payment_date: line.requestedPaymentDate,
    }));
    const duplicateScan = await collectDuplicatePaymentMatches({
      lines: candidateLines,
      packetRow,
      connection: conn,
    });
    if (duplicateScan.warnings.length) {
      await appendPacketDuplicateWarnings({
        packetId,
        warnings: duplicateScan.warnings,
        connection: conn,
      });
    }

    const interventionIdsForEvidence = new Set(
      lineInputs.map(line => line.interventionId).filter(Boolean)
    );
    if (packetRow.intervention_id) {
      interventionIdsForEvidence.add(packetRow.intervention_id);
    }
    await attachSupportingDocumentsToPaymentPacket({
      packetId,
      caseId: packetRow.case_id,
      clientId: packetRow.client_id,
      interventionIds: Array.from(interventionIdsForEvidence),
      connection: conn,
    });

    await clearPaymentPacketValidation({ packetId, connection: conn });

    await conn.commit();
    const packet = await fetchPaymentPacketById(packetId);
    res.status(201).json(packet);
  } catch (err) {
    await conn.rollback();
    console.error('[payments] failed to add recurring payment lines', err);
    res.status(500).json({ error: 'failed_to_add_recurring_payment_lines' });
  } finally {
    conn.release();
  }
});

app.delete('/api/finance/payment-lines/:id', async (req, res) => {
  if (requirePaymentsRole(req, res)) return;
  const lineId = parsePaymentLineId(req.params.id);
  if (!Number.isFinite(lineId)) {
    return res.status(400).json({ error: 'invalid_payment_line_id' });
  }

  const conn = await pool.getConnection();
  let packetId = null;
  try {
    await conn.beginTransaction();
    const [[lineRow]] = await conn.query(
      'SELECT payment_packet_id FROM payment_packet_line WHERE id = ? LIMIT 1',
      [lineId]
    );
    if (!lineRow) {
      await conn.rollback();
      return res.status(404).json({ error: 'payment_line_not_found' });
    }
    const accessError = await validatePaymentPacketAccess(req, lineRow.payment_packet_id, { connection: conn });
    if (accessError) {
      await conn.rollback();
      return res.status(accessError.status).json(accessError.body);
    }
    const result = await deletePaymentLine({ lineId, connection: conn });
    if (result.missing) {
      await conn.rollback();
      return res.status(404).json({ error: 'payment_line_not_found' });
    }
    if (result.notDraft) {
      await conn.rollback();
      return res.status(409).json({ error: 'packet_not_editable', status: result.status || null });
    }
    packetId = result.packetId ? Number(result.packetId) : null;
    await conn.commit();
  } catch (err) {
    await conn.rollback();
    console.error('[payments] failed to delete payment line', err);
    return res.status(500).json({ error: 'failed_to_delete_payment_line' });
  } finally {
    conn.release();
  }

  if (!packetId) {
    return res.status(200).json({ deleted: true });
  }
  const packet = await fetchPaymentPacketById(packetId);
  return packet ? res.status(200).json(packet) : res.status(200).json({ deleted: true, packetId });
});

app.put('/api/finance/payment-lines/:id', async (req, res) => {
  if (requirePaymentsRole(req, res)) return;
  const lineId = parsePaymentLineId(req.params.id);
  if (!Number.isFinite(lineId)) {
    return res.status(400).json({ error: 'invalid_payment_line_id' });
  }
  const body = req.body || {};
  if (body.status) {
    return res.status(400).json({ error: 'status_updates_require_status_endpoint' });
  }
  try {
    const fields = [];
    const params = [];
    const nextValues = {};
    const assign = (column, value) => {
      fields.push(`${column} = ?`);
      params.push(value);
      nextValues[column] = value;
    };
    if (body.paymentType !== undefined || body.payment_type !== undefined) {
      const value =
        typeof body.paymentType === 'string'
          ? body.paymentType.trim()
          : typeof body.payment_type === 'string'
            ? body.payment_type.trim()
            : null;
      if (!value) {
        return res.status(400).json({ error: 'paymentType_required' });
      }
      assign('payment_type', value);
    }
    if (body.payeeType !== undefined || body.payee_type !== undefined) {
      const value =
        typeof body.payeeType === 'string'
          ? body.payeeType.trim()
          : typeof body.payee_type === 'string'
            ? body.payee_type.trim()
            : null;
      if (!value) {
        return res.status(400).json({ error: 'payeeType_required' });
      }
      assign('payee_type', value);
    }
    if (body.payeeName !== undefined || body.payee_name !== undefined) {
      const value =
        typeof body.payeeName === 'string'
          ? body.payeeName.trim()
          : typeof body.payee_name === 'string'
            ? body.payee_name.trim()
            : null;
      if (!value) {
        return res.status(400).json({ error: 'payeeName_required' });
      }
      assign('payee_name', value);
    }
    if (body.payeeProfileId !== undefined || body.payee_profile_id !== undefined) {
      assign(
        'payee_profile_id',
        normalisePositiveInteger(body.payeeProfileId || body.payee_profile_id) || null
      );
    }
    if (body.payeeReference !== undefined || body.payee_reference !== undefined) {
      assign('payee_reference', body.payeeReference || body.payee_reference || null);
    }
    if (body.amount !== undefined) {
      const amount = Number(body.amount);
      if (!Number.isFinite(amount) || amount <= 0) {
        return res.status(400).json({ error: 'invalid_amount' });
      }
      assign('amount', amount);
    }
    if (body.currency !== undefined) {
      assign('currency', body.currency || 'CAD');
    }
    if (body.servicePeriodStart !== undefined || body.service_period_start !== undefined) {
      assign('service_period_start', body.servicePeriodStart || body.service_period_start || null);
    }
    if (body.servicePeriodEnd !== undefined || body.service_period_end !== undefined) {
      assign('service_period_end', body.servicePeriodEnd || body.service_period_end || null);
    }
    if (body.invoiceReferenceNumber !== undefined || body.invoice_reference_number !== undefined) {
      assign('invoice_reference_number', body.invoiceReferenceNumber || body.invoice_reference_number || null);
    }
    if (body.requestedPaymentDate !== undefined || body.requested_payment_date !== undefined) {
      assign('requested_payment_date', body.requestedPaymentDate || body.requested_payment_date || null);
    }
    if (body.budgetPotId !== undefined || body.budget_pot_id !== undefined || body.potId !== undefined) {
      const potId = normalisePositiveInteger(body.budgetPotId || body.budget_pot_id || body.potId);
      if (!potId) {
        return res.status(400).json({ error: 'invalid_budget_pot_id' });
      }
      assign('budget_pot_id', potId);
      if (body.fundingStream === undefined && body.funding_stream === undefined) {
        const [[potRow]] = await pool.query(
          'SELECT funding_source FROM budget_pot WHERE id = ? LIMIT 1',
          [potId]
        );
        const fallback = potRow?.funding_source ? normalizeFundingSource(potRow.funding_source) : null;
        assign('funding_stream', fallback);
      }
    }
    if (body.fundingStream !== undefined || body.funding_stream !== undefined) {
      const fundingStream = body.fundingStream || body.funding_stream || null;
      assign('funding_stream', fundingStream ? normalizeFundingSource(fundingStream) : null);
    }
    if (body.holdReason !== undefined || body.hold_reason !== undefined) {
      assign('hold_reason', body.holdReason || body.hold_reason || null);
    }
    if (body.metadata !== undefined) {
      const meta = safeJsonParse(body.metadata, {}) || {};
      assign('metadata', JSON.stringify(meta));
    }
    if (!fields.length) {
      return res.status(400).json({ error: 'no_fields_to_update' });
    }
    const [[currentLine]] = await pool.query(
      'SELECT * FROM payment_packet_line WHERE id = ? LIMIT 1',
      [lineId]
    );
    if (!currentLine) {
      return res.status(404).json({ error: 'payment_line_not_found' });
    }
    const nextLine = { ...currentLine, ...nextValues };
    const [[packetRow]] = await pool.query(
      'SELECT case_id, intervention_id, client_id FROM payment_packet WHERE id = ? LIMIT 1',
      [nextLine.payment_packet_id]
    );
    if (!packetRow) {
      return res.status(404).json({ error: 'payment_packet_not_found' });
    }
    const accessError = await validatePaymentPacketAccess(req, nextLine.payment_packet_id);
    if (accessError) {
      return res.status(accessError.status).json(accessError.body);
    }
    const policyRules = await readPaymentPolicyRules(pool);
    const recurrencePolicyByType = await readPaymentRecurrencePolicyByType(pool);
    const paymentTypeMap = await readPaymentInterventionMapping(pool);
    const primaryInterventionId = nextLine.intervention_id || packetRow?.intervention_id || null;
    const targetAccessError = await validatePaymentTargetAccess(req, {
      caseId: packetRow.case_id,
      clientId: packetRow.client_id,
      interventionIds: primaryInterventionId ? [primaryInterventionId] : [],
      requireScopedContext: true,
    });
    if (targetAccessError) {
      return res.status(targetAccessError.status).json(targetAccessError.body);
    }
    const interventionMap = await fetchInterventionsById({
      ids: primaryInterventionId ? [primaryInterventionId] : [],
      connection: pool,
    });
    const intervention = primaryInterventionId
      ? interventionMap.get(Number(primaryInterventionId))
      : null;
    const evidenceTypeKeys = await fetchEvidenceTypeSetForLine({
      packetId: Number(nextLine.payment_packet_id),
      lineId,
      connection: pool,
    });
    const validationErrors = validatePaymentLinePolicy({
      line: nextLine,
      intervention,
      evidenceTypeKeys,
      policyRules,
      interventionPaymentTypeMap: paymentTypeMap,
      recurrencePolicyByType,
      validationStage: 'draft',
    });
    if (validationErrors.length) {
      return res.status(400).json({
        error: 'invalid_line_items',
        message: 'One or more payment line items are invalid.',
        details: validationErrors.map(err => ({
          field: err.field,
          error: err.code,
          message: err.message,
        })),
      });
    }
    if (primaryInterventionId) {
      const usageMap = await fetchFundingUsageForInterventions({
        interventionIds: [primaryInterventionId],
        connection: pool,
      });
      const auth = await resolveFundingAuthorizationForIntervention({
        interventionRow: intervention,
        caseId: packetRow?.case_id || intervention?.case_id || null,
        connection: pool,
      });
      const fundingErrors = validateFundingAuthorizationForLine({
        line: nextLine,
        auth,
        usage: usageMap.get(String(primaryInterventionId)) || { byCategory: {}, total: 0, byLine: new Map() },
      });
      if (fundingErrors.length) {
        return res.status(400).json({
          error: 'invalid_line_items',
          message: 'One or more payment line items exceed available funding.',
          details: fundingErrors.map(err => ({
            field: err.field,
            error: err.code,
            message: err.message,
          })),
        });
      }
    }
    params.push(lineId);
    await pool.query(
      `UPDATE payment_packet_line SET ${fields.join(', ')}, updated_at = NOW() WHERE id = ?`,
      params
    );
    const duplicateScan = await collectDuplicatePaymentMatches({
      lines: [nextLine],
      packetRow: {
        id: nextLine.payment_packet_id,
        client_id: packetRow?.client_id || null,
        intervention_id: packetRow?.intervention_id || null,
      },
      connection: pool,
    });
    if (duplicateScan.warnings.length) {
      await appendPacketDuplicateWarnings({
        packetId: nextLine.payment_packet_id,
        warnings: duplicateScan.warnings,
        connection: pool,
      });
    }
    await clearPaymentPacketValidation({ packetId: nextLine.payment_packet_id, connection: pool });
    const [[lineRow]] = await pool.query(
      `SELECT ppl.*, bp.name AS pot_name, bp.funding_source AS pot_funding_source
         FROM payment_packet_line ppl
         LEFT JOIN budget_pot bp ON bp.id = ppl.budget_pot_id
        WHERE ppl.id = ?
        LIMIT 1`,
      [lineId]
    );
    if (!lineRow) {
      return res.status(404).json({ error: 'payment_line_not_found' });
    }
    res.status(200).json(mapPaymentLineRow(lineRow));
  } catch (err) {
    console.error('[payments] failed to update payment line', err);
    res.status(500).json({ error: 'failed_to_update_payment_line' });
  }
});

app.post('/api/finance/payment-lines/:id/status', async (req, res) => {
  if (requirePaymentsRole(req, res)) return;
  const lineId = parsePaymentLineId(req.params.id);
  if (!Number.isFinite(lineId)) {
    return res.status(400).json({ error: 'invalid_payment_line_id' });
  }
  const body = req.body || {};
  const nextStatus = normalizePaymentLineStatus(body.status);
  if (!nextStatus) {
    return res.status(400).json({ error: 'invalid_status' });
  }
  let actorUserId = null;
  const actorRoleRaw = inferUserRole(req);
  const actorRole = canonicaliseAccessRole(actorRoleRaw) || actorRoleRaw;
  const notes = typeof body.notes === 'string' ? body.notes.trim() : null;
  const holdReason = body.holdReason || body.hold_reason || null;
  const overrideReason = normalizeOverrideReason(
    body.overrideReason || body.override_reason || body.overrideNote || body.override_note
  );
  const paidAt = parsePaymentDateTime(
    body.paidAt || body.paid_at || body.paidDate || body.paid_date || body.paymentDate || body.payment_date
  );
  const paymentReference = normalizePaymentReference(
    body.paymentReference || body.payment_reference || body.paymentRef || body.reference
  );
  const paymentProofDocumentId = normalisePositiveInteger(
    body.paymentProofDocumentId || body.payment_proof_document_id || body.proofDocumentId
  ) || null;
  const overrideRequested = body.override === true || !!overrideReason || !!body.overrideType || !!body.override_type;
  const overrideTypeRaw = body.overrideType || body.override_type || null;
  const overrideType = typeof overrideTypeRaw === 'string' ? overrideTypeRaw.trim() : null;

  const conn = await pool.getConnection();
  try {
    await conn.beginTransaction();
    actorUserId = await resolveFinanceRouteActorUserId(req, conn);
    if (!actorUserId) {
      await conn.rollback();
      return res.status(400).json({ error: 'actor_user_required' });
    }
    const [[lineRow]] = await conn.query(
      `SELECT ppl.*, pp.case_id, pp.intervention_id, pp.client_id, pp.status AS packet_status, pp.confirmed_at,
              pp.metadata AS packet_metadata, pp.requester_user_id
         FROM payment_packet_line ppl
         LEFT JOIN payment_packet pp ON pp.id = ppl.payment_packet_id
        WHERE ppl.id = ?
        LIMIT 1`,
      [lineId]
    );
    if (!lineRow) {
      await conn.rollback();
      return res.status(404).json({ error: 'payment_line_not_found' });
    }
    const accessError = await validatePaymentPacketAccess(req, lineRow.payment_packet_id, { connection: conn });
    if (accessError) {
      await conn.rollback();
      return res.status(accessError.status).json(accessError.body);
    }
    const fromStatus = lineRow.status || null;
    const simplePaidWorkflow = SIMPLE_PAYMENT_WORKFLOW && nextStatus === 'paid';
    const resolvedPaidAt = simplePaidWorkflow ? (paidAt || new Date()) : paidAt;
    const resolvedPaymentReference = simplePaidWorkflow ? (paymentReference || null) : paymentReference;
    const resolvedProofDocumentId = paymentProofDocumentId || lineRow.payment_proof_document_id || null;
    if (nextStatus === 'paid') {
      if (!simplePaidWorkflow) {
        if (!isFinancePaymentsRole(actorRole)) {
          await conn.rollback();
          return res.status(403).json({ error: 'finance_role_required' });
        }
        if (!resolvedPaidAt) {
          await conn.rollback();
          return res.status(400).json({ error: 'paid_at_required' });
        }
        if (!resolvedPaymentReference) {
          await conn.rollback();
          return res.status(400).json({ error: 'payment_reference_required' });
        }
        if (!resolvedProofDocumentId) {
          await conn.rollback();
          return res.status(400).json({ error: 'payment_proof_required' });
        }
        if (resolvedProofDocumentId) {
          const [[docRow]] = await conn.query(
            `SELECT id, checksum_sha256, client_id, case_id, application_id, action_plan_id, applicant_user_id
               FROM iset_document
              WHERE id = ? AND status = "active"
              LIMIT 1`,
            [resolvedProofDocumentId]
          );
          if (!docRow) {
            await conn.rollback();
            return res.status(400).json({ error: 'payment_proof_document_not_found' });
          }
          let documentAccessError = await validateDocumentAccess(req, docRow, { connection: conn });
          if (documentAccessError) {
            const paymentDocumentAccessError = await validatePaymentPacketDocumentAccess(req, {
              packetId: lineRow.payment_packet_id,
              documentRow: docRow,
              connection: conn,
            });
            documentAccessError = paymentDocumentAccessError || null;
          }
          if (documentAccessError) {
            await conn.rollback();
            return res.status(documentAccessError.status).json(documentAccessError.body);
          }
          if (docRow.client_id && lineRow.client_id && Number(docRow.client_id) !== Number(lineRow.client_id)) {
            await conn.rollback();
            return res.status(409).json({ error: 'client_id_mismatch' });
          }
          if (!docRow.checksum_sha256 || String(docRow.checksum_sha256).length !== 64) {
            await conn.rollback();
            return res.status(400).json({ error: 'payment_proof_checksum_missing' });
          }
        }
        if (normalizePaymentLineStatus(lineRow.status) !== 'submitted') {
          await conn.rollback();
          return res.status(409).json({ error: 'line_not_submitted' });
        }
        const [[batchRow]] = await conn.query(
          `SELECT pb.id, pb.status
             FROM payment_batch_line pbl
             LEFT JOIN payment_batch pb ON pb.id = pbl.payment_batch_id
            WHERE pbl.payment_packet_line_id = ?
            ORDER BY pb.id DESC
            LIMIT 1`,
          [lineId]
        );
        if (!batchRow || !batchRow.id) {
          await conn.rollback();
          return res.status(409).json({ error: 'batch_required' });
        }
        if (!['approved', 'exported'].includes(batchRow.status)) {
          await conn.rollback();
          return res.status(409).json({
            error: 'batch_not_approved',
            batchId: batchRow.id ? String(batchRow.id) : null,
            batchStatus: batchRow.status || null,
          });
        }
      }
    }
    if (nextStatus === 'paid') {
      const policyRules = await readPaymentPolicyRules(conn);
      const recurrencePolicyByType = await readPaymentRecurrencePolicyByType(conn);
      const paymentTypeMap = await readPaymentInterventionMapping(conn);
      const interventionMap = await fetchInterventionsById({
        ids: [lineRow.intervention_id || lineRow.interventionId],
        connection: conn,
      });
      const intervention = lineRow.intervention_id
        ? interventionMap.get(Number(lineRow.intervention_id))
        : null;
      const evidenceTypeKeys = await fetchEvidenceTypeSetForLine({
        packetId: Number(lineRow.payment_packet_id),
        lineId,
        connection: conn,
      });
      const validationErrors = validatePaymentLinePolicy({
        line: lineRow,
        intervention,
        evidenceTypeKeys,
        policyRules,
        interventionPaymentTypeMap: paymentTypeMap,
        recurrencePolicyByType,
        validationStage: 'submission',
      });
      if (validationErrors.length) {
        await conn.rollback();
        return res.status(409).json({
          error: 'payment_policy_violation',
          details: validationErrors.map(err => ({
            field: err.field,
            error: err.code,
            message: err.message,
          })),
        });
      }
    }
    if (nextStatus === 'paid') {
      const primaryInterventionId = lineRow.intervention_id || lineRow.interventionId || null;
      if (primaryInterventionId) {
        const interventionMap = await fetchInterventionsById({
          ids: [primaryInterventionId],
          connection: conn,
        });
        const intervention = interventionMap.get(Number(primaryInterventionId)) || null;
        const usageMap = await fetchFundingUsageForInterventions({
          interventionIds: [primaryInterventionId],
          connection: conn,
        });
        const auth = await resolveFundingAuthorizationForIntervention({
          interventionRow: intervention,
          caseId: lineRow.case_id || intervention?.case_id || null,
          connection: conn,
        });
        const fundingErrors = validateFundingAuthorizationForLine({
          line: lineRow,
          auth,
          usage: usageMap.get(String(primaryInterventionId)) || { byCategory: {}, total: 0, byLine: new Map() },
        });
        if (fundingErrors.length) {
          await conn.rollback();
          return res.status(409).json({
            error: 'payment_funding_violation',
            details: fundingErrors.map(err => ({
              field: err.field,
              error: err.code,
              message: err.message,
            })),
          });
        }
      }
    }
    if (nextStatus === 'paid') {
      if (!simplePaidWorkflow) {
        if (!actorUserId) {
          await conn.rollback();
          return res.status(400).json({ error: 'actor_user_required' });
        }
        const approvalRules = await readPaymentApprovalRules(conn);
        const requirement = resolveApprovalRequirement(approvalRules.paid, {
          totalAmount: Number(lineRow.amount || 0),
          maxLineAmount: Number(lineRow.amount || 0),
        });
        if (requirement && !roleAllowedByApprovalRule(actorRole, requirement)) {
          if (!overrideRequested || !overrideReason || !canUsePaymentOverride(actorRole)) {
            await conn.rollback();
            return res.status(403).json({
              error: 'approval_threshold_requires_role',
              requiredRoles: requirement.roles || [],
            });
          }
          await recordPaymentOverride({
            packetId: Number(lineRow.payment_packet_id),
            lineId,
            overrideType: overrideType || 'approval_threshold',
            reason: overrideReason,
            actorUserId,
            actorRole,
            fromStatus,
            toStatus: nextStatus,
            connection: conn,
          });
        }
      }
    }
    if (EVIDENCE_GATE_LINE_STATUSES.has(nextStatus)) {
      const missing = await fetchMissingRequiredEvidence({
        packetId: Number(lineRow.payment_packet_id),
        lineId: lineId,
        connection: conn,
      });
      if (missing.length) {
        if (!overrideRequested || !overrideReason || !canUsePaymentOverride(actorRole)) {
          await conn.rollback();
          return res.status(409).json({ error: 'missing_required_evidence', missing });
        }
        await recordPaymentOverride({
          packetId: Number(lineRow.payment_packet_id),
          lineId,
          overrideType: overrideType || 'evidence_gate',
          reason: overrideReason,
          actorUserId,
          actorRole,
          fromStatus,
          toStatus: nextStatus,
          connection: conn,
        });
      }
    }

    if (EI_GATE_LINE_STATUSES.has(nextStatus)) {
      const interventionId = lineRow.intervention_id || lineRow.interventionId || null;
      const interventionMap = interventionId
        ? await fetchInterventionsById({ ids: [interventionId], connection: conn })
        : new Map();
      const eiViolations = await findEiEligibilityViolations({
        lines: [lineRow],
        packetRow: { case_id: lineRow.case_id || null },
        interventionMap,
        connection: conn,
      });
      if (eiViolations.length) {
        await conn.rollback();
        return res.status(409).json({ error: 'ei_active_claim_ineligible', details: eiViolations });
      }
    }

    if (DUPLICATE_GATE_LINE_STATUSES.has(nextStatus)) {
      const duplicateScan = await collectDuplicatePaymentMatches({
        lines: [lineRow],
        packetRow: {
          id: lineRow.payment_packet_id,
          client_id: lineRow.client_id || null,
          intervention_id: lineRow.intervention_id || null,
        },
        connection: conn,
      });
      if (duplicateScan.matches.length) {
        if (duplicateScan.warnings.length) {
          await appendPacketDuplicateWarnings({
            packetId: Number(lineRow.payment_packet_id),
            warnings: duplicateScan.warnings,
            connection: conn,
          });
        }
        if (!overrideRequested || !overrideReason || !canUsePaymentOverride(actorRole)) {
          await conn.commit();
          return res.status(409).json({
            error: 'duplicate_payment_detected',
            details: duplicateScan.matches,
          });
        }
        await recordPaymentOverride({
          packetId: Number(lineRow.payment_packet_id),
          lineId,
          overrideType: overrideType || 'duplicate_payment',
          reason: overrideReason,
          actorUserId,
          actorRole,
          fromStatus,
          toStatus: nextStatus,
          connection: conn,
        });
      }
    }

    const fields = ['status = ?', 'updated_at = NOW()'];
    const params = [nextStatus];
    if (nextStatus === 'held') {
      fields.push('hold_reason = ?');
      params.push(typeof holdReason === 'string' ? holdReason.trim() : holdReason);
    }
    if (nextStatus === 'paid') {
      fields.push('paid_at = ?');
      params.push(resolvedPaidAt);
      fields.push('payment_reference = ?');
      params.push(resolvedPaymentReference);
      fields.push('payment_proof_document_id = ?');
      params.push(resolvedProofDocumentId);
    }
    const nextFollowUpStatus =
      nextStatus === 'paid'
        ? 'confirmed_by_evidence'
        : nextStatus === 'held'
          ? 'follow_up_needed'
          : nextStatus === 'submitted'
            ? 'sent_to_finance'
            : nextStatus === 'cancelled'
              ? 'cancelled_not_proceeding'
              : nextStatus === 'needs_evidence' || nextStatus === 'ready_to_send'
                ? 'not_required'
                : null;
    if (nextFollowUpStatus) {
      fields.push('follow_up_status = ?');
      params.push(nextFollowUpStatus);
      if (nextFollowUpStatus === 'not_required') {
        fields.push('follow_up_due_at = NULL');
        fields.push('follow_up_updated_at = NULL');
      } else {
        fields.push('follow_up_updated_at = NOW()');
      }
    }
    params.push(lineId);
    await conn.query(`UPDATE payment_packet_line SET ${fields.join(', ')} WHERE id = ?`, params);

    await conn.query(
      `INSERT INTO payment_status_event
        (payment_packet_id, payment_packet_line_id, from_status, to_status, actor_user_id, notes, metadata, created_at)
       VALUES (?, ?, ?, ?, ?, ?, NULL, NOW())`,
      [lineRow.payment_packet_id, lineId, fromStatus, nextStatus, actorUserId, notes]
    );

    if (nextFollowUpStatus) {
      const fromFollowUpStatus = normalizePaymentFollowUpStatus(lineRow.follow_up_status) || 'not_required';
      if (fromFollowUpStatus !== nextFollowUpStatus) {
        await createPaymentFollowUpEvent({
          packetId: Number(lineRow.payment_packet_id),
          lineId,
          fromStatus: fromFollowUpStatus,
          toStatus: nextFollowUpStatus,
          actorUserId,
          note: notes,
          metadata: { source: 'line_status_transition', lineStatus: nextStatus },
          connection: conn,
        });
        await recomputePacketFollowUpStatusFromLines({
          packetId: Number(lineRow.payment_packet_id),
          connection: conn,
        });
      }
    }

    if (nextStatus === 'paid') {
      const evidenceRules = await readPaymentEvidenceRules(conn);
      const policyRules = await readPaymentPolicyRules(conn);
      lineRow.paid_at = resolvedPaidAt;
      lineRow.payment_reference = resolvedPaymentReference;
      lineRow.payment_proof_document_id = resolvedProofDocumentId;
      const postPayTypes = extractPostPayEvidenceTypes(lineRow, evidenceRules);
      if (postPayTypes.length) {
        const currentMeta = safeJsonParse(lineRow.metadata, {}) || {};
        const schedule = ensurePostPayEvidenceSchedule({
          lineMeta: currentMeta,
          types: postPayTypes,
          referenceDate: new Date(),
          policyRules,
        });
        if (schedule.changed) {
          await updatePaymentLineMetadata({
            lineId,
            metadata: schedule.metadata,
            connection: conn,
          });
        }
      }
      const packetSnapshot = {
        case_id: lineRow.case_id,
        intervention_id: lineRow.intervention_id,
        confirmed_at: lineRow.confirmed_at || new Date(),
        metadata: lineRow.packet_metadata,
      };
      await createFinanceTransactionForLine({ lineRow, packetRow: packetSnapshot, connection: conn });

      const [[counts]] = await conn.query(
        `SELECT
           SUM(status IN ('paid','cancelled')) AS done_count,
           COUNT(*) AS total_count
         FROM payment_packet_line
         WHERE payment_packet_id = ?`,
        [lineRow.payment_packet_id]
      );
      if (Number(counts?.total_count) > 0 && Number(counts?.done_count) === Number(counts?.total_count)) {
        const [[packetRow]] = await conn.query(
          'SELECT status, confirmed_at FROM payment_packet WHERE id = ? LIMIT 1',
          [lineRow.payment_packet_id]
        );
        if (packetRow && packetRow.status !== 'confirmed' && packetRow.status !== 'cancelled') {
          await conn.query(
            'UPDATE payment_packet SET status = ?, confirmed_at = COALESCE(confirmed_at, NOW()), updated_at = NOW() WHERE id = ?',
            ['confirmed', lineRow.payment_packet_id]
          );
          await conn.query(
            `INSERT INTO payment_status_event
              (payment_packet_id, payment_packet_line_id, from_status, to_status, actor_user_id, notes, metadata, created_at)
             VALUES (?, NULL, ?, ?, ?, ?, NULL, NOW())`,
            [lineRow.payment_packet_id, packetRow.status, 'confirmed', actorUserId, 'Auto-confirmed when all lines paid']
          );
        }
      }
    }

    if (normalizePacketWorkflowStage(lineRow.packet_status) === 'draft') {
      await clearPaymentPacketValidation({
        packetId: lineRow.payment_packet_id,
        connection: conn,
      });
    }

    await conn.commit();
    await refreshFinancePotSums();
    const [[updatedLine]] = await pool.query(
      `SELECT ppl.*, bp.name AS pot_name, bp.funding_source AS pot_funding_source
         FROM payment_packet_line ppl
         LEFT JOIN budget_pot bp ON bp.id = ppl.budget_pot_id
        WHERE ppl.id = ?
        LIMIT 1`,
      [lineId]
    );
    if (!updatedLine) {
      return res.status(404).json({ error: 'payment_line_not_found' });
    }
    res.status(200).json(mapPaymentLineRow(updatedLine));
  } catch (err) {
    await conn.rollback();
    console.error('[payments] failed to update payment line status', err);
    res.status(500).json({ error: 'failed_to_update_payment_line_status' });
  } finally {
    conn.release();
  }
});

app.post('/api/finance/payment-packets/:id/documents', async (req, res) => {
  if (requirePaymentsRole(req, res)) return;
  const packetId = parsePaymentPacketId(req.params.id);
  if (!Number.isFinite(packetId)) {
    return res.status(400).json({ error: 'invalid_payment_packet_id' });
  }
  const body = req.body || {};
  const documentId = normalisePositiveInteger(body.documentId || body.document_id);
  if (!documentId) {
    return res.status(400).json({ error: 'invalid_document_id' });
  }
  const evidenceType =
    typeof body.evidenceType === 'string'
      ? body.evidenceType.trim()
      : typeof body.evidence_type === 'string'
        ? body.evidence_type.trim()
        : '';
  if (!evidenceType) {
    return res.status(400).json({ error: 'evidenceType_required' });
  }
  const lineId = parsePaymentLineId(body.lineId || body.paymentPacketLineId || body.payment_packet_line_id);
  const requiredRaw = body.required;
  const required = requiredRaw !== undefined ? normalizeBooleanLike(requiredRaw) : false;
  if (requiredRaw !== undefined && required === null) {
    return res.status(400).json({ error: 'invalid_required_flag' });
  }
  const receivedAt =
    body.receivedAt ||
    body.received_at ||
    (body.received ? new Date() : null);
  const verificationRequested =
    body.verifiedByUserId !== undefined ||
    body.verified_by_user_id !== undefined ||
    body.verifiedAt !== undefined ||
    body.verified_at !== undefined;
  const verifiedByUserId = verificationRequested
    ? await resolveFinanceRouteActorUserId(req, pool)
    : null;
  if (verificationRequested && !verifiedByUserId) {
    return res.status(400).json({ error: 'verified_by_user_required' });
  }
  const verifiedAt =
    verificationRequested
      ? (body.verifiedAt || body.verified_at || new Date())
      : null;
  const notes = typeof body.notes === 'string' ? body.notes.trim() : null;

  try {
    const [[packetRow]] = await pool.query(
      'SELECT id, case_id, client_id FROM payment_packet WHERE id = ? LIMIT 1',
      [packetId]
    );
    if (!packetRow) {
      return res.status(404).json({ error: 'payment_packet_not_found' });
    }
    let lineRow = null;
    if (lineId) {
      const [[resolvedLineRow]] = await pool.query(
        'SELECT id, payment_packet_id FROM payment_packet_line WHERE id = ? LIMIT 1',
        [lineId]
      );
      if (!resolvedLineRow) {
        return res.status(404).json({ error: 'payment_line_not_found' });
      }
      if (Number(resolvedLineRow.payment_packet_id) !== Number(packetId)) {
        return res.status(409).json({ error: 'payment_line_packet_mismatch' });
      }
      lineRow = resolvedLineRow;
    }
    const packetAccessError = await validatePaymentPacketAccess(req, packetId);
    if (packetAccessError) {
      return res.status(packetAccessError.status).json(packetAccessError.body);
    }
    const [[docRow]] = await pool.query(
      `SELECT id, checksum_sha256, client_id, case_id, application_id, action_plan_id, applicant_user_id
         FROM iset_document
        WHERE id = ? AND status = "active"
        LIMIT 1`,
      [documentId]
    );
    if (!docRow) {
      return res.status(404).json({ error: 'document_not_found' });
    }
    let documentAccessError = await validateDocumentAccess(req, docRow);
    if (documentAccessError) {
      const paymentDocumentAccessError = await validatePaymentPacketDocumentAccess(req, {
        packetId,
        documentRow: docRow,
      });
      documentAccessError = paymentDocumentAccessError || null;
    }
    if (documentAccessError) {
      return res.status(documentAccessError.status).json(documentAccessError.body);
    }
    if (!docRow.checksum_sha256 || String(docRow.checksum_sha256).length !== 64) {
      return res.status(400).json({ error: 'document_checksum_missing' });
    }
    if (!packetRow.client_id) {
      return res.status(422).json({ error: 'packet_client_required' });
    }
    if (!docRow.client_id) {
      return res.status(422).json({ error: 'document_client_required' });
    }
    if (Number(docRow.client_id) !== Number(packetRow.client_id)) {
      return res.status(409).json({ error: 'client_id_mismatch' });
    }
    const [result] = await pool.query(
      `INSERT INTO payment_packet_document
        (payment_packet_id, payment_packet_line_id, document_id, evidence_type, required, received_at, verified_by_user_id, verified_at, notes, created_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())`,
      [
        packetId,
        lineRow?.id || null,
        documentId,
        evidenceType,
        required ? 1 : 0,
        receivedAt,
        verifiedByUserId,
        verifiedAt,
        notes,
      ]
    );
    const [[evidenceRow]] = await pool.query(
      `SELECT ppd.*, d.file_name, d.label,
              u.name AS verified_by_name, u.email AS verified_by_email
         FROM payment_packet_document ppd
         LEFT JOIN iset_document d ON d.id = ppd.document_id
         LEFT JOIN user u ON u.id = ppd.verified_by_user_id
        WHERE ppd.id = ?
        LIMIT 1`,
      [result.insertId]
    );
    await clearPaymentPacketValidation({ packetId, connection: pool });
    res.status(201).json(mapPaymentDocumentRow(evidenceRow));
  } catch (err) {
    console.error('[payments] failed to attach payment document', err);
    res.status(500).json({ error: 'failed_to_attach_payment_document' });
  }
});

app.put('/api/finance/payment-documents/:id', async (req, res) => {
  if (requirePaymentsRole(req, res)) return;
  const documentLinkId = normalisePositiveInteger(req.params.id);
  if (!documentLinkId) {
    return res.status(400).json({ error: 'invalid_payment_document_id' });
  }
  const body = req.body || {};
  const fields = [];
  const params = [];
  const assign = (column, value) => {
    fields.push(`${column} = ?`);
    params.push(value);
  };
  if (body.required !== undefined) {
    const required = normalizeBooleanLike(body.required);
    if (required === null) {
      return res.status(400).json({ error: 'invalid_required_flag' });
    }
    assign('required', required ? 1 : 0);
  }
  if (body.receivedAt !== undefined || body.received_at !== undefined || body.received !== undefined) {
    const receivedAt = body.receivedAt || body.received_at || (body.received ? new Date() : null);
    assign('received_at', receivedAt);
  }
  const verifiedFlagProvided = body.verified !== undefined;
  const hasExplicitVerifier = body.verifiedByUserId !== undefined || body.verified_by_user_id !== undefined;
  const hasExplicitVerifiedAt = body.verifiedAt !== undefined || body.verified_at !== undefined;
  if (verifiedFlagProvided) {
    const verified = normalizeBooleanLike(body.verified);
    if (verified === null) {
      return res.status(400).json({ error: 'invalid_verified_flag' });
    }
    if (!hasExplicitVerifier) {
      const verifierId = verified ? await resolveFinanceRouteActorUserId(req, pool) : null;
      if (verified && !verifierId) {
        return res.status(400).json({ error: 'verified_by_user_required' });
      }
      assign('verified_by_user_id', verifierId || null);
    }
    if (!hasExplicitVerifiedAt) {
      assign('verified_at', verified ? new Date() : null);
    }
  }
  if (body.verifiedByUserId !== undefined || body.verified_by_user_id !== undefined) {
    const requestedVerifierId = normalisePositiveInteger(body.verifiedByUserId || body.verified_by_user_id);
    if (!requestedVerifierId) {
      assign('verified_by_user_id', null);
    } else {
      const verifierId = await resolveFinanceRouteActorUserId(req, pool);
      if (!verifierId) {
        return res.status(400).json({ error: 'verified_by_user_required' });
      }
      assign('verified_by_user_id', verifierId);
    }
  }
  if (body.verifiedAt !== undefined || body.verified_at !== undefined) {
    assign('verified_at', body.verifiedAt || body.verified_at || null);
  }
  if (body.notes !== undefined) {
    assign('notes', typeof body.notes === 'string' ? body.notes.trim() : null);
  }
  if (!fields.length) {
    return res.status(400).json({ error: 'no_fields_to_update' });
  }
  params.push(documentLinkId);
  try {
    const [[existingLink]] = await pool.query(
      'SELECT payment_packet_id FROM payment_packet_document WHERE id = ? LIMIT 1',
      [documentLinkId]
    );
    if (!existingLink) {
      return res.status(404).json({ error: 'payment_document_not_found' });
    }
    const accessError = await validatePaymentPacketAccess(req, existingLink.payment_packet_id);
    if (accessError) {
      return res.status(accessError.status).json(accessError.body);
    }
    await pool.query(
      `UPDATE payment_packet_document SET ${fields.join(', ')} WHERE id = ?`,
      params
    );
    const [[row]] = await pool.query(
      `SELECT ppd.*, d.file_name, d.label,
              u.name AS verified_by_name, u.email AS verified_by_email
         FROM payment_packet_document ppd
         LEFT JOIN iset_document d ON d.id = ppd.document_id
         LEFT JOIN user u ON u.id = ppd.verified_by_user_id
        WHERE ppd.id = ?
        LIMIT 1`,
      [documentLinkId]
    );
    if (!row) {
      return res.status(404).json({ error: 'payment_document_not_found' });
    }
    if (row.payment_packet_id) {
      await clearPaymentPacketValidation({ packetId: row.payment_packet_id, connection: pool });
    }
    res.status(200).json(mapPaymentDocumentRow(row));
  } catch (err) {
    console.error('[payments] failed to update payment document', err);
    res.status(500).json({ error: 'failed_to_update_payment_document' });
  }
});

