app.post('/api/render-njk', requireUnsafeAdminDebugAccess, (req, res) => {
  const { template, props } = req.body;

  if (!template || typeof template !== 'string') {
    return res.status(400).json({ error: 'Missing or invalid template' });
  }

  try {
    const renderedHtml = nunjucks.renderString(template, { props });
    res.send(renderedHtml);
  } catch (err) {
    console.error('Nunjucks render error:', err);
    res.status(500).json({ error: 'Failed to render Nunjucks template' });
  }
});

app.get('/api/admin/messages/:id/attachments', async (req, res) => {
  const messageId = normalisePositiveInteger(req.params.id);
  if (!messageId) return res.status(400).json({ error: 'invalid_message_id' });
  const caseIdFromQuery = req.query.case_id ? normalisePositiveInteger(req.query.case_id) : null;
  if (req.query.case_id && !caseIdFromQuery) {
    return res.status(400).json({ error: 'invalid_case_id' });
  }
  try {
    const ownerUserId = await resolveOrCreateUserIdFromAuth(req);
    if (!ownerUserId) return res.status(401).json({ error: 'unauthorized' });
    await ensureCaseMessageItemTable();
    const message = await fetchCaseSecureMessageRow(messageId);
    if (!message) {
      return res.status(404).json({ error: 'Message not found' });
    }
    const accessResult = await resolveCaseSecureMessageAccess(req, message, {
      requestedCaseId: caseIdFromQuery,
      ownerUserId,
      requireCaseScope: Boolean(req.query.case_id),
    });
    if (accessResult.error) {
      return res.status(accessResult.error.status).json(accessResult.error.body);
    }

    if (!accessResult.caseId) {
      const [[itemRow]] = await pool.query(
        `SELECT id
           FROM message_item
          WHERE message_id = ? AND owner_user_id = ? AND purged_at IS NULL
          LIMIT 1`,
        [messageId, ownerUserId]
      );
      if (!itemRow) {
        return res.status(403).json({ error: 'forbidden' });
      }
    }

    // Get all attachments for this message after message/case access is established.
    const [attachments] = await pool.query(
      `SELECT id, message_id, case_id, client_id, file_path, original_filename, uploaded_at, user_id, application_id
       FROM message_attachment
       WHERE message_id = ?
       ORDER BY uploaded_at ASC`,
      [messageId]
    );

    const caseId = accessResult.caseId || null;
    const resolvedApplicationId = accessResult.applicationId || message.application_id || null;
    let applicantUserId = accessResult.applicantUserId || null;
    if (!applicantUserId) {
      if (messageActorMatchesUser(message, 'sender', 'applicant_user', message.sender_user_id)) {
        applicantUserId = message.sender_user_id;
      } else if (messageActorMatchesUser(message, 'recipient', 'applicant_user', message.recipient_user_id)) {
        applicantUserId = message.recipient_user_id;
      }
    }

    const adoptedAttachments = [];

    if (caseId) {
      let resolvedClientId = null;
      try {
        resolvedClientId = await resolveClientIdForDocument({
          applicantUserId,
          caseId,
          applicationId: resolvedApplicationId,
        });
        if (!resolvedClientId) {
          return res.status(422).json({ error: 'client_id_required' });
        }
      } catch (err) {
        const errorCode = err?.code || 'client_id_resolution_failed';
        return res.status(400).json({ error: errorCode });
      }
      for (const att of attachments) {
        const attachmentCaseId = normalisePositiveInteger(att.case_id);
        if (attachmentCaseId && caseId && attachmentCaseId !== Number(caseId)) {
          return res.status(409).json({ error: 'attachment_case_scope_mismatch', attachment_id: att.id });
        }
        const attachmentApplicationId = normalisePositiveInteger(att.application_id);
        if (
          attachmentApplicationId &&
          resolvedApplicationId &&
          attachmentApplicationId !== Number(resolvedApplicationId)
        ) {
          return res.status(409).json({ error: 'attachment_application_scope_mismatch', attachment_id: att.id });
        }
        const attachmentClientId = normalisePositiveInteger(att.client_id);
        if (attachmentClientId && resolvedClientId && attachmentClientId !== Number(resolvedClientId)) {
          return res.status(409).json({ error: 'attachment_client_scope_mismatch', attachment_id: att.id });
        }
        const docApplicantUserId =
          applicantUserId ||
          att.applicant_user_id ||
          att.user_id ||
          null;
        const docUserId = att.user_id || applicantUserId || null;

        let relativeFilePath = att.file_path.replace(/\\/g, '/');
        const uploadsIndex = relativeFilePath.lastIndexOf('uploads/');
        if (uploadsIndex !== -1) {
          relativeFilePath = relativeFilePath.substring(uploadsIndex);
        }
        relativeFilePath = relativeFilePath.replace(/\\/g, '/');

        let createdAt = att.uploaded_at ? new Date(att.uploaded_at) : new Date();
        if (Number.isNaN(createdAt.getTime())) {
          createdAt = new Date();
        }

        try {
          const [insertResult] = await pool.query(
            `INSERT INTO iset_document (case_id, application_id, action_plan_id, client_id, applicant_user_id, user_id, origin_message_id, source, file_name, file_path, label, created_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, 'secure_message_attachment', ?, ?, 'Secure Message Attachment', ?)
             ON DUPLICATE KEY UPDATE applicant_user_id = VALUES(applicant_user_id), application_id = VALUES(application_id), action_plan_id = VALUES(action_plan_id), client_id = VALUES(client_id), user_id = VALUES(user_id), origin_message_id = VALUES(origin_message_id), updated_at = NOW()` ,
            [
              caseId,
              resolvedApplicationId,
              null,
              resolvedClientId,
              docApplicantUserId,
              docUserId,
              messageId,
              att.original_filename || 'Attachment',
              relativeFilePath,
              createdAt
            ]
          );
          if (insertResult && insertResult.affectedRows === 1) {
            adoptedAttachments.push({
              fileName: att.original_filename || 'Attachment',
              agentId: docUserId || null,
            });
          }
        } catch (err) {
          if (err && (err.code === 'ER_DUP_ENTRY' || err.code === '23505')) {
            continue;
          } else {
            console.error('Error inserting into iset_document:', err);
            throw err;
          }
        }
      }
    }

    if (caseId && adoptedAttachments.length) {
      const firstName = adoptedAttachments[0]?.fileName || 'Attachment';
      const message =
        adoptedAttachments.length === 1
          ? `Secure message attachment adopted: ${firstName}.`
          : `${adoptedAttachments.length} secure message attachments adopted (e.g., ${firstName}).`;
      await emitDocumentUploadedEvent({
        req,
        caseId,
        applicationId: resolvedApplicationId,
        applicantUserId,
        fileName: firstName,
        source: 'secure_message_attachment',
        message,
      });
    }

    let attachmentsWithLinks = attachments;
    try {
      const { presignGet, DRIVER } = require('../ISET-intake/s3Provider');
      if (DRIVER === 's3' && typeof presignGet === 'function') {
        attachmentsWithLinks = await Promise.all(
          attachments.map(async att => {
            const key = att?.file_path ? String(att.file_path).replace(/^\/+/, '') : '';
            if (!key) return { ...att, download_url: null };
            try {
              const presigned = await presignGet({ key });
              const url = presigned?.url || presigned?.signedUrl || null;
              return { ...att, download_url: url };
            } catch (err) {
              console.warn('[admin:messages:attachments] presign failed for message %s attachment %s: %s', messageId, att?.id, err?.message || err);
              return { ...att, download_url: null };
            }
          })
        );
      }
    } catch (err) {
      console.warn('[admin:messages:attachments] failed to prepare download links: %s', err?.message || err);
    }

    res.status(200).json(attachmentsWithLinks);
  } catch (error) {
    console.error('Error fetching message attachments:', error);
    res.status(500).json({ error: 'Failed to fetch message attachments' });
  }
});

