app.patch('/api/config/notifications/email-settings', async (req, res) => {
    if (!(await requireNotificationConfigAccess(req, res, MANAGE_NOTIFICATIONS_ROUTE))) return;
    try {
        const { senderEmail = null, senderName = null, replyTo = null } = req.body || {};
        const trimmedSenderEmail = senderEmail === null || senderEmail === undefined
          ? null
          : String(senderEmail).trim();
        const trimmedSenderName = senderName === null || senderName === undefined
          ? null
          : String(senderName).trim();
        const trimmedReplyTo = replyTo === null || replyTo === undefined
          ? null
          : String(replyTo).trim();
        if (trimmedSenderEmail && !normalizeEmailAddress(trimmedSenderEmail)) {
            return res.status(400).json({ error: 'Enter a valid sender email address.' });
        }
        if (trimmedReplyTo && !normalizeEmailAddress(trimmedReplyTo)) {
            return res.status(400).json({ error: 'Enter a valid reply-to email address.' });
        }
        const settings = await writeNotificationEmailSettings({
          senderEmail: trimmedSenderEmail || null,
          senderName: trimmedSenderName || null,
          replyTo: trimmedReplyTo || null,
        });
        res.json(settings);
    } catch (err) {
        console.error(err);
        res.status(500).json({ error: 'Failed to save notification email settings' });
    }
});

// GET all notification settings with template info
app.get('/api/notifications', async (req, res) => {
    if (!(await requireNotificationConfigAccess(req, res, MANAGE_NOTIFICATIONS_ROUTE))) return;
    try {
        const [rows] = await pool.query(`
            SELECT ns.*, nt.name as template_name, nt.language as template_language
            FROM notification_setting ns
            LEFT JOIN notification_template nt ON ns.template_id = nt.id
            ORDER BY ns.event, ns.role, ns.language
        `);
        res.json(rows);
    } catch (err) {
        console.error(err);
        res.status(500).json({ error: 'Failed to fetch notification settings' });
    }
});

// POST create or update a notification setting
app.post('/api/notifications', async (req, res) => {
    if (!(await requireNotificationConfigAccess(req, res, MANAGE_NOTIFICATIONS_ROUTE))) return;
    const { id, event, role, template_id, language, enabled, email_alert, bell_alert } = req.body;
    try {
        if (id) {
            // Update existing
            await pool.query(
                `UPDATE notification_setting SET event=?, role=?, template_id=?, language=?, enabled=?, email_alert=?, bell_alert=?, updated_at=NOW() WHERE id=?`,
                [event, role, template_id, language, enabled, email_alert ?? 0, bell_alert ?? 0, id]
            );
            res.json({ success: true, id });
        } else {
            // Insert new
            const [result] = await pool.query(
                `INSERT INTO notification_setting (event, role, template_id, language, enabled, email_alert, bell_alert) VALUES (?, ?, ?, ?, ?, ?, ?)`,
                [event, role, template_id, language, enabled, email_alert ?? 0, bell_alert ?? 0]
            );
            res.json({ success: true, id: result.insertId });
        }
    } catch (err) {
        console.error(err);
        res.status(500).json({ error: 'Failed to save notification setting' });
    }
});

// DELETE a notification setting
app.delete('/api/notifications/:id', async (req, res) => {
    if (!(await requireNotificationConfigAccess(req, res, MANAGE_NOTIFICATIONS_ROUTE))) return;
    const { id } = req.params;
    try {
        await pool.query(`DELETE FROM notification_setting WHERE id=?`, [id]);
        res.json({ success: true });
    } catch (err) {
        console.error(err);
        res.status(500).json({ error: 'Failed to delete notification setting' });
    }
});

